#dlg-risk .gde-prob-evidence .gde-prob-k {font-weight:650; color:var(--ink-1);}
#dlg-risk .gde-prob-evidence.is-thin, #dlg-risk .gde-prob-evidence.is-thin .gde-prob-k {color:var(--ink-warn);}
#dlg-risk .gde-stamp-live, #dlg-risk .gde-pending {color:var(--ink-2);}
#dlg-risk .gde-disc {margin-top:4px;}
#dlg-risk .gde-disc > summary {cursor:pointer; min-height:40px; align-content:center; font-size:var(--fs-label); color:var(--ink-2);}
#dlg-risk .gde-disc > summary:focus-visible {outline:2px solid var(--link); outline-offset:2px; border-radius:var(--r-ctl);}
#dlg-risk .gde-disc-body {padding-top:8px; border-top:1px solid var(--line);}
#dlg-risk .gde-tblwrap {max-width:100%; overflow-x:auto;}
#dlg-risk .gde-tbl {width:100%; border-collapse:collapse; font-size:var(--fs-label);}
#dlg-risk .gde-tbl th, #dlg-risk .gde-tbl td {padding:8px; text-align:left; border-bottom:1px solid var(--line); vertical-align:top; overflow-wrap:break-word;}
#dlg-risk .gde-tbl th {color:var(--ink-2); font-weight:600;}
#dlg-risk .gde-tbl td {color:var(--ink-1);}
/* Review (FU2): the page-wide body.page-macro td rule puts the numeric face on every
   non-first cell; prose and labels in this table read in the UI face, and the As-of
   date never splits across lines when the read column takes the width. */
#dlg-risk .gde-tbl td[data-label-en="As of"] {white-space:nowrap;}
#dlg-risk .gde-tbl td .l-en, #dlg-risk .gde-tbl td .l-zh {font-family:var(--font-ui); letter-spacing:normal;}
/* D2 (FU2 recapture): below 481 px four columns cannot hold "Leadership cohort" or
   the uppercase headers without letter-level breaks, so the table reduces to one
   stacked card per source: the header row leaves the visual flow (still read by
   assistive tech) and every cell carries its own column label from data-label-*. */
@media(max-width:480px) {
  #dlg-risk .gde-tbl thead {position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap;}
  #dlg-risk .gde-tbl, #dlg-risk .gde-tbl tbody {display:block;}
  #dlg-risk .gde-tbl tr {display:block; padding:6px 0; border-bottom:1px solid var(--line);}
  #dlg-risk .gde-tbl td {display:grid; grid-template-columns:minmax(0, 7.5em) minmax(0, 1fr); gap:0 12px; padding:3px 0; border-bottom:0;}
  #dlg-risk .gde-tbl td::before {color:var(--ink-2); font-weight:600; font-size:var(--fs-label); font-family:var(--font-ui); letter-spacing:normal;}
  #dlg-risk .gde-tbl td > * {grid-column:2;}
  /* The label is visual only (empty alt text): assistive tech still has the header row.
     The plain declaration first is the fallback for engines without the alt-text syntax. */
  html:not([data-lang="zh"]) #dlg-risk .gde-tbl td::before {content:attr(data-label-en); content:attr(data-label-en) / "";}
  html[data-lang="zh"] #dlg-risk .gde-tbl td::before {content:attr(data-label-zh); content:attr(data-label-zh) / "";}
}
#dlg-risk .gde-warn {color:var(--ink-warn);}
#dlg-risk .gde-req {color:var(--ink-3);}
#dlg-risk .gde-disc-h {font-size:var(--fs-sm); font-weight:600; margin:12px 0 4px;}
#dlg-risk .gde-conflicts {padding-left:16px; margin:0; font-size:var(--fs-label); line-height:1.5;}
#dlg-risk .gde-receipt, #dlg-risk .gde-policy {font-size:var(--fs-label); line-height:1.5; color:var(--ink-3); overflow-wrap:anywhere; margin:8px 0 0;}
@media(max-width:640px) {
  #dlg-risk .riskdlg-context {padding:12px;}
  #dlg-risk .gde-reads {gap:8px 16px;}
}

/* The legacy band must not impose its rails or large spacing inside Risk Radar. */
#dlg-risk .gde-head {border:0; padding:0; margin:0;}
#dlg-risk .gde-read {border:0; padding:0; margin:0;}
#dlg-risk .gde-disc > summary {display:flex; gap:6px; align-items:center; padding:0;}
#dlg-risk .gde-disc > summary::before {content:"+";}
#dlg-risk .gde-disc[open] > summary::before {content:"−";}

/* The existing button carries a separate stress caveat, never a changed radar score. */
#mx5BtnRisk {max-width:100%; flex-wrap:wrap;}
#mx5BtnRisk .gde-button-context {border-left:1px solid var(--line); padding-left:6px; white-space:normal;}
.gde-button-context[data-gde-stage="FRAGILE"] {color:var(--ink-warn);}
.gde-button-context[data-gde-stage="TRANSMITTING"], .gde-button-context[data-gde-stage="BREAKDOWN"] {color:var(--ink-act);}
#mx5BtnRisk .gde-button-context[hidden], #dlg-risk .gde-live-reading[hidden], #dlg-risk .gde-input-caveat[hidden] {display:none;}
#dlg-risk .gde-causes {margin:8px 0 0; font-size:var(--fs-sm); line-height:1.45; color:var(--ink-1);}
#dlg-risk .gde-input-caveat {margin:4px 0 0; font-size:var(--fs-label); color:var(--ink-warn);}
#dlg-risk .gde-live-reading {display:flex; gap:4px 10px; flex-wrap:wrap; margin-top:8px; font-size:var(--fs-sm); line-height:1.4;}
#dlg-risk .gde-live-reading strong {font-weight:650; color:var(--ink-1);}
#dlg-risk .gde-live-reading > span {color:var(--ink-2);}

#dlg-risk .gde-live-source-rows {white-space:pre-line; font-size:var(--fs-label); line-height:1.6; overflow-wrap:anywhere;}
#dlg-risk #gde-live-sources[hidden] {display:none;}

/* ── EW-P4.T1 descriptive early-warning observation (consumer-only). Chairman
   2026-10-18 rule: even one-piece borders on ALL four sides, neutral or
   surface-warn-subtle backgrounds from tokens, no edge stripe / accent rail /
   inset shadow bar; state carried by text + ink color, never color alone. ── */
#dlg-risk .gde-scope {font-size:var(--fs-label); color:var(--ink-3);}
#dlg-risk .gde-ew {--gde-ew-surface:var(--esurf-neutral-soft); margin-top:8px; padding:10px 12px; border:1px solid var(--line); border-radius:var(--r-card); background:var(--gde-ew-surface); overflow-wrap:anywhere;}
/* L3: light is its own art direction. The card is a raised white panel with the card
   shadow on the deeper canvas, never a recessed --panel2 well. Only the surface token
   moves, so the warning-state backgrounds below still win. */
html[data-theme="light"] #dlg-risk .gde-ew {--gde-ew-surface:var(--panel); box-shadow:var(--card-shadow);}
#dlg-risk .gde-ew[data-ew-state="stale"],
#dlg-risk .gde-ew[data-ew-state="unavailable"],
#dlg-risk .gde-ew[data-ew-state="unreadable"],
#dlg-risk .gde-ew[data-ew-state="withdrawn"],
#dlg-risk .gde-ew[data-ew-state="partial"],
#dlg-risk .gde-ew[data-ew-state="conflicting"] {background:var(--surface-warn-subtle,var(--panel2,var(--card)));}
#dlg-risk .gde-ew-head {margin:0; display:flex; gap:8px; align-items:baseline; flex-wrap:wrap; font-size:var(--fs-sm); color:var(--ink-1);}
#dlg-risk .gde-ew-scope {font-weight:600;}
#dlg-risk .gde-ew-state {font-weight:600; color:var(--text);}
#dlg-risk .gde-ew[data-ew-state="stale"] .gde-ew-state,
#dlg-risk .gde-ew[data-ew-state="unavailable"] .gde-ew-state,
#dlg-risk .gde-ew[data-ew-state="unreadable"] .gde-ew-state,
#dlg-risk .gde-ew[data-ew-state="withdrawn"] .gde-ew-state,
#dlg-risk .gde-ew[data-ew-state="partial"] .gde-ew-state,
#dlg-risk .gde-ew[data-ew-state="conflicting"] .gde-ew-state {color:var(--ink-warn);}
#dlg-risk .gde-ew[data-ew-state="corrected"] .gde-ew-state {color:var(--ink-info);}
#dlg-risk .gde-ew-what {margin:6px 0 0; font-size:var(--fs-sm); line-height:1.45; color:var(--ink-1);}
#dlg-risk .gde-ew-note {margin:4px 0 0; font-size:var(--fs-label); color:var(--ink-2);}
#dlg-risk .gde-ew-when {margin:4px 0 0; font-size:var(--fs-label); color:var(--ink-3);}
#dlg-risk .gde-ew-built {color:var(--muted); font-size:var(--fs-label);}
#dlg-risk .gde-ew-means {margin:4px 0 0; font-size:var(--fs-label); color:var(--ink-3);}
#dlg-risk .gde-ew-next {display:inline-block; margin-top:6px; font-size:var(--fs-label); color:var(--link);}
#dlg-risk .gde-ew-next:focus-visible, #dlg-risk .gde-ew-study > summary:focus-visible {outline:2px solid var(--link); outline-offset:2px; border-radius:var(--r-ctl);}
#dlg-risk .gde-ew-brief-h {margin-top:4px;}
#dlg-risk .gde-ew-tablewrap {margin-top:8px; max-width:100%;}
#dlg-risk .gde-ew-legs {width:100%; border-collapse:collapse; font-size:var(--fs-label);}
#dlg-risk .gde-ew-legs caption {caption-side:top; text-align:left; padding:0 8px 4px; color:var(--ink-3); font-size:var(--fs-label);}
#dlg-risk .gde-ew-legs th, #dlg-risk .gde-ew-legs td {padding:6px 8px; text-align:left; border-bottom:1px solid var(--line); vertical-align:top; overflow-wrap:anywhere;}
/* D6: row headers read as sentence-case UI labels on both hosts; the page-wide
   body.page-macro th rule would otherwise make them uppercase micro type. */
#dlg-risk .gde-ew-legs th {color:var(--ink-2); font-weight:600; font-family:var(--font-ui); font-size:var(--fs-label); text-transform:none; letter-spacing:normal;}
#dlg-risk .gde-ew-legs td {color:var(--ink-1); font-variant-numeric:tabular-nums;}
/* Review (FU2): sector names read in the UI face on both hosts; only .tnum cells are figures. */
#dlg-risk .gde-ew-legs td:not(.tnum) {font-family:var(--font-ui); letter-spacing:normal; font-variant-numeric:normal;}
#dlg-risk .gde-ew-contextline {margin:6px 0 0; font-size:var(--fs-sm); line-height:1.45;}
#dlg-risk .gde-ew-horizons {display:flex; gap:10px; flex-wrap:wrap; margin-top:8px;}
#dlg-risk .gde-ew-hz {flex:1 1 150px; min-width:0; border:1px solid var(--line); border-radius:var(--r-ctl); padding:8px 10px; font-size:var(--fs-label); color:var(--ink-2); display:flex; gap:6px 10px; align-items:baseline; flex-wrap:wrap;}
#dlg-risk .gde-ew-hz-k {font-weight:600; color:var(--ink-1);}
#dlg-risk .gde-ew-hz-v {font-size:var(--fs-md); font-weight:650; color:var(--ink-1);}
#dlg-risk .gde-ew-hz-q {color:var(--ink-3);}
#dlg-risk .gde-ew-against {padding-left:16px; margin:0; font-size:var(--fs-label); line-height:1.5; color:var(--ink-2);}
#dlg-risk .gde-ew-study {margin-top:10px; font-size:var(--fs-label);}
#dlg-risk .gde-ew-study > summary {cursor:pointer; min-height:32px; align-content:center; color:var(--ink-2);}
#dlg-risk .gde-ew-dl {margin:4px 0 0;}
#dlg-risk .gde-ew-dl > div {display:flex; gap:4px 12px; flex-wrap:wrap; padding:5px 0; border-bottom:1px solid var(--line);}
#dlg-risk .gde-ew-dl dt {flex:0 0 auto; color:var(--ink-3); font-weight:600;}
#dlg-risk .gde-ew-dl dd {margin:0; min-width:0; flex:1 1 120px; color:var(--ink-1); overflow-wrap:anywhere;}
#dlg-risk .gde-ew-id {user-select:all; font-family:var(--font-mono);}
@media(max-width:640px) {
  #dlg-risk .gde-ew {padding:10px;}
  #dlg-risk .gde-ew-horizons {flex-direction:column;}
  #dlg-risk .gde-ew-hz {flex-basis:100%;}
  #dlg-risk .gde-ew-legs th, #dlg-risk .gde-ew-legs td {display:block; width:100%; box-sizing:border-box; border-bottom:none; padding:2px 8px;}
  #dlg-risk .gde-ew-legs tr {display:block; border-bottom:1px solid var(--line); padding:4px 0;}
  #dlg-risk .gde-ew-legs {border-bottom:1px solid var(--line);}
}

rules.old:
/* ============================================================================
   RISK RADAR CARD (.rrx) — the one shared, redesigned alert used on the US Macro
   + US-Stocks pages AND the China / HK / Canada Market-State boards (the macros
   live in _risk_radar_card.html.j2). GLOBAL theme vars only + an inline --rc state
   accent, so it renders the same in the page-macro, page-stocks and china/hk/canada
   scopes. The escalating odds ramp replaces the old cramped "5d.. 10d.. 21d.." run.
   Included by dashboard.html.j2 (both modes) + _market_state.css.j2 (CN/HK/CA). ==== */
.rrx { --rc: var(--warn);
       display: grid; gap: 12px; margin: 12px 0 2px; padding: 15px 18px; border-radius: 12px;
       background: var(--panel);
       border: 1px solid var(--line);
       border-left: 4px solid var(--rc); font-size: 12.5px; line-height: 1.4;
       box-shadow: 0 1px 2px rgba(0,0,0,.06), 0 16px 32px -24px rgba(0,0,0,.4); }
body.page-macro .ms-front > .rrx { margin: 0 0 14px; }
/* grouping wrappers: inert everywhere by default (the card keeps its single-column
   stack on the China/HK/Canada/stocks placements); the macro front-page overrides
   these to display:flex to build the 2-column banner. */
.rrx > .rrx-main, .rrx > .rrx-side { display: contents; min-width: 0; }
/* Perf: loud pulse = pseudo animating ONLY opacity (compositor-run); animating
   box-shadow on the card repainted it every frame (2026-07-21 mobile audit).
   mmGlowBreathe keyframes ship in theme.css (loaded on every placement). */
.rrx.rrx-loud { background: color-mix(in srgb, var(--rc) 5%, var(--panel));
       position: relative;
       box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--rc) 20%, transparent), 0 14px 34px -18px color-mix(in srgb, var(--rc) 70%, transparent); }
.rrx.rrx-loud::before { content: ""; position: absolute; inset: 0; border-radius: inherit;
       pointer-events: none;
       box-shadow: 0 0 0 5px color-mix(in srgb, var(--rc) 6%, transparent);
       opacity: 0; animation: mmGlowBreathe 2.4s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .rrx.rrx-loud::before { animation: none; opacity: 0; }
       .rrx.rrx-loud { box-shadow: 0 0 0 1px color-mix(in srgb, var(--rc) 30%, transparent); } }
/* header */
.rrx .rrx-hd { display: flex; align-items: flex-start; gap: 10px; }
.rrx .rrx-ic { font-size: 18px; line-height: 1.1; flex: none; }
.rrx .rrx-id { min-width: 0; flex: 1; }
.rrx .rrx-ttl { display: flex; align-items: center; flex-wrap: wrap; gap: 7px;
       font-weight: 700; font-size: 13px; color: var(--text); }
.rrx .rrx-badge { font-weight: 800; letter-spacing: .03em; color: var(--rc); font-size: 11.5px;
       font-variant-numeric: tabular-nums; padding: 1px 7px; border-radius: 5px;
       background: color-mix(in srgb, var(--rc) 16%, transparent);
       border: 1px solid color-mix(in srgb, var(--rc) 38%, transparent); }
.rrx .rrx-dom { color: var(--muted); font-size: 11.5px; margin-top: 2px; }
.rrx .rrx-authority { font-size: 10.5px; line-height: 1.35; margin-top: 3px; font-weight: 600; }
.rrx .rrx-authority.is-advisory { color: var(--muted); }
.rrx .rrx-authority.is-binding { color: var(--rc); }
.rrx .rrx-amp { color: var(--rc); font-weight: 600; font-size: 11px; margin-top: 3px; }
.rrx .rrx-gross { flex: none; text-align: center; padding: 3px 11px; border-radius: 9px;
       background: color-mix(in srgb, var(--rc) 12%, transparent);
       border: 1px solid color-mix(in srgb, var(--rc) 32%, transparent); }
.rrx .rrx-gross .gv { display: block; font-weight: 800; font-size: 15px; color: var(--rc);
       font-variant-numeric: tabular-nums; line-height: 1.1; }
.rrx .rrx-gross .gn { display: block; font-size: 9px; text-transform: uppercase; letter-spacing: .07em;
       color: var(--muted); }
/* odds hero — flat on the card (the amber wash now lives on .rrx itself, not a nested box) */
.rrx .rrx-odds { display: flex; gap: 16px; align-items: stretch; flex-wrap: wrap; }
.rrx .rrx-odds-l { flex: 1 1 150px; display: flex; flex-direction: column; justify-content: center; }
.rrx .rrx-cap { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .09em;
       color: var(--muted); }
.rrx .rrx-cap-sub { font-weight: 600; letter-spacing: .02em; opacity: .8; }
.rrx .rrx-big { font-weight: 800; font-size: 40px; line-height: .95; color: var(--rc); margin: 4px 0 2px;
       font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
.rrx .rrx-big .pct { font-size: 22px; margin-left: 1px; }
.rrx .rrx-big .rrx-hz { font-size: 11px; font-weight: 600; color: var(--muted); margin-left: 7px;
       letter-spacing: 0; }
.rrx .rrx-vsn { font-size: 11.5px; color: var(--muted); }
.rrx .rrx-vsn b { color: var(--text); font-variant-numeric: tabular-nums; }
/* escalating ramp */
.rrx .rrx-ramp { flex: 1 1 240px; min-width: 0; max-width: 430px; display: flex; align-items: flex-end;
       justify-content: space-between; gap: 12px; position: relative; padding-top: 18px; }
.rrx .rrx-col { flex: 1 1 0; min-width: 0; max-width: 76px; display: flex; flex-direction: column;
       align-items: center; gap: 5px; }
.rrx .rrx-v { font-size: 12.5px; font-weight: 800; color: var(--text); font-variant-numeric: tabular-nums; }
.rrx .rrx-col.is-hd .rrx-v { color: var(--rc); }
.rrx .rrx-tk { width: 100%; max-width: 54px; height: 64px; position: relative;
       display: flex; align-items: flex-end; justify-content: center; border-bottom: 1px solid var(--line); }
.rrx .rrx-norm { position: absolute; left: 0; right: 0; bottom: 0; border-radius: 2px 2px 0 0;
       background: repeating-linear-gradient(-45deg, color-mix(in srgb, var(--muted) 32%, transparent) 0 4px, transparent 4px 8px);
       border-top: 1px dashed color-mix(in srgb, var(--muted) 60%, transparent); }
.rrx .rrx-fill { width: 100%; border-radius: 3px 3px 0 0; position: relative; z-index: 1; min-height: 6px;
       background: linear-gradient(180deg, var(--rc), color-mix(in srgb, var(--rc) 50%, transparent)); }
.rrx .rrx-hl { font-size: 10.5px; font-weight: 600; color: var(--muted); }
.rrx .rrx-col.is-hd .rrx-hl { color: var(--text); }
.rrx .rrx-leg { position: absolute; top: 0; right: 2px; display: flex; align-items: center; gap: 4px;
       font-size: 9.5px; color: var(--muted); }
.rrx .rrx-leg-n { width: 13px; border-top: 1px dashed color-mix(in srgb, var(--muted) 60%, transparent); }
/* threat meters */
.rrx .rrx-threats { display: flex; flex-wrap: wrap; gap: 6px; }
.rrx .rrx-th { --sb: var(--muted); display: inline-flex; align-items: center; gap: 6px;
       padding: 3px 9px; border-radius: 7px; font-size: 11px;
       background: var(--panel); border: 1px solid var(--line); }
.rrx .rrx-th.dom { background: color-mix(in srgb, var(--sb) 10%, var(--panel));
       border-color: color-mix(in srgb, var(--sb) 50%, var(--line)); }
.rrx .rrx-th.dim { opacity: .58; }
.rrx .rrx-th-n { color: var(--text); font-weight: 600; }
.rrx .rrx-th.dom .rrx-th-n { color: var(--sb); }
.rrx .rrx-meter { display: inline-flex; gap: 1.5px; }
.rrx .rrx-meter i { width: 3px; height: 11px; border-radius: 1px;
       background: color-mix(in srgb, var(--muted) 28%, transparent); }
.rrx .rrx-meter i.on { background: var(--sb); }
.rrx .rrx-th-s { color: var(--text); font-weight: 800; font-size: 11.5px; font-variant-numeric: tabular-nums; }
.rrx .rrx-tag { font-size: 8.5px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted);
       border: 1px solid var(--line); border-radius: 4px; padding: 0 4px; }
.rrx .rrx-ev { font-size: 11px; color: var(--muted); }
.rrx .rrx-ev-k { font-weight: 700; color: var(--text); margin-right: 6px; }
.rrx .rrx-ev-p { color: var(--text); font-weight: 600; font-variant-numeric: tabular-nums; }
/* action */
.rrx .rrx-do { font-size: 12px; color: var(--text); padding-top: 9px;
       border-top: 1px solid color-mix(in srgb, var(--rc) 20%, var(--line)); }
.rrx .rrx-do-k { font-weight: 800; color: var(--rc); text-transform: uppercase; letter-spacing: .06em;
       font-size: 10.5px; margin-right: 8px; }
/* election-cycle context chip (US radar only; engine/election_cycle.py) */
/* compressed to <=2 dense lines so the cycle context never balloons the card */
.rrx .rrx-cyc { font-size: 10.5px; color: var(--muted); padding-top: 7px; margin-top: 2px; line-height: 1.4;
       border-top: 1px solid color-mix(in srgb, var(--rc) 16%, var(--line));
       display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 8px; row-gap: 1px; }
.rrx .rrx-cyc-k { font-weight: 700; color: var(--text); }
.rrx .rrx-cyc-tag { color: var(--rc); font-weight: 700; font-size: 9.5px; }
/* RC-R11 washout counter-read chip — a cyan-tinted variant of the modulator row. */
.rrx .rrx-cyc.rrx-washout { border-top-color: color-mix(in srgb, var(--cyan, #38bdf8) 22%, var(--line)); }
.rrx .rrx-cyc.rrx-washout .rrx-cyc-k { color: var(--cyan, #38bdf8); }
.rrx .rrx-cyc-sub { color: var(--muted); font-size: 10px; margin: 0; }
.rrx .rrx-cyc-sec { color: var(--text); font-size: 10px; margin: 0; flex-basis: 100%;
       font-variant-numeric: tabular-nums; }
/* self-audit line (international radars only) */
.rrx .rrx-audit { font-size: 10.5px; color: var(--muted); }
.rrx .rrx-audit-k { font-weight: 700; color: var(--text); margin-right: 6px; }
