<link rel="stylesheet" href="product-nav-icons.css">
<style>
/* ambient aurora — fixed accents blended into transparent, pinned behind all
   content (paints over the opaque body bg, under the page). Light default gets
   the airier tint; dark gets the richer wash. */
html body::before{content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:
