  background:
   radial-gradient(680px 440px at 10% -8%,color-mix(in srgb,#416aec 20%,transparent),transparent 68%),
   radial-gradient(620px 440px at 94% 2%,color-mix(in srgb,#8b5cf6 16%,transparent),transparent 70%),
   radial-gradient(760px 520px at 50% 112%,color-mix(in srgb,#0ea5e9 14%,transparent),transparent 70%);}

/* buttons — smooth transition + a subtle accent glow / lift on hover (additive;
   vtm/tm only exist on the Bitcoin Vector page, harmless elsewhere) */
.vtm-btn,.tm-btn,.navbtn,.ai-brief-link{transition:transform .16s ease,border-color .16s ease,
  color .16s ease,background .16s ease,box-shadow .18s ease;}
.vtm-btn:hover,.tm-btn:hover,.navbtn:hover{border-color:color-mix(in srgb,var(--blue) 58%,var(--grid));
  box-shadow:0 4px 13px -5px color-mix(in srgb,var(--blue) 40%,transparent);}
.ai-brief-link:hover{transform:translateY(-1px);
  box-shadow:0 5px 14px -5px color-mix(in srgb,var(--blue) 42%,transparent);}

/* top-bar link light-up — accent-tinted hover/active. Mix base uses the FULL
   surface fallback chain --card → --panel2 → --panel (+ hardcoded final), same as
   the glass fill below: the vector family has two palette conventions (most pages
   define --card; commodities uses --panel2/--panel and no --card), so a bare
   --card OR bare --panel2 base is null on some pages → invalid color-mix → dead
   hover. The dropdown-item hover moved to the aurora-glass block below. */
a.nav-link:hover,a.nav-link.active{background:color-mix(in srgb,var(--blue) 12%,var(--card,var(--panel2,var(--panel,#eef1f6))));}
html[data-theme="dark"] a.nav-link:hover,html[data-theme="dark"] a.nav-link.active{
  background:color-mix(in srgb,var(--blue) 20%,var(--card,var(--panel2,var(--panel,#222732))));}

/* 3rd-tier fly-out (Other Assets ▸ Bitcoin Vector / Commodities) — layout only,
   palette inherited from the host page's inline nav-dd-menu. Loaded after the
   page <style>, so these position overrides win. */
.nav-dd-menu .nav-sub{display:block;position:relative;}
.nav-dd-menu .nav-sub>a.nav-sub-trig{display:flex;align-items:flex-start;}
.nav-dd-menu .nav-sub>a.nav-sub-trig .caret-r{margin-left:auto;padding-left:12px;font-size:10px;
  opacity:.55;flex:none;align-self:center;transition:transform .2s,color .2s,opacity .2s,filter .2s;}
/* breathe only while the dropdown is open + hover-capable + motion allowed — never
   on hidden carets (perf) or the mobile accordion (theme.js rotate clobber). */
@media (hover:hover) and (prefers-reduced-motion:no-preference){
