  box-shadow:0 24px 64px -22px rgba(3,7,18,.74),0 12px 28px -14px rgba(3,7,18,.55),inset 0 1px 0 color-mix(in srgb,#fff 10%,transparent)}
/* 3rd-tier fly-out: its parent .nav-dd-menu is already a backdrop root, so the
