.site-nav .nav-dd-menu .nav-sub>.nav-dd-menu,.topbar .nav-dd-menu .nav-sub>.nav-dd-menu{
  background:color-mix(in srgb,var(--card,var(--panel2,var(--panel,#181b21))) 97%,transparent)}
.site-nav .nav-dd:hover>.nav-dd-menu,.site-nav .nav-dd:focus-within>.nav-dd-menu{opacity:1;visibility:visible;transform:translateY(0)}
.site-nav .nav-dd-menu a{display:block;padding:9px 12px;border-radius:9px;font-size:13.5px;font-weight:600;color:var(--text);text-decoration:none;white-space:nowrap;transition:background .15s,color .15s}
.site-nav .nav-dd-menu a .d{display:block;font-size:11.5px;font-weight:400;color:var(--muted,var(--mut,#8b93a1));margin-top:2px}
/* aurora-glass hover — mirrors theme.css on compact legacy dropdowns:
   a soft blue→violet wash (::before) + luminous left bar (::after) + 2px glide.
   The Research mega menu owns a newer quiet hover language in
   navigation-refresh.css, so this late-loaded partial must never repaint it.
   Accent --blue→--link→#5b9dff resolves on every legacy family palette. */
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item){position:relative;isolation:isolate;transition:transform .24s cubic-bezier(.2,.7,.3,1),color .18s}
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item)::before{content:"";position:absolute;inset:0;border-radius:inherit;z-index:-1;opacity:0;transition:opacity .3s ease;
  background:radial-gradient(130% 150% at 0% 50%,color-mix(in srgb,var(--blue,var(--link,#5b9dff)) 18%,transparent),transparent 62%),linear-gradient(90deg,color-mix(in srgb,var(--blue,var(--link,#5b9dff)) 10%,transparent),color-mix(in srgb,#9b8cff 7%,transparent) 70%,transparent);
  box-shadow:inset 0 1px 0 color-mix(in srgb,#fff 8%,transparent)}
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item)::after{content:"";position:absolute;left:3px;top:50%;transform:translateY(-50%);height:0;width:2.5px;border-radius:3px;z-index:-1;opacity:0;
  background:linear-gradient(color-mix(in srgb,var(--blue,var(--link,#5b9dff)) 90%,#fff),#9b8cff);
  box-shadow:0 0 8px color-mix(in srgb,var(--blue,var(--link,#5b9dff)) 70%,transparent);transition:height .3s cubic-bezier(.2,.7,.3,1),opacity .3s ease}
/* background:transparent neutralises each page's hardcoded inline flat hover
   (#222732 / #eef1f6) so only the aurora wash paints (my 0,4,1 beats page 0,2,0). */
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item):hover{transform:translateX(2px);background:transparent}
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item).active{background:transparent}
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item):hover::before,.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item).active::before{opacity:1}
.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item):hover::after,.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item).active::after{height:56%;opacity:1}
@keyframes navCaretBreath{0%,100%{opacity:.45;transform:translateX(0)}50%{opacity:.9;transform:translateX(2px)}}
@media(prefers-reduced-motion:reduce){.nav-dd-menu .nav-sub>a.nav-sub-trig .caret-r{animation:none}.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item):hover{transform:none}.nav-dd-menu:not(.mega-menu) a:not(.nm-feat):not(.nav-mega-item)::after{transition:none}}
.site-nav .nav-ctrls{grid-column:2;grid-row:2;justify-self:end;align-self:center;display:flex;align-items:center;gap:10px}
.site-nav .nav-ctrls .ai-brief-link{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;flex:none;padding:5px 12px;border-radius:999px;background:var(--card);border:1px solid var(--grid);color:var(--text);font-size:12.5px;font-weight:600;line-height:1;cursor:pointer}
.site-nav .nav-ctrls .ai-brief-link.active{background:var(--blue);border-color:var(--blue);color:#fff}
.site-nav .theme-switch{width:56px;height:27px;border-radius:999px;background:var(--card);border:1px solid var(--grid);position:relative;cursor:pointer;padding:0;flex:none}
.site-nav .theme-switch .ic{position:absolute;top:50%;transform:translateY(-50%);font-size:10.5px;opacity:.5;line-height:1}
.site-nav .theme-switch .ic.sun{right:8px}
.site-nav .theme-switch .ic.moon{left:8px}
.site-nav .theme-switch .knob{position:absolute;top:2px;left:2px;width:22px;height:22px;border-radius:50%;background:#e8c15a;display:flex;align-items:center;justify-content:center;font-size:11px;box-shadow:0 2px 5px rgba(0,0,0,.3);transition:transform .34s cubic-bezier(.34,1.45,.5,1),background .3s}
.site-nav .theme-switch .knob::before{content:"🌙"}
html[data-theme="light"] .site-nav .theme-switch .knob{transform:translateX(29px);background:#285fff}
html[data-theme="light"] .site-nav .theme-switch .knob::before{content:"☀️"}
.site-nav .lang-toggle{display:inline-flex;position:relative;background:var(--card);border:1px solid var(--grid);border-radius:999px;padding:3px;flex:none;cursor:pointer}
.site-nav .lang-toggle .pill{position:absolute;top:3px;left:3px;width:calc(50% - 3px);height:calc(100% - 6px);border-radius:999px;background:var(--blue);transition:transform .34s cubic-bezier(.34,1.4,.5,1)}
html[data-lang="zh"] .site-nav .lang-toggle .pill{transform:translateX(100%)}
.site-nav .lang-toggle .opt{position:relative;z-index:1;min-width:28px;text-align:center;padding:3px 9px;font-size:11.5px;font-weight:600;color:var(--muted);transition:color .25s;user-select:none}
html:not([data-lang="zh"]) .site-nav .lang-toggle .en-opt{color:#fff}
html[data-lang="zh"] .site-nav .lang-toggle .zh-opt{color:#fff}

/* One-row section menu (re-fix on current main): the 8-dropdown section menu
   (~1418px) overflowed the 1180 content rail and wrapped onto a second row.
   Widen the nav to the same ~1500 rail the macro family uses, on >=701px, for
   whichever nav variant a family page renders today: the body-level .site-nav
   (migrated vector pages, capped by an inline max-width:1180) and the legacy
   in-wrap .topbar (strategy / misc pages, a sticky bar inside the content rail).
   The page body keeps its 1180 rail and the <=700px hamburger (theme.js) is
   untouched. */
@media (min-width:701px){
  nav.site-nav{max-width:1500px !important;}
  .topbar{margin-left:calc(50% - 50vw);margin-right:calc(50% - 50vw);
    padding-left:max(40px,calc((100vw - 1500px)/2));
    padding-right:max(40px,calc((100vw - 1500px)/2));}
}

/* toggles — subtle hover feedback (their slide animations are untouched) */
.theme-switch,.lang-toggle{transition:border-color .18s ease,box-shadow .18s ease;}
.theme-switch:hover,.lang-toggle:hover{border-color:color-mix(in srgb,var(--blue) 55%,var(--grid));
  box-shadow:0 3px 11px -5px color-mix(in srgb,var(--blue) 40%,transparent);}

/* clickable card / tile containers — the landing's hover light-up, but only when
   the card is actually a link (display cards are untouched) */
a.card,a.actitem,a.idx-alloc{transition:transform .2s cubic-bezier(.2,.7,.3,1),
  border-color .2s ease,box-shadow .2s ease;}
a.card:hover,a.actitem:hover,a.idx-alloc:hover{transform:translateY(-2px);
  border-color:color-mix(in srgb,var(--blue) 45%,var(--grid));
  box-shadow:0 14px 30px -16px color-mix(in srgb,var(--blue) 40%,transparent);}

/* AI Daily Brief card — these self-contained pages don't link theme.css, where
   the .aibrief-card / .abc-* layout lives, so the 🧠 card collapsed to a raw
   emoji + text run with no flex. Port the layout here (mirrors theme.css) so it
   lays out; the base .card surface + the a.card:hover above still apply. */
.aibrief-card{display:flex;align-items:center;gap:14px;text-decoration:none}
.aibrief-card .abc-ic{font-size:30px;line-height:1;flex:none}
.aibrief-card .abc-mid{flex:1;min-width:0}
.aibrief-card .abc-tit{display:block;font-size:16px;font-weight:700;color:var(--ink)}
.aibrief-card .abc-sub{display:block;margin-top:3px;color:var(--muted);font-size:13px;line-height:1.5}
.aibrief-card .abc-go{font-size:22px;font-weight:700;color:var(--ink-link, var(--blue));flex:none}

/* "?" help affordance — a circled question-mark that reveals a plain-language
   note on hover/focus (native title, bilingual "EN · ZH" like the .tip pattern).
   Used to lift cryptic micro-copy off the cards without losing the explanation. */
.qm{display:inline-flex;align-items:center;justify-content:center;width:15px;height:15px;
  border-radius:50%;border:1px solid var(--faint);color:var(--muted);font-size:10px;
  font-weight:700;line-height:1;cursor:help;vertical-align:middle;margin-left:5px;
  user-select:none;transition:border-color .15s ease,color .15s ease}
.qm:hover,.qm:focus{border-color:var(--blue);color:var(--ink-link, var(--blue));outline:none}

/* accessible keyboard focus ring */
:where(.vtm-btn,.tm-btn,.navbtn,.ai-brief-link,a.nav-link,.nav-dd-menu a,.theme-switch,
  .lang-toggle,a.card,a.actitem,a.idx-alloc):focus-visible{
  outline:2px solid color-mix(in srgb,var(--blue) 70%,transparent);outline-offset:2px;}

@media (prefers-reduced-motion: reduce){
  .vtm-btn:hover,.tm-btn:hover,.navbtn:hover,.ai-brief-link:hover,
  a.card:hover,a.actitem:hover,a.idx-alloc:hover{transform:none;}
}

