<link rel="stylesheet" href="product-nav-icons.css">
<style>
/* ambient aurora — fixed accents blended into transparent, pinned behind all
   content (paints over the opaque body bg, under the page). Light default gets
   the airier tint; dark gets the richer wash. */
html body::before{content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:
   radial-gradient(680px 440px at 10% -8%,color-mix(in srgb,#416aec 9%,transparent),transparent 68%),
   radial-gradient(620px 440px at 94% 2%,color-mix(in srgb,#8b5cf6 8%,transparent),transparent 70%),
   radial-gradient(760px 520px at 50% 112%,color-mix(in srgb,#0ea5e9 7%,transparent),transparent 70%);}
html[data-theme="dark"] body::before{
  background:
   radial-gradient(680px 440px at 10% -8%,color-mix(in srgb,#416aec 20%,transparent),transparent 68%),
   radial-gradient(620px 440px at 94% 2%,color-mix(in srgb,#8b5cf6 16%,transparent),transparent 70%),
   radial-gradient(760px 520px at 50% 112%,color-mix(in srgb,#0ea5e9 14%,transparent),transparent 70%);}

/* buttons — smooth transition + a subtle accent glow / lift on hover (additive;
   vtm/tm only exist on the Bitcoin Vector page, harmless elsewhere) */
.vtm-btn,.tm-btn,.navbtn,.ai-brief-link{transition:transform .16s ease,border-color .16s ease,
  color .16s ease,background .16s ease,box-shadow .18s ease;}
.vtm-btn:hover,.tm-btn:hover,.navbtn:hover{border-color:color-mix(in srgb,var(--blue) 58%,var(--grid));
  box-shadow:0 4px 13px -5px color-mix(in srgb,var(--blue) 40%,transparent);}
.ai-brief-link:hover{transform:translateY(-1px);
  box-shadow:0 5px 14px -5px color-mix(in srgb,var(--blue) 42%,transparent);}

/* top-bar link light-up — accent-tinted hover/active. Mix base uses the FULL
   surface fallback chain --card → --panel2 → --panel (+ hardcoded final), same as
   the glass fill below: the vector family has two palette conventions (most pages
   define --card; commodities uses --panel2/--panel and no --card), so a bare
   --card OR bare --panel2 base is null on some pages → invalid color-mix → dead
   hover. The dropdown-item hover moved to the aurora-glass block below. */
a.nav-link:hover,a.nav-link.active{background:color-mix(in srgb,var(--blue) 12%,var(--card,var(--panel2,var(--panel,#eef1f6))));}
html[data-theme="dark"] a.nav-link:hover,html[data-theme="dark"] a.nav-link.active{
  background:color-mix(in srgb,var(--blue) 20%,var(--card,var(--panel2,var(--panel,#222732))));}

/* 3rd-tier fly-out (Other Assets ▸ Bitcoin Vector / Commodities) — layout only,
   palette inherited from the host page's inline nav-dd-menu. Loaded after the
   page <style>, so these position overrides win. */
.nav-dd-menu .nav-sub{display:block;position:relative;}
.nav-dd-menu .nav-sub>a.nav-sub-trig{display:flex;align-items:flex-start;}
.nav-dd-menu .nav-sub>a.nav-sub-trig .caret-r{margin-left:auto;padding-left:12px;font-size:10px;
  opacity:.55;flex:none;align-self:center;transition:transform .2s,color .2s,opacity .2s,filter .2s;}
/* breathe only while the dropdown is open + hover-capable + motion allowed — never
   on hidden carets (perf) or the mobile accordion (theme.js rotate clobber). */
@media (hover:hover) and (prefers-reduced-motion:no-preference){
  .nav-dd:hover .nav-sub>a.nav-sub-trig .caret-r,
  .nav-dd:focus-within .nav-sub>a.nav-sub-trig .caret-r{animation:navCaretBreath 2.6s ease-in-out infinite;}}
.nav-dd-menu .nav-sub:hover>a.nav-sub-trig .caret-r{animation:none;opacity:1;transform:translateX(3px);
  color:var(--blue,var(--link,#5b9dff));
  filter:drop-shadow(0 0 5px color-mix(in srgb,var(--blue,var(--link,#5b9dff)) 65%,transparent));}
.nav-dd-menu .nav-sub>a.nav-sub-trig .nav-sub-text{display:block;flex:1;min-width:0;white-space:normal;}
.nav-dd-menu .nav-sub>.nav-dd-menu{top:-7px;left:100%;z-index:95;}
.nav-dd-menu .nav-sub::after{content:"";position:absolute;top:0;left:100%;width:12px;height:100%;}

/* ---- #286 regression repair -------------------------------------------------
   PR #286 switched the self-contained Vector-family pages (vector, commodities,
   forex, bonds, transmission) from the old inline `.topbar` nav to
   `<nav class="site-nav">` — but these pages don't link theme.css, so the
   `.site-nav` menu lost ALL its base styling and rendered as a fully-expanded,
   unstyled list ("menu looks css-broken"). Restore the base menu + controls CSS
   here (the partial every Vector-family page already shares), themed with the
   Vector-family vars (--card/--grid/--ink/--text/--muted/--blue) and scoped to
   `.site-nav` so the `.topbar` pages that also include this partial keep their
   own inline nav untouched. The fly-out + hover polish above still apply. The
   `≤700px` mobile hamburger is injected later by theme.js and wins on order. */
.site-nav{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:12px;row-gap:9px;max-width:1500px;margin-left:auto;margin-right:auto}
/* menu on its own first row (one line); search + controls share row two — holds the bar to two rows */
.site-nav .nav-links{grid-column:1 / -1;grid-row:1;display:flex;flex-wrap:wrap;align-items:center;gap:3px;min-width:0}
.site-nav .nav-search{grid-column:1;grid-row:2;max-width:480px;position:relative;min-width:0}
/* global stock search field — the #286 repair restored the menu/brand/controls but
   left the search field itself unstyled: the <input> fell back to a raw browser box
   (inset border, square corners, ~150px wide) with the 🔎 glyph floating inline and
   the suggestions list dropping into normal flow ("search bar looks css-broken").
   Port theme.css's .nav-search recipe, scoped to .site-nav and themed via var
   fallbacks that cover every palette this partial serves: theme.css pages
   (--panel2/--line/--text/--muted/--link/--glass-*), the --card/--grid/--text/--muted
   pages, and commodities' --panel2/--line/--tx/--mut/--blue. Loaded after each page's
   own <style> (and after theme.css on the two pages that link it), so it wins. */
/* CLS: pre-collapse the mobile nav at PARSE time (port of the theme.css rule —
   this partial's pages don't all load theme.css). theme.js's hamburger sheet lands
   ~2s in on phones; until then the expanded menu caused a 0.30 layout shift
   (2026-07-21 audit). :not(.nav-open) yields once the flyout opens; the noscript
   re-expand in _navlinks.html.j2 keeps the no-JS fallback reachable. */
@media (max-width:900px){
  .site-nav:not(.nav-open) .nav-links{display:none}
}
.site-nav .nav-search .mag{position:absolute;left:11px;top:50%;transform:translateY(-50%);font-size:12px;opacity:.65;pointer-events:none}
.site-nav .nav-search input{width:100%;box-sizing:border-box;padding:8px 12px 8px 32px;border-radius:10px;border:1px solid color-mix(in srgb,#416aec 30%,var(--line,var(--grid)));background:var(--panel2,var(--card));color:var(--text,var(--tx));font:inherit;font-size:13px;outline:none;box-shadow:0 0 5px 0 rgba(65,106,236,.10);transition:border-color .18s,box-shadow .25s ease}
/* Perf: glow breathe on a pseudo animating ONLY opacity (compositor) — animating
   border/box-shadow on the input restyled+repainted every frame (2026-07-21 mobile
   audit; mirrors theme.css .nav-search::after). Local keyframes: vector-family
   pages don't all load theme.css. */
.site-nav .nav-search{position:relative}
.site-nav .nav-search::after{content:"";position:absolute;inset:0;border-radius:10px;border:1px solid #416aec;box-shadow:0 0 0 3px rgba(65,106,236,.22),0 0 16px 2px rgba(65,106,236,.38);opacity:0;pointer-events:none;animation:vpGlowO 3.8s ease-in-out infinite}
.site-nav .nav-search:focus-within::after{animation:none;opacity:0}
@keyframes vpGlowO{0%,100%{opacity:0}50%{opacity:1}}
.site-nav .nav-search input::placeholder{color:var(--muted,var(--mut))}
.site-nav .nav-search input:focus{border-color:var(--blue,var(--link));box-shadow:none}
@media(prefers-reduced-motion:reduce){.site-nav .nav-search::after{animation:none;opacity:0}}
.site-nav .nav-sugg{position:absolute;top:calc(100% + 5px);left:0;right:0;z-index:80;background:var(--glass-bg,color-mix(in srgb,var(--card,var(--panel)) 92%,transparent));-webkit-backdrop-filter:var(--glass-blur,saturate(180%) blur(22px));backdrop-filter:var(--glass-blur,saturate(180%) blur(22px));border:1px solid var(--glass-brd,color-mix(in srgb,var(--ink) 12%,transparent));border-radius:13px;overflow:hidden;overflow-y:auto;max-height:60vh;box-shadow:var(--glass-shadow,0 20px 54px -24px rgba(20,32,64,.34),0 10px 24px -14px rgba(20,32,64,.20));display:none}
html[data-theme="dark"] .site-nav .nav-sugg{box-shadow:var(--glass-shadow,0 24px 64px -22px rgba(3,7,18,.74),0 10px 26px -12px rgba(3,7,18,.55))}
.site-nav .nav-sugg.show{display:block}
.site-nav .nav-sugg .row{display:flex;align-items:center;gap:9px;padding:8px 12px;cursor:pointer}
.site-nav .nav-sugg .row:hover,.site-nav .nav-sugg .row.sel{background:color-mix(in srgb,var(--blue,var(--link)) 12%,var(--panel2,var(--card)))}
.site-nav .nav-sugg .row .mkt{flex:none;width:20px;text-align:center;font-size:13px;line-height:1}
.site-nav .nav-sugg .row b{min-width:58px;font-size:13px;color:var(--text,var(--tx));font-weight:600}
.site-nav .nav-sugg .row small{flex:1;color:var(--muted,var(--mut));font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.site-nav .nav-sugg .row .stt{font-size:10px;font-weight:700;padding:2px 7px;border-radius:6px;white-space:nowrap}
.site-nav .nav-sugg .empty{padding:11px 13px;color:var(--muted,var(--mut));font-size:12.5px}
/* MASTERMIND brand lockup — covers the .site-nav (migrated) and legacy .topbar nav (mirrors theme.css; --blue stands in for the macro --link). */
.site-nav .nav-brand,.topbar .nav-brand{display:inline-flex;align-items:center;gap:8px;flex:none;padding:3px 10px 3px 4px;margin:0 6px 0 0;border-radius:11px;text-decoration:none;transition:background .18s,transform .16s ease}
.site-nav .nav-brand:hover,.topbar .nav-brand:hover{background:color-mix(in srgb,var(--blue) 11%,transparent);transform:translateY(-1px)}
.site-nav .nav-brand .brand-glyph,.topbar .nav-brand .brand-glyph{width:29px;height:29px;display:block;flex:none;filter:drop-shadow(0 2px 6px rgba(40,56,128,.34))}
.site-nav .nav-brand .brand-word,.topbar .nav-brand .brand-word{font-family:var(--font-ui);font-size:13.5px;font-weight:900;letter-spacing:.07em;line-height:1;color:var(--text);white-space:nowrap}
@media(max-width:560px){.site-nav .nav-brand .brand-word,.topbar .nav-brand .brand-word{display:none}}
.site-nav a.nav-link{padding:7px 11px;border-radius:9px;font-size:13.5px;font-weight:500;color:var(--muted);text-decoration:none;white-space:nowrap;transition:color .18s,background .18s}
.site-nav .nav-dd{position:relative;display:inline-flex}
.site-nav .nav-dd>a.nav-link .caret{display:inline-block;margin-left:3px;font-size:9px;opacity:.6;transition:transform .2s}
.site-nav .nav-dd:hover>a.nav-link .caret,.site-nav .nav-dd:focus-within>a.nav-link .caret{transform:rotate(180deg)}
.site-nav .nav-dd::after{content:"";position:absolute;left:0;right:0;top:100%;height:9px}
/* The two rules above are theme.css copies, and this partial loads AFTER
   navigation-refresh.css — at an identical (0,2,0) they silently outranked the
   wide-menu anchors that file owns. A .nav-market-dd/.nav-mega-dd left
   `position:relative` makes the pill the offset parent, so the mega's `right:0`
   pinned a 1276px panel to the RIGHT EDGE OF ITS TRIGGER and hung the other
   ~950px off the left of the viewport (that is the split-panel artifact on
   special_situations.html and the other 58 vector-family pages). Restoring
   static also restores navigation-refresh's `content:none`: on a static parent
   the ::after bridge stops being a 9px strip under the pill and becomes one
   spanning the whole header, which keeps panels alive on any downward exit.
   Re-asserted here verbatim, under the SAME media gates as the source, so the
   family matches a theme.css page exactly. */
@media (min-width: 701px){
  .site-nav .nav-mega-dd{position:static}
  .site-nav .nav-mega-dd::after{content:none}
}
@media (min-width: 901px){
  .site-nav .nav-market-dd{position:static}
  .site-nav .nav-market-dd::after{content:none}
}
/* frosted glass — mirrors the --glass-* token recipe in theme.css (which this
   self-contained family can't load), themed with the vector palette. Dual-targets
   BOTH nav wrappers this family ships: the migrated `.site-nav` pages (forex,
   bonds, commodities, vector, crossasset, transmission) and the legacy `.topbar`
   pages (strategies, masterminds, spr, *_allocation …), so every page in the
   family gets the same glass — not just the site-nav half. Loaded after each
   page's inline `.nav-dd-menu` (0,1,0), so this (0,2,0) wins. */
/* surface fallback chain --card → --panel2 → --panel covers BOTH vector-family
   palette conventions: most pages (forex/vector/bonds/spr/strategies…) define
   --card but not --panel2; commodities uses --panel2/--panel and no --card. A
   hardcoded final keeps the glass opaque even if a page defines none. */
