   underweight/avoid=bearish → green in zh. swap both bg AND color literals. */
html[data-lang="zh"] .chip.ow { background:rgba(210,70,70,.14); color:#cf4b4b; border-color:rgba(210,70,70,.4); }
html[data-lang="zh"] .chip.uw, html[data-lang="zh"] .chip.avoid { background:rgba(34,160,90,.14); color:#1f9d57; border-color:rgba(34,160,90,.4); }
.chip.fade { background:rgba(70,120,210,.14); color:#3f72d6; border-color:rgba(70,120,210,.4); }
.chip.conv { background:var(--grid); color:var(--muted); }
.thesis .body { margin:6px 0; }
