/* ---- cross-market AI-semis confirmer chip (lite/THS page; display-only) ---- */
.semis-chip { display:flex; flex-wrap:wrap; align-items:baseline; gap:6px 10px; background:var(--panel2);
  border:1px solid var(--line); border-radius:9px; padding:8px 12px; margin:10px 0 0; font-size:12.5px; }
.semis-chip .sx-tag { font-size:10.5px; color:var(--muted); font-style:italic; }
.semis-badge { display:inline-block; font-size:10px; font-weight:650; border:1px solid var(--line);
  border-radius:6px; padding:0 6px; margin-left:6px; color:var(--muted); vertical-align:1px; }
.semis-badge.on { color:var(--ink-up, var(--up)); border-color:color-mix(in srgb, var(--up) 40%, var(--line)); }
/* ---- score badge ---- */
.score-badge { display:inline-flex; align-items:center; gap:3px; font-size:11px; font-weight:700;
  padding:1px 7px; border-radius:7px; border:1px solid var(--line); font-variant-numeric:tabular-nums;
  vertical-align:1px; margin-left:6px; }
.score-badge.strong { color:#4ade80; border-color:color-mix(in srgb,#4ade80 40%,var(--line)); background:color-mix(in srgb,#4ade80 8%,transparent); }
.score-badge.neutral { color:var(--muted); border-color:var(--line); }
.score-badge.weak { color:#f87171; border-color:color-mix(in srgb,#f87171 40%,var(--line)); background:color-mix(in srgb,#f87171 8%,transparent); }
/* ---- turn-state chip ---- */
.turn-chip { display:inline-block; font-size:10.5px; font-weight:600; padding:1px 6px; border-radius:6px;
  border:1px solid var(--line); margin-left:5px; vertical-align:1px; }
.turn-chip.washed_out { color:#60a5fa; border-color:color-mix(in srgb,#60a5fa 40%,var(--line)); }
.turn-chip.basing     { color:#facc15; border-color:color-mix(in srgb,#facc15 40%,var(--line)); }
.turn-chip.turning    { color:#fb923c; border-color:color-mix(in srgb,#fb923c 40%,var(--line)); }
.turn-chip.confirmed  { color:#4ade80; border-color:color-mix(in srgb,#4ade80 40%,var(--line)); }
/* ---- signal tier chip ---- */
.sig-fresh { color:#4ade80; font-size:8px; vertical-align:middle; margin-left:2px; }
.sig-chip { display:inline-block; font-size:10px; font-weight:700; padding:0 5px;
  border-radius:5px; vertical-align:1px; color:var(--ink-up, var(--up));
  border:1px solid color-mix(in srgb,var(--up) 40%,var(--line)); margin-left:4px; }
/* ---- entry radar strip ---- */
.entry-radar { background:var(--panel); border:1px solid var(--line); 
  border-radius:10px; padding:12px 15px; margin:0 0 20px; }
.entry-radar .er-head { font-size:14px; font-weight:700; margin:0 0 2px; display:flex; align-items:center; gap:8px; }
.entry-radar .er-sub { font-size:12px; color:var(--muted); margin:0 0 10px; line-height:1.5; }
.entry-radar .er-items { display:flex; flex-direction:column; gap:7px; }
.entry-radar .er-item { display:flex; flex-wrap:wrap; align-items:center; gap:6px 10px; font-size:13px; }
.entry-radar .er-reco { font-size:11px; color:var(--muted); }
.entry-radar .er-note { font-size:11px; color:var(--muted); margin-top:8px; line-height:1.5; border-top:1px solid var(--line); padding-top:7px; }
.entry-radar .er-empty { color:var(--muted); font-size:12.5px; font-style:italic; padding:4px 0; }
/* ---- overlap chips ---- */
.overlap-row { margin:6px 0 2px; display:flex; flex-wrap:wrap; gap:5px; align-items:center; font-size:11.5px; }
.overlap-chip { display:inline-block; padding:1px 8px; border:1px solid var(--line); border-radius:7px;
  background:var(--panel2); font-size:11px; cursor:pointer; color:inherit; }
.overlap-chip:hover { border-color:var(--muted); }

/* ── Theme Context Hero — aurora living-glass (ported from baskets.html.j2) ── */
#theme-context-hero { position:relative; overflow:hidden; border-radius:12px;
  background:rgba(var(--panel-rgb,16,22,30),.55); border:1px solid rgba(255,255,255,.09);
  backdrop-filter:blur(16px); -webkit-backdrop-filter:blur(16px);
  box-shadow:0 8px 28px rgba(0,0,0,.40),0 1.5px 0 rgba(255,255,255,.06) inset;
  padding:16px 18px; margin-top:10px; }
[data-theme='light'] #theme-context-hero {
  background:rgba(255,255,255,.78); border-color:rgba(0,0,0,.09);
  box-shadow:0 4px 18px rgba(0,0,0,.08),0 1px 0 rgba(255,255,255,.9) inset; }
.tc-aurora { position:absolute; inset:0; pointer-events:none; z-index:0; overflow:hidden; }
.tc-aurora::before { content:""; position:absolute; top:-80px; left:-60px;
  width:480px; height:380px; border-radius:50%; filter:blur(80px);
  background:radial-gradient(ellipse,var(--tc-blob-a,rgba(74,222,128,.08)) 0%,transparent 70%);
  animation:tc-drift-a 28s ease-in-out infinite alternate; }
.tc-aurora::after  { content:""; position:absolute; bottom:-60px; right:-40px;
  width:380px; height:320px; border-radius:50%; filter:blur(80px);
  background:radial-gradient(ellipse,rgba(93,139,255,.06) 0%,transparent 70%);
  animation:tc-drift-b 34s ease-in-out infinite alternate; }
@keyframes tc-drift-a { from{transform:translate(0,0)} to{transform:translate(30px,20px)} }
@keyframes tc-drift-b { from{transform:translate(0,0)} to{transform:translate(-25px,18px)} }
@media(prefers-reduced-motion:reduce){
  .tc-aurora,.tc-aurora::before,.tc-aurora::after{ animation:none; } }
