rules.old:
/* BioCatalyst Intelligence — current-source clinical trial workbench. */
* { box-sizing: border-box; }

/* Palette derived from the subject: a versioned regulatory record.
   stamp  — methyl-violet registrar ink; the KNOWN-AT clock and the page accent
   filed  — kraft/ochre folder stock; the EFFECTIVE clock (when a fact was true)
   redline— the correction mark on a filed page; never sentiment, never direction
   onion  — onionskin carbon copy; the first-seen observation ledger
   The ground is ruled ledger paper rather than an ambient glow. */
:root {
  --bci-stamp: #8f7bff;
  --bci-stamp-strong: #b9adff;
  --bci-filed: #e3a14a;
  --bci-filed-strong: #f3c489;
  --bci-redline: #ef6a52;
  --bci-redline-strong: #ff9683;
  --bci-observe: #9db06a;
  --bci-observe-strong: #c4d296;
  /* Legacy alias: the earlier accent name now resolves to the stamp ink so the
     whole surface migrates in one place instead of drifting two accents. */
  --bci-cyan: var(--bci-stamp);
  --bci-cyan-strong: var(--bci-stamp-strong);
  --bci-glass: color-mix(in srgb, var(--panel) 88%, transparent);
  --bci-soft: color-mix(in srgb, var(--panel2) 72%, transparent);
  --bci-line: color-mix(in srgb, var(--text) 12%, transparent);
  --bci-line-strong: color-mix(in srgb, var(--text) 22%, transparent);
  --bci-rule: color-mix(in srgb, var(--text) 6%, transparent);
  --bci-shadow: 0 24px 66px -42px rgba(0, 0, 0, .82), inset 0 1px 0 rgba(255,255,255,.05);
  --bci-radius: 18px;
  --bci-ruled: repeating-linear-gradient(180deg, var(--bci-rule) 0 1px, transparent 1px 29px);
}

/* Light is composed, not inverted: white record cards float on a deeper desk
   tone, the stamp ink deepens so it holds on paper, and the ochre darkens to
   an ink rather than a highlighter smear. */
html[data-theme="light"] {
  --bci-stamp: #5334c9;
  --bci-stamp-strong: #3d1fa6;
  --bci-filed: #9a640d;
  --bci-filed-strong: #7a4d05;
  --bci-redline: #b93a20;
  --bci-redline-strong: #94240d;
  --bci-observe: #5f7429;
  --bci-observe-strong: #46561a;
  --bci-glass: var(--panel);
  --bci-soft: color-mix(in srgb, var(--panel2) 82%, var(--panel));
  --bci-line: color-mix(in srgb, #1b2430 13%, transparent);
  --bci-line-strong: color-mix(in srgb, #1b2430 24%, transparent);
  --bci-rule: color-mix(in srgb, #1b2430 5%, transparent);
  --bci-shadow: 0 18px 38px -28px rgba(20, 38, 62, .38), 0 1px 0 rgba(20, 38, 62, .05);
}

body.bci-page {
  min-width: 320px;
  margin: 0;
  padding: 18px;
  overflow-x: hidden;
  color: var(--text);
  background: var(--bci-ruled), var(--bg);
  font: 400 14px/1.52 var(--font-ui);
  -webkit-font-smoothing: antialiased;
}
html[data-theme="light"] body.bci-page { background: var(--bci-ruled), #e8ebf1; }

.bci-page :is(button, input, select) { font: inherit; }
.bci-page button { color: inherit; }
.bci-page button, .bci-page select { cursor: pointer; }
.bci-page [hidden] { display: none !important; }
.bci-page :focus-visible { outline: 2px solid var(--bci-cyan); outline-offset: 3px; }
.bci-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }

.bci-workspace { width: min(100%, 1540px); margin: 18px auto 72px; }

.bci-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 26px;
  padding: 27px 4px 24px;
}
.bci-eyebrow, .bci-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 6px;
  color: var(--bci-cyan);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .115em;
  text-transform: uppercase;
}
.bci-pulse { width: 7px; height: 7px; border: 1px solid var(--bci-cyan); border-radius: 50%; box-shadow: 0 0 0 4px color-mix(in srgb, var(--bci-cyan) 12%, transparent); }
.bci-hero h1 { max-width: 640px; margin: 0; font-size: clamp(30px, 4vw, 49px); line-height: .99; letter-spacing: -.055em; }
.bci-deck { max-width: 580px; margin: 11px 0 0; color: var(--muted); font-size: 15px; }

.bci-run-status {
  display: flex;
  align-items: center;
  min-width: 288px;
  padding: 10px 10px 10px 13px;
  border: 1px solid var(--bci-line);
  border-radius: 14px;
  background: var(--bci-glass);
  box-shadow: var(--bci-shadow);
  backdrop-filter: saturate(150%) blur(18px);
  -webkit-backdrop-filter: saturate(150%) blur(18px);
  gap: 9px;
}
.bci-status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--bci-cyan); box-shadow: 0 0 0 4px color-mix(in srgb, var(--bci-cyan) 12%, transparent); }
.bci-run-status.is-stale .bci-status-dot { background: var(--warn); box-shadow: 0 0 0 4px color-mix(in srgb, var(--warn) 13%, transparent); }
.bci-run-status.is-unavailable .bci-status-dot { background: var(--act); box-shadow: 0 0 0 4px color-mix(in srgb, var(--act) 13%, transparent); }
.bci-status-label, .bci-status-detail { display: block; }
.bci-status-label { color: var(--text); font-size: 11px; font-weight: 750; line-height: 1.2; }
.bci-status-detail { margin-top: 2px; color: var(--muted); font-size: 10px; }
.bci-refresh {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  margin-left: auto;
  padding: 7px 9px;
  border: 1px solid var(--bci-line);
  border-radius: 9px;
  color: var(--muted);
  background: color-mix(in srgb, var(--panel2) 52%, transparent);
  font-size: 10px;
  font-weight: 750;
  gap: 5px;
  transition: border-color .18s ease, color .18s ease, transform .18s ease, background .18s ease;
}
.bci-refresh svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.75; }
.bci-refresh:hover { border-color: color-mix(in srgb, var(--bci-cyan) 46%, var(--bci-line)); color: var(--bci-cyan); transform: translateY(-1px); }
.bci-refresh.is-spinning svg { animation: bci-spin .8s linear infinite; }
@keyframes bci-spin { to { transform: rotate(360deg); } }

.bci-information {
  display: grid;
  grid-template-columns: minmax(228px, .72fr) minmax(410px, 1.55fr) minmax(300px, 1fr);
  align-items: stretch;
  height: min(760px, calc(100vh - 180px));
  min-height: 620px;
  border: 1px solid var(--bci-line);
  border-radius: var(--bci-radius);
  background: var(--bci-glass);
  box-shadow: var(--bci-shadow);
  overflow: hidden;
  backdrop-filter: saturate(155%) blur(21px);
  -webkit-backdrop-filter: saturate(155%) blur(21px);
}
.bci-filter-pane, .bci-queue-pane, .bci-inspector-pane { min-width: 0; min-height: 0; height: 100%; overflow: hidden; }
.bci-filter-pane { overflow: auto; padding: 20px; border-right: 1px solid var(--bci-line); background: color-mix(in srgb, var(--panel2) 30%, transparent); }
.bci-queue-pane { display: flex; flex-direction: column; padding: 20px; border-right: 1px solid var(--bci-line); }
.bci-inspector-pane { display: flex; flex-direction: column; background: color-mix(in srgb, var(--panel2) 25%, transparent); }
.bci-pane-head, .bci-queue-head, .bci-inspector-head { border-bottom: 1px solid var(--bci-line); }
.bci-pane-head { padding-bottom: 17px; }
.bci-pane-head h2, .bci-queue-head h2, .bci-inspector-head h2 { margin: 0; color: var(--text); font-size: 17px; line-height: 1.16; letter-spacing: -.025em; }
/* Five surfaces read as a filed index, not as five squeezed tabs: one line
   each, a hairline rule between, and the active surface carries the stamp rail. */
.bci-mode-control { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 17px; overflow: hidden; border: 1px solid var(--bci-line); border-radius: 11px; background: color-mix(in srgb, var(--panel) 68%, transparent); box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 7%, transparent); }
.bci-mode { display: flex; align-items: center; min-height: 34px; padding: 0 10px 0 12px; border: 0; border-bottom: 1px solid var(--bci-line); color: var(--muted); background: transparent; font-size: 10.5px; font-weight: 780; letter-spacing: .005em; text-align: left; gap: 8px; transition: color .18s ease, background .18s ease, box-shadow .18s ease, padding .18s ease; }
.bci-mode::before { flex: none; width: 5px; height: 5px; border: 1px solid currentColor; border-radius: 1px; opacity: .55; content: ''; transform: rotate(45deg); }
.bci-mode:last-child { border-bottom: 0; }
.bci-mode:hover { color: var(--bci-stamp); background: color-mix(in srgb, var(--bci-stamp) 7%, transparent); }
.bci-mode.is-active { padding-left: 14px; color: var(--text); background: linear-gradient(90deg, color-mix(in srgb, var(--bci-stamp) 17%, transparent), transparent 78%); box-shadow: inset 3px 0 0 var(--bci-stamp); }
.bci-mode.is-active::before { background: var(--bci-stamp); border-color: var(--bci-stamp); opacity: 1; }
.bci-mode-prospective:hover { color: var(--bci-observe); background: color-mix(in srgb, var(--bci-observe) 8%, transparent); }
.bci-mode-prospective.is-active { background: linear-gradient(90deg, color-mix(in srgb, var(--bci-observe) 18%, transparent), transparent 78%); box-shadow: inset 3px 0 0 var(--bci-observe); }
.bci-mode-prospective.is-active::before { background: var(--bci-observe); border-color: var(--bci-observe); }
.bci-control-label { display: block; margin-bottom: 6px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.bci-search, .bci-control { display: block; margin-top: 17px; }
.bci-window-control { min-width: 0; margin: 17px 0 0; padding: 0; border: 0; }
.bci-window-options { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); overflow: hidden; border: 1px solid var(--bci-line); border-radius: 11px; background: color-mix(in srgb, var(--panel) 68%, transparent); box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 7%, transparent); }
.bci-window { min-height: 34px; border: 0; border-right: 1px solid var(--bci-line); color: var(--muted); background: transparent; font-size: 10px; font-weight: 780; transition: color .18s ease, background .18s ease; }
.bci-window:last-child { border-right: 0; }
.bci-window:hover { color: var(--bci-cyan); background: color-mix(in srgb, var(--bci-cyan) 7%, transparent); }
.bci-window.is-active { color: var(--text); background: linear-gradient(145deg, color-mix(in srgb, var(--bci-cyan) 22%, transparent), color-mix(in srgb, var(--bci-cyan) 8%, transparent)); box-shadow: inset 0 -2px 0 var(--bci-cyan); }
.bci-search-field { position: relative; display: block; }
.bci-search-field svg { position: absolute; top: 50%; left: 11px; width: 15px; height: 15px; fill: none; stroke: var(--muted); stroke-linecap: round; stroke-width: 1.7; transform: translateY(-50%); pointer-events: none; }
.bci-search input, .bci-control select {
  width: 100%;
  min-height: 40px;
  border: 1px solid var(--bci-line);
  border-radius: 10px;
  outline: 0;
  color: var(--text);
  background: color-mix(in srgb, var(--panel) 68%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 8%, transparent);
}
.bci-search input { padding: 9px 11px 9px 34px; }
.bci-control select { padding: 8px 10px; }
.bci-search input::placeholder { color: var(--muted); opacity: .85; }
.bci-search input:focus, .bci-control select:focus { border-color: color-mix(in srgb, var(--bci-cyan) 70%, var(--bci-line)); }
.bci-filter-actions { margin-top: 20px; }
.bci-clear { border: 0; padding: 3px 0; color: var(--bci-cyan); background: transparent; font-size: 11px; font-weight: 750; }
.bci-clear:hover { color: var(--bci-cyan-strong); text-decoration: underline; text-underline-offset: 3px; }
.bci-brain-launch { display: none; }
.bci-source-note { display: flex; margin-top: 29px; padding-top: 15px; border-top: 1px solid var(--bci-line); color: var(--muted); font-size: 11px; line-height: 1.52; gap: 9px; }
.bci-source-note p { margin: 0; }
.bci-source-mark { flex: none; color: var(--bci-cyan); font-size: 19px; line-height: .9; }

.bci-queue-head { display: flex; align-items: flex-start; justify-content: space-between; min-height: 86px; padding: 1px 1px 17px; gap: 12px; }
.bci-queue-subtitle { margin: 6px 0 0; color: var(--muted); font-size: 11px; }
.bci-asof { max-width: 145px; padding: 5px 7px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 22%, transparent); border-radius: 999px; color: var(--bci-cyan); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.25; text-align: right; }
.bci-asof:empty { display: none; }
.bci-state-notice { margin: 14px 0 0; padding: 10px 12px; border: 1px solid color-mix(in srgb, var(--warn) 29%, var(--bci-line)); border-radius: 11px; color: var(--muted); background: color-mix(in srgb, var(--warn) 7%, transparent); font-size: 11px; line-height: 1.4; }
.bci-state-notice.is-error { border-color: color-mix(in srgb, var(--act) 33%, var(--bci-line)); background: color-mix(in srgb, var(--act) 7%, transparent); }
.bci-state-notice.is-locked { border-color: color-mix(in srgb, #8b5cf6 34%, var(--bci-line)); background: color-mix(in srgb, #8b5cf6 8%, transparent); }
.bci-state-notice.is-restart { border-color: color-mix(in srgb, var(--bci-cyan) 36%, var(--bci-line)); background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); }
.bci-queue { display: flex; flex: 1; flex-direction: column; min-height: 0; margin-top: 13px; overflow: auto; padding-right: 4px; gap: 7px; }
.bci-queue-footer { padding: 12px 1px 0; border-top: 1px solid var(--bci-line); }
.bci-load-more { display: flex; align-items: center; justify-content: center; width: 100%; min-height: 38px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 34%, var(--bci-line)); border-radius: 10px; color: var(--bci-cyan); background: color-mix(in srgb, var(--bci-cyan) 6%, transparent); font-size: 10px; font-weight: 800; letter-spacing: .025em; transition: border-color .18s ease, color .18s ease, background .18s ease, transform .18s ease; }
.bci-load-more:hover:not(:disabled) { border-color: var(--bci-cyan); color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 12%, transparent); transform: translateY(-1px); }
.bci-load-more:disabled { cursor: wait; opacity: .62; }
.bci-trial {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  width: 100%;
  min-height: 96px;
  padding: 14px;
  border: 1px solid transparent;
  border-radius: 13px;
  color: inherit;
  background: transparent;
  text-align: left;
  gap: 12px;
  transition: background .18s ease, border-color .18s ease, transform .18s ease, box-shadow .18s ease;
}
.bci-trial:hover, .bci-trial.is-selected { border-color: color-mix(in srgb, var(--bci-cyan) 30%, var(--bci-line)); background: color-mix(in srgb, var(--bci-cyan) 7%, var(--bci-soft)); box-shadow: 0 10px 28px -25px color-mix(in srgb, var(--bci-cyan) 80%, transparent); }
.bci-trial:hover { transform: translateY(-1px); }
.bci-trial-main { min-width: 0; }
.bci-trial-topline { display: flex; align-items: center; gap: 7px; }
.bci-trial-id { color: var(--bci-cyan); font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; font-weight: 750; letter-spacing: .025em; }
.bci-registry-kind { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 24%, var(--bci-line)); border-radius: 99px; color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 7%, transparent); font-size: 8px; font-weight: 800; letter-spacing: .035em; line-height: 1.2; text-overflow: ellipsis; text-transform: uppercase; white-space: nowrap; }
.bci-status-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid var(--bci-line); border-radius: 99px; color: var(--muted); font-size: 9px; font-weight: 750; line-height: 1.2; text-overflow: ellipsis; white-space: nowrap; }
.bci-trial-title { display: -webkit-box; margin: 7px 0 0; overflow: hidden; color: var(--text); font-size: 12px; font-weight: 720; line-height: 1.34; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.bci-trial-meta { display: flex; flex-wrap: wrap; margin-top: 7px; color: var(--muted); font-size: 10px; gap: 4px 10px; }
.bci-trial-meta span { display: inline-flex; align-items: center; }
.bci-trial-meta span + span::before { width: 3px; height: 3px; margin-right: 9px; border-radius: 50%; background: var(--bci-line-strong); content: ''; }
.bci-trial-date { display: grid; justify-items: end; max-width: 124px; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-trial-date strong { display: block; color: var(--text); font-family: var(--font-ui); font-size: 13px; font-weight: 780; letter-spacing: -.02em; }
.bci-date-type { display: inline-flex; width: fit-content; padding: 3px 6px; border: 1px solid var(--bci-line); border-radius: 99px; color: var(--muted); background: color-mix(in srgb, var(--panel2) 55%, transparent); font-family: var(--font-ui); font-size: 8px; font-weight: 850; letter-spacing: .075em; line-height: 1; }
.bci-date-type.is-actual { border-color: color-mix(in srgb, var(--bci-cyan) 34%, var(--bci-line)); color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); }
.bci-date-type.is-estimated { border-color: color-mix(in srgb, var(--warn) 34%, var(--bci-line)); color: color-mix(in srgb, var(--warn) 80%, var(--text)); background: color-mix(in srgb, var(--warn) 8%, transparent); }
.bci-change-card { min-height: 126px; align-items: stretch; }
.bci-change-card .bci-trial-main { display: flex; flex-direction: column; }
.bci-change-card .bci-trial-topline { flex-wrap: wrap; }
.bci-change-card .bci-registry-kind { border-color: color-mix(in srgb, #9c7cff 35%, var(--bci-line)); color: color-mix(in srgb, #b6a2ff 82%, var(--text)); background: color-mix(in srgb, #8b5cf6 10%, transparent); }
.bci-change-preview { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border: 1px solid color-mix(in srgb, var(--bci-line) 86%, transparent); border-radius: 9px; color: var(--muted); background: color-mix(in srgb, var(--panel) 54%, transparent); font-family: var(--font-mono); font-size: 9px; line-height: 1.36; gap: 7px; }
.bci-change-preview > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bci-change-preview > b { color: var(--bci-cyan); font-family: var(--font-ui); font-size: 12px; font-weight: 760; }
.bci-change-receipt { display: grid; align-content: space-between; justify-items: end; min-width: 104px; padding: 1px 0; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 8px; }
.bci-change-receipt strong { color: var(--text); font-family: var(--font-ui); font-size: 12px; font-weight: 780; letter-spacing: -.02em; }
.bci-change-version { display: inline-flex; width: fit-content; padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 24%, var(--bci-line)); border-radius: 999px; color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 7%, transparent); font-family: var(--font-ui); font-size: 8px; font-weight: 850; letter-spacing: .06em; line-height: 1; }
.bci-prospective-card { min-height: 147px; align-items: stretch; }
.bci-prospective-card .bci-trial-main { display: flex; flex-direction: column; }
.bci-prospective-card .bci-trial-topline { flex-wrap: wrap; }
.bci-prospective-card:hover, .bci-prospective-card.is-selected { border-color: color-mix(in srgb, var(--bci-observe) 48%, var(--bci-line)); background: color-mix(in srgb, var(--bci-observe) 7%, var(--bci-soft)); box-shadow: 0 10px 28px -25px color-mix(in srgb, var(--bci-observe) 90%, transparent); }
.bci-observation-kind { display: inline-flex; width: fit-content; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--bci-observe) 45%, var(--bci-line)); border-radius: 99px; color: var(--bci-observe-strong); background: color-mix(in srgb, var(--bci-observe) 10%, transparent); font-family: var(--font-ui); font-size: 8px; font-weight: 830; letter-spacing: .045em; line-height: 1.2; text-overflow: ellipsis; text-transform: uppercase; white-space: nowrap; }
.bci-observation-preview { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border: 1px solid color-mix(in srgb, var(--bci-observe) 22%, var(--bci-line)); border-radius: 9px; color: var(--muted); background: linear-gradient(145deg, color-mix(in srgb, var(--bci-observe) 6%, var(--panel)), color-mix(in srgb, var(--panel) 54%, transparent)); font-family: var(--font-mono); font-size: 9px; line-height: 1.36; gap: 7px; }
.bci-observation-preview > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bci-observation-preview > b { color: var(--bci-observe); font-family: var(--font-ui); font-size: 12px; font-weight: 760; }
.bci-observation-preview.is-omitted { display: block; border-style: dashed; color: var(--muted); font-family: var(--font-ui); }
.bci-observation-preview.is-omitted > span { display: block; overflow: visible; text-overflow: clip; white-space: normal; }
.bci-observation-receipt { display: grid; align-content: space-between; justify-items: end; min-width: 118px; padding: 1px 0; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-observation-receipt strong { color: var(--text); font-family: var(--font-ui); font-size: 12px; font-weight: 780; letter-spacing: -.02em; }

/* Catalyst Radar — Trial Milestones (BioCatalyst P1-1). */
.bci-radar-card { align-items: stretch; flex-shrink: 0; }
.bci-radar-card .bci-trial-topline { flex-wrap: wrap; }
.bci-radar-card .bci-trial-topline > * { flex-shrink: 0; }
.bci-radar-group-title { margin: 18px 0 8px; padding: 0 2px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }
.bci-radar-group-title:first-child { margin-top: 2px; }
.bci-phase-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid var(--bci-line); border-radius: 99px; color: var(--muted); font-size: 9px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.bci-issuer-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border-radius: 99px; font-size: 9px; font-weight: 750; text-overflow: ellipsis; white-space: nowrap; }
.bci-issuer-chip.is-resolved { border: 1px solid color-mix(in srgb, var(--bci-cyan) 30%, var(--bci-line)); color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.bci-issuer-chip.is-unresolved { border: 1px dashed var(--bci-line-strong); color: var(--muted); background: transparent; }
.bci-issuer-chip.is-parent { border-style: dashed; border-color: color-mix(in srgb, var(--bci-filed) 40%, var(--bci-line)); color: var(--bci-filed-strong); background: color-mix(in srgb, var(--bci-filed) 8%, transparent); }
.bci-status-chip.is-paused { border-color: color-mix(in srgb, var(--warn) 34%, var(--bci-line)); color: color-mix(in srgb, var(--warn) 80%, var(--text)); background: color-mix(in srgb, var(--warn) 8%, transparent); }
.bci-status-chip.is-inactive { border-color: color-mix(in srgb, var(--bci-redline) 34%, var(--bci-line)); color: color-mix(in srgb, var(--bci-redline) 78%, var(--text)); background: color-mix(in srgb, var(--bci-redline) 8%, transparent); }
.bci-revision-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--bci-filed) 40%, var(--bci-line)); border-radius: 99px; color: var(--bci-filed-strong); background: color-mix(in srgb, var(--bci-filed) 10%, transparent); font-size: 9px; font-weight: 750; text-overflow: ellipsis; white-space: nowrap; }
.bci-days-to-milestone { display: block; color: var(--muted); font-family: var(--font-ui); font-size: 9px; font-weight: 650; letter-spacing: 0; }
.bci-radar-revision-section .bci-endpoint p { margin-top: 4px; }

.bci-skeleton { min-height: 95px; padding: 16px; border: 1px solid var(--bci-line); border-radius: 13px; background: color-mix(in srgb, var(--panel2) 32%, transparent); }
.bci-skeleton span { display: block; height: 10px; margin-bottom: 10px; border-radius: 999px; background: linear-gradient(90deg, color-mix(in srgb, var(--bci-line) 75%, transparent), color-mix(in srgb, var(--bci-cyan) 12%, transparent), color-mix(in srgb, var(--bci-line) 75%, transparent)); background-size: 220% 100%; animation: bci-shimmer 1.85s ease-in-out infinite; }
.bci-skeleton span:nth-child(1) { width: 30%; }.bci-skeleton span:nth-child(2) { width: 84%; }.bci-skeleton span:nth-child(3) { width: 57%; margin-bottom: 0; }
@keyframes bci-shimmer { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }
.bci-empty { display: grid; min-height: 270px; place-items: center; padding: 25px; color: var(--muted); text-align: center; }
.bci-empty > div { max-width: 265px; }
.bci-empty-mark { display: grid; width: 40px; height: 40px; margin: 0 auto 12px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 30%, var(--bci-line)); border-radius: 13px; color: var(--bci-cyan); font-size: 20px; place-items: center; }
.bci-empty strong { display: block; color: var(--text); font-size: 13px; }.bci-empty p { margin: 6px 0 0; font-size: 11px; line-height: 1.5; }.bci-empty button { margin-top: 12px; border: 1px solid var(--bci-line); border-radius: 8px; padding: 7px 10px; color: var(--bci-cyan); background: transparent; font-size: 10px; font-weight: 750; }

.bci-inspector-head { display: flex; align-items: flex-start; justify-content: space-between; min-height: 86px; padding: 21px 20px 17px; gap: 10px; }
.bci-inspector-close { width: 28px; height: 28px; padding: 0; border: 1px solid transparent; border-radius: 8px; color: var(--muted); background: transparent; font-size: 20px; line-height: 1; }
.bci-inspector-close:hover { border-color: var(--bci-line); color: var(--text); background: var(--bci-soft); }
.bci-inspector-body { flex: 1; overflow: auto; padding: 20px; }
.bci-inspector-empty { display: grid; min-height: 280px; place-items: center; color: var(--muted); text-align: center; }.bci-inspector-empty p { max-width: 230px; margin: 15px 0 0; font-size: 12px; line-height: 1.55; }
.bci-empty-orbit { position: relative; display: block; width: 46px; height: 46px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 50%, transparent); border-radius: 50%; }.bci-empty-orbit::before,.bci-empty-orbit::after { position: absolute; border: 1px solid color-mix(in srgb, var(--bci-cyan) 30%, transparent); border-radius: 50%; content: ''; }.bci-empty-orbit::before { inset: 10px; }.bci-empty-orbit::after { top: 18px; left: 18px; width: 8px; height: 8px; border: 0; background: var(--bci-cyan); box-shadow: 0 0 0 5px color-mix(in srgb, var(--bci-cyan) 13%, transparent); }
.bci-detail-title { margin: 0; color: var(--text); font-size: 15px; letter-spacing: -.02em; line-height: 1.28; }.bci-detail-id { margin: 6px 0 0; color: var(--bci-cyan); font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; }.bci-detail-link { display: inline-flex; margin-top: 14px; color: var(--bci-cyan); font-size: 11px; font-weight: 750; text-decoration: none; }.bci-detail-link:hover { color: var(--bci-cyan-strong); text-decoration: underline; text-underline-offset: 3px; }
.bci-detail-section { margin-top: 22px; padding-top: 18px; border-top: 1px solid var(--bci-line); }.bci-detail-section h3 { margin: 0 0 10px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }.bci-detail-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 8px; }.bci-detail-fact { min-width: 0; padding: 9px; border: 1px solid var(--bci-line); border-radius: 10px; background: color-mix(in srgb, var(--panel) 47%, transparent); }.bci-detail-fact span,.bci-detail-fact strong { display:block; }.bci-detail-fact span { color: var(--muted); font-size: 9px; }.bci-detail-fact strong { margin-top: 3px; overflow-wrap: anywhere; color: var(--text); font-size: 10px; line-height: 1.36; }.bci-detail-list { display: flex; flex-wrap: wrap; margin: 0; padding: 0; list-style: none; gap: 6px; }.bci-detail-list li { padding: 5px 7px; border: 1px solid var(--bci-line); border-radius: 8px; color: var(--muted); font-size: 10px; line-height: 1.34; }.bci-detail-note { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.bci-evidence-section { margin-top: 18px; padding-top: 15px; border-top-color: color-mix(in srgb, var(--bci-cyan) 25%, var(--bci-line)); }
.bci-evidence-strip { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.bci-evidence-strip .bci-detail-fact { position: relative; overflow: hidden; padding: 9px 10px; background: linear-gradient(145deg, color-mix(in srgb, var(--bci-cyan) 7%, var(--panel)), color-mix(in srgb, var(--panel) 67%, transparent)); }
.bci-evidence-strip .bci-detail-fact::before { position: absolute; top: 0; left: 0; width: 100%; height: 1px; background: color-mix(in srgb, var(--bci-cyan) 34%, transparent); content: ''; }
.bci-evidence-link { display: block; margin-top: 4px; overflow-wrap: anywhere; color: var(--bci-cyan); font-size: 10px; font-weight: 760; line-height: 1.35; text-decoration: none; }
.bci-evidence-link:hover { color: var(--bci-cyan-strong); text-decoration: underline; text-underline-offset: 3px; }
.bci-endpoints { display: grid; gap: 8px; }.bci-endpoint { padding: 10px; border: 1px solid var(--bci-line); border-radius: 10px; background: color-mix(in srgb, var(--panel) 47%, transparent); }.bci-endpoint strong,.bci-endpoint span { display: block; }.bci-endpoint strong { color: var(--text); font-size: 11px; line-height: 1.4; }.bci-endpoint span { margin-top: 4px; color: var(--bci-cyan); font-family: var(--font-mono); font-size: 9px; line-height: 1.35; }.bci-endpoint p { margin: 7px 0 0; color: var(--muted); font-size: 10px; line-height: 1.48; }
.bci-history-group { position: relative; margin-top: 9px; overflow: hidden; padding: 12px 12px 12px 15px; background: linear-gradient(145deg, color-mix(in srgb, var(--bci-cyan) 7%, var(--panel)), color-mix(in srgb, var(--panel) 58%, transparent)); }
.bci-history-group::before { position: absolute; inset: 0 auto 0 0; width: 2px; background: linear-gradient(180deg, var(--bci-cyan), color-mix(in srgb, var(--bci-cyan) 12%, transparent)); content: ""; }
.bci-history-group > strong { font-size: 12px; letter-spacing: -.01em; }
.bci-history-group > .bci-detail-link { margin-top: 6px; font-family: var(--font-mono); font-size: 9px; font-weight: 650; }
.bci-history-delta { margin-top: 10px; padding-top: 10px; border-top: 1px solid color-mix(in srgb, var(--bci-line) 72%, transparent); }
.bci-history-kind { display: inline-flex !important; width: fit-content; margin: 0 0 2px !important; padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 24%, transparent); border-radius: 999px; background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); color: var(--bci-cyan-strong) !important; font-family: var(--font-ui) !important; font-size: 8px !important; font-weight: 800; letter-spacing: .06em; line-height: 1 !important; text-transform: uppercase; }
.bci-history-delta p { overflow-wrap: anywhere; }
.bci-observation-section { border-top-color: color-mix(in srgb, var(--bci-observe) 36%, var(--bci-line)); }
.bci-observation-section > h3 { color: var(--bci-observe-strong); }
.bci-observation-strip .bci-detail-fact { background: linear-gradient(145deg, color-mix(in srgb, var(--bci-observe) 8%, var(--panel)), color-mix(in srgb, var(--panel) 68%, transparent)); }
.bci-observation-strip .bci-detail-fact::before { background: color-mix(in srgb, var(--bci-observe) 40%, transparent); }
.bci-observation-note { margin-top: 10px; padding: 9px 10px; border-left: 2px solid color-mix(in srgb, var(--bci-observe) 60%, transparent); background: color-mix(in srgb, var(--bci-observe) 5%, transparent); }
.bci-observation-delta { margin-top: 9px; padding: 12px; border-color: color-mix(in srgb, var(--bci-observe) 26%, var(--bci-line)); background: linear-gradient(145deg, color-mix(in srgb, var(--bci-observe) 7%, var(--panel)), color-mix(in srgb, var(--panel) 58%, transparent)); }
.bci-observation-delta p { overflow-wrap: anywhere; }
.bci-loading-detail { display: grid; min-height: 220px; place-items: center; color: var(--muted); font-size: 11px; }.bci-loading-detail::before { width: 21px; height: 21px; margin-bottom: 9px; border: 2px solid color-mix(in srgb, var(--bci-cyan) 25%, transparent); border-top-color: var(--bci-cyan); border-radius: 50%; content: ''; animation: bci-spin .8s linear infinite; }

/* ------------------------------------------------------------------ *
 * D0b — decision sentence, temporal braid, screen, peer matrix, tape.
 * ------------------------------------------------------------------ */

/* The stamp: the one type signature on this page. A cut-corner plate with a
   doubled baseline rule, set in tracked mono — an office received-stamp. */
.bci-stamp-mark {
  display: inline-flex;
  align-items: center;
  flex: none;
  padding: 5px 10px 4px;
  border-bottom: 1px solid var(--bci-stamp);
  color: var(--bci-stamp-strong);
  background: color-mix(in srgb, var(--bci-stamp) 15%, transparent);
  box-shadow: 0 3px 0 -1px color-mix(in srgb, var(--bci-stamp) 55%, transparent);
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .16em;
  line-height: 1.25;
  text-transform: uppercase;
}
html[data-theme="light"] .bci-stamp-mark { color: var(--bci-stamp-strong); background: color-mix(in srgb, var(--bci-stamp) 11%, #fff); }
.bci-stamp-mark.is-wait { border-bottom-color: var(--bci-filed); color: var(--bci-filed-strong); background: color-mix(in srgb, var(--bci-filed) 16%, transparent); box-shadow: 0 3px 0 -1px color-mix(in srgb, var(--bci-filed) 58%, transparent); }
.bci-stamp-mark.is-conflict { border-bottom-color: var(--bci-redline); color: var(--bci-redline-strong); background: color-mix(in srgb, var(--bci-redline) 15%, transparent); box-shadow: 0 3px 0 -1px color-mix(in srgb, var(--bci-redline) 58%, transparent); }
.bci-stamp-mark.is-quiet { border-bottom-color: var(--bci-line-strong); color: var(--muted); background: color-mix(in srgb, var(--panel2) 70%, transparent); box-shadow: 0 3px 0 -1px var(--bci-line); }
html[data-theme="light"] .bci-stamp-mark.is-wait { background: color-mix(in srgb, var(--bci-filed) 10%, #fff); }
html[data-theme="light"] .bci-stamp-mark.is-conflict { background: color-mix(in srgb, var(--bci-redline) 9%, #fff); }

/* Decision sentence — first thing in the main pane, above the fold. */
.bci-decision { display: flex; align-items: baseline; margin: 14px 0 0; padding: 0 1px; gap: 11px; }
.bci-decision-why { min-width: 0; margin: 0; color: var(--text); font-size: 14.5px; font-weight: 560; letter-spacing: -.012em; line-height: 1.36; }
html[data-lang="zh"] .bci-decision-why { font-size: 14px; letter-spacing: 0; }

/* Temporal braid — the signature. Two clocks on one labelled scale; the
   horizontal bar between them IS the reporting lag. */
.bci-braid { margin-top: 14px; padding: 12px 13px 10px; border: 1px solid var(--bci-line); border-radius: 12px; background: color-mix(in srgb, var(--panel) 58%, transparent); }
.bci-braid[hidden] { display: none !important; }
.bci-braid-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.bci-braid-head h3 { margin: 0; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }
.bci-braid-unit { color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; }
.bci-braid-plot { position: relative; height: 86px; margin-top: 9px; }
.bci-braid-rail { position: absolute; right: 0; left: 0; height: 1px; background: var(--bci-line-strong); }
.bci-braid-rail.is-effective { top: 17px; background: color-mix(in srgb, var(--bci-filed) 42%, transparent); }
.bci-braid-rail.is-known { top: 53px; background: color-mix(in srgb, var(--bci-stamp) 42%, transparent); }
.bci-braid-rail-name { position: absolute; padding: 0 5px 0 0; color: var(--muted); font-size: 8.5px; font-weight: 780; letter-spacing: .05em; text-transform: uppercase; }
.bci-braid-rail-name.is-effective { top: 3px; left: 0; color: color-mix(in srgb, var(--bci-filed) 85%, var(--text)); }
.bci-braid-rail-name.is-known { top: 68px; left: 0; color: color-mix(in srgb, var(--bci-stamp) 85%, var(--text)); }
.bci-braid-rec { position: absolute; top: 8px; height: 68px; padding: 0; border: 1px solid transparent; border-radius: 4px; background: transparent; }
.bci-braid-rec:hover, .bci-braid-rec:focus-visible { border-color: color-mix(in srgb, var(--bci-stamp) 45%, transparent); background: color-mix(in srgb, var(--bci-stamp) 9%, transparent); }
.bci-braid-eff { position: absolute; top: 5px; width: 9px; height: 9px; margin-left: -4px; background: var(--bci-filed); content: ''; transform: rotate(45deg); }
.bci-braid-stem { position: absolute; top: 9px; width: 1px; background: color-mix(in srgb, var(--text) 26%, transparent); }
.bci-braid-lag { position: absolute; height: 2px; min-width: 2px; background: linear-gradient(90deg, var(--bci-filed), var(--bci-stamp)); }
.bci-braid-lag.is-reverse { background: linear-gradient(270deg, var(--bci-filed), var(--bci-stamp)); }
.bci-braid-known { position: absolute; width: 8px; height: 8px; margin-left: -4px; border-radius: 1px; background: var(--bci-stamp); }
.bci-braid-branch { position: absolute; width: 1px; height: 11px; background: var(--bci-redline); }
.bci-braid-corr { position: absolute; width: 7px; height: 7px; margin-left: -3px; border: 1.5px solid var(--bci-redline); border-radius: 50%; background: var(--panel); }
.bci-braid-scale { display: flex; justify-content: space-between; margin-top: 2px; padding-top: 5px; border-top: 1px dashed var(--bci-line); color: var(--muted); font-family: var(--font-mono); font-size: 8.5px; font-variant-numeric: tabular-nums; gap: 8px; }
.bci-braid-readout { margin: 7px 0 0; min-height: 15px; color: var(--text); font-size: 10.5px; line-height: 1.4; }
.bci-braid-readout:empty::before { color: var(--muted); content: attr(data-rest); }
.bci-braid-foot { margin: 6px 0 0; color: var(--muted); font-size: 10.5px; line-height: 1.45; }
.bci-braid-list { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

/* Active query as removable chips, not a dense form echo. */
.bci-chips { display: flex; flex-wrap: wrap; margin-top: 12px; gap: 6px; }
.bci-chips[hidden] { display: none !important; }
.bci-chip { display: inline-flex; align-items: center; padding: 4px 6px 4px 8px; border: 1px solid var(--bci-line); border-radius: 7px; color: var(--text); background: color-mix(in srgb, var(--panel) 62%, transparent); font-size: 10px; font-weight: 640; gap: 7px; }
.bci-chip b { color: var(--muted); font-family: var(--font-mono); font-size: 8.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; }
.bci-chip-drop { width: 15px; height: 15px; padding: 0; border: 0; border-radius: 4px; color: var(--muted); background: color-mix(in srgb, var(--text) 8%, transparent); font-size: 12px; line-height: 1; }
.bci-chip-drop:hover { color: var(--bci-redline); background: color-mix(in srgb, var(--bci-redline) 16%, transparent); }
.bci-chip-none { color: var(--muted); font-size: 10.5px; }

/* Facet rail — counts under the filters they belong to. */
.bci-facets[hidden], .bci-screen-controls[hidden], .bci-cohort[hidden] { display: none !important; }
.bci-facets { margin-top: 18px; padding-top: 15px; border-top: 1px solid var(--bci-line); }
.bci-facet-group + .bci-facet-group { margin-top: 13px; }
.bci-facet-group h3 { display: flex; justify-content: space-between; margin: 0 0 6px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; gap: 8px; }
.bci-facet-note { color: var(--muted); font-family: var(--font-mono); font-size: 8.5px; letter-spacing: 0; text-transform: none; }
.bci-facet { display: flex; align-items: center; width: 100%; min-height: 26px; padding: 3px 6px; border: 0; border-radius: 6px; color: var(--muted); background: transparent; font-size: 10.5px; gap: 8px; }
.bci-facet:hover { color: var(--text); background: color-mix(in srgb, var(--bci-stamp) 10%, transparent); }
.bci-facet.is-active { color: var(--text); background: color-mix(in srgb, var(--bci-stamp) 15%, transparent); box-shadow: inset 2px 0 0 var(--bci-stamp); }
.bci-facet-name { flex: 1; min-width: 0; overflow: hidden; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
.bci-facet-count { color: var(--bci-stamp-strong); font-family: var(--font-mono); font-size: 9.5px; font-variant-numeric: tabular-nums; font-weight: 700; }
.bci-facet-miss { margin: 7px 0 0; color: var(--muted); font-size: 10px; line-height: 1.45; }

/* Cohort intake — the user supplies the peer set; nothing is discovered. */
.bci-cohort { margin-top: 17px; }
.bci-cohort textarea { width: 100%; min-height: 112px; padding: 9px 11px; border: 1px solid var(--bci-line); border-radius: 10px; outline: 0; color: var(--text); background: color-mix(in srgb, var(--panel) 68%, transparent); font-family: var(--font-mono); font-size: 11px; letter-spacing: .02em; line-height: 1.6; resize: vertical; }
.bci-cohort textarea:focus { border-color: color-mix(in srgb, var(--bci-stamp) 70%, var(--bci-line)); }
.bci-cohort-actions { display: flex; align-items: center; margin-top: 9px; gap: 9px; }
.bci-cohort-run { min-height: 34px; padding: 0 13px; border: 1px solid color-mix(in srgb, var(--bci-stamp) 46%, var(--bci-line)); border-radius: 9px; color: var(--bci-stamp-strong); background: color-mix(in srgb, var(--bci-stamp) 12%, transparent); font-size: 10px; font-weight: 800; letter-spacing: .03em; }
.bci-cohort-run:hover { border-color: var(--bci-stamp); background: color-mix(in srgb, var(--bci-stamp) 20%, transparent); }
.bci-cohort-hint { color: var(--muted); font-size: 10px; line-height: 1.4; }

/* Peer matrix — stable identity column, per-cell provenance, and coverage
   that is visible as texture rather than as a colour the eye must decode. */
.bci-peer { position: relative; min-width: 0; overflow: auto; }
/* A frozen identity column only helps if the reader can tell there is more to
   the right, so the scroll edge is stated rather than implied. */
.bci-peer-more { margin: 6px 0 0; color: var(--muted); font-size: 10px; }
.bci-peer table { width: 100%; border-collapse: separate; border-spacing: 0; }
.bci-peer th, .bci-peer td { padding: 8px 10px; border-bottom: 1px solid var(--bci-line); font-size: 10.5px; text-align: left; vertical-align: top; }
.bci-peer thead th { position: sticky; top: 0; z-index: 3; color: var(--muted); background: var(--panel); font-size: 9px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; white-space: nowrap; }
.bci-peer .bci-peer-id { position: sticky; left: 0; z-index: 2; min-width: 168px; border-right: 1px solid var(--bci-line-strong); background: var(--panel); }
.bci-peer thead .bci-peer-id { z-index: 4; }
.bci-peer-nct { display: block; color: var(--bci-stamp-strong); font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; font-weight: 700; }
.bci-peer-name { display: -webkit-box; overflow: hidden; margin-top: 3px; color: var(--text); font-size: 10.5px; font-weight: 640; line-height: 1.34; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.bci-peer-val { display: block; color: var(--text); overflow-wrap: anywhere; }
.bci-peer-cell.is-partial .bci-peer-val { color: color-mix(in srgb, var(--bci-filed) 62%, var(--text)); border-bottom: 1px dashed var(--bci-filed); }
.bci-peer-cell.is-uncovered { background: repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in srgb, var(--text) 7%, transparent) 5px 6px); }
.bci-peer-cell.is-uncovered .bci-peer-val { color: var(--muted); font-style: italic; }
.bci-peer-src { display: block; margin-top: 5px; padding: 0; border: 0; max-width: 132px; overflow: hidden; color: var(--muted); background: transparent; font-family: var(--font-mono); font-size: 8.5px; letter-spacing: .02em; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
.bci-peer-src:hover { color: var(--bci-stamp-strong); text-decoration: underline; text-underline-offset: 2px; }
.bci-peer-cards { display: grid; gap: 9px; }
.bci-peer-card { padding: 12px; border: 1px solid var(--bci-line); border-radius: 12px; background: color-mix(in srgb, var(--panel) 58%, transparent); }
.bci-peer-card > header { padding-bottom: 8px; border-bottom: 1px solid var(--bci-line); }
.bci-peer-row { display: grid; grid-template-columns: 96px minmax(0, 1fr); align-items: baseline; padding: 7px 0; border-bottom: 1px solid var(--bci-rule); gap: 10px; }
.bci-peer-row:last-child { border-bottom: 0; }
.bci-peer-row > dt { color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.bci-peer-row > dd { margin: 0; min-width: 0; font-size: 10.5px; }
.bci-peer-legend { display: flex; flex-wrap: wrap; margin-top: 10px; color: var(--muted); font-size: 10px; gap: 6px 14px; }
.bci-peer-legend span { display: inline-flex; align-items: center; gap: 6px; }
.bci-peer-legend i { width: 10px; height: 10px; border: 1px solid var(--bci-line-strong); border-radius: 2px; }
.bci-peer-legend i.is-partial { border-color: var(--bci-filed); border-style: dashed; }
.bci-peer-legend i.is-uncovered { background: repeating-linear-gradient(135deg, transparent 0 3px, color-mix(in srgb, var(--text) 22%, transparent) 3px 4px); }

/* A comparison is read whole: the peer surface drops the fixed workspace height
   so rows are never cut mid-record inside a scroll box. */
[data-surface="peers"] .bci-information { height: auto; min-height: 0; }
[data-surface="peers"] .bci-filter-pane, [data-surface="peers"] .bci-queue-pane, [data-surface="peers"] .bci-inspector-pane { height: auto; overflow: visible; }
[data-surface="peers"] .bci-queue { overflow: visible; padding-right: 0; }

/* Change tape row — exact before/after, the source path, both clocks. */
.bci-tape-card { min-height: 132px; align-items: stretch; }
.bci-tape-card .bci-trial-main { display: flex; flex-direction: column; }
.bci-tape-card .bci-trial-topline { flex-wrap: wrap; }
.bci-tape-delta { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border: 1px solid var(--bci-line); border-left: 2px solid var(--bci-redline); border-radius: 0 9px 9px 0; color: var(--muted); background: color-mix(in srgb, var(--panel) 56%, transparent); font-family: var(--font-mono); font-size: 9px; line-height: 1.36; gap: 7px; }
.bci-tape-delta > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bci-tape-delta > b { color: var(--bci-redline); font-family: var(--font-ui); font-size: 12px; font-weight: 760; }
.bci-tape-exact { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border: 1px solid var(--bci-line); border-left: 2px solid var(--bci-redline); border-radius: 0 9px 9px 0; background: color-mix(in srgb, var(--panel) 58%, transparent); gap: 7px; }
.bci-tape-exact > b { color: var(--bci-redline); font-size: 12px; }
.bci-tape-value { display: grid; min-width: 0; gap: 2px; }
.bci-tape-value small { color: var(--muted); font-family: var(--font-ui); font-size: 8px; font-weight: 800; letter-spacing: .055em; text-transform: uppercase; }
.bci-tape-value code { display: block; min-width: 0; overflow: hidden; color: var(--text); font-family: var(--font-mono); font-size: 9px; line-height: 1.4; text-overflow: ellipsis; white-space: nowrap; }
.bci-tape-value.is-missing code, .bci-tape-value.is-unavailable code { color: var(--muted); font-family: var(--font-ui); font-style: italic; }
.bci-tape-value em { color: var(--muted); font-family: var(--font-ui); font-size: 8px; font-style: normal; }
.bci-tape-exact.is-detail { margin: 10px 0 0; padding: 11px; }
.bci-endpoint .bci-tape-exact { display: grid; }
.bci-endpoint .bci-tape-value { display: grid; margin-top: 0; color: inherit; font-family: inherit; }
.bci-tape-exact.is-detail .bci-tape-value code { overflow: visible; overflow-wrap: anywhere; text-overflow: clip; white-space: pre-wrap; }
.bci-tape-disclosure { margin-top: 10px; padding-top: 9px; border-top: 1px solid var(--bci-line); }
.bci-tape-disclosure summary { width: fit-content; cursor: pointer; color: var(--bci-cyan-strong); font-size: 10px; font-weight: 760; }
.bci-tape-disclosure p { display: grid; grid-template-columns: 104px minmax(0, 1fr); margin: 8px 0 0; color: var(--muted); font-size: 9px; gap: 8px; }
.bci-tape-disclosure p > span { margin: 0; color: var(--muted); font-family: var(--font-ui); font-size: 8px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; }
.bci-tape-disclosure code, .bci-tape-disclosure strong { min-width: 0; overflow-wrap: anywhere; color: var(--text); font-family: var(--font-mono); font-size: 9px; font-weight: 650; }
.bci-tape-path { display: block; margin-top: 7px; overflow: hidden; color: color-mix(in srgb, var(--bci-stamp) 72%, var(--text)); font-family: var(--font-mono); font-size: 9px; letter-spacing: .01em; text-overflow: ellipsis; white-space: nowrap; }
.bci-tape-review { display: inline-flex; padding: 2px 6px; border: 1px dashed color-mix(in srgb, var(--bci-filed) 55%, var(--bci-line)); border-radius: 99px; color: var(--bci-filed-strong); font-size: 8.5px; font-weight: 800; letter-spacing: .04em; line-height: 1.3; text-transform: uppercase; }
.bci-tape-clocks { display: grid; align-content: start; justify-items: end; min-width: 116px; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-tape-clocks b { color: color-mix(in srgb, var(--bci-filed) 70%, var(--text)); font-weight: 700; }
.bci-tape-clocks i { color: color-mix(in srgb, var(--bci-stamp) 74%, var(--text)); font-style: normal; font-weight: 700; }

/* Screen row — the row carries what differs; constants sit in the footer. */
.bci-screen-card { min-height: 92px; }
.bci-cues { display: flex; flex-wrap: wrap; margin-top: 7px; color: var(--muted); font-size: 9.5px; gap: 3px 9px; }
.bci-cues span { display: inline-flex; align-items: center; }
.bci-cues span + span::before { width: 3px; height: 3px; margin-right: 8px; border-radius: 50%; background: var(--bci-line-strong); content: ''; }
.bci-cues .is-partial { color: color-mix(in srgb, var(--bci-filed) 68%, var(--text)); }
.bci-cues .is-missing { color: var(--muted); font-style: italic; }
.bci-interval { display: grid; justify-items: end; min-width: 118px; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-interval strong { color: var(--text); font-family: var(--font-ui); font-size: 12.5px; font-weight: 780; letter-spacing: -.02em; }

/* One footer, once — every constant the rows would otherwise repeat. */
.bci-panel-foot { margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--bci-line); color: var(--muted); font-size: 10.5px; line-height: 1.5; }
.bci-panel-foot[hidden] { display: none !important; }
.bci-panel-foot b { color: color-mix(in srgb, var(--text) 78%, var(--muted)); font-weight: 700; }

.bci-scrim { position: fixed; z-index: 100010; inset: 0; background: rgba(5, 9, 18, .42); backdrop-filter: blur(2px); }

@media (max-width: 1120px) {
  .bci-information { grid-template-columns: 230px minmax(0, 1fr); backdrop-filter: none; -webkit-backdrop-filter: none; }.bci-inspector-pane { position: fixed; z-index: 100020; top: 0; right: 0; bottom: 0; width: min(440px, 88vw); border-left: 1px solid var(--bci-line); background: var(--panel); box-shadow: -28px 0 70px -40px rgba(0,0,0,.8); transform: translateX(105%); transition: transform .24s ease, visibility 0s linear .24s; visibility: hidden; }.bci-inspector-pane.is-open { transform: translateX(0); transition-delay: 0s; visibility: visible; }.bci-queue-pane { border-right: 0; }.bci-inspector-close { display: block; } body.bci-inspector-open #mmb-launch { opacity: 0 !important; pointer-events: none !important; visibility: hidden !important; }
}
@media (min-width: 1121px) { .bci-inspector-close,.bci-scrim { display: none !important; } }
@media (max-width: 760px) {
  body.bci-page { padding: 12px; }.bci-workspace { margin-top: 10px; }.bci-hero { align-items: flex-start; flex-direction: column; padding: 20px 3px 19px; gap: 16px; }.bci-run-status { width: 100%; min-width: 0; }.bci-information { display: block; height: auto; min-height: 0; overflow: visible; background: transparent; border: 0; box-shadow: none; }.bci-filter-pane, .bci-queue-pane { height: auto; border: 1px solid var(--bci-line); border-radius: var(--bci-radius); background: var(--bci-glass); box-shadow: var(--bci-shadow); backdrop-filter: saturate(155%) blur(21px); -webkit-backdrop-filter: saturate(155%) blur(21px); }.bci-filter-pane { display: grid; grid-template-columns: 1fr 1fr; margin-bottom: 12px; padding: 15px; border-right: 1px solid var(--bci-line); overflow: visible; gap: 0 11px; }.bci-filter-pane .bci-pane-head, .bci-filter-pane .bci-mode-control, .bci-filter-pane .bci-window-control, .bci-filter-pane .bci-search, .bci-filter-pane .bci-source-note { grid-column: 1 / -1; }.bci-filter-pane .bci-control { min-width: 0; }.bci-pane-head { padding-bottom: 12px; }.bci-window-control,.bci-search,.bci-control { margin-top: 12px; }.bci-filter-actions { margin-top: 15px; }.bci-source-note { margin-top: 17px; padding-top: 12px; }.bci-queue-pane { display: block; padding: 15px; border-right: 1px solid var(--bci-line); }.bci-queue-head { min-height: 74px; }.bci-queue { min-height: 350px; overflow: visible; padding-right: 0; }.bci-inspector-pane { top: auto; width: 100vw; max-height: calc(100dvh - 24px); border-width: 1px 0 0; border-radius: 19px 19px 0 0; transform: translateY(calc(100% + 16px)); }.bci-inspector-pane.is-open { transform: translateY(0); }.bci-inspector-pane::before { display: block; width: 40px; height: 4px; margin: 8px auto -2px; border-radius: 99px; background: var(--bci-line-strong); content: ''; }.bci-inspector-head { min-height: 80px; padding: 15px 16px 13px; }.bci-inspector-body { padding: 16px 16px 28px; }.bci-trial { min-height: 104px; padding: 12px; }.bci-trial-date { max-width: 112px; }.bci-change-card { min-height: 133px; }.bci-change-receipt { min-width: 92px; }.bci-asof { font-size: 8px; }
  /* A fixed global chat launcher intercepted the lower filter controls on
     phone-sized monitors. This page owns an inline, keyboard-accessible entry
     instead, so no fixed element can cover a form target while users scroll. */
  .bci-prospective-card { min-height: 148px; }
  .bci-observation-receipt { min-width: 92px; }
  body.bci-page #mmb-launch { display: none !important; }
  .bci-brain-launch { display: inline-flex; align-items: center; justify-content: center; min-height: 38px; width: 100%; margin-top: 13px; border: 1px solid color-mix(in srgb, #8b5cf6 42%, var(--bci-line)); border-radius: 10px; color: color-mix(in srgb, #a78bfa 82%, var(--text)); background: color-mix(in srgb, #8b5cf6 10%, transparent); font-size: 10px; font-weight: 800; letter-spacing: .025em; gap: 6px; }
  .bci-brain-launch:hover { border-color: color-mix(in srgb, #a78bfa 70%, var(--bci-line)); background: color-mix(in srgb, #8b5cf6 16%, transparent); }
}
@media (max-width: 450px) { .bci-filter-pane { display: block; }.bci-filter-pane .bci-control { margin-top: 12px; }.bci-hero h1 { font-size: 33px; }.bci-refresh { padding-right: 7px; padding-left: 7px; }.bci-trial { grid-template-columns: minmax(0,1fr); gap: 8px; }.bci-trial-date,.bci-change-receipt,.bci-observation-receipt { justify-items: start; max-width: none; text-align: left; }.bci-trial-date strong { display: inline; margin-right: 5px; }.bci-detail-grid,.bci-evidence-strip { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { .bci-refresh,.bci-trial,.bci-window,.bci-mode,.bci-load-more,.bci-inspector-pane { transition: none; }.bci-skeleton span,.bci-refresh.is-spinning svg,.bci-loading-detail::before { animation: none !important; } }

/* The braid holds no meaning in motion: with animation off every mark, rail,
   lag bar, and readout stays exactly where it is and says the same thing. */
@media (prefers-reduced-motion: reduce) {
  .bci-braid-rec, .bci-facet, .bci-chip-drop, .bci-cohort-run, .bci-peer-src { transition: none !important; }
}

@media (max-width: 1120px) {
  .bci-peer .bci-peer-id { min-width: 148px; }
}
@media (max-width: 760px) {
  .bci-filter-pane .bci-facets, .bci-filter-pane .bci-cohort, .bci-filter-pane .bci-screen-controls { grid-column: 1 / -1; }
  .bci-decision { align-items: flex-start; flex-direction: column; gap: 8px; }
  .bci-decision-why { font-size: 14px; }
  .bci-braid-plot { height: 94px; }
  .bci-braid-scale span:nth-child(even) { display: none; }
  .bci-tape-card { min-height: 150px; }
  .bci-tape-clocks { min-width: 96px; }
  .bci-screen-card { min-height: 104px; }
}
@media (max-width: 450px) {
  .bci-interval, .bci-tape-clocks { justify-items: start; min-width: 0; text-align: left; }
  .bci-tape-exact { grid-template-columns: minmax(0, 1fr); }
  .bci-tape-exact > b { justify-self: start; transform: rotate(90deg); }
  .bci-tape-disclosure p { grid-template-columns: minmax(0, 1fr); gap: 2px; }
  .bci-peer-row { grid-template-columns: minmax(0, 1fr); gap: 2px; }
  .bci-braid-rail-name { font-size: 8px; }
}

rules.new:
/* BioCatalyst Intelligence — current-source clinical trial workbench. */
* { box-sizing: border-box; }

/* Palette derived from the subject: a versioned regulatory record.
   stamp  — methyl-violet registrar ink; the KNOWN-AT clock and the page accent
   filed  — kraft/ochre folder stock; the EFFECTIVE clock (when a fact was true)
   redline— the correction mark on a filed page; never sentiment, never direction
   onion  — onionskin carbon copy; the first-seen observation ledger
   The ground is ruled ledger paper rather than an ambient glow. */
:root {
  --bci-stamp: #8f7bff;
  --bci-stamp-strong: #b9adff;
  --bci-filed: #e3a14a;
  --bci-filed-strong: #f3c489;
  --bci-redline: #ef6a52;
  --bci-redline-strong: #ff9683;
  --bci-observe: #9db06a;
  --bci-observe-strong: #c4d296;
  /* Legacy alias: the earlier accent name now resolves to the stamp ink so the
     whole surface migrates in one place instead of drifting two accents. */
  --bci-cyan: var(--bci-stamp);
  --bci-cyan-strong: var(--bci-stamp-strong);
  --bci-glass: color-mix(in srgb, var(--panel) 88%, transparent);
  --bci-soft: color-mix(in srgb, var(--panel2) 72%, transparent);
  --bci-line: color-mix(in srgb, var(--text) 12%, transparent);
  --bci-line-strong: color-mix(in srgb, var(--text) 22%, transparent);
  --bci-rule: color-mix(in srgb, var(--text) 6%, transparent);
  --bci-shadow: 0 24px 66px -42px rgba(0, 0, 0, .82), inset 0 1px 0 rgba(255,255,255,.05);
  --bci-radius: 18px;
  --bci-ruled: repeating-linear-gradient(180deg, var(--bci-rule) 0 1px, transparent 1px 29px);
}

/* Light is composed, not inverted: white record cards float on a deeper desk
   tone, the stamp ink deepens so it holds on paper, and the ochre darkens to
   an ink rather than a highlighter smear. */
html[data-theme="light"] {
  --bci-stamp: #5334c9;
  --bci-stamp-strong: #3d1fa6;
  --bci-filed: #9a640d;
  --bci-filed-strong: #7a4d05;
  --bci-redline: #b93a20;
  --bci-redline-strong: #94240d;
  --bci-observe: #5f7429;
  --bci-observe-strong: #46561a;
  --bci-glass: var(--panel);
  --bci-soft: color-mix(in srgb, var(--panel2) 82%, var(--panel));
  --bci-line: color-mix(in srgb, #1b2430 13%, transparent);
  --bci-line-strong: color-mix(in srgb, #1b2430 24%, transparent);
  --bci-rule: color-mix(in srgb, #1b2430 5%, transparent);
  --bci-shadow: 0 18px 38px -28px rgba(20, 38, 62, .38), 0 1px 0 rgba(20, 38, 62, .05);
}

body.bci-page {
  min-width: 320px;
  margin: 0;
  padding: 18px;
  overflow-x: hidden;
  color: var(--text);
  background: var(--bci-ruled), var(--bg);
  font: 400 14px/1.52 var(--font-ui);
  -webkit-font-smoothing: antialiased;
}
html[data-theme="light"] body.bci-page { background: var(--bci-ruled), #e8ebf1; }

.bci-page :is(button, input, select) { font: inherit; }
.bci-page button { color: inherit; }
.bci-page button, .bci-page select { cursor: pointer; }
.bci-page [hidden] { display: none !important; }
.bci-page :focus-visible { outline: 2px solid var(--bci-cyan); outline-offset: 3px; }
.bci-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }

.bci-workspace { width: min(100%, 1540px); margin: 18px auto 72px; }

.bci-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 26px;
  padding: 27px 4px 24px;
}
.bci-eyebrow, .bci-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 6px;
  color: var(--bci-cyan);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .115em;
  text-transform: uppercase;
}
.bci-pulse { width: 7px; height: 7px; border: 1px solid var(--bci-cyan); border-radius: 50%; box-shadow: 0 0 0 4px color-mix(in srgb, var(--bci-cyan) 12%, transparent); }
.bci-hero h1 { max-width: 640px; margin: 0; font-size: clamp(30px, 4vw, 49px); line-height: .99; letter-spacing: -.055em; }
.bci-deck { max-width: 580px; margin: 11px 0 0; color: var(--muted); font-size: 15px; }

.bci-run-status {
  display: flex;
  align-items: center;
  min-width: 288px;
  padding: 10px 10px 10px 13px;
  border: 1px solid var(--bci-line);
  border-radius: 14px;
  background: var(--bci-glass);
  box-shadow: var(--bci-shadow);
  backdrop-filter: saturate(150%) blur(18px);
  -webkit-backdrop-filter: saturate(150%) blur(18px);
  gap: 9px;
}
.bci-status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--bci-cyan); box-shadow: 0 0 0 4px color-mix(in srgb, var(--bci-cyan) 12%, transparent); }
.bci-run-status.is-stale .bci-status-dot { background: var(--warn); box-shadow: 0 0 0 4px color-mix(in srgb, var(--warn) 13%, transparent); }
.bci-run-status.is-unavailable .bci-status-dot { background: var(--act); box-shadow: 0 0 0 4px color-mix(in srgb, var(--act) 13%, transparent); }
.bci-status-label, .bci-status-detail { display: block; }
.bci-status-label { color: var(--text); font-size: 11px; font-weight: 750; line-height: 1.2; }
.bci-status-detail { margin-top: 2px; color: var(--muted); font-size: 10px; }
.bci-refresh {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  margin-left: auto;
  padding: 7px 9px;
  border: 1px solid var(--bci-line);
  border-radius: 9px;
  color: var(--muted);
  background: color-mix(in srgb, var(--panel2) 52%, transparent);
  font-size: 10px;
  font-weight: 750;
  gap: 5px;
  transition: border-color .18s ease, color .18s ease, transform .18s ease, background .18s ease;
}
.bci-refresh svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.75; }
.bci-refresh:hover { border-color: color-mix(in srgb, var(--bci-cyan) 46%, var(--bci-line)); color: var(--bci-cyan); transform: translateY(-1px); }
.bci-refresh.is-spinning svg { animation: bci-spin .8s linear infinite; }
@keyframes bci-spin { to { transform: rotate(360deg); } }

.bci-information {
  display: grid;
  grid-template-columns: minmax(228px, .72fr) minmax(410px, 1.55fr) minmax(300px, 1fr);
  align-items: stretch;
  height: min(760px, calc(100vh - 180px));
  min-height: 620px;
  border: 1px solid var(--bci-line);
  border-radius: var(--bci-radius);
  background: var(--bci-glass);
  box-shadow: var(--bci-shadow);
  overflow: hidden;
  backdrop-filter: saturate(155%) blur(21px);
  -webkit-backdrop-filter: saturate(155%) blur(21px);
}
.bci-filter-pane, .bci-queue-pane, .bci-inspector-pane { min-width: 0; min-height: 0; height: 100%; overflow: hidden; }
.bci-filter-pane { overflow: auto; padding: 20px; border-right: 1px solid var(--bci-line); background: color-mix(in srgb, var(--panel2) 30%, transparent); }
.bci-queue-pane { display: flex; flex-direction: column; padding: 20px; border-right: 1px solid var(--bci-line); }
.bci-inspector-pane { display: flex; flex-direction: column; background: color-mix(in srgb, var(--panel2) 25%, transparent); }
.bci-pane-head, .bci-queue-head, .bci-inspector-head { border-bottom: 1px solid var(--bci-line); }
.bci-pane-head { padding-bottom: 17px; }
.bci-pane-head h2, .bci-queue-head h2, .bci-inspector-head h2 { margin: 0; color: var(--text); font-size: 17px; line-height: 1.16; letter-spacing: -.025em; }
/* Five surfaces read as a filed index, not as five squeezed tabs: one line
   each, a hairline rule between, and the active surface carries the stamp rail. */
.bci-mode-control { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 17px; overflow: hidden; border: 1px solid var(--bci-line); border-radius: 11px; background: color-mix(in srgb, var(--panel) 68%, transparent); box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 7%, transparent); }
.bci-mode { display: flex; align-items: center; min-height: 34px; padding: 0 10px 0 12px; border: 0; border-bottom: 1px solid var(--bci-line); color: var(--muted); background: transparent; font-size: 10.5px; font-weight: 780; letter-spacing: .005em; text-align: left; gap: 8px; transition: color .18s ease, background .18s ease, box-shadow .18s ease, padding .18s ease; }
.bci-mode::before { flex: none; width: 5px; height: 5px; border: 1px solid currentColor; border-radius: 1px; opacity: .55; content: ''; transform: rotate(45deg); }
.bci-mode:last-child { border-bottom: 0; }
.bci-mode:hover { color: var(--bci-stamp); background: color-mix(in srgb, var(--bci-stamp) 7%, transparent); }
.bci-mode.is-active { padding-left: 14px; color: var(--text); background: linear-gradient(90deg, var(--panel2), transparent 78%); box-shadow: none; }
.bci-mode.is-active::before { background: var(--bci-stamp); border-color: var(--bci-stamp); opacity: 1; }
.bci-mode-prospective:hover { color: var(--bci-observe); background: color-mix(in srgb, var(--bci-observe) 8%, transparent); }
.bci-mode-prospective.is-active { background: linear-gradient(90deg, var(--panel2), transparent 78%); box-shadow: none; }
.bci-mode-prospective.is-active::before { background: var(--bci-observe); border-color: var(--bci-observe); }
.bci-control-label { display: block; margin-bottom: 6px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.bci-search, .bci-control { display: block; margin-top: 17px; }
.bci-window-control { min-width: 0; margin: 17px 0 0; padding: 0; border: 0; }
.bci-window-options { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); overflow: hidden; border: 1px solid var(--bci-line); border-radius: 11px; background: color-mix(in srgb, var(--panel) 68%, transparent); box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 7%, transparent); }
.bci-window { min-height: 34px; border: 0; border-right: 1px solid var(--bci-line); color: var(--muted); background: transparent; font-size: 10px; font-weight: 780; transition: color .18s ease, background .18s ease; }
.bci-window:last-child { border-right: 0; }
.bci-window:hover { color: var(--bci-cyan); background: color-mix(in srgb, var(--bci-cyan) 7%, transparent); }
.bci-window.is-active { color: var(--text); background: linear-gradient(145deg, var(--surface-info-subtle,var(--panel2,var(--card))), var(--surface-info-subtle,var(--panel2,var(--card)))); box-shadow: none; }
.bci-search-field { position: relative; display: block; }
.bci-search-field svg { position: absolute; top: 50%; left: 11px; width: 15px; height: 15px; fill: none; stroke: var(--muted); stroke-linecap: round; stroke-width: 1.7; transform: translateY(-50%); pointer-events: none; }
.bci-search input, .bci-control select {
  width: 100%;
  min-height: 40px;
  border: 1px solid var(--bci-line);
  border-radius: 10px;
  outline: 0;
  color: var(--text);
  background: color-mix(in srgb, var(--panel) 68%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 8%, transparent);
}
.bci-search input { padding: 9px 11px 9px 34px; }
.bci-control select { padding: 8px 10px; }
.bci-search input::placeholder { color: var(--muted); opacity: .85; }
.bci-search input:focus, .bci-control select:focus { border-color: color-mix(in srgb, var(--bci-cyan) 70%, var(--bci-line)); }
.bci-filter-actions { margin-top: 20px; }
.bci-clear { border: 0; padding: 3px 0; color: var(--bci-cyan); background: transparent; font-size: 11px; font-weight: 750; }
.bci-clear:hover { color: var(--bci-cyan-strong); text-decoration: underline; text-underline-offset: 3px; }
.bci-brain-launch { display: none; }
.bci-source-note { display: flex; margin-top: 29px; padding-top: 15px; border-top: 1px solid var(--bci-line); color: var(--muted); font-size: 11px; line-height: 1.52; gap: 9px; }
.bci-source-note p { margin: 0; }
.bci-source-mark { flex: none; color: var(--bci-cyan); font-size: 19px; line-height: .9; }

.bci-queue-head { display: flex; align-items: flex-start; justify-content: space-between; min-height: 86px; padding: 1px 1px 17px; gap: 12px; }
.bci-queue-subtitle { margin: 6px 0 0; color: var(--muted); font-size: 11px; }
.bci-asof { max-width: 145px; padding: 5px 7px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 22%, transparent); border-radius: 999px; color: var(--bci-cyan); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.25; text-align: right; }
.bci-asof:empty { display: none; }
.bci-state-notice { margin: 14px 0 0; padding: 10px 12px; border: 1px solid color-mix(in srgb, var(--warn) 29%, var(--bci-line)); border-radius: 11px; color: var(--muted); background: color-mix(in srgb, var(--warn) 7%, transparent); font-size: 11px; line-height: 1.4; }
.bci-state-notice.is-error { border-color: color-mix(in srgb, var(--act) 33%, var(--bci-line)); background: color-mix(in srgb, var(--act) 7%, transparent); }
.bci-state-notice.is-locked { border-color: color-mix(in srgb, #8b5cf6 34%, var(--bci-line)); background: color-mix(in srgb, #8b5cf6 8%, transparent); }
.bci-state-notice.is-restart { border-color: color-mix(in srgb, var(--bci-cyan) 36%, var(--bci-line)); background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); }
.bci-queue { display: flex; flex: 1; flex-direction: column; min-height: 0; margin-top: 13px; overflow: auto; padding-right: 4px; gap: 7px; }
.bci-queue-footer { padding: 12px 1px 0; border-top: 1px solid var(--bci-line); }
.bci-load-more { display: flex; align-items: center; justify-content: center; width: 100%; min-height: 38px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 34%, var(--bci-line)); border-radius: 10px; color: var(--bci-cyan); background: color-mix(in srgb, var(--bci-cyan) 6%, transparent); font-size: 10px; font-weight: 800; letter-spacing: .025em; transition: border-color .18s ease, color .18s ease, background .18s ease, transform .18s ease; }
.bci-load-more:hover:not(:disabled) { border-color: var(--bci-cyan); color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 12%, transparent); transform: translateY(-1px); }
.bci-load-more:disabled { cursor: wait; opacity: .62; }
.bci-trial {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  width: 100%;
  min-height: 96px;
  padding: 14px;
  border: 1px solid transparent;
  border-radius: 13px;
  color: inherit;
  background: transparent;
  text-align: left;
  gap: 12px;
  transition: background .18s ease, border-color .18s ease, transform .18s ease, box-shadow .18s ease;
}
.bci-trial:hover, .bci-trial.is-selected { border-color: color-mix(in srgb, var(--bci-cyan) 30%, var(--bci-line)); background: color-mix(in srgb, var(--bci-cyan) 7%, var(--bci-soft)); box-shadow: 0 10px 28px -25px color-mix(in srgb, var(--bci-cyan) 80%, transparent); }
.bci-trial:hover { transform: translateY(-1px); }
.bci-trial-main { min-width: 0; }
.bci-trial-topline { display: flex; align-items: center; gap: 7px; }
.bci-trial-id { color: var(--bci-cyan); font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; font-weight: 750; letter-spacing: .025em; }
.bci-registry-kind { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 24%, var(--bci-line)); border-radius: 99px; color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 7%, transparent); font-size: 8px; font-weight: 800; letter-spacing: .035em; line-height: 1.2; text-overflow: ellipsis; text-transform: uppercase; white-space: nowrap; }
.bci-status-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid var(--bci-line); border-radius: 99px; color: var(--muted); font-size: 9px; font-weight: 750; line-height: 1.2; text-overflow: ellipsis; white-space: nowrap; }
.bci-trial-title { display: -webkit-box; margin: 7px 0 0; overflow: hidden; color: var(--text); font-size: 12px; font-weight: 720; line-height: 1.34; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.bci-trial-meta { display: flex; flex-wrap: wrap; margin-top: 7px; color: var(--muted); font-size: 10px; gap: 4px 10px; }
.bci-trial-meta span { display: inline-flex; align-items: center; }
.bci-trial-meta span + span::before { width: 3px; height: 3px; margin-right: 9px; border-radius: 50%; background: var(--bci-line-strong); content: ''; }
.bci-trial-date { display: grid; justify-items: end; max-width: 124px; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-trial-date strong { display: block; color: var(--text); font-family: var(--font-ui); font-size: 13px; font-weight: 780; letter-spacing: -.02em; }
.bci-date-type { display: inline-flex; width: fit-content; padding: 3px 6px; border: 1px solid var(--bci-line); border-radius: 99px; color: var(--muted); background: color-mix(in srgb, var(--panel2) 55%, transparent); font-family: var(--font-ui); font-size: 8px; font-weight: 850; letter-spacing: .075em; line-height: 1; }
.bci-date-type.is-actual { border-color: color-mix(in srgb, var(--bci-cyan) 34%, var(--bci-line)); color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); }
.bci-date-type.is-estimated { border-color: color-mix(in srgb, var(--warn) 34%, var(--bci-line)); color: color-mix(in srgb, var(--warn) 80%, var(--text)); background: color-mix(in srgb, var(--warn) 8%, transparent); }
.bci-change-card { min-height: 126px; align-items: stretch; }
.bci-change-card .bci-trial-main { display: flex; flex-direction: column; }
.bci-change-card .bci-trial-topline { flex-wrap: wrap; }
.bci-change-card .bci-registry-kind { border-color: color-mix(in srgb, #9c7cff 35%, var(--bci-line)); color: color-mix(in srgb, #b6a2ff 82%, var(--text)); background: color-mix(in srgb, #8b5cf6 10%, transparent); }
.bci-change-preview { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border: 1px solid color-mix(in srgb, var(--bci-line) 86%, transparent); border-radius: 9px; color: var(--muted); background: color-mix(in srgb, var(--panel) 54%, transparent); font-family: var(--font-mono); font-size: 9px; line-height: 1.36; gap: 7px; }
.bci-change-preview > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bci-change-preview > b { color: var(--bci-cyan); font-family: var(--font-ui); font-size: 12px; font-weight: 760; }
.bci-change-receipt { display: grid; align-content: space-between; justify-items: end; min-width: 104px; padding: 1px 0; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 8px; }
.bci-change-receipt strong { color: var(--text); font-family: var(--font-ui); font-size: 12px; font-weight: 780; letter-spacing: -.02em; }
.bci-change-version { display: inline-flex; width: fit-content; padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 24%, var(--bci-line)); border-radius: 999px; color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 7%, transparent); font-family: var(--font-ui); font-size: 8px; font-weight: 850; letter-spacing: .06em; line-height: 1; }
.bci-prospective-card { min-height: 147px; align-items: stretch; }
.bci-prospective-card .bci-trial-main { display: flex; flex-direction: column; }
.bci-prospective-card .bci-trial-topline { flex-wrap: wrap; }
.bci-prospective-card:hover, .bci-prospective-card.is-selected { border-color: color-mix(in srgb, var(--bci-observe) 48%, var(--bci-line)); background: color-mix(in srgb, var(--bci-observe) 7%, var(--bci-soft)); box-shadow: 0 10px 28px -25px color-mix(in srgb, var(--bci-observe) 90%, transparent); }
.bci-observation-kind { display: inline-flex; width: fit-content; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--bci-observe) 45%, var(--bci-line)); border-radius: 99px; color: var(--bci-observe-strong); background: color-mix(in srgb, var(--bci-observe) 10%, transparent); font-family: var(--font-ui); font-size: 8px; font-weight: 830; letter-spacing: .045em; line-height: 1.2; text-overflow: ellipsis; text-transform: uppercase; white-space: nowrap; }
.bci-observation-preview { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border: 1px solid color-mix(in srgb, var(--bci-observe) 22%, var(--bci-line)); border-radius: 9px; color: var(--muted); background: linear-gradient(145deg, color-mix(in srgb, var(--bci-observe) 6%, var(--panel)), color-mix(in srgb, var(--panel) 54%, transparent)); font-family: var(--font-mono); font-size: 9px; line-height: 1.36; gap: 7px; }
.bci-observation-preview > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bci-observation-preview > b { color: var(--bci-observe); font-family: var(--font-ui); font-size: 12px; font-weight: 760; }
.bci-observation-preview.is-omitted { display: block; border-style: dashed; color: var(--muted); font-family: var(--font-ui); }
.bci-observation-preview.is-omitted > span { display: block; overflow: visible; text-overflow: clip; white-space: normal; }
.bci-observation-receipt { display: grid; align-content: space-between; justify-items: end; min-width: 118px; padding: 1px 0; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-observation-receipt strong { color: var(--text); font-family: var(--font-ui); font-size: 12px; font-weight: 780; letter-spacing: -.02em; }

/* Catalyst Radar — Trial Milestones (BioCatalyst P1-1). */
.bci-radar-card { align-items: stretch; flex-shrink: 0; }
.bci-radar-card .bci-trial-topline { flex-wrap: wrap; }
.bci-radar-card .bci-trial-topline > * { flex-shrink: 0; }
.bci-radar-group-title { margin: 18px 0 8px; padding: 0 2px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }
.bci-radar-group-title:first-child { margin-top: 2px; }
.bci-phase-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid var(--bci-line); border-radius: 99px; color: var(--muted); font-size: 9px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.bci-issuer-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border-radius: 99px; font-size: 9px; font-weight: 750; text-overflow: ellipsis; white-space: nowrap; }
.bci-issuer-chip.is-resolved { border: 1px solid color-mix(in srgb, var(--bci-cyan) 30%, var(--bci-line)); color: var(--bci-cyan-strong); background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.bci-issuer-chip.is-unresolved { border: 1px dashed var(--bci-line-strong); color: var(--muted); background: transparent; }
.bci-issuer-chip.is-parent { border-style: dashed; border-color: color-mix(in srgb, var(--bci-filed) 40%, var(--bci-line)); color: var(--bci-filed-strong); background: color-mix(in srgb, var(--bci-filed) 8%, transparent); }
.bci-status-chip.is-paused { border-color: color-mix(in srgb, var(--warn) 34%, var(--bci-line)); color: color-mix(in srgb, var(--warn) 80%, var(--text)); background: color-mix(in srgb, var(--warn) 8%, transparent); }
.bci-status-chip.is-inactive { border-color: color-mix(in srgb, var(--bci-redline) 34%, var(--bci-line)); color: color-mix(in srgb, var(--bci-redline) 78%, var(--text)); background: color-mix(in srgb, var(--bci-redline) 8%, transparent); }
.bci-revision-chip { display: inline-flex; max-width: 100%; overflow: hidden; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--bci-filed) 40%, var(--bci-line)); border-radius: 99px; color: var(--bci-filed-strong); background: color-mix(in srgb, var(--bci-filed) 10%, transparent); font-size: 9px; font-weight: 750; text-overflow: ellipsis; white-space: nowrap; }
.bci-days-to-milestone { display: block; color: var(--muted); font-family: var(--font-ui); font-size: 9px; font-weight: 650; letter-spacing: 0; }
.bci-radar-revision-section .bci-endpoint p { margin-top: 4px; }

.bci-skeleton { min-height: 95px; padding: 16px; border: 1px solid var(--bci-line); border-radius: 13px; background: color-mix(in srgb, var(--panel2) 32%, transparent); }
.bci-skeleton span { display: block; height: 10px; margin-bottom: 10px; border-radius: 999px; background: linear-gradient(90deg, color-mix(in srgb, var(--bci-line) 75%, transparent), color-mix(in srgb, var(--bci-cyan) 12%, transparent), color-mix(in srgb, var(--bci-line) 75%, transparent)); background-size: 220% 100%; animation: bci-shimmer 1.85s ease-in-out infinite; }
.bci-skeleton span:nth-child(1) { width: 30%; }.bci-skeleton span:nth-child(2) { width: 84%; }.bci-skeleton span:nth-child(3) { width: 57%; margin-bottom: 0; }
@keyframes bci-shimmer { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }
.bci-empty { display: grid; min-height: 270px; place-items: center; padding: 25px; color: var(--muted); text-align: center; }
.bci-empty > div { max-width: 265px; }
.bci-empty-mark { display: grid; width: 40px; height: 40px; margin: 0 auto 12px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 30%, var(--bci-line)); border-radius: 13px; color: var(--bci-cyan); font-size: 20px; place-items: center; }
.bci-empty strong { display: block; color: var(--text); font-size: 13px; }.bci-empty p { margin: 6px 0 0; font-size: 11px; line-height: 1.5; }.bci-empty button { margin-top: 12px; border: 1px solid var(--bci-line); border-radius: 8px; padding: 7px 10px; color: var(--bci-cyan); background: transparent; font-size: 10px; font-weight: 750; }

.bci-inspector-head { display: flex; align-items: flex-start; justify-content: space-between; min-height: 86px; padding: 21px 20px 17px; gap: 10px; }
.bci-inspector-close { width: 28px; height: 28px; padding: 0; border: 1px solid transparent; border-radius: 8px; color: var(--muted); background: transparent; font-size: 20px; line-height: 1; }
.bci-inspector-close:hover { border-color: var(--bci-line); color: var(--text); background: var(--bci-soft); }
.bci-inspector-body { flex: 1; overflow: auto; padding: 20px; }
.bci-inspector-empty { display: grid; min-height: 280px; place-items: center; color: var(--muted); text-align: center; }.bci-inspector-empty p { max-width: 230px; margin: 15px 0 0; font-size: 12px; line-height: 1.55; }
.bci-empty-orbit { position: relative; display: block; width: 46px; height: 46px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 50%, transparent); border-radius: 50%; }.bci-empty-orbit::before,.bci-empty-orbit::after { position: absolute; border: 1px solid color-mix(in srgb, var(--bci-cyan) 30%, transparent); border-radius: 50%; content: ''; }.bci-empty-orbit::before { inset: 10px; }.bci-empty-orbit::after { top: 18px; left: 18px; width: 8px; height: 8px; border: 0; background: var(--bci-cyan); box-shadow: 0 0 0 5px color-mix(in srgb, var(--bci-cyan) 13%, transparent); }
.bci-detail-title { margin: 0; color: var(--text); font-size: 15px; letter-spacing: -.02em; line-height: 1.28; }.bci-detail-id { margin: 6px 0 0; color: var(--bci-cyan); font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; }.bci-detail-link { display: inline-flex; margin-top: 14px; color: var(--bci-cyan); font-size: 11px; font-weight: 750; text-decoration: none; }.bci-detail-link:hover { color: var(--bci-cyan-strong); text-decoration: underline; text-underline-offset: 3px; }
.bci-detail-section { margin-top: 22px; padding-top: 18px; border-top: 1px solid var(--bci-line); }.bci-detail-section h3 { margin: 0 0 10px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }.bci-detail-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 8px; }.bci-detail-fact { min-width: 0; padding: 9px; border: 1px solid var(--bci-line); border-radius: 10px; background: color-mix(in srgb, var(--panel) 47%, transparent); }.bci-detail-fact span,.bci-detail-fact strong { display:block; }.bci-detail-fact span { color: var(--muted); font-size: 9px; }.bci-detail-fact strong { margin-top: 3px; overflow-wrap: anywhere; color: var(--text); font-size: 10px; line-height: 1.36; }.bci-detail-list { display: flex; flex-wrap: wrap; margin: 0; padding: 0; list-style: none; gap: 6px; }.bci-detail-list li { padding: 5px 7px; border: 1px solid var(--bci-line); border-radius: 8px; color: var(--muted); font-size: 10px; line-height: 1.34; }.bci-detail-note { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.bci-evidence-section { margin-top: 18px; padding-top: 15px; border-top-color: color-mix(in srgb, var(--bci-cyan) 25%, var(--bci-line)); }
.bci-evidence-strip { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.bci-evidence-strip .bci-detail-fact { position: relative; overflow: hidden; padding: 9px 10px; background: linear-gradient(145deg, color-mix(in srgb, var(--bci-cyan) 7%, var(--panel)), color-mix(in srgb, var(--panel) 67%, transparent)); }
.bci-evidence-strip .bci-detail-fact::before {content:none;}
.bci-evidence-link { display: block; margin-top: 4px; overflow-wrap: anywhere; color: var(--bci-cyan); font-size: 10px; font-weight: 760; line-height: 1.35; text-decoration: none; }
.bci-evidence-link:hover { color: var(--bci-cyan-strong); text-decoration: underline; text-underline-offset: 3px; }
.bci-endpoints { display: grid; gap: 8px; }.bci-endpoint { padding: 10px; border: 1px solid var(--bci-line); border-radius: 10px; background: color-mix(in srgb, var(--panel) 47%, transparent); }.bci-endpoint strong,.bci-endpoint span { display: block; }.bci-endpoint strong { color: var(--text); font-size: 11px; line-height: 1.4; }.bci-endpoint span { margin-top: 4px; color: var(--bci-cyan); font-family: var(--font-mono); font-size: 9px; line-height: 1.35; }.bci-endpoint p { margin: 7px 0 0; color: var(--muted); font-size: 10px; line-height: 1.48; }
.bci-history-group { position: relative; margin-top: 9px; overflow: hidden; padding: 12px 12px 12px 15px; background: linear-gradient(145deg, color-mix(in srgb, var(--bci-cyan) 7%, var(--panel)), color-mix(in srgb, var(--panel) 58%, transparent)); }
.bci-history-group::before {content:none;}
.bci-history-group > strong { font-size: 12px; letter-spacing: -.01em; }
.bci-history-group > .bci-detail-link { margin-top: 6px; font-family: var(--font-mono); font-size: 9px; font-weight: 650; }
.bci-history-delta { margin-top: 10px; padding-top: 10px; border-top: 1px solid color-mix(in srgb, var(--bci-line) 72%, transparent); }
.bci-history-kind { display: inline-flex !important; width: fit-content; margin: 0 0 2px !important; padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--bci-cyan) 24%, transparent); border-radius: 999px; background: color-mix(in srgb, var(--bci-cyan) 8%, transparent); color: var(--bci-cyan-strong) !important; font-family: var(--font-ui) !important; font-size: 8px !important; font-weight: 800; letter-spacing: .06em; line-height: 1 !important; text-transform: uppercase; }
.bci-history-delta p { overflow-wrap: anywhere; }
.bci-observation-section { border-top-color: color-mix(in srgb, var(--bci-observe) 36%, var(--bci-line)); }
.bci-observation-section > h3 { color: var(--bci-observe-strong); }
.bci-observation-strip .bci-detail-fact { background: linear-gradient(145deg, color-mix(in srgb, var(--bci-observe) 8%, var(--panel)), color-mix(in srgb, var(--panel) 68%, transparent)); }
.bci-observation-strip .bci-detail-fact::before { background: color-mix(in srgb, var(--bci-observe) 40%, transparent); }
.bci-observation-note { margin-top: 10px; padding: 9px 10px; border:1px solid var(--line); background: var(--panel2); }
.bci-observation-delta { margin-top: 9px; padding: 12px; border-color: color-mix(in srgb, var(--bci-observe) 26%, var(--bci-line)); background: linear-gradient(145deg, color-mix(in srgb, var(--bci-observe) 7%, var(--panel)), color-mix(in srgb, var(--panel) 58%, transparent)); }
.bci-observation-delta p { overflow-wrap: anywhere; }
.bci-loading-detail { display: grid; min-height: 220px; place-items: center; color: var(--muted); font-size: 11px; }.bci-loading-detail::before { width: 21px; height: 21px; margin-bottom: 9px; border: 2px solid color-mix(in srgb, var(--bci-cyan) 25%, transparent); border-top-color: var(--bci-cyan); border-radius: 50%; content: ''; animation: bci-spin .8s linear infinite; }

/* ------------------------------------------------------------------ *
 * D0b — decision sentence, temporal braid, screen, peer matrix, tape.
 * ------------------------------------------------------------------ */

/* The stamp: the one type signature on this page. A cut-corner plate with a
   doubled baseline rule, set in tracked mono — an office received-stamp. */
.bci-stamp-mark {
  display: inline-flex;
  align-items: center;
  flex: none;
  padding: 5px 10px 4px;
  border-bottom: 1px solid var(--bci-stamp);
  color: var(--bci-stamp-strong);
  background: color-mix(in srgb, var(--bci-stamp) 15%, transparent);
  box-shadow: 0 3px 0 -1px color-mix(in srgb, var(--bci-stamp) 55%, transparent);
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .16em;
  line-height: 1.25;
  text-transform: uppercase;
}
html[data-theme="light"] .bci-stamp-mark { color: var(--bci-stamp-strong); background: color-mix(in srgb, var(--bci-stamp) 11%, #fff); }
.bci-stamp-mark.is-wait { border-bottom-color: var(--bci-filed); color: var(--bci-filed-strong); background: color-mix(in srgb, var(--bci-filed) 16%, transparent); box-shadow: 0 3px 0 -1px color-mix(in srgb, var(--bci-filed) 58%, transparent); }
.bci-stamp-mark.is-conflict { border-bottom-color: var(--bci-redline); color: var(--bci-redline-strong); background: color-mix(in srgb, var(--bci-redline) 15%, transparent); box-shadow: 0 3px 0 -1px color-mix(in srgb, var(--bci-redline) 58%, transparent); }
.bci-stamp-mark.is-quiet { border-bottom-color: var(--bci-line-strong); color: var(--muted); background: color-mix(in srgb, var(--panel2) 70%, transparent); box-shadow: 0 3px 0 -1px var(--bci-line); }
html[data-theme="light"] .bci-stamp-mark.is-wait { background: color-mix(in srgb, var(--bci-filed) 10%, #fff); }
html[data-theme="light"] .bci-stamp-mark.is-conflict { background: color-mix(in srgb, var(--bci-redline) 9%, #fff); }

/* Decision sentence — first thing in the main pane, above the fold. */
.bci-decision { display: flex; align-items: baseline; margin: 14px 0 0; padding: 0 1px; gap: 11px; }
.bci-decision-why { min-width: 0; margin: 0; color: var(--text); font-size: 14.5px; font-weight: 560; letter-spacing: -.012em; line-height: 1.36; }
html[data-lang="zh"] .bci-decision-why { font-size: 14px; letter-spacing: 0; }

/* Temporal braid — the signature. Two clocks on one labelled scale; the
   horizontal bar between them IS the reporting lag. */
.bci-braid { margin-top: 14px; padding: 12px 13px 10px; border: 1px solid var(--bci-line); border-radius: 12px; background: color-mix(in srgb, var(--panel) 58%, transparent); }
.bci-braid[hidden] { display: none !important; }
.bci-braid-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.bci-braid-head h3 { margin: 0; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }
.bci-braid-unit { color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; }
.bci-braid-plot { position: relative; height: 86px; margin-top: 9px; }
.bci-braid-rail { position: absolute; right: 0; left: 0; height: 1px; background: var(--bci-line-strong); }
.bci-braid-rail.is-effective { top: 17px; background: color-mix(in srgb, var(--bci-filed) 42%, transparent); }
.bci-braid-rail.is-known { top: 53px; background: color-mix(in srgb, var(--bci-stamp) 42%, transparent); }
.bci-braid-rail-name { position: absolute; padding: 0 5px 0 0; color: var(--muted); font-size: 8.5px; font-weight: 780; letter-spacing: .05em; text-transform: uppercase; }
.bci-braid-rail-name.is-effective { top: 3px; left: 0; color: color-mix(in srgb, var(--bci-filed) 85%, var(--text)); }
.bci-braid-rail-name.is-known { top: 68px; left: 0; color: color-mix(in srgb, var(--bci-stamp) 85%, var(--text)); }
.bci-braid-rec { position: absolute; top: 8px; height: 68px; padding: 0; border: 1px solid transparent; border-radius: 4px; background: transparent; }
.bci-braid-rec:hover, .bci-braid-rec:focus-visible { border-color: color-mix(in srgb, var(--bci-stamp) 45%, transparent); background: color-mix(in srgb, var(--bci-stamp) 9%, transparent); }
.bci-braid-eff { position: absolute; top: 5px; width: 9px; height: 9px; margin-left: -4px; background: var(--bci-filed); content: ''; transform: rotate(45deg); }
.bci-braid-stem { position: absolute; top: 9px; width: 1px; background: color-mix(in srgb, var(--text) 26%, transparent); }
.bci-braid-lag { position: absolute; height: 2px; min-width: 2px; background: linear-gradient(90deg, var(--bci-filed), var(--bci-stamp)); }
.bci-braid-lag.is-reverse { background: linear-gradient(270deg, var(--bci-filed), var(--bci-stamp)); }
.bci-braid-known { position: absolute; width: 8px; height: 8px; margin-left: -4px; border-radius: 1px; background: var(--bci-stamp); }
.bci-braid-branch { position: absolute; width: 1px; height: 11px; background: var(--bci-redline); }
.bci-braid-corr { position: absolute; width: 7px; height: 7px; margin-left: -3px; border: 1.5px solid var(--bci-redline); border-radius: 50%; background: var(--panel); }
.bci-braid-scale { display: flex; justify-content: space-between; margin-top: 2px; padding-top: 5px; border-top: 1px dashed var(--bci-line); color: var(--muted); font-family: var(--font-mono); font-size: 8.5px; font-variant-numeric: tabular-nums; gap: 8px; }
.bci-braid-readout { margin: 7px 0 0; min-height: 15px; color: var(--text); font-size: 10.5px; line-height: 1.4; }
.bci-braid-readout:empty::before { color: var(--muted); content: attr(data-rest); }
.bci-braid-foot { margin: 6px 0 0; color: var(--muted); font-size: 10.5px; line-height: 1.45; }
.bci-braid-list { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

/* Active query as removable chips, not a dense form echo. */
.bci-chips { display: flex; flex-wrap: wrap; margin-top: 12px; gap: 6px; }
.bci-chips[hidden] { display: none !important; }
.bci-chip { display: inline-flex; align-items: center; padding: 4px 6px 4px 8px; border: 1px solid var(--bci-line); border-radius: 7px; color: var(--text); background: color-mix(in srgb, var(--panel) 62%, transparent); font-size: 10px; font-weight: 640; gap: 7px; }
.bci-chip b { color: var(--muted); font-family: var(--font-mono); font-size: 8.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; }
.bci-chip-drop { width: 15px; height: 15px; padding: 0; border: 0; border-radius: 4px; color: var(--muted); background: color-mix(in srgb, var(--text) 8%, transparent); font-size: 12px; line-height: 1; }
.bci-chip-drop:hover { color: var(--bci-redline); background: color-mix(in srgb, var(--bci-redline) 16%, transparent); }
.bci-chip-none { color: var(--muted); font-size: 10.5px; }

/* Facet rail — counts under the filters they belong to. */
.bci-facets[hidden], .bci-screen-controls[hidden], .bci-cohort[hidden] { display: none !important; }
.bci-facets { margin-top: 18px; padding-top: 15px; border-top: 1px solid var(--bci-line); }
.bci-facet-group + .bci-facet-group { margin-top: 13px; }
.bci-facet-group h3 { display: flex; justify-content: space-between; margin: 0 0 6px; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; gap: 8px; }
.bci-facet-note { color: var(--muted); font-family: var(--font-mono); font-size: 8.5px; letter-spacing: 0; text-transform: none; }
.bci-facet { display: flex; align-items: center; width: 100%; min-height: 26px; padding: 3px 6px; border: 0; border-radius: 6px; color: var(--muted); background: transparent; font-size: 10.5px; gap: 8px; }
.bci-facet:hover { color: var(--text); background: color-mix(in srgb, var(--bci-stamp) 10%, transparent); }
.bci-facet.is-active { color: var(--text); background: var(--panel2); box-shadow: none; }
.bci-facet-name { flex: 1; min-width: 0; overflow: hidden; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
.bci-facet-count { color: var(--bci-stamp-strong); font-family: var(--font-mono); font-size: 9.5px; font-variant-numeric: tabular-nums; font-weight: 700; }
.bci-facet-miss { margin: 7px 0 0; color: var(--muted); font-size: 10px; line-height: 1.45; }

/* Cohort intake — the user supplies the peer set; nothing is discovered. */
.bci-cohort { margin-top: 17px; }
.bci-cohort textarea { width: 100%; min-height: 112px; padding: 9px 11px; border: 1px solid var(--bci-line); border-radius: 10px; outline: 0; color: var(--text); background: color-mix(in srgb, var(--panel) 68%, transparent); font-family: var(--font-mono); font-size: 11px; letter-spacing: .02em; line-height: 1.6; resize: vertical; }
.bci-cohort textarea:focus { border-color: color-mix(in srgb, var(--bci-stamp) 70%, var(--bci-line)); }
.bci-cohort-actions { display: flex; align-items: center; margin-top: 9px; gap: 9px; }
.bci-cohort-run { min-height: 34px; padding: 0 13px; border: 1px solid color-mix(in srgb, var(--bci-stamp) 46%, var(--bci-line)); border-radius: 9px; color: var(--bci-stamp-strong); background: color-mix(in srgb, var(--bci-stamp) 12%, transparent); font-size: 10px; font-weight: 800; letter-spacing: .03em; }
.bci-cohort-run:hover { border-color: var(--bci-stamp); background: color-mix(in srgb, var(--bci-stamp) 20%, transparent); }
.bci-cohort-hint { color: var(--muted); font-size: 10px; line-height: 1.4; }

/* Peer matrix — stable identity column, per-cell provenance, and coverage
   that is visible as texture rather than as a colour the eye must decode. */
.bci-peer { position: relative; min-width: 0; overflow: auto; }
/* A frozen identity column only helps if the reader can tell there is more to
   the right, so the scroll edge is stated rather than implied. */
.bci-peer-more { margin: 6px 0 0; color: var(--muted); font-size: 10px; }
.bci-peer table { width: 100%; border-collapse: separate; border-spacing: 0; }
.bci-peer th, .bci-peer td { padding: 8px 10px; border-bottom: 1px solid var(--bci-line); font-size: 10.5px; text-align: left; vertical-align: top; }
.bci-peer thead th { position: sticky; top: 0; z-index: 3; color: var(--muted); background: var(--panel); font-size: 9px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; white-space: nowrap; }
.bci-peer .bci-peer-id { position: sticky; left: 0; z-index: 2; min-width: 168px; border-right: 1px solid var(--bci-line-strong); background: var(--panel); }
.bci-peer thead .bci-peer-id { z-index: 4; }
.bci-peer-nct { display: block; color: var(--bci-stamp-strong); font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; font-weight: 700; }
.bci-peer-name { display: -webkit-box; overflow: hidden; margin-top: 3px; color: var(--text); font-size: 10.5px; font-weight: 640; line-height: 1.34; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.bci-peer-val { display: block; color: var(--text); overflow-wrap: anywhere; }
.bci-peer-cell.is-partial .bci-peer-val { color: color-mix(in srgb, var(--bci-filed) 62%, var(--text)); border-bottom: 1px dashed var(--bci-filed); }
.bci-peer-cell.is-uncovered { background: repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in srgb, var(--text) 7%, transparent) 5px 6px); }
.bci-peer-cell.is-uncovered .bci-peer-val { color: var(--muted); font-style: italic; }
.bci-peer-src { display: block; margin-top: 5px; padding: 0; border: 0; max-width: 132px; overflow: hidden; color: var(--muted); background: transparent; font-family: var(--font-mono); font-size: 8.5px; letter-spacing: .02em; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
.bci-peer-src:hover { color: var(--bci-stamp-strong); text-decoration: underline; text-underline-offset: 2px; }
.bci-peer-cards { display: grid; gap: 9px; }
.bci-peer-card { padding: 12px; border: 1px solid var(--bci-line); border-radius: 12px; background: color-mix(in srgb, var(--panel) 58%, transparent); }
.bci-peer-card > header { padding-bottom: 8px; border-bottom: 1px solid var(--bci-line); }
.bci-peer-row { display: grid; grid-template-columns: 96px minmax(0, 1fr); align-items: baseline; padding: 7px 0; border-bottom: 1px solid var(--bci-rule); gap: 10px; }
.bci-peer-row:last-child { border-bottom: 0; }
.bci-peer-row > dt { color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.bci-peer-row > dd { margin: 0; min-width: 0; font-size: 10.5px; }
.bci-peer-legend { display: flex; flex-wrap: wrap; margin-top: 10px; color: var(--muted); font-size: 10px; gap: 6px 14px; }
.bci-peer-legend span { display: inline-flex; align-items: center; gap: 6px; }
.bci-peer-legend i { width: 10px; height: 10px; border: 1px solid var(--bci-line-strong); border-radius: 2px; }
.bci-peer-legend i.is-partial { border-color: var(--bci-filed); border-style: dashed; }
.bci-peer-legend i.is-uncovered { background: repeating-linear-gradient(135deg, transparent 0 3px, color-mix(in srgb, var(--text) 22%, transparent) 3px 4px); }

/* A comparison is read whole: the peer surface drops the fixed workspace height
   so rows are never cut mid-record inside a scroll box. */
[data-surface="peers"] .bci-information { height: auto; min-height: 0; }
[data-surface="peers"] .bci-filter-pane, [data-surface="peers"] .bci-queue-pane, [data-surface="peers"] .bci-inspector-pane { height: auto; overflow: visible; }
[data-surface="peers"] .bci-queue { overflow: visible; padding-right: 0; }

/* Change tape row — exact before/after, the source path, both clocks. */
.bci-tape-card { min-height: 132px; align-items: stretch; }
.bci-tape-card .bci-trial-main { display: flex; flex-direction: column; }
.bci-tape-card .bci-trial-topline { flex-wrap: wrap; }
.bci-tape-delta { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border:1px solid var(--line);  border-radius:var(--r-card,12px); color: var(--muted); background: var(--panel2); font-family: var(--font-mono); font-size: 9px; line-height: 1.36; gap: 7px; }
.bci-tape-delta > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bci-tape-delta > b { color: var(--bci-redline); font-family: var(--font-ui); font-size: 12px; font-weight: 760; }
.bci-tape-exact { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; margin-top: 10px; padding: 8px 9px; border:1px solid var(--line);  border-radius:var(--r-card,12px); background: var(--panel2); gap: 7px; }
.bci-tape-exact > b { color: var(--bci-redline); font-size: 12px; }
.bci-tape-value { display: grid; min-width: 0; gap: 2px; }
.bci-tape-value small { color: var(--muted); font-family: var(--font-ui); font-size: 8px; font-weight: 800; letter-spacing: .055em; text-transform: uppercase; }
.bci-tape-value code { display: block; min-width: 0; overflow: hidden; color: var(--text); font-family: var(--font-mono); font-size: 9px; line-height: 1.4; text-overflow: ellipsis; white-space: nowrap; }
.bci-tape-value.is-missing code, .bci-tape-value.is-unavailable code { color: var(--muted); font-family: var(--font-ui); font-style: italic; }
.bci-tape-value em { color: var(--muted); font-family: var(--font-ui); font-size: 8px; font-style: normal; }
.bci-tape-exact.is-detail { margin: 10px 0 0; padding: 11px; }
.bci-endpoint .bci-tape-exact { display: grid; }
.bci-endpoint .bci-tape-value { display: grid; margin-top: 0; color: inherit; font-family: inherit; }
.bci-tape-exact.is-detail .bci-tape-value code { overflow: visible; overflow-wrap: anywhere; text-overflow: clip; white-space: pre-wrap; }
.bci-tape-disclosure { margin-top: 10px; padding-top: 9px; border-top: 1px solid var(--bci-line); }
.bci-tape-disclosure summary { width: fit-content; cursor: pointer; color: var(--bci-cyan-strong); font-size: 10px; font-weight: 760; }
.bci-tape-disclosure p { display: grid; grid-template-columns: 104px minmax(0, 1fr); margin: 8px 0 0; color: var(--muted); font-size: 9px; gap: 8px; }
.bci-tape-disclosure p > span { margin: 0; color: var(--muted); font-family: var(--font-ui); font-size: 8px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; }
.bci-tape-disclosure code, .bci-tape-disclosure strong { min-width: 0; overflow-wrap: anywhere; color: var(--text); font-family: var(--font-mono); font-size: 9px; font-weight: 650; }
.bci-tape-path { display: block; margin-top: 7px; overflow: hidden; color: color-mix(in srgb, var(--bci-stamp) 72%, var(--text)); font-family: var(--font-mono); font-size: 9px; letter-spacing: .01em; text-overflow: ellipsis; white-space: nowrap; }
.bci-tape-review { display: inline-flex; padding: 2px 6px; border: 1px dashed color-mix(in srgb, var(--bci-filed) 55%, var(--bci-line)); border-radius: 99px; color: var(--bci-filed-strong); font-size: 8.5px; font-weight: 800; letter-spacing: .04em; line-height: 1.3; text-transform: uppercase; }
.bci-tape-clocks { display: grid; align-content: start; justify-items: end; min-width: 116px; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-tape-clocks b { color: color-mix(in srgb, var(--bci-filed) 70%, var(--text)); font-weight: 700; }
.bci-tape-clocks i { color: color-mix(in srgb, var(--bci-stamp) 74%, var(--text)); font-style: normal; font-weight: 700; }

/* Screen row — the row carries what differs; constants sit in the footer. */
.bci-screen-card { min-height: 92px; }
.bci-cues { display: flex; flex-wrap: wrap; margin-top: 7px; color: var(--muted); font-size: 9.5px; gap: 3px 9px; }
.bci-cues span { display: inline-flex; align-items: center; }
.bci-cues span + span::before { width: 3px; height: 3px; margin-right: 8px; border-radius: 50%; background: var(--bci-line-strong); content: ''; }
.bci-cues .is-partial { color: color-mix(in srgb, var(--bci-filed) 68%, var(--text)); }
.bci-cues .is-missing { color: var(--muted); font-style: italic; }
.bci-interval { display: grid; justify-items: end; min-width: 118px; color: var(--muted); font-family: var(--font-mono); font-size: 9px; font-variant-numeric: tabular-nums; line-height: 1.35; text-align: right; gap: 5px; }
.bci-interval strong { color: var(--text); font-family: var(--font-ui); font-size: 12.5px; font-weight: 780; letter-spacing: -.02em; }

/* One footer, once — every constant the rows would otherwise repeat. */
.bci-panel-foot { margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--bci-line); color: var(--muted); font-size: 10.5px; line-height: 1.5; }
.bci-panel-foot[hidden] { display: none !important; }
.bci-panel-foot b { color: color-mix(in srgb, var(--text) 78%, var(--muted)); font-weight: 700; }

.bci-scrim { position: fixed; z-index: 100010; inset: 0; background: rgba(5, 9, 18, .42); backdrop-filter: blur(2px); }

@media (max-width: 1120px) {
