[data-theme="light"] .pw .pw-backdrop{background:color-mix(in srgb, var(--panel) 72%, transparent);box-shadow:inset 0 1px 0 color-mix(in srgb, var(--panel) 90%, transparent), 0 6px 18px color-mix(in srgb, var(--text) 6%, transparent)}
