* { box-sizing:border-box; }
body { background:var(--bg); color:var(--text); font:14px/1.5 -apple-system,"Segoe UI",Roboto,Helvetica,sans-serif; margin:0; padding:18px; }
@media (min-width:1100px){ body{ padding:26px max(40px,calc((100vw - 1100px)/2)); } }
a { text-decoration:none; color:var(--ink-link, var(--link)); }
h1 { font-size:20px; margin:0; }
h2 { font-size:13px; margin:0 0 9px; color:var(--muted); text-transform:uppercase; letter-spacing:.06em; }
h3 { font-size:15px; margin:0 0 8px; }
.panel { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:16px 18px; margin-bottom:16px; }
.panel-head { display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:12px; }

/* ── Hero panel ── */
.nw-hero { background:linear-gradient(135deg, color-mix(in srgb,var(--link) 12%,var(--panel)) 0%, var(--panel) 60%); border:1px solid color-mix(in srgb,var(--link) 30%,var(--line)); border-radius:14px; padding:28px 24px 22px; margin-bottom:16px; }
.nw-hero-headline { font-size:clamp(28px,5vw,42px); font-weight:900; letter-spacing:-.02em; margin:0 0 6px; background:linear-gradient(120deg, var(--link) 0%, color-mix(in srgb,var(--link) 60%,var(--up)) 100%); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; line-height:1.1; }
.nw-hero-tagline { font-size:16px; color:var(--muted); margin:0 0 14px; font-style:italic; }
.nw-hero-desc { font-size:14px; line-height:1.7; max-width:760px; margin-bottom:18px; color:var(--text); }
.nw-stat-chips { display:flex; flex-wrap:wrap; gap:10px; align-items:center; }
.nw-chip { display:inline-flex; align-items:center; gap:7px; padding:7px 14px; border-radius:30px; background:color-mix(in srgb,var(--link) 10%,var(--panel2)); border:1px solid color-mix(in srgb,var(--link) 25%,var(--line)); font-size:13px; font-weight:600; backdrop-filter:blur(4px); }
.nw-chip-val { font-size:18px; font-weight:800; color:var(--ink-link, var(--link)); }
.nw-chip-label { font-size:11px; color:var(--muted); font-weight:400; margin-top:1px; }
.nw-chip-ok { border-color:color-mix(in srgb,var(--up) 35%,var(--line)); }
.nw-chip-ok .nw-chip-val { color:var(--ink-up, var(--up)); }
.nw-chip-offline { border-color:color-mix(in srgb,var(--warn) 35%,var(--line)); }
.nw-chip-offline .nw-chip-val { color:var(--ink-warn, var(--warn)); }

/* ── Auth gate ── */
#cm_gate { text-align:center; padding:48px 24px; }
#cm_gate h2 { font-size:18px; text-transform:none; letter-spacing:0; color:var(--text); margin-bottom:10px; }
#cm_gate p { color:var(--muted); max-width:480px; margin:0 auto 18px; }
.btn-primary { background:var(--link); color:#fff; border:none; border-radius:9px; padding:10px 22px; font-size:15px; font-weight:700; cursor:pointer; }
.btn-primary:hover { opacity:.88; }
#cm_content { display:none; }

/* ── Search ── */
.cm-search-wrap { position:relative; flex:1; min-width:260px; max-width:520px; }
#cm_q { width:100%; padding:10px 14px; border-radius:10px; border:1px solid var(--line); background:var(--panel2); color:var(--text); font-size:15px; outline:none; }
#cm_q:focus { border-color:var(--link); }
#cm_sugg { position:absolute; top:104%; left:0; right:0; background:var(--panel); border:1px solid var(--line); border-radius:10px; z-index:50; max-height:320px; overflow:auto; display:none; box-shadow:var(--popover-shadow,0 8px 32px rgba(0,0,0,.22)); }
#cm_sugg div { padding:8px 13px; cursor:pointer; display:flex; gap:10px; align-items:center; }
#cm_sugg div:hover, #cm_sugg div.sel { background:var(--panel2); }
#cm_sugg b { min-width:62px; flex:none; }
#cm_sugg small { color:var(--muted); flex:1; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.cm-index-count { font-size:12px; color:var(--muted); margin-top:6px; }
.cm-index-warn { background:color-mix(in srgb,var(--warn) 12%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 35%,transparent); border-radius:8px; padding:8px 12px; margin-top:8px; font-size:13px; color:var(--ink-warn, var(--warn)); display:none; }
.cm-quick-tries { display:flex; flex-wrap:wrap; gap:7px; margin-top:14px; }
.cm-quick-chip { padding:5px 12px; border-radius:20px; border:1px solid var(--line); background:var(--panel2); font-size:13px; font-weight:700; cursor:pointer; color:var(--ink-link, var(--link)); transition:background .15s; }
.cm-quick-chip:hover { background:color-mix(in srgb,var(--link) 12%,var(--panel2)); }

/* ── Committee (provenance) view ── */
.cm-ticker-header { display:flex; align-items:baseline; gap:12px; flex-wrap:wrap; margin-bottom:14px; }
.cm-ticker-sym { font-size:22px; font-weight:800; }
.cm-ticker-name { font-size:15px; color:var(--muted); }
.cm-ticker-decision { font-size:13px; color:var(--muted); }

.prov-table { width:100%; border-collapse:collapse; font-size:13px; }
.prov-table th { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); padding:6px 8px; border-bottom:1px solid var(--line); text-align:left; }
.prov-table td { padding:8px; border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent); vertical-align:top; }
.prov-table tr:last-child td { border-bottom:none; }
.prov-table tr:hover td { background:color-mix(in srgb,var(--link) 5%,transparent); }

.tier-badge { display:inline-block; padding:2px 8px; border-radius:6px; font-size:11px; font-weight:700; letter-spacing:.04em; }
.tier-DISPLAY  { background:color-mix(in srgb,var(--link) 18%,var(--panel2)); color:var(--ink-link, var(--link)); }
.tier-SHADOW   { background:color-mix(in srgb,var(--warn) 18%,var(--panel2)); color:var(--ink-warn, var(--warn)); }
.tier-UNKNOWN  { background:var(--panel2); color:var(--muted); }

.kernel-ic { font-variant-numeric:tabular-nums; }
.kernel-null { color:var(--muted); font-style:italic; }
.armed-yes { color:var(--ink-up, var(--up)); font-weight:700; }
.armed-no  { color:var(--muted); }

.stale-ok   { color:var(--ink-ok, var(--ok)); }
.stale-warn { color:var(--ink-warn, var(--warn)); }
.stale-old  { color:var(--ink-act, var(--act)); }

.source-expand { cursor:pointer; color:var(--ink-link, var(--link)); font-size:11px; user-select:none; }
.source-detail { display:none; background:var(--panel2); border-radius:7px; padding:8px 10px; font-size:11.5px; color:var(--muted); margin-top:4px; }
.source-detail.open { display:block; }

.dir-pos { color:var(--ink-up, var(--up)); font-weight:700; }
.dir-neg { color:var(--ink-down, var(--down)); font-weight:700; }
.dir-neu { color:var(--muted); }

/* ── Compliance disclaimer (fixed at bottom) ── */
.disclaimer-bar { position:fixed; bottom:0; left:0; right:0; background:color-mix(in srgb,var(--panel) 97%,transparent); border-top:1px solid var(--line); padding:7px 18px; font-size:11px; color:var(--muted); display:flex; align-items:center; gap:10px; z-index:100; backdrop-filter:blur(8px); }
.disclaimer-bar button { background:none; border:none; color:var(--muted); cursor:pointer; font-size:14px; padding:0 4px; line-height:1; }
#disc_bar { display:none; }
body { padding-bottom:56px; }

/* ── Synapse map canvas ── */
/* Deep-space backdrop (both themes — the map is deliberately a dark window even in light mode).
   Layers top→bottom: vignette, 4 tiled star layers (non-harmonic tile sizes so no visible grid),
   3 corner nebulas echoing the lobe palette, base depth gradient. Center stays darkest so the
   core's white glow and low-alpha wiring edges keep contrast. */
.graph-wrap {
  position:relative; border-radius:12px; overflow:hidden;
  background-color:#02030c;
  background-image:
    radial-gradient(ellipse 120% 100% at 50% 42%, transparent 58%, rgba(1,2,8,.55) 100%),
    radial-gradient(1.6px 1.6px at 137px 41px, rgba(230,239,255,.8), transparent 50%),
    radial-gradient(1.2px 1.2px at 23px 108px, rgba(218,231,255,.6), transparent 50%),
    radial-gradient(1px 1px at 191px 67px, rgba(214,228,255,.45), transparent 50%),
    radial-gradient(1px 1px at 79px 152px, rgba(200,216,255,.3), transparent 50%),
    radial-gradient(ellipse 55% 42% at 14% 8%, rgba(79,97,255,.13), transparent 62%),
    radial-gradient(ellipse 48% 40% at 87% 12%, rgba(56,189,248,.09), transparent 60%),
    radial-gradient(ellipse 58% 48% at 80% 98%, rgba(168,85,247,.12), transparent 62%),
    linear-gradient(180deg, #050818 0%, #02030c 48%, #030410 100%);
  background-repeat:no-repeat, repeat, repeat, repeat, repeat, no-repeat, no-repeat, no-repeat, no-repeat;
  background-size:100% 100%, 347px 347px, 289px 289px, 231px 231px, 173px 173px, 100% 100%, 100% 100%, 100% 100%, 100% 100%;
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line) 55%,transparent);
}
#graph_canvas { width:100%; height:640px; display:block; cursor:grab; touch-action:none; }
@media(max-width:719px){ #graph_canvas { height:420px; } }
#graph_canvas:active { cursor:grabbing; }
.graph-controls { position:absolute; top:10px; right:10px; display:flex; gap:5px; z-index:10; }
.gc-btn { width:32px; height:32px; border-radius:8px; border:1px solid color-mix(in srgb,var(--line) 60%,transparent); background:color-mix(in srgb,var(--panel) 70%,transparent); color:var(--text); font-size:14px; cursor:pointer; display:flex; align-items:center; justify-content:center; backdrop-filter:blur(6px); transition:background .15s; }
.gc-btn:hover { background:color-mix(in srgb,var(--link) 20%,var(--panel)); }
.graph-tooltip { position:absolute; pointer-events:none; background:color-mix(in srgb,var(--panel) 95%,transparent); border:1px solid var(--line); border-radius:10px; padding:9px 13px; font-size:12px; max-width:260px; z-index:20; display:none; backdrop-filter:blur(8px); box-shadow:0 4px 20px rgba(0,0,0,.3); line-height:1.55; }
.graph-tooltip.visible { display:block; }
.graph-tooltip strong { color:var(--ink-link, var(--link)); font-size:13px; }
.graph-info-card { position:absolute; top:50px; right:10px; width:220px; background:color-mix(in srgb,var(--panel) 95%,transparent); border:1px solid var(--line); border-radius:11px; padding:12px 14px; font-size:12px; z-index:15; display:none; backdrop-filter:blur(8px); box-shadow:0 4px 20px rgba(0,0,0,.25); max-height:calc(100% - 70px); overflow-y:auto; }
@media(max-width:719px){ .graph-info-card { position:static; width:100%; margin-top:8px; max-height:240px; } }
.graph-info-card.visible { display:block; }
.graph-info-title { font-size:14px; font-weight:700; color:var(--ink-link, var(--link)); margin-bottom:4px; }
.graph-info-type { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); margin-bottom:8px; }
.graph-info-section { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:8px 0 4px; }
.graph-nbr-chip { display:inline-block; padding:2px 8px; border-radius:12px; background:var(--panel2); border:1px solid var(--line); font-size:11px; cursor:pointer; margin:2px; color:var(--text); }
.graph-nbr-chip:hover { border-color:var(--link); color:var(--ink-link, var(--link)); }
.graph-legend { display:flex; flex-wrap:wrap; gap:10px; margin-top:10px; font-size:12px; align-items:center; }
.gl-dot { width:11px; height:11px; border-radius:50%; flex:none; display:inline-block; }
.gl-line { width:28px; height:3px; display:inline-block; vertical-align:middle; flex:none; }

/* ── Cortex memo panel ── */
.probation-banner { background:color-mix(in srgb,var(--warn) 14%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 40%,transparent); border-radius:9px; padding:10px 14px; margin-bottom:12px; font-size:13px; }
.probation-banner strong { color:var(--ink-warn, var(--warn)); }
.is-context-badge { display:inline-block; background:color-mix(in srgb,var(--info,#5b9dff) 14%,var(--panel2)); color:var(--ink-info, var(--info,#5b9dff)); font-size:10px; font-weight:700; padding:2px 8px; border-radius:6px; letter-spacing:.05em; vertical-align:middle; margin-left:8px; }
.memo-summary-card { background:color-mix(in srgb,var(--link) 8%,var(--panel2)); border-left:3px solid var(--link); border-radius:0 9px 9px 0; padding:12px 16px; margin:10px 0 14px; font-size:14px; line-height:1.7; }
.fired-list { margin:8px 0; padding-left:18px; }
.fired-list li { margin:3px 0; font-size:13px; color:var(--muted); }
.tc-chip { display:inline-block; background:var(--panel2); padding:2px 8px; border-radius:6px; font-size:12px; margin:2px; }
.memo-failed-banner { background:color-mix(in srgb,var(--warn) 14%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 40%,transparent); border-radius:9px; padding:12px 16px; margin-bottom:12px; font-size:13px; color:var(--text); }
.memo-failed-banner strong { color:var(--ink-warn, var(--warn)); }
.memo-partial-banner { background:color-mix(in srgb,var(--warn) 8%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 25%,transparent); border-radius:9px; padding:10px 14px; margin-bottom:12px; font-size:13px; }
details.memo-raw summary { cursor:pointer; font-size:12px; color:var(--muted); padding:6px 0; user-select:none; }
details.memo-raw pre { font-size:11px; overflow-x:auto; color:var(--muted); white-space:pre-wrap; }

/* ── Ask the brain ── */
.ask-box { display:flex; flex-direction:column; gap:12px; }
.ask-row { display:flex; gap:8px; align-items:flex-start; flex-wrap:wrap; }
.ask-q { flex:1; min-width:200px; padding:10px 14px; border-radius:10px; border:1px solid var(--line); background:var(--panel2); color:var(--text); font-size:14px; outline:none; resize:vertical; min-height:58px; }
.ask-q:focus { border-color:var(--link); }
.ask-ticker { width:110px; padding:10px 12px; border-radius:10px; border:1px solid var(--line); background:var(--panel2); color:var(--text); font-size:13px; outline:none; text-transform:uppercase; }
.ask-ticker:focus { border-color:var(--link); }
.ask-ticker::placeholder { text-transform:none; }
.ask-btn { padding:11px 22px; background:var(--link); color:#fff; border:none; border-radius:10px; font-size:15px; font-weight:700; cursor:pointer; white-space:nowrap; }
.ask-btn:hover:not(:disabled) { opacity:.88; }
.ask-btn:disabled { opacity:.45; cursor:default; }
.ask-charcount { font-size:11px; color:var(--muted); align-self:center; }
.ask-examples { font-size:12px; color:var(--muted); }
.ask-examples span { font-style:italic; }
.ask-state-loading { display:none; padding:14px 0; color:var(--muted); font-size:14px; }
.ask-state-loading.active { display:block; }
.ask-answer { display:none; }
.ask-answer.active { display:block; }
.ask-mode-badge { display:inline-flex; align-items:center; gap:6px; padding:3px 10px; border-radius:7px; font-size:11px; font-weight:700; letter-spacing:.05em; margin-bottom:10px; }
.ask-mode-live { background:var(--wash-ok); color:var(--ink-ok, var(--ok)); }
.ask-mode-memo { background:color-mix(in srgb,var(--warn) 16%,var(--panel2)); color:var(--ink-warn, var(--warn)); }
.ask-degraded { background:color-mix(in srgb,var(--warn) 12%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 35%,transparent); border-radius:8px; padding:8px 12px; margin-bottom:10px; font-size:13px; color:var(--ink-warn, var(--warn)); }
.ask-answer-text { font-size:14px; line-height:1.7; margin:8px 0 14px; white-space:pre-wrap; }
.ask-citations { margin:0; padding-left:18px; }
.ask-citations li { font-size:12.5px; color:var(--muted); margin:3px 0; }
.ask-citations-head { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:12px 0 5px; }
.ask-disclaimer { font-size:11px; color:var(--muted); border-top:1px solid var(--line); margin-top:12px; padding-top:8px; }
.ask-error { display:none; background:color-mix(in srgb,var(--down) 12%,var(--panel2)); border:1px solid color-mix(in srgb,var(--down) 35%,transparent); border-radius:9px; padding:10px 14px; font-size:13px; color:var(--ink-down, var(--down)); }
.ask-error.active { display:block; }
.ask-signin-msg { background:color-mix(in srgb,var(--link) 10%,var(--panel2)); border:1px solid color-mix(in srgb,var(--link) 30%,transparent); border-radius:9px; padding:10px 14px; font-size:13px; display:none; }
.ask-signin-msg.active { display:block; }

/* ── Kernel family cards ── */
.kf-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:10px; }
.kf-card { background:var(--panel2); border:1px solid var(--line); border-radius:10px; padding:12px 14px; }
.kf-name { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; margin-bottom:6px; color:var(--text); display:flex; justify-content:space-between; align-items:center; }
.kf-ic { font-size:20px; font-weight:800; font-variant-numeric:tabular-nums; }
.kf-ic.kf-pos { color:var(--ink-up, var(--up)); }
.kf-ic.kf-neg { color:var(--ink-down, var(--down)); }
.kf-ic.kf-null { color:var(--muted); font-size:14px; font-style:italic; }
.kf-sub { font-size:11px; color:var(--muted); margin-top:3px; }
.kf-armed-badge { font-size:10px; font-weight:700; padding:2px 7px; border-radius:5px; }
.kf-armed-yes { background:color-mix(in srgb,var(--up) 16%,var(--panel2)); color:var(--ink-up, var(--up)); }
.kf-armed-no  { background:var(--panel); color:var(--muted); }
.kf-stale { font-size:10.5px; color:var(--muted); margin-top:5px; }
.kf-hl { font-size:11px; color:var(--muted); margin-top:5px; }
.kf-hl-val { color:var(--ink-link, var(--link)); font-weight:600; cursor:help; }
.kf-hl .kf-null { font-style:italic; cursor:help; }
.kf-unit-chip { display:inline-block; font-size:9.5px; font-weight:700; padding:1px 6px; border-radius:5px; margin-left:6px; vertical-align:middle; background:color-mix(in srgb,var(--warn) 14%,var(--panel2)); color:var(--ink-warn, var(--warn)); cursor:help; line-height:1.5; }
.kf-spark { display:block; margin-top:6px; }
.kf-meter { height:4px; border-radius:2px; background:var(--panel); overflow:hidden; margin-top:7px; }
.kf-meter-fill { height:100%; background:color-mix(in srgb,var(--link) 55%,transparent); }
.kf-accrue-strip { background:var(--panel2); border:1px dashed var(--line); border-radius:10px; padding:9px 14px; font-size:11.5px; color:var(--muted); margin-top:10px; line-height:1.7; }
.kf-progress { margin-top:12px; font-size:11px; color:var(--muted); line-height:1.7; border-top:1px solid var(--line); padding-top:9px; }
.kf-fresh-chip { font-size:10.5px; font-weight:600; padding:2px 8px; border-radius:5px; background:var(--panel2); color:var(--muted); }
.kf-fresh-chip.kf-fresh-stale { background:color-mix(in srgb,var(--warn) 12%,var(--panel2)); color:var(--ink-warn, var(--warn)); }

/* ── Liquidity plumbing compact cells ── */
.lq-cells { display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:8px; }
.lq-cell { background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:8px 10px; }
.lq-cell-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin-bottom:3px; }
.lq-cell-val { font-size:15px; font-weight:800; font-variant-numeric:tabular-nums; }
.lq-cell-sub { font-size:10.5px; color:var(--muted); margin-top:2px; }
.lq-sec-label { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:2px 0 6px; display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.lq-state-chip { font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:5px; }

/* ── Market plane hero strip ── */
.mp-strip { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin-top:12px; }
.mp-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 11px; border-radius:20px; font-size:11.5px; font-weight:600; background:var(--panel2); border:1px solid var(--line); color:var(--text); }
.mp-pill { font-weight:800; font-size:12.5px; }
.mp-dot { width:8px; height:8px; border-radius:50%; display:inline-block; flex:none; }
.mp-sub { font-size:10px; color:var(--muted); font-weight:400; }
.mp-stale .mp-chip { opacity:.45; filter:grayscale(.7); }

/* ── Plain-English explainer box ── */
.plain-eng { background:color-mix(in srgb,var(--link) 8%,var(--panel2)); border-left:3px solid var(--link); border-radius:0 9px 9px 0; padding:12px 16px; margin:14px 0; font-size:13.5px; line-height:1.65; }
.plain-eng strong { color:var(--ink-link, var(--link)); }

/* ── Today's Read card (PR-4 M1) ── */
.tr-card { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:18px 20px; margin-bottom:16px; }
.tr-header { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px; margin-bottom:14px; }
.tr-title { font-size:16px; font-weight:800; letter-spacing:-.01em; }
.tr-asof { font-size:11px; color:var(--muted); }
.tr-tape { border-left:3px solid var(--link); background:color-mix(in srgb,var(--link) 7%,var(--panel2)); border-radius:0 9px 9px 0; padding:10px 14px; margin-bottom:12px; }
.tr-tape-primary { font-size:14px; font-weight:700; line-height:1.4; }
.tr-tape-legs { font-size:12px; color:var(--muted); margin-top:4px; }
.tr-tape-alts { font-size:12px; color:var(--muted); margin-top:2px; }
.tr-regime { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:12px; align-items:center; }
.tr-regime-chip { display:inline-flex; align-items:center; gap:5px; padding:5px 12px; border-radius:20px; background:var(--panel2); border:1px solid var(--line); font-size:12px; font-weight:600; }
.tr-regime-conf { font-size:11px; color:var(--muted); }
.tr-regime-low { border-color:color-mix(in srgb,var(--warn) 40%,var(--line)); }
.tr-regime-low .tr-regime-chip { color:var(--ink-warn, var(--warn)); }
.tr-section-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); margin-bottom:5px; }
.tr-item { display:flex; align-items:baseline; gap:7px; padding:5px 0; border-bottom:1px solid color-mix(in srgb,var(--line) 40%,transparent); font-size:13px; }
.tr-item:last-child { border-bottom:none; }
.tr-sev { font-size:10px; font-weight:700; padding:2px 6px; border-radius:5px; flex:none; }
.tr-sev-P1 { background:color-mix(in srgb,var(--down) 18%,var(--panel2)); color:var(--ink-down, var(--down)); }
.tr-sev-P2 { background:color-mix(in srgb,var(--warn) 18%,var(--panel2)); color:var(--ink-warn, var(--warn,#e6a817)); }
.tr-sev-P3 { background:var(--panel2); color:var(--muted); }
.tr-attn-block { margin-bottom:12px; }
.tr-contra-block { margin-bottom:12px; }
.tr-stale-count { font-size:12px; color:var(--muted); margin-bottom:10px; }
.tr-degraded-line { font-size:12px; color:var(--ink-warn, var(--warn,#e6a817)); padding:6px 10px; border-radius:7px; background:color-mix(in srgb,var(--warn) 10%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 30%,transparent); display:none; }
.tr-degraded-line.visible { display:block; }
.tr-loading { font-size:13px; color:var(--muted); padding:8px 0; }
.tr-empty { font-size:13px; color:var(--muted); font-style:italic; }

/* ── Lazy sections ── */
.section-lazy { opacity:0; transform:translateY(14px); transition:opacity .35s ease,transform .35s ease; }
.section-lazy.visible { opacity:1; transform:none; }

/* ── Empty / loading states ── */
.cm-empty { color:var(--muted); font-style:italic; padding:20px 0; text-align:center; }
.cm-loading { display:none; color:var(--muted); font-size:13px; padding:10px 0; }

/* ── NW read layer: Web Health / Disagreements / Constitution ledger ── */
.nwh-status-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 12px; border-radius:20px; font-size:12px; font-weight:800; letter-spacing:.05em; border:1px solid var(--line); }
.nwh-counts { display:flex; flex-wrap:wrap; gap:8px; margin:10px 0 12px; }
.nwh-count { background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:6px 12px; font-size:11px; color:var(--muted); }
.nwh-count b { display:block; font-size:16px; font-weight:800; line-height:1.2; }
.nwh-item { display:flex; align-items:baseline; gap:8px; padding:5px 0; border-bottom:1px solid color-mix(in srgb,var(--line) 40%,transparent); font-size:13px; }
.nwh-item:last-child { border-bottom:none; }
.nwh-dot { display:inline-block; width:10px; height:10px; border-radius:50%; flex:none; }
.contra-row { border-left:3px solid var(--muted); background:var(--panel2); border-radius:0 8px 8px 0; padding:9px 12px; margin:8px 0; font-size:13px; }
.contra-row.contra-tension { border-left-color:var(--warn); }
.contra-sev { display:inline-block; font-size:10px; font-weight:700; padding:2px 7px; border-radius:5px; letter-spacing:.05em; margin-right:7px; background:var(--panel); color:var(--muted); border:1px solid var(--line); }
.contra-sev-tension { background:color-mix(in srgb,var(--warn) 16%,var(--panel2)); color:var(--ink-warn, var(--warn)); border-color:color-mix(in srgb,var(--warn) 40%,transparent); }
.gov-row { display:flex; align-items:baseline; gap:9px; padding:7px 0; border-bottom:1px solid color-mix(in srgb,var(--line) 40%,transparent); font-size:13px; flex-wrap:wrap; }
.gov-row:last-child { border-bottom:none; }
.gov-date { font-size:11px; color:var(--muted); font-variant-numeric:tabular-nums; flex:none; }
.gov-type { font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:10.5px; font-weight:700; background:color-mix(in srgb,var(--link) 12%,var(--panel2)); color:var(--ink-link, var(--link)); padding:2px 7px; border-radius:5px; flex:none; }
.gov-target { font-weight:600; }
.gov-note { flex-basis:100%; font-size:12px; color:var(--muted); line-height:1.5; }

/* ── W1 Role badges ── */
.role-badge { display:inline-block; padding:2px 7px; border-radius:5px; font-size:10.5px; font-weight:700; letter-spacing:.04em; cursor:default; }
.role-veto    { background:color-mix(in srgb,var(--down)  18%,var(--panel2)); color:var(--ink-down, var(--down)); }
.role-alpha   { background:color-mix(in srgb,var(--up)    18%,var(--panel2)); color:var(--ink-up, var(--up)); }
.role-sizing  { background:color-mix(in srgb,var(--link)  18%,var(--panel2)); color:var(--ink-link, var(--link)); }
.role-timing  { background:color-mix(in srgb,var(--warn)  18%,var(--panel2)); color:var(--ink-warn, var(--warn)); }
.role-context { background:var(--panel); color:var(--muted); }

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .section-lazy { transition:none; }
}

/* ═══════════════════ NEURAL WEB · MX5 DESIGN LAYER ═══════════════════
   Ports the macro.html (mx5, Fable) visual language onto the Neural Web:
   glass cards, ambient aurora, a living-brain hero, sticky chapter tabs,
   and a mono "telemetry" type system grounded in the subject — a machine
   that thinks. Every motion respects prefers-reduced-motion. */
.page-committee{
  --lobe-core:#e2e8f0; --lobe-us:#4da3ff; --lobe-cn:#f0883e;
  --lobe-sig:#a78bfa; --lobe-macro:#2dd4bf;
  /* Third ink for the neural-web chapter. #eaf0fb is a DARK-plane text value and
     was serving both themes — 1.21:1 on the light panel where it carries the
     active chapter tab. --text already re-keys per theme. */
  --nw-ink:var(--text);
  --nw-mono:var(--font-mono, ui-monospace,SFMono-Regular,Menlo,monospace);
  --nw-hair:color-mix(in srgb,var(--line) 72%,transparent);
  --nw-glass-brd:color-mix(in srgb,var(--line) 90%,transparent);
}
html{ scroll-behavior:smooth; }
/* #cm_content is switched to flex by showContent(); order:* on each section
   drives the reading order without moving any DOM node (JS + tests untouched). */
.page-committee #cm_content{ flex-direction:column; }
.page-committee .nw-hero .plain-eng{ background:color-mix(in srgb,#0a1122 58%,transparent);
  border-left-color:var(--lobe-us); color:#c9d3e4; }
.page-committee .nw-hero .plain-eng strong{ color:#dbe4f4; }

/* Ambient aurora — quotes the synapse lobe palette (the map is this page's
   signature, so the atmosphere echoes it, not macro's green/indigo). */
.nw-aurora{ position:fixed; inset:0; z-index:-2; pointer-events:none;
  background:
    radial-gradient(38% 32% at 12% 6%, color-mix(in srgb,var(--lobe-us) 16%,transparent), transparent 70%),
    radial-gradient(34% 30% at 90% 4%, color-mix(in srgb,var(--lobe-macro) 12%,transparent), transparent 70%),
    radial-gradient(48% 44% at 84% 98%, color-mix(in srgb,var(--lobe-sig) 15%,transparent), transparent 72%),
    radial-gradient(40% 40% at 4% 96%, color-mix(in srgb,var(--lobe-cn) 8%,transparent), transparent 72%);
  animation:nwAuroraDrift 36s ease-in-out infinite alternate; }
@keyframes nwAuroraDrift{ from{transform:translate3d(0,0,0) scale(1);} to{transform:translate3d(0,-2.2%,0) scale(1.06);} }
:root[data-theme="light"] .nw-aurora{ opacity:.5; }

/* Sticky chapter tabs — a floating segmented control: "jump to what you want".
   The site-nav is in-flow and scrolls away, so this pins near the top. */
.nw-subnav{ position:sticky; top:10px; z-index:60; margin:2px 0 22px; padding:6px;
  display:flex; background:color-mix(in srgb,var(--bg) 80%,transparent);
  border:1px solid var(--nw-hair); border-radius:999px;
  backdrop-filter:blur(14px) saturate(1.3); box-shadow:0 12px 32px -20px rgba(0,0,0,.7); }
.nw-subnav-inner{ display:flex; gap:4px; overflow-x:auto; scrollbar-width:none; width:100%; }
.nw-subnav-inner::-webkit-scrollbar{ display:none; }
.nw-tab{ flex:none; display:inline-flex; align-items:center; gap:7px; padding:7px 14px;
  border-radius:999px; font:600 12px/1 var(--font-ui); color:var(--muted);
  border:1px solid transparent; cursor:pointer; white-space:nowrap; text-decoration:none;
  transition:color .16s,background .16s,border-color .16s; }
.nw-tab:hover{ color:var(--text); background:color-mix(in srgb,var(--link) 9%,transparent); }
.nw-tab.is-active{ color:var(--nw-ink); background:color-mix(in srgb,var(--link) 15%,var(--panel2));
  border-color:color-mix(in srgb,var(--link) 32%,var(--line)); }
.nw-tab .tdot{ width:6px; height:6px; border-radius:50%; background:var(--accent,currentColor); opacity:.85; flex:none; }

/* Section band headers — telemetry eyebrow + a confident title. */
.nw-band{ margin:44px 2px 6px; scroll-margin-top:78px; }
.nw-eyebrow{ font:600 10.5px/1 var(--nw-mono); letter-spacing:.18em; text-transform:uppercase;
  color:color-mix(in srgb,var(--link) 72%,var(--muted)); display:inline-flex; align-items:center; gap:9px; }
.nw-eyebrow::before{ content:""; width:20px; height:1px; background:currentColor; opacity:.55; }
.nw-band-title{ font:800 21px/1.12 var(--font-ui); letter-spacing:-.02em;
  color:var(--text); text-transform:none; margin:9px 0 0; }
.nw-band-sub{ font-size:13px; color:var(--muted); margin:3px 0 0; max-width:660px; }

/* Glass cards — restyle every panel + Today's Read into frosted mx5 cards. */
.page-committee .panel,
.page-committee .tr-card{ position:relative; scroll-margin-top:78px;
  background:linear-gradient(180deg,color-mix(in srgb,var(--panel) 90%,transparent),color-mix(in srgb,var(--panel2) 94%,transparent));
  border:1px solid var(--nw-glass-brd); border-radius:16px;
  box-shadow:0 1px 0 color-mix(in srgb,#fff 4%,transparent) inset, 0 20px 44px -30px rgba(0,0,0,.65);
  backdrop-filter:blur(6px); padding:18px 20px; margin-bottom:16px;
  transition:border-color .25s,transform .25s,box-shadow .25s; }
.page-committee .panel::before{ content:""; position:absolute; left:18px; right:18px; top:0; height:1px;
  background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent,var(--link)) 55%,transparent),transparent);
  opacity:.6; }
.page-committee .panel:hover{ border-color:color-mix(in srgb,var(--accent,var(--link)) 28%,var(--nw-glass-brd));
  box-shadow:0 1px 0 color-mix(in srgb,#fff 5%,transparent) inset, 0 26px 52px -28px rgba(0,0,0,.72); }
.page-committee [data-lobe="us"]{ --accent:var(--lobe-us); }
.page-committee [data-lobe="cn"]{ --accent:var(--lobe-cn); }
.page-committee [data-lobe="sig"]{ --accent:var(--lobe-sig); }
.page-committee [data-lobe="macro"]{ --accent:var(--lobe-macro); }
.page-committee .panel-head h1{ font:800 17px/1.2 var(--font-ui); letter-spacing:-.01em; }

/* Living-brain hero. */
.page-committee .nw-hero{ position:relative; overflow:hidden; border-radius:20px;
  padding:clamp(24px,4vw,38px) clamp(20px,3.5vw,32px) 24px; margin-bottom:16px;
  border:1px solid color-mix(in srgb,var(--lobe-us) 24%,var(--line)); color:#e7ecf6;
  background:
    radial-gradient(120% 130% at 50% 34%, transparent 52%, rgba(2,3,12,.55)),
    radial-gradient(1.5px 1.5px at 18% 26%, rgba(232,240,255,.75), transparent 50%),
    radial-gradient(1.2px 1.2px at 68% 16%, rgba(214,228,255,.5), transparent 50%),
    radial-gradient(1px 1px at 86% 62%, rgba(200,216,255,.42), transparent 50%),
    radial-gradient(1px 1px at 40% 78%, rgba(190,206,255,.35), transparent 50%),
    radial-gradient(52% 62% at 14% 8%, color-mix(in srgb,var(--lobe-us) 22%,transparent), transparent 60%),
    radial-gradient(54% 64% at 90% 92%, color-mix(in srgb,var(--lobe-sig) 20%,transparent), transparent 62%),
    linear-gradient(180deg,#050818,#02030c 58%,#05060f); }
.nw-hero-eyebrow{ font:600 10.5px/1 var(--nw-mono); letter-spacing:.2em; text-transform:uppercase;
  color:color-mix(in srgb,var(--lobe-us) 78%,#cdd7ea); display:flex; align-items:center; gap:10px;
  flex-wrap:wrap; margin-bottom:16px; }
.nw-hero-eyebrow .live{ display:inline-flex; align-items:center; gap:6px; color:#c7d2e6; }
.nw-hero-eyebrow .live i{ width:7px; height:7px; border-radius:var(--r-pill, 999px); background:var(--ok); font-style:normal;
  box-shadow:0 0 0 0 transparent; animation:nwPulse 2.6s ease-out infinite; }
.page-committee .nw-hero-headline{ font:900 clamp(30px,5.6vw,54px)/1.01 var(--font-ui); letter-spacing:-.03em;
  margin:0 0 8px; background:linear-gradient(100deg,var(--lobe-us),var(--lobe-sig) 50%,var(--lobe-macro));
  -webkit-background-clip:text; background-clip:text; -webkit-text-fill-color:transparent; }
.page-committee .nw-hero-tagline{ font-size:clamp(15px,1.7vw,17px); color:#aeb9cc; font-style:normal;
  margin:0 0 18px; max-width:620px; }
.nw-hero-stance{ display:flex; align-items:center; gap:11px; padding:10px 15px; border-radius:12px;
  background:color-mix(in srgb,#0a1122 66%,transparent); border:1px solid color-mix(in srgb,var(--lobe-us) 24%,transparent);
  font-size:13.5px; line-height:1.5; color:#d3dbea; max-width:660px; margin-bottom:22px; }
.nw-hero-stance .tag{ font:700 10px/1 var(--nw-mono); letter-spacing:.12em; text-transform:uppercase;
  color:var(--lobe-macro); border:1px solid color-mix(in srgb,var(--lobe-macro) 42%,transparent);
  padding:4px 8px; border-radius:6px; flex:none; }
.page-committee .nw-stat-chips{ gap:10px; }
.page-committee .nw-chip{ background:color-mix(in srgb,#0a1122 52%,transparent);
  border:1px solid color-mix(in srgb,var(--lobe-us) 20%,transparent); border-radius:12px;
  padding:9px 14px; backdrop-filter:blur(3px); }
.page-committee .nw-chip-val{ font-family:var(--nw-mono); font-weight:800; color:#eaf0fb; }
.page-committee .nw-chip-label{ font-family:var(--nw-mono); letter-spacing:.07em; text-transform:uppercase;
  font-size:10px; color:#93a0b6; }
.page-committee .nw-chip-ok{ border-color:color-mix(in srgb,var(--up) 38%,transparent); }
.page-committee .nw-chip-ok .nw-chip-val{ color:var(--ink-up, var(--up)); }
.page-committee .nw-chip-offline{ border-color:color-mix(in srgb,var(--warn) 42%,transparent); }
.page-committee .nw-chip-offline .nw-chip-val{ color:var(--ink-warn, var(--warn)); }
.nw-hero .mp-strip{ margin-top:20px; padding-top:16px;
  border-top:1px solid color-mix(in srgb,var(--lobe-us) 16%,transparent); }
.nw-hero .mp-chip{ background:color-mix(in srgb,#0a1122 55%,transparent);
  border-color:color-mix(in srgb,var(--lobe-us) 20%,transparent); color:#d7deec; }
.nw-about{ margin-top:18px; font-size:13px; color:#9fabc0; }
.nw-about > summary{ cursor:pointer; color:#c2ccdd; font-weight:600; list-style:none;
  display:inline-flex; align-items:center; gap:7px; }
.nw-about > summary::-webkit-details-marker{ display:none; }
.nw-about > summary::before{ content:"＋"; font-family:var(--nw-mono); color:var(--lobe-us); }
.nw-about[open] > summary::before{ content:"－"; }
.nw-about p{ margin:9px 0 0; line-height:1.7; max-width:760px; }

/* Scroll reveal (upgrades the existing lazy reveal). */
.page-committee .section-lazy{ opacity:0; transform:translateY(18px);
  transition:opacity .55s cubic-bezier(.2,.7,.2,1),transform .55s cubic-bezier(.2,.7,.2,1); }
.page-committee .section-lazy.visible{ opacity:1; transform:none; }

/* Hero boot + pulse. */
@keyframes nwBoot{ from{opacity:0; transform:translateY(12px);} to{opacity:1; transform:none;} }
@keyframes nwPulse{ 0%{box-shadow:0 0 0 0 var(--ok);} 70%{box-shadow:0 0 0 8px transparent;} 100%{box-shadow:0 0 0 0 transparent;} }
.nw-hero .nw-hero-eyebrow{ animation:nwBoot .6s .04s both; }
.page-committee .nw-hero-headline{ animation:nwBoot .6s .12s both; }
.page-committee .nw-hero-tagline{ animation:nwBoot .6s .2s both; }
.nw-hero-stance{ animation:nwBoot .6s .28s both; }
.page-committee .nw-hero .nw-stat-chips{ animation:nwBoot .6s .36s both; }

@media (max-width:719px){
  .page-committee .panel,.page-committee .tr-card{ border-radius:14px; padding:15px 15px; }
  .nw-band{ margin-top:34px; }
}
@media (prefers-reduced-motion:reduce){
  html{ scroll-behavior:auto; }
  .nw-aurora{ animation:none; }
  .nw-hero-eyebrow .live i{ animation:none; }
  .page-committee .nw-hero *{ animation:none !important; }
  .page-committee .section-lazy{ transition:none; }
}

rules.new:
* { box-sizing:border-box; }
body { background:var(--bg); color:var(--text); font:14px/1.5 -apple-system,"Segoe UI",Roboto,Helvetica,sans-serif; margin:0; padding:18px; }
@media (min-width:1100px){ body{ padding:26px max(40px,calc((100vw - 1100px)/2)); } }
a { text-decoration:none; color:var(--ink-link, var(--link)); }
h1 { font-size:20px; margin:0; }
h2 { font-size:13px; margin:0 0 9px; color:var(--muted); text-transform:uppercase; letter-spacing:.06em; }
h3 { font-size:15px; margin:0 0 8px; }
.panel { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:16px 18px; margin-bottom:16px; }
.panel-head { display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:12px; }

/* ── Hero panel ── */
.nw-hero { background:linear-gradient(135deg, color-mix(in srgb,var(--link) 12%,var(--panel)) 0%, var(--panel) 60%); border:1px solid color-mix(in srgb,var(--link) 30%,var(--line)); border-radius:14px; padding:28px 24px 22px; margin-bottom:16px; }
.nw-hero-headline { font-size:clamp(28px,5vw,42px); font-weight:900; letter-spacing:-.02em; margin:0 0 6px; background:linear-gradient(120deg, var(--link) 0%, color-mix(in srgb,var(--link) 60%,var(--up)) 100%); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; line-height:1.1; }
.nw-hero-tagline { font-size:16px; color:var(--muted); margin:0 0 14px; font-style:italic; }
.nw-hero-desc { font-size:14px; line-height:1.7; max-width:760px; margin-bottom:18px; color:var(--text); }
.nw-stat-chips { display:flex; flex-wrap:wrap; gap:10px; align-items:center; }
.nw-chip { display:inline-flex; align-items:center; gap:7px; padding:7px 14px; border-radius:30px; background:color-mix(in srgb,var(--link) 10%,var(--panel2)); border:1px solid color-mix(in srgb,var(--link) 25%,var(--line)); font-size:13px; font-weight:600; backdrop-filter:blur(4px); }
.nw-chip-val { font-size:18px; font-weight:800; color:var(--ink-link, var(--link)); }
.nw-chip-label { font-size:11px; color:var(--muted); font-weight:400; margin-top:1px; }
.nw-chip-ok { border-color:color-mix(in srgb,var(--up) 35%,var(--line)); }
.nw-chip-ok .nw-chip-val { color:var(--ink-up, var(--up)); }
.nw-chip-offline { border-color:color-mix(in srgb,var(--warn) 35%,var(--line)); }
.nw-chip-offline .nw-chip-val { color:var(--ink-warn, var(--warn)); }

/* ── Auth gate ── */
#cm_gate { text-align:center; padding:48px 24px; }
#cm_gate h2 { font-size:18px; text-transform:none; letter-spacing:0; color:var(--text); margin-bottom:10px; }
#cm_gate p { color:var(--muted); max-width:480px; margin:0 auto 18px; }
.btn-primary { background:var(--link); color:#fff; border:none; border-radius:9px; padding:10px 22px; font-size:15px; font-weight:700; cursor:pointer; }
.btn-primary:hover { opacity:.88; }
#cm_content { display:none; }

/* ── Search ── */
.cm-search-wrap { position:relative; flex:1; min-width:260px; max-width:520px; }
#cm_q { width:100%; padding:10px 14px; border-radius:10px; border:1px solid var(--line); background:var(--panel2); color:var(--text); font-size:15px; outline:none; }
#cm_q:focus { border-color:var(--link); }
#cm_sugg { position:absolute; top:104%; left:0; right:0; background:var(--panel); border:1px solid var(--line); border-radius:10px; z-index:50; max-height:320px; overflow:auto; display:none; box-shadow:var(--popover-shadow,0 8px 32px rgba(0,0,0,.22)); }
#cm_sugg div { padding:8px 13px; cursor:pointer; display:flex; gap:10px; align-items:center; }
#cm_sugg div:hover, #cm_sugg div.sel { background:var(--panel2); }
#cm_sugg b { min-width:62px; flex:none; }
#cm_sugg small { color:var(--muted); flex:1; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.cm-index-count { font-size:12px; color:var(--muted); margin-top:6px; }
.cm-index-warn { background:color-mix(in srgb,var(--warn) 12%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 35%,transparent); border-radius:8px; padding:8px 12px; margin-top:8px; font-size:13px; color:var(--ink-warn, var(--warn)); display:none; }
.cm-quick-tries { display:flex; flex-wrap:wrap; gap:7px; margin-top:14px; }
.cm-quick-chip { padding:5px 12px; border-radius:20px; border:1px solid var(--line); background:var(--panel2); font-size:13px; font-weight:700; cursor:pointer; color:var(--ink-link, var(--link)); transition:background .15s; }
.cm-quick-chip:hover { background:color-mix(in srgb,var(--link) 12%,var(--panel2)); }

/* ── Committee (provenance) view ── */
.cm-ticker-header { display:flex; align-items:baseline; gap:12px; flex-wrap:wrap; margin-bottom:14px; }
.cm-ticker-sym { font-size:22px; font-weight:800; }
.cm-ticker-name { font-size:15px; color:var(--muted); }
.cm-ticker-decision { font-size:13px; color:var(--muted); }

.prov-table { width:100%; border-collapse:collapse; font-size:13px; }
.prov-table th { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); padding:6px 8px; border-bottom:1px solid var(--line); text-align:left; }
.prov-table td { padding:8px; border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent); vertical-align:top; }
.prov-table tr:last-child td { border-bottom:none; }
.prov-table tr:hover td { background:color-mix(in srgb,var(--link) 5%,transparent); }

.tier-badge { display:inline-block; padding:2px 8px; border-radius:6px; font-size:11px; font-weight:700; letter-spacing:.04em; }
.tier-DISPLAY  { background:color-mix(in srgb,var(--link) 18%,var(--panel2)); color:var(--ink-link, var(--link)); }
.tier-SHADOW   { background:color-mix(in srgb,var(--warn) 18%,var(--panel2)); color:var(--ink-warn, var(--warn)); }
.tier-UNKNOWN  { background:var(--panel2); color:var(--muted); }

.kernel-ic { font-variant-numeric:tabular-nums; }
.kernel-null { color:var(--muted); font-style:italic; }
.armed-yes { color:var(--ink-up, var(--up)); font-weight:700; }
.armed-no  { color:var(--muted); }

.stale-ok   { color:var(--ink-ok, var(--ok)); }
.stale-warn { color:var(--ink-warn, var(--warn)); }
.stale-old  { color:var(--ink-act, var(--act)); }

.source-expand { cursor:pointer; color:var(--ink-link, var(--link)); font-size:11px; user-select:none; }
.source-detail { display:none; background:var(--panel2); border-radius:7px; padding:8px 10px; font-size:11.5px; color:var(--muted); margin-top:4px; }
.source-detail.open { display:block; }

.dir-pos { color:var(--ink-up, var(--up)); font-weight:700; }
.dir-neg { color:var(--ink-down, var(--down)); font-weight:700; }
.dir-neu { color:var(--muted); }

/* ── Compliance disclaimer (fixed at bottom) ── */
.disclaimer-bar { position:fixed; bottom:0; left:0; right:0; background:color-mix(in srgb,var(--panel) 97%,transparent); border-top:1px solid var(--line); padding:7px 18px; font-size:11px; color:var(--muted); display:flex; align-items:center; gap:10px; z-index:100; backdrop-filter:blur(8px); }
.disclaimer-bar button { background:none; border:none; color:var(--muted); cursor:pointer; font-size:14px; padding:0 4px; line-height:1; }
#disc_bar { display:none; }
body { padding-bottom:56px; }

/* ── Synapse map canvas ── */
/* Deep-space backdrop (both themes — the map is deliberately a dark window even in light mode).
   Layers top→bottom: vignette, 4 tiled star layers (non-harmonic tile sizes so no visible grid),
   3 corner nebulas echoing the lobe palette, base depth gradient. Center stays darkest so the
   core's white glow and low-alpha wiring edges keep contrast. */
.graph-wrap {
  position:relative; border-radius:12px; overflow:hidden;
  background-color:#02030c;
  background-image:
    radial-gradient(ellipse 120% 100% at 50% 42%, transparent 58%, rgba(1,2,8,.55) 100%),
    radial-gradient(1.6px 1.6px at 137px 41px, rgba(230,239,255,.8), transparent 50%),
    radial-gradient(1.2px 1.2px at 23px 108px, rgba(218,231,255,.6), transparent 50%),
    radial-gradient(1px 1px at 191px 67px, rgba(214,228,255,.45), transparent 50%),
    radial-gradient(1px 1px at 79px 152px, rgba(200,216,255,.3), transparent 50%),
    radial-gradient(ellipse 55% 42% at 14% 8%, rgba(79,97,255,.13), transparent 62%),
    radial-gradient(ellipse 48% 40% at 87% 12%, rgba(56,189,248,.09), transparent 60%),
    radial-gradient(ellipse 58% 48% at 80% 98%, rgba(168,85,247,.12), transparent 62%),
    linear-gradient(180deg, #050818 0%, #02030c 48%, #030410 100%);
  background-repeat:no-repeat, repeat, repeat, repeat, repeat, no-repeat, no-repeat, no-repeat, no-repeat;
  background-size:100% 100%, 347px 347px, 289px 289px, 231px 231px, 173px 173px, 100% 100%, 100% 100%, 100% 100%, 100% 100%;
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line) 55%,transparent);
}
#graph_canvas { width:100%; height:640px; display:block; cursor:grab; touch-action:none; }
@media(max-width:719px){ #graph_canvas { height:420px; } }
#graph_canvas:active { cursor:grabbing; }
.graph-controls { position:absolute; top:10px; right:10px; display:flex; gap:5px; z-index:10; }
.gc-btn { width:32px; height:32px; border-radius:8px; border:1px solid color-mix(in srgb,var(--line) 60%,transparent); background:color-mix(in srgb,var(--panel) 70%,transparent); color:var(--text); font-size:14px; cursor:pointer; display:flex; align-items:center; justify-content:center; backdrop-filter:blur(6px); transition:background .15s; }
.gc-btn:hover { background:color-mix(in srgb,var(--link) 20%,var(--panel)); }
.graph-tooltip { position:absolute; pointer-events:none; background:color-mix(in srgb,var(--panel) 95%,transparent); border:1px solid var(--line); border-radius:10px; padding:9px 13px; font-size:12px; max-width:260px; z-index:20; display:none; backdrop-filter:blur(8px); box-shadow:0 4px 20px rgba(0,0,0,.3); line-height:1.55; }
.graph-tooltip.visible { display:block; }
.graph-tooltip strong { color:var(--ink-link, var(--link)); font-size:13px; }
.graph-info-card { position:absolute; top:50px; right:10px; width:220px; background:color-mix(in srgb,var(--panel) 95%,transparent); border:1px solid var(--line); border-radius:11px; padding:12px 14px; font-size:12px; z-index:15; display:none; backdrop-filter:blur(8px); box-shadow:0 4px 20px rgba(0,0,0,.25); max-height:calc(100% - 70px); overflow-y:auto; }
@media(max-width:719px){ .graph-info-card { position:static; width:100%; margin-top:8px; max-height:240px; } }
.graph-info-card.visible { display:block; }
.graph-info-title { font-size:14px; font-weight:700; color:var(--ink-link, var(--link)); margin-bottom:4px; }
.graph-info-type { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); margin-bottom:8px; }
.graph-info-section { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:8px 0 4px; }
.graph-nbr-chip { display:inline-block; padding:2px 8px; border-radius:12px; background:var(--panel2); border:1px solid var(--line); font-size:11px; cursor:pointer; margin:2px; color:var(--text); }
.graph-nbr-chip:hover { border-color:var(--link); color:var(--ink-link, var(--link)); }
.graph-legend { display:flex; flex-wrap:wrap; gap:10px; margin-top:10px; font-size:12px; align-items:center; }
.gl-dot { width:11px; height:11px; border-radius:50%; flex:none; display:inline-block; }
.gl-line { width:28px; height:3px; display:inline-block; vertical-align:middle; flex:none; }

/* ── Cortex memo panel ── */
.probation-banner { background:color-mix(in srgb,var(--warn) 14%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 40%,transparent); border-radius:9px; padding:10px 14px; margin-bottom:12px; font-size:13px; }
.probation-banner strong { color:var(--ink-warn, var(--warn)); }
.is-context-badge { display:inline-block; background:color-mix(in srgb,var(--info,#5b9dff) 14%,var(--panel2)); color:var(--ink-info, var(--info,#5b9dff)); font-size:10px; font-weight:700; padding:2px 8px; border-radius:6px; letter-spacing:.05em; vertical-align:middle; margin-left:8px; }
.memo-summary-card { background:var(--surface-info-subtle,var(--panel2,var(--card))); border:1px solid var(--line); border-radius:var(--r-card,12px); padding:12px 16px; margin:10px 0 14px; font-size:14px; line-height:1.7; }
.fired-list { margin:8px 0; padding-left:18px; }
.fired-list li { margin:3px 0; font-size:13px; color:var(--muted); }
.tc-chip { display:inline-block; background:var(--panel2); padding:2px 8px; border-radius:6px; font-size:12px; margin:2px; }
.memo-failed-banner { background:color-mix(in srgb,var(--warn) 14%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 40%,transparent); border-radius:9px; padding:12px 16px; margin-bottom:12px; font-size:13px; color:var(--text); }
.memo-failed-banner strong { color:var(--ink-warn, var(--warn)); }
.memo-partial-banner { background:color-mix(in srgb,var(--warn) 8%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 25%,transparent); border-radius:9px; padding:10px 14px; margin-bottom:12px; font-size:13px; }
details.memo-raw summary { cursor:pointer; font-size:12px; color:var(--muted); padding:6px 0; user-select:none; }
details.memo-raw pre { font-size:11px; overflow-x:auto; color:var(--muted); white-space:pre-wrap; }

/* ── Ask the brain ── */
.ask-box { display:flex; flex-direction:column; gap:12px; }
.ask-row { display:flex; gap:8px; align-items:flex-start; flex-wrap:wrap; }
.ask-q { flex:1; min-width:200px; padding:10px 14px; border-radius:10px; border:1px solid var(--line); background:var(--panel2); color:var(--text); font-size:14px; outline:none; resize:vertical; min-height:58px; }
.ask-q:focus { border-color:var(--link); }
.ask-ticker { width:110px; padding:10px 12px; border-radius:10px; border:1px solid var(--line); background:var(--panel2); color:var(--text); font-size:13px; outline:none; text-transform:uppercase; }
.ask-ticker:focus { border-color:var(--link); }
.ask-ticker::placeholder { text-transform:none; }
.ask-btn { padding:11px 22px; background:var(--link); color:#fff; border:none; border-radius:10px; font-size:15px; font-weight:700; cursor:pointer; white-space:nowrap; }
.ask-btn:hover:not(:disabled) { opacity:.88; }
.ask-btn:disabled { opacity:.45; cursor:default; }
.ask-charcount { font-size:11px; color:var(--muted); align-self:center; }
.ask-examples { font-size:12px; color:var(--muted); }
.ask-examples span { font-style:italic; }
.ask-state-loading { display:none; padding:14px 0; color:var(--muted); font-size:14px; }
.ask-state-loading.active { display:block; }
.ask-answer { display:none; }
.ask-answer.active { display:block; }
.ask-mode-badge { display:inline-flex; align-items:center; gap:6px; padding:3px 10px; border-radius:7px; font-size:11px; font-weight:700; letter-spacing:.05em; margin-bottom:10px; }
.ask-mode-live { background:var(--wash-ok); color:var(--ink-ok, var(--ok)); }
.ask-mode-memo { background:color-mix(in srgb,var(--warn) 16%,var(--panel2)); color:var(--ink-warn, var(--warn)); }
.ask-degraded { background:color-mix(in srgb,var(--warn) 12%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 35%,transparent); border-radius:8px; padding:8px 12px; margin-bottom:10px; font-size:13px; color:var(--ink-warn, var(--warn)); }
.ask-answer-text { font-size:14px; line-height:1.7; margin:8px 0 14px; white-space:pre-wrap; }
.ask-citations { margin:0; padding-left:18px; }
.ask-citations li { font-size:12.5px; color:var(--muted); margin:3px 0; }
.ask-citations-head { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:12px 0 5px; }
.ask-disclaimer { font-size:11px; color:var(--muted); border-top:1px solid var(--line); margin-top:12px; padding-top:8px; }
.ask-error { display:none; background:color-mix(in srgb,var(--down) 12%,var(--panel2)); border:1px solid color-mix(in srgb,var(--down) 35%,transparent); border-radius:9px; padding:10px 14px; font-size:13px; color:var(--ink-down, var(--down)); }
.ask-error.active { display:block; }
.ask-signin-msg { background:color-mix(in srgb,var(--link) 10%,var(--panel2)); border:1px solid color-mix(in srgb,var(--link) 30%,transparent); border-radius:9px; padding:10px 14px; font-size:13px; display:none; }
.ask-signin-msg.active { display:block; }

/* ── Kernel family cards ── */
.kf-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:10px; }
.kf-card { background:var(--panel2); border:1px solid var(--line); border-radius:10px; padding:12px 14px; }
.kf-name { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; margin-bottom:6px; color:var(--text); display:flex; justify-content:space-between; align-items:center; }
.kf-ic { font-size:20px; font-weight:800; font-variant-numeric:tabular-nums; }
.kf-ic.kf-pos { color:var(--ink-up, var(--up)); }
.kf-ic.kf-neg { color:var(--ink-down, var(--down)); }
.kf-ic.kf-null { color:var(--muted); font-size:14px; font-style:italic; }
.kf-sub { font-size:11px; color:var(--muted); margin-top:3px; }
.kf-armed-badge { font-size:10px; font-weight:700; padding:2px 7px; border-radius:5px; }
.kf-armed-yes { background:color-mix(in srgb,var(--up) 16%,var(--panel2)); color:var(--ink-up, var(--up)); }
.kf-armed-no  { background:var(--panel); color:var(--muted); }
.kf-stale { font-size:10.5px; color:var(--muted); margin-top:5px; }
.kf-hl { font-size:11px; color:var(--muted); margin-top:5px; }
.kf-hl-val { color:var(--ink-link, var(--link)); font-weight:600; cursor:help; }
.kf-hl .kf-null { font-style:italic; cursor:help; }
.kf-unit-chip { display:inline-block; font-size:9.5px; font-weight:700; padding:1px 6px; border-radius:5px; margin-left:6px; vertical-align:middle; background:color-mix(in srgb,var(--warn) 14%,var(--panel2)); color:var(--ink-warn, var(--warn)); cursor:help; line-height:1.5; }
.kf-spark { display:block; margin-top:6px; }
.kf-meter { height:4px; border-radius:2px; background:var(--panel); overflow:hidden; margin-top:7px; }
.kf-meter-fill { height:100%; background:color-mix(in srgb,var(--link) 55%,transparent); }
.kf-accrue-strip { background:var(--panel2); border:1px dashed var(--line); border-radius:10px; padding:9px 14px; font-size:11.5px; color:var(--muted); margin-top:10px; line-height:1.7; }
.kf-progress { margin-top:12px; font-size:11px; color:var(--muted); line-height:1.7; border-top:1px solid var(--line); padding-top:9px; }
.kf-fresh-chip { font-size:10.5px; font-weight:600; padding:2px 8px; border-radius:5px; background:var(--panel2); color:var(--muted); }
.kf-fresh-chip.kf-fresh-stale { background:color-mix(in srgb,var(--warn) 12%,var(--panel2)); color:var(--ink-warn, var(--warn)); }

/* ── Liquidity plumbing compact cells ── */
.lq-cells { display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:8px; }
.lq-cell { background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:8px 10px; }
.lq-cell-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin-bottom:3px; }
.lq-cell-val { font-size:15px; font-weight:800; font-variant-numeric:tabular-nums; }
.lq-cell-sub { font-size:10.5px; color:var(--muted); margin-top:2px; }
.lq-sec-label { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:2px 0 6px; display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.lq-state-chip { font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:5px; }

/* ── Market plane hero strip ── */
.mp-strip { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin-top:12px; }
.mp-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 11px; border-radius:20px; font-size:11.5px; font-weight:600; background:var(--panel2); border:1px solid var(--line); color:var(--text); }
.mp-pill { font-weight:800; font-size:12.5px; }
.mp-dot { width:8px; height:8px; border-radius:50%; display:inline-block; flex:none; }
.mp-sub { font-size:10px; color:var(--muted); font-weight:400; }
.mp-stale .mp-chip { opacity:.45; filter:grayscale(.7); }

/* ── Plain-English explainer box ── */
.plain-eng { background:var(--surface-info-subtle,var(--panel2,var(--card))); border:1px solid var(--line); border-radius:var(--r-card,12px); padding:12px 16px; margin:14px 0; font-size:13.5px; line-height:1.65; }
.plain-eng strong { color:var(--ink-link, var(--link)); }

/* ── Today's Read card (PR-4 M1) ── */
.tr-card { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:18px 20px; margin-bottom:16px; }
.tr-header { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px; margin-bottom:14px; }
.tr-title { font-size:16px; font-weight:800; letter-spacing:-.01em; }
.tr-asof { font-size:11px; color:var(--muted); }
.tr-tape { border:1px solid var(--line); background:var(--surface-info-subtle,var(--panel2,var(--card))); border-radius:var(--r-card,12px); padding:10px 14px; margin-bottom:12px; }
.tr-tape-primary { font-size:14px; font-weight:700; line-height:1.4; }
.tr-tape-legs { font-size:12px; color:var(--muted); margin-top:4px; }
.tr-tape-alts { font-size:12px; color:var(--muted); margin-top:2px; }
.tr-regime { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:12px; align-items:center; }
.tr-regime-chip { display:inline-flex; align-items:center; gap:5px; padding:5px 12px; border-radius:20px; background:var(--panel2); border:1px solid var(--line); font-size:12px; font-weight:600; }
.tr-regime-conf { font-size:11px; color:var(--muted); }
.tr-regime-low { border-color:color-mix(in srgb,var(--warn) 40%,var(--line)); }
.tr-regime-low .tr-regime-chip { color:var(--ink-warn, var(--warn)); }
.tr-section-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); margin-bottom:5px; }
.tr-item { display:flex; align-items:baseline; gap:7px; padding:5px 0; border-bottom:1px solid color-mix(in srgb,var(--line) 40%,transparent); font-size:13px; }
.tr-item:last-child { border-bottom:none; }
.tr-sev { font-size:10px; font-weight:700; padding:2px 6px; border-radius:5px; flex:none; }
.tr-sev-P1 { background:color-mix(in srgb,var(--down) 18%,var(--panel2)); color:var(--ink-down, var(--down)); }
.tr-sev-P2 { background:color-mix(in srgb,var(--warn) 18%,var(--panel2)); color:var(--ink-warn, var(--warn,#e6a817)); }
.tr-sev-P3 { background:var(--panel2); color:var(--muted); }
.tr-attn-block { margin-bottom:12px; }
.tr-contra-block { margin-bottom:12px; }
.tr-stale-count { font-size:12px; color:var(--muted); margin-bottom:10px; }
.tr-degraded-line { font-size:12px; color:var(--ink-warn, var(--warn,#e6a817)); padding:6px 10px; border-radius:7px; background:color-mix(in srgb,var(--warn) 10%,var(--panel2)); border:1px solid color-mix(in srgb,var(--warn) 30%,transparent); display:none; }
.tr-degraded-line.visible { display:block; }
.tr-loading { font-size:13px; color:var(--muted); padding:8px 0; }
.tr-empty { font-size:13px; color:var(--muted); font-style:italic; }

/* ── Lazy sections ── */
.section-lazy { opacity:0; transform:translateY(14px); transition:opacity .35s ease,transform .35s ease; }
.section-lazy.visible { opacity:1; transform:none; }

/* ── Empty / loading states ── */
.cm-empty { color:var(--muted); font-style:italic; padding:20px 0; text-align:center; }
.cm-loading { display:none; color:var(--muted); font-size:13px; padding:10px 0; }

/* ── NW read layer: Web Health / Disagreements / Constitution ledger ── */
.nwh-status-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 12px; border-radius:20px; font-size:12px; font-weight:800; letter-spacing:.05em; border:1px solid var(--line); }
.nwh-counts { display:flex; flex-wrap:wrap; gap:8px; margin:10px 0 12px; }
.nwh-count { background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:6px 12px; font-size:11px; color:var(--muted); }
.nwh-count b { display:block; font-size:16px; font-weight:800; line-height:1.2; }
.nwh-item { display:flex; align-items:baseline; gap:8px; padding:5px 0; border-bottom:1px solid color-mix(in srgb,var(--line) 40%,transparent); font-size:13px; }
.nwh-item:last-child { border-bottom:none; }
.nwh-dot { display:inline-block; width:10px; height:10px; border-radius:50%; flex:none; }
.contra-row { border:1px solid var(--line); background:var(--panel2); border-radius:var(--r-ctl,8px); padding:9px 12px; margin:8px 0; font-size:13px; }
.contra-row.contra-tension {  }
.contra-sev { display:inline-block; font-size:10px; font-weight:700; padding:2px 7px; border-radius:5px; letter-spacing:.05em; margin-right:7px; background:var(--panel); color:var(--muted); border:1px solid var(--line); }
.contra-sev-tension { background:color-mix(in srgb,var(--warn) 16%,var(--panel2)); color:var(--ink-warn, var(--warn)); border-color:color-mix(in srgb,var(--warn) 40%,transparent); }
.gov-row { display:flex; align-items:baseline; gap:9px; padding:7px 0; border-bottom:1px solid color-mix(in srgb,var(--line) 40%,transparent); font-size:13px; flex-wrap:wrap; }
.gov-row:last-child { border-bottom:none; }
.gov-date { font-size:11px; color:var(--muted); font-variant-numeric:tabular-nums; flex:none; }
.gov-type { font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:10.5px; font-weight:700; background:color-mix(in srgb,var(--link) 12%,var(--panel2)); color:var(--ink-link, var(--link)); padding:2px 7px; border-radius:5px; flex:none; }
.gov-target { font-weight:600; }
.gov-note { flex-basis:100%; font-size:12px; color:var(--muted); line-height:1.5; }

/* ── W1 Role badges ── */
.role-badge { display:inline-block; padding:2px 7px; border-radius:5px; font-size:10.5px; font-weight:700; letter-spacing:.04em; cursor:default; }
.role-veto    { background:color-mix(in srgb,var(--down)  18%,var(--panel2)); color:var(--ink-down, var(--down)); }
.role-alpha   { background:color-mix(in srgb,var(--up)    18%,var(--panel2)); color:var(--ink-up, var(--up)); }
.role-sizing  { background:color-mix(in srgb,var(--link)  18%,var(--panel2)); color:var(--ink-link, var(--link)); }
.role-timing  { background:color-mix(in srgb,var(--warn)  18%,var(--panel2)); color:var(--ink-warn, var(--warn)); }
.role-context { background:var(--panel); color:var(--muted); }

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .section-lazy { transition:none; }
}

/* ═══════════════════ NEURAL WEB · MX5 DESIGN LAYER ═══════════════════
   Ports the macro.html (mx5, Fable) visual language onto the Neural Web:
   glass cards, ambient aurora, a living-brain hero, sticky chapter tabs,
   and a mono "telemetry" type system grounded in the subject — a machine
   that thinks. Every motion respects prefers-reduced-motion. */
.page-committee{
  --lobe-core:#e2e8f0; --lobe-us:#4da3ff; --lobe-cn:#f0883e;
  --lobe-sig:#a78bfa; --lobe-macro:#2dd4bf;
  /* Third ink for the neural-web chapter. #eaf0fb is a DARK-plane text value and
     was serving both themes — 1.21:1 on the light panel where it carries the
     active chapter tab. --text already re-keys per theme. */
  --nw-ink:var(--text);
  --nw-mono:var(--font-mono, ui-monospace,SFMono-Regular,Menlo,monospace);
  --nw-hair:color-mix(in srgb,var(--line) 72%,transparent);
  --nw-glass-brd:color-mix(in srgb,var(--line) 90%,transparent);
}
html{ scroll-behavior:smooth; }
/* #cm_content is switched to flex by showContent(); order:* on each section
   drives the reading order without moving any DOM node (JS + tests untouched). */
.page-committee #cm_content{ flex-direction:column; }
.page-committee .nw-hero .plain-eng{ background:color-mix(in srgb,#0a1122 58%,transparent);
   color:var(--text); }
.page-committee .nw-hero .plain-eng strong{ color:#dbe4f4; }

/* Ambient aurora — quotes the synapse lobe palette (the map is this page's
   signature, so the atmosphere echoes it, not macro's green/indigo). */
.nw-aurora{ position:fixed; inset:0; z-index:-2; pointer-events:none;
  background:
    radial-gradient(38% 32% at 12% 6%, color-mix(in srgb,var(--lobe-us) 16%,transparent), transparent 70%),
    radial-gradient(34% 30% at 90% 4%, color-mix(in srgb,var(--lobe-macro) 12%,transparent), transparent 70%),
    radial-gradient(48% 44% at 84% 98%, color-mix(in srgb,var(--lobe-sig) 15%,transparent), transparent 72%),
    radial-gradient(40% 40% at 4% 96%, color-mix(in srgb,var(--lobe-cn) 8%,transparent), transparent 72%);
  animation:nwAuroraDrift 36s ease-in-out infinite alternate; }
@keyframes nwAuroraDrift{ from{transform:translate3d(0,0,0) scale(1);} to{transform:translate3d(0,-2.2%,0) scale(1.06);} }
:root[data-theme="light"] .nw-aurora{ opacity:.5; }

/* Sticky chapter tabs — a floating segmented control: "jump to what you want".
   The site-nav is in-flow and scrolls away, so this pins near the top. */
.nw-subnav{ position:sticky; top:10px; z-index:60; margin:2px 0 22px; padding:6px;
  display:flex; background:color-mix(in srgb,var(--bg) 80%,transparent);
  border:1px solid var(--nw-hair); border-radius:999px;
  backdrop-filter:blur(14px) saturate(1.3); box-shadow:0 12px 32px -20px rgba(0,0,0,.7); }
.nw-subnav-inner{ display:flex; gap:4px; overflow-x:auto; scrollbar-width:none; width:100%; }
.nw-subnav-inner::-webkit-scrollbar{ display:none; }
.nw-tab{ flex:none; display:inline-flex; align-items:center; gap:7px; padding:7px 14px;
  border-radius:999px; font:600 12px/1 var(--font-ui); color:var(--muted);
  border:1px solid transparent; cursor:pointer; white-space:nowrap; text-decoration:none;
  transition:color .16s,background .16s,border-color .16s; }
.nw-tab:hover{ color:var(--text); background:color-mix(in srgb,var(--link) 9%,transparent); }
.nw-tab.is-active{ color:var(--nw-ink); background:color-mix(in srgb,var(--link) 15%,var(--panel2));
  border-color:color-mix(in srgb,var(--link) 32%,var(--line)); }
.nw-tab .tdot{ width:6px; height:6px; border-radius:50%; background:var(--accent,currentColor); opacity:.85; flex:none; }

/* Section band headers — telemetry eyebrow + a confident title. */
.nw-band{ margin:44px 2px 6px; scroll-margin-top:78px; }
.nw-eyebrow{ font:600 10.5px/1 var(--nw-mono); letter-spacing:.18em; text-transform:uppercase;
  color:color-mix(in srgb,var(--link) 72%,var(--muted)); display:inline-flex; align-items:center; gap:9px; }
.nw-eyebrow::before{ content:""; width:20px; height:1px; background:currentColor; opacity:.55; }
.nw-band-title{ font:800 21px/1.12 var(--font-ui); letter-spacing:-.02em;
  color:var(--text); text-transform:none; margin:9px 0 0; }
.nw-band-sub{ font-size:13px; color:var(--muted); margin:3px 0 0; max-width:660px; }

/* Glass cards — restyle every panel + Today's Read into frosted mx5 cards. */
.page-committee .panel,
.page-committee .tr-card{ position:relative; scroll-margin-top:78px;
  background:linear-gradient(180deg,color-mix(in srgb,var(--panel) 90%,transparent),color-mix(in srgb,var(--panel2) 94%,transparent));
  border:1px solid var(--nw-glass-brd); border-radius:16px;
  box-shadow:0 1px 0 color-mix(in srgb,#fff 4%,transparent) inset, 0 20px 44px -30px rgba(0,0,0,.65);
  backdrop-filter:blur(6px); padding:18px 20px; margin-bottom:16px;
  transition:border-color .25s,transform .25s,box-shadow .25s; }
.page-committee .panel::before{content:none;}
.page-committee .panel:hover{ border-color:color-mix(in srgb,var(--accent,var(--link)) 28%,var(--nw-glass-brd));
  box-shadow:0 1px 0 color-mix(in srgb,#fff 5%,transparent) inset, 0 26px 52px -28px rgba(0,0,0,.72); }
.page-committee [data-lobe="us"]{ --accent:var(--lobe-us); }
.page-committee [data-lobe="cn"]{ --accent:var(--lobe-cn); }
.page-committee [data-lobe="sig"]{ --accent:var(--lobe-sig); }
.page-committee [data-lobe="macro"]{ --accent:var(--lobe-macro); }
.page-committee .panel-head h1{ font:800 17px/1.2 var(--font-ui); letter-spacing:-.01em; }

/* Living-brain hero. */
.page-committee .nw-hero{ position:relative; overflow:hidden; border-radius:20px;
  padding:clamp(24px,4vw,38px) clamp(20px,3.5vw,32px) 24px; margin-bottom:16px;
  border:1px solid color-mix(in srgb,var(--lobe-us) 24%,var(--line)); color:#e7ecf6;
  background:
    radial-gradient(120% 130% at 50% 34%, transparent 52%, rgba(2,3,12,.55)),
    radial-gradient(1.5px 1.5px at 18% 26%, rgba(232,240,255,.75), transparent 50%),
    radial-gradient(1.2px 1.2px at 68% 16%, rgba(214,228,255,.5), transparent 50%),
    radial-gradient(1px 1px at 86% 62%, rgba(200,216,255,.42), transparent 50%),
    radial-gradient(1px 1px at 40% 78%, rgba(190,206,255,.35), transparent 50%),
    radial-gradient(52% 62% at 14% 8%, color-mix(in srgb,var(--lobe-us) 22%,transparent), transparent 60%),
    radial-gradient(54% 64% at 90% 92%, color-mix(in srgb,var(--lobe-sig) 20%,transparent), transparent 62%),
    linear-gradient(180deg,#050818,#02030c 58%,#05060f); }
.nw-hero-eyebrow{ font:600 10.5px/1 var(--nw-mono); letter-spacing:.2em; text-transform:uppercase;
  color:color-mix(in srgb,var(--lobe-us) 78%,#cdd7ea); display:flex; align-items:center; gap:10px;
  flex-wrap:wrap; margin-bottom:16px; }
.nw-hero-eyebrow .live{ display:inline-flex; align-items:center; gap:6px; color:#c7d2e6; }
.nw-hero-eyebrow .live i{ width:7px; height:7px; border-radius:var(--r-pill, 999px); background:var(--ok); font-style:normal;
  box-shadow:0 0 0 0 transparent; animation:nwPulse 2.6s ease-out infinite; }
.page-committee .nw-hero-headline{ font:900 clamp(30px,5.6vw,54px)/1.01 var(--font-ui); letter-spacing:-.03em;
  margin:0 0 8px; background:linear-gradient(100deg,var(--lobe-us),var(--lobe-sig) 50%,var(--lobe-macro));
  -webkit-background-clip:text; background-clip:text; -webkit-text-fill-color:transparent; }
.page-committee .nw-hero-tagline{ font-size:clamp(15px,1.7vw,17px); color:#aeb9cc; font-style:normal;
  margin:0 0 18px; max-width:620px; }
.nw-hero-stance{ display:flex; align-items:center; gap:11px; padding:10px 15px; border-radius:12px;
  background:color-mix(in srgb,#0a1122 66%,transparent); border:1px solid color-mix(in srgb,var(--lobe-us) 24%,transparent);
  font-size:13.5px; line-height:1.5; color:#d3dbea; max-width:660px; margin-bottom:22px; }
.nw-hero-stance .tag{ font:700 10px/1 var(--nw-mono); letter-spacing:.12em; text-transform:uppercase;
  color:var(--lobe-macro); border:1px solid color-mix(in srgb,var(--lobe-macro) 42%,transparent);
  padding:4px 8px; border-radius:6px; flex:none; }
.page-committee .nw-stat-chips{ gap:10px; }
.page-committee .nw-chip{ background:color-mix(in srgb,#0a1122 52%,transparent);
  border:1px solid color-mix(in srgb,var(--lobe-us) 20%,transparent); border-radius:12px;
  padding:9px 14px; backdrop-filter:blur(3px); }
.page-committee .nw-chip-val{ font-family:var(--nw-mono); font-weight:800; color:#eaf0fb; }
.page-committee .nw-chip-label{ font-family:var(--nw-mono); letter-spacing:.07em; text-transform:uppercase;
  font-size:10px; color:#93a0b6; }
.page-committee .nw-chip-ok{ border-color:color-mix(in srgb,var(--up) 38%,transparent); }
.page-committee .nw-chip-ok .nw-chip-val{ color:var(--ink-up, var(--up)); }
.page-committee .nw-chip-offline{ border-color:color-mix(in srgb,var(--warn) 42%,transparent); }
.page-committee .nw-chip-offline .nw-chip-val{ color:var(--ink-warn, var(--warn)); }
.nw-hero .mp-strip{ margin-top:20px; padding-top:16px;
  border-top:1px solid color-mix(in srgb,var(--lobe-us) 16%,transparent); }
.nw-hero .mp-chip{ background:color-mix(in srgb,#0a1122 55%,transparent);
  border-color:color-mix(in srgb,var(--lobe-us) 20%,transparent); color:#d7deec; }
.nw-about{ margin-top:18px; font-size:13px; color:#9fabc0; }
.nw-about > summary{ cursor:pointer; color:#c2ccdd; font-weight:600; list-style:none;
  display:inline-flex; align-items:center; gap:7px; }
.nw-about > summary::-webkit-details-marker{ display:none; }
.nw-about > summary::before{ content:"＋"; font-family:var(--nw-mono); color:var(--lobe-us); }
.nw-about[open] > summary::before{ content:"－"; }
.nw-about p{ margin:9px 0 0; line-height:1.7; max-width:760px; }

/* Scroll reveal (upgrades the existing lazy reveal). */
.page-committee .section-lazy{ opacity:0; transform:translateY(18px);
  transition:opacity .55s cubic-bezier(.2,.7,.2,1),transform .55s cubic-bezier(.2,.7,.2,1); }
.page-committee .section-lazy.visible{ opacity:1; transform:none; }

/* Hero boot + pulse. */
@keyframes nwBoot{ from{opacity:0; transform:translateY(12px);} to{opacity:1; transform:none;} }
@keyframes nwPulse{ 0%{box-shadow:0 0 0 0 var(--ok);} 70%{box-shadow:0 0 0 8px transparent;} 100%{box-shadow:0 0 0 0 transparent;} }
.nw-hero .nw-hero-eyebrow{ animation:nwBoot .6s .04s both; }
.page-committee .nw-hero-headline{ animation:nwBoot .6s .12s both; }
.page-committee .nw-hero-tagline{ animation:nwBoot .6s .2s both; }
.nw-hero-stance{ animation:nwBoot .6s .28s both; }
.page-committee .nw-hero .nw-stat-chips{ animation:nwBoot .6s .36s both; }

@media (max-width:719px){
  .page-committee .panel,.page-committee .tr-card{ border-radius:14px; padding:15px 15px; }
  .nw-band{ margin-top:34px; }
}
@media (prefers-reduced-motion:reduce){
  html{ scroll-behavior:auto; }
  .nw-aurora{ animation:none; }
  .nw-hero-eyebrow .live i{ animation:none; }
  .page-committee .nw-hero *{ animation:none !important; }
  .page-committee .section-lazy{ transition:none; }
}

