  font-size:12px; font-weight:600; white-space:nowrap; cursor:pointer;
  transition:background .15s,border-color .15s,color .15s; }
.cg-more-btn:hover { border-color:var(--link); color:var(--text); }
.cg-more-btn .chev { font-size:9px; opacity:.65; transition:transform .2s; }
.cg-more-btn[aria-expanded="true"] .chev { transform:rotate(180deg); }

rules.old:
.mb-tier-watch  { color:#5b8def; font-weight:600; }
.mb-tier-limited{ color:var(--muted); }
/* front-line row accent */
tr.fl { border-left:3px solid #f59e0b; background:rgba(245,158,11,0.04); }
html[data-theme="dark"] tr.fl { background:rgba(245,158,11,0.07); }
tr.fl td:first-child { padding-left:5px; }

rules.new:
.mb-tier-watch  { color:#5b8def; font-weight:600; }
.mb-tier-limited{ color:var(--muted); }
/* Front-line rows retain a quiet surface and their entry-signal chips. */
tr.fl {  background:var(--surface-warn-subtle,var(--panel2,var(--card))); }
html[data-theme="dark"] tr.fl { background:rgba(245,158,11,0.07); }
tr.fl td:first-child { padding-left:5px; }

rules.old:
*{box-sizing:border-box}
:root{--crypto:#8d75ff;--crypto-soft:color-mix(in srgb,var(--crypto) 11%,transparent);
  --crypto-line:color-mix(in srgb,var(--crypto) 36%,var(--line));--tone:var(--muted)}
html[data-theme="light"]{--crypto:#6248d8}
body.crypto-page{margin:0;padding:18px 0 0;background:var(--bg);color:var(--text);
  font:14px/1.5 var(--font-ui);letter-spacing:-.005em}
body.crypto-page::before{opacity:.34}
.crypto-rail{width:min(1500px,calc(100% - 40px));margin:0 auto;padding:10px 0 72px}
.crypto-shelf{position:relative;margin-top:18px;border:1px solid var(--line);background:var(--panel);
  box-shadow:var(--card-shadow);overflow:hidden}
.crypto-shelf::before{content:"";position:absolute;inset:0 auto 0 0;width:2px;background:var(--crypto)}
.shelf-pad{padding:22px 24px}
.shelf-head{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}
.shelf-index,.shelf-kicker{font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--crypto)}
.shelf-title{margin:0;font-size:17px;font-weight:780;letter-spacing:-.02em}
.shelf-sub{margin-left:auto;color:var(--muted);font-size:11px}
.num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.tone-up{--tone:var(--up)}.tone-down{--tone:var(--down)}.tone-flat{--tone:var(--muted)}
.state{display:inline-flex;align-items:center;gap:7px;color:var(--tone);font-weight:720}
.state::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--tone);box-shadow:0 0 0 3px color-mix(in srgb,var(--tone) 12%,transparent)}
.muted{color:var(--muted)}

/* H1 */
.hero{background:color-mix(in srgb,var(--crypto) 3%,var(--panel))}
.hero-grid{display:grid;grid-template-columns:minmax(320px,.74fr) minmax(520px,1.26fr);gap:42px;align-items:end;padding:32px 32px 26px}
.hero-word{margin:8px 0 0;font-size:clamp(54px,7.2vw,108px);line-height:.82;letter-spacing:-.07em;font-weight:850}
.hero-stance{margin-top:25px;font-size:clamp(20px,2.2vw,32px);font-weight:780;letter-spacing:-.035em;max-width:640px}
.hero-copy{max-width:620px;margin:10px 0 0;color:var(--muted);font-size:13px}
.hero-meta{display:flex;align-items:center;gap:10px;margin-top:18px;color:var(--muted);font-size:10.5px}
.live-chip{display:inline-flex;align-items:center;gap:7px;padding:5px 9px;border:1px solid var(--crypto-line);color:var(--text)}
.live-chip i{width:5px;height:5px;border-radius:50%;background:var(--crypto)}
.hero-viz{padding-left:26px;border-left:1px solid var(--line)}
.hero-viz-head{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:12px}
.hero-viz-head b{font-size:11px;letter-spacing:.08em;text-transform:uppercase}
.hero-stats{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line);margin-bottom:12px}
.hero-stat{padding:12px 14px;border-right:1px solid var(--line)}
.hero-stat:last-child{border-right:0}.hero-stat b{display:block;font:760 20px/1.1 var(--font-mono)}
.hero-stat span{display:block;margin-top:5px;color:var(--muted);font-size:10px}
.hero-stat em{font-style:normal;color:var(--tone)}
.hero-tape .ilx{margin:0}

/* R15: scoped first-read desk; no shared tokens or Market Board styles change. */
body.crypto-page #crypto-overview{border:0;background:transparent;box-shadow:none;backdrop-filter:none;overflow:visible}
#crypto-overview .desk-page-head{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:8px 0 24px}
#crypto-overview .desk-page-title{margin:7px 0 0;font-size:var(--fs-h1,28px);font-weight:650;line-height:1.15;letter-spacing:-.035em}
#crypto-overview .desk-page-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
#crypto-overview .desk-brain-entry{font-family:var(--font-ui);background:var(--panel2);cursor:pointer}
#crypto-overview .desk-brain-entry:focus-visible{outline:2px solid var(--info);outline-offset:3px}
#crypto-overview .desk-brain-entry:hover{color:var(--ink-link,var(--link))}
#crypto-overview .desk-brain-entry:disabled{cursor:wait}
#crypto-overview .desk-brain-status{font-size:var(--fs-body,14px);color:var(--muted);line-height:1.5}
body.crypto-page.crypto-desk-ready #mmb-boot,body.crypto-page.crypto-desk-ready #mmb-launch{display:none!important}
#crypto-overview .shelf-kicker{font-size:var(--fs-sm,12.5px);font-weight:600;letter-spacing:.05em;line-height:1.5}
#crypto-overview .desk-vector-link{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:44px;padding:10px 15px;border:1px solid var(--line);border-radius:var(--r-btn,10px);color:var(--text);font-size:var(--fs-body,14px);text-decoration:none}
#crypto-overview .desk-nav{display:flex;align-items:center;flex-wrap:wrap;gap:6px 24px;border-bottom:1px solid var(--line);padding-bottom:4px}
#crypto-overview .desk-nav a{display:inline-flex;align-items:center;min-height:44px;padding:10px 0;color:var(--muted);font-size:var(--fs-body,14px);text-decoration:none;border-bottom:2px solid transparent}
#crypto-overview .desk-nav a:first-child{color:var(--text);border-color:var(--info)}
#crypto-overview a:focus-visible{outline:2px solid var(--info);outline-offset:3px;border-radius:var(--r-ctl,8px)}
#crypto-overview a:hover{color:var(--ink-link,var(--link))}
#crypto-overview .desk-lead{display:grid;grid-template-columns:minmax(0,1fr) 304px;gap:32px;padding:28px 0}
#crypto-overview .desk-lead-copy{min-width:0}
#crypto-overview .hero-stance{margin-top:8px;max-width:760px;font-size:clamp(30px,3.6vw,46px);font-weight:650;line-height:1.1;letter-spacing:-.035em;overflow-wrap:anywhere}
#crypto-overview .hero-copy{max-width:740px;font-size:var(--fs-body,14px);line-height:1.65;margin-top:12px}
#crypto-overview .hero-meta{display:flex;flex-wrap:wrap;gap:12px;font-size:var(--fs-sm,12.5px);line-height:1.5}
#crypto-overview .desk-context-rule{margin:0;align-self:center;border-left:1px solid var(--line);padding-left:22px;color:var(--text);font-size:var(--fs-body,14px);line-height:1.6}
#crypto-overview .desk-context-rule>span{display:block;margin-top:8px;color:var(--muted)}
#crypto-overview .desk-context-rule>span.l-zh{display:none}
html[data-lang="zh"] #crypto-overview .desk-context-rule>span.l-en{display:none}
html[data-lang="zh"] #crypto-overview .desk-context-rule>span.l-zh{display:block}
#crypto-overview .desk-grid{display:grid;grid-template-columns:minmax(0,1fr) 304px;gap:28px;align-items:stretch}
#crypto-overview .desk-market-panel{min-width:0;padding:22px 24px;border:1px solid var(--line);border-radius:var(--r-panel,14px);background:var(--panel)}
#crypto-overview .desk-instrument-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}
#crypto-overview .desk-instrument-head h2{margin:0;font-size:var(--fs-h2,17px);font-weight:650;line-height:1.4}
#crypto-overview .desk-instrument-head p{margin:6px 0 0;font-size:var(--fs-sm,12.5px);color:var(--muted);line-height:1.5}
#crypto-overview .desk-observation-tag{flex:none;color:var(--muted);font-size:var(--fs-sm,12.5px);padding:5px 8px;background:var(--panel2);border-radius:var(--r-ctl,8px)}
#crypto-overview .desk-market-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:24px 0 18px}
#crypto-overview .desk-market-stats>div{min-width:0}
#crypto-overview .desk-market-stats>div>span{display:block;font-size:var(--fs-sm,12.5px);color:var(--muted);line-height:1.5}
#crypto-overview .desk-market-stats b{display:block;margin:7px 0;font-size:var(--fs-num-lg,22px);font-weight:650;line-height:1.25;letter-spacing:-.025em}
#crypto-overview .desk-market-stats small{display:block;color:var(--muted);font-size:var(--fs-sm,12.5px);line-height:1.5}
#crypto-overview .desk-market-stats em{font-style:normal;color:var(--tone)}
#crypto-overview .desk-tape{min-height:240px;padding-top:8px}
#crypto-overview .desk-tape .ilx{margin:0}
/* A viewBox-length dash can clip a non-scaling stroke on a widened SVG. */
#crypto-overview .desk-tape .ilx-path{stroke-dasharray:none}
#crypto-overview .desk-chart-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:240px;text-align:center;padding:24px;gap:12px;color:var(--muted)}
#crypto-overview .desk-chart-empty p{margin:0;max-width:480px;font-size:var(--fs-body,14px);line-height:1.6}
#crypto-overview .desk-chart-foot{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--line);margin-top:18px;padding-top:12px;color:var(--muted);font-size:var(--fs-sm,12.5px)}
#crypto-overview .desk-chart-foot a,#crypto-overview .desk-next-step a{display:inline-flex;align-items:center;min-height:44px;gap:8px;color:var(--ink-link,var(--link));text-decoration:none;font-size:var(--fs-body,14px)}
#crypto-overview .desk-budget{min-width:0;padding:0 0 0 2px;display:flex;flex-direction:column}
#crypto-overview .desk-budget-head h2{margin:0;font-size:var(--fs-body,14px);font-weight:600;line-height:1.5}
#crypto-overview .desk-budget-head>span{display:block;margin-top:5px;font-size:var(--fs-sm,12.5px);color:var(--muted)}
#crypto-overview .desk-target{display:flex;align-items:baseline;flex-wrap:wrap;gap:10px;margin:18px 0}
#crypto-overview .desk-target strong{font-size:var(--fs-display,46px);font-weight:650;letter-spacing:-.04em;line-height:1.1}
#crypto-overview .desk-target>span{font-size:var(--fs-sm,12.5px);color:var(--muted)}
#crypto-overview .desk-target-rail{height:6px;border-radius:var(--r-pill,999px);background:var(--line);overflow:hidden}
#crypto-overview .desk-target-rail i{display:block;height:100%;background:var(--info)}
#crypto-overview .desk-cash{display:flex;justify-content:space-between;gap:12px;padding:12px 0;font-size:var(--fs-body,14px);color:var(--muted)}
#crypto-overview .desk-cash strong{color:var(--text);font-weight:600}
#crypto-overview .desk-budget-limit{margin:0 0 10px;color:var(--muted);font-size:var(--fs-body,14px);line-height:1.6}
#crypto-overview .desk-budget-meta{margin:4px 0 0;padding:10px 0;border-top:1px solid var(--line)}
#crypto-overview .desk-budget-meta>div{display:flex;justify-content:space-between;gap:12px;align-items:baseline;font-size:var(--fs-sm,12.5px);line-height:1.5}
#crypto-overview .desk-budget-meta dt{color:var(--muted)}
#crypto-overview .desk-budget-meta dd{margin:0}
#crypto-overview .desk-holdings-note{margin:0 0 16px;font-size:var(--fs-sm,12.5px);color:var(--muted);line-height:1.5}
#crypto-overview .desk-budget-cta{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:44px;padding:12px 15px;border:1px solid var(--line);border-radius:var(--r-btn,10px);color:var(--ink-link,var(--link));background:var(--panel2);font-size:var(--fs-body,14px);font-weight:600;text-decoration:none}
#crypto-overview .desk-next-step{border-top:1px solid var(--line);margin-top:24px;padding-top:20px}
#crypto-overview .desk-next-step h3{font-size:var(--fs-h2,17px);font-weight:600;line-height:1.4;margin:8px 0}
#crypto-overview .desk-next-step p{font-size:var(--fs-body,14px);line-height:1.6;color:var(--muted);margin:0 0 8px}
#leverage-heat [data-crypto-funding-state] .reading{font-size:var(--fs-num-lg,22px);line-height:1.3}
@media(max-width:1000px){
  #crypto-overview .desk-lead{grid-template-columns:minmax(0,1fr);gap:18px}
  #crypto-overview .desk-context-rule{border-left:0;padding:0;max-width:740px}
  #crypto-overview .desk-grid{grid-template-columns:minmax(0,1fr);gap:24px}
  #crypto-overview .desk-budget{padding:22px 24px;border:1px solid var(--line);border-radius:var(--r-panel,14px);background:var(--panel)}
}
@media(max-width:600px){
  #crypto-overview .desk-page-head{align-items:flex-start;flex-direction:column;gap:14px;padding:4px 0 18px}
  #crypto-overview .desk-page-actions{width:100%;gap:10px}
  #crypto-overview .desk-page-actions>*{flex:1}
  #crypto-overview .desk-page-title{font-size:var(--fs-num-lg,22px)}
  #crypto-overview .desk-vector-link{padding:10px;font-size:var(--fs-sm,12.5px);max-width:none;text-align:center}
  #crypto-overview .desk-nav{gap:0 18px}
  #crypto-overview .desk-lead{padding:22px 0}
  #crypto-overview .hero-stance{font-size:32px;line-height:1.15}
  #crypto-overview .desk-market-panel,#crypto-overview .desk-budget{padding:18px 16px}
  #crypto-overview .desk-instrument-head{display:block}
  #crypto-overview .desk-observation-tag{display:inline-flex;margin-top:10px}
  #crypto-overview .desk-market-stats{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px 12px;padding:20px 0 12px}
  #crypto-overview .desk-market-stats>div:first-child{grid-column:1/-1;padding-bottom:14px;border-bottom:1px solid var(--line)}
  #crypto-overview .desk-market-stats>div:first-child b{font-size:var(--fs-num-xl,38px)}
  #crypto-overview .desk-chart-foot{align-items:flex-start;flex-direction:column;gap:4px}
  #crypto-overview .desk-tape{min-height:180px}
}

/* H2 */
.market-board{border-top:1px solid var(--line)}
.market-row{display:grid;grid-template-columns:minmax(170px,1.3fr) 140px 94px minmax(150px,1fr) 115px;
  min-height:58px;align-items:center;border-bottom:1px solid var(--line)}
.market-row:last-child{border-bottom:0}
.market-row>div{padding:8px 15px;min-width:0}
.market-head{min-height:35px;background:var(--panel2);color:var(--muted);font-size:9px;font-weight:760;letter-spacing:.1em;text-transform:uppercase}
.asset{display:grid;grid-template-columns:30px 48px minmax(0,1fr);align-items:center;gap:8px}
.rank{color:var(--muted);font:650 10px/1 var(--font-mono)}
.asset b{font:780 13px/1 var(--font-mono);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.asset small{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}.asset .asset-receipt{grid-column:2/-1;margin:0;color:var(--muted);font:500 9.5px/1.3 var(--font-mono);white-space:normal;overflow-wrap:anywhere}
.market-value,.market-change{font:700 12px/1 var(--font-mono);font-variant-numeric:tabular-nums}
.market-change,.compact-chg{color:var(--muted)}.market-change.up,.compact-chg.up{color:var(--ink-up,var(--up))}.market-change.down,.compact-chg.down{color:var(--ink-down,var(--down))}
.spark-cell{height:50px;padding-block:4px!important;display:flex;align-items:center;gap:8px}.spark-cell .ilx{margin:0;height:42px;flex:1 1 auto;min-width:0}.spark-cell .ilx-tag,.spark-cell .ilx-d{display:none}
.history-null{display:inline-flex;align-items:center;height:100%;color:var(--muted);font-size:10px}
.history-chip{font:650 9px/1 var(--font-mono);padding:4px 6px;border:1px solid var(--line);color:var(--muted);margin-left:0;flex:none}
.source-line{display:flex;justify-content:space-between;gap:20px;padding:10px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:10px}
.more-market{border-top:1px solid var(--line)}.more-market summary{padding:13px 15px;cursor:pointer;font-weight:720;font-size:11px}
.compact-market{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border-top:1px solid var(--line)}
.compact-asset{display:flex;justify-content:space-between;gap:8px;padding:10px 12px;background:var(--panel);font:650 10px/1 var(--font-mono)}

/* H3/H4 */
.triptych{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line)}
.sensor{position:relative;min-height:160px;padding:20px;border-right:1px solid var(--line)}
.sensor:last-child{border-right:0}.sensor .eyebrow{color:var(--muted);font-size:9px;letter-spacing:.1em;text-transform:uppercase;font-weight:760}
body.crypto-page .qm{display:inline-grid;place-items:center;width:18px;height:18px;border:1px solid var(--line);border-radius:var(--r-pill,999px);color:var(--muted);font:700 10px/1 var(--font-ui);cursor:help;letter-spacing:0;text-transform:none;vertical-align:middle;margin:-5px 0 -5px 4px}
body.crypto-page .qm:hover,body.crypto-page .qm:focus-visible{color:var(--text);border-color:var(--crypto)}
.sensor .reading{margin-top:16px;font:780 28px/1 var(--font-mono);letter-spacing:-.04em}
.sensor .read-label{margin-top:9px}.sensor .receipt{margin-top:17px;color:var(--muted);font-size:10.5px}
.receipt-nowrap{white-space:nowrap}
.heat-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(240px,.7fr);border:1px solid var(--line)}
.heat-cards{display:grid;grid-template-columns:repeat(3,1fr)}
.heat-meter{padding:24px;border-left:1px solid var(--line);background:var(--panel2)}
.meter-score{display:flex;align-items:flex-end;justify-content:space-between;margin:20px 0 13px}
.meter-score b{font:800 42px/.9 var(--font-mono)}.meter-score span{color:var(--muted);font-size:10px}
.meter-rail{height:8px;background:var(--line);position:relative}.meter-rail i{position:absolute;inset:0 auto 0 0;background:var(--tone);width:var(--v)}
.meter-scale{display:flex;justify-content:space-between;margin-top:7px;color:var(--muted);font-size:9px}
.deriv-fold{border:1px solid var(--line);border-top:0}.deriv-fold summary{display:flex;align-items:center;gap:12px;padding:13px 16px;cursor:pointer;font-size:11px;font-weight:740}
.deriv-fold summary span:last-child{margin-left:auto;color:var(--muted);font:650 10px/1 var(--font-mono)}
.deriv-grid{display:grid;grid-template-columns:repeat(6,1fr);border-top:1px solid var(--line)}
.deriv-fact{min-height:92px;padding:15px;border-right:1px solid var(--line)}.deriv-fact:last-child{border-right:0}
.deriv-fact span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.deriv-fact b{display:block;margin-top:13px;font:760 16px/1 var(--font-mono)}
.deriv-note{padding:10px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:10px}

/* H5 */
.alloc-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr);border:1px solid var(--line)}
.alloc-main{padding:22px;border-right:1px solid var(--line)}
.alloc-top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}
.alloc-top h3{margin:0;font-size:23px;letter-spacing:-.035em}.alloc-top p{margin:6px 0 0;color:var(--muted);font-size:11px}
.exposure-big{text-align:right}.exposure-big b{display:block;font:820 46px/.9 var(--font-mono)}.exposure-big span{display:block;margin-top:8px;margin-inline-end:-.1em;font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}
.alloc-bar{display:flex;height:44px;margin:24px 0 12px;background:var(--line);overflow:hidden}
.alloc-seg{display:grid;place-items:center;min-width:0;color:white;font:760 10px/1 var(--font-mono);overflow:hidden}
.alloc-btc{background:#d97813}.alloc-eth{background:#6173d9}.alloc-alts{background:#7a5dc7}.alloc-cash{background:#65707d}
.alloc-legend{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.alloc-key{border-top:2px solid var(--line);padding-top:8px}
.alloc-key b{display:block;font:760 18px/1 var(--font-mono)}.alloc-key span{font-size:10px;color:var(--muted)}
.alloc-side{padding:22px}.alloc-side dl{margin:16px 0 0}.alloc-side div{display:flex;justify-content:space-between;gap:18px;padding:10px 0;border-bottom:1px solid var(--line)}
.alloc-side dt{color:var(--muted);font-size:10px}.alloc-side dd{margin:0;font:700 11px/1 var(--font-mono)}.alloc-side dd .receipt{display:block;margin-top:3px;font:500 9.5px/1.3 var(--font-mono);color:var(--muted)}
.alloc-note{margin-top:16px;color:var(--muted);font-size:10px}

/* Snapshot evidence is separate from the independently owned Market Board rows. */
#universe-snapshot{margin:16px 0 0;padding:14px 18px;border:1px solid var(--line);border-radius:var(--r-card,12px);background:var(--panel2);font-size:var(--fs-body,14px);line-height:1.5}
#universe-snapshot .snapshot-summary{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
#universe-snapshot p{margin:8px 0;color:var(--muted)}
#universe-snapshot summary{display:list-item;min-height:44px;padding:12px 0;cursor:pointer;color:var(--ink-link,var(--link))}
#universe-snapshot .breadth-receipt{padding:12px 0;border-top:1px solid var(--line)}
#universe-snapshot .excluded-observation{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,2fr);gap:14px;padding:12px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}
#universe-snapshot small{display:block;color:var(--muted);font-size:var(--fs-sm,12.5px)}
@media(max-width:600px){
  #universe-snapshot .excluded-observation{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
  #universe-snapshot .excluded-observation>div:last-child{grid-column:1/-1}
}
/* H5-only reading hierarchy; keep the shared shell and Market Board untouched. */
#allocation .alloc-main,#allocation .alloc-side{min-width:0}
#allocation .alloc-top p,#allocation .alloc-note{font-size:var(--fs-body,14px);line-height:1.6}
#allocation .alloc-side dt,#allocation .alloc-side dd,#allocation .source-line{font-size:var(--fs-sm,12.5px);line-height:1.5}
#allocation .alloc-side dd{text-align:right;overflow-wrap:anywhere}
#allocation .source-line a{display:inline-flex;align-items:center;min-height:44px}
@media(max-width:720px){
  #allocation .alloc-grid{grid-template-columns:minmax(0,1fr)}
  #allocation .alloc-top{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}
  #allocation .exposure-big{display:grid;justify-items:start;gap:6px;text-align:left}
  #allocation .exposure-big span{margin:0;font-size:var(--fs-sm,12.5px);white-space:nowrap;letter-spacing:normal}
  #allocation .alloc-main{border-right:0}
  #allocation .alloc-side div{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);align-items:start;gap:12px}
}


/* H6/H7/H8 */
.lane-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line)}
.asset-lane{padding:24px;border-right:1px solid var(--line);text-decoration:none;color:inherit}.asset-lane:last-child{border-right:0}
.lane-top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.lane-symbol{font:820 34px/.9 var(--font-mono);letter-spacing:-.05em}
.lane-name{margin-top:5px;color:var(--muted);font-size:10px}.lane-price{text-align:right;font:760 18px/1 var(--font-mono)}
.lane-price small{display:block;margin-top:7px;color:var(--tone);font-size:10px}
.lane-state{margin-top:24px;font-size:17px;font-weight:760}.lane-copy{min-height:42px;margin:8px 0 20px;color:var(--muted);font-size:11px}
.lane-coverage{min-height:28px;margin:-10px 0 17px;color:var(--muted);font-size:9px}
.lane-cta{font-size:10px;font-weight:740;color:var(--ink-link, var(--link))}
.equity-grid{display:grid;grid-template-columns:repeat(7,1fr);border:1px solid var(--line)}
.equity{padding:16px 14px;border-right:1px solid var(--line);text-decoration:none;color:inherit}.equity:last-child{border-right:0}
/* Rails member with no dossier page — the basket names a wider universe than
   we render. Tile and quote stay; the click does not. */
.equity-off{cursor:default}
.equity b{font:780 14px/1 var(--font-mono)}.equity .eq-price{margin-top:18px;font:720 13px/1 var(--font-mono)}
.equity .eq-change{margin-top:6px;color:var(--tone);font:680 10px/1 var(--font-mono)}.equity .state{margin-top:13px;font-size:9.5px}
.calendar-grid{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--line)}
.event{min-height:145px;padding:17px 15px;border-right:1px solid var(--line)}.event:last-child{border-right:0}
.event-date{display:flex;justify-content:space-between;color:var(--muted);font:650 9px/1 var(--font-mono)}
.event-date b{color:var(--crypto)}.event h3{margin:24px 0 7px;font-size:13px;line-height:1.2}.event p{margin:0;color:var(--muted);font-size:10px}
.page-foot{padding:26px 4px 0;color:var(--muted);font-size:10px;text-align:center}

@media(max-width:1050px){
  .hero-grid{grid-template-columns:1fr;gap:28px}.hero-viz{border-left:0;padding-left:0;border-top:1px solid var(--line);padding-top:20px}
  .heat-layout,.alloc-grid{grid-template-columns:1fr}.heat-meter,.alloc-side{border-left:0;border-top:1px solid var(--line)}
  .deriv-grid{grid-template-columns:repeat(3,1fr)}.deriv-fact{border-bottom:1px solid var(--line)}
  .equity-grid{grid-template-columns:repeat(4,1fr)}.equity{border-bottom:1px solid var(--line)}
  .calendar-grid{grid-template-columns:repeat(3,1fr)}.event{border-bottom:1px solid var(--line)}
}
@media(max-width:720px){
  body.crypto-page{padding-top:10px}.crypto-rail{width:min(100% - 20px,1500px)}.shelf-pad{padding:17px 15px}
  .hero-grid{padding:24px 17px}.hero-word{font-size:55px}.hero-stats{grid-template-columns:1fr}.hero-stat{border-right:0;border-bottom:1px solid var(--line)}
  .hero-stat:last-child{border-bottom:0}.shelf-sub{display:none}
  .market-row{grid-template-columns:minmax(145px,1.2fr) 92px 72px}.market-row>div:nth-child(4),.market-row>div:nth-child(5){display:none}
  .triptych,.heat-cards{grid-template-columns:1fr}.sensor{border-right:0;border-bottom:1px solid var(--line)}.sensor:last-child{border-bottom:0}
  .alloc-legend{grid-template-columns:repeat(2,1fr)}.lane-grid{grid-template-columns:1fr}.asset-lane{border-right:0;border-bottom:1px solid var(--line)}
  .equity-grid{grid-template-columns:repeat(2,1fr)}.calendar-grid{grid-template-columns:repeat(2,1fr)}
  .compact-market{grid-template-columns:repeat(2,1fr)}.source-line{display:block}
}


body.crypto-page,
body.page-vector {
  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display",
    "SF Pro Text", Inter, system-ui, "Segoe UI", Roboto, sans-serif;
  --font-data: Inter, -apple-system, BlinkMacSystemFont, "SF Pro Text",
    system-ui, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-data);
  --num: var(--font-data);
  --deck-accent: var(--info);
  --deck-glass: color-mix(in srgb, var(--panel) 86%, transparent);
  --deck-border: color-mix(in srgb, var(--text) 12%, transparent);
  --deck-shadow: 0 8px 32px rgba(0, 0, 0, .34),
    inset 0 1px 0 color-mix(in srgb, #fff 7%, transparent);
  --deck-hover-shadow: 0 12px 36px rgba(0, 0, 0, .40),
    inset 0 1px 0 color-mix(in srgb, #fff 9%, transparent);
  font-family: var(--font-data);
  font-size: 14px;
  line-height: 1.48;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
}

html[data-theme="light"] body.crypto-page,
html[data-theme="light"] body.page-vector {
  --deck-glass: rgba(255, 255, 255, .80);
  --deck-border: rgba(28, 36, 48, .08);
  --deck-shadow: 0 4px 20px rgba(20, 30, 50, .08),
    inset 0 1px 0 rgba(255, 255, 255, .92);
  --deck-hover-shadow: 0 8px 28px rgba(20, 30, 50, .12),
    inset 0 1px 0 rgba(255, 255, 255, .96);
}

body.crypto-page :is(h1, h2, h3, .hero-word, .hero-stance),
body.page-vector :is(h1, h2, h3, .stance, .decision-action, .exposure-band) {
  font-family: var(--font-display);
}

body.crypto-page :is(.num, .rank, .asset b, .market-value, .market-change,
  .reading, .meter-score b, .exposure-big b, .lane-symbol, .lane-price,
  .equity b, .eq-price, .event-date, .deriv-fact b),
body.page-vector :is(.num, .live-price, .live-change, .meter-score,
  .exposure-band, .risk-context b, .axis-micro b, .complex-symbol,
  .complex-value, .fold-stat, .metric .v, .fact .v, .vtm-date, .vtm-price) {
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

/* Shared page rhythm: the Macro/Commodities centered command surface. */
body.crypto-page,
html body.page-vector {
  padding-top: 24px;
}

.crypto-rail,
.vector-wrap {
  width: min(1320px, calc(100% - 40px));
  margin-inline: auto;
  padding: 18px 0 72px;
}

body.crypto-page .crypto-shelf,
body.page-vector .shelf {
  margin-top: 16px;
  border: 1px solid var(--deck-border);
  border-radius: 16px;
  background: var(--deck-glass);
  box-shadow: var(--deck-shadow);
  backdrop-filter: saturate(165%) blur(18px);
  -webkit-backdrop-filter: saturate(165%) blur(18px);
  transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;
}

body.crypto-page .crypto-shelf:hover,
body.page-vector .shelf:hover {
  border-color: color-mix(in srgb, var(--text) 18%, transparent);
  box-shadow: var(--deck-hover-shadow);
}

body.crypto-page .crypto-shelf::before,
body.page-vector .shelf::before {
  display: none;
}

body.crypto-page .shelf-pad,
body.page-vector .shelf-inner {
  padding: 18px 20px;
}

body.crypto-page .shelf-head,
body.page-vector .shelf-head {
  gap: 9px;
  margin-bottom: 13px;
}

body.crypto-page :is(.shelf-index, .shelf-kicker),
body.page-vector .shelf-kicker {
  color: var(--muted);
  font-family: var(--font-data);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .13em;
}

body.crypto-page .shelf-index,
body.page-vector .shelf-kicker {
  color: var(--deck-accent);
}

body.crypto-page .shelf-title,
body.page-vector .shelf-title {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 650;
  letter-spacing: .005em;
}

body.crypto-page .shelf-sub,
body.page-vector .shelf-sub {
  font-size: 11px;
}

body.crypto-page :is(.market-board, .triptych, .heat-layout, .deriv-fold,
  .alloc-grid, .lane-grid, .equity-grid, .calendar-grid),
body.page-vector :is(.decision-grid, .axis-board, .watch-grid, .complex-grid,
  .study-list) {
  overflow: hidden;
  border-color: var(--line);
  border-radius: 12px;
}

body.crypto-page :is(.market-row, .sensor, .deriv-fact, .asset-lane, .equity, .event),
body.page-vector :is(.axis-row, .watch-item, .complex-card, .study-fold) {
  transition: background .16s ease, border-color .16s ease;
}

body.crypto-page :is(.market-row:not(.market-head), .asset-lane, .equity, .event):hover,
body.page-vector :is(.axis-row, .watch-item, .complex-card):hover {
  background: color-mix(in srgb, var(--panel2) 70%, transparent);
}

body.crypto-page :is(.live-chip, .history-chip),
body.page-vector :is(.asof-chip, .change-chip, .strategy-tab, .vtm-btn, .vtm-tag) {
  border-radius: 999px;
}

body.crypto-page :focus-visible,
body.page-vector :focus-visible {
  outline-color: var(--deck-accent);
}

/* Crypto Intelligence: turn the oversized editorial cover into the same compact
   page header + dominant stance pattern used by Commodities. */
body.crypto-page {
  --crypto: var(--info);
  --crypto-soft: color-mix(in srgb, var(--info) 10%, transparent);
  --crypto-line: color-mix(in srgb, var(--info) 30%, var(--line));
}

body.crypto-page .hero {
  background: var(--deck-glass);
}

body.crypto-page .hero-grid {
  grid-template-columns: minmax(310px, .82fr) minmax(480px, 1.18fr);
  gap: 30px;
  align-items: center;
  padding: 26px 28px;
}

body.crypto-page .hero-word {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.15;
  font-weight: 650;
  letter-spacing: .13em;
  text-transform: uppercase;
}

body.crypto-page .hero-stance {
  max-width: 690px;
  margin-top: 18px;
  color: var(--text);
  font-size: clamp(38px, 5vw, 62px);
  line-height: .96;
  font-weight: 800;
  letter-spacing: -.035em;
  text-wrap: balance;
}

body.crypto-page .hero-copy {
  max-width: 58ch;
  margin-top: 12px;
  font-size: 13.5px;
  line-height: 1.55;
}

body.crypto-page .hero-meta {
  margin-top: 16px;
}

body.crypto-page .live-chip {
  padding: 4px 10px;
  border-color: var(--line);
  color: var(--muted);
  background: color-mix(in srgb, var(--panel2) 55%, transparent);
}

body.crypto-page .hero-viz {
  padding-left: 28px;
}

body.crypto-page .hero-stats {
  gap: 8px;
  border: 0;
  background: transparent;
}

body.crypto-page .hero-stat {
  padding: 12px 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel2) 72%, transparent);
}

body.crypto-page .hero-stat:last-child {
  border-right: 1px solid var(--line);
}

body.crypto-page .hero-stat b {
  font-size: 18px;
}

body.crypto-page .market-head {
  background: color-mix(in srgb, var(--panel2) 72%, transparent);
}

body.crypto-page .compact-market {
  background: transparent;
  gap: 8px;
  padding: 10px;
}

body.crypto-page .compact-asset {
  border: 1px solid var(--line);
  border-radius: 9px;
  background: color-mix(in srgb, var(--panel2) 68%, transparent);
}

body.crypto-page .sensor {
  min-height: 150px;
}

body.crypto-page .heat-meter,
body.crypto-page .alloc-side {
  background: color-mix(in srgb, var(--panel2) 62%, transparent);
}

body.crypto-page .meter-rail,
body.crypto-page .alloc-bar {
  border-radius: 999px;
  overflow: hidden;
}

body.crypto-page .alloc-top h3 {
  font-size: 21px;
}

body.crypto-page .alloc-key {
  border-color: var(--line);
}

body.crypto-page .lane-symbol {
  font-size: 28px;
  letter-spacing: -.035em;
}

body.crypto-page .lane-state {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 650;
}

body.crypto-page .event h3 {
  font-size: 12.5px;
}

/* Bitcoin Vector: preserve orange as the asset/data cue, while page structure,
   focus and shelf hierarchy use the shared Mastermind blue accent. */
body.page-vector {
  --btc-structural: var(--deck-accent);
}

body.page-vector .shelf::before {
  background: var(--btc-structural);
}

body.page-vector .hero {
  padding: 24px 26px 20px;
  background: transparent;
}

body.page-vector .wordmark {
  color: var(--muted);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 650;
  letter-spacing: .04em;
}

body.page-vector .wordmark .mark {
  font-family: var(--font-display);
  font-size: 22px;
}

body.page-vector .hero-read {
  grid-template-columns: minmax(0, 1fr) 270px;
  gap: 24px;
  margin: 24px 0 10px;
}

body.page-vector .stance {
  max-width: 900px;
  font-size: clamp(40px, 5.2vw, 66px);
  line-height: .95;
  font-weight: 800;
  letter-spacing: -.04em;
}

body.page-vector .hero-summary {
  margin-top: 12px;
  font-size: 13.5px;
  line-height: 1.55;
}

body.page-vector .master-meter {
  padding: 15px 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel2) 68%, transparent);
}

body.page-vector .tape-shell {
  margin-top: 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

body.page-vector .what-changed {
  margin-top: 12px;
}

body.page-vector .decision-main,
body.page-vector .decision-detail {
  padding: 22px 24px;
}

body.page-vector .decision-action {
  font-size: clamp(28px, 3.2vw, 42px);
}

body.page-vector .level,
body.page-vector :is(.study-card, .metric, .fact, .chart-card, .equity-box, .vtm-readout) {
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel2) 56%, transparent);
}

body.page-vector .study-body {
  background: color-mix(in srgb, var(--bg) 46%, transparent);
}

body.page-vector .strategy-tab.on {
  color: var(--deck-accent);
  border-color: color-mix(in srgb, var(--deck-accent) 45%, var(--line));
  background: color-mix(in srgb, var(--deck-accent) 9%, transparent);
}

body.page-vector .all-alerts {
  color: var(--ink-link, var(--link));
}

@media (prefers-reduced-motion: reduce) {
  body.crypto-page .crypto-shelf,
  body.page-vector .shelf,
  body.crypto-page :is(.market-row, .sensor, .asset-lane, .equity, .event),
  body.page-vector :is(.axis-row, .watch-item, .complex-card, .study-fold) {
    transition: none;
  }
}

@media (max-width: 1050px) {
  body.crypto-page .hero-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 780px) {
  .crypto-rail,
  .vector-wrap {
    width: min(100% - 24px, 1320px);
    padding-top: 10px;
  }

  body.crypto-page .hero-grid,
  body.page-vector .hero {
    padding: 20px 18px;
  }

  body.crypto-page .hero-viz {
    padding-left: 0;
  }

  body.crypto-page .hero-stance,
  body.page-vector .stance {
    font-size: 40px;
  }

  body.page-vector .master-meter {
    border: 1px solid var(--line);
    padding: 14px 15px;
  }
}

@media (max-width: 480px) {
  .crypto-rail,
  .vector-wrap {
    width: calc(100% - 16px);
  }

  body.crypto-page .crypto-shelf,
  body.page-vector .shelf {
    margin-top: 12px;
    border-radius: 13px;
  }

  body.crypto-page .hero-stance,
  body.page-vector .stance {
    font-size: 35px;
  }

  body.crypto-page .hero-stats {
    gap: 7px;
  }
}

rules.new:
*{box-sizing:border-box}
:root{--crypto:#8d75ff;--crypto-soft:color-mix(in srgb,var(--crypto) 11%,transparent);
  --crypto-line:color-mix(in srgb,var(--crypto) 36%,var(--line));--tone:var(--muted)}
html[data-theme="light"]{--crypto:#6248d8}
body.crypto-page{margin:0;padding:18px 0 0;background:var(--bg);color:var(--text);
  font:14px/1.5 var(--font-ui);letter-spacing:-.005em}
body.crypto-page::before{opacity:.34}
.crypto-rail{width:min(1500px,calc(100% - 40px));margin:0 auto;padding:10px 0 72px}
.crypto-shelf{position:relative;margin-top:18px;border:1px solid var(--line);background:var(--panel);
  box-shadow:var(--card-shadow);overflow:hidden}
.crypto-shelf::before{content:none;}
.shelf-pad{padding:22px 24px}
.shelf-head{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}
.shelf-index,.shelf-kicker{font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--crypto)}
.shelf-title{margin:0;font-size:17px;font-weight:780;letter-spacing:-.02em}
.shelf-sub{margin-left:auto;color:var(--muted);font-size:11px}
.num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.tone-up{--tone:var(--up)}.tone-down{--tone:var(--down)}.tone-flat{--tone:var(--muted)}
.state{display:inline-flex;align-items:center;gap:7px;color:var(--tone);font-weight:720}
.state::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--tone);box-shadow:0 0 0 3px color-mix(in srgb,var(--tone) 12%,transparent)}
.muted{color:var(--muted)}

/* H1 */
.hero{background:color-mix(in srgb,var(--crypto) 3%,var(--panel))}
.hero-grid{display:grid;grid-template-columns:minmax(320px,.74fr) minmax(520px,1.26fr);gap:42px;align-items:end;padding:32px 32px 26px}
.hero-word{margin:8px 0 0;font-size:clamp(54px,7.2vw,108px);line-height:.82;letter-spacing:-.07em;font-weight:850}
.hero-stance{margin-top:25px;font-size:clamp(20px,2.2vw,32px);font-weight:780;letter-spacing:-.035em;max-width:640px}
.hero-copy{max-width:620px;margin:10px 0 0;color:var(--muted);font-size:13px}
.hero-meta{display:flex;align-items:center;gap:10px;margin-top:18px;color:var(--muted);font-size:10.5px}
.live-chip{display:inline-flex;align-items:center;gap:7px;padding:5px 9px;border:1px solid var(--crypto-line);color:var(--text)}
.live-chip i{width:5px;height:5px;border-radius:50%;background:var(--crypto)}
.hero-viz{padding-left:26px;border-left:1px solid var(--line)}
.hero-viz-head{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:12px}
.hero-viz-head b{font-size:11px;letter-spacing:.08em;text-transform:uppercase}
.hero-stats{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line);margin-bottom:12px}
.hero-stat{padding:12px 14px;border-right:1px solid var(--line)}
.hero-stat:last-child{border-right:0}.hero-stat b{display:block;font:760 20px/1.1 var(--font-mono)}
.hero-stat span{display:block;margin-top:5px;color:var(--muted);font-size:10px}
.hero-stat em{font-style:normal;color:var(--tone)}
.hero-tape .ilx{margin:0}

/* R15: scoped first-read desk; no shared tokens or Market Board styles change. */
body.crypto-page #crypto-overview{border:0;background:transparent;box-shadow:none;backdrop-filter:none;overflow:visible}
#crypto-overview .desk-page-head{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:8px 0 24px}
#crypto-overview .desk-page-title{margin:7px 0 0;font-size:var(--fs-h1,28px);font-weight:650;line-height:1.15;letter-spacing:-.035em}
#crypto-overview .desk-page-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
#crypto-overview .desk-brain-entry{font-family:var(--font-ui);background:var(--panel2);cursor:pointer}
#crypto-overview .desk-brain-entry:focus-visible{outline:2px solid var(--info);outline-offset:3px}
#crypto-overview .desk-brain-entry:hover{color:var(--ink-link,var(--link))}
#crypto-overview .desk-brain-entry:disabled{cursor:wait}
#crypto-overview .desk-brain-status{font-size:var(--fs-body,14px);color:var(--muted);line-height:1.5}
body.crypto-page.crypto-desk-ready #mmb-boot,body.crypto-page.crypto-desk-ready #mmb-launch{display:none!important}
#crypto-overview .shelf-kicker{font-size:var(--fs-sm,12.5px);font-weight:600;letter-spacing:.05em;line-height:1.5}
#crypto-overview .desk-vector-link{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:44px;padding:10px 15px;border:1px solid var(--line);border-radius:var(--r-btn,10px);color:var(--text);font-size:var(--fs-body,14px);text-decoration:none}
#crypto-overview .desk-nav{display:flex;align-items:center;flex-wrap:wrap;gap:6px 24px;border-bottom:1px solid var(--line);padding-bottom:4px}
#crypto-overview .desk-nav a{display:inline-flex;align-items:center;min-height:44px;padding:10px 0;color:var(--muted);font-size:var(--fs-body,14px);text-decoration:none;border-bottom:2px solid transparent}
#crypto-overview .desk-nav a:first-child{color:var(--text);border-color:var(--info)}
#crypto-overview a:focus-visible{outline:2px solid var(--info);outline-offset:3px;border-radius:var(--r-ctl,8px)}
#crypto-overview a:hover{color:var(--ink-link,var(--link))}
#crypto-overview .desk-lead{display:grid;grid-template-columns:minmax(0,1fr) 304px;gap:32px;padding:28px 0}
#crypto-overview .desk-lead-copy{min-width:0}
#crypto-overview .hero-stance{margin-top:8px;max-width:760px;font-size:clamp(30px,3.6vw,46px);font-weight:650;line-height:1.1;letter-spacing:-.035em;overflow-wrap:anywhere}
#crypto-overview .hero-copy{max-width:740px;font-size:var(--fs-body,14px);line-height:1.65;margin-top:12px}
#crypto-overview .hero-meta{display:flex;flex-wrap:wrap;gap:12px;font-size:var(--fs-sm,12.5px);line-height:1.5}
#crypto-overview .desk-context-rule{margin:0;align-self:center;border-left:1px solid var(--line);padding-left:22px;color:var(--text);font-size:var(--fs-body,14px);line-height:1.6}
#crypto-overview .desk-context-rule>span{display:block;margin-top:8px;color:var(--muted)}
#crypto-overview .desk-context-rule>span.l-zh{display:none}
html[data-lang="zh"] #crypto-overview .desk-context-rule>span.l-en{display:none}
html[data-lang="zh"] #crypto-overview .desk-context-rule>span.l-zh{display:block}
#crypto-overview .desk-grid{display:grid;grid-template-columns:minmax(0,1fr) 304px;gap:28px;align-items:stretch}
#crypto-overview .desk-market-panel{min-width:0;padding:22px 24px;border:1px solid var(--line);border-radius:var(--r-panel,14px);background:var(--panel)}
#crypto-overview .desk-instrument-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}
#crypto-overview .desk-instrument-head h2{margin:0;font-size:var(--fs-h2,17px);font-weight:650;line-height:1.4}
#crypto-overview .desk-instrument-head p{margin:6px 0 0;font-size:var(--fs-sm,12.5px);color:var(--muted);line-height:1.5}
#crypto-overview .desk-observation-tag{flex:none;color:var(--muted);font-size:var(--fs-sm,12.5px);padding:5px 8px;background:var(--panel2);border-radius:var(--r-ctl,8px)}
#crypto-overview .desk-market-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:24px 0 18px}
#crypto-overview .desk-market-stats>div{min-width:0}
#crypto-overview .desk-market-stats>div>span{display:block;font-size:var(--fs-sm,12.5px);color:var(--muted);line-height:1.5}
#crypto-overview .desk-market-stats b{display:block;margin:7px 0;font-size:var(--fs-num-lg,22px);font-weight:650;line-height:1.25;letter-spacing:-.025em}
#crypto-overview .desk-market-stats small{display:block;color:var(--muted);font-size:var(--fs-sm,12.5px);line-height:1.5}
#crypto-overview .desk-market-stats em{font-style:normal;color:var(--tone)}
#crypto-overview .desk-tape{min-height:240px;padding-top:8px}
#crypto-overview .desk-tape .ilx{margin:0}
/* A viewBox-length dash can clip a non-scaling stroke on a widened SVG. */
#crypto-overview .desk-tape .ilx-path{stroke-dasharray:none}
#crypto-overview .desk-chart-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:240px;text-align:center;padding:24px;gap:12px;color:var(--muted)}
#crypto-overview .desk-chart-empty p{margin:0;max-width:480px;font-size:var(--fs-body,14px);line-height:1.6}
#crypto-overview .desk-chart-foot{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--line);margin-top:18px;padding-top:12px;color:var(--muted);font-size:var(--fs-sm,12.5px)}
#crypto-overview .desk-chart-foot a,#crypto-overview .desk-next-step a{display:inline-flex;align-items:center;min-height:44px;gap:8px;color:var(--ink-link,var(--link));text-decoration:none;font-size:var(--fs-body,14px)}
#crypto-overview .desk-budget{min-width:0;padding:0 0 0 2px;display:flex;flex-direction:column}
#crypto-overview .desk-budget-head h2{margin:0;font-size:var(--fs-body,14px);font-weight:600;line-height:1.5}
#crypto-overview .desk-budget-head>span{display:block;margin-top:5px;font-size:var(--fs-sm,12.5px);color:var(--muted)}
#crypto-overview .desk-target{display:flex;align-items:baseline;flex-wrap:wrap;gap:10px;margin:18px 0}
#crypto-overview .desk-target strong{font-size:var(--fs-display,46px);font-weight:650;letter-spacing:-.04em;line-height:1.1}
#crypto-overview .desk-target>span{font-size:var(--fs-sm,12.5px);color:var(--muted)}
#crypto-overview .desk-target-rail{height:6px;border-radius:var(--r-pill,999px);background:var(--line);overflow:hidden}
#crypto-overview .desk-target-rail i{display:block;height:100%;background:var(--info)}
#crypto-overview .desk-cash{display:flex;justify-content:space-between;gap:12px;padding:12px 0;font-size:var(--fs-body,14px);color:var(--muted)}
#crypto-overview .desk-cash strong{color:var(--text);font-weight:600}
#crypto-overview .desk-budget-limit{margin:0 0 10px;color:var(--muted);font-size:var(--fs-body,14px);line-height:1.6}
#crypto-overview .desk-budget-meta{margin:4px 0 0;padding:10px 0;border-top:1px solid var(--line)}
#crypto-overview .desk-budget-meta>div{display:flex;justify-content:space-between;gap:12px;align-items:baseline;font-size:var(--fs-sm,12.5px);line-height:1.5}
#crypto-overview .desk-budget-meta dt{color:var(--muted)}
#crypto-overview .desk-budget-meta dd{margin:0}
#crypto-overview .desk-holdings-note{margin:0 0 16px;font-size:var(--fs-sm,12.5px);color:var(--muted);line-height:1.5}
#crypto-overview .desk-budget-cta{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:44px;padding:12px 15px;border:1px solid var(--line);border-radius:var(--r-btn,10px);color:var(--ink-link,var(--link));background:var(--panel2);font-size:var(--fs-body,14px);font-weight:600;text-decoration:none}
#crypto-overview .desk-next-step{border-top:1px solid var(--line);margin-top:24px;padding-top:20px}
#crypto-overview .desk-next-step h3{font-size:var(--fs-h2,17px);font-weight:600;line-height:1.4;margin:8px 0}
#crypto-overview .desk-next-step p{font-size:var(--fs-body,14px);line-height:1.6;color:var(--muted);margin:0 0 8px}
#leverage-heat [data-crypto-funding-state] .reading{font-size:var(--fs-num-lg,22px);line-height:1.3}
@media(max-width:1000px){
  #crypto-overview .desk-lead{grid-template-columns:minmax(0,1fr);gap:18px}
  #crypto-overview .desk-context-rule{border-left:0;padding:0;max-width:740px}
  #crypto-overview .desk-grid{grid-template-columns:minmax(0,1fr);gap:24px}
  #crypto-overview .desk-budget{padding:22px 24px;border:1px solid var(--line);border-radius:var(--r-panel,14px);background:var(--panel)}
}
@media(max-width:600px){
  #crypto-overview .desk-page-head{align-items:flex-start;flex-direction:column;gap:14px;padding:4px 0 18px}
  #crypto-overview .desk-page-actions{width:100%;gap:10px}
  #crypto-overview .desk-page-actions>*{flex:1}
  #crypto-overview .desk-page-title{font-size:var(--fs-num-lg,22px)}
  #crypto-overview .desk-vector-link{padding:10px;font-size:var(--fs-sm,12.5px);max-width:none;text-align:center}
  #crypto-overview .desk-nav{gap:0 18px}
  #crypto-overview .desk-lead{padding:22px 0}
  #crypto-overview .hero-stance{font-size:32px;line-height:1.15}
  #crypto-overview .desk-market-panel,#crypto-overview .desk-budget{padding:18px 16px}
  #crypto-overview .desk-instrument-head{display:block}
  #crypto-overview .desk-observation-tag{display:inline-flex;margin-top:10px}
  #crypto-overview .desk-market-stats{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px 12px;padding:20px 0 12px}
  #crypto-overview .desk-market-stats>div:first-child{grid-column:1/-1;padding-bottom:14px;border-bottom:1px solid var(--line)}
  #crypto-overview .desk-market-stats>div:first-child b{font-size:var(--fs-num-xl,38px)}
  #crypto-overview .desk-chart-foot{align-items:flex-start;flex-direction:column;gap:4px}
  #crypto-overview .desk-tape{min-height:180px}
}

/* H2 */
.market-board{border-top:1px solid var(--line)}
.market-row{display:grid;grid-template-columns:minmax(170px,1.3fr) 140px 94px minmax(150px,1fr) 115px;
  min-height:58px;align-items:center;border-bottom:1px solid var(--line)}
.market-row:last-child{border-bottom:0}
.market-row>div{padding:8px 15px;min-width:0}
.market-head{min-height:35px;background:var(--panel2);color:var(--muted);font-size:9px;font-weight:760;letter-spacing:.1em;text-transform:uppercase}
.asset{display:grid;grid-template-columns:30px 48px minmax(0,1fr);align-items:center;gap:8px}
.rank{color:var(--muted);font:650 10px/1 var(--font-mono)}
.asset b{font:780 13px/1 var(--font-mono);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.asset small{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}.asset .asset-receipt{grid-column:2/-1;margin:0;color:var(--muted);font:500 9.5px/1.3 var(--font-mono);white-space:normal;overflow-wrap:anywhere}
.market-value,.market-change{font:700 12px/1 var(--font-mono);font-variant-numeric:tabular-nums}
.market-change,.compact-chg{color:var(--muted)}.market-change.up,.compact-chg.up{color:var(--ink-up,var(--up))}.market-change.down,.compact-chg.down{color:var(--ink-down,var(--down))}
.spark-cell{height:50px;padding-block:4px!important;display:flex;align-items:center;gap:8px}.spark-cell .ilx{margin:0;height:42px;flex:1 1 auto;min-width:0}.spark-cell .ilx-tag,.spark-cell .ilx-d{display:none}
.history-null{display:inline-flex;align-items:center;height:100%;color:var(--muted);font-size:10px}
.history-chip{font:650 9px/1 var(--font-mono);padding:4px 6px;border:1px solid var(--line);color:var(--muted);margin-left:0;flex:none}
.source-line{display:flex;justify-content:space-between;gap:20px;padding:10px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:10px}
.more-market{border-top:1px solid var(--line)}.more-market summary{padding:13px 15px;cursor:pointer;font-weight:720;font-size:11px}
.compact-market{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border-top:1px solid var(--line)}
.compact-asset{display:flex;justify-content:space-between;gap:8px;padding:10px 12px;background:var(--panel);font:650 10px/1 var(--font-mono)}

/* H3/H4 */
.triptych{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line)}
.sensor{position:relative;min-height:160px;padding:20px;border-right:1px solid var(--line)}
.sensor:last-child{border-right:0}.sensor .eyebrow{color:var(--muted);font-size:9px;letter-spacing:.1em;text-transform:uppercase;font-weight:760}
body.crypto-page .qm{display:inline-grid;place-items:center;width:18px;height:18px;border:1px solid var(--line);border-radius:var(--r-pill,999px);color:var(--muted);font:700 10px/1 var(--font-ui);cursor:help;letter-spacing:0;text-transform:none;vertical-align:middle;margin:-5px 0 -5px 4px}
body.crypto-page .qm:hover,body.crypto-page .qm:focus-visible{color:var(--text);border-color:var(--crypto)}
.sensor .reading{margin-top:16px;font:780 28px/1 var(--font-mono);letter-spacing:-.04em}
.sensor .read-label{margin-top:9px}.sensor .receipt{margin-top:17px;color:var(--muted);font-size:10.5px}
.receipt-nowrap{white-space:nowrap}
.heat-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(240px,.7fr);border:1px solid var(--line)}
.heat-cards{display:grid;grid-template-columns:repeat(3,1fr)}
.heat-meter{padding:24px;border-left:1px solid var(--line);background:var(--panel2)}
.meter-score{display:flex;align-items:flex-end;justify-content:space-between;margin:20px 0 13px}
.meter-score b{font:800 42px/.9 var(--font-mono)}.meter-score span{color:var(--muted);font-size:10px}
.meter-rail{height:8px;background:var(--line);position:relative}.meter-rail i{position:absolute;inset:0 auto 0 0;background:var(--tone);width:var(--v)}
.meter-scale{display:flex;justify-content:space-between;margin-top:7px;color:var(--muted);font-size:9px}
.deriv-fold{border:1px solid var(--line);border-top:0}.deriv-fold summary{display:flex;align-items:center;gap:12px;padding:13px 16px;cursor:pointer;font-size:11px;font-weight:740}
.deriv-fold summary span:last-child{margin-left:auto;color:var(--muted);font:650 10px/1 var(--font-mono)}
.deriv-grid{display:grid;grid-template-columns:repeat(6,1fr);border-top:1px solid var(--line)}
.deriv-fact{min-height:92px;padding:15px;border-right:1px solid var(--line)}.deriv-fact:last-child{border-right:0}
.deriv-fact span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.deriv-fact b{display:block;margin-top:13px;font:760 16px/1 var(--font-mono)}
.deriv-note{padding:10px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:10px}

/* H5 */
.alloc-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr);border:1px solid var(--line)}
.alloc-main{padding:22px;border-right:1px solid var(--line)}
.alloc-top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}
.alloc-top h3{margin:0;font-size:23px;letter-spacing:-.035em}.alloc-top p{margin:6px 0 0;color:var(--muted);font-size:11px}
.exposure-big{text-align:right}.exposure-big b{display:block;font:820 46px/.9 var(--font-mono)}.exposure-big span{display:block;margin-top:8px;margin-inline-end:-.1em;font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}
.alloc-bar{display:flex;height:44px;margin:24px 0 12px;background:var(--line);overflow:hidden}
.alloc-seg{display:grid;place-items:center;min-width:0;color:white;font:760 10px/1 var(--font-mono);overflow:hidden}
.alloc-btc{background:#d97813}.alloc-eth{background:#6173d9}.alloc-alts{background:#7a5dc7}.alloc-cash{background:#65707d}
.alloc-legend{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.alloc-key{border-top:2px solid var(--line);padding-top:8px}
.alloc-key b{display:block;font:760 18px/1 var(--font-mono)}.alloc-key span{font-size:10px;color:var(--muted)}
.alloc-side{padding:22px}.alloc-side dl{margin:16px 0 0}.alloc-side div{display:flex;justify-content:space-between;gap:18px;padding:10px 0;border-bottom:1px solid var(--line)}
.alloc-side dt{color:var(--muted);font-size:10px}.alloc-side dd{margin:0;font:700 11px/1 var(--font-mono)}.alloc-side dd .receipt{display:block;margin-top:3px;font:500 9.5px/1.3 var(--font-mono);color:var(--muted)}
.alloc-note{margin-top:16px;color:var(--muted);font-size:10px}

/* Snapshot evidence is separate from the independently owned Market Board rows. */
#universe-snapshot{margin:16px 0 0;padding:14px 18px;border:1px solid var(--line);border-radius:var(--r-card,12px);background:var(--panel2);font-size:var(--fs-body,14px);line-height:1.5}
#universe-snapshot .snapshot-summary{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
#universe-snapshot p{margin:8px 0;color:var(--muted)}
#universe-snapshot summary{display:list-item;min-height:44px;padding:12px 0;cursor:pointer;color:var(--ink-link,var(--link))}
#universe-snapshot .breadth-receipt{padding:12px 0;border-top:1px solid var(--line)}
#universe-snapshot .excluded-observation{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,2fr);gap:14px;padding:12px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}
#universe-snapshot small{display:block;color:var(--muted);font-size:var(--fs-sm,12.5px)}
@media(max-width:600px){
  #universe-snapshot .excluded-observation{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
  #universe-snapshot .excluded-observation>div:last-child{grid-column:1/-1}
}
/* H5-only reading hierarchy; keep the shared shell and Market Board untouched. */
#allocation .alloc-main,#allocation .alloc-side{min-width:0}
#allocation .alloc-top p,#allocation .alloc-note{font-size:var(--fs-body,14px);line-height:1.6}
#allocation .alloc-side dt,#allocation .alloc-side dd,#allocation .source-line{font-size:var(--fs-sm,12.5px);line-height:1.5}
#allocation .alloc-side dd{text-align:right;overflow-wrap:anywhere}
#allocation .source-line a{display:inline-flex;align-items:center;min-height:44px}
@media(max-width:720px){
  #allocation .alloc-grid{grid-template-columns:minmax(0,1fr)}
  #allocation .alloc-top{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}
  #allocation .exposure-big{display:grid;justify-items:start;gap:6px;text-align:left}
  #allocation .exposure-big span{margin:0;font-size:var(--fs-sm,12.5px);white-space:nowrap;letter-spacing:normal}
  #allocation .alloc-main{border-right:0}
  #allocation .alloc-side div{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);align-items:start;gap:12px}
}


/* H6/H7/H8 */
.lane-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line)}
.asset-lane{padding:24px;border-right:1px solid var(--line);text-decoration:none;color:inherit}.asset-lane:last-child{border-right:0}
.lane-top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.lane-symbol{font:820 34px/.9 var(--font-mono);letter-spacing:-.05em}
.lane-name{margin-top:5px;color:var(--muted);font-size:10px}.lane-price{text-align:right;font:760 18px/1 var(--font-mono)}
.lane-price small{display:block;margin-top:7px;color:var(--tone);font-size:10px}
.lane-state{margin-top:24px;font-size:17px;font-weight:760}.lane-copy{min-height:42px;margin:8px 0 20px;color:var(--muted);font-size:11px}
.lane-coverage{min-height:28px;margin:-10px 0 17px;color:var(--muted);font-size:9px}
.lane-cta{font-size:10px;font-weight:740;color:var(--ink-link, var(--link))}
.equity-grid{display:grid;grid-template-columns:repeat(7,1fr);border:1px solid var(--line)}
.equity{padding:16px 14px;border-right:1px solid var(--line);text-decoration:none;color:inherit}.equity:last-child{border-right:0}
/* Rails member with no dossier page — the basket names a wider universe than
   we render. Tile and quote stay; the click does not. */
.equity-off{cursor:default}
.equity b{font:780 14px/1 var(--font-mono)}.equity .eq-price{margin-top:18px;font:720 13px/1 var(--font-mono)}
.equity .eq-change{margin-top:6px;color:var(--tone);font:680 10px/1 var(--font-mono)}.equity .state{margin-top:13px;font-size:9.5px}
.calendar-grid{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--line)}
.event{min-height:145px;padding:17px 15px;border-right:1px solid var(--line)}.event:last-child{border-right:0}
.event-date{display:flex;justify-content:space-between;color:var(--muted);font:650 9px/1 var(--font-mono)}
.event-date b{color:var(--crypto)}.event h3{margin:24px 0 7px;font-size:13px;line-height:1.2}.event p{margin:0;color:var(--muted);font-size:10px}
.page-foot{padding:26px 4px 0;color:var(--muted);font-size:10px;text-align:center}

@media(max-width:1050px){
  .hero-grid{grid-template-columns:1fr;gap:28px}.hero-viz{border-left:0;padding-left:0;border-top:1px solid var(--line);padding-top:20px}
  .heat-layout,.alloc-grid{grid-template-columns:1fr}.heat-meter,.alloc-side{border-left:0;border-top:1px solid var(--line)}
  .deriv-grid{grid-template-columns:repeat(3,1fr)}.deriv-fact{border-bottom:1px solid var(--line)}
  .equity-grid{grid-template-columns:repeat(4,1fr)}.equity{border-bottom:1px solid var(--line)}
  .calendar-grid{grid-template-columns:repeat(3,1fr)}.event{border-bottom:1px solid var(--line)}
}
@media(max-width:720px){
  body.crypto-page{padding-top:10px}.crypto-rail{width:min(100% - 20px,1500px)}.shelf-pad{padding:17px 15px}
  .hero-grid{padding:24px 17px}.hero-word{font-size:55px}.hero-stats{grid-template-columns:1fr}.hero-stat{border-right:0;border-bottom:1px solid var(--line)}
  .hero-stat:last-child{border-bottom:0}.shelf-sub{display:none}
  .market-row{grid-template-columns:minmax(145px,1.2fr) 92px 72px}.market-row>div:nth-child(4),.market-row>div:nth-child(5){display:none}
  .triptych,.heat-cards{grid-template-columns:1fr}.sensor{border-right:0;border-bottom:1px solid var(--line)}.sensor:last-child{border-bottom:0}
  .alloc-legend{grid-template-columns:repeat(2,1fr)}.lane-grid{grid-template-columns:1fr}.asset-lane{border-right:0;border-bottom:1px solid var(--line)}
  .equity-grid{grid-template-columns:repeat(2,1fr)}.calendar-grid{grid-template-columns:repeat(2,1fr)}
  .compact-market{grid-template-columns:repeat(2,1fr)}.source-line{display:block}
}


body.crypto-page,
body.page-vector {
  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display",
    "SF Pro Text", Inter, system-ui, "Segoe UI", Roboto, sans-serif;
  --font-data: Inter, -apple-system, BlinkMacSystemFont, "SF Pro Text",
    system-ui, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-data);
  --num: var(--font-data);
  --deck-accent: var(--info);
  --deck-glass: color-mix(in srgb, var(--panel) 86%, transparent);
  --deck-border: color-mix(in srgb, var(--text) 12%, transparent);
  --deck-shadow: 0 8px 32px rgba(0, 0, 0, .34),
    inset 0 1px 0 color-mix(in srgb, #fff 7%, transparent);
  --deck-hover-shadow: 0 12px 36px rgba(0, 0, 0, .40),
    inset 0 1px 0 color-mix(in srgb, #fff 9%, transparent);
  font-family: var(--font-data);
  font-size: 14px;
  line-height: 1.48;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
}

html[data-theme="light"] body.crypto-page,
html[data-theme="light"] body.page-vector {
  --deck-glass: rgba(255, 255, 255, .80);
  --deck-border: rgba(28, 36, 48, .08);
  --deck-shadow: 0 4px 20px rgba(20, 30, 50, .08),
    inset 0 1px 0 rgba(255, 255, 255, .92);
  --deck-hover-shadow: 0 8px 28px rgba(20, 30, 50, .12),
    inset 0 1px 0 rgba(255, 255, 255, .96);
}

body.crypto-page :is(h1, h2, h3, .hero-word, .hero-stance),
body.page-vector :is(h1, h2, h3, .stance, .decision-action, .exposure-band) {
  font-family: var(--font-display);
}

body.crypto-page :is(.num, .rank, .asset b, .market-value, .market-change,
  .reading, .meter-score b, .exposure-big b, .lane-symbol, .lane-price,
  .equity b, .eq-price, .event-date, .deriv-fact b),
body.page-vector :is(.num, .live-price, .live-change, .meter-score,
  .exposure-band, .risk-context b, .axis-micro b, .complex-symbol,
  .complex-value, .fold-stat, .metric .v, .fact .v, .vtm-date, .vtm-price) {
  font-family: var(--font-data);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

/* Shared page rhythm: the Macro/Commodities centered command surface. */
body.crypto-page,
html body.page-vector {
  padding-top: 24px;
}

.crypto-rail,
.vector-wrap {
  width: min(1320px, calc(100% - 40px));
  margin-inline: auto;
  padding: 18px 0 72px;
}

body.crypto-page .crypto-shelf,
body.page-vector .shelf {
  margin-top: 16px;
  border: 1px solid var(--deck-border);
  border-radius: 16px;
  background: var(--deck-glass);
  box-shadow: var(--deck-shadow);
  backdrop-filter: saturate(165%) blur(18px);
  -webkit-backdrop-filter: saturate(165%) blur(18px);
  transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;
}

body.crypto-page .crypto-shelf:hover,
body.page-vector .shelf:hover {
  border-color: color-mix(in srgb, var(--text) 18%, transparent);
  box-shadow: var(--deck-hover-shadow);
}

body.crypto-page .crypto-shelf::before,
body.page-vector .shelf::before {
  display: none;
}

body.crypto-page .shelf-pad,
body.page-vector .shelf-inner {
  padding: 18px 20px;
}

body.crypto-page .shelf-head,
body.page-vector .shelf-head {
  gap: 9px;
  margin-bottom: 13px;
}

body.crypto-page :is(.shelf-index, .shelf-kicker),
body.page-vector .shelf-kicker {
  color: var(--muted);
  font-family: var(--font-data);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .13em;
}

body.crypto-page .shelf-index,
body.page-vector .shelf-kicker {
  color: var(--deck-accent);
}

body.crypto-page .shelf-title,
body.page-vector .shelf-title {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 650;
  letter-spacing: .005em;
}

body.crypto-page .shelf-sub,
body.page-vector .shelf-sub {
  font-size: 11px;
}

body.crypto-page :is(.market-board, .triptych, .heat-layout, .deriv-fold,
  .alloc-grid, .lane-grid, .equity-grid, .calendar-grid),
body.page-vector :is(.decision-grid, .axis-board, .watch-grid, .complex-grid,
  .study-list) {
  overflow: hidden;
  border-color: var(--line);
  border-radius: 12px;
}

body.crypto-page :is(.market-row, .sensor, .deriv-fact, .asset-lane, .equity, .event),
body.page-vector :is(.axis-row, .watch-item, .complex-card, .study-fold) {
  transition: background .16s ease, border-color .16s ease;
}

body.crypto-page :is(.market-row:not(.market-head), .asset-lane, .equity, .event):hover,
body.page-vector :is(.axis-row, .watch-item, .complex-card):hover {
  background: color-mix(in srgb, var(--panel2) 70%, transparent);
}

body.crypto-page :is(.live-chip, .history-chip),
body.page-vector :is(.asof-chip, .change-chip, .strategy-tab, .vtm-btn, .vtm-tag) {
  border-radius: 999px;
}

body.crypto-page :focus-visible,
body.page-vector :focus-visible {
  outline-color: var(--deck-accent);
}

/* Crypto Intelligence: turn the oversized editorial cover into the same compact
   page header + dominant stance pattern used by Commodities. */
body.crypto-page {
  --crypto: var(--info);
  --crypto-soft: color-mix(in srgb, var(--info) 10%, transparent);
  --crypto-line: color-mix(in srgb, var(--info) 30%, var(--line));
}

body.crypto-page .hero {
  background: var(--deck-glass);
}

body.crypto-page .hero-grid {
  grid-template-columns: minmax(310px, .82fr) minmax(480px, 1.18fr);
  gap: 30px;
  align-items: center;
  padding: 26px 28px;
}

body.crypto-page .hero-word {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.15;
  font-weight: 650;
  letter-spacing: .13em;
  text-transform: uppercase;
}

body.crypto-page .hero-stance {
  max-width: 690px;
  margin-top: 18px;
  color: var(--text);
  font-size: clamp(38px, 5vw, 62px);
  line-height: .96;
  font-weight: 800;
  letter-spacing: -.035em;
  text-wrap: balance;
}

body.crypto-page .hero-copy {
  max-width: 58ch;
  margin-top: 12px;
  font-size: 13.5px;
  line-height: 1.55;
}

body.crypto-page .hero-meta {
  margin-top: 16px;
}

body.crypto-page .live-chip {
  padding: 4px 10px;
  border-color: var(--line);
  color: var(--muted);
  background: color-mix(in srgb, var(--panel2) 55%, transparent);
}

body.crypto-page .hero-viz {
  padding-left: 28px;
}

body.crypto-page .hero-stats {
  gap: 8px;
  border: 0;
  background: transparent;
}

body.crypto-page .hero-stat {
  padding: 12px 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel2) 72%, transparent);
}

body.crypto-page .hero-stat:last-child {
  border-right: 1px solid var(--line);
}

body.crypto-page .hero-stat b {
  font-size: 18px;
}

body.crypto-page .market-head {
  background: color-mix(in srgb, var(--panel2) 72%, transparent);
}

body.crypto-page .compact-market {
  background: transparent;
  gap: 8px;
  padding: 10px;
}

body.crypto-page .compact-asset {
  border: 1px solid var(--line);
  border-radius: 9px;
  background: color-mix(in srgb, var(--panel2) 68%, transparent);
}

body.crypto-page .sensor {
  min-height: 150px;
}

body.crypto-page .heat-meter,
body.crypto-page .alloc-side {
  background: color-mix(in srgb, var(--panel2) 62%, transparent);
}

body.crypto-page .meter-rail,
body.crypto-page .alloc-bar {
  border-radius: 999px;
  overflow: hidden;
}

body.crypto-page .alloc-top h3 {
  font-size: 21px;
}

body.crypto-page .alloc-key {
  border-color: var(--line);
}

body.crypto-page .lane-symbol {
  font-size: 28px;
  letter-spacing: -.035em;
}

body.crypto-page .lane-state {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 650;
}

body.crypto-page .event h3 {
  font-size: 12.5px;
}

/* Bitcoin Vector: preserve orange as the asset/data cue, while page structure,
   focus and shelf hierarchy use the shared Mastermind blue accent. */
body.page-vector {
  --btc-structural: var(--deck-accent);
}

body.page-vector .shelf::before {
  background: var(--btc-structural);
}

body.page-vector .hero {
  padding: 24px 26px 20px;
  background: transparent;
}

body.page-vector .wordmark {
  color: var(--muted);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 650;
  letter-spacing: .04em;
}

body.page-vector .wordmark .mark {
  font-family: var(--font-display);
  font-size: 22px;
}

body.page-vector .hero-read {
  grid-template-columns: minmax(0, 1fr) 270px;
  gap: 24px;
  margin: 24px 0 10px;
}

body.page-vector .stance {
  max-width: 900px;
  font-size: clamp(40px, 5.2vw, 66px);
  line-height: .95;
  font-weight: 800;
  letter-spacing: -.04em;
}

body.page-vector .hero-summary {
  margin-top: 12px;
  font-size: 13.5px;
  line-height: 1.55;
}

body.page-vector .master-meter {
  padding: 15px 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel2) 68%, transparent);
}

body.page-vector .tape-shell {
  margin-top: 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

body.page-vector .what-changed {
  margin-top: 12px;
}

body.page-vector .decision-main,
body.page-vector .decision-detail {
  padding: 22px 24px;
}

body.page-vector .decision-action {
  font-size: clamp(28px, 3.2vw, 42px);
}

body.page-vector .level,
body.page-vector :is(.study-card, .metric, .fact, .chart-card, .equity-box, .vtm-readout) {
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel2) 56%, transparent);
}

body.page-vector .study-body {
  background: color-mix(in srgb, var(--bg) 46%, transparent);
}

body.page-vector .strategy-tab.on {
  color: var(--deck-accent);
  border-color: color-mix(in srgb, var(--deck-accent) 45%, var(--line));
  background: color-mix(in srgb, var(--deck-accent) 9%, transparent);
}

body.page-vector .all-alerts {
  color: var(--ink-link, var(--link));
}

@media (prefers-reduced-motion: reduce) {
  body.crypto-page .crypto-shelf,
  body.page-vector .shelf,
  body.crypto-page :is(.market-row, .sensor, .asset-lane, .equity, .event),
  body.page-vector :is(.axis-row, .watch-item, .complex-card, .study-fold) {
    transition: none;
  }
}

@media (max-width: 1050px) {
  body.crypto-page .hero-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 780px) {
  .crypto-rail,
  .vector-wrap {
    width: min(100% - 24px, 1320px);
    padding-top: 10px;
  }

  body.crypto-page .hero-grid,
  body.page-vector .hero {
    padding: 20px 18px;
  }

  body.crypto-page .hero-viz {
    padding-left: 0;
  }

  body.crypto-page .hero-stance,
  body.page-vector .stance {
    font-size: 40px;
  }

  body.page-vector .master-meter {
    border: 1px solid var(--line);
    padding: 14px 15px;
  }
}

@media (max-width: 480px) {
  .crypto-rail,
  .vector-wrap {
    width: calc(100% - 16px);
  }

  body.crypto-page .crypto-shelf,
  body.page-vector .shelf {
    margin-top: 12px;
    border-radius: 13px;
  }

  body.crypto-page .hero-stance,
  body.page-vector .stance {
    font-size: 35px;
  }

  body.crypto-page .hero-stats {
    gap: 7px;
  }
}

rules.old:
.crypto-shelf{position:relative;margin-top:18px;border:1px solid var(--line);background:var(--panel);
  box-shadow:var(--card-shadow);overflow:hidden}
.crypto-shelf::before{content:"";position:absolute;inset:0 auto 0 0;width:2px;background:var(--crypto)}
.shelf-pad{padding:22px 24px}
.shelf-head{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}

rules.new:
.crypto-shelf{position:relative;margin-top:18px;border:1px solid var(--line);background:var(--panel);
  box-shadow:var(--card-shadow);overflow:hidden}
.crypto-shelf::before{content:none;}
.shelf-pad{padding:22px 24px}
.shelf-head{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}

rules.old:
  * { box-sizing:border-box; }
  body { background:var(--bg); color:var(--text); font:15px/1.5 Inter,-apple-system,"Segoe UI",Roboto,Helvetica,sans-serif; margin:0; padding:0; overflow-x:hidden; }
  .site-nav { width:min(1200px,calc(100% - 36px)); margin-top:18px; }
  .dp-shell { width:min(1180px,calc(100% - 36px)); margin:0 auto 40px; }
  a { text-decoration:none; color:inherit; }
  h2 { margin:0; }
  .muted { color:var(--muted); }
  .sm { font-size:12px; }

  /* lean identity hues — the page's organising colour language.
     --acc (accumulation/up) & --dis (distribution/down) are DIRECTION reads →
     they swap under html[data-lang="zh"] per the house 红涨绿跌 ruling.
     --unc (amber) & --dpb (blue) are non-directional → they never swap. */
  :root { --ink:#e8edf4; --faint:#828b9c; --acc:#2dd4a7; --dis:#e5738a; --unc:#e0a44a; --dpb:#8b96f8; }
  html[data-theme="light"] { --ink:#0f1622; --faint:#5f6a7a; --acc:#0f9b7a; --dis:#cf5570; --unc:#b9791a; --dpb:#4559dc; }
  html[data-lang="zh"] { --acc:#e5738a; --dis:#2dd4a7; }
  html[data-theme="light"][data-lang="zh"] { --acc:#cf5570; --dis:#0f9b7a; }

  /* ---------- hero ---------- */
  .dp-hero { padding:26px 0 4px; animation:dpUp .55s cubic-bezier(.2,.7,.3,1) both; }
  .dp-brand { display:flex; align-items:center; gap:11px; font-weight:800; font-size:26px; color:var(--ink); letter-spacing:-.02em; }
  .dp-mark { width:30px; height:30px; flex:none; }
  .dp-mark svg { display:block; width:30px; height:30px; }
  .dp-brand .gn { background:linear-gradient(96deg,var(--acc),var(--dpb) 60%,var(--unc)); -webkit-background-clip:text; background-clip:text; color:transparent; }
  .dp-sub { color:var(--muted); font-size:14px; margin:5px 0 0; max-width:640px; }
  .dp-verdict { font-size:clamp(20px,3vw,28px); font-weight:800; color:var(--ink); letter-spacing:-.022em; line-height:1.3; margin:18px 0 4px; max-width:900px; }
  .dp-asof { display:inline-flex; align-items:center; flex-wrap:wrap; gap:6px 8px; font-size:12px; line-height:1.45; color:var(--muted); margin-top:8px; }
  .dp-asof { max-width:100%; }
  .dp-asof .l-en,.dp-asof .l-zh { white-space:normal; min-width:0; }
  .dp-dot { width:7px; height:7px; border-radius:50%; background:var(--up); animation:dpBreathe 2.8s ease-in-out infinite; flex:none; }
  .dp-census { display:flex; flex-wrap:wrap; gap:7px; margin-top:10px; font-size:11.5px; color:var(--muted); }
  .dp-census span { padding:4px 9px; border:1px solid var(--line); border-radius:999px; background:var(--panel); }
  .dp-census b { color:var(--ink); font-variant-numeric:tabular-nums; }
  .session-badge { display:inline-flex; margin-left:7px; padding:2px 6px; border-radius:999px; border:1px solid color-mix(in srgb,var(--unc) 45%,var(--line)); color:var(--unc); font-size:9.5px; font-weight:750; white-space:nowrap; vertical-align:middle; }
  tr.is-stale td { color:color-mix(in srgb,var(--muted) 86%,transparent); }

  /* ---------- market gauge ---------- */
  .dp-gauge { margin:16px 0 2px; }
  .gg { display:inline-flex; align-items:baseline; gap:11px; flex-wrap:wrap; padding:11px 16px; border-radius:13px; border:1px solid var(--line); background:var(--panel); }
  .gg-k { font-size:11.5px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; color:var(--muted); }
  .gg-v { font-size:22px; font-weight:800; color:var(--ink); font-variant-numeric:tabular-nums; letter-spacing:-.02em; }
  .gg-n { font-size:12px; color:var(--muted); }

  /* ---------- coverage / limits ---------- */
  .dp-limits { margin:30px 0 0; padding:15px 17px; border:1px solid var(--line); border-radius:13px; background:var(--panel); }
  .dp-limits .lh { font-size:10.5px; font-weight:800; letter-spacing:.09em; text-transform:uppercase; color:var(--muted); margin-bottom:8px; }
  .dp-limits ul { margin:0; padding-left:17px; }
  .dp-limits li { font-size:12.5px; color:var(--muted); line-height:1.6; }
  .dp-limits b { color:var(--ink); font-weight:700; font-variant-numeric:tabular-nums; }

  /* ---------- what changed ---------- */
  .dp-changes { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:22px 0 2px; }
  .dp-changes .eb { font-size:10.5px; font-weight:800; letter-spacing:.09em; text-transform:uppercase; color:var(--muted); margin-right:2px; }
  .cchip { display:inline-flex; align-items:center; gap:7px; padding:6px 13px; border-radius:999px; border:1px solid var(--line); background:var(--panel); font-size:12.5px; font-weight:600; color:var(--ink); }
  .cchip .cd { width:6px; height:6px; border-radius:50%; background:var(--unc); flex:none; animation:dpBreathe 2.2s ease-in-out infinite; }
  .cchip.calm { color:var(--muted); font-weight:500; }
  .cchip.calm .cd { background:var(--up); }

  /* ---------- section chrome ---------- */
  .sec { display:flex; align-items:baseline; gap:11px; margin:36px 0 3px; flex-wrap:wrap; }
  .sec .sd { width:8px; height:8px; border-radius:2px; background:var(--sc,var(--faint)); align-self:center; flex:none; }
  .sec h2 { font-size:12px; font-weight:800; color:var(--ink); text-transform:uppercase; letter-spacing:.08em; }
  .sec .cnt { font-size:12px; color:var(--faint); font-weight:600; }
  .sec-sub { font-size:13px; color:var(--muted); margin:2px 0 15px; max-width:820px; }

  /* ---------- lean rail (the thesis + glance) ---------- */
  .rail { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
  @media(max-width:820px){ .rail { grid-template-columns:1fr; } }
  .lc { position:relative; background:var(--panel); border:1px solid var(--line); border-radius:16px; padding:18px 18px 16px; overflow:hidden; animation:dpUp .55s cubic-bezier(.2,.7,.3,1) both; }
  .lc::before { content:''; position:absolute; inset:0 0 auto 0; height:3px; background:var(--c); }
  .lc.acc { --c:var(--acc); } .lc.dis { --c:var(--dis); } .lc.unc { --c:var(--unc); }
  .lc:nth-child(2){ animation-delay:.05s; } .lc:nth-child(3){ animation-delay:.1s; }
  /* prints settling into the dark — cheap opacity-only ambient */
  .pool { position:absolute; right:14px; top:15px; width:52px; height:42px; opacity:.5; pointer-events:none; }
  .pool i { position:absolute; width:4px; height:4px; border-radius:50%; background:var(--c); opacity:0; animation:dpSink 3.6s ease-in infinite; }
  .pool i:nth-child(1){ left:5px; animation-delay:0s; } .pool i:nth-child(2){ left:19px; animation-delay:.9s; }
  .pool i:nth-child(3){ left:33px; animation-delay:1.8s; } .pool i:nth-child(4){ left:46px; animation-delay:2.6s; }
  .lc-k { display:flex; align-items:center; gap:8px; font-size:11.5px; font-weight:800; letter-spacing:.05em; text-transform:uppercase; color:var(--c); }
  .lc-state { font-size:23px; font-weight:800; color:var(--ink); letter-spacing:-.02em; margin:11px 0 2px; line-height:1.12; }
  .lc-state small { font-size:14px; color:var(--muted); font-weight:600; }
  .lc-read { font-size:12.5px; color:var(--muted); line-height:1.5; margin:6px 0 0; }
  .lc-names { display:flex; flex-wrap:wrap; gap:5px; margin-top:12px; }
  .tag { display:inline-block; padding:3px 9px; border-radius:7px; font-size:11.5px; font-weight:700; font-variant-numeric:tabular-nums; background:color-mix(in srgb,var(--c) 13%,var(--panel)); color:var(--c); }
  .lc-foot { display:flex; align-items:center; justify-content:space-between; margin-top:14px; padding-top:12px; border-top:1px solid var(--line); }
  .stance { display:inline-flex; align-items:center; gap:6px; padding:5px 13px; border-radius:999px; font-size:12px; font-weight:700; background:color-mix(in srgb,var(--c) 11%,var(--panel)); color:var(--c); border:1px solid color-mix(in srgb,var(--c) 28%,var(--line)); }
  .stance .sdot { background:currentColor; width:6px; height:6px; border-radius:50%; animation:dpBreathe 2.4s ease-in-out infinite; flex:none; }

  /* ---------- standouts board (actionable payload) ---------- */
  .board { display:grid; grid-template-columns:1fr 1fr; gap:13px; }
  @media(max-width:760px){ .board { grid-template-columns:1fr; } }
  .name { position:relative; background:var(--panel); border:1px solid var(--line); border-radius:15px; padding:15px 17px; overflow:hidden; transition:transform .16s ease,border-color .2s ease,box-shadow .2s ease; animation:dpUp .5s cubic-bezier(.2,.7,.3,1) both; }
  .name:hover { transform:translateY(-2px); border-color:color-mix(in srgb,var(--c) 45%,var(--line)); box-shadow:0 12px 30px -18px rgba(0,0,0,.5); }
  .name::before { content:''; position:absolute; inset:0 auto 0 0; width:3px; background:var(--c); }
  .name.acc { --c:var(--acc); } .name.dis { --c:var(--dis); } .name.unc { --c:var(--unc); }
  .n-top { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; }
  .n-tk { font-size:19px; font-weight:800; color:var(--ink); letter-spacing:-.01em; }
  .n-lean { display:inline-flex; align-items:center; gap:6px; padding:4px 11px; border-radius:999px; font-size:11px; font-weight:700; white-space:nowrap; background:color-mix(in srgb,var(--c) 13%,var(--panel)); color:var(--c); border:1px solid color-mix(in srgb,var(--c) 32%,var(--line)); }
  /* depth meter — the signature: how much of the day's volume went dark */
  .n-depth { margin:15px 0 4px; }
  .n-depth .dl { display:flex; justify-content:space-between; font-size:10.5px; color:var(--muted); font-weight:600; letter-spacing:.02em; margin-bottom:6px; }
  .n-depth .dl b { color:var(--ink); font-size:12.5px; font-variant-numeric:tabular-nums; }
  .dtrack { position:relative; height:10px; border-radius:6px; background:repeating-linear-gradient(90deg,color-mix(in srgb,var(--line) 60%,transparent) 0 2px,transparent 2px 7px); border:1px solid var(--line); overflow:visible; }
  .dfill { position:absolute; inset:0 auto 0 0; border-radius:5px; background:linear-gradient(90deg,color-mix(in srgb,var(--c) 22%,transparent),color-mix(in srgb,var(--c) 60%,transparent)); animation:dpGrow .8s cubic-bezier(.2,.7,.3,1) both; transform-origin:left; }
  .dnorm { position:absolute; top:-3px; bottom:-3px; width:2px; background:var(--ink); opacity:.5; border-radius:2px; }
  .dnorm::after { content:attr(data-le); position:absolute; top:-13px; left:50%; transform:translateX(-50%); font-size:8px; color:var(--faint); font-weight:700; letter-spacing:.03em; white-space:nowrap; }
  html[data-lang="zh"] .dnorm::after { content:attr(data-lz); }
  .n-facts { display:flex; gap:16px; margin-top:13px; flex-wrap:wrap; }
  .nf { font-size:11px; color:var(--muted); }
  .nf b { display:block; font-size:13px; color:var(--ink); font-weight:700; font-variant-numeric:tabular-nums; margin-top:1px; }
  .nf b.up { color:var(--dis); } .nf b.dn { color:var(--acc); }
  .n-read { font-size:12px; color:var(--muted); line-height:1.45; margin-top:11px; padding-top:11px; border-top:1px solid color-mix(in srgb,var(--line) 70%,transparent); }
  .n-read b { color:var(--text); font-weight:600; }

  /* ---------- venue flow ---------- */
  .vcard { background:var(--panel); border:1px solid var(--line); border-radius:16px; padding:16px 20px; }
  .vrow { display:grid; grid-template-columns:minmax(150px,1.1fr) 2fr 132px; align-items:center; gap:14px; padding:9px 0; }
  .vrow + .vrow { border-top:1px solid color-mix(in srgb,var(--line) 60%,transparent); }
  @media(max-width:620px){ .vrow { grid-template-columns:1fr 96px; } .vtrack { display:none; } }
  .vn { font-size:13px; font-weight:700; color:var(--ink); }
  .vn .mp { display:block; font-size:10.5px; font-weight:500; color:var(--faint); margin-top:1px; letter-spacing:.02em; }
  .vtrack { position:relative; height:9px; background:color-mix(in srgb,var(--line) 55%,var(--panel)); border-radius:999px; overflow:hidden; }
  .vfill { position:absolute; inset:0 auto 0 0; border-radius:999px; background:linear-gradient(90deg,color-mix(in srgb,var(--dpb) 28%,transparent),color-mix(in srgb,var(--dpb) 60%,transparent)); animation:dpGrow .8s cubic-bezier(.2,.7,.3,1) both; transform-origin:left; }
  .vfill.mover { background:linear-gradient(90deg,color-mix(in srgb,var(--acc) 32%,transparent),color-mix(in srgb,var(--acc) 64%,transparent)); }
  .vwow { justify-self:end; display:inline-flex; align-items:center; gap:7px; font-size:12px; font-weight:700; font-variant-numeric:tabular-nums; white-space:nowrap; }
  .vpct { color:var(--ink); }
  .vd { font-size:11.5px; font-weight:700; } .vd.u { color:var(--acc); } .vd.dn { color:var(--dis); } .vd.f { color:var(--faint); }
  .vnew { font-size:9.5px; font-weight:800; letter-spacing:.04em; text-transform:uppercase; color:var(--acc); background:color-mix(in srgb,var(--acc) 12%,var(--panel)); padding:2px 7px; border-radius:6px; }

  /* ---------- quiet state ---------- */
  .dp-quiet { background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:22px; color:var(--muted); font-size:14px; line-height:1.6; }

  /* ---------- shelves (go deeper: desk + method) ---------- */
  .shelf details { background:var(--panel); border:1px solid var(--line); border-radius:14px; margin-top:12px; overflow:hidden; }
  .shelf summary { list-style:none; cursor:pointer; padding:15px 20px; display:flex; align-items:center; gap:12px; font-size:14px; font-weight:700; color:var(--ink); }
  .shelf summary::-webkit-details-marker { display:none; }
  .shelf summary:hover { background:color-mix(in srgb,var(--dpb) 5%,var(--panel)); }
  .shelf summary .si { flex:none; width:26px; height:26px; border-radius:8px; display:flex; align-items:center; justify-content:center; font-size:13px; background:color-mix(in srgb,var(--dpb) 10%,var(--panel)); }
  .shelf summary .sh { margin-left:auto; font-size:11.5px; font-weight:600; color:var(--faint); }
  .shelf summary .sc { flex:none; font-size:11px; color:var(--faint); transition:transform .25s; }
  .shelf details[open] summary .sc { transform:rotate(90deg); }
  .shelf .sb { padding:6px 20px 20px; border-top:1px solid var(--line); }
  .method { font-size:13px; color:var(--muted); line-height:1.7; max-width:840px; }
  .method p { margin:8px 0; }
  .method b { color:var(--ink); }

  .disc { font-size:12px; color:var(--muted); margin:28px 0 0; padding-top:14px; border-top:1px solid var(--line); line-height:1.6; }

  /* ---------- desk (demoted) ---------- */
  .tbl-wrap { overflow-x:auto; margin-top:10px; max-width:100%; -webkit-overflow-scrolling:touch; }
  table.dp-tbl { border-collapse:collapse; width:100%; font-size:12.5px; }
  table.dp-tbl th { color:var(--muted); font-weight:600; font-size:11px; text-transform:uppercase; letter-spacing:.04em; padding:6px 8px; border-bottom:1px solid var(--line); text-align:right; white-space:nowrap; cursor:pointer; user-select:none; }
  table.dp-tbl th:first-child { text-align:left; }
  table.dp-tbl th.sort-asc::after { content:' ▲'; font-size:9px; }
  table.dp-tbl th.sort-desc::after { content:' ▼'; font-size:9px; }
  table.dp-tbl td { padding:5px 8px; border-bottom:1px solid var(--line); text-align:right; font-variant-numeric:tabular-nums; }
  table.dp-tbl td:first-child { text-align:left; font-weight:600; color:var(--ink); }
  table.dp-tbl tr:hover td { background:var(--panel2); }
  .num-pos { color:var(--ink-up, var(--up)); } .num-neg { color:var(--ink-down, var(--down)); } .num-neu { color:var(--muted); }
  .norm-chip { display:inline-block; font-size:10.5px; padding:1px 7px; border-radius:12px; white-space:nowrap; }
  .norm-hi2 { background:rgba(220,50,50,.14); color:var(--ink-down, var(--down)); } .norm-hi1 { background:rgba(220,50,50,.07); color:var(--ink-down, var(--down)); }
  .norm-mid { background:var(--panel2); color:var(--muted); }
  .norm-lo1 { background:rgba(35,134,54,.07); color:var(--ink-up, var(--up)); } .norm-lo2 { background:rgba(35,134,54,.14); color:var(--ink-up, var(--up)); }
  .spark-cell { min-width:90px; } svg.spark { display:block; overflow:visible; }
  .filters-row { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:10px 0; }
  .dp-input, .dp-select { background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:5px 10px; font-size:13px; color:var(--text); outline:none; }
  .dp-input::placeholder { color:var(--muted); }
  #dp-search { max-width:200px; } #dp-min-share { max-width:110px; }
  .clear-btn, .export-btn { font-size:12px; color:var(--muted); cursor:pointer; padding:4px 8px; border:1px solid var(--line); border-radius:8px; background:none; }
  .clear-btn:hover, .export-btn:hover { border-color:var(--text); color:var(--text); }
  .export-btn { margin-left:auto; }
  .row-count { font-size:11.5px; color:var(--muted); margin-bottom:6px; }
  .presets-row { display:flex; flex-wrap:wrap; gap:6px; margin:4px 0 10px; }
  .chip { display:inline-flex; align-items:center; font-size:11.5px; padding:2px 9px; border-radius:20px; border:1px solid var(--line); background:var(--panel2); color:var(--muted); white-space:normal; max-width:100%; }
  .chip.preset { cursor:pointer; user-select:none; }
  .chip.preset:hover { background:var(--panel2); border-color:var(--text); color:var(--text); }
  .chip.preset.active { background:var(--dpb); border-color:transparent; color:#fff; }
  .tip-wrap { display:inline-flex; align-items:center; justify-content:center; width:15px; height:15px; border-radius:50%; border:1px solid var(--muted); color:var(--muted); font-size:9px; font-weight:700; cursor:help; position:relative; vertical-align:middle; margin-left:3px; }
  .tip-pop { display:none; position:absolute; top:140%; left:50%; transform:translateX(-50%); width:min(260px,calc(100vw - 32px)); background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:9px 12px; z-index:80; font-size:12px; line-height:1.5; color:var(--text); box-shadow:0 4px 16px rgba(0,0,0,.18); pointer-events:none; white-space:normal; overflow-wrap:break-word; font-weight:400; text-transform:none; letter-spacing:0; }
  .tip-wrap:hover .tip-pop { display:block; }

  /* ---------- motion ---------- */
  @keyframes dpUp { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:none} }
  @keyframes dpBreathe { 0%,100%{opacity:.45;transform:scale(.85)} 50%{opacity:1;transform:scale(1.1)} }
  @keyframes dpGrow { from{transform:scaleX(0)} to{transform:scaleX(1)} }
  @keyframes dpSink { 0%{opacity:0;transform:translateY(-6px)} 25%{opacity:.9} 70%{opacity:.5} 100%{opacity:0;transform:translateY(28px)} }
  @media(max-width:900px){ .pool { display:none; } }
  @media(prefers-reduced-motion:reduce){ .dp-hero,.lc,.name,.dfill,.vfill,.dp-dot,.cchip .cd,.stance .sdot,.pool i { animation:none; } * { transition:none !important; } }

  @media (max-width:900px) { .sc-hide { display:none; } }
  @media (max-width:640px) { .sc-hide-sm { display:none; } }
  @media (max-width:480px) { .sc-hide-xs { display:none; } }

/* Native browse controls: one compact desk, keyboard/touch parity in both themes. */
.shelf summary.dp-desk-summary{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:4px 12px}
.dp-desk-summary .si{grid-column:1;grid-row:1 / span 2}
.dp-desk-summary .dp-desk-title{grid-column:2;min-width:0}
.shelf summary.dp-desk-summary .sh{grid-column:2;grid-row:2;margin-left:0}
.dp-desk-summary .sc{grid-column:3;grid-row:1 / span 2}
.presets-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.presets-row .chip.preset{min-height:40px;white-space:normal;text-align:center;justify-content:center;padding:6px 8px;font:inherit;font-size:12px;line-height:1.3;touch-action:manipulation}
.presets-row .chip.preset.active{color:var(--ink);background:var(--panel2);border-color:var(--dpb);font-weight:700}
.filters-row{display:grid;grid-template-columns:minmax(120px,1.2fr) minmax(100px,.8fr) repeat(2,minmax(145px,1fr)) auto auto;align-items:end}
.dp-filter{display:flex;flex-direction:column;gap:4px;min-width:0}
.dp-filter label{font-size:11px;font-weight:600;color:var(--muted)}
.dp-filter .dp-input,.dp-filter .dp-select{width:100%;min-width:0;min-height:40px}
.filters-row .clear-btn,.filters-row .export-btn{min-height:40px;touch-action:manipulation}
.dp-sort{border:0;padding:4px 0;min-height:40px;background:transparent;color:inherit;font:inherit;letter-spacing:inherit;text-transform:inherit;cursor:pointer;touch-action:manipulation}
#dp-table th[data-col]{cursor:default}
/* Keep the stock identity visible while browsing the wide data table. */
#dp-table th:first-child,#dp-table tr:not(.dp-empty)>td:first-child{position:sticky;left:0;z-index:1;background:var(--panel);box-shadow:1px 0 0 var(--line)}
#dp-table th:first-child{z-index:2}
#dp-table tr:not(.dp-empty):hover>td:first-child{background:var(--panel2)}
.presets-row .preset:focus-visible,.filters-row :is(input,select,button):focus-visible,#dp-table .dp-sort:focus-visible,.dp-desk-summary:focus-visible{outline:2px solid currentColor;outline-offset:2px}
#dp-table .dp-empty td{text-align:left;padding:16px 8px;font-weight:400;white-space:normal;color:var(--muted)}
@media(max-width:820px){.filters-row{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.presets-row{grid-template-columns:repeat(2,minmax(0,1fr))}}

rules.new:
  * { box-sizing:border-box; }
  body { background:var(--bg); color:var(--text); font:15px/1.5 Inter,-apple-system,"Segoe UI",Roboto,Helvetica,sans-serif; margin:0; padding:0; overflow-x:hidden; }
  .site-nav { width:min(1200px,calc(100% - 36px)); margin-top:18px; }
  .dp-shell { width:min(1180px,calc(100% - 36px)); margin:0 auto 40px; }
  a { text-decoration:none; color:inherit; }
  h2 { margin:0; }
  .muted { color:var(--muted); }
  .sm { font-size:12px; }

  /* lean identity hues — the page's organising colour language.
     --acc (accumulation/up) & --dis (distribution/down) are DIRECTION reads →
     they swap under html[data-lang="zh"] per the house 红涨绿跌 ruling.
     --unc (amber) & --dpb (blue) are non-directional → they never swap. */
  :root { --ink:#e8edf4; --faint:#828b9c; --acc:#2dd4a7; --dis:#e5738a; --unc:#e0a44a; --dpb:#8b96f8; }
  html[data-theme="light"] { --ink:#0f1622; --faint:#5f6a7a; --acc:#0f9b7a; --dis:#cf5570; --unc:#b9791a; --dpb:#4559dc; }
  html[data-lang="zh"] { --acc:#e5738a; --dis:#2dd4a7; }
  html[data-theme="light"][data-lang="zh"] { --acc:#cf5570; --dis:#0f9b7a; }

  /* ---------- hero ---------- */
  .dp-hero { padding:26px 0 4px; animation:dpUp .55s cubic-bezier(.2,.7,.3,1) both; }
  .dp-brand { display:flex; align-items:center; gap:11px; font-weight:800; font-size:26px; color:var(--ink); letter-spacing:-.02em; }
  .dp-mark { width:30px; height:30px; flex:none; }
  .dp-mark svg { display:block; width:30px; height:30px; }
  .dp-brand .gn { background:linear-gradient(96deg,var(--acc),var(--dpb) 60%,var(--unc)); -webkit-background-clip:text; background-clip:text; color:transparent; }
  .dp-sub { color:var(--muted); font-size:14px; margin:5px 0 0; max-width:640px; }
  .dp-verdict { font-size:clamp(20px,3vw,28px); font-weight:800; color:var(--ink); letter-spacing:-.022em; line-height:1.3; margin:18px 0 4px; max-width:900px; }
  .dp-asof { display:inline-flex; align-items:center; flex-wrap:wrap; gap:6px 8px; font-size:12px; line-height:1.45; color:var(--muted); margin-top:8px; }
  .dp-asof { max-width:100%; }
  .dp-asof .l-en,.dp-asof .l-zh { white-space:normal; min-width:0; }
  .dp-dot { width:7px; height:7px; border-radius:50%; background:var(--up); animation:dpBreathe 2.8s ease-in-out infinite; flex:none; }
  .dp-census { display:flex; flex-wrap:wrap; gap:7px; margin-top:10px; font-size:11.5px; color:var(--muted); }
  .dp-census span { padding:4px 9px; border:1px solid var(--line); border-radius:999px; background:var(--panel); }
  .dp-census b { color:var(--ink); font-variant-numeric:tabular-nums; }
  .session-badge { display:inline-flex; margin-left:7px; padding:2px 6px; border-radius:999px; border:1px solid color-mix(in srgb,var(--unc) 45%,var(--line)); color:var(--unc); font-size:9.5px; font-weight:750; white-space:nowrap; vertical-align:middle; }
  tr.is-stale td { color:color-mix(in srgb,var(--muted) 86%,transparent); }

  /* ---------- market gauge ---------- */
  .dp-gauge { margin:16px 0 2px; }
  .gg { display:inline-flex; align-items:baseline; gap:11px; flex-wrap:wrap; padding:11px 16px; border-radius:13px; border:1px solid var(--line); background:var(--panel); }
  .gg-k { font-size:11.5px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; color:var(--muted); }
  .gg-v { font-size:22px; font-weight:800; color:var(--ink); font-variant-numeric:tabular-nums; letter-spacing:-.02em; }
  .gg-n { font-size:12px; color:var(--muted); }

  /* ---------- coverage / limits ---------- */
  .dp-limits { margin:30px 0 0; padding:15px 17px; border:1px solid var(--line); border-radius:13px; background:var(--panel); }
  .dp-limits .lh { font-size:10.5px; font-weight:800; letter-spacing:.09em; text-transform:uppercase; color:var(--muted); margin-bottom:8px; }
  .dp-limits ul { margin:0; padding-left:17px; }
  .dp-limits li { font-size:12.5px; color:var(--muted); line-height:1.6; }
  .dp-limits b { color:var(--ink); font-weight:700; font-variant-numeric:tabular-nums; }

  /* ---------- what changed ---------- */
  .dp-changes { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:22px 0 2px; }
  .dp-changes .eb { font-size:10.5px; font-weight:800; letter-spacing:.09em; text-transform:uppercase; color:var(--muted); margin-right:2px; }
  .cchip { display:inline-flex; align-items:center; gap:7px; padding:6px 13px; border-radius:999px; border:1px solid var(--line); background:var(--panel); font-size:12.5px; font-weight:600; color:var(--ink); }
  .cchip .cd { width:6px; height:6px; border-radius:50%; background:var(--unc); flex:none; animation:dpBreathe 2.2s ease-in-out infinite; }
  .cchip.calm { color:var(--muted); font-weight:500; }
  .cchip.calm .cd { background:var(--up); }

  /* ---------- section chrome ---------- */
  .sec { display:flex; align-items:baseline; gap:11px; margin:36px 0 3px; flex-wrap:wrap; }
  .sec .sd { width:8px; height:8px; border-radius:2px; background:var(--sc,var(--faint)); align-self:center; flex:none; }
  .sec h2 { font-size:12px; font-weight:800; color:var(--ink); text-transform:uppercase; letter-spacing:.08em; }
  .sec .cnt { font-size:12px; color:var(--faint); font-weight:600; }
  .sec-sub { font-size:13px; color:var(--muted); margin:2px 0 15px; max-width:820px; }

  /* ---------- lean rail (the thesis + glance) ---------- */
  .rail { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
  @media(max-width:820px){ .rail { grid-template-columns:1fr; } }
  .lc { position:relative; background:var(--panel); border:1px solid var(--line); border-radius:16px; padding:18px 18px 16px; overflow:hidden; animation:dpUp .55s cubic-bezier(.2,.7,.3,1) both; }
  .lc::before {content:none;}
  .lc.acc { --c:var(--acc); } .lc.dis { --c:var(--dis); } .lc.unc { --c:var(--unc); }
  .lc:nth-child(2){ animation-delay:.05s; } .lc:nth-child(3){ animation-delay:.1s; }
  /* prints settling into the dark — cheap opacity-only ambient */
  .pool { position:absolute; right:14px; top:15px; width:52px; height:42px; opacity:.5; pointer-events:none; }
  .pool i { position:absolute; width:4px; height:4px; border-radius:50%; background:var(--c); opacity:0; animation:dpSink 3.6s ease-in infinite; }
