  @keyframes mtf-sk{0%{background-position:100% 0}100%{background-position:0 0}}
  @media (prefers-reduced-motion:reduce){.mtf-skel-hd,.mtf-skel-row{animation:none}}
/* ══════════════════════════════════════════════════════════════════════════
     LIGHT MODE — designed, not inherited (2026-08-03)
     This board was drawn dark-first and light arrived as a token swap: panel and
     canvas landed within one step of each other (#f5f5f7 on #eceef1), so the
     five action lanes stopped being lanes, the gated teasers turned into beige
     smudges, and the sign-up bands bleached into pastel. Light gets its own
     three-level depth recipe here:

         canvas #e8ebf1  →  panel #ffffff  →  card / lane wash

     Rules of the port: (1) every selector is guarded on html[data-theme="light"]
     AND scoped to body.page-stocks, so the dark render stays byte-identical and
     the macro page is untouched; (2) theme.js injects
     html.soft-contrast[data-theme="light"] LATE in <head> at specificity (0,2,1)
     — every rule below clears it on SPECIFICITY, never on source order;
     (3) directional colour goes through the estate's --ink-* twins so 红涨绿跌
     still flips; only non-directional state hues (amber) are pinned as hex.
     ══════════════════════════════════════════════════════════════════════════ */

  /* 1 · canvas — a step deeper than the estate default so white reads as material */
  html[data-theme="light"] body.page-stocks{ background:#e8ebf1; }

  /* 2 · panels — white material, hairline edge, one soft lift */
  html[data-theme="light"] body.page-stocks .panel{
    background:#fff; border-color:#dde2ea;
    box-shadow:0 1px 2px rgba(23,32,55,.05), 0 8px 24px -12px rgba(23,32,55,.10);
  }
  html[data-theme="light"] body.page-stocks #stocks-header{
    background:
      radial-gradient(900px 180px at 12% -40%,color-mix(in srgb,var(--link) 9%,transparent),transparent 60%),
      #fff;
  }
  html[data-theme="light"] body.page-stocks .stk-status{ background:#f4f6fa; border-color:#dde2ea; }

  /* 3 · the action board — in light the five lane containers vanished into the
     panel, so the board read as one undifferentiated list instead of five
     stances side by side. Each lane gets a wash and an edge in its OWN accent,
     so the column IS the stance before a single word is read. */
  html[data-theme="light"] body.page-stocks .actcol{
    background:color-mix(in srgb, var(--act-accent) 4%, #fff);
    border-color:color-mix(in srgb, var(--act-accent) 14%, #dde2ea);
    box-shadow:0 1px 2px rgba(23,32,55,.05), 0 8px 22px -15px rgba(23,32,55,.20);
  }
  html[data-theme="light"] body.page-stocks .acth{
    border-bottom-color:color-mix(in srgb, var(--act-accent) 16%, #dde2ea);
  }
  html[data-theme="light"] body.page-stocks .actitem{
    border-bottom-color:color-mix(in srgb, var(--act-accent) 10%, #e3e8f0);
  }
  html[data-theme="light"] body.page-stocks .actitem:hover,
  html[data-theme="light"] body.page-stocks .actitem:focus{ background:rgba(255,255,255,.72); }
  html[data-theme="light"] body.page-stocks .actitem.hovered{ background:rgba(255,255,255,.9); }

  /* 4 · gated teasers — a blurred colour chip on white smears into a dirty beige
     stain. Desaturating first makes the same rows read as what they are: a
     deliberate skeleton of content that is there, just not yours yet. */
  html[data-theme="light"] body.page-stocks .mx-tier-blurred{
    filter:blur(5px) saturate(.35); opacity:.46;
  }

  /* 5 · RECENTLY FIRED — the "theme just confirmed" row. On ink a warm gradient
     reads as a whisper; on white the same gradient shouts a cream band across
     the panel. Light gets the quiet-notice form instead: near-white wash, one
     amber rail, amber headline. */
  html[data-theme="light"] body.page-stocks .pbr-r{
    background:#f7f9fc; border-color:#e3e8f0;
  }
  html[data-theme="light"] body.page-stocks .pbr-r.pbr-warm{
    background:color-mix(in srgb,#b98a2b 7%,#fff);
    border-color:color-mix(in srgb,#b98a2b 26%,#dde2ea);
    border:1px solid var(--line);
  }
  html[data-theme="light"] body.page-stocks .pbr-wl{ color:#7a5a14; }

  /* 6 · entry chips — "pullback zone …" + "extended" sat as two abutting heavy
     tints, reading as one double-highlighted blob. Thinner washes and a hairline
     ring make them two chips again. The green keeps --ink-up (not a hex) so the
     红涨绿跌 flip still swaps it to red; amber is a non-directional state hue and
     is pinned. */
  html[data-theme="light"] body.page-stocks .ent-good{
    color:var(--ink-up, var(--up));
    background:color-mix(in srgb, var(--ink-up, var(--up)) 9%, #fff);
    box-shadow:inset 0 0 0 1px color-mix(in srgb, var(--ink-up, var(--up)) 24%, transparent);
  }
  html[data-theme="light"] body.page-stocks .ent-warn{
    color:#8a6410;
    background:color-mix(in srgb,#b98a2b 10%,#fff);
    box-shadow:inset 0 0 0 1px color-mix(in srgb,#b98a2b 26%,transparent);
  }

  /* 7 · the "?" affordance — a filled pill tuned for ink reads as a dark blob on
     white. It is a hint, not a control: hollow ring, muted glyph. */
  html[data-theme="light"] body.page-stocks span.help,
  html[data-theme="light"] body.page-stocks span.help.help-upgraded{
    background:transparent; color:var(--muted);
    border:1px solid color-mix(in srgb, var(--muted) 55%, transparent);
  }
  html[data-theme="light"] body.page-stocks span.help:hover,
  html[data-theme="light"] body.page-stocks span.help.help-upgraded:hover{
    border-color:var(--muted); color:var(--text);
  }

  /* 8 · the sign-up bands stay DARK ISLANDS. Everything else on this page went
     white, which is exactly why these two must not: they are the one place the
     page asks for something, and a pastel band on a white page is furniture.
     Buttons keep their vivid accent — unchanged from dark. */
  html[data-theme="light"] body.page-stocks .mx-tier-gate{
    background:linear-gradient(118deg,#233254 0%,#182034 62%,#151b2c 100%);
    border-color:#2f3f63;
    box-shadow:0 18px 44px -26px rgba(20,30,58,.55);
  }
  html[data-theme="light"] body.page-stocks .mx-tier-gate--prophet{
    background:linear-gradient(118deg,#2b2550 0%,#1d1c37 62%,#17172b 100%);
    border-color:#3b3268;
  }
  html[data-theme="light"] body.page-stocks .mx-tier-gate::before{ background:color-mix(in srgb,#8fb4f2 15%,transparent); }
  html[data-theme="light"] body.page-stocks .mx-tier-gate--prophet::before{ background:color-mix(in srgb,#a996ff 15%,transparent); }
  html[data-theme="light"] body.page-stocks .mx-tier-gate::after{
    background:linear-gradient(90deg,transparent,color-mix(in srgb,#8fb4f2 85%,transparent),transparent);
  }
  html[data-theme="light"] body.page-stocks .mx-tier-gate--prophet::after{
    background:linear-gradient(90deg,transparent,color-mix(in srgb,#a996ff 85%,transparent),transparent);
  }
  html[data-theme="light"] body.page-stocks .mx-tier-eyebrow{ color:#8fb4f2; }
  html[data-theme="light"] body.page-stocks .mx-tier-gate--prophet .mx-tier-eyebrow{ color:#a996ff; }
  html[data-theme="light"] body.page-stocks .mx-tier-mark{
    background:color-mix(in srgb,#8fb4f2 16%,transparent);
    border-color:color-mix(in srgb,#8fb4f2 34%,transparent);
  }
  html[data-theme="light"] body.page-stocks .mx-tier-gate--prophet .mx-tier-mark{
    background:color-mix(in srgb,#a996ff 16%,transparent);
    border-color:color-mix(in srgb,#a996ff 34%,transparent);
  }
  html[data-theme="light"] body.page-stocks .mx-tier-copy b{ color:#f2f5fa; }
  html[data-theme="light"] body.page-stocks .mx-tier-copy small{ color:rgba(224,232,245,.74); }
  html[data-theme="light"] body.page-stocks .mx-tier-signin{ color:rgba(224,232,245,.66); }
  html[data-theme="light"] body.page-stocks .mx-tier-signin:hover{ color:#fff; }

  /* 9 · level 3 — the containers that live INSIDE a white panel. They must sit
     just off white, or the hierarchy collapses back to one flat sheet. */
  html[data-theme="light"] body.page-stocks .pbt,
  html[data-theme="light"] body.page-stocks .pbf-bar{
    background:#f4f6fa; border-color:#e3e8f0;
  }
  html[data-theme="light"] body.page-stocks .pbf-bar button[aria-pressed="true"]{
    background:#fff; border-color:#dde2ea; box-shadow:0 1px 2px rgba(23,32,55,.10);
  }
  html[data-theme="light"] body.page-stocks .chip{ border-color:#dde2ea; }

rules.old:
/* ===== MARKET STATE — command-center (DISPLAY-ONLY synthesis) =====
   Bloomberg-grade: monochrome by default, colour spent only on signal.
   Verdict (left) reads in 2s; the six-factor evidence matrix (right) and the
   multi-timeframe tape say WHY. The macro backdrop quadrant lives below. */
body.page-macro .ms{--ms-c:var(--ink-3)}
body.page-macro .ms.ms-green{--ms-c:var(--up)}
body.page-macro .ms.ms-yellow{--ms-c:var(--warn)}
body.page-macro .ms.ms-red{--ms-c:var(--down)}

/* header strip */
body.page-macro .ms-head{display:flex;align-items:center;gap:10px 12px;flex-wrap:wrap;margin:0 0 4px}
body.page-macro .ms-eyebrow{display:inline-flex;align-items:center;gap:9px;white-space:nowrap;font-family:var(--num);
  font-size:11px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-2);margin:0}
body.page-macro .ms-live{width:7px;height:7px;border-radius:50%;background:var(--ms-c);flex:none;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--ms-c) 20%,transparent)}
body.page-macro .ms-date{font-family:var(--num);font-size:11px;letter-spacing:.04em;color:var(--ink-3);white-space:nowrap}
body.page-macro .ms-alerts{white-space:nowrap;display:inline-flex;align-items:center;gap:8px;cursor:pointer;
  border:var(--rule) solid var(--hair-strong);background:transparent;color:var(--ink-2);border-radius:999px;
  padding:5px 12px;font-size:11.5px;font-weight:600;letter-spacing:.02em;transition:border-color .14s,color .14s}
body.page-macro .ms-alerts:hover{border-color:var(--ink-3);color:var(--ink-1)}
body.page-macro .ms-alerts .dot{width:6px;height:6px;border-radius:50%;background:var(--act);flex:none}
body.page-macro .ms-alerts .ct{font-family:var(--num);font-weight:700;color:var(--ink-1)}
body.page-macro .ms-alerts .ct.is-zero{color:var(--ink-3)}

/* one-line reconciliation: names the slow backdrop and the fast risk read as two
   DIFFERENT questions, so "Goldilocks" + "Risk-off" don't read as a contradiction */
body.page-macro .ms-oneline{display:flex;align-items:baseline;gap:7px 10px;flex-wrap:wrap;
  margin:0 0 15px;padding-bottom:14px;border-bottom:var(--rule) solid var(--hair-strong);font-family:var(--num)}
body.page-macro .ms-oneline .olk{font-size:10px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3)}
body.page-macro .ms-oneline b{font-size:15px;font-weight:800;letter-spacing:-.01em;color:var(--ink-1)}
body.page-macro .ms-oneline .olsep{color:var(--hair-strong);font-weight:700}
html[data-lang="zh"] body.page-macro .ms-oneline .olk{letter-spacing:0}

/* ===== FRONT BOARD — Market State (left) + Macro Backdrop (right), side by side =====
   Base = mobile: one tight stack (radar → eyebrow → verdict/evidence → tape → divider →
   backdrop). At >=901px it promotes to a grid: radar + eyebrow span the top, the tape spans
   the bottom, Market State sits left (~60%) and the Macro Backdrop right (~40%). The .ms
   class is only present when market_state exists, so the grid never triggers on the
   (already mode-gated) empty case. */
body.page-macro .ms-front.ms{display:flex;flex-direction:column;gap:14px;margin-top:14px}
body.page-macro .ms-front>.rrx{margin:0}
body.page-macro .ms-front>.ms-head{margin:0}
body.page-macro .ms-front>.ms-top{margin-top:0}
body.page-macro .ms-front>.ms-tape{margin-top:0}
body.page-macro .ms-front>.ms-divider{margin:4px 0 0}
@media(min-width:1100px){
  body.page-macro .ms-front.ms{display:grid;gap:0 30px;align-items:start;
    grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);
    grid-template-areas:"radar radar" "head head" "state hero" "tape hero"}
  /* Risk Radar = a wide BANNER spanning the top: header + escalating odds on the left,
     and the threat meters / leading evidence / action — which used to stack at the bottom
     of a tall half-width block — moved into the right column that was empty whitespace.
     Even 1fr/1fr columns (the detail-heavy right column used to be squeezed narrow, which
     made it TALLER and left the sparse left column with a ~190px void beneath the ramp). */
  body.page-macro .ms-front>.rrx{grid-area:radar;margin-bottom:12px;
    grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:22px;row-gap:0;align-items:stretch}
  body.page-macro .ms-front>.rrx>.rrx-main{display:flex;flex-direction:column;gap:12px;min-width:0}
  body.page-macro .ms-front>.rrx>.rrx-main .rrx-odds{flex:0 0 auto}
  body.page-macro .ms-front>.rrx>.rrx-main .rrx-ramp{align-items:flex-end}
  body.page-macro .ms-front>.rrx>.rrx-main .rrx-tk{height:44px;flex:0 0 44px;min-height:44px}
  body.page-macro .ms-front>.rrx>.rrx-side{display:flex;flex-direction:column;justify-content:center;gap:7px;min-width:0;
    padding-left:20px;border-left:1px solid color-mix(in srgb,var(--rc) 22%,var(--line))}
  body.page-macro .ms-front>.ms-head{grid-area:head}
  body.page-macro .ms-front>.ms-top{grid-area:state;margin-top:14px}
  body.page-macro .ms-front>.ms-tape{grid-area:tape}
  body.page-macro .ms-front>.ms-divider{display:none}
  /* the backdrop, recomposed for the narrow right column: [locator | regime] on top,
     the four vitals as a 2×2 strip beneath — never the wide 3-up desktop layout */
  body.page-macro .ms-front>.hero-bar{grid-area:hero;margin-top:14px;padding-left:30px;
    border-left:var(--rule) solid var(--hair);grid-template-columns:auto minmax(0,1fr);gap:12px 18px}
  body.page-macro .ms-front>.hero-bar .hero-main{grid-column:2;border:0;padding:0}
  body.page-macro .ms-front>.hero-bar .hero-vitals{grid-column:1/-1;gap:12px 18px}
}

/* top: verdict | evidence */
body.page-macro .ms-top{display:grid;grid-template-columns:minmax(0,236px) minmax(0,1fr);margin-top:16px}
body.page-macro .ms-verdict{padding-right:22px;border-right:var(--rule) solid var(--hair)}
body.page-macro .ms-evidence{padding-left:22px;min-width:0}
@media(max-width:760px){
  body.page-macro .ms-top{grid-template-columns:1fr}
  body.page-macro .ms-verdict{padding:0 0 16px;border-right:0;border-bottom:var(--rule) solid var(--hair-strong)}
  body.page-macro .ms-evidence{padding:16px 0 0}
}

/* verdict column */
body.page-macro .v-label{font-family:var(--num);font-size:var(--fs-micro);font-weight:700;letter-spacing:var(--trk);text-transform:uppercase;
  color:var(--ink-3);margin:0 0 9px}
body.page-macro .v-word{font-size:var(--fs-display);line-height:.92;font-weight:800;letter-spacing:-.03em;margin:0;color:var(--ms-c);
  display:flex;align-items:center;gap:.2em}
body.page-macro .v-word .arr{font-family:var(--num);font-size:.42em;font-weight:700;transform:translateY(-.04em)}
html[data-lang="zh"] body.page-macro .v-word{letter-spacing:0}
@media(max-width:560px){body.page-macro .v-word{font-size:38px}}
body.page-macro .v-scorerow{display:flex;align-items:baseline;gap:7px;margin-top:12px}
body.page-macro .v-score{font-family:var(--num);font-size:var(--fs-num-xl);font-weight:800;line-height:1;letter-spacing:-.02em;color:var(--ink-1)}
body.page-macro .v-outof{font-family:var(--num);font-size:var(--fs-sm);color:var(--ink-3)}
body.page-macro .v-meter{margin-top:12px;height:6px;border-radius:3px;position:relative;overflow:hidden;
  background:linear-gradient(90deg,
    color-mix(in srgb,var(--down) 30%,var(--panel2)) 0 42%,
    color-mix(in srgb,var(--warn) 30%,var(--panel2)) 42% 60%,
    color-mix(in srgb,var(--up) 30%,var(--panel2)) 60% 100%)}
body.page-macro .v-meter .tick{position:absolute;top:-3px;bottom:-3px;width:2px;background:var(--ms-c);border-radius:2px;
  box-shadow:0 0 0 2px var(--panel)}
body.page-macro .v-scale{display:flex;justify-content:space-between;margin-top:6px;font-family:var(--num);font-size:9.5px;
  letter-spacing:.02em;color:var(--ink-3)}
/* mx merge: the board's own thesis IS the page headline — gradient display type
   (operator ruling: one hero, the Market State board; score appears once, on the bar). */
body.page-macro .v-thesis{
  margin:14px 0 0;font-size:clamp(17px,1.8vw,22px);font-weight:800;line-height:1.28;letter-spacing:-.02em;
  background:linear-gradient(120deg,var(--up) 0%,color-mix(in srgb,var(--up) 60%,var(--info)) 45%,var(--info) 85%);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
body.page-macro .ms-red .v-thesis{background:linear-gradient(120deg,var(--down) 0%,color-mix(in srgb,var(--down) 60%,var(--warn)) 45%,var(--warn) 85%);-webkit-background-clip:text;background-clip:text}
body.page-macro .ms-yellow .v-thesis{background:linear-gradient(120deg,var(--warn) 0%,color-mix(in srgb,var(--warn) 55%,var(--info)) 50%,var(--info) 90%);-webkit-background-clip:text;background-clip:text}
body.page-macro .v-flip{margin:12px 0 0;padding:1px 0 1px 11px;border-left:2px solid color-mix(in srgb,var(--warn) 55%,transparent);
  background:none;font-size:12px;line-height:1.45;color:var(--ink-3)}
body.page-macro .v-override{margin:10px 0 0;display:flex;align-items:flex-start;gap:7px;padding:8px 11px;border-radius:7px;
  border:var(--rule) solid color-mix(in srgb,var(--act) 38%,var(--hair));background:color-mix(in srgb,var(--act) 11%,transparent);
  font-size:11.5px;line-height:1.4;color:var(--ink-1)}
body.page-macro .v-override .ic{color:var(--ink-act, var(--act));flex:none;font-size:12px;line-height:1.3}

/* Risk-Radar banner now renders through the shared .rrx card (macro risk_radar_card);
   its old .ms-radar / .msr-* styling was retired with the cramped text-run markup. */

/* Heads-up chips — compact live flags integrated into the Market State board. */
.heads-up{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.heads-up .hu-label{font-family:var(--font-mono);font-size:10px;font-weight:700;letter-spacing:.18em;
  text-transform:uppercase;color:var(--muted);flex:none}
/* institutional flag: a status dot in the state colour + a clean label —
   no emoji, no border-left hack, no bubble pill */
.heads-up .hu-chip{display:inline-flex;align-items:center;gap:8px;padding:6px 13px;border-radius:9px;
  font-size:12.5px;line-height:1.3;color:var(--text);text-decoration:none;font-weight:500;
  background:var(--panel2);border:1px solid var(--line);transition:border-color .14s,box-shadow .14s}
.heads-up .hu-chip::before{content:"";width:7px;height:7px;border-radius:50%;flex:none;background:var(--hc);
  box-shadow:0 0 0 3px color-mix(in srgb,var(--hc) 18%,transparent)}
.heads-up a.hu-chip:hover{border-color:color-mix(in srgb,var(--hc) 55%,var(--line));
  box-shadow:0 4px 14px -8px color-mix(in srgb,var(--hc) 60%,transparent)}
.heads-up .hu-chip b{font-family:var(--font-mono);color:var(--hc)}

/* evidence matrix — one tight row per factor (arrow · title · bar · score). The short read
   and the metric tags live in a hover popup anchored to the dotted-underlined title; there
   is no inline description and no expand/collapse. */
body.page-macro .e-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:0 0 2px}
body.page-macro .e-title{font-family:var(--num);font-size:10px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;
  color:var(--ink-3);margin:0}
body.page-macro .e-cols{font-family:var(--num);font-size:9.5px;letter-spacing:.06em;color:var(--ink-3)}
body.page-macro .ms-f{border-top:var(--rule) solid var(--hair);display:grid;align-items:center;
  grid-template-columns:14px minmax(0,1fr) 70px 28px;column-gap:11px;padding:6px 3px}
body.page-macro .ms-f.tone-good{--ft:var(--up)}
body.page-macro .ms-f.tone-warn{--ft:var(--warn)}
body.page-macro .ms-f.tone-bad{--ft:var(--down)}
body.page-macro .ms-f.tone-flat{--ft:var(--ink-3)}
body.page-macro .f-dir{font-family:var(--num);font-size:11px;line-height:1;text-align:center;color:var(--ft)}
/* the title IS the hover target: reuse the .help/.tip machinery but strip the 15px ?-circle
   down to plain dotted-underlined text (overflow:visible so the popup is never clipped) */
body.page-macro .f-name.help{position:relative;display:block;min-width:0;width:auto;height:auto;
  border:0;border-radius:0;margin:0;overflow:visible;cursor:help}
body.page-macro .f-name .f-txt{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-size:12.5px;font-weight:600;color:var(--ink-1);
  text-decoration:underline dotted color-mix(in srgb,var(--ink-3) 55%,transparent);text-underline-offset:3px}
body.page-macro .f-name.help:hover .f-txt{text-decoration-color:var(--ink-2)}
html[data-lang="zh"] body.page-macro .f-name .f-txt{text-underline-offset:2px}
body.page-macro .f-name .tip{width:248px;font-weight:400}
body.page-macro .f-tipread{display:block;color:var(--ink-1);line-height:1.45;margin-bottom:7px}
body.page-macro .f-tipmetrics{display:flex;flex-wrap:wrap;gap:6px 7px}
body.page-macro .f-tone{height:4px;border-radius:2px;background:var(--panel2);overflow:hidden}
body.page-macro .f-tone i{display:block;height:100%;border-radius:2px;background:var(--ft)}
body.page-macro .f-score{font-family:var(--num);font-size:15px;font-weight:700;text-align:right;line-height:1;color:var(--ft)}
body.page-macro .ms-metric{display:inline-flex;align-items:baseline;gap:6px;padding:3px 9px;background:var(--tile);
  border:var(--rule) solid var(--hair);border-radius:6px;font-size:11px;color:var(--ink-3)}
body.page-macro .ms-metric b{font-family:var(--num);font-weight:700;color:var(--ink-1)}
@media(max-width:760px){
  body.page-macro .ms-f{grid-template-columns:14px minmax(0,1fr) 72px 26px;column-gap:9px}
}
@media(max-width:560px){
  body.page-macro .f-score{font-size:14px}
}

/* multi-timeframe tape — the technical detail behind the Trend factor */
body.page-macro .ms-tape{margin-top:16px;padding-top:13px;border-top:var(--rule) solid var(--hair-strong)}
body.page-macro .tape-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:6px}
body.page-macro .tape-title{display:inline-flex;align-items:center;gap:7px;font-family:var(--num);font-size:10px;font-weight:700;
  letter-spacing:.2em;text-transform:uppercase;color:var(--ink-3);margin:0}
body.page-macro .tape-sub{font-family:var(--num);font-size:9.5px;letter-spacing:.04em;color:var(--ink-3)}
body.page-macro table.ms-tapetbl{width:100%;border-collapse:collapse}
body.page-macro table.ms-tapetbl th{font-size:10px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-3);
  text-align:center;padding:6px 6px;border-bottom:var(--rule) solid var(--hair)}
body.page-macro table.ms-tapetbl th.l,body.page-macro table.ms-tapetbl td.l{text-align:left}
body.page-macro table.ms-tapetbl th.r,body.page-macro table.ms-tapetbl td.r{text-align:right}
body.page-macro table.ms-tapetbl td{padding:6px 6px;border-bottom:var(--rule) solid var(--hair)}
body.page-macro table.ms-tapetbl tr:last-child td{border-bottom:0}
body.page-macro .t-inst{font-size:13px;font-weight:600;color:var(--ink-1)}
body.page-macro .ms-cell2{display:inline-flex;align-items:baseline;gap:6px;justify-content:center;font-family:var(--num)}
body.page-macro .ms-cell2 .ar{font-size:11px;line-height:1}
body.page-macro .ms-cell2 .rsi{font-size:12.5px;color:var(--ink-2)}
body.page-macro .ms-cell2.good,body.page-macro .ms-conf.good{color:var(--ink-up, var(--up))}
body.page-macro .ms-cell2.bad,body.page-macro .ms-conf.bad{color:var(--ink-down, var(--down))}
body.page-macro .ms-cell2.flat,body.page-macro .ms-conf.warn,body.page-macro .ms-conf.flat{color:var(--ink-warn, var(--warn))}
body.page-macro .ms-conf{font-size:12px;font-weight:700;white-space:nowrap}
@media(max-width:560px){
  body.page-macro table.ms-tapetbl th,body.page-macro table.ms-tapetbl td{padding-left:3px;padding-right:3px}
  body.page-macro .ms-cell2 .rsi{display:none}
}

/* divider into the macro-backdrop quadrant locator below */
body.page-macro .ms-divider{display:flex;align-items:center;gap:12px;margin:22px 0 6px;font-family:var(--num);
  font-size:9.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3)}
body.page-macro .ms-divider::after{content:"";flex:1;height:1px;background:var(--hair)}
html[data-lang="zh"] body.page-macro .ms-divider,html[data-lang="zh"] body.page-macro .tape-title,
html[data-lang="zh"] body.page-macro .ms-eyebrow{letter-spacing:0}

/* ===== fired-alerts popup (hover-activated; tap-toggle fallback via #ms-alerts-toggle) =====
   Replaces the old right slide-out drawer: the "Fired alerts" pill now reveals a
   frosted-glass popover anchored beneath it ON HOVER — no click needed. The glass
   matches the nav dropdowns / gear popover (shared --glass-* tokens in theme.css).
   On touch (no hover) the pill still tap-toggles the popup via the #ms-alerts-toggle
   checkbox; Esc, a jump-link, or a click outside closes it (script at end of panel). */
body.page-macro .ms-alerts-wrap{position:relative;margin-left:auto;display:inline-flex}
body.page-macro .ms-alerts-pop{position:absolute;top:calc(100% + 9px);right:0;z-index:120;
  width:min(442px,calc(100vw - 24px));max-height:min(560px,72vh);overflow-y:auto;box-sizing:border-box;
  background:var(--glass-bg);-webkit-backdrop-filter:var(--glass-blur);backdrop-filter:var(--glass-blur);
  border:1px solid var(--glass-brd);border-radius:16px;box-shadow:var(--glass-shadow);padding:14px 15px 15px;
  transform-origin:top right;opacity:0;visibility:hidden;pointer-events:none;transform:translateY(-8px) scale(.98);
  transition:opacity .16s ease,transform .22s cubic-bezier(.32,1.3,.5,1),visibility 0s linear .22s}
body.page-macro .ms-alerts-pop::-webkit-scrollbar{width:7px}
body.page-macro .ms-alerts-pop::-webkit-scrollbar-thumb{background:var(--hair-strong);border-radius:7px}
body.page-macro #ms-alerts-toggle:checked ~ .ms-front .ms-alerts-pop{opacity:1;visibility:visible;pointer-events:auto;
  transform:none;transition:opacity .16s ease,transform .22s cubic-bezier(.32,1.3,.5,1),visibility 0s}
body.page-macro #ms-alerts-toggle:checked ~ .ms-front .ms-alerts{border-color:var(--ink-3);color:var(--ink-1)}
@media (hover:hover) and (pointer:fine){
  body.page-macro .ms-alerts-wrap::after{content:"";position:absolute;top:100%;right:0;width:100%;height:13px}
  body.page-macro .ms-alerts-wrap:hover .ms-alerts-pop,
  body.page-macro .ms-alerts-wrap:focus-within .ms-alerts-pop{opacity:1;visibility:visible;pointer-events:auto;
    transform:none;transition:opacity .16s ease,transform .22s cubic-bezier(.32,1.3,.5,1),visibility 0s}
  body.page-macro .ms-alerts-wrap:hover .ms-alerts,body.page-macro .ms-alerts-wrap:focus-within .ms-alerts{border-color:var(--ink-3);color:var(--ink-1)}
}
@media (prefers-reduced-motion:reduce){
  body.page-macro .ms-alerts-pop{transition:opacity .14s ease,visibility 0s linear .14s;transform:none}
  body.page-macro .ms-alerts-wrap:hover .ms-alerts-pop,
  body.page-macro #ms-alerts-toggle:checked ~ .ms-front .ms-alerts-pop{transform:none;transition:opacity .14s ease}}
body.page-macro .ms-pop-head{display:flex;align-items:flex-start;gap:10px;margin:0 0 11px;padding-bottom:11px;border-bottom:var(--rule) solid var(--hair)}
body.page-macro .ms-pop-title{font-size:13.5px;font-weight:800;color:var(--ink-1);line-height:1.25}
body.page-macro .ms-pop-sub{font-size:11px;color:var(--ink-3);line-height:1.45;margin-top:3px}
body.page-macro .ms-pop-body{display:flex;flex-direction:column;gap:9px}
body.page-macro .ms-sig{display:block;border:var(--rule) solid var(--hair);
  border-radius:10px;background:var(--tile);padding:12px 14px;color:var(--ink-1);transition:transform .12s,box-shadow .12s}
body.page-macro a.ms-sig:hover{transform:translateX(-2px);box-shadow:0 4px 16px -8px rgba(0,0,0,.4)}
body.page-macro .ms-sig.sev-act{--sgc:var(--act)}
body.page-macro .ms-sig.sev-warn{--sgc:var(--warn)}
body.page-macro .ms-sig.sev-info{--sgc:var(--info)}
body.page-macro .ms-sig-head{display:flex;align-items:baseline;gap:9px}
body.page-macro .ms-sig-ico{font-size:16px;line-height:1;flex:none}
body.page-macro .ms-sig-title{font-size:13.5px;font-weight:700;color:var(--ink-1);line-height:1.3}
body.page-macro .ms-sig-jump{margin-left:auto;font-size:11px;font-weight:700;color:var(--ink-link, var(--link));white-space:nowrap;flex:none}
body.page-macro .ms-sig-detail{font-family:var(--num);font-size:12px;color:var(--ink-2);margin:8px 0 0;line-height:1.4}
body.page-macro .ms-sig-what{font-size:11.5px;color:var(--ink-3);line-height:1.5;margin:8px 0 0;padding-top:8px;border-top:var(--rule) solid var(--hair)}
body.page-macro .ms-sig-edge{font-size:11.5px;color:var(--ink-2);margin:6px 0 0;line-height:1.45}
body.page-macro .ms-sig-edge b{color:var(--ink-3);font-weight:600}
body.page-macro .ms-pop-empty{text-align:center;color:var(--ink-3);padding:30px 18px;font-size:12.5px;line-height:1.55}
body.page-macro .ms-pop-empty .big{font-size:32px;display:block;margin-bottom:8px;color:var(--ink-up, var(--up));opacity:.7}

rules.new:
/* ===== MARKET STATE — command-center (DISPLAY-ONLY synthesis) =====
   Bloomberg-grade: monochrome by default, colour spent only on signal.
   Verdict (left) reads in 2s; the six-factor evidence matrix (right) and the
   multi-timeframe tape say WHY. The macro backdrop quadrant lives below. */
body.page-macro .ms{--ms-c:var(--ink-3)}
body.page-macro .ms.ms-green{--ms-c:var(--up)}
body.page-macro .ms.ms-yellow{--ms-c:var(--warn)}
body.page-macro .ms.ms-red{--ms-c:var(--down)}

/* header strip */
body.page-macro .ms-head{display:flex;align-items:center;gap:10px 12px;flex-wrap:wrap;margin:0 0 4px}
body.page-macro .ms-eyebrow{display:inline-flex;align-items:center;gap:9px;white-space:nowrap;font-family:var(--num);
  font-size:11px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-2);margin:0}
body.page-macro .ms-live{width:7px;height:7px;border-radius:50%;background:var(--ms-c);flex:none;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--ms-c) 20%,transparent)}
body.page-macro .ms-date{font-family:var(--num);font-size:11px;letter-spacing:.04em;color:var(--ink-3);white-space:nowrap}
body.page-macro .ms-alerts{white-space:nowrap;display:inline-flex;align-items:center;gap:8px;cursor:pointer;
  border:var(--rule) solid var(--hair-strong);background:transparent;color:var(--ink-2);border-radius:999px;
  padding:5px 12px;font-size:11.5px;font-weight:600;letter-spacing:.02em;transition:border-color .14s,color .14s}
body.page-macro .ms-alerts:hover{border-color:var(--ink-3);color:var(--ink-1)}
body.page-macro .ms-alerts .dot{width:6px;height:6px;border-radius:50%;background:var(--act);flex:none}
body.page-macro .ms-alerts .ct{font-family:var(--num);font-weight:700;color:var(--ink-1)}
body.page-macro .ms-alerts .ct.is-zero{color:var(--ink-3)}

/* one-line reconciliation: names the slow backdrop and the fast risk read as two
   DIFFERENT questions, so "Goldilocks" + "Risk-off" don't read as a contradiction */
body.page-macro .ms-oneline{display:flex;align-items:baseline;gap:7px 10px;flex-wrap:wrap;
  margin:0 0 15px;padding-bottom:14px;border-bottom:var(--rule) solid var(--hair-strong);font-family:var(--num)}
body.page-macro .ms-oneline .olk{font-size:10px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3)}
body.page-macro .ms-oneline b{font-size:15px;font-weight:800;letter-spacing:-.01em;color:var(--ink-1)}
body.page-macro .ms-oneline .olsep{color:var(--hair-strong);font-weight:700}
html[data-lang="zh"] body.page-macro .ms-oneline .olk{letter-spacing:0}

/* ===== FRONT BOARD — Market State (left) + Macro Backdrop (right), side by side =====
   Base = mobile: one tight stack (radar → eyebrow → verdict/evidence → tape → divider →
   backdrop). At >=901px it promotes to a grid: radar + eyebrow span the top, the tape spans
   the bottom, Market State sits left (~60%) and the Macro Backdrop right (~40%). The .ms
   class is only present when market_state exists, so the grid never triggers on the
   (already mode-gated) empty case. */
body.page-macro .ms-front.ms{display:flex;flex-direction:column;gap:14px;margin-top:14px}
body.page-macro .ms-front>.rrx{margin:0}
body.page-macro .ms-front>.ms-head{margin:0}
body.page-macro .ms-front>.ms-top{margin-top:0}
body.page-macro .ms-front>.ms-tape{margin-top:0}
body.page-macro .ms-front>.ms-divider{margin:4px 0 0}
@media(min-width:1100px){
  body.page-macro .ms-front.ms{display:grid;gap:0 30px;align-items:start;
    grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);
    grid-template-areas:"radar radar" "head head" "state hero" "tape hero"}
  /* Risk Radar = a wide BANNER spanning the top: header + escalating odds on the left,
     and the threat meters / leading evidence / action — which used to stack at the bottom
     of a tall half-width block — moved into the right column that was empty whitespace.
     Even 1fr/1fr columns (the detail-heavy right column used to be squeezed narrow, which
     made it TALLER and left the sparse left column with a ~190px void beneath the ramp). */
  body.page-macro .ms-front>.rrx{grid-area:radar;margin-bottom:12px;
    grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:22px;row-gap:0;align-items:stretch}
  body.page-macro .ms-front>.rrx>.rrx-main{display:flex;flex-direction:column;gap:12px;min-width:0}
  body.page-macro .ms-front>.rrx>.rrx-main .rrx-odds{flex:0 0 auto}
  body.page-macro .ms-front>.rrx>.rrx-main .rrx-ramp{align-items:flex-end}
  body.page-macro .ms-front>.rrx>.rrx-main .rrx-tk{height:44px;flex:0 0 44px;min-height:44px}
  body.page-macro .ms-front>.rrx>.rrx-side{display:flex;flex-direction:column;justify-content:center;gap:7px;min-width:0;
    padding-left:20px;border-left:1px solid var(--line)}
  body.page-macro .ms-front>.ms-head{grid-area:head}
  body.page-macro .ms-front>.ms-top{grid-area:state;margin-top:14px}
  body.page-macro .ms-front>.ms-tape{grid-area:tape}
  body.page-macro .ms-front>.ms-divider{display:none}
  /* the backdrop, recomposed for the narrow right column: [locator | regime] on top,
     the four vitals as a 2×2 strip beneath — never the wide 3-up desktop layout */
  body.page-macro .ms-front>.hero-bar{grid-area:hero;margin-top:14px;padding-left:30px;
    border-left:var(--rule) solid var(--hair);grid-template-columns:auto minmax(0,1fr);gap:12px 18px}
  body.page-macro .ms-front>.hero-bar .hero-main{grid-column:2;border:0;padding:0}
  body.page-macro .ms-front>.hero-bar .hero-vitals{grid-column:1/-1;gap:12px 18px}
}

/* top: verdict | evidence */
body.page-macro .ms-top{display:grid;grid-template-columns:minmax(0,236px) minmax(0,1fr);margin-top:16px}
body.page-macro .ms-verdict{padding-right:22px;border-right:var(--rule) solid var(--hair)}
body.page-macro .ms-evidence{padding-left:22px;min-width:0}
@media(max-width:760px){
  body.page-macro .ms-top{grid-template-columns:1fr}
  body.page-macro .ms-verdict{padding:0 0 16px;border-right:0;border-bottom:var(--rule) solid var(--hair-strong)}
  body.page-macro .ms-evidence{padding:16px 0 0}
}

/* verdict column */
body.page-macro .v-label{font-family:var(--num);font-size:var(--fs-micro);font-weight:700;letter-spacing:var(--trk);text-transform:uppercase;
  color:var(--ink-3);margin:0 0 9px}
body.page-macro .v-word{font-size:var(--fs-display);line-height:.92;font-weight:800;letter-spacing:-.03em;margin:0;color:var(--ms-c);
  display:flex;align-items:center;gap:.2em}
body.page-macro .v-word .arr{font-family:var(--num);font-size:.42em;font-weight:700;transform:translateY(-.04em)}
html[data-lang="zh"] body.page-macro .v-word{letter-spacing:0}
@media(max-width:560px){body.page-macro .v-word{font-size:38px}}
body.page-macro .v-scorerow{display:flex;align-items:baseline;gap:7px;margin-top:12px}
body.page-macro .v-score{font-family:var(--num);font-size:var(--fs-num-xl);font-weight:800;line-height:1;letter-spacing:-.02em;color:var(--ink-1)}
body.page-macro .v-outof{font-family:var(--num);font-size:var(--fs-sm);color:var(--ink-3)}
body.page-macro .v-meter{margin-top:12px;height:6px;border-radius:3px;position:relative;overflow:hidden;
  background:linear-gradient(90deg,
    color-mix(in srgb,var(--down) 30%,var(--panel2)) 0 42%,
    color-mix(in srgb,var(--warn) 30%,var(--panel2)) 42% 60%,
    color-mix(in srgb,var(--up) 30%,var(--panel2)) 60% 100%)}
body.page-macro .v-meter .tick{position:absolute;top:-3px;bottom:-3px;width:2px;background:var(--ms-c);border-radius:2px;
  box-shadow:0 0 0 2px var(--panel)}
body.page-macro .v-scale{display:flex;justify-content:space-between;margin-top:6px;font-family:var(--num);font-size:9.5px;
  letter-spacing:.02em;color:var(--ink-3)}
/* mx merge: the board's own thesis IS the page headline — gradient display type
   (operator ruling: one hero, the Market State board; score appears once, on the bar). */
body.page-macro .v-thesis{
  margin:14px 0 0;font-size:clamp(17px,1.8vw,22px);font-weight:800;line-height:1.28;letter-spacing:-.02em;
  background:linear-gradient(120deg,var(--up) 0%,color-mix(in srgb,var(--up) 60%,var(--info)) 45%,var(--info) 85%);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
body.page-macro .ms-red .v-thesis{background:linear-gradient(120deg,var(--down) 0%,color-mix(in srgb,var(--down) 60%,var(--warn)) 45%,var(--warn) 85%);-webkit-background-clip:text;background-clip:text}
body.page-macro .ms-yellow .v-thesis{background:linear-gradient(120deg,var(--warn) 0%,color-mix(in srgb,var(--warn) 55%,var(--info)) 50%,var(--info) 90%);-webkit-background-clip:text;background-clip:text}
body.page-macro .v-flip{margin:12px 0 0;padding:1px 0 1px 11px;border:1px solid var(--line);
  background:none;font-size:12px;line-height:1.45;color:var(--ink-3)}
body.page-macro .v-override{margin:10px 0 0;display:flex;align-items:flex-start;gap:7px;padding:8px 11px;border-radius:7px;
  border:var(--rule) solid color-mix(in srgb,var(--act) 38%,var(--hair));background:color-mix(in srgb,var(--act) 11%,transparent);
  font-size:11.5px;line-height:1.4;color:var(--ink-1)}
body.page-macro .v-override .ic{color:var(--ink-act, var(--act));flex:none;font-size:12px;line-height:1.3}

/* Risk-Radar banner now renders through the shared .rrx card (macro risk_radar_card);
   its old .ms-radar / .msr-* styling was retired with the cramped text-run markup. */

/* Heads-up chips — compact live flags integrated into the Market State board. */
.heads-up{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.heads-up .hu-label{font-family:var(--font-mono);font-size:10px;font-weight:700;letter-spacing:.18em;
  text-transform:uppercase;color:var(--muted);flex:none}
/* institutional flag: a status dot in the state colour + a clean label —
   no emoji, no border-left hack, no bubble pill */
.heads-up .hu-chip{display:inline-flex;align-items:center;gap:8px;padding:6px 13px;border-radius:9px;
  font-size:12.5px;line-height:1.3;color:var(--text);text-decoration:none;font-weight:500;
  background:var(--panel2);border:1px solid var(--line);transition:border-color .14s,box-shadow .14s}
.heads-up .hu-chip::before{content:"";width:7px;height:7px;border-radius:50%;flex:none;background:var(--hc);
  box-shadow:0 0 0 3px color-mix(in srgb,var(--hc) 18%,transparent)}
.heads-up a.hu-chip:hover{border-color:color-mix(in srgb,var(--hc) 55%,var(--line));
  box-shadow:0 4px 14px -8px color-mix(in srgb,var(--hc) 60%,transparent)}
.heads-up .hu-chip b{font-family:var(--font-mono);color:var(--hc)}

/* evidence matrix — one tight row per factor (arrow · title · bar · score). The short read
   and the metric tags live in a hover popup anchored to the dotted-underlined title; there
   is no inline description and no expand/collapse. */
body.page-macro .e-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:0 0 2px}
body.page-macro .e-title{font-family:var(--num);font-size:10px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;
  color:var(--ink-3);margin:0}
body.page-macro .e-cols{font-family:var(--num);font-size:9.5px;letter-spacing:.06em;color:var(--ink-3)}
body.page-macro .ms-f{border-top:var(--rule) solid var(--hair);display:grid;align-items:center;
  grid-template-columns:14px minmax(0,1fr) 70px 28px;column-gap:11px;padding:6px 3px}
body.page-macro .ms-f.tone-good{--ft:var(--up)}
body.page-macro .ms-f.tone-warn{--ft:var(--warn)}
body.page-macro .ms-f.tone-bad{--ft:var(--down)}
body.page-macro .ms-f.tone-flat{--ft:var(--ink-3)}
body.page-macro .f-dir{font-family:var(--num);font-size:11px;line-height:1;text-align:center;color:var(--ft)}
/* the title IS the hover target: reuse the .help/.tip machinery but strip the 15px ?-circle
   down to plain dotted-underlined text (overflow:visible so the popup is never clipped) */
body.page-macro .f-name.help{position:relative;display:block;min-width:0;width:auto;height:auto;
  border:0;border-radius:0;margin:0;overflow:visible;cursor:help}
body.page-macro .f-name .f-txt{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-size:12.5px;font-weight:600;color:var(--ink-1);
  text-decoration:underline dotted color-mix(in srgb,var(--ink-3) 55%,transparent);text-underline-offset:3px}
body.page-macro .f-name.help:hover .f-txt{text-decoration-color:var(--ink-2)}
html[data-lang="zh"] body.page-macro .f-name .f-txt{text-underline-offset:2px}
body.page-macro .f-name .tip{width:248px;font-weight:400}
body.page-macro .f-tipread{display:block;color:var(--ink-1);line-height:1.45;margin-bottom:7px}
body.page-macro .f-tipmetrics{display:flex;flex-wrap:wrap;gap:6px 7px}
body.page-macro .f-tone{height:4px;border-radius:2px;background:var(--panel2);overflow:hidden}
body.page-macro .f-tone i{display:block;height:100%;border-radius:2px;background:var(--ft)}
body.page-macro .f-score{font-family:var(--num);font-size:15px;font-weight:700;text-align:right;line-height:1;color:var(--ft)}
body.page-macro .ms-metric{display:inline-flex;align-items:baseline;gap:6px;padding:3px 9px;background:var(--tile);
  border:var(--rule) solid var(--hair);border-radius:6px;font-size:11px;color:var(--ink-3)}
body.page-macro .ms-metric b{font-family:var(--num);font-weight:700;color:var(--ink-1)}
@media(max-width:760px){
  body.page-macro .ms-f{grid-template-columns:14px minmax(0,1fr) 72px 26px;column-gap:9px}
}
@media(max-width:560px){
  body.page-macro .f-score{font-size:14px}
}

/* multi-timeframe tape — the technical detail behind the Trend factor */
body.page-macro .ms-tape{margin-top:16px;padding-top:13px;border-top:var(--rule) solid var(--hair-strong)}
body.page-macro .tape-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:6px}
body.page-macro .tape-title{display:inline-flex;align-items:center;gap:7px;font-family:var(--num);font-size:10px;font-weight:700;
  letter-spacing:.2em;text-transform:uppercase;color:var(--ink-3);margin:0}
body.page-macro .tape-sub{font-family:var(--num);font-size:9.5px;letter-spacing:.04em;color:var(--ink-3)}
body.page-macro table.ms-tapetbl{width:100%;border-collapse:collapse}
body.page-macro table.ms-tapetbl th{font-size:10px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-3);
  text-align:center;padding:6px 6px;border-bottom:var(--rule) solid var(--hair)}
body.page-macro table.ms-tapetbl th.l,body.page-macro table.ms-tapetbl td.l{text-align:left}
body.page-macro table.ms-tapetbl th.r,body.page-macro table.ms-tapetbl td.r{text-align:right}
body.page-macro table.ms-tapetbl td{padding:6px 6px;border-bottom:var(--rule) solid var(--hair)}
body.page-macro table.ms-tapetbl tr:last-child td{border-bottom:0}
body.page-macro .t-inst{font-size:13px;font-weight:600;color:var(--ink-1)}
body.page-macro .ms-cell2{display:inline-flex;align-items:baseline;gap:6px;justify-content:center;font-family:var(--num)}
body.page-macro .ms-cell2 .ar{font-size:11px;line-height:1}
body.page-macro .ms-cell2 .rsi{font-size:12.5px;color:var(--ink-2)}
body.page-macro .ms-cell2.good,body.page-macro .ms-conf.good{color:var(--ink-up, var(--up))}
body.page-macro .ms-cell2.bad,body.page-macro .ms-conf.bad{color:var(--ink-down, var(--down))}
body.page-macro .ms-cell2.flat,body.page-macro .ms-conf.warn,body.page-macro .ms-conf.flat{color:var(--ink-warn, var(--warn))}
body.page-macro .ms-conf{font-size:12px;font-weight:700;white-space:nowrap}
@media(max-width:560px){
  body.page-macro table.ms-tapetbl th,body.page-macro table.ms-tapetbl td{padding-left:3px;padding-right:3px}
  body.page-macro .ms-cell2 .rsi{display:none}
}

/* divider into the macro-backdrop quadrant locator below */
body.page-macro .ms-divider{display:flex;align-items:center;gap:12px;margin:22px 0 6px;font-family:var(--num);
  font-size:9.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3)}
body.page-macro .ms-divider::after{content:"";flex:1;height:1px;background:var(--hair)}
html[data-lang="zh"] body.page-macro .ms-divider,html[data-lang="zh"] body.page-macro .tape-title,
html[data-lang="zh"] body.page-macro .ms-eyebrow{letter-spacing:0}

/* ===== fired-alerts popup (hover-activated; tap-toggle fallback via #ms-alerts-toggle) =====
   Replaces the old right slide-out drawer: the "Fired alerts" pill now reveals a
   frosted-glass popover anchored beneath it ON HOVER — no click needed. The glass
   matches the nav dropdowns / gear popover (shared --glass-* tokens in theme.css).
   On touch (no hover) the pill still tap-toggles the popup via the #ms-alerts-toggle
   checkbox; Esc, a jump-link, or a click outside closes it (script at end of panel). */
body.page-macro .ms-alerts-wrap{position:relative;margin-left:auto;display:inline-flex}
body.page-macro .ms-alerts-pop{position:absolute;top:calc(100% + 9px);right:0;z-index:120;
  width:min(442px,calc(100vw - 24px));max-height:min(560px,72vh);overflow-y:auto;box-sizing:border-box;
  background:var(--glass-bg);-webkit-backdrop-filter:var(--glass-blur);backdrop-filter:var(--glass-blur);
  border:1px solid var(--glass-brd);border-radius:16px;box-shadow:var(--glass-shadow);padding:14px 15px 15px;
  transform-origin:top right;opacity:0;visibility:hidden;pointer-events:none;transform:translateY(-8px) scale(.98);
  transition:opacity .16s ease,transform .22s cubic-bezier(.32,1.3,.5,1),visibility 0s linear .22s}
body.page-macro .ms-alerts-pop::-webkit-scrollbar{width:7px}
body.page-macro .ms-alerts-pop::-webkit-scrollbar-thumb{background:var(--hair-strong);border-radius:7px}
body.page-macro #ms-alerts-toggle:checked ~ .ms-front .ms-alerts-pop{opacity:1;visibility:visible;pointer-events:auto;
  transform:none;transition:opacity .16s ease,transform .22s cubic-bezier(.32,1.3,.5,1),visibility 0s}
body.page-macro #ms-alerts-toggle:checked ~ .ms-front .ms-alerts{border-color:var(--ink-3);color:var(--ink-1)}
@media (hover:hover) and (pointer:fine){
  body.page-macro .ms-alerts-wrap::after{content:"";position:absolute;top:100%;right:0;width:100%;height:13px}
  body.page-macro .ms-alerts-wrap:hover .ms-alerts-pop,
  body.page-macro .ms-alerts-wrap:focus-within .ms-alerts-pop{opacity:1;visibility:visible;pointer-events:auto;
    transform:none;transition:opacity .16s ease,transform .22s cubic-bezier(.32,1.3,.5,1),visibility 0s}
  body.page-macro .ms-alerts-wrap:hover .ms-alerts,body.page-macro .ms-alerts-wrap:focus-within .ms-alerts{border-color:var(--ink-3);color:var(--ink-1)}
}
@media (prefers-reduced-motion:reduce){
  body.page-macro .ms-alerts-pop{transition:opacity .14s ease,visibility 0s linear .14s;transform:none}
  body.page-macro .ms-alerts-wrap:hover .ms-alerts-pop,
  body.page-macro #ms-alerts-toggle:checked ~ .ms-front .ms-alerts-pop{transform:none;transition:opacity .14s ease}}
body.page-macro .ms-pop-head{display:flex;align-items:flex-start;gap:10px;margin:0 0 11px;padding-bottom:11px;border-bottom:var(--rule) solid var(--hair)}
body.page-macro .ms-pop-title{font-size:13.5px;font-weight:800;color:var(--ink-1);line-height:1.25}
body.page-macro .ms-pop-sub{font-size:11px;color:var(--ink-3);line-height:1.45;margin-top:3px}
body.page-macro .ms-pop-body{display:flex;flex-direction:column;gap:9px}
body.page-macro .ms-sig{display:block;border:var(--rule) solid var(--hair);
  border-radius:10px;background:var(--tile);padding:12px 14px;color:var(--ink-1);transition:transform .12s,box-shadow .12s}
body.page-macro a.ms-sig:hover{transform:translateX(-2px);box-shadow:0 4px 16px -8px rgba(0,0,0,.4)}
body.page-macro .ms-sig.sev-act{--sgc:var(--act)}
body.page-macro .ms-sig.sev-warn{--sgc:var(--warn)}
body.page-macro .ms-sig.sev-info{--sgc:var(--info)}
body.page-macro .ms-sig-head{display:flex;align-items:baseline;gap:9px}
body.page-macro .ms-sig-ico{font-size:16px;line-height:1;flex:none}
body.page-macro .ms-sig-title{font-size:13.5px;font-weight:700;color:var(--ink-1);line-height:1.3}
body.page-macro .ms-sig-jump{margin-left:auto;font-size:11px;font-weight:700;color:var(--ink-link, var(--link));white-space:nowrap;flex:none}
body.page-macro .ms-sig-detail{font-family:var(--num);font-size:12px;color:var(--ink-2);margin:8px 0 0;line-height:1.4}
body.page-macro .ms-sig-what{font-size:11.5px;color:var(--ink-3);line-height:1.5;margin:8px 0 0;padding-top:8px;border-top:var(--rule) solid var(--hair)}
body.page-macro .ms-sig-edge{font-size:11.5px;color:var(--ink-2);margin:6px 0 0;line-height:1.45}
body.page-macro .ms-sig-edge b{color:var(--ink-3);font-weight:600}
body.page-macro .ms-pop-empty{text-align:center;color:var(--ink-3);padding:30px 18px;font-size:12.5px;line-height:1.55}
body.page-macro .ms-pop-empty .big{font-size:32px;display:block;margin-bottom:8px;color:var(--ink-up, var(--up));opacity:.7}

rules.old:
/* ══════════════════════════════════════════════════════
   MX2 — v2 row-ledger layout (macro mode only)
   Scoped to body.page-macro to protect stocks mode.
   Tokens reuse theme.css vars throughout.
   ══════════════════════════════════════════════════════ */


/* ── Topbar v2 (within the macro panel) ── */
body.page-macro .mx2-topbar{
  display:flex;align-items:center;justify-content:space-between;
  padding:14px 0 12px;border-bottom:1px solid var(--line);
}
body.page-macro .mx2-topbar-brand{font-size:13px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
body.page-macro .mx2-topbar-right{display:flex;align-items:center;gap:10px}
body.page-macro .mx2-topbar-date{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}
/* mx2-expand-btn — gbtn glass recipe with the info/up expand accent (macro sweep
   2026-07): frosted fill + inset sheen + diagonal sheen sweep on hover; keeps the
   .ea-ic caret rotate contract. */
body.page-macro .mx2-expand-btn{
  position:relative;overflow:hidden;
  display:inline-flex;align-items:center;gap:7px;cursor:pointer;white-space:nowrap;
  padding:6px 15px;border-radius:999px;min-height:0;
  background:linear-gradient(180deg,color-mix(in srgb,var(--info) 15%,var(--gbtn-bg)),var(--gbtn-bg));
  border:1px solid color-mix(in srgb,var(--info) 42%,var(--gbtn-brd));
  -webkit-backdrop-filter:blur(12px) saturate(140%);backdrop-filter:blur(12px) saturate(140%);
  color:var(--text);font-size:11px;font-weight:700;letter-spacing:.05em;
  box-shadow:inset 0 1px 0 var(--gbtn-sheen),0 2px 12px -7px color-mix(in srgb,var(--info) 55%,transparent);
  transition:transform .16s ease,box-shadow .25s,border-color .2s,background .2s;
}
body.page-macro .mx2-expand-btn::after{content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(105deg,transparent 40%,rgba(255,255,255,.13) 50%,transparent 60%);
  transform:translateX(-140%) skewX(-8deg);}
body.page-macro .mx2-expand-btn:hover::after{transform:translateX(140%) skewX(-8deg);transition:transform .55s ease;}
body.page-macro .mx2-expand-btn:hover{
  transform:translateY(-1px);border-color:var(--info);
  background:linear-gradient(180deg,color-mix(in srgb,var(--info) 22%,var(--gbtn-bg)),var(--gbtn-bg));
  box-shadow:inset 0 1px 0 var(--gbtn-sheen),0 8px 22px -9px color-mix(in srgb,var(--info) 60%,transparent);
}
body.page-macro .mx2-expand-btn:active{transform:translateY(0) scale(.985)}
@media (prefers-reduced-motion: reduce){
  body.page-macro .mx2-expand-btn,body.page-macro .mx2-expand-btn:hover,body.page-macro .mx2-expand-btn:active{transform:none;}
  body.page-macro .mx2-expand-btn::after{display:none;}
}
body.page-macro .mx2-expand-btn .ea-ic{
  display:inline-block;font-size:12px;line-height:1;color:var(--ink-info, var(--info));
  transition:transform .28s cubic-bezier(.4,0,.2,1);
}
body.page-macro .mx2-expand-btn.all-open .ea-ic{transform:rotate(180deg)}

/* ── HERO section ── */
body.page-macro .mx2-hero{padding:22px 0 0}
/* The v-thesis p BECOMES the gradient headline in v2 — restyle in place */
body.page-macro .mx2-hero .v-thesis{
  font-size:26px;font-weight:800;line-height:1.2;letter-spacing:-.02em;
  -webkit-text-fill-color:transparent;text-fill-color:transparent;
  background-clip:text;-webkit-background-clip:text;
  margin-bottom:4px;
}
body.page-macro .mx2-hero .v-thesis.ms-green{
  background-image:linear-gradient(120deg,var(--up) 0%,#5fc89a 40%,var(--info) 80%);
}
body.page-macro .mx2-hero .v-thesis.ms-yellow{
  background-image:linear-gradient(120deg,var(--warn) 0%,color-mix(in srgb,var(--warn) 55%,var(--info)) 50%,var(--info) 90%);
}
body.page-macro .mx2-hero .v-thesis.ms-red{
  background-image:linear-gradient(120deg,var(--down) 0%,color-mix(in srgb,var(--down) 60%,var(--warn)) 45%,var(--warn) 85%);
}
/* VIS-01: light-theme thesis gradient — darken mid-stops to ≥3.0:1 on #f7f8fa (bg).
   Dark theme keeps the bright stops; light overrides to darker shades.
   ms-green: #1f9a55→#166b3c, #5fc89a→#2f9e6a (was 1.93:1, now ≥3.5:1 on near-white bg)
   ms-yellow: warn already ~3.19:1 in light; darken mid to #8a5a00 for the mid-range
   ms-red: down is dark blue; override mid to a darker amber */
[data-theme="light"] body.page-macro .mx2-hero .v-thesis.ms-green{
  background-image:linear-gradient(120deg,#166b3c 0%,#2f9e6a 40%,#1a5cc8 80%);
}
[data-theme="light"] body.page-macro .mx2-hero .v-thesis.ms-yellow{
  background-image:linear-gradient(120deg,#8a5a00 0%,#6a4800 50%,#1a5cc8 90%);
}
[data-theme="light"] body.page-macro .mx2-hero .v-thesis.ms-red{
  background-image:linear-gradient(120deg,#a8000f 0%,#8a3400 45%,#804400 85%);
}
body.page-macro .mx2-hero .v-override,
body.page-macro .mx2-hero .v-flip{
  font-size:12px;color:var(--muted);margin-top:3px;
}
body.page-macro .mx2-hero-sub{font-size:12px;color:var(--muted);margin-bottom:16px}
body.page-macro .mx2-hero-row{display:flex;align-items:flex-start;gap:18px;flex-wrap:wrap;margin-bottom:14px}

/* Score panel — the hero-score-block; .ms-front provides color scope */
body.page-macro .mx2-score-block{
  display:flex;flex-direction:column;gap:10px;flex-shrink:0;
  min-width:280px;padding:14px 18px 12px;
  border-radius:14px;
  /* VIS-05: glow + border keyed to verdict color (--ms-c set by .ms-green/.ms-yellow/.ms-red) */
  border:1px solid color-mix(in srgb,var(--ms-c,var(--up)) 18%,var(--line));
  box-shadow:0 0 40px -12px color-mix(in srgb,var(--ms-c,var(--up)) 20%,transparent);
}
body.page-macro .ms-front.ms-green .mx2-score-block{
  background:linear-gradient(145deg,var(--panel) 0%,color-mix(in srgb,var(--up) 5%,var(--panel)) 100%);
  border-color:color-mix(in srgb,var(--up) 20%,var(--line));
}
body.page-macro .ms-front.ms-yellow .mx2-score-block{
  background:linear-gradient(145deg,var(--panel) 0%,color-mix(in srgb,var(--warn) 5%,var(--panel)) 100%);
  border-color:color-mix(in srgb,var(--warn) 20%,var(--line));
}
body.page-macro .ms-front.ms-red .mx2-score-block{
  background:linear-gradient(145deg,var(--panel) 0%,color-mix(in srgb,var(--down) 5%,var(--panel)) 100%);
  border-color:color-mix(in srgb,var(--down) 20%,var(--line));
}
body.page-macro .mx2-score-top{display:flex;align-items:baseline;gap:10px}
/* Restyle existing #ms-score el */
body.page-macro .mx2-score-block .v-score{
  font-size:72px;font-weight:900;line-height:1;letter-spacing:-.04em;color:var(--ms-c,var(--up));
  text-shadow:0 0 60px color-mix(in srgb,var(--ms-c,var(--up)) 35%,transparent);
}
body.page-macro .mx2-score-block .v-outof{font-size:18px;font-weight:500;color:var(--muted);align-self:flex-end;margin-bottom:10px}
body.page-macro .mx2-score-label-stack{display:flex;flex-direction:column;gap:3px;padding-bottom:8px}
body.page-macro .mx2-score-label{font-size:11px;font-weight:700;color:var(--muted);letter-spacing:.06em;text-transform:uppercase}
/* Restyle existing #ms-word el */
body.page-macro .mx2-score-block .v-word{font-size:15px;font-weight:800;color:var(--ms-c,var(--up));margin:0;padding:0}
body.page-macro .mx2-score-block .v-word .arr{margin-left:4px}
/* Progress bar — wraps existing #ms-tick */
body.page-macro .mx2-prog-wrap{display:flex;flex-direction:column;gap:0}
body.page-macro .mx2-prog-track{
  height:8px;border-radius:4px;
  background:color-mix(in srgb,var(--muted) 15%,transparent);
  overflow:visible;position:relative;
}
body.page-macro .mx2-prog-fill{
  height:8px;border-radius:4px;
  background:linear-gradient(90deg,var(--q1) 0%,var(--up) 60%,#6ee7b7 100%);
  transition:width .6s cubic-bezier(.4,0,.2,1);pointer-events:none;
}
body.page-macro .ms-yellow .mx2-prog-fill{
  background:linear-gradient(90deg,var(--q2) 0%,var(--warn) 100%);
}
body.page-macro .ms-red .mx2-prog-fill{
  background:linear-gradient(90deg,var(--q3) 0%,var(--down) 100%);
}
/* Restyle existing #ms-tick */
body.page-macro .mx2-prog-track .tick{
  position:absolute;top:-3px;bottom:-3px;width:2.5px;border-radius:2px;
  background:var(--text);transform:translateX(-50%);
  box-shadow:0 0 8px color-mix(in srgb,var(--up) 60%,transparent);
  pointer-events:none;
}
body.page-macro .mx2-prog-labels{
  display:flex;justify-content:space-between;
  font-size:9px;color:var(--muted);margin-top:4px;
}
/* ms-live-pill stays in score top */
body.page-macro .mx2-score-block .ms-live-wrap{display:flex;align-items:center;gap:6px;margin-left:auto}
/* v-meter hide (replaced by mx2-prog-track) */
body.page-macro .mx2-score-block .v-meter{display:none}
body.page-macro .mx2-score-block .v-scale{display:none}
body.page-macro .mx2-score-block .v-label{display:none}

/* Hero context card */
body.page-macro .mx2-hero-ctx{
  flex:1;min-width:200px;max-width:420px;
  font-size:12px;color:var(--muted);
  padding:12px 16px;background:var(--panel);border:1px solid var(--line);border-radius:10px;
  line-height:1.6;
  display:flex;flex-direction:column;gap:8px;
}
body.page-macro .mx2-hero-ctx strong{color:var(--text)}
body.page-macro .mx2-hero-ctx .mx2-alerts-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
/* Leadership context line — muted context, not an alert; hidden when sector_bias absent */
body.page-macro .mx2-leadership-ctx{font-size:11px;color:var(--muted);line-height:1.55;padding:5px 8px;background:color-mix(in srgb,var(--muted) 7%,var(--panel));border:1px solid color-mix(in srgb,var(--muted) 14%,transparent);border-radius:6px;margin-top:2px}
body.page-macro .mx2-leadership-ctx strong{color:var(--ink-2);font-weight:600}
/* "What would flip this call" strip — calibrated regime keys only (flip margin /
   odds drift / conviction); shared by ledger hero and grid scorecard. Theme-var
   colors so it holds in light mode too. */
body.page-macro .mxfs{margin-top:12px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:color-mix(in srgb,var(--panel2) 55%,transparent);display:flex;flex-direction:column;gap:6px}
body.page-macro .mxfs-hd{display:flex;align-items:center;gap:8px;font-size:10.5px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
body.page-macro .mxfs-badge{margin-left:auto;font-size:9.5px;font-weight:600;letter-spacing:.03em;text-transform:none;color:var(--muted);border:1px solid var(--line);border-radius:6px;padding:2px 7px;white-space:nowrap}
body.page-macro .mxfs-subtitle{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));line-height:1.4;margin-top:-2px}
body.page-macro .mxfs-row{display:flex;gap:10px;align-items:baseline;font-size:12px;line-height:1.5;color:var(--text)}
body.page-macro .mxfs-k{flex:none;width:118px;font-size:10.5px;font-weight:700;letter-spacing:.04em;color:var(--muted)}
body.page-macro .mxfs-v{min-width:0}
body.page-macro .mxfs-v b{font-weight:700;color:var(--text)}
body.page-macro .mxfs-stance{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));line-height:1.5;padding-top:4px;border-top:1px solid var(--line);margin-top:2px}
/* ── Goldilocks explainer — quad-map hero (macro sweep 2026-07) ──────────────
   Full-width 2×2 map with odds printed inside each rounded tile, a pulsing
   position dot and an animated drift arrow. The old side-by-side odds list is
   retired (odds now live in the tiles). */
body.page-macro .mxqm-eyebrow-row{display:flex;align-items:center;gap:8px;margin-bottom:8px}
body.page-macro .mxqm-eyebrow-chip{margin-left:auto;font-size:9.5px;font-weight:600;letter-spacing:.02em;color:var(--muted);
  border:1px solid var(--gbtn-brd);border-radius:999px;padding:2px 9px;white-space:nowrap;background:var(--gbtn-bg)}
/* Inside the pop: the eyebrow row already carries the "context, not a forecast"
   chip, so suppress the duplicate badge in the shared regime_flip_strip header. */
body.page-macro #mx5FlipCtxPop .mxfs-badge{display:none}
body.page-macro .mxqm-glance{font-size:12.5px;line-height:1.5;color:var(--ink-2,rgba(255,255,255,.78));margin:2px 0 10px}
/* The regime name was --warn, i.e. the SAME token the position dot used — so the
   headline word and a dot sitting in a different quadrant were painted alike, which
   is half of why the two read as one self-contradicting claim. It is also 3.6:1 on
   white (12.5px bold is not WCAG large text, so it wanted 4.5:1). Full text ink
   fixes both, and leaves hue to mean quadrant and nothing else. */
body.page-macro .mxqm-glance b{color:var(--text,#c8d0dc);font-weight:700}
/* Divergence line — shown ONLY when today's reading and the confirmed label sit in
   different quadrants. A watch condition, never an alarm: no falsifier/refutation
   vocabulary on a user surface (operator 2026-07-27). */
body.page-macro .mxqm-diverge{display:block;margin-top:3px;color:var(--muted)}
/* Legend. The map carries two different KINDS of object — a measurement and a
   label — and shipped naming neither, so the dot read as a broken "you are here".
   One row, defined once, under the plot. */
body.page-macro .mxqm-legend{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:4px 14px;
  margin:6px 0 0;font-size:9.5px;letter-spacing:.02em;color:var(--muted)}
body.page-macro .mxqm-lg-item{display:inline-flex;align-items:center;gap:5px;white-space:nowrap}
body.page-macro .mxqm-lg-dot{width:7px;height:7px;border-radius:50%;flex:none;background:var(--mxqm-mark,#f2f6fc)}
/* swatch = the active tile's exact composite (its hue at .42 over the plate), the
   same color-mix the odds halo uses, so it re-shades per theme and through the zh
   q1/q3 swap for free. */
body.page-macro .mxqm-lg-tile{width:9px;height:9px;border-radius:2.5px;flex:none}
body.page-macro .mxqm-lg-q1{background:color-mix(in srgb,var(--q1,#2e9e4f) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-lg-q2{background:color-mix(in srgb,var(--q2,#d4a017) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-lg-q3{background:color-mix(in srgb,var(--q3,#d04545) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-lg-q4{background:color-mix(in srgb,var(--q4,#3f78d8) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-wrap{margin:0 0 8px}
body.page-macro .mxqm-svg-box{width:100%;max-width:300px;margin:0 auto}
body.page-macro .mxqm-svg-box svg{width:100%;height:auto;display:block;overflow:visible}
/* Quad fill classes — CSS rules (not presentation attrs) so var() resolves fine;
   --q1/--q3 swap under zh (theme.css 红涨绿跌) and all four re-shade per theme,
   which also retires the old per-theme literal overrides. Active tile lifts brighter. */
body.page-macro .mxqm-q1-fill{fill:var(--q1,#2e9e4f);opacity:.14}
body.page-macro .mxqm-q2-fill{fill:var(--q2,#d4a017);opacity:.14}
body.page-macro .mxqm-q3-fill{fill:var(--q3,#d04545);opacity:.14}
body.page-macro .mxqm-q4-fill{fill:var(--q4,#3f78d8);opacity:.14}
body.page-macro .mxqm-q1-fill.active{opacity:.42}
body.page-macro .mxqm-q2-fill.active{opacity:.42}
body.page-macro .mxqm-q3-fill.active{opacity:.42}
body.page-macro .mxqm-q4-fill.active{opacity:.42}
body.page-macro .mxqm-axis-label{fill:rgba(255,255,255,.34);font-size:7.5px;letter-spacing:.04em;font-family:Inter,-apple-system,sans-serif}


body.page-macro .mxqm-quad-label{fill:rgba(255,255,255,.62);font-size:6.6px;letter-spacing:.04em;font-family:Inter,-apple-system,sans-serif;font-weight:700;
  paint-order:stroke fill;stroke-width:2.2;stroke-linejoin:round}
body.page-macro .mxqm-quad-label.l-zh{font-size:8px;letter-spacing:.06em}
/* The odds numeral carries a HALO so the position dot (drawn beneath it — see the
   marker-layer note in the SVG) can pass behind the glyphs without eating them.
   paint-order:stroke fill lays the stroke down first, so the stroke reads as an
   outline OUTSIDE the letterform instead of thinning it.
   The halo has to be the colour of the tile it sits on, or it shows up as a glow:
   each tile is `fill:var(--qN); opacity:.14` (or .42 when active) composited over
   the popup plate, which color-mix() reproduces exactly. Referencing --qN keeps
   this correct through both themes AND the zh 红涨绿跌 q1/q3 swap for free. */
body.page-macro .mxqm-odds{fill:rgba(255,255,255,.72);font-size:17px;font-weight:800;font-family:Inter,-apple-system,sans-serif;font-variant-numeric:tabular-nums;
  paint-order:stroke fill;stroke-width:3.4;stroke-linejoin:round;
  stroke:color-mix(in srgb,var(--q1,#2e9e4f) 14%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q1{stroke:color-mix(in srgb,var(--q1,#2e9e4f) 14%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q2{stroke:color-mix(in srgb,var(--q2,#d4a017) 14%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q3{stroke:color-mix(in srgb,var(--q3,#d04545) 14%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q4{stroke:color-mix(in srgb,var(--q4,#3f78d8) 14%,var(--mxqm-plate,rgba(16,21,30,.97)))}
/* active tile = the .42 fill. NOT necessarily the tile the dot lands in: the dot is
   today's raw growth x inflation reading, the active tile is the hysteresis-confirmed
   label, and during a transition they legitimately differ (see .mxqm-diverge). Every
   tile therefore needs its halo mix at BOTH opacities. */
body.page-macro .mxqm-halo-q1.active{stroke:color-mix(in srgb,var(--q1,#2e9e4f) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q2.active{stroke:color-mix(in srgb,var(--q2,#d4a017) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q3.active{stroke:color-mix(in srgb,var(--q3,#d04545) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-halo-q4.active{stroke:color-mix(in srgb,var(--q4,#3f78d8) 42%,var(--mxqm-plate,rgba(16,21,30,.97)))}
body.page-macro .mxqm-odds.active{fill:#fff}
/* ── Colour law for this map: HUE = quadrant, INK = measurement ────────────────
   All four hues are spoken for (--q1..--q4), and --q1/--q3 additionally SWAP under
   zh 红涨绿跌 — so any hue the position marker picks collides with some tile in some
   theme x language. It shipped on --warn, which resolves to #b9791a on light: six
   degrees of hue from --q2 #b07d05, the REFLATION tile. The "you are here" dot was
   therefore painted in one of the four categories it is supposed to be neutral
   about — it camouflaged on an active Reflation tile, and over the pale Stagflation
   tile it read as a brown smudge rather than a marker (operator report 2026-08-11).
   The old light-theme stroke rgba(0,0,0,.5) made that worse: a translucent black rim
   over a dark ochre fill is mud, and it separates the dot from nothing.
   --mxqm-mark is theme ink and carries NO category meaning; the ring is the plate
   colour, opaque, so the marker separates from all four tile hues in both themes.
   Anything painted here that means "the reading" (dot, pulse, drift arrow) takes
   --mxqm-mark. Never a --qN, never a state token. */
body.page-macro .mxqm-dot{fill:var(--mxqm-mark,#f2f6fc);stroke:var(--mxqm-plate,rgba(16,21,30,.97));stroke-width:2}
body.page-macro .mxqm-pulse{fill:var(--mxqm-mark,#f2f6fc);opacity:.26;transform-box:fill-box;transform-origin:center;animation:mxqmPulse 2.4s ease-out infinite}
body.page-macro .mxqm-arrow{stroke:var(--mxqm-mark,#f2f6fc);stroke-width:2;fill:none;marker-end:url(#mxqmArrowHead);opacity:.62;
  stroke-dasharray:120;stroke-dashoffset:120;animation:mxqmDraw .9s ease-out .15s forwards}
body.page-macro .mxqm-arrowhead{fill:var(--mxqm-mark,#f2f6fc)}
@keyframes mxqmPulse{0%{transform:scale(1);opacity:.30}70%{transform:scale(2.9);opacity:0}100%{transform:scale(2.9);opacity:0}}
@keyframes mxqmDraw{to{stroke-dashoffset:0}}
@media (prefers-reduced-motion: reduce){
  body.page-macro .mxqm-pulse{animation:none;opacity:.20}
  body.page-macro .mxqm-arrow{animation:none;stroke-dashoffset:0}
}
[data-theme="light"] body.page-macro .mxqm-axis-label{fill:rgba(0,0,0,.58)}
[data-theme="light"] body.page-macro .mxqm-quad-label{fill:rgba(0,0,0,.62)}
[data-theme="light"] body.page-macro .mxqm-odds{fill:rgba(0,0,0,.6)}
[data-theme="light"] body.page-macro .mxqm-odds.active{fill:rgba(0,0,0,.9)}

/* ── Task 6: leadership drawdown bar strip ── */
body.page-macro .rsx-ldr-bars{margin:6px 0 4px;display:flex;flex-direction:column;gap:3px;position:relative}
body.page-macro .rsx-ldr-bar-row{display:flex;align-items:center;gap:5px;font-size:10.5px;min-height:16px}
body.page-macro .rsx-ldr-bar-ticker{flex:none;width:38px;font-weight:700;color:var(--ink-2,rgba(255,255,255,.72));font-size:10px}
body.page-macro .rsx-ldr-bar-track{flex:1;height:8px;border-radius:4px;background:rgba(255,255,255,.06);position:relative;overflow:visible}
body.page-macro .rsx-ldr-bar-fill{height:100%;border-radius:4px;background-color:var(--down,#ef4444);opacity:.75}
body.page-macro .rsx-ldr-bar-pct{flex:none;font-size:10px;font-weight:700}
/* index reference line — absolutely positioned over the track; drawn via inline style left:% */
body.page-macro .rsx-ldr-idx-line{
  position:absolute;top:0;bottom:0;width:1.5px;
  background:rgba(255,255,255,.35);border-radius:1px;pointer-events:none;
}
body.page-macro .rsx-ldr-idx-label{
  position:absolute;top:-12px;transform:translateX(-50%);
  font-size:8.5px;color:var(--ink-3,rgba(255,255,255,.4));white-space:nowrap;
}
[data-theme="light"] body.page-macro .rsx-ldr-bar-ticker{color:rgba(0,0,0,.72)}
[data-theme="light"] body.page-macro .rsx-ldr-bar-fill{background-color:#ef4444}
[data-theme="light"] body.page-macro .rsx-ldr-idx-line{background:rgba(0,0,0,.3)}
[data-theme="light"] body.page-macro .rsx-ldr-idx-label{color:rgba(0,0,0,.58)}
@media(max-width:640px){body.page-macro .mxfs-row{flex-direction:column;gap:1px}body.page-macro .mxfs-k{width:auto}
/* the longer honest-stance pill text ("… — not all-clear") must wrap on narrow
   phones instead of bleeding past the card edge (pill is nowrap on desktop; nowrap removed
   in 1c so this override is now redundant but harmless) */
body.page-macro.mx4-grid .mx5-regime-pill{white-space:normal}}
/* ── Flip-context hover panel (grid view only) ── */
/* Panel floats over the thesis/buttons; hover on gauge row or panel itself keeps it open */
body.page-macro.mx4-grid .mx5-flipctx-anchor{position:relative;}
body.page-macro.mx4-grid .mx5-flipctx-pop{
  position:absolute;left:0;right:0;
  top:34px;z-index:120;
  opacity:0;visibility:hidden;transform:translateY(-4px);
  transition:opacity .18s ease .05s,transform .18s ease .05s,visibility 0s linear .3s;
  pointer-events:none;
  /* Goldilocks trim (2026-07-20): the pop now fits without scrolling (flip-strip section
     deleted, weakest+grip compressed to one line), so the scroll cap + bottom fade are
     removed per Fable's "a hover popup must never scroll" ruling. */
  background:var(--mx5-pop-bg,rgba(16,21,30,.97));
  /* the plate the quad tiles composite over — the quad-map numeral halo mixes its
     tile hue into this to land on the tile's exact colour. Kept as its own token
     because the light theme overrides `background` with a literal below rather
     than re-pointing --mx5-pop-bg, so the halo cannot read the background. */
  --mxqm-plate:var(--mx5-pop-bg,rgba(16,21,30,.97));
  /* the MEASUREMENT ink — position dot, its pulse and the drift arrow. Deliberately
     NOT a state token: see the colour law above .mxqm-dot. Denser than --text so a
     4.5-unit dot still reads as a marker rather than as a stray glyph. */
  --mxqm-mark:#f2f6fc;
  border:1px solid var(--mx5-glass-border,rgba(255,255,255,.12));
  border-radius:14px;
  box-shadow:0 18px 48px rgba(0,0,0,.5);
  padding:12px 14px 14px;
  backdrop-filter:blur(20px);
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-flipctx-pop{
  background:#fff;
  --mxqm-plate:#fff;
  --mxqm-mark:#1b2333;
  border-color:rgba(0,0,0,.12);
  box-shadow:0 18px 48px rgba(20,30,50,.18);
}
/* reveal on regime pill hover/focus, or when cursor enters the panel itself */
body.page-macro.mx4-grid .mx5-regime-pill:hover ~ .mx5-flipctx-pop,
body.page-macro.mx4-grid .mx5-flipctx-pop:hover,
body.page-macro.mx4-grid .mx5-regime-pill:focus ~ .mx5-flipctx-pop{
  opacity:1;visibility:visible;transform:none;pointer-events:auto;
  transition:opacity .18s ease .12s,transform .18s ease .12s,visibility 0s linear 0s;
}
/* neutralize the .mxfs card chrome inside the pop — the pop provides its own container */
body.page-macro.mx4-grid .mx5-flipctx-pop .mxfs{border:none;background:transparent;margin-top:0;}
/* affordance: pill cursor + info icon */
body.page-macro.mx4-grid .mx5-regime-pill{cursor:help;}
body.page-macro.mx4-grid .mx5-pill-info{
  font-size:10px;margin-left:3px;flex-shrink:0;
}
/* mobile: pop is static and initially hidden; toggled by JS tap */
@media(max-width:700px){
  body.page-macro.mx4-grid .mx5-flipctx-pop{
    position:static;box-shadow:none;
    border:1px solid var(--line);
    display:none;opacity:1;visibility:visible;transform:none;pointer-events:auto;
  }
  body.page-macro.mx4-grid .mx5-flipctx-pop.open{display:block;}
}
/* Grid view: hide driver-ctx text block (Zone 2 covers it); keep alerts+catalyst pill row */
body.page-macro.mx4-grid .mx2-hero-ctx>div:first-child{display:none;}
/* In grid view, ctx card becomes a slim row with just alerts */
body.page-macro.mx4-grid .mx2-hero-ctx{
  background:transparent;border:none;padding:4px 0;flex:none;min-width:0;
}

/* ── Island system color tokens per section ── */
body.page-macro{
  --isle-evidence:#20c0a0;
  --isle-events:#e0a030;
  --isle-markets:#4d8ef5;
  --isle-risk:#e05c5c;
  --isle-policy:#a070e8;
  --isle-brief:#38c472;
  --isle-news:#7a8494;
  --isle-deep:#4d8ef5;
  /* tri-layer shadow stack */
  --island-shadow-tight:0 2px 10px rgba(0,0,0,.6);
  --island-shadow-mid:0 10px 40px -6px rgba(0,0,0,.55);
  --island-shadow-ambient:0 36px 90px -18px rgba(0,0,0,.40);
}
[data-theme="light"] body.page-macro,[data-theme="light"].page-macro{
  --island-shadow-tight:0 2px 8px rgba(20,30,50,.12);
  --island-shadow-mid:0 10px 32px -6px rgba(20,30,50,.16);
  --island-shadow-ambient:0 32px 72px -14px rgba(20,30,50,.14);
}

/* ── Row-ledger sections ── */
body.page-macro .sx{
  position:relative;
  margin-top:0;border-bottom:1px solid var(--line);
  transition:opacity .35s ease,transform .35s ease,filter .35s ease;
}
body.page-macro .sx:last-of-type{border-bottom:none}
body.page-macro .sx[data-open]{z-index:10}
/* Sibling recession when any island is open */
body.page-macro.has-open-island .sx:not([data-open]){
  opacity:.45;
  filter:saturate(.4) brightness(.85);
  transform:scale(.998);
}
[data-theme="light"] body.page-macro.has-open-island .sx:not([data-open]){
  opacity:.55;filter:saturate(.5) brightness(.93);
}

/* sx-sum / sx-label / sx-chev / sx-glance CSS removed (v5.1: ledger rows retired) */

/* ── v3 ISLAND TRAY — grid-template-rows expand mechanism ── */
body.page-macro .sx-tray{
  display:grid;
  grid-template-rows:0fr;
  opacity:0;
  transition:
    grid-template-rows .40s cubic-bezier(.34,1.08,.64,1),
    opacity .28s ease;
}
body.page-macro .sx-tray-inner-wrap{overflow:hidden}
body.page-macro .sx[data-open] .sx-tray{
  grid-template-rows:1fr;
  opacity:1;
}
/* Legacy sx-tray-inner (still present in RISK/POLICY/AIBRIEF/NEWS/DEEP trays) */
body.page-macro .sx-tray-inner{padding:0 0 24px}

/* ── ISLAND CARD — the dimensional lift container ── */
body.page-macro .sx-island{
  position:relative;
  margin:0 -6px 20px -6px;
  padding:20px 22px 24px;
  border-radius:18px;
  border:1.5px solid var(--isle-color,var(--info));
  transform-style:preserve-3d;
  background:var(--panel);
  background-image:linear-gradient(160deg,rgba(255,255,255,.025) 0%,transparent 60%);
  border-top-color:color-mix(in srgb,var(--isle-color,var(--info)) 55%,rgba(255,255,255,.6));
  box-shadow:none;
  transition:
    box-shadow .4s cubic-bezier(.34,1.08,.64,1),
    transform .4s cubic-bezier(.34,1.08,.64,1),
    border-color .3s ease;
}
body.page-macro .sx[data-open] .sx-island{
  transform:translateY(-3px) rotateX(0.6deg) scale(1.012);
  box-shadow:
    var(--island-shadow-tight),
    var(--island-shadow-mid),
    var(--island-shadow-ambient),
    0 0 60px -10px color-mix(in srgb,var(--isle-color,var(--info)) 30%,transparent),
    inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter:blur(16px);
  -webkit-backdrop-filter:blur(16px);
  animation:isle-breathe 6s ease-in-out infinite;
}
body.page-macro .sx:not([data-open]) .sx-island{
  transform:translateY(0) rotateX(0deg) scale(1);
  box-shadow:none;animation:none;
  backdrop-filter:none;-webkit-backdrop-filter:none;
}
/* Light mode island */
[data-theme="light"] body.page-macro .sx[data-open] .sx-island{
  background:var(--panel);
  border-width:2px;
  border-color:color-mix(in srgb,var(--isle-color,var(--info)) 70%,transparent);
  border-top-color:var(--isle-color,var(--info));
  box-shadow:
    var(--island-shadow-tight),
    var(--island-shadow-mid),
    var(--island-shadow-ambient),
    0 0 30px -10px color-mix(in srgb,var(--isle-color,var(--info)) 22%,transparent),
    inset 0 1px 0 rgba(255,255,255,.9);
  backdrop-filter:none;-webkit-backdrop-filter:none;
}
/* many-open: ≥3 islands open → halve glow mass */
body.page-macro.many-open .sx[data-open] .sx-island{
  box-shadow:
    var(--island-shadow-tight),
    var(--island-shadow-mid),
    0 0 30px -12px color-mix(in srgb,var(--isle-color,var(--info)) 18%,transparent),
    inset 0 1px 0 rgba(255,255,255,.06);
}

/* Aurora edge drift ::before */
body.page-macro .sx-island::before{
  content:'';
  position:absolute;inset:-1.5px;border-radius:inherit;z-index:-1;
  background:conic-gradient(
    from var(--isle-aurora-angle,0deg),
    color-mix(in srgb,var(--isle-color,var(--info)) 50%,transparent) 0%,
    transparent 22%,
    color-mix(in srgb,var(--isle-color,var(--info)) 28%,transparent) 50%,
    transparent 72%,
    color-mix(in srgb,var(--isle-color,var(--info)) 50%,transparent) 100%
  );
  opacity:0;transition:opacity .5s ease;
}
body.page-macro .sx[data-open] .sx-island::before{
  /* Perf (2026-07-21 mobile audit): the angle sweep restyles + repaints the whole
     island every frame (custom-property animation is main-thread). steps(84)
     keeps the drift at ~6fps — visually identical on this soft gradient — and
     cuts ~90% of the paint work; touch devices hold the lit rim entirely. */
  opacity:.38;animation:isle-aurora 14s steps(84) infinite;
}
@media (pointer:coarse){
  body.page-macro .sx[data-open] .sx-island::before{animation:none}
}
body.page-macro .sx:not([data-open]) .sx-island::before{opacity:0;animation:none}
[data-theme="light"] body.page-macro .sx[data-open] .sx-island::before{opacity:.2}

/* Under-glow floor ::after */
body.page-macro .sx-island::after{
  content:'';
  position:absolute;left:10%;right:10%;bottom:-14px;height:30px;
  border-radius:50%;
  background:color-mix(in srgb,var(--isle-color,var(--info)) 38%,transparent);
  /* blur frozen at the midpoint — animating blur() re-rasterizes every frame
     (2026-07-21 mobile audit); the breathing lives in opacity alone below. */
  filter:blur(16px);opacity:0;transition:opacity .4s ease;z-index:-2;
}
body.page-macro .sx[data-open] .sx-island::after{
  opacity:.55;animation:isle-underglow 5s ease-in-out infinite;
}
body.page-macro .sx:not([data-open]) .sx-island::after{opacity:0;animation:none}
body.page-macro.many-open .sx[data-open] .sx-island::after{opacity:.28}
[data-theme="light"] body.page-macro .sx[data-open] .sx-island::after{
  opacity:.25;background:color-mix(in srgb,var(--isle-color,var(--info)) 50%,transparent);
}

/* Island keyframes */
@keyframes isle-breathe{
  0%,100%{transform:translateY(-3px) rotateX(0.6deg) scale(1.012)}
  50%{transform:translateY(-5px) rotateX(0.7deg) scale(1.013)}
}
@keyframes isle-aurora{
  from{--isle-aurora-angle:0deg}to{--isle-aurora-angle:360deg}
}
@keyframes isle-underglow{
