/* MOB-05: hide heatmap sublabels at mobile — heatmap.js renders labels with inline style="font-size:Xpx"
   where X can be 4–5px on a 281px canvas at 390px viewport.
   Target via CSS attr substring matching on the inline style; silence text ≤7px while preserving ≥8px. */
@media(max-width:560px){
  /* px-anchored so 40-79px labels never match the substring (verify F6) */
  body.page-macro #heatmap-scorecard [style*="font-size:4px"],
  body.page-macro #heatmap-scorecard [style*="font-size: 4px"],
  body.page-macro #heatmap-scorecard [style*="font-size:5px"],
  body.page-macro #heatmap-scorecard [style*="font-size: 5px"],
  body.page-macro #heatmap-scorecard [style*="font-size:6px"],
  body.page-macro #heatmap-scorecard [style*="font-size: 6px"],
  body.page-macro #heatmap-scorecard [style*="font-size:7px"],
  body.page-macro #heatmap-scorecard [style*="font-size: 7px"],
  body.page-macro #heatmap-scorecard [style*="font-size:4."],
  body.page-macro #heatmap-scorecard [style*="font-size:5."],
  body.page-macro #heatmap-scorecard [style*="font-size:6."],
  body.page-macro #heatmap-scorecard [style*="font-size:7."]{color:transparent!important}
}
/* PERMA-FIX — recurring black-label regression (operator: the institutional board is
   ALWAYS white text). This guard lives in the freshly-rendered page CSS, so it overrides
   a STALE cached heatmap.js (script tag carries no ?v=) that still computes a dark
   contrast colour for some tiles — heatmap.js sets the label colour as an inline style,
   which a stylesheet !important beats. Kept at low specificity (no #id) so the MOB-05
   sublabel-hide above still wins on mobile and silences tiny sub-labels. */
