/* Six-factor deep rows (SIGNALS dialog) */
.mx5-dlg-factor-row{
  display:grid;grid-template-columns:minmax(120px,1.4fr) 1fr 52px;
  align-items:center;gap:14px;
  padding:12px 14px;
  background:rgba(255,255,255,.03);border-radius:12px;
  border:1px solid rgba(255,255,255,.06);
  margin-bottom:8px;
}
[data-theme="light"] .mx5-dlg-factor-row{background:rgba(0,0,0,.025);border-color:rgba(0,0,0,.06);}
.mx5-dlg-factor-row.weakest{border-color:rgba(245,158,11,.25);}
.mx5-dlg-factor-name{font-size:12px;font-weight:700;}
.mx5-dlg-factor-read{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));margin-top:3px;line-height:1.4;}
[data-theme="light"] .mx5-dlg-factor-read{color:rgba(0,0,0,.62);}
.mx5-dlg-factor-bar{position:relative;height:7px;border-radius:4px;background:rgba(255,255,255,.08);}
[data-theme="light"] .mx5-dlg-factor-bar{background:rgba(0,0,0,.09);}
.mx5-dlg-factor-fill{position:absolute;left:0;top:0;height:100%;border-radius:4px;opacity:.85;}
.mx5-dlg-factor-score{font-size:16px;font-weight:800;text-align:right;font-variant-numeric:tabular-nums;}
/* Bar tick labels (0 / 50 / 100) */
.mx5-dlg-bar-ticks{display:flex;justify-content:space-between;margin-top:4px;font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));}
@media(max-width:700px){.mx5-dlg-bar-ticks{display:none;}}

/* Weakest-leg callout (SIGNALS dialog) */
.mx5-dlg-weakest-callout{
  display:flex;gap:12px;align-items:flex-start;
  padding:14px 16px;
  background:rgba(245,158,11,.07);border-radius:12px;
  border:1px solid rgba(245,158,11,.2);
  margin:4px 0 16px;
}
.mx5-dlg-weakest-icon{
  width:32px;height:32px;border-radius:8px;flex-shrink:0;
  background:rgba(245,158,11,.14);display:flex;align-items:center;justify-content:center;
}
.mx5-dlg-weakest-label{font-size:13px;font-weight:700;color:var(--mx5-warn,#f59e0b);margin-bottom:3px;}
.mx5-dlg-weakest-sub{font-size:11px;color:var(--ink-2,rgba(255,255,255,.6));}
[data-theme="light"] .mx5-dlg-weakest-sub{color:rgba(0,0,0,.55);}

/* MTF tape table (inside SIGNALS dialog) */
.mx5-dlg-mtf-tbl{width:100%;border-collapse:collapse;font-size:11.5px;margin-top:10px;}
.mx5-dlg-mtf-tbl th{
  text-align:left;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:var(--ink-3,rgba(255,255,255,.36));padding:0 0 8px;
}
[data-theme="light"] .mx5-dlg-mtf-tbl th{color:rgba(0,0,0,.58);}
.mx5-dlg-mtf-tbl th:not(:first-child){text-align:center;}
.mx5-dlg-mtf-tbl td{padding:6px 0;}
.mx5-dlg-mtf-tbl td:not(:first-child){text-align:center;}
.mx5-dlg-mtf-tbl tbody tr+tr td{border-top:1px solid rgba(255,255,255,.05);}
[data-theme="light"] .mx5-dlg-mtf-tbl tbody tr+tr td{border-top-color:rgba(0,0,0,.05);}
.mx5-dlg-mtf-conf.good{color:var(--ink-up, var(--up,#22d97a));}
.mx5-dlg-mtf-conf.bad{color:var(--ink-down, var(--down,#ef4444));}
.mx5-dlg-mtf-conf.flat{color:var(--ink-3,rgba(255,255,255,.36));}

/* Index deep cards (MARKETS dialog) */
.mx5-dlg-idx-grid{
  display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px;
}
@media(max-width:700px){.mx5-dlg-idx-grid{grid-template-columns:repeat(2,1fr);}}
.mx5-dlg-idx-card{
  padding:14px 14px 12px;
  background:rgba(255,255,255,.04);border-radius:12px;
  border:1px solid rgba(255,255,255,.08);
}
[data-theme="light"] .mx5-dlg-idx-card{background:rgba(0,0,0,.03);border-color:rgba(0,0,0,.07);}
.mx5-dlg-idx-ticker{font-size:12px;font-weight:700;margin-bottom:1px;}
.mx5-dlg-idx-name{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));margin-bottom:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
[data-theme="light"] .mx5-dlg-idx-name{color:rgba(0,0,0,.62);}
.mx5-dlg-idx-px{font-size:20px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums;margin-bottom:3px;}
.mx5-dlg-idx-chg{font-size:11.5px;font-weight:700;font-variant-numeric:tabular-nums;margin-bottom:10px;}
.mx5-dlg-idx-chg.up{color:var(--ink-up, var(--up,#22d97a));}
.mx5-dlg-idx-chg.dn{color:var(--ink-down, var(--down,#ef4444));}
.mx5-dlg-idx-chips{display:flex;flex-wrap:wrap;gap:4px;}
.mx5-dlg-idx-chip{
  display:inline-flex;align-items:center;padding:2px 7px;
  border-radius:6px;font-size:11px;font-weight:600;
}
.mx5-dlg-idx-chip.ok{color:var(--ink-up, var(--up,#22d97a));background:rgba(62,200,122,.1);border:1px solid rgba(62,200,122,.2);}
.mx5-dlg-idx-chip.wn{color:var(--ink-warn, var(--warn,#f59e0b));background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.2);}
.mx5-dlg-idx-chip.mt{color:var(--ink-3,rgba(255,255,255,.36));background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);}
[data-theme="light"] .mx5-dlg-idx-chip.mt{color:rgba(0,0,0,.58);background:rgba(0,0,0,.04);border-color:rgba(0,0,0,.08);}

/* Sector columns (MARKETS dialog) */
.mx5-dlg-sector-cols{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px;}
.mx5-dlg-sector-col-head{
  font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:var(--ink-3,rgba(255,255,255,.36));margin-bottom:10px;
}
[data-theme="light"] .mx5-dlg-sector-col-head{color:rgba(0,0,0,.58);}
.mx5-dlg-sector-row{
  display:flex;align-items:center;gap:8px;padding:9px 0;
  border-bottom:1px solid rgba(255,255,255,.05);font-size:12px;
}
[data-theme="light"] .mx5-dlg-sector-row{border-bottom-color:rgba(0,0,0,.05);}
.mx5-dlg-sector-arr{font-size:11px;flex-shrink:0;}
.mx5-dlg-sector-arr.heat{color:var(--ink-down, var(--down,#ef4444));}
.mx5-dlg-sector-arr.cool{color:var(--ink-up, var(--up,#22d97a));}
.mx5-dlg-sector-name{flex:1;font-weight:500;}
.mx5-dlg-sector-rk{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));font-variant-numeric:tabular-nums;}
[data-theme="light"] .mx5-dlg-sector-rk{color:rgba(0,0,0,.58);}

/* ── Sector Temperature — rotation ladder (dlg-sector rebuild) ─────────────────
   Each sector is a rung; the little trace is its 5-day rank move (an honest 2-point
   trajectory — up = climbed, down = slipped), coloured green/red via --up/--down so
   ZH flips. Lane = current standing (leading / lagging); trace + delta = the move. */
.sct-lane{margin:0 0 20px;}
.sct-lane:last-of-type{margin-bottom:6px;}
.sct-lane-head{display:flex;align-items:center;gap:8px;margin:0 0 11px;
  font:700 11px/1 var(--font-ui,inherit);letter-spacing:.09em;text-transform:uppercase;}
.sct-lane-dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto;box-shadow:0 0 9px currentColor;}
.sct-lane.lead .sct-lane-head{color:color-mix(in srgb,var(--up,#22d97a) 78%,var(--text));}
.sct-lane.lag  .sct-lane-head{color:color-mix(in srgb,var(--down,#ef4444) 78%,var(--text));}
.sct-lane.lead .sct-lane-dot{color:var(--ink-up, var(--up,#22d97a));background:currentColor;}
.sct-lane.lag  .sct-lane-dot{color:var(--ink-down, var(--down,#ef4444));background:currentColor;}
.sct-lane-n{margin-left:auto;font:600 10.5px/1 var(--font-ui,inherit);letter-spacing:.01em;text-transform:none;color:var(--ink-3,rgba(255,255,255,.42));}
.sct-rung{display:grid;grid-template-columns:32px 1fr 132px 54px;align-items:center;gap:12px;
  padding:11px 13px;border-radius:13px;background:rgba(255,255,255,.03);
  border:1px solid rgba(255,255,255,.06);transition:border-color .2s,background .2s,transform .16s;}
.sct-rung + .sct-rung{margin-top:8px;}
[data-theme="light"] .sct-rung{background:rgba(0,0,0,.018);border-color:rgba(0,0,0,.06);}
.sct-rung:hover{transform:translateY(-1px);background:rgba(255,255,255,.05);
  border-color:color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 36%,var(--line,rgba(255,255,255,.1)));}
[data-theme="light"] .sct-rung:hover{background:rgba(0,0,0,.035);}
.sct-badge{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;
  color:var(--sct-c,var(--up,#22d97a));background:color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 14%,transparent);
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 28%,transparent);}
.sct-badge svg{width:15px;height:15px;display:block;}
.sct-body{min-width:0;}
.sct-name{font:700 13px/1.25 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.92));
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.sct-sub{margin-top:2px;font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.44));display:flex;align-items:center;gap:7px;}
.sct-sub .sct-rk{font-variant-numeric:tabular-nums;font-weight:700;color:var(--ink-2,rgba(255,255,255,.6));}
.sct-sub .sct-stance{text-transform:capitalize;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sct-trace{width:132px;height:30px;display:block;overflow:visible;}
.sct-trace .sct-base{stroke:color-mix(in srgb,var(--ink-3,#8b93a1) 45%,transparent);stroke-width:1;stroke-dasharray:2 3;}
.sct-trace .sct-ln{fill:none;stroke:var(--sct-c,var(--up,#22d97a));stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;}
.sct-trace .sct-dot-old{fill:none;stroke:color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 55%,transparent);stroke-width:1.6;}
.sct-trace .sct-dot-now{fill:var(--sct-c,var(--up,#22d97a));}
.sct-delta{display:flex;flex-direction:column;align-items:flex-end;}
.sct-delta-v{font:800 16px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;color:var(--sct-c,var(--up,#22d97a));letter-spacing:-.01em;}
.sct-delta-k{margin-top:3px;font-size:9px;color:var(--ink-3,rgba(255,255,255,.4));letter-spacing:.02em;white-space:nowrap;}
@media(max-width:430px){
  .sct-rung{grid-template-columns:28px 1fr 82px 44px;gap:9px;padding:10px;}
  .sct-trace{width:82px;}
  .sct-delta-v{font-size:15px;}
}
@media(prefers-reduced-motion:no-preference){
  #dlg-sector .sct-rung{opacity:0;transform:translateY(8px);
    transition:opacity .44s ease,transform .44s cubic-bezier(.22,.9,.26,1.02),border-color .2s,background .2s;}
  #dlg-sector.mx5-dlg-in .sct-rung{opacity:1;transform:translateY(0);}
  #dlg-sector.mx5-dlg-in .sct-rung:nth-child(2){transition-delay:.05s}
  #dlg-sector.mx5-dlg-in .sct-rung:nth-child(3){transition-delay:.11s}
  #dlg-sector.mx5-dlg-in .sct-rung:nth-child(4){transition-delay:.17s}
  #dlg-sector.mx5-dlg-in .sct-rung:nth-child(5){transition-delay:.23s}
  #dlg-sector .sct-trace .sct-ln{stroke-dasharray:150;stroke-dashoffset:150;}
  #dlg-sector.mx5-dlg-in .sct-trace .sct-ln{transition:stroke-dashoffset .72s cubic-bezier(.22,.9,.26,1.02) .22s;stroke-dashoffset:0;}
  #dlg-sector .sct-trace .sct-dot-now{opacity:0;}
  #dlg-sector.mx5-dlg-in .sct-trace .sct-dot-now{transition:opacity .3s ease .6s;opacity:1;}
}

/* ── News modal — Market Intelligence headline list (nbx-*): each headline is a
     tappable card with a theme tag, the outlet + date, and a summary snippet — replaces
     the bare title-only accordion (the "no context / no dates" complaint). ── */
.nbx-list{display:flex;flex-direction:column;gap:8px;margin-top:12px;}
.nbx-item{display:block;text-decoration:none;color:inherit;padding:11px 13px;border-radius:11px;
  background:rgba(255,255,255,.028);border:1px solid rgba(255,255,255,.06);
  transition:border-color .2s,background .2s,transform .16s;}
[data-theme="light"] .nbx-item{background:rgba(0,0,0,.02);border-color:rgba(0,0,0,.06);}
.nbx-item:hover{transform:translateY(-1px);background:rgba(255,255,255,.05);
  border-color:color-mix(in srgb,var(--link,#22d97a) 34%,var(--line,rgba(255,255,255,.1)));}
[data-theme="light"] .nbx-item:hover{background:rgba(0,0,0,.035);}
.nbx-top{display:flex;align-items:baseline;gap:9px;min-width:0;}
.nbx-theme{flex:0 0 auto;font:700 9px/1 var(--font-ui,inherit);letter-spacing:.06em;text-transform:uppercase;
  padding:3px 7px;border-radius:5px;color:var(--ink-2,rgba(255,255,255,.6));
  background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.09);white-space:nowrap;margin-top:1px;}
[data-theme="light"] .nbx-theme{background:rgba(0,0,0,.045);border-color:rgba(0,0,0,.09);}
.nbx-title{flex:1;min-width:0;font:600 13px/1.4 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.92));}
.nbx-meta{display:flex;align-items:center;gap:8px;margin-top:6px;font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.42));}
.nbx-src{font-weight:700;color:var(--ink-2,rgba(255,255,255,.6));white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px;}
.nbx-dot{opacity:.5;}
.nbx-date{font-variant-numeric:tabular-nums;white-space:nowrap;}
.nbx-arrow{margin-left:auto;font-weight:700;color:var(--ink-link, var(--link,#22d97a));white-space:nowrap;}
.nbx-sum{margin-top:6px;font-size:11.5px;line-height:1.5;color:var(--ink-3,rgba(255,255,255,.5));
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}
@media(prefers-reduced-motion:no-preference){
  #dlg-news .nbx-item{opacity:0;transform:translateY(6px);transition:opacity .4s ease,transform .4s cubic-bezier(.22,.9,.26,1.02),border-color .2s,background .2s;}
  #dlg-news.mx5-dlg-in .nbx-item{opacity:1;transform:translateY(0);}
  #dlg-news.mx5-dlg-in .nbx-item:nth-child(2){transition-delay:.04s}
  #dlg-news.mx5-dlg-in .nbx-item:nth-child(3){transition-delay:.08s}
  #dlg-news.mx5-dlg-in .nbx-item:nth-child(4){transition-delay:.12s}
  #dlg-news.mx5-dlg-in .nbx-item:nth-child(n+5){transition-delay:.15s}
}

/* Asset tiles (MARKETS dialog) */
.mx5-dlg-asset-row{
  display:flex;flex-wrap:wrap;gap:10px;margin-top:4px;
}
.mx5-dlg-asset-tile{
  flex:1 1 100px;min-width:90px;
  padding:12px 12px 10px;
  background:rgba(255,255,255,.03);border-radius:12px;
  border:1px solid rgba(255,255,255,.07);
  text-align:center;
}
[data-theme="light"] .mx5-dlg-asset-tile{background:rgba(0,0,0,.025);border-color:rgba(0,0,0,.07);}
.mx5-dlg-asset-lbl{font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--ink-3,rgba(255,255,255,.36));margin-bottom:6px;}
[data-theme="light"] .mx5-dlg-asset-lbl{color:rgba(0,0,0,.58);}
.mx5-dlg-asset-val{font-size:17px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1;margin-bottom:3px;}
.mx5-dlg-asset-ctx{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));}
[data-theme="light"] .mx5-dlg-asset-ctx{color:rgba(0,0,0,.58);}

/* Events calendar cards (EVENTS dialog) */
.mx5-dlg-cal-grid{
  display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-bottom:20px;
}
.mx5-dlg-cal-card{
  padding:14px 14px 12px;
  background:rgba(255,255,255,.04);border-radius:12px;
  border:1px solid rgba(255,255,255,.07);
  position:relative;
}
.mx5-dlg-cal-card.hot{border-color:rgba(245,158,11,.25);background:rgba(245,158,11,.04);}
[data-theme="light"] .mx5-dlg-cal-card{background:rgba(0,0,0,.03);border-color:rgba(0,0,0,.07);}
[data-theme="light"] .mx5-dlg-cal-card.hot{background:rgba(245,158,11,.04);}
/* ── Calendar date = Release Radar selector (rr-inline, 2026-07) ─────────────
   Every non-FOMC card selects its date for the inline panel below. Covered
   dates carry a subtle radar dot; every selector sharing the selected date
   receives the same --info accent ring. FOMC cards route to Fed Path instead. */
.mx5-dlg-cal-card.rr-select{cursor:pointer;transition:border-color .16s ease,box-shadow .22s ease,background .16s ease;}
.mx5-dlg-cal-card.rr-select:hover{border-color:color-mix(in srgb,var(--info,#60a5fa) 40%,transparent);box-shadow:0 2px 12px color-mix(in srgb,var(--info,#60a5fa) 8%,transparent);}
.mx5-dlg-cal-card.rr-select:focus-visible{outline:2px solid var(--info,#60a5fa);outline-offset:2px;}
/* Selected date — outer blue ring survives green/amber live-status fills. */
.mx5-dlg-cal-card.rr-active{
  border-color:color-mix(in srgb,var(--info,#60a5fa) 58%,transparent);
  background:color-mix(in srgb,var(--info,#60a5fa) 8%,rgba(255,255,255,.04));
  box-shadow:0 0 0 2px color-mix(in srgb,var(--info,#60a5fa) 72%,transparent),0 6px 18px -10px color-mix(in srgb,var(--info,#60a5fa) 60%,transparent);
}
[data-theme="light"] .mx5-dlg-cal-card.rr-active{background:color-mix(in srgb,var(--info,#60a5fa) 9%,rgba(0,0,0,.03));}
/* covered-date indicator — small radar dot chip (replaces the old "Release Radar ▸" text link) */
.mx5-dlg-cal-radar{display:inline-flex;align-items:center;gap:5px;margin-top:8px;
  font-size:10px;font-weight:700;letter-spacing:.02em;color:var(--ink-info, var(--info,#60a5fa));}
.mx5-dlg-cal-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0;
  background:var(--info,#60a5fa);position:relative;}
.mx5-dlg-cal-dot::after{content:"";position:absolute;inset:-3px;border-radius:50%;
  border:1px solid color-mix(in srgb,var(--info,#60a5fa) 55%,transparent);
  animation:rrDotPulse 2.4s ease-in-out infinite;}
@keyframes rrDotPulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.5);opacity:0}}
.mx5-dlg-cal-card.rr-active .mx5-dlg-cal-dot::after{animation:none;opacity:.9;transform:scale(1.15);}
/* Fed Path affordance chip — routes to dlg-fed (FOMC cards only) */
.mx5-dlg-cal-fed{display:inline-flex;align-items:center;gap:5px;margin-top:8px;
  padding:3px 9px;border-radius:999px;font-size:10.5px;font-weight:700;letter-spacing:.02em;
  color:color-mix(in srgb,var(--link,#22d97a) 88%,var(--text));
  background:color-mix(in srgb,var(--link,#22d97a) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--link,#22d97a) 32%,transparent);
  transition:background .16s ease,border-color .16s ease,transform .14s ease;}
.mx5-dlg-cal-card.rr-fed{cursor:pointer;transition:border-color .16s ease,box-shadow .22s ease;}
.mx5-dlg-cal-card.rr-fed:hover{border-color:color-mix(in srgb,var(--link,#22d97a) 40%,transparent);}
.mx5-dlg-cal-card.rr-fed:hover .mx5-dlg-cal-fed{background:color-mix(in srgb,var(--link,#22d97a) 20%,transparent);border-color:color-mix(in srgb,var(--link,#22d97a) 50%,transparent);transform:translateX(1px);}
.mx5-dlg-cal-card.rr-fed:focus-visible{outline:2px solid var(--link,#22d97a);outline-offset:2px;}
@media (prefers-reduced-motion: reduce){
  .mx5-dlg-cal-dot::after{animation:none;opacity:.6;}
  .mx5-dlg-cal-card.rr-select,.mx5-dlg-cal-card.rr-fed,.mx5-dlg-cal-fed{transition:none;}
  .mx5-dlg-cal-card.rr-fed:hover .mx5-dlg-cal-fed{transform:none;}
}
.mx5-dlg-cal-date{font-size:11px;font-weight:700;color:var(--ink-3,rgba(255,255,255,.36));margin-bottom:5px;}
[data-theme="light"] .mx5-dlg-cal-date{color:rgba(0,0,0,.62);}
.mx5-dlg-cal-title{font-size:13px;font-weight:700;margin-bottom:6px;line-height:1.3;}
.mx5-dlg-cal-meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
.mx5-dlg-cal-time{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));}
[data-theme="light"] .mx5-dlg-cal-time{color:rgba(0,0,0,.62);}
.mx5-dlg-cal-badge{
  display:inline-flex;align-items:center;padding:2px 8px;border-radius:6px;
  font-size:11px;font-weight:700;
}
.mx5-dlg-cal-badge.high{color:var(--ink-down, var(--down,#ef4444));background:rgba(239,68,68,.12);border:1px solid rgba(239,68,68,.2);}
.mx5-dlg-cal-badge.med{color:var(--ink-warn, var(--warn,#f59e0b));background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.18);}
.mx5-dlg-cal-badge.low{color:var(--ink-3,rgba(255,255,255,.36));background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);}
[data-theme="light"] .mx5-dlg-cal-badge.low{color:rgba(0,0,0,.58);background:rgba(0,0,0,.04);border-color:rgba(0,0,0,.08);}

/* Fed strip inside dialogs (EVENTS dialog) */
.mx5-dlg-fed-strip{
  display:flex;flex-direction:column;gap:6px;
  padding:14px 16px;
  background:rgba(255,255,255,.03);border-radius:12px;
  border:1px solid rgba(255,255,255,.07);
  margin-bottom:20px;
}
[data-theme="light"] .mx5-dlg-fed-strip{background:rgba(0,0,0,.025);border-color:rgba(0,0,0,.07);}
.mx5-dlg-fed-item{display:flex;align-items:center;justify-content:space-between;padding:5px 0;}
.mx5-dlg-fed-item+.mx5-dlg-fed-item{border-top:1px solid rgba(255,255,255,.05);}
[data-theme="light"] .mx5-dlg-fed-item+.mx5-dlg-fed-item{border-top-color:rgba(0,0,0,.05);}
.mx5-dlg-fed-desc{font-size:12px;flex:1;padding-right:12px;color:var(--ink-2,rgba(255,255,255,.6));}
[data-theme="light"] .mx5-dlg-fed-desc{color:rgba(0,0,0,.55);}
.mx5-dlg-fed-val{font-size:13px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--ink-link, var(--link,#22d97a));white-space:nowrap;}
.mx5-dlg-fed-chg{font-size:11px;font-variant-numeric:tabular-nums;margin-left:6px;}
.mx5-dlg-fed-chg.pos{color:var(--ink-up,var(--up,#22d97a));}.mx5-dlg-fed-chg.neg{color:var(--ink-down,var(--down,#ef4444));}
.mx5-dlg-fed-src{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));text-align:right;padding-top:6px;}
[data-theme="light"] .mx5-dlg-fed-src{color:rgba(0,0,0,.58);}

/* ── Inline Release Radar panel (#rr-inline, EVENTS dialog) ───────────────────
   Replaces the retired per-date popup + its open button. Shows the selected
   calendar date's model prints on the same surface; reuses the RR card renderer
   + #rr-modal for depth. Header carries the selected date + a covered radar dot;
   body cross-fades on date swap; one display-only footer. */
#rr-inline{margin-top:4px;}
.rr-inline-head{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:10px;}
.rr-inline-date{display:inline-flex;align-items:center;gap:7px;
  font-size:14px;font-weight:800;letter-spacing:-.01em;color:var(--ink-1,rgba(255,255,255,.94));
  font-variant-numeric:tabular-nums;}
.rr-inline-date .mx5-dlg-cal-dot{width:8px;height:8px;}
.rr-inline-sub{font-size:11.5px;color:var(--ink-3,rgba(255,255,255,.42));}
[data-theme="light"] .rr-inline-sub{color:rgba(0,0,0,.62);}
/* body: cross-fade on swap (JS toggles .rr-inline-swap for one frame) */
.rr-inline-body{transition:opacity .22s ease;}
.rr-inline-body.rr-inline-swap{opacity:0;}
.rr-inline-body .rr-grid{display:flex;flex-wrap:wrap;gap:12px;}
/* honest empty state (no coverage / auctions / FOMC-adjacent) */
.rr-inline-empty{padding:14px 16px;border-radius:12px;
  background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);
  display:flex;flex-direction:column;gap:6px;}
[data-theme="light"] .rr-inline-empty{background:rgba(0,0,0,.025);border-color:rgba(0,0,0,.07);}
.rr-inline-empty-line{font-size:12.5px;line-height:1.5;color:var(--ink-2,rgba(255,255,255,.72));}
[data-theme="light"] .rr-inline-empty-line{color:rgba(0,0,0,.62);}
.rr-inline-empty-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--ink-3,rgba(255,255,255,.42));}
[data-theme="light"] .rr-inline-empty-meta{color:rgba(0,0,0,.62);}
/* single display-only footer for the inline panel (Law 4: one footnote) */
.rr-inline-foot{margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,.06);
  font-size:10px;line-height:1.5;color:var(--ink-3,rgba(255,255,255,.36));}
[data-theme="light"] .rr-inline-foot{border-top-color:rgba(0,0,0,.06);color:rgba(0,0,0,.58);}
@media (prefers-reduced-motion: reduce){ .rr-inline-body{transition:none;} }

/* Heatmap wrap inside dialog — chromeless spacer (1.2 de-chrome) */
.mx5-dlg-heatmap-wrap{
  background:none;border:none;border-radius:0;
  overflow:visible;margin-bottom:20px;min-height:120px;
}
[data-theme="light"] .mx5-dlg-heatmap-wrap{background:none;border:none;}
/* .mx5-dlg-heatmap-head rules removed (1.2) */

/* ── Gauge SVG glow (JS patchable via data attrs) ───────────────── */
/* Arc and needle updated by risk_state_live.js; see §3.1 */
body.page-macro.mx4-grid #mx5-gauge-arc-fill{
  /* initial dasharray set by Jinja inline style; JS updates via setAttribute */
}
body.page-macro.mx4-grid #mx5-gauge-needle{
  /* rotate transform set by Jinja inline; JS updates on live push */
}
body.page-macro.mx4-grid #mx5-score-numeral{
  /* font-size 24px; glow filter via inline style */
  filter:drop-shadow(0 0 10px rgba(34,217,122,.7));
  display:none; /* 2.2: one glow remains on .mx5-big-score; DOM kept for risk_state_live.js */
}
body.page-macro.mx4-grid #mx5-score-numeral + text{display:none;} /* hides /100 sublabel */

/* ══════════════════════════════════════════════════════════════════
   S2 — v5 card face styles (ALL scoped body.page-macro.mx4-grid)
   Port from v5_final.html rev2; CSS token aliases → mx5 custom props
   ══════════════════════════════════════════════════════════════════ */

/* ── v5 grid ORDER: resequence cards without changing DOM ───────── */
/* DOM: sx-evidence(WTD), sx-events-v2, sx-markets-v2, sx-risk-v2(order:-1=row1)
   then sx-policy-v2, sx-aibrief-v2, sx-news-v2, sx-deep-context
   Static cards injected after sx-events-v2 in DOM so they fall in row 4 naturally.
   Visual row order: scorecard(-1), markets(1), wtd+events(2), static(3), alerts+policy+ai(4), deep(5) */
body.page-macro.mx4-grid #sx-markets-v2{order:1;}
body.page-macro.mx4-grid #sx-evidence{order:2;}
body.page-macro.mx4-grid #sx-events-v2{order:2;}
body.page-macro.mx4-grid #sx-v5-fed{order:3;}
body.page-macro.mx4-grid #sx-v5-sentiment{order:3;}
body.page-macro.mx4-grid #sx-v5-sector{order:3;}
body.page-macro.mx4-grid #sx-news-v2{order:4;}
body.page-macro.mx4-grid #sx-policy-v2{order:4;}
body.page-macro.mx4-grid #sx-aibrief-v2{order:4;}
body.page-macro.mx4-grid #sx-deep-context{order:5;}

/* ── v5 static card shell (matches .card in v5_final) ─────────── */
body.page-macro.mx4-grid .mx5-card{
  background:var(--mx5-glass-bg);
  border:1px solid var(--mx5-glass-border);
  border-radius:var(--mx5-radius-card);
  backdrop-filter:var(--mx5-blur);
  box-shadow:var(--mx5-glass-shadow);
  padding:24px 26px;
  position:relative;overflow:hidden;
  display:flex;flex-direction:column;
  height:100%;box-sizing:border-box;
}
body.page-macro.mx4-grid .mx5-card::before{
  content:"";position:absolute;inset:0;
  border-radius:var(--mx5-radius-card);
  background:linear-gradient(135deg,rgba(255,255,255,.04) 0%,transparent 55%);
  pointer-events:none;
}
/* Static-card click target (Fed / Sentiment / Sector) */
body.page-macro.mx4-grid .mx5-card[role="button"]{cursor:pointer;transition:background .2s ease-out,border-color .2s ease-out,box-shadow .2s ease-out,transform .2s ease-out;}
body.page-macro.mx4-grid .mx5-card[role="button"]:hover{background:var(--mx5-hover-bg);border-color:var(--mx5-hover-border);box-shadow:var(--mx5-hover-shadow);transform:translateY(-1px);}
body.page-macro.mx4-grid .mx5-card[role="button"]:focus-visible{outline:none;box-shadow:var(--mx5-focus-ring),var(--mx5-hover-shadow);}
/* sxg-face in grid view = v5 card face; override default padding to match .mx5-card */
body.page-macro.mx4-grid .sxg-face.mx5-card-face{
  background:var(--mx5-glass-bg);
  border:1px solid var(--mx5-glass-border);
  border-radius:var(--mx5-radius-card)!important;
  backdrop-filter:var(--mx5-blur);
  box-shadow:var(--mx5-glass-shadow);
  padding:24px 26px!important;
  min-height:unset;
  height:100%;
  transition:background .2s ease-out,border-color .2s ease-out,box-shadow .2s ease-out,transform .2s ease-out;
}
body.page-macro.mx4-grid .sxg-face.mx5-card-face::before{
  content:"";position:absolute;inset:0;
  border-radius:inherit;
  background:linear-gradient(135deg,rgba(255,255,255,.04) 0%,transparent 55%);
  pointer-events:none;
}
body.page-macro.mx4-grid .sx:hover .sxg-face.mx5-card-face,
body.page-macro.mx4-grid .sxg-face.mx5-card-face:hover{
  background:var(--mx5-hover-bg);
  border-color:var(--mx5-hover-border);
  box-shadow:var(--mx5-hover-shadow);
  transform:translateY(-1px);
}
body.page-macro.mx4-grid .sxg-face.mx5-card-face:focus-visible{
  outline:none;box-shadow:var(--mx5-focus-ring),var(--mx5-hover-shadow);
}
/* Card title row */
body.page-macro.mx4-grid .mx5-card-title{
  font-size:13px;font-weight:700;
  color:var(--ink-1,rgba(255,255,255,.92));
  letter-spacing:-.01em;margin-bottom:18px;
}
body.page-macro.mx4-grid .mx5-card-title-row{
  display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;
}
body.page-macro.mx4-grid .mx5-card-badge{
  font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;
  padding:3px 9px;border-radius:var(--mx5-radius-pill);
  background:rgba(255,255,255,.07);color:var(--ink-2,rgba(255,255,255,.6));
}
/* Static card sections (not .sx — no island): sit in the rack grid */
body.page-macro.mx4-grid .sx-v5-static{
  /* participates in the rack 12-col grid just like .sx */
}
body.page-macro:not(.mx4-grid) .sx-v5-static{
  display:none; /* hidden in ledger view — these are grid-only surfaces */
}
/* D1: command scorecard (left+right) must be hidden in ledger view, mirroring .sx-v5-static */
body.page-macro:not(.mx4-grid) .mx5-sc-left,
body.page-macro:not(.mx4-grid) .mx5-sc-right{display:none;}

/* ── MARKETS tiles (v5: four-col strip inside the sxg-face) ────── */
body.page-macro.mx4-grid #sx-markets-v2 .sxg-face.mx5-card-face{
  /* Markets face = full-width tile strip; override flex-direction for row layout */
  display:flex;flex-direction:column;
  padding:18px 20px 14px!important;
}
body.page-macro.mx4-grid .mx5-mkt-grid{
  display:grid;grid-template-columns:repeat(6,1fr);gap:16px;
}
@media(max-width:1100px){
  body.page-macro.mx4-grid .mx5-mkt-grid{grid-template-columns:repeat(3,1fr);}
}
@media(max-width:700px){
  body.page-macro.mx4-grid .mx5-mkt-grid{grid-template-columns:1fr 1fr;}
}
body.page-macro.mx4-grid .mx5-mkt-tile{
  /* v5.3.1: tiles are NESTED inside an already-glass card — glass-on-glass at .1 over .1
     compounded to ~19% white ("too bright"). Inner surfaces use a subtle 3% fill, no
     second blur, hairline border, no drop shadow. */
  background:rgba(255,255,255,.03);
  border:1px solid rgba(255,255,255,.08);
  border-radius:12px;
  padding:16px 18px 12px;
  position:relative;overflow:hidden;cursor:pointer;
  transition:background .2s ease-out,border-color .2s ease-out,box-shadow .2s ease-out,transform .2s ease-out;
}
/* Light: the dark "3% fill on glass" trick inverts badly — a 3% BLACK wash on a
   white card is a grey smudge with a 1.10:1 edge, so the six futures read as one
   undivided band. Each tile becomes its own white surface with the recipe
   hairline and a single contact shadow: the same card idiom as the panel that
   holds them, one scale down. The 16px grid gap does the rest of the separating. */
[data-theme="light"] body.page-macro.mx4-grid .mx5-mkt-tile{
  background:#ffffff;border-color:#dde2ea;
  box-shadow:0 1px 2px rgba(23,32,55,.05);
}
/* v5.3.1: tiles sit calm — neutral border like every other card; direction color
   lives on the delta text and a dimmed sparkline only (operator: too bright) */
body.page-macro.mx4-grid .mx5-mkt-tile.up,
body.page-macro.mx4-grid .mx5-mkt-tile.dn{border-color:var(--glass-border,rgba(255,255,255,.12));}
/* Unified hover (Order 5) — overrides the directional .up/.dn border on hover
   so no accent tint survives; placed AFTER .up/.dn for cascade precedence. */
body.page-macro.mx4-grid .mx5-mkt-tile:hover,
body.page-macro.mx4-grid .mx5-mkt-tile.up:hover,
body.page-macro.mx4-grid .mx5-mkt-tile.dn:hover{
  background:var(--mx5-hover-bg);
  border-color:var(--mx5-hover-border);
  box-shadow:var(--mx5-hover-shadow);
  transform:translateY(-1px);
}
body.page-macro.mx4-grid .mx5-mkt-tile:focus-visible{outline:none;box-shadow:var(--mx5-focus-ring),var(--mx5-hover-shadow);}
body.page-macro.mx4-grid .mx5-mkt-ticker{
  font-size:11px;font-weight:700;letter-spacing:.07em;
  color:var(--ink-3,rgba(255,255,255,.36));text-transform:uppercase;margin-bottom:3px;
}
body.page-macro.mx4-grid .mx5-mkt-sub{
  font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));
  letter-spacing:.04em;text-transform:uppercase;margin-bottom:4px;
}
body.page-macro.mx4-grid .mx5-mkt-price{
  font-size:19px;font-weight:700;line-height:1;
  color:var(--ink-1,rgba(255,255,255,.92));margin-bottom:4px;
  font-variant-numeric:tabular-nums;
  min-height:1em;min-width:8ch;display:block;
}
/* Skeleton keeps the shimmer; geometry lives on the node so dropping .skel
   (null/behind) cannot collapse the tile. ~8ch matches a live quote ("6,712.25"). */
body.page-macro.mx4-grid .mx5-mkt-price.skel{
  display:block;
}
/* .dtp-token is a chip in theme.css; on a Markets price node size it to the tile. */
body.page-macro.mx4-grid .mx5-mkt-price.dtp-token{
  display:block;font-size:19px;font-weight:700;letter-spacing:normal;
  text-transform:none;gap:0;align-items:baseline;color:var(--muted);
}
body.page-macro.mx4-grid .mx5-mkt-delta.skel{
  min-height:1em;min-width:3.2ch;display:block;
}
body.page-macro .mx5-card-stance{
  font-size:var(--fs-sm);line-height:1.45;color:var(--ink-2);margin-top:8px;font-weight:500;
}
body.page-macro.mx4-grid .mx5-mkt-delta{font-size:13px;font-weight:600;}
body.page-macro.mx4-grid .mx5-mkt-delta.up{color:var(--ink-up, var(--up,#22d97a));}
body.page-macro.mx4-grid .mx5-mkt-delta.dn{color:var(--ink-down, var(--down,#ef4444));}
/* live.js paintChg speaks up/down (not dn) — alias it into the same token path so a
   live-patched delta paints identically to a baked one (and flips in zh with it) */
body.page-macro.mx4-grid .mx5-mkt-delta.down{color:var(--ink-down, var(--down,#ef4444));}
body.page-macro.mx4-grid .mx5-spark{margin-top:10px;}
body.page-macro.mx4-grid .mx5-spark svg{width:100%;height:32px;display:block;}

/* B3: intl risk chips in the hero button row — red (alert) variant + non-interactive chip */
body.page-macro.mx4-grid a.mx5-sc-btn{text-decoration:none;}
body.page-macro.mx4-grid .mx5-sc-btn-alert{
  color:var(--ink-down, var(--down,#ef4444));
  border-color:color-mix(in srgb,var(--down,#ef4444) 30%,transparent);
  background:color-mix(in srgb,var(--down,#ef4444) 9%,transparent);
}
body.page-macro.mx4-grid .mx5-sc-btn-up{
  color:color-mix(in srgb,var(--up,#22c55e) 80%,white);
  border-color:color-mix(in srgb, var(--up) 45%, var(--gbtn-brd));
  background:linear-gradient(180deg, color-mix(in srgb, var(--up) 12%, var(--gbtn-bg)), var(--gbtn-bg));
}
body.page-macro.mx4-grid .mx5-sc-btn-up:hover{
  color:color-mix(in srgb,var(--up,#22c55e) 90%,white);
  border-color:color-mix(in srgb, var(--up) 60%, var(--gbtn-brd));
  background:linear-gradient(180deg, color-mix(in srgb, var(--up) 20%, var(--gbtn-bg)), var(--gbtn-bg));
}
body.page-macro.mx4-grid .mx5-sc-btn-up-strong{
  color:color-mix(in srgb,var(--up,#22c55e) 90%,white);
  border-color:color-mix(in srgb, var(--up) 60%, var(--gbtn-brd));
  background:linear-gradient(180deg, color-mix(in srgb, var(--up) 20%, var(--gbtn-bg)), var(--gbtn-bg));
}
body.page-macro.mx4-grid .mx5-sc-btn-static{cursor:default;}
/* B3 (now in dlg-risk): intl section classes — re-scoped to body.page-macro (dialog is not
   inside .mx4-grid; both grid view and dialog share these classes) */
/* (.mx5-popover-intl removed — popover retired; content lives in dlg-risk Overseas section) */
body.page-macro .mx5-pop-asof{
  font-size:10px;font-weight:400;color:var(--ink-3,rgba(255,255,255,.36));
  margin-left:8px;font-variant-numeric:tabular-nums;
}
body.page-macro .mx5-pop-intl-body{padding:4px 8px 8px;}
/* Market grid: alert tiles first, 2-col auto-fill */
body.page-macro .mx5-pop-intl-grid{
  display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:6px;
  margin-bottom:10px;
}
body.page-macro .mx5-pop-intl-tile{
  display:flex;align-items:center;gap:5px;
  padding:5px 7px;border-radius:7px;
  background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);
  font-size:11px;line-height:1.3;
}
[data-theme="light"] body.page-macro .mx5-pop-intl-tile{
  background:rgba(0,0,0,.02);border-color:rgba(0,0,0,.06);
}
body.page-macro .mx5-pop-intl-tile.intl-alert{
  border-color:color-mix(in srgb,var(--down,#ef4444) 28%,transparent);
  background:color-mix(in srgb,var(--down,#ef4444) 6%,transparent);
}
body.page-macro .mx5-intl-dot{
  width:6px;height:6px;border-radius:50%;flex-shrink:0;
  background:var(--ink-3,rgba(255,255,255,.36));
}
body.page-macro .mx5-intl-dot.intl-dot-alert{background:var(--down,#ef4444);}
body.page-macro .mx5-intl-name{flex:1;min-width:0;color:var(--ink-2,rgba(255,255,255,.62));}
body.page-macro .mx5-intl-score{
  font-size:11px;font-weight:700;font-variant-numeric:tabular-nums;
  color:var(--ink-3,rgba(255,255,255,.36));margin-left:auto;flex-shrink:0;
}
body.page-macro .mx5-intl-score.intl-score-alert{color:var(--ink-down, var(--down,#ef4444));}
/* Spread speed row */
body.page-macro .mx5-pop-intl-spread{
  font-size:12px;line-height:1.5;color:var(--ink-2,rgba(255,255,255,.62));
  padding:6px 0;border-top:1px solid rgba(255,255,255,.06);margin-bottom:8px;
}
[data-theme="light"] body.page-macro .mx5-pop-intl-spread{border-color:rgba(0,0,0,.07);}
body.page-macro .mx5-pop-intl-small{
  display:block;font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.36));margin-top:3px;
}
/* Spillover board */
body.page-macro .mx5-pop-intl-spill{
  padding:6px 0;border-top:1px solid rgba(255,255,255,.06);margin-bottom:8px;
}
[data-theme="light"] body.page-macro .mx5-pop-intl-spill{border-color:rgba(0,0,0,.07);}
body.page-macro .mx5-pop-intl-spill-hd{
  display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;
  color:var(--ink-2,rgba(255,255,255,.62));margin-bottom:7px;
}
body.page-macro .mx5-pop-intl-spill-word{font-size:11.5px;font-weight:500;}
body.page-macro .mx5-pop-intl-spill-word.spill-alert{color:var(--ink-down, var(--down,#ef4444));}
body.page-macro .mx5-pop-intl-spill-word.spill-warn{color:var(--ink-warn, var(--warn,#f59e0b));}
body.page-macro .mx5-pop-intl-spill-word.spill-muted{color:var(--ink-3,rgba(255,255,255,.36));}
body.page-macro .mx5-pop-intl-legs{
  display:flex;flex-wrap:wrap;gap:5px;margin-bottom:5px;
}
