/* ══ FED FORWARD BOARD — dlg-fed rebuild (fbm-* = Fed Board) ══════════════════
   Signature idiom: a physical balance beam. Hawkish weight tilts it left (down),
   easing weight tilts it right. The tilt IS the stance — a cold reader gets
   "which way is policy leaning" before reading a word. Legs are chips resting on
   the pans; the full threshold receipt lives on each chip's hover (data-tip).
   All animation gated on .mx5-dlg-in + prefers-reduced-motion. */

/* — Pressure beam hero — */
.fbm-beam-wrap{position:relative;margin:4px 0 20px;padding:8px 4px 0;}
.fbm-beam-heads{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px;}
.fbm-beam-head{font:700 11px/1 var(--font-ui,inherit);letter-spacing:.04em;display:flex;align-items:baseline;gap:5px;}
.fbm-beam-head.hawk{color:var(--ink-down, var(--down,#ef4444));}
.fbm-beam-head.ease{color:var(--ink-up, var(--up,#22d97a));}
.fbm-beam-head .fbm-wt{font-size:15px;font-weight:800;font-variant-numeric:tabular-nums;}
/* The physical scale: fulcrum + rotating beam + two chip pans */
.fbm-beam-stage{position:relative;height:160px;}
.fbm-beam-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;}
/* beam bar rotates around the centre fulcrum by --tilt degrees */
.fbm-beam-bar{position:absolute;left:8%;right:8%;top:26px;height:4px;border-radius:3px;
  background:linear-gradient(90deg,var(--down,#ef4444),color-mix(in srgb,var(--down,#ef4444) 40%,var(--up,#22d97a)) 50%,var(--up,#22d97a));
  transform-origin:50% 50%;transform:rotate(var(--tilt,0deg));
  box-shadow:0 1px 6px -1px color-mix(in srgb,var(--isle-policy,#a070e8) 40%,transparent);}
/* Pans pivot about the BEAM's centreline (y≈28px), NOT the stage centre — otherwise the
   raised chip pan sweeps up THROUGH the beam line on the heavy side (the "Equity risk-off"
   clip). Matching the pivot keeps a constant gap between beam and chips across all tilts;
   pan top then just sets that gap (must clear the ±9° sweep of the top chip row). */
.fbm-beam-pans{position:absolute;inset:0;transform-origin:50% 28px;transform:rotate(var(--tilt,0deg));}
.fbm-beam-pan{position:absolute;top:54px;width:42%;display:flex;flex-direction:column;align-items:center;gap:5px;
  transform:rotate(calc(-1 * var(--tilt,0deg)));/* keep chips level while the beam tilts */}
.fbm-beam-pan.hawk{left:0;}
.fbm-beam-pan.ease{right:0;}
.fbm-beam-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:4px;max-width:100%;}
/* fulcrum triangle drawn in CSS, centred */
.fbm-fulcrum{position:absolute;left:50%;top:28px;transform:translateX(-50%);
  width:0;height:0;border-left:11px solid transparent;border-right:11px solid transparent;
  border-bottom:18px solid color-mix(in srgb,var(--isle-policy,#a070e8) 55%,var(--panel2,rgba(255,255,255,.05)));}
.fbm-fulcrum::after{content:"";position:absolute;left:50%;top:18px;transform:translateX(-50%);
  width:44px;height:3px;border-radius:2px;background:color-mix(in srgb,var(--isle-policy,#a070e8) 30%,transparent);}
/* leg chip: state colour by side + active weight */
.fbm-leg{display:inline-flex;align-items:center;gap:5px;font:600 10.5px/1 var(--font-ui,inherit);
  padding:4px 8px;border-radius:999px;white-space:nowrap;cursor:help;
  border:1px solid transparent;background:var(--panel2,rgba(255,255,255,.05));
  color:var(--ink-3,rgba(255,255,255,.42));transition:transform .16s ease,border-color .2s ease;}
.fbm-leg .fbm-dot{width:6px;height:6px;border-radius:50%;flex:0 0 auto;background:currentColor;opacity:.5;}
.fbm-leg.hawk{color:color-mix(in srgb,var(--down,#ef4444) 82%,var(--ink-2,#fff));border-color:color-mix(in srgb,var(--down,#ef4444) 20%,transparent);}
.fbm-leg.ease{color:color-mix(in srgb,var(--up,#22d97a) 82%,var(--ink-2,#fff));border-color:color-mix(in srgb,var(--up,#22d97a) 20%,transparent);}
.fbm-leg.on{font-weight:700;}
.fbm-leg.hawk.on{background:color-mix(in srgb,var(--down,#ef4444) 14%,transparent);border-color:color-mix(in srgb,var(--down,#ef4444) 40%,transparent);color:var(--ink-down, var(--down,#ef4444));}
.fbm-leg.ease.on{background:color-mix(in srgb,var(--up,#22d97a) 14%,transparent);border-color:color-mix(in srgb,var(--up,#22d97a) 40%,transparent);color:var(--ink-up, var(--up,#22d97a));}
.fbm-leg.on .fbm-dot{opacity:1;}
.fbm-leg:hover{transform:translateY(-1px);border-color:color-mix(in srgb,var(--text,#fff) 30%,transparent);}
/* verdict caption under the beam */
.fbm-beam-verdict{text-align:center;font:600 12px/1.4 var(--font-ui,inherit);color:var(--ink-2,rgba(255,255,255,.7));margin-top:6px;}
.fbm-beam-verdict .fbm-lean{font-weight:800;}
.fbm-beam-verdict .fbm-lean.ease{color:var(--ink-up, var(--up,#22d97a));}
.fbm-beam-verdict .fbm-lean.hawk{color:var(--ink-down, var(--down,#ef4444));}
.fbm-beam-verdict .fbm-lean.even{color:var(--ink-warn, var(--warn,#f59e0b));}

/* — Rate-path flagship chart (ported from dlg-policy plx idiom, bigger) — */
.fbm-chart-wrap{margin:2px 0 6px;}
.fbm-chart-svg{display:block;width:100%;height:auto;}
.fbm-chart-caption{font-size:12px;color:var(--ink-2,rgba(255,255,255,.68));line-height:1.5;margin-top:8px;}
.fbm-chart-take{font-size:12.5px;font-weight:600;color:var(--ink-1,rgba(255,255,255,.9));line-height:1.5;margin-top:6px;}
.fbm-gap-chip{display:inline-flex;align-items:center;gap:4px;font:600 11px/1 var(--font-ui,inherit);
  padding:3px 9px;border-radius:999px;margin-left:2px;cursor:help;
  background:rgba(245,158,11,.10);border:1px solid rgba(245,158,11,.26);color:var(--ink-warn, var(--warn,#f59e0b));}
.fbm-diamond-key{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--ink-warn, var(--warn,#f59e0b));margin-left:8px;}
.fbm-diamond-key svg{flex:0 0 auto;}

/* — Glance rows (inflation / risk) — state word + one plain line + ? tip — */
.fbm-row{display:flex;align-items:flex-start;gap:10px;padding:9px 0;}
.fbm-row+.fbm-row{border-top:1px solid rgba(255,255,255,.06);}
[data-theme="light"] .fbm-row+.fbm-row{border-top-color:rgba(0,0,0,.06);}
.fbm-row-state{flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;font:700 12px/1.3 var(--font-ui,inherit);min-width:96px;}
.fbm-row-dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto;}
.fbm-row-line{flex:1;min-width:0;font-size:12px;color:var(--ink-2,rgba(255,255,255,.66));line-height:1.5;}
.fbm-tip{display:inline-flex;align-items:center;justify-content:center;width:15px;height:15px;flex:0 0 auto;
  border-radius:50%;border:1px solid rgba(255,255,255,.22);color:var(--ink-3,rgba(255,255,255,.5));
  font:700 10px/1 var(--font-ui,inherit);cursor:help;margin-left:2px;user-select:none;transition:border-color .2s,color .2s;}
.fbm-tip:hover{border-color:var(--isle-policy,#a070e8);color:var(--isle-policy,#a070e8);}
[data-theme="light"] .fbm-tip{border-color:rgba(0,0,0,.22);color:rgba(0,0,0,.62);}

/* — Chip row (policy conditions) — */
.fbm-chips{display:flex;flex-wrap:wrap;gap:7px;margin:2px 0 4px;}
.fbm-chip{display:inline-flex;align-items:center;gap:6px;font:600 11.5px/1 var(--font-ui,inherit);
  padding:6px 11px;border-radius:999px;
  background:var(--panel2,rgba(255,255,255,.05));border:1px solid rgba(255,255,255,.1);
  color:var(--ink-1,rgba(255,255,255,.88));}
[data-theme="light"] .fbm-chip{background:rgba(0,0,0,.03);border-color:rgba(0,0,0,.1);}
.fbm-chip .fbm-chip-k{color:var(--ink-3,rgba(255,255,255,.45));font-weight:500;}
.fbm-chip.armed{border-color:color-mix(in srgb,var(--warn,#f59e0b) 42%,transparent);background:color-mix(in srgb,var(--warn,#f59e0b) 10%,transparent);color:var(--ink-warn, var(--warn,#f59e0b));}
.fbm-chip.warn{border-color:color-mix(in srgb,var(--down,#ef4444) 38%,transparent);background:color-mix(in srgb,var(--down,#ef4444) 9%,transparent);}

/* — Unified market-implied benchmark strip (shared: dlg-fed + dlg-events) — */
.fbm-bench{display:flex;flex-direction:column;gap:8px;margin:2px 0 6px;}
.fbm-bench-row{display:flex;align-items:center;gap:14px;padding:11px 14px;border-radius:12px;
  background:var(--panel2,rgba(255,255,255,.04));border:1px solid rgba(255,255,255,.08);}
[data-theme="light"] .fbm-bench-row{background:rgba(0,0,0,.025);border-color:rgba(0,0,0,.07);}
.fbm-bench-odds{font:800 26px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;color:var(--isle-policy,#a070e8);flex:0 0 auto;min-width:52px;}
.fbm-bench-odds small{font-size:13px;font-weight:600;color:var(--ink-3,rgba(255,255,255,.5));}
.fbm-bench-body{flex:1;min-width:0;}
.fbm-bench-outcome{font:700 13px/1.3 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.9));}
.fbm-bench-label{font-size:11px;color:var(--ink-3,rgba(255,255,255,.5));margin-top:1px;}
.fbm-bench-arrow{flex:0 0 auto;display:inline-flex;align-items:center;gap:3px;font:700 12px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;}
.fbm-bench-arrow.pos{color:var(--ink-up,var(--up,#22d97a));}
.fbm-bench-arrow.neg{color:var(--ink-down,var(--down,#ef4444));}
.fbm-bench-src{font-size:10px;color:var(--ink-3,rgba(255,255,255,.36));}
[data-theme="light"] .fbm-bench-odds small,[data-theme="light"] .fbm-bench-outcome{color:inherit;}

/* — Motion: beam settles + chart draws on dialog open — */
@media(prefers-reduced-motion:no-preference){
  /* beam swings from level → resting tilt */
  #dlg-fed .fbm-beam-bar,#dlg-fed .fbm-beam-pans{transform:rotate(0deg);
    transition:transform 720ms cubic-bezier(.34,1.28,.5,1);}
  #dlg-fed.mx5-dlg-in .fbm-beam-bar,#dlg-fed.mx5-dlg-in .fbm-beam-pans{transform:rotate(var(--tilt,0deg));}
  /* leg chips fade+rise, staggered */
  #dlg-fed .fbm-leg{opacity:0;transform:translateY(6px);transition:opacity .4s ease,transform .4s cubic-bezier(.22,.9,.26,1.02);}
  #dlg-fed.mx5-dlg-in .fbm-leg{opacity:1;transform:translateY(0);}
  #dlg-fed.mx5-dlg-in .fbm-leg:nth-child(1){transition-delay:.34s;}
  #dlg-fed.mx5-dlg-in .fbm-leg:nth-child(2){transition-delay:.42s;}
  #dlg-fed.mx5-dlg-in .fbm-leg:nth-child(3){transition-delay:.5s;}
  #dlg-fed.mx5-dlg-in .fbm-leg:nth-child(4){transition-delay:.58s;}
  #dlg-fed.mx5-dlg-in .fbm-leg:nth-child(n+5){transition-delay:.64s;}
  /* rate-path line reveal (stroke-dashoffset) + area fade — both dialogs */
  .fbm-chart-line{stroke-dasharray:var(--dash,1400);stroke-dashoffset:var(--dash,1400);}
  #dlg-fed.mx5-dlg-in .fbm-chart-line,#dlg-policy.mx5-dlg-in .fbm-chart-line{
    transition:stroke-dashoffset 900ms ease .25s;stroke-dashoffset:0;}
  .fbm-chart-area,.fbm-chart-node,.fbm-chart-diamond{opacity:0;}
  #dlg-fed.mx5-dlg-in .fbm-chart-area,#dlg-fed.mx5-dlg-in .fbm-chart-node,#dlg-fed.mx5-dlg-in .fbm-chart-diamond,
  #dlg-policy.mx5-dlg-in .fbm-chart-area,#dlg-policy.mx5-dlg-in .fbm-chart-node,#dlg-policy.mx5-dlg-in .fbm-chart-diamond{
    transition:opacity .6s ease .7s;opacity:1;}
}
@media(prefers-reduced-motion:reduce){
  /* everything at rest state immediately */
  .fbm-beam-bar,.fbm-beam-pans{transform:rotate(var(--tilt,0deg));}
  .fbm-leg{opacity:1;}
  .fbm-chart-line{stroke-dashoffset:0;}
  .fbm-chart-area,.fbm-chart-node,.fbm-chart-diamond{opacity:1;}
}

/* — 390px bottom-sheet: keep the beam legible, stack benchmark odds tighter — */
@media(max-width:430px){
  .fbm-beam-stage{height:156px;}
  .fbm-beam-pan{top:48px;width:44%;}
  .fbm-leg{font-size:10px;padding:3px 7px;}
  .fbm-bench-odds{font-size:22px;min-width:44px;}
  .fbm-row-state{min-width:82px;font-size:11.5px;}
}

/* ══ RISK RADAR MODAL — Sol freeze (verdict → why → watch → context) ════════
   Scoped to #dlg-risk. Shared _risk_radar_card / country clones are untouched.
   rlx-* stay global because LENS clones live on body. No parallel :root tokens. */

#dlg-risk .mx5-dlg-panel{
  container: risk-dialog / inline-size;
  font-family:var(--font-ui);
  max-width:min(900px, calc(100vw - 48px));
  width:calc(100% - 48px);
  max-height:min(88vh, 900px);
  overflow-x:hidden;
}
#dlg-risk .mx5-dlg-body,#dlg-risk .mx5-dlg-body *{min-width:0;}
#dlg-risk .mx5-dlg-title{
  font-family:var(--font-ui);
  font-size:var(--fs-md);font-weight:650;letter-spacing:0;text-transform:none;
  color:var(--ink-2);
  display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;
}
#dlg-risk .riskdlg-asof{
  font:500 var(--fs-label)/1 var(--font-ui);letter-spacing:0;text-transform:none;
  color:var(--ink-3);font-variant-numeric:tabular-nums;
}
#dlg-risk .mx5-dlg-close{width:44px;height:44px;font-size:22px;}
#dlg-risk .mx5-dlg-header{padding:14px 22px 12px;}
#dlg-risk .mx5-dlg-body{padding:6px 22px 22px;}
@media(max-width:899px){
  #dlg-risk .mx5-dlg-panel{max-width:calc(100vw - 32px);width:calc(100vw - 32px);}
}
@media(max-width:700px){
  #dlg-risk .mx5-dlg-header{padding:14px 16px 10px;}
  #dlg-risk .mx5-dlg-body{padding:4px 16px 20px;}
}
@media(prefers-reduced-motion:no-preference){
  #dlg-risk .mx5-dlg-body > *{opacity:1;transform:none;transition:none;}
}
[data-theme="light"] #dlg-risk .mx5-dlg-title{color:var(--ink-2);}
[data-theme="light"] #dlg-risk .riskdlg-asof{color:var(--ink-3);}

/* — Risk Brief (one hero) — */
#dlg-risk .riskdlg-brief{
  padding:14px 16px 12px;border-radius:var(--r-card);
  background:color-mix(in srgb, var(--text) 4%, transparent);
  border:1px solid var(--line);
  border-left:2px solid var(--rkc-c,var(--ok));
}
#dlg-risk .riskdlg-brief[data-rk-state="calm"],
#dlg-risk .riskdlg-brief[data-rk-state="unknown"]{--rkc-c:var(--ok);}
#dlg-risk .riskdlg-brief[data-rk-state="watch"]{--rkc-c:var(--info);}
#dlg-risk .riskdlg-brief[data-rk-state="elevated"],
#dlg-risk .riskdlg-brief[data-rk-state="caution"]{--rkc-c:var(--warn);}
#dlg-risk .riskdlg-brief[data-rk-state="risk-off"],
#dlg-risk .riskdlg-brief[data-rk-state="high"]{--rkc-c:var(--down);}
[data-theme="light"] #dlg-risk .riskdlg-brief{background:var(--panel);}
#dlg-risk .riskdlg-brief-top{display:flex;align-items:baseline;justify-content:space-between;gap:12px;}
#dlg-risk .riskdlg-state{
  font:700 var(--fs-sm)/1 var(--font-ui);letter-spacing:.02em;text-transform:none;
  color:var(--rkc-c,var(--ok));
}
#dlg-risk .riskdlg-score{
  font:800 var(--fs-h1)/.9 var(--font-ui);font-variant-numeric:tabular-nums;
  color:var(--ink-1);letter-spacing:-.02em;
}
#dlg-risk .riskdlg-score small{font-size:var(--fs-sm);font-weight:600;color:var(--ink-3);margin-left:2px;}
#dlg-risk .riskdlg-domain{font:650 var(--fs-md)/1.35 var(--font-ui);color:var(--ink-1);margin-top:6px;}
#dlg-risk .riskdlg-stance{font:500 var(--fs-body)/1.45 var(--font-ui);color:var(--ink-2);margin-top:4px;}
#dlg-risk .riskdlg-authority{font:500 var(--fs-label)/1.4 var(--font-ui);color:var(--ink-3);margin-top:6px;}
#dlg-risk .riskdlg-odds{margin-top:12px;padding-top:10px;border-top:1px solid var(--line);}
#dlg-risk .riskdlg-odds-k{font:600 var(--fs-label)/1.2 var(--font-ui);color:var(--ink-3);margin-bottom:6px;}
#dlg-risk .riskdlg-odds-h{display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;}
#dlg-risk .riskdlg-odds-h span{font:500 var(--fs-sm)/1 var(--font-ui);color:var(--ink-2);}
#dlg-risk .riskdlg-odds-h b{font-weight:750;font-variant-numeric:tabular-nums;margin-left:4px;color:var(--ink-1);}
#dlg-risk .riskdlg-odds-h .is-lead{font-size:var(--fs-body);color:var(--ink-1);}
#dlg-risk .riskdlg-odds-h .is-lead b{font-size:var(--fs-num-lg);font-weight:800;}
#dlg-risk .riskdlg-odds-rail{position:relative;height:10px;margin-top:8px;}
#dlg-risk .riskdlg-odds-track{display:block;height:2px;border-radius:0;position:absolute;left:0;right:0;top:4px;
  background:var(--line);}
#dlg-risk .riskdlg-odds-dot{position:absolute;top:1px;width:8px;height:8px;border-radius:var(--r-pill);
  background:var(--ink-3);transform:translateX(-50%);}
#dlg-risk .riskdlg-odds-dot.is-lead{width:10px;height:10px;top:0;background:var(--rkc-c,var(--ok));}
#dlg-risk .riskdlg-odds-norm{position:absolute;top:-1px;width:1px;height:12px;opacity:.55;
  background:var(--ink-3);transform:translateX(-50%);}
#dlg-risk .riskdlg-odds-note{font:500 var(--fs-label)/1.3 var(--font-ui);color:var(--ink-3);margin-top:6px;font-variant-numeric:tabular-nums;}
#dlg-risk .riskdlg-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px;}
#dlg-risk .riskdlg-chip{
  font:600 var(--fs-label)/1 var(--font-ui);padding:5px 8px;border-radius:var(--r-btn);
  border:1px solid var(--line);color:var(--ink-2);
  background:transparent;
}
#dlg-risk .riskdlg-chip.is-accent{color:var(--rkc-c);border-color:color-mix(in srgb,var(--rkc-c) 32%,transparent);}
#dlg-risk .riskdlg-chip[data-fed="hawkish"],
#dlg-risk .riskdlg-chip[data-fed="very-hawkish"]{--rkc-c:var(--down);}
#dlg-risk .riskdlg-chip[data-fed="dovish"],
#dlg-risk .riskdlg-chip[data-fed="very-dovish"]{--rkc-c:var(--up);}
#dlg-risk .riskdlg-chip[data-fed="neutral"]{--rkc-c:var(--warn);}

#dlg-risk .riskdlg-sec-h{
  font:650 var(--fs-body)/1.3 var(--font-ui);color:var(--ink-1);
  margin:16px 0 8px;letter-spacing:0;text-transform:none;
  display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;
}
#dlg-risk .riskdlg-sec-h small{font:500 var(--fs-label)/1 var(--font-ui);color:var(--ink-3);text-transform:none;letter-spacing:0;}

#dlg-risk .riskdlg-drv-list{
  border:1px solid var(--line);border-radius:var(--r-card);
  background:color-mix(in srgb, var(--text) 3%, transparent);overflow:hidden;
}
[data-theme="light"] #dlg-risk .riskdlg-drv-list{background:var(--panel);}
#dlg-risk .riskdlg-drv{
  display:flex;align-items:center;gap:10px;padding:8px 12px;min-height:40px;
  border-bottom:1px solid var(--line);min-width:0;
}
#dlg-risk .riskdlg-drv:last-child{border-bottom:none;}
#dlg-risk .riskdlg-drv[data-tip-en]{cursor:help;}
#dlg-risk .riskdlg-drv[data-isle="risk"]{--rkc-c:var(--isle-risk);}
#dlg-risk .riskdlg-drv[data-isle="events"]{--rkc-c:var(--isle-events);}
#dlg-risk .riskdlg-drv[data-isle="markets"]{--rkc-c:var(--isle-markets);}
#dlg-risk .riskdlg-drv[data-isle="news"]{--rkc-c:var(--isle-news);}
#dlg-risk .riskdlg-drv[data-pressure="high"]{--rkc-c:var(--down);}
#dlg-risk .riskdlg-drv[data-pressure="moderate"]{--rkc-c:var(--warn);}
#dlg-risk .riskdlg-drv[data-pressure="low"]{--rkc-c:var(--up);}
#dlg-risk .riskdlg-drv .rlx-viz{--rlx-c:var(--rkc-c);}
#dlg-risk .riskdlg-drv .lens-ill{color:var(--rkc-c);}
#dlg-risk .riskdlg-drv .rkc-sig-ico{
  width:20px;height:20px;border-radius:0;background:transparent;
}
#dlg-risk .riskdlg-drv .rkc-sig-ico svg{width:16px;height:16px;}
#dlg-risk .riskdlg-drv .rkc-sig-body{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;}
#dlg-risk .riskdlg-drv .rkc-sig-lbl{font:650 var(--fs-label)/1.25 var(--font-ui);color:var(--ink-3);flex:0 0 auto;min-width:4.6em;}
#dlg-risk .riskdlg-drv .rkc-sig-state{margin:0;font-size:var(--fs-sm);flex:1;min-width:0;}
#dlg-risk .riskdlg-drv .rkc-sig-tip{width:44px;height:44px;border-radius:var(--r-pill);}
.rkc-sig-ico{flex:0 0 auto;width:26px;height:26px;border-radius:var(--r-btn);display:flex;align-items:center;justify-content:center;
  color:var(--rkc-c,var(--isle-risk));background:color-mix(in srgb,var(--rkc-c,var(--isle-risk)) 12%,transparent);}
.rkc-sig-ico svg{width:15px;height:15px;display:block;}
.rkc-sig-body{min-width:0;flex:1;}
.rkc-sig-lbl{font:700 12px/1.25 var(--font-ui);color:var(--ink-1);}
.rkc-sig-state{font-size:11px;line-height:1.45;color:var(--ink-2);margin-top:2px;
  display:flex;align-items:baseline;flex-wrap:wrap;gap:5px;}
.rkc-sig-chip{display:inline-flex;align-items:center;font:700 10px/1 var(--font-ui);
  letter-spacing:.03em;padding:2px 6px;border-radius:var(--r-ctl);white-space:nowrap;
  color:var(--rkc-c,var(--isle-risk));
  background:color-mix(in srgb,var(--rkc-c,var(--isle-risk)) 13%,transparent);
  border:1px solid color-mix(in srgb,var(--rkc-c,var(--isle-risk)) 32%,transparent);}
.rkc-sig-tip{display:inline-flex;align-items:center;justify-content:center;width:14px;height:14px;flex:0 0 auto;
  border-radius:var(--r-pill);border:1px solid var(--line);color:var(--ink-3);
  font:700 10px/1 var(--font-ui);cursor:help;user-select:none;margin-left:auto;transition:border-color .2s,color .2s;}
.rkc-sig-tip:hover{border-color:var(--isle-risk);color:var(--isle-risk);}
[data-theme="light"] .rkc-sig-tip{border-color:var(--line);color:var(--ink-2);}

/* ── rlx-* : rich-lens popover anatomy (Tier-2 rework 2026-07-20) ────────────
   Illustrated hover cards for the six dlg-risk signal tiles (+ any heavy tip).
   Content lives in a hidden .lens-src child of the tile; the site LENS engine
   (theme.js #3102) clones it into a body-appended glass .lens-pop and manages
   chrome / clamping / bottom-sheet at ≤640px / reduced-motion. These classes
   style the CLONE, so they are global (not #dlg-risk-scoped) and lean on the
   --lens-* token chain the engine sets, so light mode + vector pages inherit.
   Anatomy (Fable direction): .lens-hd (engine) → optional rlx-viz mini-illustration
   → rlx-rows label:value glance rows → optional rlx-chips ticker row → .lens-receipt
   (engine) honest compressed receipt. Budget ≤ ~45 visible words + receipt. */
.rlx-viz{margin:2px 16px 4px;padding:10px 12px;border-radius:11px;
  background:color-mix(in srgb,var(--lens-text,#d7dce3) 4%,transparent);
  border:1px solid color-mix(in srgb,var(--lens-text,#d7dce3) 9%,transparent);}
.rlx-viz-cap{font:600 10px/1.4 var(--font-ui,Inter,sans-serif);color:var(--lens-mut,#8b93a1);margin-top:8px;}
.rlx-viz.is-news{--rlx-c:var(--isle-news);}
/* comparison bars — a label ABOVE each full-width bar. (Was a 64px label column, which
   crushed descriptive leg names like "Cyclicals fading vs defensives" into 4-line,
   mid-word-broken wraps — the "bad layout". Stacking gives the name full width and the
   bars share one left edge so length still compares cleanly.) */
.rlx-bars{display:flex;flex-direction:column;gap:12px;}
.rlx-bar-row{display:flex;flex-direction:column;gap:6px;min-width:0;}
.rlx-bar-lbl{font:600 11px/1.3 var(--font-ui,Inter,sans-serif);
  color:color-mix(in srgb,var(--lens-text,#d7dce3) 84%,var(--lens-mut,#8b93a1));overflow-wrap:break-word;}
.rlx-bar-track{position:relative;height:9px;border-radius:5px;
  background:color-mix(in srgb,var(--lens-mut,#8b93a1) 20%,transparent);overflow:hidden;}
.rlx-bar-fill{position:absolute;inset:0 auto 0 0;border-radius:5px;
  width:var(--rlx-w,50%);
  background:linear-gradient(90deg,color-mix(in srgb,var(--rlx-c,var(--lens-accent,#5b9bf0)) 55%,transparent),var(--rlx-c,var(--lens-accent,#5b9bf0)));}
.rlx-bar-fill.muted{background:color-mix(in srgb,var(--lens-mut,#8b93a1) 45%,transparent);}
/* progress-to-maturity bar (single track + marker) */
.rlx-prog{position:relative;height:10px;border-radius:6px;
  background:color-mix(in srgb,var(--lens-mut,#8b93a1) 20%,transparent);overflow:hidden;}
.rlx-prog-fill{position:absolute;inset:0 auto 0 0;width:var(--rlx-w,50%);border-radius:6px;
  background:linear-gradient(90deg,color-mix(in srgb,var(--rlx-c,var(--lens-accent,#5b9bf0)) 50%,transparent),var(--rlx-c,var(--lens-accent,#5b9bf0)));}
/* label:value glance rows */
.rlx-rows{margin:6px 16px 10px;display:flex;flex-direction:column;gap:8px;}
.rlx-row{display:flex;flex-direction:column;gap:2px;min-width:0;}
.rlx-k{font:700 8.5px/1 var(--font-ui,Inter,sans-serif);letter-spacing:.11em;text-transform:uppercase;
  color:color-mix(in srgb,var(--lens-mut,#8b93a1) 82%,transparent);}
.rlx-v{font:450 12px/1.5 var(--font-ui,Inter,sans-serif);color:color-mix(in srgb,var(--lens-text,#d7dce3) 90%,var(--lens-mut,#8b93a1));}
.rlx-v b{font-weight:650;color:var(--lens-text,#d7dce3);}
/* ticker chip row — Favor (green-tint) · Trim (red-tint) */
.rlx-chips{margin:0 16px 12px;display:flex;flex-wrap:wrap;gap:5px 6px;align-items:center;}
.rlx-chips-lbl{font:700 8.5px/1 var(--font-ui,Inter,sans-serif);letter-spacing:.1em;text-transform:uppercase;
  color:color-mix(in srgb,var(--lens-mut,#8b93a1) 80%,transparent);margin-right:1px;}
.rlx-chip{display:inline-flex;align-items:center;font:700 10.5px/1 var(--font-ui,Inter,sans-serif);
  letter-spacing:.02em;padding:3px 8px;border-radius:6px;white-space:nowrap;}
.rlx-chip.up{color:var(--ink-ok, var(--ok,var(--up,#3da564)));background:color-mix(in srgb,var(--ok,var(--up,#3da564)) 14%,transparent);
  border:1px solid color-mix(in srgb,var(--ok,var(--up,#3da564)) 30%,transparent);}
.rlx-chip.dn{color:var(--ink-down, var(--down,#ef4444));background:color-mix(in srgb,var(--down,#ef4444) 13%,transparent);
  border:1px solid color-mix(in srgb,var(--down,#ef4444) 30%,transparent);}
@media(prefers-reduced-motion:no-preference){
  .lens-pop.open .rlx-bar-fill,.lens-pop.open .rlx-prog-fill{transform:scaleX(0);transform-origin:0 50%;
    animation:rlxGrow .6s cubic-bezier(.22,.9,.26,1.02) .1s both;}
}
@keyframes rlxGrow{to{transform:scaleX(1);}}

/* — 3. Leadership rotation + tracked-cohort damage block — */
.rkc-rot-head,.rkc-cohort-kicker{display:flex;align-items:baseline;justify-content:space-between;gap:8px;
  font:750 10px/1.3 var(--font-ui,inherit);letter-spacing:.08em;text-transform:uppercase;
  color:var(--ink-2,rgba(255,255,255,.68));margin:2px 0 8px;}
.rkc-rot-head small,.rkc-cohort-kicker small{font-size:9px;font-weight:500;letter-spacing:.02em;text-transform:none;color:var(--ink-3,rgba(255,255,255,.4));}
.rkc-rot-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:6px;margin-bottom:4px;}
.rkc-rot-chip{display:flex;align-items:center;justify-content:space-between;gap:7px;min-width:0;padding:7px 9px;
  border-radius:8px;text-decoration:none;color:var(--ink-2,rgba(255,255,255,.72));
  background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.07);}
[data-theme="light"] .rkc-rot-chip{background:rgba(0,0,0,.02);border-color:rgba(0,0,0,.07);}
.rkc-rot-chip.up{border-color:color-mix(in srgb,var(--up,#22c55e) 34%,transparent);background:color-mix(in srgb,var(--up,#22c55e) 7%,transparent);}
.rkc-rot-chip.down{border-color:color-mix(in srgb,var(--down,#ef4444) 28%,transparent);background:color-mix(in srgb,var(--down,#ef4444) 5%,transparent);}
.rkc-rot-name{font:650 10.5px/1.25 var(--font-ui,inherit);min-width:0;}
.rkc-rot-meta{flex:0 0 auto;font:700 9.5px/1 var(--font-mono,ui-monospace,monospace);color:var(--ink-3,rgba(255,255,255,.46));}
.rkc-rot-chip.up .rkc-rot-meta{color:var(--ink-up, var(--up,#22c55e));}.rkc-rot-chip.down .rkc-rot-meta{color:var(--ink-down, var(--down,#ef4444));}
.rkc-cohort-kicker{margin-top:14px;padding-top:11px;border-top:1px solid var(--line,rgba(255,255,255,.08));}
.rkc-ldr-head{display:flex;align-items:center;gap:9px;margin:2px 0 10px;}
.rkc-ldr-state{flex:1;min-width:0;font:600 13px/1.4 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.9));}
.rkc-ldr-count{flex:0 0 auto;display:inline-flex;align-items:baseline;gap:6px;font:800 14px/1 var(--font-ui,inherit);
  font-variant-numeric:tabular-nums;padding:5px 10px;border-radius:999px;color:var(--ink-down, var(--down,#ef4444));
  background:color-mix(in srgb,var(--down,#ef4444) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--down,#ef4444) 30%,transparent);}
.rkc-ldr-count small{font-size:10px;font-weight:600;color:color-mix(in srgb,var(--down,#ef4444) 78%,var(--ink-2));letter-spacing:.02em;}
/* padding-top reserves a lane for the "index" tick label, which is absolutely
   positioned at top:-15px off the FIRST row's track. Without it the label escapes
   the bars block and collides with the state line above (operator, 2026-07-26). */
.rkc-ldr-bars{display:flex;flex-direction:column;gap:6px;position:relative;padding-top:16px;}
.rkc-ldr-row{display:grid;grid-template-columns:52px 1fr 46px;align-items:center;gap:9px;}
.rkc-ldr-tkr{font:700 11px/1 var(--font-mono,ui-monospace,'SF Mono',monospace);
  color:var(--ink-2,rgba(255,255,255,.72));letter-spacing:.02em;}
[data-theme="light"] .rkc-ldr-tkr{color:rgba(0,0,0,.72);}
.rkc-ldr-track{position:relative;height:9px;border-radius:5px;background:rgba(255,255,255,.06);overflow:visible;}
[data-theme="light"] .rkc-ldr-track{background:rgba(0,0,0,.06);}
.rkc-ldr-fill{height:100%;border-radius:5px;transform-origin:0 50%;
  background:linear-gradient(90deg,color-mix(in srgb,var(--down,#ef4444) 55%,transparent),var(--down,#ef4444));}
.rkc-ldr-idx{position:absolute;top:-3px;bottom:-3px;width:2px;border-radius:1px;
  background:var(--ink-2,rgba(255,255,255,.55));}
.rkc-ldr-idx-lbl{position:absolute;top:-15px;left:50%;transform:translateX(-50%);
  font:600 10px/1 var(--font-ui,inherit);letter-spacing:.04em;
  color:var(--ink-3,rgba(255,255,255,.52));white-space:nowrap;}
/* When the tick sits hard against the left edge of the track a centred label hangs
   over the ticker gutter — anchor it to the tick instead. */
.rkc-ldr-idx.at-start .rkc-ldr-idx-lbl{left:0;transform:none;}
.rkc-ldr-pct{font:800 11px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;text-align:right;color:var(--ink-down, var(--down,#ef4444));}
.rkc-ldr-sub{font-size:11px;color:var(--ink-3,rgba(255,255,255,.42));margin-top:9px;line-height:1.5;}
.rkc-ldr-sub b{color:var(--ink-2,rgba(255,255,255,.62));font-weight:700;font-variant-numeric:tabular-nums;}
@media(prefers-reduced-motion:no-preference){
  #dlg-risk .rkc-ldr-fill{transform:scaleX(0);transition:transform 620ms cubic-bezier(.22,.9,.26,1.02);}
  #dlg-risk.mx5-dlg-in .rkc-ldr-fill{transform:scaleX(1);}
  #dlg-risk.mx5-dlg-in .rkc-ldr-row:nth-child(2) .rkc-ldr-fill{transition-delay:.06s;}
  #dlg-risk.mx5-dlg-in .rkc-ldr-row:nth-child(3) .rkc-ldr-fill{transition-delay:.12s;}
  #dlg-risk.mx5-dlg-in .rkc-ldr-row:nth-child(4) .rkc-ldr-fill{transition-delay:.18s;}
  #dlg-risk.mx5-dlg-in .rkc-ldr-row:nth-child(5) .rkc-ldr-fill{transition-delay:.24s;}
  #dlg-risk.mx5-dlg-in .rkc-ldr-row:nth-child(n+6) .rkc-ldr-fill{transition-delay:.30s;}
}

/* — 4. Overseas severity-ring tiles (SIGNATURE) — */
.rkc-ov-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px;margin:2px 0 12px;}
.rkc-ov{display:flex;flex-direction:column;align-items:center;gap:7px;padding:11px 8px 10px;border-radius:12px;
  text-decoration:none;color:inherit;
  background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.06);
  transition:border-color .2s ease,transform .16s ease,background .2s ease;}
[data-theme="light"] .rkc-ov{background:rgba(0,0,0,.02);border-color:rgba(0,0,0,.06);}
.rkc-ov:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--rkc-c,var(--isle-risk,#e05c5c)) 40%,var(--line,rgba(255,255,255,.1)));
  background:rgba(255,255,255,.04);}
[data-theme="light"] .rkc-ov:hover{background:rgba(0,0,0,.035);}
.rkc-ov.is-alert{border-color:color-mix(in srgb,var(--rkc-c,var(--down,#ef4444)) 30%,transparent);
  background:color-mix(in srgb,var(--rkc-c,var(--down,#ef4444)) 6%,transparent);}
.rkc-ov-ring{position:relative;width:52px;height:52px;border-radius:50%;flex:0 0 auto;
  /* conic arc 0..(val/100) in state colour, remainder a faint track */
  background:conic-gradient(var(--rkc-c,var(--isle-risk,#e05c5c)) calc(var(--rkc-v,0) * 1%),
    color-mix(in srgb,var(--muted,#8a93a3) 20%,transparent) 0);
  display:flex;align-items:center;justify-content:center;
  transition:filter .2s ease;}
.rkc-ov:hover .rkc-ov-ring{filter:drop-shadow(0 0 6px color-mix(in srgb,var(--rkc-c,var(--isle-risk,#e05c5c)) 55%,transparent));}
.rkc-ov-ring::before{content:"";position:absolute;inset:4px;border-radius:50%;
  background:var(--panel,#0f1420);}
[data-theme="light"] .rkc-ov-ring::before{background:#fff;}
.rkc-ov-val{position:relative;z-index:1;font:800 15px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;
  color:var(--rkc-c,var(--isle-risk,#e05c5c));}
.rkc-ov-name{font:600 11px/1.25 var(--font-ui,inherit);color:var(--ink-2,rgba(255,255,255,.66));text-align:center;
  max-width:100%;overflow-wrap:anywhere;}
[data-theme="light"] .rkc-ov-name{color:rgba(0,0,0,.62);}
/* state word — in the ring's own band colour, so the tile says what its colour means
   (the three markets with no hover profile had a coloured ring and no word at all) */
.rkc-ov-state{margin-top:-3px;font:700 9px/1.2 var(--font-ui,inherit);letter-spacing:.08em;
  text-transform:uppercase;text-align:center;color:var(--rkc-c,var(--muted,#8a93a3));}
/* this ring's own grading date, shown ONLY when it predates the board — the dialog's
   single footer stamp is the board's date, and a ring can be days behind it */
.rkc-ov-age{margin-top:-4px;font:600 9px/1.2 var(--font-ui,inherit);text-align:center;
  color:var(--ink-3,rgba(255,255,255,.34));}
[data-theme="light"] .rkc-ov-age{color:rgba(0,0,0,.58);}
.row-pop-why li.row-pop-stale{color:var(--ink-warn, var(--warn,#f59e0b));}
@media(prefers-reduced-motion:no-preference){
  #dlg-risk .rkc-ov-ring{--rkc-anim:0;
    background:conic-gradient(var(--rkc-c,var(--isle-risk,#e05c5c)) calc(var(--rkc-anim,0) * 1%),
      color-mix(in srgb,var(--muted,#8a93a3) 20%,transparent) 0);
    transition:filter .2s ease,--rkc-anim 700ms cubic-bezier(.22,.9,.26,1.02);}
  #dlg-risk.mx5-dlg-in .rkc-ov-ring{--rkc-anim:var(--rkc-v,0);}
}
@property --rkc-anim{syntax:'<number>';inherits:false;initial-value:0;}

/* — Transmission verdict as a state chip — */
.rkc-tx-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;}
.rkc-tx-ttl{font:700 12px/1 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.86));}
.rkc-tx-verdict{display:inline-flex;align-items:center;gap:5px;font:700 11px/1 var(--font-ui,inherit);
  letter-spacing:.03em;padding:3px 9px;border-radius:999px;}
.rkc-tx-verdict::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;}
.rkc-tx-verdict.v-alert{color:var(--ink-down, var(--down,#ef4444));background:color-mix(in srgb,var(--down,#ef4444) 12%,transparent);border:1px solid color-mix(in srgb,var(--down,#ef4444) 30%,transparent);}
.rkc-tx-verdict.v-warn{color:var(--ink-warn, var(--warn,#f59e0b));background:color-mix(in srgb,var(--warn,#f59e0b) 12%,transparent);border:1px solid color-mix(in srgb,var(--warn,#f59e0b) 30%,transparent);}
.rkc-tx-verdict.v-ok{color:var(--ink-up, var(--up,#22c55e));background:color-mix(in srgb,var(--up,#22c55e) 12%,transparent);border:1px solid color-mix(in srgb,var(--up,#22c55e) 30%,transparent);}

/* — 5. Scare ladder: one flat instrument, not seven cards — */
#dlg-risk .riskdlg-scare-list.scare-ladder{
  gap:0;margin:0;border:1px solid var(--line);border-radius:var(--r-card);overflow:hidden;
}
#dlg-risk .riskdlg-scare{
  display:grid;grid-template-columns:minmax(0,1.5fr) minmax(72px,1fr) 40px 58px;
  align-items:center;gap:10px;min-height:34px;padding:4px 12px;
  background:transparent;border:0;border-bottom:1px solid var(--line);border-radius:0;
}
#dlg-risk .riskdlg-scare:last-child{border-bottom:0;}
#dlg-risk .riskdlg-scare[data-band="sc-band-high"]{--rkc-c:var(--down);}
#dlg-risk .riskdlg-scare[data-band="sc-band-watch"]{--rkc-c:var(--warn);}
#dlg-risk .riskdlg-scare[data-band="sc-band-elev"]{--rkc-c:var(--info);}
#dlg-risk .riskdlg-scare[data-band="sc-band-calm"]{--rkc-c:var(--muted);}
#dlg-risk .riskdlg-scare[data-band="sc-band-unavailable"]{--rkc-c:var(--muted);}
#dlg-risk .rkc-sc-ico{display:none;}
#dlg-risk .sc-name{font-size:var(--fs-sm);font-weight:650;}
#dlg-risk .sc-score{font-size:var(--fs-body);font-weight:750;}
#dlg-risk .sc-bar-track{height:5px;background:color-mix(in srgb, var(--text) 8%, transparent);}
#dlg-risk .sc-bar-fill{height:5px;transform-origin:0 50%;
  background:linear-gradient(90deg,color-mix(in srgb,var(--rkc-c,var(--muted)) 45%,transparent),var(--rkc-c,var(--muted)))!important;}
@media(prefers-reduced-motion:no-preference){
  #dlg-risk .sc-bar-fill{transform:scaleX(0);transition:transform 420ms cubic-bezier(.22,.9,.26,1.02);}
  #dlg-risk.mx5-dlg-in .sc-bar-fill{transform:scaleX(1);}
}
@media(prefers-reduced-motion:reduce){
  #dlg-risk .sc-bar-fill{transform:none;}
}
@container risk-dialog (max-width:700px){
  #dlg-risk .riskdlg-scare{grid-template-columns:minmax(0,1fr) 40px 58px;}
  #dlg-risk .riskdlg-scare .sc-bar-track{display:none;}
}
@container risk-dialog (max-width:390px){
  #dlg-risk .riskdlg-scare{
    grid-template-columns:minmax(0,1fr) auto;
    grid-template-areas:"copy score" "copy band";
    align-items:start;gap:2px 8px;padding:8px 12px;min-height:44px;
  }
  #dlg-risk .sc-name{grid-area:copy;}
  #dlg-risk .sc-score{grid-area:score;text-align:right;}
  #dlg-risk .sc-band{grid-area:band;justify-self:end;}
}

/* — 6. Mood check: two independent instruments.
   Labels, values and status chips live outside the rails, so a score near 50 can
   never collide with the Neutral axis label (the original 48/Neutral bug). — */
.rkc-mood-board{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:10px;}
.rkc-mood-lens{padding:11px 12px 12px;border-radius:12px;
  background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.075);}
[data-theme="light"] .rkc-mood-lens{background:rgba(0,0,0,.022);border-color:rgba(0,0,0,.07);}
.rkc-mood-lens-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:12px;}
.rkc-mood-lens-name{font:700 10px/1.25 var(--font-ui,inherit);letter-spacing:.055em;text-transform:uppercase;
  color:var(--ink-2,rgba(255,255,255,.68));padding-top:3px;}
.rkc-mood-scoreline{display:flex;align-items:center;justify-content:flex-end;gap:5px;flex-wrap:wrap;text-align:right;}
.rkc-mood-score{font:800 20px/.9 var(--font-ui,inherit);font-variant-numeric:tabular-nums;
  color:var(--ink-1,rgba(255,255,255,.94));letter-spacing:-.02em;}
.rkc-mood-unit{font:600 10px/1 var(--font-ui,inherit);color:var(--ink-3,rgba(255,255,255,.44));}
.rkc-mood-scoreline .chip{font-size:10px;line-height:1;padding:3px 7px;}
.rkc-mood-mini-track{position:relative;height:9px;border-radius:999px;
  background:linear-gradient(90deg,var(--down,#ef4444) 0%,var(--warn,#f59e0b) 50%,var(--up,#22c55e) 100%);
  box-shadow:inset 0 1px 3px rgba(0,0,0,.24);}
.rkc-mood-mini-track::after{content:"";position:absolute;left:50%;top:-2px;width:1px;height:13px;
  background:color-mix(in srgb,var(--ink-1,#fff) 40%,transparent);}
.rkc-mood-pin{position:absolute;left:var(--rkc-pos,50%);top:50%;width:13px;height:13px;border-radius:50%;
  transform:translate(-50%,-50%);background:var(--text,#fff);border:3px solid var(--panel,#0f1420);
  box-shadow:0 1px 5px rgba(0,0,0,.45);z-index:2;}
[data-theme="light"] .rkc-mood-pin{border-color:#fff;box-shadow:0 1px 4px rgba(0,0,0,.23);}
.rkc-mood-axis{display:grid;grid-template-columns:repeat(5,1fr);align-items:start;
  font:600 10px/1.25 var(--font-ui,inherit);color:var(--muted);margin-top:7px;letter-spacing:.01em;}
.rkc-mood-axis span{text-align:center;}
.rkc-mood-axis span:first-child{text-align:left;}
.rkc-mood-axis span:last-child{text-align:right;}
.rkc-mood-note{font:600 11px/1.45 var(--font-ui,inherit);color:var(--ink-3,rgba(255,255,255,.44));margin-top:9px;}
@media(prefers-reduced-motion:no-preference){
  #dlg-risk .rkc-mood-pin{left:50%;transition:left 760ms cubic-bezier(.34,1.28,.5,1) .2s;}
  #dlg-risk.mx5-dlg-in .rkc-mood-pin{left:var(--rkc-pos,50%);}
}
@media(prefers-reduced-motion:reduce){
  #dlg-risk .rkc-mood-pin{left:var(--rkc-pos,50%);}
  #dlg-risk .rkc-ldr-fill,#dlg-risk .sc-bar-fill{transform:none;}
  #dlg-risk .rkc-ov-ring{--rkc-anim:var(--rkc-v,0);}
}

/* Froth header: a title cluster and a score cluster, never four loose flex items. */
#dlg-risk .rsx-froth-hd{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:10px;margin-bottom:8px;}
.rsx-froth-title{display:flex;align-items:center;gap:7px;min-width:0;font:700 13px/1.3 var(--font-ui,inherit);}
.rsx-froth-scoreline{display:flex;align-items:center;justify-content:flex-end;gap:6px;flex-wrap:wrap;}
.rsx-froth-score{font:850 20px/.9 var(--font-ui,inherit);font-variant-numeric:tabular-nums;letter-spacing:-.02em;}
.rsx-froth-provisional{font:600 9px/1 var(--font-ui,inherit);color:var(--ink-3,rgba(255,255,255,.4));}

/* — Leadership rows + method disclosure — */
#dlg-risk .rkc-rot-head{
  font:650 var(--fs-sm)/1.3 var(--font-ui);letter-spacing:0;text-transform:none;
  color:var(--ink-2);
}
#dlg-risk .rkc-mood-lens-name{letter-spacing:0;text-transform:none;font:650 var(--fs-label)/1.25 var(--font-ui);}
#dlg-risk .riskdlg-rot{
  display:flex;flex-direction:column;
  border:1px solid var(--line);border-radius:var(--r-card);overflow:hidden;
}
#dlg-risk .riskdlg-theme{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:7px 12px;min-height:34px;text-decoration:none;
  color:var(--ink-2);background:transparent;
  border-bottom:1px solid var(--line);
}
#dlg-risk .riskdlg-theme:last-child,#dlg-risk .riskdlg-rot > .riskdlg-fold{border-bottom:0;}
#dlg-risk .riskdlg-tn{font:650 var(--fs-sm)/1.3 var(--font-ui);min-width:0;}
#dlg-risk .riskdlg-tm{font:700 var(--fs-label)/1 var(--font-mono);font-variant-numeric:tabular-nums;color:var(--ink-3);flex:0 0 auto;}
/* Rank is neutral; only the observed 5-session move carries direction colour.
   --ink-up/--ink-down intentionally follow the site's locale convention:
   EN = green up / red down; ZH = red up / green down. */
#dlg-risk .riskdlg-rank-delta.up{color:var(--ink-up,var(--up));}
#dlg-risk .riskdlg-rank-delta.down{color:var(--ink-down,var(--down));}
#dlg-risk .riskdlg-ldr-caveat{font:500 var(--fs-sm)/1.45 var(--font-ui);color:var(--ink-3);margin:8px 0 4px;}
#dlg-risk .riskdlg-fold > summary,
#dlg-risk .riskdlg-method > summary{
  cursor:pointer;list-style:none;font:600 var(--fs-sm)/1.3 var(--font-ui);
  color:var(--ink-2);padding:8px 12px;min-height:44px;
  display:flex;align-items:center;gap:6px;
}
#dlg-risk .riskdlg-fold > summary::-webkit-details-marker,
#dlg-risk .riskdlg-method > summary::-webkit-details-marker{display:none;}
#dlg-risk .riskdlg-fold > summary::before,
#dlg-risk .riskdlg-method > summary::before{content:"+";font-weight:700;color:var(--ink-3);width:1em;}
#dlg-risk .riskdlg-fold[open] > summary::before,
#dlg-risk .riskdlg-method[open] > summary::before{content:"–";}
#dlg-risk .riskdlg-method{
  margin-top:14px;border:1px solid var(--line);border-radius:var(--r-card);
}
#dlg-risk .riskdlg-method-note{font:500 var(--fs-sm)/1.45 var(--font-ui);color:var(--ink-3);padding:0 12px 12px;margin:0;}
#dlg-risk .rsx-dlg-footer{font:500 var(--fs-label)/1.5 var(--font-ui);color:var(--ink-3);margin-top:10px;}
#dlg-risk .riskdlg-rot > .riskdlg-fold{padding:0;}
#dlg-risk .riskdlg-rot > .riskdlg-fold > summary{border-top:1px solid var(--line);}

/* — narrow embedded-panel bleed checks — */
@container risk-dialog (max-width:520px){
  .rkc-mood-board{grid-template-columns:1fr;}
  .rkc-ov-grid{grid-template-columns:repeat(auto-fill,minmax(80px,1fr));gap:6px;}
  .rkc-ov-ring{width:46px;height:46px;}
  .rkc-ov-val{font-size:14px;}
  .rkc-ldr-row{grid-template-columns:46px 1fr 42px;gap:7px;}
  #dlg-risk .rsx-froth-bar-lbl{width:92px;}
  #dlg-risk .riskdlg-drv .rkc-sig-body{flex-direction:column;gap:2px;align-items:flex-start;}
  #dlg-risk .riskdlg-odds-h{gap:12px;}
}
@container risk-dialog (max-width:340px){
  .rkc-mood-axis span:nth-child(2),.rkc-mood-axis span:nth-child(4){visibility:hidden;}
  #dlg-risk .rsx-froth-hd{grid-template-columns:1fr;}
  .rsx-froth-scoreline{justify-content:flex-start;}
  #dlg-risk .rsx-froth-bar-row{display:grid;grid-template-columns:minmax(0,1fr) 32px;gap:5px 8px;}
  #dlg-risk .rsx-froth-bar-lbl{width:auto;}
  #dlg-risk .rsx-froth-bar-track{grid-column:1/-1;grid-row:2;}
}

/* ═══ WAVE D — Market Sentiment dialog (sg-* classes) ══════════════════════
   Coherent with Wave C: same Fear→Neutral→Greed spectrum, the same conic
   @property arc idiom (--sg-anim), animations gated on #dlg-sentiment.mx5-dlg-in
   + prefers-reduced-motion. The SIGNATURE is the 0-100 zone dial — a small arc
   with Fear/Neutral/Greed bands + a pointer — reused in the hero track and in
   every leg's hover popover. */
:root{ --sg-fear:var(--down,#ef4444); --sg-neu:var(--warn,#f59e0b); --sg-greed:var(--up,#22d97a); }
@property --sg-anim{syntax:'<number>';inherits:false;initial-value:0;}

/* — Hero: slim 0-100 zone track under the composite numeral — */
.sg-hero{display:flex;align-items:center;gap:16px;margin-bottom:8px;}
.sg-hero-num{font:800 40px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;}
.sg-hero-band{font:700 18px/1.15 var(--font-ui,inherit);}
.sg-hero-sub{font-size:11px;color:var(--ink-3,rgba(255,255,255,.4));margin-top:2px;}
.sg-track-wrap{position:relative;margin:6px 0 22px;padding-top:2px;}
.sg-track{position:relative;height:12px;border-radius:7px;overflow:hidden;
  background:linear-gradient(90deg,var(--sg-fear) 0%,var(--sg-neu) 50%,var(--sg-greed) 100%);
  opacity:.82;box-shadow:inset 0 1px 3px rgba(0,0,0,.28);}
[data-theme="light"] .sg-track{opacity:.9;}
.sg-track-tick{position:absolute;top:0;bottom:0;width:1px;background:rgba(255,255,255,.35);}
[data-theme="light"] .sg-track-tick{background:rgba(0,0,0,.22);}
.sg-track-marker{position:absolute;top:-5px;width:4px;height:22px;border-radius:3px;
  background:var(--text,#fff);border:2px solid var(--panel,#0f1420);z-index:2;
  box-shadow:0 1px 4px rgba(0,0,0,.4);transform:translateX(-50%);}
[data-theme="light"] .sg-track-marker{border-color:#fff;box-shadow:0 1px 4px rgba(0,0,0,.2);}
.sg-track-axis{display:flex;justify-content:space-between;font:600 9px/1 var(--font-ui,inherit);
  letter-spacing:.03em;color:var(--muted);margin-top:8px;text-transform:uppercase;}
@media(prefers-reduced-motion:no-preference){
  #dlg-sentiment .sg-track-marker{left:50%;transition:left 780ms cubic-bezier(.34,1.28,.5,1) .18s;}
  #dlg-sentiment.mx5-dlg-in .sg-track-marker{left:var(--sg-pos,50%);}
}
@media(prefers-reduced-motion:reduce){ #dlg-sentiment .sg-track-marker{left:var(--sg-pos,50%);} }

/* — Composite leg rows: hoverable popover triggers — */
#dlg-sentiment .mx5-dlg-factor-row[data-rpop]{cursor:pointer;
  transition:border-color .18s ease,transform .16s ease,background .18s ease;}
#dlg-sentiment .mx5-dlg-factor-row[data-rpop]:hover,
#dlg-sentiment .mx5-dlg-factor-row[data-rpop]:focus-visible{
  transform:translateY(-1px);border-color:color-mix(in srgb,var(--sg-c,var(--muted)) 45%,transparent);
  background:color-mix(in srgb,var(--sg-c,var(--muted)) 7%,rgba(255,255,255,.03));outline:none;}
[data-theme="light"] #dlg-sentiment .mx5-dlg-factor-row[data-rpop]:hover{
  background:color-mix(in srgb,var(--sg-c,var(--muted)) 7%,rgba(0,0,0,.02));}
.sg-hint{display:inline-flex;align-items:center;justify-content:center;width:15px;height:15px;
  margin-left:6px;border-radius:50%;font:700 9px/1 var(--font-ui,inherit);vertical-align:middle;
  color:var(--muted);border:1px solid color-mix(in srgb,var(--muted) 40%,transparent);opacity:.7;}
#dlg-sentiment .mx5-dlg-factor-row[data-rpop]:hover .sg-hint{opacity:1;color:var(--sg-c,var(--muted));
  border-color:color-mix(in srgb,var(--sg-c,var(--muted)) 55%,transparent);}
#dlg-sentiment .mx5-dlg-factor-fill{transform-origin:0 50%;}
@media(prefers-reduced-motion:no-preference){
  #dlg-sentiment .mx5-dlg-factor-fill{transform:scaleX(0);transition:transform 620ms cubic-bezier(.22,.9,.26,1.02);}
  #dlg-sentiment.mx5-dlg-in .mx5-dlg-factor-fill{transform:scaleX(1);}
}

/* — The zone dial (SIGNATURE): 0-100 semicircle, Fear/Neutral/Greed bands +
   pointer. Lives inside the cloned .rp-src payload, so all styling is by class. — */
.sg-dial{position:relative;width:132px;height:88px;margin:2px auto 0;}
.sg-dial svg{display:block;width:100%;height:74px;overflow:visible;}
.sg-dial-band-fear{stroke:var(--sg-fear);}
.sg-dial-band-neu{stroke:var(--sg-neu);}
.sg-dial-band-greed{stroke:var(--sg-greed);}
.sg-dial-track{stroke:color-mix(in srgb,var(--muted) 22%,transparent);}
.sg-dial-ptr{stroke:var(--text,#fff);stroke-width:2.4;stroke-linecap:round;}
.sg-dial-hub{fill:var(--text,#fff);}
/* numeral + cap sit BELOW the arc baseline (y=64) so the needle never overlaps them */
.sg-dial-val{position:absolute;left:0;right:0;top:66px;text-align:center;
  font:800 19px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;color:var(--sg-c,var(--text));}
.sg-dial-cap{position:absolute;left:0;right:0;top:85px;text-align:center;
  font:600 9px/1 var(--font-ui,inherit);letter-spacing:.05em;text-transform:uppercase;color:var(--muted);}

/* — Popover interior (extends the shared .row-pop card) — */
.sg-pop-lead{padding:12px 14px 4px;}
.sg-pop-dialwrap{padding:8px 14px 6px;}
.sg-pop-expl{padding:2px 14px 12px;display:flex;flex-direction:column;gap:9px;}
.sg-pop-expl .sg-pe{display:flex;flex-direction:column;gap:2px;}
.sg-pe-lbl{font:600 9px/1 var(--font-ui,inherit);letter-spacing:.07em;text-transform:uppercase;color:var(--muted);}
.sg-pe-txt{font-size:12px;line-height:1.5;color:var(--text);}
.sg-pop-spark{padding:0 14px 12px;}
.sg-pop-spark-lbl{font:600 9px/1 var(--font-ui,inherit);letter-spacing:.07em;text-transform:uppercase;color:var(--muted);margin-bottom:5px;}
.sg-spark svg{display:block;width:100%;height:36px;}
/* graph slot collapses when no history is present — no fake chart (house law) */

/* — Volatility weather: per-row glyph + percentile position bar — */
/* (the vsb-vw-row class was retired by UD-B2-W1 R3 — the vol-weather strip now
   lives inside .mx5-sc-left and inherits tokens via .sx-vw-row.) */
.sg-wx{width:24px;height:24px;display:flex;align-items:center;justify-content:center;color:var(--muted);}
.sg-wx svg{width:20px;height:20px;display:block;}
.sg-pos{position:relative;height:6px;border-radius:4px;background:rgba(255,255,255,.08);margin-top:7px;}
[data-theme="light"] .sg-pos{background:rgba(0,0,0,.08);}
.sg-pos-axis{display:flex;justify-content:space-between;font:600 8px/1 var(--font-ui,inherit);color:var(--muted);margin-top:4px;letter-spacing:.02em;}
@media(prefers-reduced-motion:no-preference){
  #dlg-sentiment .sg-pos-mark{left:50%;transition:left 640ms cubic-bezier(.34,1.2,.5,1) .12s;}
  #dlg-sentiment.mx5-dlg-in .sg-pos-mark{left:var(--sg-pp,50%);}
}
@media(prefers-reduced-motion:reduce){ #dlg-sentiment .sg-pos-mark{left:var(--sg-pp,50%);} }

/* — AI names vs the rest: two proportional cohort bars + delta chip — */
.sg-split{display:flex;flex-direction:column;gap:12px;margin:4px 0 8px;}
.sg-split-row{display:grid;grid-template-columns:minmax(96px,auto) 1fr 42px;align-items:center;gap:12px;}
.sg-split-lbl{font:600 12px/1.3 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.85));}
[data-theme="light"] .sg-split-lbl{color:rgba(0,0,0,.8);}
.sg-split-track{position:relative;height:16px;border-radius:8px;background:rgba(255,255,255,.06);overflow:hidden;}
[data-theme="light"] .sg-split-track{background:rgba(0,0,0,.06);}
.sg-split-fill{position:absolute;left:0;top:0;bottom:0;border-radius:8px;transform-origin:0 50%;}
.sg-split-fill.ai{background:linear-gradient(90deg,color-mix(in srgb,var(--info,#4d8ef5) 55%,transparent),var(--info,#4d8ef5));}
.sg-split-fill.non{background:linear-gradient(90deg,color-mix(in srgb,var(--muted) 45%,transparent),color-mix(in srgb,var(--muted) 80%,transparent));}
.sg-split-val{font:800 16px/1 var(--font-ui,inherit);font-variant-numeric:tabular-nums;text-align:right;color:var(--ink-1,rgba(255,255,255,.85));}
[data-theme="light"] .sg-split-val{color:rgba(0,0,0,.82);}
.sg-split-delta{display:inline-flex;align-items:center;gap:5px;font:700 10.5px/1 var(--font-ui,inherit);letter-spacing:.02em;
  padding:4px 10px;border-radius:999px;margin-top:2px;
  color:var(--ink-warn, var(--warn,#f59e0b));background:color-mix(in srgb,var(--warn,#f59e0b) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--warn,#f59e0b) 30%,transparent);}
.sg-split-delta::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;}
@media(prefers-reduced-motion:no-preference){
  #dlg-sentiment .sg-split-fill{transform:scaleX(0);transition:transform 700ms cubic-bezier(.22,.9,.26,1.02) .1s;}
  #dlg-sentiment.mx5-dlg-in .sg-split-fill{transform:scaleX(1);}
}

/* — one-line dialog footer receipt (Wave B section-j pattern) — */
.sg-foot{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 12px;font-size:10px;
  color:var(--ink-3,rgba(255,255,255,.4));line-height:1.5;margin-top:6px;}
.sg-foot-asof{font-variant-numeric:tabular-nums;}

@media(max-width:430px){
  .sg-hero-num{font-size:34px;}
  .sg-split-row{grid-template-columns:minmax(80px,auto) 1fr 38px;gap:8px;}
  .row-pop .sg-dial{width:120px;height:68px;}
}

/* ── MARKET SENTIMENT (static card — odometer dial) ────────────── */
body.page-macro.mx4-grid .mx5-sentiment-dial-wrap{
  text-align:center;margin-bottom:4px;
}
body.page-macro.mx4-grid .mx5-sentiment-zone-text{
  font-size:15px;font-weight:700;color:var(--mx5-accent-ink);
  text-align:center;margin-bottom:3px;
}
body.page-macro.mx4-grid .mx5-sentiment-label{
  font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));
  text-align:center;margin-top:2px;
}

/* ── SECTOR TEMPERATURE (static card) ──────────────────────────── */
body.page-macro.mx4-grid .mx5-sector-row{margin-bottom:14px;}
body.page-macro.mx4-grid .mx5-sector-sub-label{
  font-size:11px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;
  color:var(--ink-3,rgba(255,255,255,.36));margin-bottom:7px;
}
body.page-macro.mx4-grid .mx5-sector-chips{display:flex;flex-wrap:wrap;gap:5px;}
body.page-macro.mx4-grid .mx5-sector-chip{
  padding:4px 11px;border-radius:var(--mx5-radius-pill);
  font-size:12px;font-weight:600;
}
body.page-macro.mx4-grid .mx5-sector-chip.hot{
  background:rgba(34,217,122,.11);border:1px solid rgba(34,217,122,.28);
  color:var(--ink-up,var(--up,#22d97a));
}
body.page-macro.mx4-grid .mx5-sector-chip.cold{
  background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.22);
  color:var(--ink-down,var(--down,#ef4444));
}
/* zh 红涨绿跌: hot(强势)=red family, cold(退潮)=green family — text already flips
   via --up/--down; the literal glass tints mirror here */
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-sector-chip.hot{
  background:rgba(239,68,68,.11);border-color:rgba(239,68,68,.28);
}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-sector-chip.cold{
  background:rgba(34,217,122,.08);border-color:rgba(34,217,122,.22);
}
/* sector heat bars — hue by class (rank decay rides the bar's inline opacity) */
body.page-macro.mx4-grid .mx5-shb-hot{background:#22d97a;}
body.page-macro.mx4-grid .mx5-shb-cool{background:#ef4444;}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-shb-hot{background:#ef4444;}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-shb-cool{background:#22d97a;}
body.page-macro.mx4-grid .mx5-sector-heat-divider{
  margin-top:14px;padding-top:14px;border-top:1px solid rgba(255,255,255,.07);
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-sector-heat-divider{border-top-color:rgba(0,0,0,.06);}
/* Wave E — enlarged hero heat strip: taller cells + a baseline so it reads as a chart */
body.page-macro.mx4-grid .mx5-sector-heat-divider.hero{margin-top:16px;}
body.page-macro.mx4-grid .mx5-sector-heat-label{
  font-size:11px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;
  color:var(--ink-3,rgba(255,255,255,.36));margin-bottom:10px;
}
body.page-macro.mx4-grid .mx5-sector-heat-bars{
  display:flex;gap:5px;align-items:flex-end;
}
body.page-macro.mx4-grid .mx5-sector-heat-divider.hero .mx5-sector-heat-bars{
  min-height:56px;gap:6px;padding-bottom:9px;
  border-bottom:1px solid rgba(255,255,255,.06);
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-sector-heat-divider.hero .mx5-sector-heat-bars{border-bottom-color:rgba(0,0,0,.05);}
body.page-macro.mx4-grid .mx5-sector-heat-col{
  flex:1 1 0;min-width:14px;display:flex;flex-direction:column;gap:3px;align-items:center;
}
body.page-macro.mx4-grid .mx5-sector-heat-bar{width:100%;border-radius:3px 3px 2px 2px;
  transition:filter .18s ease;}
body.page-macro.mx4-grid .mx5-sector-heat-divider.hero .mx5-sector-heat-bar{border-radius:4px 4px 2px 2px;}
body.page-macro.mx4-grid #sx-v5-sector .mx5-card:hover .mx5-sector-heat-bar{filter:brightness(1.12);}
/* legend under the hero strip: heating vs cooling */
body.page-macro.mx4-grid .mx5-sector-heat-legend{
  display:flex;justify-content:space-between;margin-top:8px;
  font-size:10px;font-weight:600;letter-spacing:.03em;
}
body.page-macro.mx4-grid .mx5-sector-heat-legend .heat-up{color:var(--ink-up,var(--up,#22d97a));}
body.page-macro.mx4-grid .mx5-sector-heat-legend .heat-dn{color:var(--ink-down,var(--down,#ef4444));}
/* .mx5-sector-heat-name removed (2.5 — truncation at every width; full names in chip lists) */

/* ── ALERTS CENTRE (sx-news-v2 face) — Wave E ───────────────────────────── */
body.page-macro.mx4-grid #sx-news-v2 .sxg-face.mx5-card-face .mx5-alerts-list{
  display:flex;flex-direction:column;margin:0 -26px;
}
body.page-macro.mx4-grid .mx5-alert-item{
  position:relative;display:flex;align-items:flex-start;gap:11px;
  padding:12px 26px 12px 23px;border-bottom:1px solid rgba(255,255,255,.05);
  border-left:3px solid transparent;
  transition:background .18s ease;
}
body.page-macro.mx4-grid .mx5-alert-item:last-child{border-bottom:none;}
/* left severity accent bar per row + glass row hover */
body.page-macro.mx4-grid .mx5-alert-item.warn{
  background:rgba(245,158,11,.04);border-left-color:var(--mx5-warn,#f59e0b);
}
body.page-macro.mx4-grid .mx5-alert-item.info{
  border-left-color:color-mix(in srgb,var(--ink-3,#8a93a3) 40%,transparent);
}
body.page-macro.mx4-grid .mx5-alert-item:hover{background:rgba(255,255,255,.03);}
body.page-macro.mx4-grid .mx5-alert-item.warn:hover{background:rgba(245,158,11,.07);}
[data-theme="light"] body.page-macro.mx4-grid .mx5-alert-item:hover{background:rgba(0,0,0,.02);}
body.page-macro.mx4-grid .mx5-alert-dot{
  width:8px;height:8px;border-radius:50%;flex-shrink:0;margin-top:5px;
}
body.page-macro.mx4-grid .mx5-alert-dot.warn{
  background:var(--mx5-warn);box-shadow:0 0 6px rgba(245,158,11,.55);
}
body.page-macro.mx4-grid .mx5-alert-dot.info{
  background:var(--ink-3,rgba(255,255,255,.36));
}
body.page-macro.mx4-grid .mx5-alert-content{flex:1;min-width:0;}
body.page-macro.mx4-grid .mx5-alert-title{
  font-size:13px;font-weight:600;
  color:var(--ink-1,rgba(255,255,255,.92));line-height:1.4;
}
body.page-macro.mx4-grid .mx5-alert-k{
  font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  color:var(--ink-3);margin-right:6px;
}
body.page-macro.mx4-grid .mx5-alert-title.warn{color:var(--mx5-warn-ink);}
body.page-macro.mx4-grid .mx5-alert-detail{
  font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));
  margin-top:3px;line-height:1.5;
}
body.page-macro.mx4-grid .mx5-alert-footer{
  margin-top:14px;padding-top:11px;border-top:1px solid rgba(255,255,255,.06);
  font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));
  display:flex;justify-content:space-between;align-items:center;gap:10px;
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-alert-footer{border-top-color:rgba(0,0,0,.06);}
@media(prefers-reduced-motion:reduce){
  body.page-macro.mx4-grid .mx5-alert-item{transition:none;}
}

/* ── POLICY MONITOR (sx-policy-v2 face) ────────────────────────── */
body.page-macro.mx4-grid .mx5-policy-rows{display:flex;flex-direction:column;}
body.page-macro.mx4-grid .mx5-policy-row{
  display:flex;justify-content:space-between;align-items:baseline;
  padding:9px 0;border-bottom:1px solid rgba(255,255,255,.06);font-size:13px;
}
body.page-macro.mx4-grid .mx5-policy-row:last-child{border-bottom:none;}
body.page-macro.mx4-grid .mx5-policy-key{
  color:var(--ink-3,rgba(255,255,255,.36));font-size:12px;
}
body.page-macro.mx4-grid .mx5-policy-val{
  color:var(--ink-1,rgba(255,255,255,.92));font-weight:600;text-align:right;
}

/* ── POLICY MONITOR face revamp (plf-*) ────────────────────────── */
body.page-macro.mx4-grid .plf-stance-row{display:flex;align-items:flex-start;gap:7px;font-size:12px;font-weight:600;color:var(--ink-1,rgba(255,255,255,.92));margin-bottom:10px;}
body.page-macro.mx4-grid .plf-spark-row{display:flex;align-items:center;gap:10px;margin-bottom:10px;}
body.page-macro.mx4-grid .plf-spark-svg{width:120px;height:36px;flex-shrink:0;}
body.page-macro.mx4-grid .plf-spark-label{font-size:11px;color:var(--ink-2,rgba(255,255,255,.6));line-height:1.5;min-width:0;}
body.page-macro.mx4-grid .plf-chip-row{display:flex;flex-wrap:wrap;gap:5px;}
body.page-macro.mx4-grid .plf-chip{
  display:inline-flex;align-items:center;font-size:11px;font-weight:500;
  padding:2px 8px;border-radius:var(--mx5-radius-pill,20px);
  background:rgba(160,112,232,.10);border:1px solid rgba(160,112,232,.22);
  color:var(--ink-2,rgba(255,255,255,.6));
}
[data-theme="light"] .plf-chip{background:rgba(160,112,232,.08);border-color:rgba(160,112,232,.28);color:rgba(40,20,70,.72);}
/* Fed face: spark hero gets more presence + quiet "open" affordance bottom-right */
body.page-macro.mx4-grid #sx-v5-fed .plf-spark-svg{width:100%;height:44px;}
body.page-macro.mx4-grid #sx-v5-fed .plf-spark-row{margin-bottom:8px;}
body.page-macro.mx4-grid .plf-open{display:inline-flex;align-items:center;gap:4px;margin-top:12px;
  font:600 10.5px/1 var(--font-ui,inherit);letter-spacing:.04em;text-align:right;
  color:color-mix(in srgb,var(--isle-policy,#a070e8) 45%,var(--text));transition:opacity .18s ease,transform .18s ease;}
/* face-anatomy: each card's open chip carries its own isle colour + right-aligns */
body.page-macro.mx4-grid #sx-v5-fed .plf-open{color:color-mix(in srgb,var(--isle-policy,#a070e8) 45%,var(--text));align-self:flex-start;}
body.page-macro.mx4-grid #sx-v5-sentiment .mx5-card,
body.page-macro.mx4-grid #sx-v5-sector .mx5-card{display:flex;flex-direction:column;}
body.page-macro.mx4-grid .plf-open-sent{color:color-mix(in srgb,var(--isle-brief,#38c472) 45%,var(--text));align-self:flex-end;margin-left:auto;}
body.page-macro.mx4-grid .plf-open-sect{color:color-mix(in srgb,var(--isle-evidence,#20c0a0) 45%,var(--text));align-self:flex-end;margin-left:auto;}
body.page-macro.mx4-grid #sx-v5-fed:hover .plf-open,
body.page-macro.mx4-grid #sx-v5-fed:focus-within .plf-open,
body.page-macro.mx4-grid #sx-v5-sentiment:hover .plf-open,
body.page-macro.mx4-grid #sx-v5-sentiment:focus-within .plf-open,
body.page-macro.mx4-grid #sx-v5-sector:hover .plf-open,
body.page-macro.mx4-grid #sx-v5-sector:focus-within .plf-open{opacity:1;transform:translateX(2px);}
@media(prefers-reduced-motion:reduce){
  body.page-macro.mx4-grid #sx-v5-fed:hover .plf-open,
  body.page-macro.mx4-grid #sx-v5-sentiment:hover .plf-open,
  body.page-macro.mx4-grid #sx-v5-sector:hover .plf-open{transform:none;}
}
/* ── AI BRIEF (sx-aibrief-v2 face) ─────────────────────────────── */
body.page-macro.mx4-grid .mx5-ai-ticker-pills{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:11px;}
body.page-macro.mx4-grid .mx5-ai-ticker-pill{
  padding:4px 10px;border-radius:var(--mx5-radius-pill);
  background:var(--mx5-accent-dim);border:1px solid rgba(34,217,122,.28);
  font-size:11px;font-weight:700;color:var(--mx5-accent-ink);letter-spacing:.03em;
}
body.page-macro.mx4-grid .mx5-ai-body{
  font-size:13px;color:var(--ink-2,rgba(255,255,255,.6));
  line-height:1.55;margin-bottom:10px;
}
body.page-macro.mx4-grid .mx5-ai-note{
  font-size:11.5px;color:var(--ink-3,rgba(255,255,255,.36));
  background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);
  border-radius:8px;padding:8px 11px;line-height:1.45;margin-top:auto;
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-ai-note{
  background:rgba(0,0,0,.03);border-color:rgba(0,0,0,.06);
}

/* ── WHERE NEXT router (sx-deep-context face) — Wave E ─────────────
   Signal-ranked destination cards: eyebrow / destination kicker / state word /
   one plain line / arrow. Each card is a glass tile with a left rail tinted to the
   destination's isle colour. Degrades per-slot to the quiet link row below. */
body.page-macro.mx4-grid #sx-deep-context .sxg-face.mx5-card-face{
  flex-direction:column;align-items:stretch;gap:14px;
  padding:18px 20px 16px!important;min-height:unset;cursor:default;
}
body.page-macro.mx4-grid .wnx-eyebrow{
  font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--ink-3,rgba(255,255,255,.4));display:flex;align-items:center;gap:8px;
}
body.page-macro.mx4-grid .wnx-eyebrow::after{content:'';flex:1;height:1px;
  background:linear-gradient(90deg,color-mix(in srgb,var(--isle-deep) 30%,transparent),transparent);}
body.page-macro.mx4-grid .wnx-cards{
  display:grid;grid-template-columns:repeat(3,1fr);gap:12px;
}
body.page-macro.mx4-grid .wnx-card{
  --wnx-c:var(--isle-deep,#4d8ef5);
  position:relative;display:flex;flex-direction:column;gap:5px;
  padding:14px 16px 14px 18px;border-radius:13px;
  background:color-mix(in srgb,var(--wnx-c) 5%,var(--mx5-glass-bg));
  border:1px solid color-mix(in srgb,var(--wnx-c) 16%,var(--mx5-glass-border));
  text-decoration:none;overflow:hidden;
  transition:transform .16s ease,border-color .2s ease,background .2s ease,box-shadow .25s ease;
}
body.page-macro.mx4-grid .wnx-card::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;
  background:var(--wnx-c);opacity:.85;border-radius:0 2px 2px 0;}
body.page-macro.mx4-grid .wnx-card:hover,
body.page-macro.mx4-grid .wnx-card:focus-visible{
  transform:translateY(-2px);outline:none;
  border-color:color-mix(in srgb,var(--wnx-c) 42%,transparent);
  background:color-mix(in srgb,var(--wnx-c) 9%,var(--mx5-glass-bg));
  box-shadow:0 10px 26px -14px color-mix(in srgb,var(--wnx-c) 60%,transparent);
}
body.page-macro.mx4-grid .wnx-kicker{
  font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  color:color-mix(in srgb,var(--wnx-c) 45%,var(--text));display:flex;align-items:center;gap:6px;
}
body.page-macro.mx4-grid .wnx-kicker svg{width:12px;height:12px;flex-shrink:0;}
body.page-macro.mx4-grid .wnx-state{
  font-size:15px;font-weight:800;line-height:1.2;color:var(--ink-1,rgba(255,255,255,.94));
  font-variant-numeric:tabular-nums;
}
body.page-macro.mx4-grid .wnx-line{
  font-size:11.5px;line-height:1.4;color:var(--ink-2,rgba(255,255,255,.6));
  margin-bottom:2px;
}
body.page-macro.mx4-grid .wnx-go{
  margin-top:auto;font-size:10.5px;font-weight:700;letter-spacing:.03em;
  /* accent mixed to text-grade in BOTH themes (the .68-alpha wash measured
     1.69–1.76:1 on light, 2.92–4.15 dark); hover keeps the lift + slide. */
  color:color-mix(in srgb,var(--wnx-c) 45%,var(--text));display:inline-flex;align-items:center;gap:4px;
  transition:opacity .18s ease,transform .18s ease;
}
body.page-macro.mx4-grid .wnx-card:hover .wnx-go,
body.page-macro.mx4-grid .wnx-card:focus-visible .wnx-go{opacity:1;transform:translateX(2px);}
/* quiet link row — nothing lost: all six destinations remain reachable */
body.page-macro.mx4-grid .mx5-deep-chips{display:flex;flex-wrap:wrap;gap:8px 6px;align-items:center;
  padding-top:12px;border-top:1px solid rgba(255,255,255,.05);}
[data-theme="light"] body.page-macro.mx4-grid .mx5-deep-chips{border-top-color:rgba(0,0,0,.05);}
body.page-macro.mx4-grid .mx5-deep-chips-lbl{
  font-size:10px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;
  color:var(--ink-3,rgba(255,255,255,.34));margin-right:2px;}
body.page-macro.mx4-grid .mx5-deep-chip{
  display:inline-flex;align-items:center;gap:6px;
  padding:5px 11px;border-radius:var(--mx5-radius-pill);
  background:transparent;border:1px solid transparent;
  font-size:11.5px;font-weight:600;color:var(--ink-3,rgba(255,255,255,.45));
  text-decoration:none;
  transition:color .15s,border-color .15s,background .15s;
}
body.page-macro.mx4-grid .mx5-deep-chip:hover{
  color:var(--ink-1,rgba(255,255,255,.92));
  border-color:rgba(255,255,255,.14);background:rgba(255,255,255,.06);
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-deep-chip:hover{
  border-color:rgba(0,0,0,.1);background:rgba(0,0,0,.04);}
/* Look-up row. Same chip component as .mx5-deep-chips; only the mark differs.
   The # is the library's own mark (it is the reveal glyph on reference.html's
   index lines) — it appears on the dashboard wherever a definition is one click
   away, and nowhere else. One idea, two surfaces. */
body.page-macro.mx4-grid .mx5-deep-chips--ref{padding-top:8px;border-top:0;}
body.page-macro.mx4-grid .mx5-ref-hash{font-weight:600;margin-right:1px;}
/* DARK: hold the mark back with opacity — on graphite, depth is the quiet axis
   and a full-strength glyph would read as a bullet.
   LIGHT: opacity on white is contrast LOSS, so light restores full colour and
   adds weight instead. Same emphasis, opposite mechanism. */
body.page-macro.mx4-grid .mx5-ref-hash{opacity:.55;}
[data-theme="light"] body.page-macro.mx4-grid .mx5-ref-hash{opacity:1;font-weight:700;
  color:var(--muted);}
body.page-macro.mx4-grid .mx5-ref-chip:hover .mx5-ref-hash{opacity:1;}
@media(max-width:760px){
  body.page-macro.mx4-grid .wnx-cards{grid-template-columns:1fr;}
}
@media(prefers-reduced-motion:reduce){
  body.page-macro.mx4-grid .wnx-card,
  body.page-macro.mx4-grid .wnx-card:hover,
  body.page-macro.mx4-grid .wnx-card:focus-visible{transform:none;}
  body.page-macro.mx4-grid .wnx-card:hover .wnx-go,
  body.page-macro.mx4-grid .wnx-card:focus-visible .wnx-go{transform:none;}
}

/* ── Sparkline (idx_spark, static SVG) ─────────────────────────── */
/* spark colors match sign: .up or .dn set on the tile */
body.page-macro.mx4-grid .mx5-spark-up path.mx5-spark-area{fill:rgba(34,217,122,.10);}
body.page-macro.mx4-grid .mx5-spark-up path.mx5-spark-line,
body.page-macro.mx4-grid .mx5-spark-up polyline{stroke:#22d97a;}
body.page-macro.mx4-grid .mx5-spark-dn path.mx5-spark-area{fill:rgba(239,68,68,.08);}
body.page-macro.mx4-grid .mx5-spark-dn path.mx5-spark-line,
body.page-macro.mx4-grid .mx5-spark-dn polyline{stroke:#ef4444;}
/* zh 红涨绿跌 mirror — up-spark red, down-spark green (neon family preserved) */
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-spark-up path.mx5-spark-area{fill:rgba(239,68,68,.10);}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-spark-up path.mx5-spark-line,
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-spark-up polyline{stroke:#ef4444;}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-spark-dn path.mx5-spark-area{fill:rgba(34,217,122,.08);}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-spark-dn path.mx5-spark-line,
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-spark-dn polyline{stroke:#22d97a;}

/* ── 1.2 heatmap scorecard title hidden (eyebrow already names it) ── */
body.page-macro.mx4-grid #dlg-heatmap-scorecard .hm-sc-tit{display:none}

/* ── 1.3 expanded overlay de-chrome (body.page-macro scoping; no heatmap.js edit) ── */
body.page-macro .hm-ov .hm-bar{background:none;border:none;padding:0;border-radius:0}
body.page-macro .hm-ov .hm-tm-wrap{background:transparent;border:none;border-radius:0}

/* ── 2.5 mobile-only full heatmap link (hidden on wider screens) ── */
body.page-macro .mx5-dlg-hm-mobile-link{display:none;margin-top:10px;text-align:center;}
body.page-macro .mx5-dlg-hm-mobile-link a{font-size:13px;color:var(--ink-link, var(--link,#22d97a));font-weight:600;}
@media(max-width:700px){body.page-macro .mx5-dlg-hm-mobile-link{display:block;}}


/* light: bloom off (DESIGN_DOCTRINE §5.8) — a coloured glow behind text is a jewel on graphite
     and a stain on white; dark keeps every one of these). */
html[data-theme="light"] :is(
  body.page-macro.mx4-grid .mx5-big-score,
  body.page-macro.mx4-grid.ms-green-page .mx5-big-score, body.page-macro.mx4-grid .mx5-score-green .mx5-big-score,
  body.page-macro.mx4-grid.ms-yellow-page .mx5-big-score, body.page-macro.mx4-grid .mx5-score-yellow .mx5-big-score,
  body.page-macro.mx4-grid.ms-red-page .mx5-big-score, body.page-macro.mx4-grid .mx5-score-red .mx5-big-score
) { text-shadow:none; }

/* ══════════════════════════════════════════════════════════
   Macro Risk Detail — volatility & correlation diagnostics
   The eight display-only vol-weather reads live behind Risk Detail rather
   than lengthening the primary scorecard. Same engine bands and chip keys;
   presentation only. Desktop groups the evidence into a compact 2-column
   grid; mobile stacks to one column. */

body.page-macro .riskdlg-vw{
  margin-top:16px;
  padding-top:16px;
  border-top:1px solid var(--line);
}
body.page-macro .riskdlg-vw-note{
  margin:-3px 0 10px;
  color:var(--ink-2,var(--muted));
  font-size:11px;
  line-height:1.5;
}
body.page-macro .riskdlg-vw .sx-vw-strip{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
  margin:0;
  padding:0;
  background:transparent;
}
body.page-macro .riskdlg-vw .sx-vw-row{
  display:grid;
  grid-template-columns:24px minmax(0,1fr) 64px;
  align-items:center;
  gap:9px;
  min-width:0;
  padding:8px 10px;
  border:1px solid var(--line);
  border-radius:var(--r-ctl);
  background:var(--panel2);
}
html[data-theme="light"] body.page-macro .riskdlg-vw .sx-vw-row{
  background:var(--panel);
  box-shadow:var(--card-shadow);
}
body.page-macro .riskdlg-vw .sg-wx{
  width:24px;
  height:24px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:var(--muted);
}
body.page-macro .riskdlg-vw .sg-wx svg{
  width:18px;
  height:18px;
  display:block;
}
body.page-macro .riskdlg-vw .sx-vw-row--calm .sg-wx{color:var(--up);}
body.page-macro .riskdlg-vw .sx-vw-row--quiet .sg-wx,
body.page-macro .riskdlg-vw .sx-vw-row--low .sg-wx,
body.page-macro .riskdlg-vw .sx-vw-row--normal .sg-wx{color:var(--info);}
body.page-macro .riskdlg-vw .sx-vw-row--elevated .sg-wx{color:var(--warn);}
body.page-macro .riskdlg-vw .sx-vw-row--extreme .sg-wx{color:var(--down);}
body.page-macro .riskdlg-vw .sx-vw-row--young .sg-wx{color:var(--muted);opacity:.6;}

body.page-macro .riskdlg-vw .sx-vw-mid{
  display:flex;
  flex-direction:column;
  gap:2px;
  min-width:0;
}
body.page-macro .riskdlg-vw .sx-vw-name{
  color:var(--ink-1,var(--text));
  font-size:11.5px;
  font-weight:700;
  line-height:1.3;
  white-space:normal;
}
body.page-macro .riskdlg-vw .sx-vw-read{
  color:var(--ink-2,var(--muted));
  font-size:10.5px;
  line-height:1.4;
  overflow-wrap:anywhere;
}
body.page-macro .riskdlg-vw .sx-vw-tier{
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  gap:1px;
  color:var(--ink-2,var(--muted));
  font-size:10.5px;
  font-weight:700;
  line-height:1.1;
  letter-spacing:.02em;
  text-align:right;
  white-space:nowrap;
}
body.page-macro .riskdlg-vw .sx-vw-row--calm .sx-vw-tier{color:var(--up);}
body.page-macro .riskdlg-vw .sx-vw-row--quiet .sx-vw-tier,
body.page-macro .riskdlg-vw .sx-vw-row--low .sx-vw-tier,
body.page-macro .riskdlg-vw .sx-vw-row--normal .sx-vw-tier{color:var(--info);}
body.page-macro .riskdlg-vw .sx-vw-row--elevated .sx-vw-tier{color:var(--warn);}
body.page-macro .riskdlg-vw .sx-vw-row--extreme .sx-vw-tier{color:var(--down);}
body.page-macro .riskdlg-vw .sx-vw-row--young .sx-vw-tier{color:var(--ink-3,var(--muted));}

@media(max-width:640px){
  body.page-macro .riskdlg-vw .sx-vw-strip{
    grid-template-columns:minmax(0,1fr);
  }
  body.page-macro .riskdlg-vw .sx-vw-row{
    grid-template-columns:22px minmax(0,1fr) 58px;
    gap:8px;
    padding:7px 9px;
  }
  body.page-macro .riskdlg-vw .sg-wx{width:22px;height:22px;}
  body.page-macro .riskdlg-vw .sg-wx svg{width:16px;height:16px;}
}

