/* ═══════════════════════════════════════════════════════════════════
   MX5 — Aurora-Glass command scorecard skin (v5_final rev2, 2026-07-12)
   ALL selectors scoped under body.page-macro.mx4-grid (grid view only).
   Ledger view (body.page-macro without .mx4-grid) is pixel-untouched.
   ═══════════════════════════════════════════════════════════════════ */

/* ── v5 glass tokens (grid view override layer) ─────────────────── */
body.page-macro.mx4-grid {
  --mx5-glass-bg:      rgba(16,22,30,.55);
  --mx5-pop-bg:        rgba(13,18,26,.96);
  --mx5-glass-border:  rgba(255,255,255,.12);
  --mx5-glass-shadow:  0 8px 32px rgba(0,0,0,.55), 0 1.5px 0 rgba(255,255,255,.07) inset;
  --mx5-glass-hover:   0 12px 40px rgba(0,0,0,.65), 0 1.5px 0 rgba(255,255,255,.09) inset;
  --mx5-blur:          blur(20px);
  --mx5-radius-card:   18px;
  --mx5-radius-pill:   999px;
  /* --mx5-accent MUST be the token, not a literal. Custom properties resolve at their
     DECLARATION scope, so the .mx5-score-green{--mx5-accent:var(--up)} redefinition
     further down can never reach the derived -glow/-dim/-ink computed here. With the
     literal in place, zh flipped the gauge arc, the needle and the big 76 to red
     (correct) while the regime pill and the 偏多 stance line beside them stayed green —
     one state drawn in both directions inside a single 300x180 card. china/hk already
     route this through --up; macro was the last page that did not. */
  --mx5-accent:        var(--up,#22d97a);
  --mx5-accent-glow:   color-mix(in srgb, var(--up,#22d97a) 30%, transparent);
  --mx5-accent-dim:    color-mix(in srgb, var(--up,#22d97a) 10%, transparent);
  --mx5-warn:          var(--warn,#f59e0b);
  --mx5-warn-dim:      color-mix(in srgb, var(--warn,#f59e0b) 10%, transparent);
  /* v5.3 audit round: TEXT-role accents. Fills keep the bright hue above;
     text uses these so light mode swaps in the darker, ≥4.5:1 accent
     (theme.css already provides --up/--warn darkened for light). */
  --mx5-accent-ink:    var(--ink-up, var(--mx5-accent));
  --mx5-warn-ink:      var(--ink-warn, var(--mx5-warn));
}
[data-theme="light"] body.page-macro.mx4-grid {
  /* Round-3 depth pass: the panels were 82% white over a near-white canvas —
     the card surface and the page were the SAME value, so nothing read as a
     card. Panels are now opaque white on the deepened #e8ebf1 canvas, with the
     estate's two-stop shadow (a tight contact shadow + a wide ambient one) and
     the soft recipe hairline. Depth now comes from the value step + the shadow,
     which is why the border can afford to be quiet. */
  --mx5-glass-bg:      #ffffff;
  --mx5-pop-bg:        #ffffff;
  --mx5-glass-border:  #dde2ea;
  --mx5-glass-shadow:  0 1px 2px rgba(23,32,55,.05), 0 8px 24px -12px rgba(23,32,55,.10);
  --mx5-glass-hover:   0 2px 4px rgba(23,32,55,.07), 0 14px 32px -14px rgba(23,32,55,.16);
  /* Dedicated dark accents for TEXT on the light glass card (>=4.5:1 vs ~#f6f7fa).
     Deliberately darker than the site-wide --up/--warn (which are tuned ~3.4:1
     for other surfaces); fills above keep the bright #22d97a / #f59e0b. */
  --mx5-accent-ink:    #17753f;
  --mx5-warn-ink:      #9c6212;
}
/* zh 红涨绿跌 + light: the risk-on accent INK is a literal (deep green for contrast),
   so it can't flip via the --up swap — mirror it to a deep red of equal contrast.
   (Dark mode needs no mirror: accent-ink chains through --mx5-accent → --up there.) */
html[data-theme="light"][data-lang="zh"] body.page-macro.mx4-grid {
  --mx5-accent-ink:    #a82f2f;
}
/* ── v5.3 UNIFIED card hover (Order 5): ONE idiom for every grid card/face.
   No accent-colored tints anywhere — border brightens, surface lifts ~2%,
   translateY(-1px), soft ambient shadow. Same both directions, 200ms ease-out. */
body.page-macro.mx4-grid {
  --mx5-hover-bg:      rgba(22,29,38,.62);
  --mx5-hover-border:  rgba(255,255,255,.16);
  --mx5-hover-shadow:  0 6px 24px rgba(0,0,0,.25);
  --mx5-focus-ring:    0 0 0 2px rgba(34,217,122,.55);
}
[data-theme="light"] body.page-macro.mx4-grid {
  /* Round-3: the resting surface is now opaque white, so "surface lifts 2%" has
     nowhere to go in light — the lift is carried by the border stepping up and
     the ambient shadow deepening, alongside the shared translateY(-1px). */
  --mx5-hover-bg:      #ffffff;
  --mx5-hover-border:  #c3cbd9;
  --mx5-hover-shadow:  0 2px 4px rgba(23,32,55,.07), 0 14px 32px -14px rgba(23,32,55,.16);
}

/* ── Aurora backdrop (fixed position, grid-view only) ───────────── */
body.page-macro.mx4-grid .mx5-aurora{
  position:fixed;inset:0;
  pointer-events:none;z-index:0;overflow:hidden;
}
body.page-macro.mx4-grid .mx5-aurora::before{
  content:"";position:absolute;
  width:900px;height:700px;top:-200px;left:-150px;
  border-radius:50%;filter:blur(90px);
  background:radial-gradient(ellipse,rgba(34,217,122,.12) 0%,transparent 70%);
}
body.page-macro.mx4-grid .mx5-aurora::after{
  content:"";position:absolute;
  width:700px;height:600px;bottom:-100px;right:-100px;
  border-radius:50%;filter:blur(90px);
  background:radial-gradient(ellipse,rgba(99,102,241,.10) 0%,transparent 70%);
}
body.page-macro.mx4-grid .mx5-aurora .mx5-a3{
  position:absolute;width:600px;height:500px;
  top:40%;left:50%;transform:translate(-50%,-50%);
  border-radius:50%;filter:blur(90px);
  background:radial-gradient(ellipse,rgba(34,217,122,.07) 0%,transparent 70%);
}
body.page-macro.mx4-grid .mx5-aurora .mx5-a4{
  position:absolute;width:800px;height:600px;bottom:-150px;left:20%;
  border-radius:50%;filter:blur(90px);
  background:radial-gradient(ellipse,rgba(99,102,241,.08) 0%,transparent 70%);
}
/* LIGHT: the aurora is a dark-mode idiom — coloured light blooming out of a black
   field. Inverted onto paper it is not light, it is INK: four 90px-blurred colour
   washes that tint the canvas green/indigo and read as a printing stain (most
   visible as the "orb" floating in the empty canvas past the footer, since the
   layer is position:fixed and spans the whole scroll). It is also pure decoration
   here — the market state it tints is already stated by the gauge, the score and
   the thesis line — so light simply doesn't get it. Depth in light comes from the
   panel/canvas value step and the shadow recipe, not from ambient bloom.
   The state-tinted (.au-yellow/.au-red) light variants are dropped with it. */
[data-theme="light"] body.page-macro.mx4-grid .mx5-aurora{display:none;}
/* verdict-tinted aurora (operator order 2026-07-14): the two GREEN blobs follow the
   market-state color — amber when Mixed, red when Risk-off; the indigo companions
   stay neutral. Class baked from market_state.color + live-swapped by risk_state_live.js. */
body.page-macro.mx4-grid .mx5-aurora.au-yellow::before{background:radial-gradient(ellipse,rgba(245,158,11,.10) 0%,transparent 70%);}
body.page-macro.mx4-grid .mx5-aurora.au-yellow .mx5-a3{background:radial-gradient(ellipse,rgba(245,158,11,.06) 0%,transparent 70%);}
body.page-macro.mx4-grid .mx5-aurora.au-red::before{background:radial-gradient(ellipse,rgba(239,68,68,.10) 0%,transparent 70%);}
body.page-macro.mx4-grid .mx5-aurora.au-red .mx5-a3{background:radial-gradient(ellipse,rgba(239,68,68,.06) 0%,transparent 70%);}
@media(prefers-reduced-motion:reduce){
  body.page-macro.mx4-grid .mx5-aurora::before,
  body.page-macro.mx4-grid .mx5-aurora::after,
  body.page-macro.mx4-grid .mx5-aurora .mx5-a3{animation:none;}
  /* Order 5: unified hover — no motion (instant, no lift) under reduced-motion */
  body.page-macro.mx4-grid .sxg-face.mx5-card-face,
  body.page-macro.mx4-grid .mx5-card[role="button"],
  body.page-macro.mx4-grid .mx5-mkt-tile{transition:none!important;}
  body.page-macro.mx4-grid .sx:hover .sxg-face.mx5-card-face,
  body.page-macro.mx4-grid .sxg-face.mx5-card-face:hover,
  body.page-macro.mx4-grid .mx5-card[role="button"]:hover,
  body.page-macro.mx4-grid .mx5-mkt-tile:hover,
  body.page-macro.mx4-grid .mx5-mkt-tile.up:hover,
  body.page-macro.mx4-grid .mx5-mkt-tile.dn:hover{transform:none!important;}
}

/* ── Command Scorecard — #regime-radar restyled in grid view ─────── */
/* In grid view, #regime-radar becomes a two-column glass card:
   left = gauge cluster, right = 60-session path (hidden ≤700px) */
body.page-macro.mx4-grid #regime-radar{
  background:var(--mx5-glass-bg);
  border:1px solid var(--mx5-glass-border);
  border-radius:var(--mx5-radius-card);
  backdrop-filter:var(--mx5-blur);
  box-shadow:var(--mx5-glass-shadow);
  padding:0;overflow:visible;
  display:grid;
  /* Order 2: ~30:70 left:right (more room for the command cluster, less for the chart) */
  grid-template-columns:minmax(0,3fr) minmax(0,7fr);
  gap:0;
  min-height:320px;
  position:relative;
}
/* Ledger view: restore normal panel look */
body.page-macro:not(.mx4-grid) #regime-radar{
  display:block;padding:19px 21px;
}
@media(max-width:1100px){
  body.page-macro.mx4-grid #regime-radar{grid-template-columns:minmax(0,34fr) minmax(0,66fr);}
}
@media(max-width:700px){
  body.page-macro.mx4-grid #regime-radar{grid-template-columns:1fr;}
}

/* ── mx2-hero: hidden in grid view (scorecard replaces it) ── */
body.page-macro.mx4-grid #regime-radar .mx2-hero{
  display:none!important;
}
/* ── alerts toggle + misc hero bits: hidden in grid ── */
body.page-macro.mx4-grid #regime-radar .ms-head,
body.page-macro.mx4-grid #regime-radar .ms-oneline,
body.page-macro.mx4-grid #regime-radar .howto,
body.page-macro.mx4-grid #regime-radar > script + div > .ms-head{
  display:none;
}

/* ── Scorecard left cluster ──────────────────────────────────────── */
body.page-macro.mx4-grid .mx5-sc-left{
  padding:28px 26px 22px;
  border-right:1px solid rgba(255,255,255,.07);
  display:flex;flex-direction:column;
  position:relative;overflow:visible;
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-sc-left{
  border-right-color:rgba(0,0,0,.06);
}
body.page-macro.mx4-grid .mx5-sc-gauge-row{
  display:flex;align-items:center;gap:20px;margin-bottom:16px;
}
body.page-macro.mx4-grid .mx5-gauge-svg{
  /* Order 2: scaled up ~1.37× (viewBox unchanged → JS gauge math contract intact) */
  width:192px;height:138px;overflow:visible;display:block;flex-shrink:0;
}
/* Light mode: the gauge's white-alpha track/ticks/scale-labels vanish on white —
   repaint in dark ink. #mx5-score-numeral keeps its own id rule (state colour). */
/* Dial scale labels (0 / 50 / 100) are text, not decoration — they are what makes the
   needle position mean anything. At .42 they composited to #989b9e = 2.79:1 on a white
   card, under the 4.5 floor at 10px. .62 lands 5.37:1 and still reads a full step
   quieter than the body copy. Twin of the body.page-china rule — same component. */
[data-theme="light"] body.page-macro.mx4-grid .mx5-gauge-svg > text{fill:rgba(10,16,24,.62);}
[data-theme="light"] body.page-macro.mx4-grid .mx5-gauge-svg path:first-of-type{stroke:rgba(10,16,24,.10);}
[data-theme="light"] body.page-macro.mx4-grid .mx5-gauge-svg g[stroke]{stroke:rgba(10,16,24,.20);}
/* The shared light-mode pointer treatment lives in theme.css (`.odo-needle`).
   Dark mode keeps the original white blade + state-coloured hub below. */
/* Regime pill (Order 3: smaller + never clips — sizes to content, no fixed width) */
body.page-macro.mx4-grid .mx5-regime-pill{
  display:inline-flex;align-items:center;gap:6px;
  padding:4px 11px;border-radius:var(--mx5-radius-pill);
  border:1px solid var(--mx5-accent);background:var(--mx5-accent-dim);
  font-size:11px;font-weight:600;color:var(--mx5-accent-ink);
  letter-spacing:.02em;margin-bottom:10px;line-height:1.3;
  max-width:100%;box-sizing:border-box;text-align:left;width:auto;
}
/* pill parent flex child must not overflow — allow wrapping instead of bleed */
body.page-macro.mx4-grid .mx5-sc-gauge-row > div:last-child{min-width:0;}
/* The pill's text span must not be forced to shrink below its content */
/* span must be allowed to shrink AND wrap inside the pill — flex:0 0 auto here made the
   text escape the pill border once the pill itself stopped being nowrap (pill-bleed bug) */
body.page-macro.mx4-grid .mx5-regime-pill > span{flex:0 1 auto;min-width:0;}
/* pill follows the market-state verdict color (operator order 2026-07-13):
   default green accent when risk-on, amber when mixed, red when risk-off */
body.page-macro.mx4-grid .mx5-regime-pill.rp-yellow{
  border-color:var(--mx5-warn);background:var(--mx5-warn-dim);color:var(--mx5-warn-ink);
}
body.page-macro.mx4-grid .mx5-regime-pill.rp-yellow .mx5-dot{
  background:var(--mx5-warn);box-shadow:0 0 6px rgba(245,158,11,.30);
}
body.page-macro.mx4-grid .mx5-regime-pill.rp-red{
  border-color:var(--down,#ef4444);background:rgba(239,68,68,.10);color:var(--ink-down, var(--down,#ef4444));
}
body.page-macro.mx4-grid .mx5-regime-pill.rp-red .mx5-dot{
  background:var(--down,#ef4444);box-shadow:0 0 6px rgba(239,68,68,.30);
}
body.page-macro.mx4-grid .mx5-regime-pill .mx5-dot{
  width:6px;height:6px;border-radius:50%;
  background:var(--mx5-accent);box-shadow:0 0 6px var(--mx5-accent-glow);
}

/* Score + verdict beside gauge */
body.page-macro.mx4-grid .mx5-score-line{
  display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;
}
/* verdict word never breaks mid-word; wraps as a whole unit if the column is tight */
body.page-macro.mx4-grid .mx5-verdict-word{white-space:nowrap;}
body.page-macro.mx4-grid .mx5-big-score{
  font-size:68px;font-weight:800;line-height:.95;color:var(--mx5-accent-ink);
  text-shadow:0 0 40px var(--mx5-accent-glow);
  letter-spacing:-.035em;font-variant-numeric:tabular-nums;
}
body.page-macro.mx4-grid .mx5-verdict-word{
  font-size:19px;font-weight:700;color:var(--ink-1,var(--text,rgba(255,255,255,.92)));
}
body.page-macro.mx4-grid .mx5-sub-line{
  font-size:11px;color:var(--mx5-accent-ink);font-weight:600;margin-top:3px;
}
/* sub-line follows the verdict color like .mx5-big-score below — without these the
   page-global green accent paints "YELLOW — Trade with caution" green */
body.page-macro.mx4-grid .mx5-score-yellow .mx5-sub-line{color:var(--mx5-warn-ink);}
body.page-macro.mx4-grid .mx5-score-red .mx5-sub-line{color:var(--ink-down, var(--down,#ef4444));}
/* score color by state */
body.page-macro.mx4-grid.ms-green-page .mx5-big-score,
body.page-macro.mx4-grid .mx5-score-green .mx5-big-score{color:var(--ink-up, var(--up,#22d97a));text-shadow:0 0 36px rgba(34,217,122,.3);}
body.page-macro.mx4-grid.ms-yellow-page .mx5-big-score,
body.page-macro.mx4-grid .mx5-score-yellow .mx5-big-score{color:var(--ink-warn, var(--warn,#f59e0b));text-shadow:0 0 36px rgba(245,158,11,.3);}
body.page-macro.mx4-grid.ms-red-page .mx5-big-score,
body.page-macro.mx4-grid .mx5-score-red .mx5-big-score{color:var(--ink-down, var(--down,#ef4444));text-shadow:0 0 36px rgba(239,68,68,.3);}
/* v6 — STATE drives the hero glance (operator order 2026-07-13). The gauge arc, needle
   accent, glow and score numeral all follow the risk-STATE band (--mx5-gauge), never a fixed
   rainbow or the regime hue — so a caution/Mixed state reads amber, not "green/go". --mx5-gauge
   and --mx5-accent route through --up/--warn/--down, so they also honour the zh 红涨绿跌 swap
   (risk-on=red, risk-off=green in Chinese). The slow regime (e.g. Goldilocks) is demoted to a
   neutral label so it never competes with the stance colour. */
body.page-macro.mx4-grid .mx5-score-green  { --mx5-gauge: var(--up);   --mx5-accent: var(--up);   }
body.page-macro.mx4-grid .mx5-score-yellow { --mx5-gauge: var(--warn); --mx5-accent: var(--warn); }
body.page-macro.mx4-grid .mx5-score-red    { --mx5-gauge: var(--down); --mx5-accent: var(--down); }
body.page-macro.mx4-grid .mx5-sc-gauge-row {
  --mx5-accent-glow: color-mix(in srgb, var(--mx5-accent) 30%, transparent);
  --mx5-accent-dim:  color-mix(in srgb, var(--mx5-accent) 10%, transparent);
}
/* CSS wins over the SVG presentation attribute, so the arc + numeral recolour by state
   (and var() resolves here, unlike in a bare SVG stroke="" attribute). */
body.page-macro.mx4-grid #mx5-gauge-arc-fill { stroke: var(--mx5-gauge, #f59e0b); }
body.page-macro.mx4-grid #mx5-score-numeral  { fill: var(--mx5-gauge, #f59e0b); }
/* Regime pill: main #2542 colours it by the market-state verdict (.rp-yellow/.rp-red);
   the risk-on default reads --mx5-accent, which the .mx5-score-* rules above set to
   var(--up) — so the pill is verdict-coloured AND flips 红涨绿跌 in zh. (My earlier flat-grey
   override was dropped in the merge: it conflicted with #2542 and left risk-on pills grey
   while yellow/red were coloured.) */

/* Thesis + flip */
body.page-macro.mx4-grid .mx5-thesis{
  font-size:13px;font-weight:450;line-height:1.55;
  color:var(--ink-1,rgba(255,255,255,.92));
  margin:12px 0 10px;
  padding-left:0;
}
body.page-macro.mx4-grid .mx5-flip{
  font-size:11px;color:var(--ink-2,rgba(255,255,255,.6));
  padding:8px 11px;
  background:var(--mx5-warn-dim);
  border:1px solid rgba(245,158,11,.18);
  border-radius:9px;line-height:1.5;
}
body.page-macro.mx4-grid .mx5-flip-arrow{color:var(--mx5-warn-ink);}

/* Popover trigger buttons row */
body.page-macro.mx4-grid .mx5-btn-row{
  display:flex;gap:8px;flex-wrap:wrap;margin-top:14px;
  position:relative;
}
/* mx5-sc-btn — already glass; harmonized with the gbtn system (macro sweep 2026-07):
   inset top sheen, hover lift + softer shadow transition, warn/up tints re-derived
   from the --warn/--up tokens via color-mix so light/zh resolve at paint. Keeps its
   own --mx5-* glass tokens (tuned for the dialog chrome) and the aria-expanded hook. */
body.page-macro.mx4-grid .mx5-sc-btn{
  display:inline-flex;align-items:center;gap:6px;
  padding:7px 13px;border-radius:var(--mx5-radius-pill);
  border:1px solid var(--mx5-glass-border);
  background:var(--mx5-glass-bg);-webkit-backdrop-filter:blur(12px) saturate(140%);backdrop-filter:blur(12px) saturate(140%);
  color:var(--ink-2,rgba(255,255,255,.6));
  font-size:11px;font-weight:600;cursor:pointer;
  font-family:inherit;
  box-shadow:inset 0 1px 0 var(--gbtn-sheen);
  transition:color .2s ease,border-color .2s ease,background .2s ease,transform .16s ease,box-shadow .25s ease;
}
body.page-macro.mx4-grid .mx5-sc-btn:hover{
  color:var(--ink-1,rgba(255,255,255,.92));
  border-color:var(--gbtn-brd-hover);
  background:var(--gbtn-bg-hover);
  transform:translateY(-1px);
  box-shadow:inset 0 1px 0 var(--gbtn-sheen),0 8px 20px -10px rgba(3,7,18,.55);
}
body.page-macro.mx4-grid .mx5-sc-btn:active{transform:translateY(0) scale(.985);box-shadow:inset 0 1px 0 var(--gbtn-sheen);}
body.page-macro.mx4-grid .mx5-sc-btn[aria-expanded="true"]{
  color:var(--ink-1,rgba(255,255,255,.92));
  border-color:var(--gbtn-brd-hover);
  background:var(--gbtn-bg-hover);
}
body.page-macro.mx4-grid .mx5-sc-btn-warn{
  color:var(--mx5-warn-ink);
  border-color:color-mix(in srgb, var(--warn) 45%, var(--gbtn-brd));
  background:linear-gradient(180deg, color-mix(in srgb, var(--warn) 12%, var(--gbtn-bg)), var(--gbtn-bg));
}
body.page-macro.mx4-grid .mx5-sc-btn-warn:hover{
  background:linear-gradient(180deg, color-mix(in srgb, var(--warn) 20%, var(--gbtn-bg)), var(--gbtn-bg));border-color:color-mix(in srgb, var(--warn) 60%, var(--gbtn-brd));
}
body.page-macro.mx4-grid .mx5-sc-btn-warn[aria-expanded="true"]{
  background:linear-gradient(180deg, color-mix(in srgb, var(--warn) 20%, var(--gbtn-bg)), var(--gbtn-bg));border-color:color-mix(in srgb, var(--warn) 60%, var(--gbtn-brd));
}
body.page-macro.mx4-grid .mx5-sc-btn:focus-visible{
  outline:2px solid var(--link,#22d97a);outline-offset:2px;
}
@media (prefers-reduced-motion: reduce){
  body.page-macro.mx4-grid .mx5-sc-btn,
  body.page-macro.mx4-grid .mx5-sc-btn:hover,
  body.page-macro.mx4-grid .mx5-sc-btn:active{transform:none;}
}

/* ── 60-session path panel (right) ──────────────────────────────── */
body.page-macro.mx4-grid .mx5-sc-right{
  padding:22px 28px 20px;display:flex;flex-direction:column;
}
body.page-macro.mx4-grid .mx5-path-header{
  display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px;
}
body.page-macro.mx4-grid .mx5-path-title{
  font-size:11px;font-weight:700;letter-spacing:.10em;
  text-transform:uppercase;color:var(--ink-3,rgba(255,255,255,.36));
}
body.page-macro.mx4-grid .mx5-path-meta{font-size:11px;color:var(--ink-3,rgba(255,255,255,.36));}
/* Plot wrapper hosts the SVG + the screen-space JS hover overlays */
body.page-macro.mx4-grid .mx5-path-plot{
  position:relative;flex:1;min-height:190px;display:flex;
}
body.page-macro.mx4-grid .mx5-path-svg{
  display:block;width:100%;flex:1;min-height:190px;overflow:visible;
  touch-action:pan-y;
}
/* Axis-label + today-marker overlay — screen-space HTML so glyphs and the dot are
   never distorted by the SVG's preserveAspectRatio="none" fill-stretch. Positioned
   by % of the plot box (which the SVG fills exactly) so they track the gridlines. */
body.page-macro.mx4-grid .mx5-path-labels{
  position:absolute;inset:0;pointer-events:none;
  font-family:Inter,-apple-system,sans-serif;font-size:11px;line-height:1;
}
/* DIRECT children only: the bilingual l-en/l-zh spans nested inside pl-zone/pl-x must
   stay in normal flow — absolutizing them shrink-wraps the anchored parent to width 0,
   so right-aligned zone words overflow rightward past the plot edge (label-bleed bug) */
body.page-macro.mx4-grid .mx5-path-labels > span{position:absolute;white-space:nowrap;}
body.page-macro.mx4-grid .mx5-pl-y{
  left:6px;transform:translateY(-50%);
  color:var(--ink-3,rgba(255,255,255,.32));font-variant-numeric:tabular-nums;
}
body.page-macro.mx4-grid .mx5-pl-zone{
  right:14px;transform:translateY(-50%);font-weight:600;
}
/* zone labels: the .60–.66 alpha literals measured 1.51:1 (light) and 2.46:1
   (dark, the maroon) — the wash was the defect. State tokens are full-strength
   in dark and text-graded in light, and they carry the zh flip natively. */
body.page-macro.mx4-grid .mx5-pl-zone.on{color:var(--ink-up,var(--up));}
body.page-macro.mx4-grid .mx5-pl-zone.mid{color:var(--ink-warn,var(--warn));}
body.page-macro.mx4-grid .mx5-pl-zone.off{color:var(--ink-down,var(--down));}
/* zh 红涨绿跌: Risk-on(偏多)=bullish→red, Risk-off(偏空)=bearish→green (mid amber stays) */
/* zh flip now rides --up/--down at the token level — no hand-rolled override. */
/* path-chart verdict-band zone fills + boundary hairlines — the SVG rect/line elements
   carry these classes so the zh mirror below can re-tint them (their fill/stroke
   presentation attrs remain as no-CSS fallbacks; CSS wins over attrs). */
body.page-macro.mx4-grid .mx5-ph-zone-on{fill:rgba(34,217,122,.045);}
/* the risk-off zone carries 2× the tint of the other two, on purpose: it is the band a
   reader must be able to see the line ENTER, and at .045 it was invisible — which is
   part of why a window containing five risk-off prints read as calm. */
body.page-macro.mx4-grid .mx5-ph-zone-off{fill:rgba(239,68,68,.08);}
body.page-macro.mx4-grid .mx5-ph-hair-on{stroke:rgba(34,217,122,.22);}
body.page-macro.mx4-grid .mx5-ph-hair-off{stroke:rgba(239,68,68,.34);}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-ph-zone-on{fill:rgba(239,68,68,.045);}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-ph-zone-off{fill:rgba(34,217,122,.08);}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-ph-hair-on{stroke:rgba(239,68,68,.20);}
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-ph-hair-off{stroke:rgba(34,217,122,.34);}
/* Band gradient stops for the score path (mx5PathBandGrad). Tokens, not baked hex, so
   the line follows the theme and flips with --up/--down under zh 红涨绿跌 exactly like
   the zone tints above. */
body.page-macro.mx4-grid .mx5-ph-line{opacity:.95;}
body.page-macro.mx4-grid #mx5PathBandGrad stop.b-on{stop-color:var(--up);}
body.page-macro.mx4-grid #mx5PathBandGrad stop.b-mid{stop-color:var(--warn);}
body.page-macro.mx4-grid #mx5PathBandGrad stop.b-off{stop-color:var(--down);}
