/* ── Sector Temperature — rotation ladder (dlg-sector rebuild) ─────────────────
   Each sector is a rung; the little trace is its 5-day rank move (an honest 2-point
   trajectory — up = climbed, down = slipped), coloured green/red via --up/--down so
   ZH flips. Lane = current standing (leading / lagging); trace + delta = the move. */
.sct-lane{margin:0 0 20px;}
.sct-lane:last-of-type{margin-bottom:6px;}
.sct-lane-head{display:flex;align-items:center;gap:8px;margin:0 0 11px;
  font:700 11px/1 var(--font-ui,inherit);letter-spacing:.09em;text-transform:uppercase;}
.sct-lane-dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto;box-shadow:0 0 9px currentColor;}
.sct-lane.lead .sct-lane-head{color:color-mix(in srgb,var(--up,#22d97a) 78%,var(--text));}
.sct-lane.lag  .sct-lane-head{color:color-mix(in srgb,var(--down,#ef4444) 78%,var(--text));}
.sct-lane.lead .sct-lane-dot{color:var(--ink-up, var(--up,#22d97a));background:currentColor;}
.sct-lane.lag  .sct-lane-dot{color:var(--ink-down, var(--down,#ef4444));background:currentColor;}
.sct-lane-n{margin-left:auto;font:600 10.5px/1 var(--font-ui,inherit);letter-spacing:.01em;text-transform:none;color:var(--ink-3,rgba(255,255,255,.42));}
.sct-rung{display:grid;grid-template-columns:32px 1fr 132px 54px;align-items:center;gap:12px;
  padding:11px 13px;border-radius:13px;background:rgba(255,255,255,.03);
  border:1px solid rgba(255,255,255,.06);transition:border-color .2s,background .2s,transform .16s;}
.sct-rung + .sct-rung{margin-top:8px;}
[data-theme="light"] .sct-rung{background:rgba(0,0,0,.018);border-color:rgba(0,0,0,.06);}
.sct-rung:hover{transform:translateY(-1px);background:rgba(255,255,255,.05);
  border-color:color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 36%,var(--line,rgba(255,255,255,.1)));}
[data-theme="light"] .sct-rung:hover{background:rgba(0,0,0,.035);}
.sct-badge{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;
  color:var(--sct-c,var(--up,#22d97a));background:color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 14%,transparent);
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sct-c,var(--up,#22d97a)) 28%,transparent);}
.sct-badge svg{width:15px;height:15px;display:block;}
.sct-body{min-width:0;}
.sct-name{font:700 13px/1.25 var(--font-ui,inherit);color:var(--ink-1,rgba(255,255,255,.92));
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.sct-sub{margin-top:2px;font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.44));display:flex;align-items:center;gap:7px;}
.sct-sub .sct-rk{font-variant-numeric:tabular-nums;font-weight:700;color:var(--ink-2,rgba(255,255,255,.6));}
.sct-sub .sct-stance{text-transform:capitalize;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sct-trace{width:132px;height:30px;display:block;overflow:visible;}
.sct-trace .sct-base{stroke:color-mix(in srgb,var(--ink-3,#8b93a1) 45%,transparent);stroke-width:1;stroke-dasharray:2 3;}
