/* ── Calendar date = Release Radar selector (rr-inline, 2026-07) ─────────────
   Every non-FOMC card selects its date for the inline panel below. Covered
   dates carry a subtle radar dot; every selector sharing the selected date
   receives the same --info accent ring. FOMC cards route to Fed Path instead. */
.mx5-dlg-cal-card.rr-select{cursor:pointer;transition:border-color .16s ease,box-shadow .22s ease,background .16s ease;}
.mx5-dlg-cal-card.rr-select:hover{border-color:color-mix(in srgb,var(--info,#60a5fa) 40%,transparent);box-shadow:0 2px 12px color-mix(in srgb,var(--info,#60a5fa) 8%,transparent);}
.mx5-dlg-cal-card.rr-select:focus-visible{outline:2px solid var(--info,#60a5fa);outline-offset:2px;}
/* Selected date — outer blue ring survives green/amber live-status fills. */
.mx5-dlg-cal-card.rr-active{
  border-color:color-mix(in srgb,var(--info,#60a5fa) 58%,transparent);
  background:color-mix(in srgb,var(--info,#60a5fa) 8%,rgba(255,255,255,.04));
  box-shadow:0 0 0 2px color-mix(in srgb,var(--info,#60a5fa) 72%,transparent),0 6px 18px -10px color-mix(in srgb,var(--info,#60a5fa) 60%,transparent);
}
[data-theme="light"] .mx5-dlg-cal-card.rr-active{background:color-mix(in srgb,var(--info,#60a5fa) 9%,rgba(0,0,0,.03));}
/* covered-date indicator — small radar dot chip (replaces the old "Release Radar ▸" text link) */
.mx5-dlg-cal-radar{display:inline-flex;align-items:center;gap:5px;margin-top:8px;
  font-size:10px;font-weight:700;letter-spacing:.02em;color:var(--ink-info, var(--info,#60a5fa));}
.mx5-dlg-cal-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0;
  background:var(--info,#60a5fa);position:relative;}
.mx5-dlg-cal-dot::after{content:"";position:absolute;inset:-3px;border-radius:50%;
  border:1px solid color-mix(in srgb,var(--info,#60a5fa) 55%,transparent);
  animation:rrDotPulse 2.4s ease-in-out infinite;}
@keyframes rrDotPulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.5);opacity:0}}
.mx5-dlg-cal-card.rr-active .mx5-dlg-cal-dot::after{animation:none;opacity:.9;transform:scale(1.15);}
