.mx5-dlg-cal-card.rr-fed{cursor:pointer;transition:border-color .16s ease,box-shadow .22s ease;}
.mx5-dlg-cal-card.rr-fed:hover{border-color:color-mix(in srgb,var(--link,#22d97a) 40%,transparent);}
.mx5-dlg-cal-card.rr-fed:hover .mx5-dlg-cal-fed{background:color-mix(in srgb,var(--link,#22d97a) 20%,transparent);border-color:color-mix(in srgb,var(--link,#22d97a) 50%,transparent);transform:translateX(1px);}
.mx5-dlg-cal-card.rr-fed:focus-visible{outline:2px solid var(--link,#22d97a);outline-offset:2px;}
