/* ── Inline Release Radar panel (#rr-inline, EVENTS dialog) ───────────────────
   Replaces the retired per-date popup + its open button. Shows the selected
   calendar date's model prints on the same surface; reuses the RR card renderer
   + #rr-modal for depth. Header carries the selected date + a covered radar dot;
   body cross-fades on date swap; one display-only footer. */
#rr-inline{margin-top:4px;}
.rr-inline-head{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:10px;}
