}
body.page-macro .mx5-intl-dot{
  width:6px;height:6px;border-radius:50%;flex-shrink:0;
  background:var(--ink-3,rgba(255,255,255,.36));
}
body.page-macro .mx5-intl-dot.intl-dot-alert{background:var(--down,#ef4444);}
body.page-macro .mx5-intl-name{flex:1;min-width:0;color:var(--ink-2,rgba(255,255,255,.62));}
body.page-macro .mx5-intl-score{
  font-size:11px;font-weight:700;font-variant-numeric:tabular-nums;
  color:var(--ink-3,rgba(255,255,255,.36));margin-left:auto;flex-shrink:0;
}
body.page-macro .mx5-intl-score.intl-score-alert{color:var(--ink-down, var(--down,#ef4444));}
/* Spread speed row */
body.page-macro .mx5-pop-intl-spread{
