  padding:6px 0;border-top:1px solid rgba(255,255,255,.06);margin-bottom:8px;
}
[data-theme="light"] body.page-macro .mx5-pop-intl-spread{border-color:rgba(0,0,0,.07);}
body.page-macro .mx5-pop-intl-small{
  display:block;font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.36));margin-top:3px;
}
/* Spillover board */
body.page-macro .mx5-pop-intl-spill{
  padding:6px 0;border-top:1px solid rgba(255,255,255,.06);margin-bottom:8px;
}
[data-theme="light"] body.page-macro .mx5-pop-intl-spill{border-color:rgba(0,0,0,.07);}
body.page-macro .mx5-pop-intl-spill-hd{
  display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;
  color:var(--ink-2,rgba(255,255,255,.62));margin-bottom:7px;
}
body.page-macro .mx5-pop-intl-spill-word{font-size:11.5px;font-weight:500;}
body.page-macro .mx5-pop-intl-spill-word.spill-alert{color:var(--ink-down, var(--down,#ef4444));}
body.page-macro .mx5-pop-intl-spill-word.spill-warn{color:var(--ink-warn, var(--warn,#f59e0b));}
body.page-macro .mx5-pop-intl-spill-word.spill-muted{color:var(--ink-3,rgba(255,255,255,.36));}
body.page-macro .mx5-pop-intl-legs{
  display:flex;flex-wrap:wrap;gap:5px;margin-bottom:5px;
}
body.page-macro .mx5-pop-intl-leg{
  display:inline-flex;align-items:center;gap:4px;
  padding:3px 7px;border-radius:20px;font-size:11px;
  background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);
  color:var(--ink-3,rgba(255,255,255,.36));
}
[data-theme="light"] body.page-macro .mx5-pop-intl-leg{
