  background:color-mix(in srgb,var(--warn,#f59e0b) 8%,transparent);
}
body.page-macro .mx5-leg-dot{
  width:5px;height:5px;border-radius:50%;flex-shrink:0;
  background:rgba(255,255,255,.24);
}
body.page-macro .mx5-leg-dot.leg-dot-hot{
  background:var(--warn,#f59e0b);
  box-shadow:0 0 4px var(--warn,#f59e0b);
}
body.page-macro .mx5-pop-intl-legcount{
  font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.36));margin-top:3px;
}
/* Fallback text row */
body.page-macro .mx5-pop-intl-fallback{
  font-size:12px;color:var(--ink-2,rgba(255,255,255,.62));margin-bottom:8px;
}
/* Footer */
body.page-macro .mx5-pop-intl-footer{
  font-size:10.5px;color:var(--ink-3,rgba(255,255,255,.36));
  border-top:1px solid rgba(255,255,255,.06);padding-top:6px;margin-top:4px;
  line-height:1.5;
}
[data-theme="light"] body.page-macro .mx5-pop-intl-footer{border-color:rgba(0,0,0,.07);}
body.page-macro .mx5-pop-intl-link{
  display:inline-block;margin-top:4px;font-size:11px;
  color:var(--isle-policy,#60a5fa);text-decoration:none;
}
body.page-macro .mx5-pop-intl-link:hover{text-decoration:underline;}
/* NOTE: the stocks market-state banner CSS (.stk-ctx-strip/.scx-*) is NOT here — this
   whole mx5-css style block is macro-only (its wrapping Jinja gate excludes stocks mode),
   so any body.page-stocks rule placed here never reaches us_stocks. That misplacement is
   exactly why the strip used to render as a bare blue hyperlink. It now lives in a
   stocks-emitted scx-css style block beside the banner markup below. */

/* ── WHAT TO DO (three-priority glance inside sx-evidence face) ───────── */
body.page-macro.mx4-grid #sx-evidence .mx5-card-title{margin-bottom:13px;}
body.page-macro.mx4-grid .mx5-action-list{display:flex;flex-direction:column;}
body.page-macro.mx4-grid .mx5-action-item{
  display:flex;align-items:center;gap:11px;
  padding:10px 0;margin:0;border-radius:0;
  border-bottom:1px solid rgba(255,255,255,.06);
  transition:transform .16s ease,background .2s ease;
}
body.page-macro.mx4-grid .mx5-action-item:last-child{border-bottom:none;}
[data-theme="light"] body.page-macro.mx4-grid .mx5-action-item{border-bottom-color:rgba(0,0,0,.06);}
body.page-macro.mx4-grid .mx5-action-item:hover{
  transform:translateX(2px);background:transparent;
}
body.page-macro.mx4-grid .mx5-action-icon{
  flex-shrink:0;width:30px;height:30px;border-radius:9px;
