}
body.page-macro.mx4-grid .mx5-action-icon svg{width:14px;height:14px;}
/* state-tinted glass icon containers (border tints to the state colour) */
body.page-macro.mx4-grid .mx5-ai-green{background:rgba(34,217,122,.10);border-color:rgba(34,217,122,.24);color:var(--ink-up, var(--up,#22d97a));}
/* zh 红涨绿跌: the icon TEXT flips via --up; the glass tint is literal — mirror it */
html[data-lang="zh"] body.page-macro.mx4-grid .mx5-ai-green{background:rgba(239,68,68,.10);border-color:rgba(239,68,68,.24);}
body.page-macro.mx4-grid .mx5-ai-yellow{background:rgba(245,158,11,.10);border-color:rgba(245,158,11,.24);color:var(--ink-warn, var(--warn,#f59e0b));}
body.page-macro.mx4-grid .mx5-ai-blue{background:rgba(129,140,248,.10);border-color:rgba(129,140,248,.26);color:#818cf8;}
body.page-macro.mx4-grid .mx5-ai-gray{background:rgba(255,255,255,.06);color:var(--ink-3,rgba(255,255,255,.5));}
[data-theme="light"] body.page-macro.mx4-grid .mx5-ai-gray{background:rgba(0,0,0,.04);}
@media(prefers-reduced-motion:reduce){
