body.page-macro.mx4-grid .mx5-timeline-rail{
  position:absolute;top:22px;left:6%;right:6%;height:2px;border-radius:2px;
  background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--isle-events,#e0a030) 30%,transparent) 12%,color-mix(in srgb,var(--isle-events,#e0a030) 30%,transparent) 88%,transparent);
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-timeline-rail{
  background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--isle-events,#e0a030) 45%,transparent) 12%,color-mix(in srgb,var(--isle-events,#e0a030) 45%,transparent) 88%,transparent);
}
body.page-macro.mx4-grid .mx5-tl-items{
  display:flex;justify-content:space-between;position:relative;gap:4px;
}
body.page-macro.mx4-grid .mx5-tl-item{
  display:flex;flex-direction:column;align-items:center;gap:4px;flex:1;min-width:0;
}
