body.page-macro.mx4-grid .mx5-tl-nodezone{
  height:22px;display:flex;align-items:center;justify-content:center;position:relative;z-index:1;
}
body.page-macro.mx4-grid .mx5-tl-dot{
  border-radius:50%;border:2px solid;flex-shrink:0;
}
body.page-macro.mx4-grid .mx5-dot-high{
  width:18px;height:18px;background:rgba(239,68,68,.24);border-color:#ef4444;
  box-shadow:0 0 10px rgba(239,68,68,.55);
}
body.page-macro.mx4-grid .mx5-dot-med{
  width:13px;height:13px;background:rgba(245,158,11,.22);border-color:#f59e0b;
  box-shadow:0 0 7px rgba(245,158,11,.4);
}
body.page-macro.mx4-grid .mx5-dot-low{
  width:9px;height:9px;background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.28);
}
[data-theme="light"] body.page-macro.mx4-grid .mx5-dot-low{background:rgba(0,0,0,.06);border-color:rgba(0,0,0,.22);}
body.page-macro.mx4-grid .mx5-tl-date{
  font-size:10.5px;font-weight:700;color:var(--ink-2,rgba(255,255,255,.62));
  text-align:center;font-variant-numeric:tabular-nums;margin-top:2px;
}
body.page-macro.mx4-grid .mx5-tl-name{
  font-size:10.5px;font-weight:600;color:var(--ink-3,rgba(255,255,255,.5));
