}
body.page-macro.mx4-grid .mx5-tl-badge{
  font-size:9px;font-weight:800;padding:1px 6px;border-radius:4px;
  letter-spacing:.05em;text-align:center;margin-top:1px;
}
body.page-macro.mx4-grid .mx5-tl-badge.high{color:var(--ink-act, var(--act));background:color-mix(in srgb, var(--act) 12%, transparent);}
body.page-macro.mx4-grid .mx5-tl-badge.med{color:var(--mx5-warn-ink);background:rgba(245,158,11,.12);}
body.page-macro.mx4-grid .mx5-tl-badge.low{color:var(--ink-3,rgba(255,255,255,.36));background:rgba(255,255,255,.05);}
/* staggered node entrance (reduced-motion snaps to final) */
@media(prefers-reduced-motion:no-preference){
  body.page-macro.mx4-grid .mx5-tl-item{opacity:0;transform:translateY(5px);
    animation:mx5TlIn .42s cubic-bezier(.22,.9,.26,1.02) forwards;}
  body.page-macro.mx4-grid .mx5-tl-item:nth-child(1){animation-delay:.04s;}
  body.page-macro.mx4-grid .mx5-tl-item:nth-child(2){animation-delay:.10s;}
  body.page-macro.mx4-grid .mx5-tl-item:nth-child(3){animation-delay:.16s;}
