/* Product typography: Inter first, Apple's San Francisco as the native fallback.
   Terminal mono is reserved for actual audit identifiers and byte coordinates. */
.earnings-wire h1,.earnings-wire h2,.earnings-wire h3{font-family:var(--ew-display)}
