/* Secure member continuation. The locked excerpts are absent from this HTML;
   this is the visible bridge to the edge-protected payload, not a CSS blur.

   `pending` is the pre-paint hold set by the inline boot script in
   earnings_wire_article.html.j2 — a session cookie is present, so the verdict is
   probably "unlocked" and the gate must not paint while we go and confirm it.
   earnings-wire.js clears the attribute the moment the answer arrives (and the boot
   script's own timer clears it if that script never runs), so this rule can only ever
   hide the gate for the length of one round trip. It is NOT an entitlement check:
   the locked excerpts are not in this document to begin with. */
html[data-earnings-member="pending"] .ewa-member-gate{display:none}
.ewa-member-gate{position:relative;margin:28px 0 8px;padding:28px 18px 18px;border:1px solid color-mix(in srgb,var(--ew-accent) 44%,var(--ew-rule));border-radius:18px;overflow:hidden;background:radial-gradient(85% 130% at 100% 0%,color-mix(in srgb,var(--ew-accent) 18%,transparent),transparent 60%),linear-gradient(145deg,color-mix(in srgb,var(--panel2) 76%,var(--panel)),var(--panel))}
.ewa-member-gate::before{content:"";position:absolute;inset:0 auto 0 0;width:3px;background:linear-gradient(180deg,var(--ew-accent),var(--ew-hot))}
.ewa-gate-ghosts{display:grid;gap:9px;opacity:.45;filter:blur(.2px)}
.ewa-gate-ghosts i{display:block;height:9px;border-radius:99px;background:linear-gradient(90deg,color-mix(in srgb,var(--ew-accent) 22%,var(--ew-rule)),transparent 88%)}
.ewa-gate-ghosts i:nth-child(2){width:82%}.ewa-gate-ghosts i:nth-child(3){width:64%}
.ewa-gate-card{position:relative;margin-top:-1px;padding:24px clamp(18px,4vw,34px) 18px;border:1px solid var(--ew-rule);border-radius:14px;background:color-mix(in srgb,var(--panel) 94%,transparent);box-shadow:0 22px 55px -38px color-mix(in srgb,var(--ew-accent) 75%,transparent)}
.ewa-gate-lock{display:grid;place-items:center;width:38px;height:38px;border:1px solid color-mix(in srgb,var(--ew-accent) 42%,var(--ew-rule));border-radius:10px;color:var(--ew-accent);background:color-mix(in srgb,var(--ew-accent) 9%,transparent)}
.ewa-gate-lock svg{width:19px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.ewa-gate-kicker{display:block;margin-top:18px;color:var(--ew-accent);font:750 10px var(--ew-ui);letter-spacing:.13em;text-transform:uppercase}
.ewa-gate-card h2{max-width:20ch;margin:7px 0 0;font-size:clamp(22px,3.2vw,32px);line-height:1.08;letter-spacing:-.035em}
.ewa-gate-card>p{max-width:61ch;margin:11px 0 0;color:var(--ink-2);font-size:13px;line-height:1.62}
.ewa-gate-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:20px}
.ewa-gate-actions a,.ewa-gate-actions a:visited{display:inline-flex;align-items:center;gap:14px;padding:11px 14px;border-radius:9px;background:var(--ew-accent);color:#07101f!important;font:750 12px var(--ew-ui)}
.ewa-gate-actions a:hover{color:#07101f!important;filter:brightness(1.06)}
.ewa-gate-actions button{border:0;background:transparent;padding:8px 2px;color:var(--ew-accent);font:700 12px var(--ew-ui);cursor:pointer}
.ewa-gate-actions button[hidden]{display:none}
.ewa-gate-proof{display:flex;align-items:center;gap:0;flex-wrap:wrap;margin-top:18px;padding-top:13px;border-top:1px solid var(--ew-rule)}
.ewa-gate-proof span{margin:4px 18px 4px 0;color:var(--ew-quiet);font-size:10px}.ewa-gate-proof b{margin-right:4px;color:var(--ink-1);font-size:12px;font-variant-numeric:tabular-nums}
