/* Weekly intelligence — a cross-call layer, visually related to the Wire but
   more editorial and spacious than the per-company evidence ledger. */
.ew-weekly-bridge{padding-block:20px;background:transparent}
.ew-weekly-bridge .ew-wrap{position:relative;display:grid;grid-template-columns:1fr minmax(280px,.72fr);gap:36px;align-items:center;overflow:hidden;padding:24px clamp(20px,3vw,32px);border:1px solid var(--ew-rule);border-radius:16px;background:color-mix(in srgb,var(--panel) 94%,var(--ew-accent) 6%)}
.ew-weekly-bridge .ew-wrap::before{content:"";position:absolute;inset:0 auto 0 0;width:3px;background:var(--ew-accent)}
.ew-weekly-bridge>div>div>span,.eww-section-head>div>span,.eww-side section>span,.eww-window>span{color:var(--ew-accent);font:750 10px var(--ew-ui);letter-spacing:.13em;text-transform:uppercase}
.ew-weekly-bridge h2{margin:5px 0 0;font-size:22px;letter-spacing:-.03em}.ew-weekly-bridge p{margin:7px 0 0;color:var(--ew-quiet);font-size:11px;font-variant-numeric:tabular-nums}
.ew-weekly-bridge a{display:grid;grid-template-columns:1fr auto;gap:3px 15px;align-items:end;padding:15px 17px;border:1px solid color-mix(in srgb,var(--ew-accent) 42%,var(--ew-rule));border-radius:12px;background:color-mix(in srgb,var(--panel) 78%,transparent);color:var(--ink-1)}
.ew-weekly-bridge a>span{grid-column:1/-1;color:var(--ew-quiet);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.ew-weekly-bridge a b{font-size:17px;text-transform:capitalize}.ew-weekly-bridge a i{color:var(--ew-accent);font-style:normal;font-size:18px}
.eww-hero{padding-top:34px;background:radial-gradient(75% 100% at 82% 0%,color-mix(in srgb,var(--ew-accent) 17%,transparent),transparent 68%);border-bottom:1px solid var(--ew-rule)}
.eww-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(250px,.55fr);gap:58px;align-items:end;padding-bottom:31px}.eww-grid h1{max-width:12ch;margin:17px 0 0;font-size:clamp(38px,5.8vw,68px);line-height:.96;letter-spacing:-.058em}.eww-grid>div>p{max-width:66ch;margin:19px 0 0;color:var(--ink-2);font-size:15px;line-height:1.66}
.eww-window{padding:18px;border:1px solid color-mix(in srgb,var(--ew-accent) 38%,var(--ew-rule));border-radius:14px;background:color-mix(in srgb,var(--panel) 80%,transparent)}.eww-window strong{display:block;margin-top:7px;font-size:17px;font-variant-numeric:tabular-nums}.eww-window p{margin:7px 0 0;color:var(--ew-quiet);font-size:11px}
.eww-stats{display:flex;align-items:center;flex-wrap:wrap;border-top:1px solid var(--ew-rule)}.eww-stats span{padding:13px 22px 13px 0;margin-right:22px;color:var(--ew-quiet);font-size:11px}.eww-stats b{margin-right:5px;color:var(--ink-1);font-size:14px;font-variant-numeric:tabular-nums}
.eww-body{display:grid;grid-template-columns:minmax(0,820px) 250px;justify-content:space-between;gap:64px;padding-block:48px 76px}.eww-section+.eww-section{margin-top:52px}.eww-section-head{display:flex;justify-content:space-between;gap:34px;align-items:end;padding-bottom:17px;border-bottom:1px solid var(--ew-rule)}.eww-section-head h2{margin:5px 0 0;font-size:25px;letter-spacing:-.035em}.eww-section-head p{max-width:42ch;margin:0;color:var(--ink-2);font-size:12px;line-height:1.55}
.eww-pulse-list{margin-top:10px}.eww-pulse-row{display:grid;grid-template-columns:minmax(150px,1fr) minmax(160px,1.2fr) 105px;gap:20px;align-items:center;padding:14px 0;border-bottom:1px solid color-mix(in srgb,var(--ew-rule) 68%,transparent)}.eww-pulse-row>div:first-child strong{display:block;text-transform:capitalize;font-size:13px}.eww-pulse-row>div:first-child span{display:block;margin-top:3px;color:var(--ew-quiet);font-size:10px}.eww-bar{height:6px;border-radius:999px;overflow:hidden;background:color-mix(in srgb,var(--ew-rule) 77%,transparent)}.eww-bar i{display:block;width:min(100%,var(--share));height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--ew-accent),var(--ew-hot))}.eww-delta{text-align:right;color:var(--ew-quiet);font-size:10px;font-variant-numeric:tabular-nums}.eww-delta.up{color:var(--ew-hot)}.eww-delta.down{color:var(--ew-warm)}
.eww-records{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-top:18px}.eww-record{display:flex;flex-direction:column;min-height:285px;padding:17px;border:1px solid var(--ew-rule);border-radius:14px;background:linear-gradient(145deg,color-mix(in srgb,var(--panel) 92%,var(--panel2)),var(--panel))}.eww-record-top{display:flex;justify-content:space-between;align-items:center}.eww-record-top span{font-size:17px;font-weight:800;letter-spacing:-.03em}.eww-record-top time{color:var(--ew-quiet);font-size:10px;font-variant-numeric:tabular-nums}.eww-record h3{margin:10px 0 0;font-size:16px;line-height:1.3;letter-spacing:-.02em}.eww-record h3 a{color:var(--ink-1)}.eww-record blockquote{margin:15px 0 auto;color:var(--ink-2);font-size:13px;line-height:1.55}.eww-record-foot{display:flex;justify-content:space-between;gap:12px;margin-top:17px;padding-top:11px;border-top:1px solid var(--ew-rule);color:var(--ew-quiet);font-size:10px}.eww-record-foot code{max-width:145px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:9px var(--num)}
.eww-side{align-self:start;position:sticky;top:82px}.eww-side section{padding:16px;border:1px solid var(--ew-rule);border-radius:12px;background:color-mix(in srgb,var(--panel2) 52%,var(--panel))}.eww-side section+section{margin-top:12px}.eww-side h2{margin:5px 0 12px;font-size:18px;letter-spacing:-.025em}.eww-side nav{display:grid}.eww-side nav a{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-top:1px solid color-mix(in srgb,var(--ew-rule) 66%,transparent);color:var(--ink-2);font-size:11px}.eww-side nav a[aria-current="page"]{color:var(--ew-accent)}.eww-side nav b{color:var(--ew-quiet);font-size:9px;font-weight:600}.eww-honesty p{margin:0;color:var(--ink-2);font-size:11px;line-height:1.58}.eww-honesty a{display:block;margin-top:13px;color:var(--ew-accent);font-size:11px;font-weight:700}
@media(max-width:900px){.ew-weekly-bridge .ew-wrap{grid-template-columns:1fr}.eww-grid{grid-template-columns:1fr;gap:22px}.eww-window{max-width:430px}.eww-body{grid-template-columns:1fr;gap:30px}.eww-side{position:static;display:grid;grid-template-columns:1fr 1fr;gap:12px}.eww-side section+section{margin-top:0}}
@media(max-width:580px){.eww-grid h1{max-width:100%;font-size:40px}.eww-stats span{padding-block:10px;margin-right:14px}.eww-section-head{display:block}.eww-section-head p{margin-top:10px}.eww-pulse-row{grid-template-columns:1fr 78px;gap:10px}.eww-bar{grid-column:1/-1;grid-row:2}.eww-records{grid-template-columns:1fr}.eww-side{grid-template-columns:1fr}}

