/* MastermindX Earnings Wire — exact-evidence public publication surface.
   The page inherits seo_base's public chrome. These rules only own the wire. */
.earnings-wire{--ew-accent:#7c9cff;--ew-hot:#8ce0be;--ew-warm:#f3c87a;--ew-quiet:color-mix(in srgb,var(--text) 52%,transparent);--ew-rule:color-mix(in srgb,var(--line) 78%,transparent);--ew-ui:Inter,-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display",sans-serif;--ew-display:Inter,-apple-system,BlinkMacSystemFont,"SF Pro Display",sans-serif;font-family:var(--ew-ui)}
.earnings-wire-index{--num:var(--ew-ui)}
html[data-theme="light"] .earnings-wire{--ew-accent:#174ec7;--ew-hot:#176a43;--ew-warm:#805100;--ew-quiet:#536174;--ew-rule:#d7dce5}
.earnings-wire .ew-wrap{width:min(1180px,calc(100% - 48px));margin-inline:auto}.earnings-wire .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.earnings-wire a{text-decoration:none}.earnings-wire a:hover{text-decoration:none}
.earnings-wire .ew-card[hidden]{display:none!important}
.earnings-wire .public-nav-cta,.earnings-wire .public-nav-cta:hover{color:#fff}
.ew-hero{padding:38px 0 0;overflow:hidden}.ew-hero .ew-wrap{padding:42px clamp(22px,4vw,58px) 0;border:1px solid var(--ew-rule);border-radius:var(--r-card,12px);background:radial-gradient(100% 125% at 100% 0%,var(--panel2),transparent 60%),linear-gradient(145deg,var(--panel2),var(--panel));position:relative}.ew-hero .ew-wrap::after{content:none;}.ew-kicker,.ewa-kicker{display:flex;align-items:center;gap:8px;font-family:var(--num);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--ew-accent)}.ew-pulse{width:7px;height:7px;background:var(--ew-hot);border-radius:var(--r-pill,999px);box-shadow:var(--card-shadow)}.ew-hero-grid{display:grid;grid-template-columns:minmax(0,1.34fr) minmax(238px,.66fr);gap:50px;align-items:end;margin-top:18px}.ew-hero h1{margin:0;font-size:clamp(34px,5vw,63px);max-width:12ch;line-height:.98;letter-spacing:-.052em;color:var(--ink-1)}.ew-dek{max-width:63ch;margin:22px 0 0;font-size:16px;line-height:1.65;color:var(--ink-2)}.ew-hero-proof{padding:18px 19px;border:1px solid var(--line);border-radius:var(--r-card,12px);background:var(--panel2)}.ew-proof-k,.ew-eyebrow,.ewa-rail-block>span,.ewa-intro>span,.ewa-disclosure>span{display:block;font-family:var(--num);font-size:10px;letter-spacing:.13em;text-transform:uppercase;color:var(--ew-accent)}.ew-hero-proof strong{display:block;margin-top:5px;font-size:15px;letter-spacing:-.01em}.ew-hero-proof p{margin:7px 0 0;font-size:12px;line-height:1.55;color:var(--ink-2)}.ew-ledger{display:flex;align-items:center;gap:0;flex-wrap:wrap;margin-top:38px;border-top:1px solid var(--ew-rule)}.ew-ledger>span,.ew-ledger>a{padding:13px 18px 13px 0;margin-right:18px;font-size:12px;color:var(--ew-quiet)}.ew-ledger b{margin-right:5px;color:var(--ink-1);font-size:13px}.ew-ledger>a{margin-left:auto;padding-right:0;color:var(--ew-accent);font-family:var(--num);font-weight:700}.ew-directory{padding:48px 0 74px}.ew-section-head{display:flex;justify-content:space-between;align-items:end;gap:36px;border-bottom:1px solid var(--ew-rule);padding-bottom:18px}.ew-section-head h2,.ew-protocol h2,.ewa-intro h2{font-size:24px;letter-spacing:-.025em;margin:5px 0 0;line-height:1.18}.ew-section-head p{max-width:47ch;margin:0;font-size:13px;line-height:1.55;color:var(--ink-2)}.ew-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:22px}.ew-search{flex:1 1 300px;position:relative}.ew-search::before{content:"⌕";position:absolute;top:50%;left:13px;transform:translateY(-53%);font-size:20px;color:var(--ew-quiet);pointer-events:none}.ew-search input{height:42px;width:100%;border:1px solid var(--ew-rule);border-radius:var(--r-card,12px);padding:0 13px 0 38px;background:var(--panel);color:var(--ink-1);font:500 13px var(--ew-ui);outline:none}.ew-search input:focus{border-color:var(--line);box-shadow:0 0 0 3px var(--ew-accent)}.ew-filter{height:40px;padding:0 11px;border:1px solid var(--ew-rule);border-radius:var(--r-pill,999px);background:transparent;color:var(--ink-2);font:600 12px var(--ew-ui);cursor:pointer}.ew-filter b{font-family:var(--ew-ui);font-weight:600;color:inherit}.ew-filter:hover,.ew-filter.active{border-color:var(--line);background:var(--panel2);color:var(--ink-1)}.ew-results{margin:13px 0 0;color:var(--ew-quiet);font-family:var(--ew-ui);font-size:11px}.ew-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:18px}.ew-card{min-height:286px;padding:17px;border:1px solid var(--ew-rule);border-radius:var(--r-card,12px);background:linear-gradient(145deg,var(--panel2),var(--panel));display:flex;flex-direction:column;transition:border-color .17s,transform .17s,box-shadow .17s}.ew-card:hover{transform:translateY(-3px);border-color:var(--line);box-shadow:var(--card-shadow)}.ew-card-top,.ew-card-foot{display:flex;justify-content:space-between;align-items:center;gap:10px}.ew-ticker{font:800 18px var(--ew-ui);font-variant-numeric:tabular-nums;letter-spacing:-.04em;color:var(--ink-1)}.ew-date,.ew-card-foot{font-size:10px;color:var(--ew-quiet)}.ew-card h3{margin:11px 0 0;font-size:17px;letter-spacing:-.016em;line-height:1.25}.ew-card h3 a{color:var(--ink-1)}.ew-card h3 a:hover{color:var(--ew-accent)}.ew-tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:10px}.ew-tags span{padding:3px 6px;border:1px solid var(--line);border-radius:var(--r-ctl,8px);color:var(--ew-accent);font:700 9px var(--ew-ui);letter-spacing:.045em;text-transform:uppercase}.ew-card blockquote{margin:15px 0 auto;padding:0;border:0;color:var(--ink-2);font-size:13px;line-height:1.53;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}.ew-card-foot{border-top:1px solid var(--ew-rule);margin-top:17px;padding-top:11px;font-family:var(--ew-ui);font-variant-numeric:tabular-nums}.ew-empty{padding:52px 16px;text-align:center;border:1px dashed var(--ew-rule);border-radius:var(--r-card,12px);margin-top:18px}.ew-empty strong{font-size:15px}.ew-empty p{margin:5px 0;color:var(--ew-quiet);font-size:13px}.ew-protocol{border-top:1px solid var(--ew-rule);border-bottom:1px solid var(--ew-rule);background:var(--panel2)}.ew-protocol-in{min-height:185px;display:grid;grid-template-columns:68px 1fr minmax(260px,.9fr);gap:24px;align-items:center}.ew-protocol-no{font-size:28px;color:var(--ew-accent)}.ew-protocol p{margin:0;color:var(--ink-2);font-size:13px;line-height:1.6}
/* Article */.ewa-head{padding:34px 0 0;background:radial-gradient(88% 110% at 88% 0%,var(--panel2),transparent 64%)}.ewa-crumb{display:flex;gap:8px;font:11px var(--num);color:var(--ew-quiet);margin-bottom:23px}.ewa-crumb a{color:var(--ew-quiet)}.ewa-crumb a:hover{color:var(--ew-accent)}.ewa-title-row{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-top:17px}.ewa-title-row h1{max-width:15ch;margin:0;font-size:clamp(31px,4.1vw,55px);line-height:1.02;letter-spacing:-.046em}.ewa-title-row h1 .mono{color:var(--ew-accent);font-size:.86em}.ewa-title-row p{max-width:66ch;margin:15px 0 0;color:var(--ink-2);font-size:15px;line-height:1.62}.ewa-dossier{min-width:182px;padding:13px 14px;border:1px solid var(--line);border-radius:var(--r-card,12px);background:var(--panel2);display:grid;grid-template-columns:1fr auto;gap:1px 9px;align-items:end;color:var(--ink-1)}.ewa-dossier span{grid-column:1/-1;font:10px var(--num);letter-spacing:.09em;text-transform:uppercase;color:var(--ew-quiet)}.ewa-dossier b{font:800 21px var(--num);letter-spacing:-.04em}.ewa-dossier i{font-style:normal;color:var(--ew-accent);font-size:17px}.ewa-dossier:hover{border-color:var(--ew-accent);transform:translateY(-1px)}.ewa-stats{display:flex;gap:0;flex-wrap:wrap;margin-top:31px;border-top:1px solid var(--ew-rule)}.ewa-stats span{padding:13px 21px 13px 0;margin-right:21px;font-size:12px;color:var(--ew-quiet)}.ewa-stats b{margin-right:5px;color:var(--ink-1);font-size:14px}.ewa-stats .ewa-stat-ok{color:var(--ew-hot);font-family:var(--num)}.ewa-correction{border-block:1px solid var(--line);background:var(--surface-warn-subtle,var(--panel2,var(--card)))}.ewa-correction .ew-wrap{display:flex;align-items:baseline;gap:11px;padding-block:11px;font-size:12px;line-height:1.5;color:var(--ink-2)}.ewa-correction b{color:var(--ew-warm);white-space:nowrap}.ewa-layout{display:grid;grid-template-columns:220px minmax(0,760px);justify-content:space-between;gap:70px;padding-block:46px}.ewa-rail{position:sticky;top:82px;align-self:start}.ewa-rail-block{padding:0 0 16px;margin-bottom:17px;border-bottom:1px solid var(--ew-rule)}.ewa-rail-block strong{display:block;margin-top:5px;font-size:12px;line-height:1.35}.ewa-rail-block p{margin:6px 0 0;color:var(--ew-quiet);font-size:11px;line-height:1.53}.ewa-terminal{display:flex;justify-content:space-between;gap:10px;padding:10px 0;color:var(--ew-accent);font:700 12px var(--num);border-bottom:1px solid var(--ew-rule)}.ewa-main{min-width:0}.ewa-intro{padding-bottom:22px;border-bottom:1px solid var(--ew-rule)}.ewa-intro p{max-width:63ch;margin:11px 0 0;color:var(--ink-2);font-size:14px;line-height:1.66}.ewa-facts{margin-top:18px}.ewa-fact{padding:23px 0;border-bottom:1px solid var(--ew-rule)}.ewa-fact-meta{display:flex;justify-content:space-between;align-items:start;gap:12px}.ewa-fact-meta>.mono{color:var(--ew-quiet);font-size:10px}.ewa-fact .ew-tags{margin-top:0}.ewa-fact blockquote{margin:14px 0 0;padding:0;border:0;color:var(--ink-1);font-size:18px;line-height:1.46;letter-spacing:-.013em}.ewa-attribution{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:12px;font-size:11px;color:var(--ew-quiet)}.ewa-attribution code,.ewa-numerics code,.ewa-receipts code{max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:10px var(--num);color:var(--ew-quiet)}.ewa-numerics{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:13px}.ewa-numerics>span{font:700 10px var(--num);letter-spacing:.07em;text-transform:uppercase;color:var(--ew-accent)}.ewa-numerics code{padding:4px 6px;border:1px solid var(--line);border-radius:var(--r-ctl,8px);color:var(--ew-accent)}.ewa-receipts{margin-top:27px;border:1px solid var(--ew-rule);border-radius:var(--r-card,12px);background:var(--panel2);overflow:hidden}.ewa-receipts summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;gap:12px;padding:15px 16px;font-weight:700;font-size:13px}.ewa-receipts summary::-webkit-details-marker{display:none}.ewa-receipts summary b{font:11px var(--num);color:var(--ew-quiet)}.ewa-receipts[open] summary{border-bottom:1px solid var(--ew-rule)}.ewa-receipt-note{padding:13px 16px 0;color:var(--ink-2);font-size:12px;line-height:1.55}.ewa-table-wrap{overflow:auto;padding:13px 16px 16px}.ewa-table-wrap table{width:100%;border-collapse:collapse;font-size:11px}.ewa-table-wrap th{padding:7px 8px;border-bottom:1px solid var(--ew-rule);font:700 9px var(--num);letter-spacing:.08em;text-transform:uppercase;text-align:left;color:var(--ew-quiet)}.ewa-table-wrap td{padding:9px 8px;border-bottom:1px solid var(--line);vertical-align:middle;color:var(--ink-2)}.ewa-table-wrap tr:last-child td{border-bottom:0}.ewa-disclosure{margin-top:25px;padding:16px 18px;border:1px solid var(--line);background:var(--surface-warn-subtle,var(--panel2,var(--card)))}.ewa-disclosure p{margin:7px 0 0;color:var(--ink-2);font-size:12px;line-height:1.62}
@media (max-width:900px){.earnings-wire .ew-wrap{width:min(100% - 32px,1180px)}.ew-hero .ew-wrap{padding:32px 23px 0}.ew-hero-grid{grid-template-columns:1fr;gap:20px}.ew-hero h1{max-width:15ch}.ew-hero-proof{max-width:430px}.ew-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ew-protocol-in{grid-template-columns:48px 1fr;gap:16px;padding-block:27px}.ew-protocol p{grid-column:2}.ewa-layout{grid-template-columns:1fr;gap:25px;padding-top:31px}.ewa-rail{position:static;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.ewa-rail-block{margin:0;padding:12px;border:1px solid var(--ew-rule);border-radius:9px}.ewa-terminal{align-items:center;border:1px solid var(--ew-rule);border-radius:9px;padding:12px}.ewa-title-row{align-items:start;flex-direction:column}.ewa-dossier{width:100%;max-width:390px}}
