rules.old:
/* ═══ tokens: layered on theme.css (dark default) — components inherit light/dark ═══ */
:root{--card:var(--panel);--grid:var(--line);--ink:#eef2f7;
  --faint:color-mix(in srgb,var(--muted) 72%,var(--bg));
  --amber:#fbbf24;--teal:#2dd4bf;--ch-a:#8b96f8;--ch-b:#2dd4bf;--ch-c:#fbbf24;
  --lift:#54c39a;--drag:#e58a97;--accent:var(--ch-b);
  /* ── the money-source pair (W1 decomposition) ────────────────────────────
     Two kinds of buying, so two marks. They are CATEGORY inks, not direction
     inks: investor money takes the market hue, and a manager's pick takes the
     page's own INK — a filing is signed by a person. Because neither is
     derived from --up/--down, neither flips under 中文 红涨绿跌, which is
     exactly right: "who was buying" is not a direction. */
  --flow:#8b96f8;
  --pick:color-mix(in srgb,var(--ink) 74%,var(--bg));
  /* glass surface tokens for the tier wall's floating card. special_situations
     defines these locally too — theme.css ships no --surface family, so pasting
     the wall CSS without them renders a transparent-but-working card, which is
     exactly the failure mode a review misses (W2 spec §B3.2). Dark first: this
     :root IS the dark default on this page. */
  --surface: color-mix(in srgb, var(--card) 80%, transparent);
  --surface-brd: color-mix(in srgb, var(--text) 13%, transparent);
  --surface-shadow: 0 20px 52px -22px rgba(3,7,18,.66), 0 6px 18px -10px rgba(3,7,18,.44),
                    inset 0 1px 0 color-mix(in srgb,#fff 7%,transparent)}
/* Light is a design target, not a token swap (Doctrine §5.8). theme.css hands
   this page #f7f8fa canvas against #ffffff panels — panel≈bg, the flatness bug —
   so the canvas is deepened HERE and the panels are lifted off it with a soft
   shadow and a crisper hairline, the reference light treatment. */
html[data-theme="light"]{--ink:#141b26;--faint:color-mix(in srgb,var(--muted) 82%,var(--bg));
  --amber:#b45309;--teal:#0f766e;--ch-a:#4559dc;--ch-b:#0f766e;--ch-c:#b45309;
  --lift:#2f9270;--drag:#c65b6e;
  --flow:#4559dc;
  --pick:color-mix(in srgb,var(--ink) 80%,transparent);
  --lift-shadow:0 1px 2px rgba(20,32,64,.05),0 10px 26px -18px rgba(20,32,64,.30);
  --surface: color-mix(in srgb, var(--card) 72%, transparent);
  --surface-brd: color-mix(in srgb, var(--ink) 12%, transparent);
  --surface-shadow: 0 14px 36px -20px rgba(20,32,64,.22), 0 4px 12px -6px rgba(20,32,64,.12),
                    inset 0 1px 0 rgba(255,255,255,.72)}
html[data-theme="light"] body{background:#e9ecf3}
/* The panel LIFT and the panel RAIL are both box-shadows, so light mode has to
   restate the rail or the second declaration silently deletes it — which is
   exactly what a "just add a shadow for light" patch does, and it renders as a
   page that quietly loses its accent system on white. Every railed surface
   carries its colour in --rail so one pair of rules covers all of them. */
.card{--rail:var(--accent)}.tile{--rail:var(--tc,var(--accent))}
.rrc{--rail:var(--rc,var(--accent))}.fc{--rail:var(--lift)}
.card,.tile,.rrc,.fc{box-shadow:inset 3px 0 0 var(--rail)}
html[data-theme="light"] .card,html[data-theme="light"] .tile,
html[data-theme="light"] .rrc,html[data-theme="light"] .fc{
  box-shadow:inset 3px 0 0 var(--rail),var(--lift-shadow)}
html[data-theme="light"] .shelf details{box-shadow:var(--lift-shadow)}
/* zh 红涨绿跌 (operator ruling): accumulate/trim are DIRECTION reads → swap. */
html[data-lang="zh"]{--lift:#e58a97;--drag:#54c39a}
html[data-theme="light"][data-lang="zh"]{--lift:#c65b6e;--drag:#2f9270}
*{box-sizing:border-box}
body{margin:0;padding:18px 0 0;background:var(--bg);color:var(--text);
  font-family:var(--font-ui),Inter,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:15px;line-height:1.5;-webkit-font-smoothing:antialiased}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px 64px}
a{color:var(--ink-link, var(--link));text-decoration:none}
.faint{color:var(--faint)}.muted{color:var(--muted)}
.pos{color:var(--lift)}.neg{color:var(--drag)}
/* ── the page's type scale ────────────────────────────────────────────────
   One eyebrow, one display size, one row voice, one micro voice. Figures are
   tabular everywhere; the MONO face is reserved for money, which keeps the two
   number classes audibly different — the bold pp is a row's headline, the mono
   dollar figure is its receipt (masterplan R2, one primary number per row). */
.eyebrow{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--muted)}
.ic-svg{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:1.7;
  stroke-linecap:round;stroke-linejoin:round;display:block}

/* ═══ hero ═══ */
.eh{padding:26px 0 6px;animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}
.eh-brand{display:flex;align-items:center;gap:11px;flex-wrap:wrap}
.eh-mark{display:inline-flex;width:30px;height:30px;border-radius:9px;flex:none;
  align-items:center;justify-content:center;font-size:19px;color:var(--ch-b);
  background:color-mix(in srgb,var(--ch-b) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--ch-b) 26%,transparent)}
.eh-brand h1{margin:0;font-size:25px;font-weight:800;letter-spacing:-.022em;color:var(--ink)}
.eh-brand .tag{font-size:13px;color:var(--muted);flex:1 1 220px;min-width:0}
.eh-verdict{font-size:clamp(21px,2.9vw,29px);font-weight:800;color:var(--ink);letter-spacing:-.022em;line-height:1.28;margin:18px 0 4px;max-width:940px;text-wrap:balance}
/* T5 stance line — the free build's Law-1 read, from rotation context only.
   Its highlight IS directional (risk-on / risk-off), so it rides --lift/--drag
   and flips correctly under 中文; the neutral case takes plain ink. */
.stance-line{font-size:16px;line-height:1.5;color:var(--ink);font-weight:600;margin:18px 0 4px;max-width:760px}
.stance-line .st.u{color:var(--lift)}.stance-line .st.d{color:var(--drag)}.stance-line .st.n{color:var(--ink)}
/* the as-of strip: the sanctioned self-labeling .dtp chip idiom (Doctrine §3).
   The state token IS its own label, there is exactly ONE as-of on the page, and
   the cycle dot takes a FIXED ink — a data-freshness mark must not ride
   --up/--down, which 中文 would flip. */
.eh-tape{margin-top:16px;border:1px solid var(--grid);border-radius:13px;
  background:color-mix(in srgb,var(--card) 62%,transparent)}
.eh-tape .dtp-dot{background:#1FA971}
.eh-tape .dtp-asof{display:inline-flex;align-items:center;gap:2px}
.eh-tape b{color:var(--ink);font-weight:800;font-variant-numeric:tabular-nums}
/* hero tiles */
.eh-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:16px}
@media(max-width:760px){.eh-tiles{grid-template-columns:1fr}}
.tile{position:relative;background:var(--card);border:1px solid var(--grid);border-radius:14px;padding:15px 17px;
  animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}
.tile:nth-child(2){animation-delay:.06s}.tile:nth-child(3){animation-delay:.12s}
.tile.t-lift{--tc:var(--lift)}.tile.t-drag{--tc:var(--drag)}.tile.t-accent{--tc:var(--ch-a)}.tile.t-neutral{--tc:var(--faint)}
/* the free build's honest-total tile: a count is not a direction, so it takes
   the brand link ink rather than an up/down one that 中文 would flip */
.tile.t-link{--tc:var(--link)}
.tile .tk{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--muted)}
/* a step below the verdict on purpose: the sentence is the page's thesis and
   the tiles support it, so they must not tie with it for first read */
.tile .tv{font-size:24px;font-weight:800;letter-spacing:-.025em;color:var(--ink);line-height:1.12;margin:6px 0 3px;font-variant-numeric:tabular-nums}
.tile .tm{font-size:12px;color:var(--faint);line-height:1.45}
.tile .tstance{margin-top:10px}

/* ═══ section chrome ═══ */
.sec{margin-top:40px}
.sec-head{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:0 0 4px}
.sec-head .sh-dot{width:7px;height:7px;border-radius:2px;background:var(--sc,var(--accent));flex:none}
.sec-head h2{margin:0;font-size:12.5px;font-weight:800;color:var(--ink);text-transform:uppercase;letter-spacing:.115em}
.sec-sub{font-size:13.5px;color:var(--muted);margin:0 0 16px;max-width:720px;line-height:1.5}
.card{background:var(--card);border:1px solid var(--grid);border-radius:16px;padding:18px 20px;position:relative;
  animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}

/* ═══ stance pill ═══ */
.stpill{display:inline-flex;align-items:center;gap:6px;padding:4px 11px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap;cursor:help;
  background:color-mix(in srgb,var(--sp,var(--muted)) 12%,var(--card));color:var(--sp,var(--muted));border:1px solid color-mix(in srgb,var(--sp,var(--muted)) 26%,var(--grid))}
.stpill .stdot{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.st-act{--sp:var(--lift)}.st-act .stdot,.st-ready .stdot{animation:txBreathe 2.4s ease-in-out infinite}
.st-ready{--sp:var(--teal)}.st-watch{--sp:var(--link)}.st-trim{--sp:var(--amber)}.st-aside{--sp:var(--faint)}.st-ignore{--sp:var(--faint)}

/* ═══ breadth constellation ═══ */
.bdots{display:inline-flex;align-items:center;gap:3px;line-height:1;cursor:help}
.bdots i{width:9px;height:9px;border-radius:50%;display:inline-block;flex:none}
.bdots i.up{background:var(--lift)}.bdots i.dn{background:var(--drag)}
.bdots i.sep{width:1px;height:12px;border-radius:0;background:var(--grid);margin:0 2px}
.bdots i.ov{width:auto;height:auto;border-radius:0;font-size:10px;font-weight:800;color:var(--lift);font-style:normal;margin-left:1px}

/* ═══ pressure bar ═══ */
.pbar{position:relative;display:block;height:7px;background:color-mix(in srgb,var(--grid) 42%,var(--card));border-radius:999px;width:100%;overflow:hidden}
.pb-mid{position:absolute;left:50%;top:0;bottom:0;width:1px;background:var(--muted);opacity:.72;z-index:1}
.pb-fill{position:absolute;top:0;bottom:0;border-radius:999px;animation:txGrow .8s cubic-bezier(.2,.7,.3,1) both}
.pb-fill.u{left:50%;transform-origin:left;background:linear-gradient(90deg,color-mix(in srgb,var(--lift) 22%,transparent),color-mix(in srgb,var(--lift) 62%,transparent))}
.pb-fill.d{right:50%;transform-origin:right;background:linear-gradient(270deg,color-mix(in srgb,var(--drag) 22%,transparent),color-mix(in srgb,var(--drag) 62%,transparent))}

/* ═══ the money-source marks (the page's signature) ═══════════════════════════
   One rail, two segments, sized by how many funds were on each side. It rides
   fund COUNTS rather than dollars on purpose: counts are this page's primary
   and least manipulable lens, they survive a sponsor that publishes no market
   values, and they cannot be misread as a second reading of the pp headline.
   1px gap + track border so the segments stay separate on white (Doctrine §5.8). */
.srail{display:inline-flex;width:32px;height:5px;border-radius:3px;overflow:hidden;flex:none;
  background:color-mix(in srgb,var(--grid) 62%,var(--card));
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--grid) 75%,transparent)}
.srail i{display:block;height:100%}
.sr-f{background:var(--flow);border-right:1px solid var(--card)}
.sr-s{flex:1;background:var(--pick)}
.sw{width:9px;height:9px;border-radius:2px;display:inline-block;margin-right:6px;flex:none;vertical-align:-1px}
.sw-f{background:var(--flow)}.sw-s{background:var(--pick)}
.src{display:inline-flex;align-items:center;gap:6px;font-size:10.5px;font-weight:700;white-space:nowrap}
.src-t{color:var(--faint)}
.sc-f .src-t{color:color-mix(in srgb,var(--flow) 62%,var(--muted))}
.sc-s .src-t{color:color-mix(in srgb,var(--ink) 55%,var(--muted))}
/* money: mono, quiet, never bold, never directional — the receipt voice */
.mny{font-family:var(--font-mono),ui-monospace,monospace;font-size:11px;font-weight:600;
  color:var(--muted);font-variant-numeric:tabular-nums;letter-spacing:-.015em;white-space:nowrap}
.mny .pl{font-style:normal;font-weight:800;color:var(--faint);cursor:help}
.mny.none{color:var(--faint)}
/* one persistence chip, outlined and quiet — a streak is context, not a call */
.prs{display:inline-block;padding:0 6px;border-radius:6px;font-size:10px;font-weight:700;
  color:var(--muted);border:1px solid var(--grid);white-space:nowrap}
/* the small-caps "active manager" mark: a person picks these holdings, so it
   takes the same ink the manager's-pick segment does */
.am{font-style:normal;font-size:9.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;
  color:color-mix(in srgb,var(--ink) 62%,var(--muted));cursor:help}

/* ═══ consensus board (signature) ═══ */
.cb-card{padding:0}
.cb-legend{display:flex;align-items:baseline;gap:7px 16px;flex-wrap:wrap;padding:12px 20px 11px;
  border-bottom:1px solid var(--grid);font-size:11.5px;color:var(--muted);line-height:1.45}
.cb-legend .lg-k{font-size:10.5px;font-weight:800;letter-spacing:.02em;color:var(--ink);white-space:nowrap}
.cb-legend .lg-t{flex:1 1 300px;min-width:0}
.cb-legend .lg-m{font-size:10.5px;color:var(--faint);white-space:nowrap}
.cb-head,.cb-row{display:grid;grid-template-columns:28px minmax(146px,1.3fr) 116px minmax(158px,1.15fr) 172px;gap:16px;align-items:center}
.cb-head{padding:9px 20px 8px;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--grid)}
.cb-head .r{text-align:right}
.cb-row{padding:12px 20px}
.cb-row+.cb-row{border-top:1px solid color-mix(in srgb,var(--grid) 55%,transparent)}
.cb-row:hover{background:color-mix(in srgb,var(--accent) 4%,transparent)}
.cb-rank{font-size:13px;font-weight:800;color:var(--faint);font-variant-numeric:tabular-nums;text-align:center}
.cb-row:nth-child(-n+6) .cb-rank{color:var(--accent)}
.stock-cell{display:flex;align-items:center;gap:9px;min-width:0}
.stock-cell .st-txt{min-width:0}
.stock-cell .st-txt b{display:block;font-size:14px;color:var(--ink);line-height:1.15;letter-spacing:-.005em}
.stock-cell .st-txt .nm{display:block;font-size:11.5px;color:var(--muted);line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}
.themetag{display:inline-block;margin-top:3px;padding:0 7px;border-radius:6px;font-size:10px;font-weight:700;letter-spacing:.01em;
  background:color-mix(in srgb,var(--muted) 13%,var(--card));color:var(--muted)}
.cb-breadth{display:flex;flex-direction:column;align-items:flex-start;gap:5px}
.cb-net{text-align:right;font-variant-numeric:tabular-nums}
.cb-net .v{font-size:15px;font-weight:800;letter-spacing:-.02em}
.cb-net .v.u{color:var(--lift)}.cb-net .v.d{color:var(--drag)}
.cb-pres{display:flex;flex-direction:column;gap:6px}
.cb-src{display:flex;align-items:center;gap:9px;flex-wrap:wrap;cursor:help}
.cb-flags{display:flex;gap:5px;flex-wrap:wrap}
.cb-flags:empty{display:none}
.mini{display:inline-block;padding:0 7px;border-radius:6px;font-size:10px;font-weight:800;letter-spacing:.02em;white-space:nowrap}
.mini.new{background:color-mix(in srgb,var(--lift) 16%,var(--card));color:var(--lift)}
.mini.exit{background:color-mix(in srgb,var(--drag) 15%,var(--card));color:var(--drag)}
/* disagreement is a FACT about the fund count, so it sits with the dots and is
   outlined rather than filled — it must not shout louder than the stance */
.mini.split{color:var(--ink-warn, var(--amber));border:1px solid color-mix(in srgb,var(--ink-warn, var(--amber)) 34%,var(--grid));font-weight:700}
.mini.old{color:var(--muted);border:1px solid var(--grid);font-weight:700;cursor:help}
.mini.contested{background:color-mix(in srgb,var(--amber) 16%,var(--card));color:var(--ink-warn, var(--amber))}
.mini.active{background:color-mix(in srgb,var(--ch-a) 15%,var(--card));color:var(--ch-a)}
/* the whose-conviction hover popover */
.cb-who{position:relative;display:inline-flex}
.cb-who .who-src{font-size:11px;color:var(--muted);cursor:help;border-bottom:1px dashed var(--grid)}
.cb-who .who-pop{display:none;position:absolute;left:0;top:20px;z-index:40;width:230px;padding:10px 12px;border-radius:11px;
  background:var(--card);border:1px solid var(--grid);box-shadow:0 14px 34px -14px rgba(9,17,40,.4);font-size:12px;line-height:1.5;color:var(--text)}
.cb-who:hover .who-pop{display:block}
.who-pop .wl{display:flex;justify-content:space-between;gap:10px;padding:2px 0}
.who-pop .wl b{color:var(--ink)}
.who-pop .wl .wv.u{color:var(--lift)}.who-pop .wl .wv.d{color:var(--drag)}
/* the size lens — below the ranking, never instead of it */
.cb-size{display:flex;align-items:center;gap:8px 14px;flex-wrap:wrap;padding:11px 20px 12px;
  border-top:1px solid var(--grid);background:color-mix(in srgb,var(--grid) 14%,transparent)}
.cb-size .cs-k{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--muted)}
.cb-size .cs-i{display:inline-flex;align-items:baseline;gap:6px;color:var(--text)}
.cb-size .cs-i b{font-size:12px;font-weight:800;color:var(--ink)}
.cb-size .cs-i:hover b{color:var(--link)}
.cb-size .cs-n{font-size:11px;color:var(--faint);cursor:help;border-bottom:1px dashed var(--grid);margin-left:auto}
@media(max-width:720px){
  .cb-head{display:none}
  .cb-row{grid-template-columns:26px 1fr auto;gap:11px;row-gap:9px;padding:13px 16px}
  .cb-legend,.cb-size{padding-left:16px;padding-right:16px}
  .cb-pres{grid-column:2/-1}
  .cb-stance-cell{grid-column:2/-1}
}

/* ═══ fresh conviction cards ═══ */
.fc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(238px,1fr));gap:14px}
.fc{position:relative;background:var(--card);border:1px solid var(--grid);border-radius:14px;padding:14px 16px;
  animation:txUp .5s cubic-bezier(.2,.7,.3,1) both}
.fc-top{display:flex;align-items:center;gap:9px}
.fc-top .st-txt{flex:1;min-width:0}
.fc-top .st-txt b{display:block;font-size:14.5px;color:var(--ink);line-height:1.1}
.fc-top .st-txt .nm{display:block;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:150px}
.fc-conv{flex:none;font-size:14px;font-weight:800;color:var(--lift);font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.fc-conv i{font-style:normal;font-size:10px;font-weight:700;color:var(--faint);margin-left:1px}
.fc-mid{font-size:11.5px;color:var(--muted);margin:11px 0 8px}
.fc-mid b{color:var(--ink);font-weight:800}
.fc-funds{display:flex;flex-wrap:wrap;gap:4px}
.fchip{padding:1px 7px;border-radius:6px;font-size:10.5px;font-weight:700;background:color-mix(in srgb,var(--muted) 13%,var(--card));color:var(--muted)}
/* an ACTIVE manager's chip takes the manager's-pick ink: a person chose it */
.fchip.act{background:color-mix(in srgb,var(--ink) 15%,var(--card));color:var(--ink);cursor:help}
.fchip.more{background:transparent;border:1px solid var(--grid);color:var(--faint)}
.fc-foot{margin-top:12px;padding-top:11px;border-top:1px solid color-mix(in srgb,var(--grid) 60%,transparent)}

/* ═══ rotation rail (market backdrop) ═══ */
.rr{display:grid;grid-template-columns:1.05fr 1.25fr 1.05fr;gap:16px;align-items:start}
@media(max-width:900px){.rr{grid-template-columns:1fr}}
.rrc{position:relative;background:var(--card);border:1px solid var(--grid);border-radius:16px;padding:17px 19px;
  animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}
.rrc:nth-child(2){animation-delay:.06s}.rrc:nth-child(3){animation-delay:.12s}
.rrc.c-risk{--rc:var(--ch-a)}.rrc.c-sect{--rc:var(--ch-b)}.rrc.c-style{--rc:var(--ch-c)}
.rrc .rr-eyebrow{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--rc,var(--accent))}
.rrc .rr-state{font-size:23px;font-weight:800;letter-spacing:-.025em;color:var(--ink);line-height:1.1;margin:9px 0 3px}
.rrc .rr-sub{font-size:14px;font-weight:700;letter-spacing:-.01em;color:var(--ink);margin:9px 0 3px;display:flex;align-items:center}
.rrc .rr-read{font-size:12px;color:var(--muted);line-height:1.45}
.rr-legs{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
.leg{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:8px;font-size:11px;font-weight:600;background:color-mix(in srgb,var(--grid) 45%,var(--card));color:var(--text)}
.leg .ar{font-size:9px}.leg.u{color:var(--lift)}.leg.d{color:var(--drag)}
/* sector ladder */
.slad{display:flex;flex-direction:column;gap:7px;margin-top:11px}
.slad .sl{display:grid;grid-template-columns:18px 74px 1fr auto;gap:9px;align-items:center;font-size:12px}
.slad .sl .rk{font-size:10px;font-weight:800;color:var(--faint);text-align:center;font-variant-numeric:tabular-nums}
.slad .sl .nm{font-weight:700;color:var(--ink)}
.slad .sl .track{position:relative;height:6px;border-radius:999px;background:color-mix(in srgb,var(--grid) 55%,var(--card))}
.slad .sl .track i{position:absolute;left:50%;top:0;bottom:0;border-radius:999px;animation:txGrow .7s ease both}
.slad .sl .track i.u{transform-origin:left;background:color-mix(in srgb,var(--lift) 55%,transparent)}
.slad .sl .track i.d{right:50%;left:auto;transform-origin:right;background:color-mix(in srgb,var(--drag) 55%,transparent)}
.slad .sl .mv{font-size:11px;font-weight:700;font-variant-numeric:tabular-nums;text-align:right;min-width:44px}
.slad .sl .mv.u{color:var(--lift)}.slad .sl .mv.d{color:var(--drag)}
/* style tug-of-war */
.tug{display:flex;flex-direction:column;gap:11px;margin-top:8px}
.tug .tw{font-size:12px}
.tug .tw .lab{display:flex;justify-content:space-between;gap:8px;margin-bottom:4px}
.tug .tw .lab .nm{font-weight:700;color:var(--ink)}
.tug .tw .lab .ld{font-size:11px;font-weight:700;color:var(--ch-c)}
.tug .tw .bar{position:relative;height:7px;border-radius:999px;background:color-mix(in srgb,var(--grid) 55%,var(--card))}
.tug .tw .bar .mid{position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--faint);opacity:.4}
.tug .tw .bar i{position:absolute;left:50%;top:0;bottom:0;border-radius:999px;animation:txGrow .7s ease both;
  background:color-mix(in srgb,var(--ch-c) 48%,transparent)}
.tug .tw .bar i.u{transform-origin:left}
.tug .tw .bar i.d{right:50%;left:auto;transform-origin:right}

/* ═══ accumulation table ═══ */
.atbl-card{padding:6px 14px}
.atbl{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}
.atbl th{text-align:left;padding:10px 10px 9px;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--grid)}
.atbl td{padding:11px 10px;border-bottom:1px solid color-mix(in srgb,var(--grid) 55%,transparent);vertical-align:middle}
.atbl tr:last-child td{border-bottom:none}
.atbl tbody tr:hover{background:color-mix(in srgb,var(--accent) 4%,transparent)}
.atbl th.r,.atbl td.r{text-align:right}
.atbl .conv{font-weight:800;font-size:14px;letter-spacing:-.02em}
.atbl .conv i{font-style:normal;font-size:10px;font-weight:700;color:var(--faint);margin-left:1px}
.atbl .conv.u{color:var(--lift)}.atbl .conv.d{color:var(--drag)}
.atbl .tsz{display:flex;align-items:center;justify-content:flex-end;gap:9px;margin-top:4px}
.fundcell b{color:var(--ink)}
.atbl-wrap{overflow-x:auto}
@media(max-width:640px){.atbl .hide-sm{display:none}}

/* ═══ shelf (trims / the fleet) ═══ */
.shelf details{background:var(--card);border:1px solid var(--grid);border-radius:15px;margin-bottom:12px}
.shelf summary{list-style:none;cursor:pointer;padding:14px 20px;display:flex;align-items:center;gap:11px;font-size:14px;font-weight:700;color:var(--ink);transition:background .18s;border-radius:15px}
.shelf summary::-webkit-details-marker{display:none}
.shelf summary:hover{background:color-mix(in srgb,var(--accent) 5%,var(--card))}
.shelf summary .sh-ic{flex:none;width:26px;height:26px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:15px;
  color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--card))}
.shelf summary .sh-sub{font-weight:500;color:var(--muted);font-size:12.5px}
.shelf summary .sh-caret{margin-left:auto;flex:none;font-size:11px;color:var(--faint);transition:transform .25s}
.shelf details[open] summary{border-radius:15px 15px 0 0}
.shelf details[open] summary .sh-caret{transform:rotate(90deg)}
.shelf .sh-body{padding:4px 20px 20px;border-top:1px solid var(--grid)}
.fdot{display:inline-block;width:8px;height:8px;border-radius:50%;vertical-align:middle;flex:none}
/* Freshness is a DATA-QUALITY status, not a market direction. It must NOT ride
   --lift/--drag: those flip under html[data-lang="zh"] (红涨绿跌), which painted
   "fresh" red and "stale" green in the first ZH render of the W2 mockup. Fixed
   semantic inks, identical in both languages. Same rule for any pass/fail tint. */
.fdot.fresh{background:#1FA971}.fdot.aging{background:#f0b429}.fdot.stale{background:#e06464}
.fdot.none{background:var(--muted)}

/* ═══ the fleet directory ═══════════════════════════════════════════════════
   Was a 105-row, six-column table: a spreadsheet, not a directory, and 58 KiB
   of the free shell's weight on its own (R3). It is now a grouped directory —
   and the grouping is the point: the three groups ARE the flow-vs-selection
   rule, so a reader who never pays still learns why an active manager's move
   and a theme fund's move mean different things. Everything constant (what the
   dots mean, what the small number is) is stated once in the legend, never per
   row (Doctrine Law 4). */
/* the fleet shelf is data quality, not distribution: it takes the page accent,
   not the trims shelf's --drag. Keyed on the summary rather than on the
   <details> so the element stays a bare `<details open>` — the tier suite pins
   that literal, because a coverage directory that ships collapsed may never be
   crawled (T-B3). */
.fl-sum .sh-ic{color:var(--ch-b);background:color-mix(in srgb,var(--ch-b) 10%,var(--card))}
.fl-sum:hover{background:color-mix(in srgb,var(--ch-b) 5%,var(--card))}
.fl-stats{display:flex;align-items:center;gap:8px 10px;flex-wrap:wrap;margin:14px 0 4px}
.fl-s{display:inline-flex;align-items:baseline;gap:6px;padding:5px 11px;border-radius:999px;
  border:1px solid var(--grid);background:color-mix(in srgb,var(--grid) 16%,transparent);
  font-size:11.5px;color:var(--muted)}
.fl-s b{font-size:14px;font-weight:800;color:var(--ink);font-variant-numeric:tabular-nums}
.fl-lg{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--faint);margin-left:auto}
.fl-lg .fdot{margin-left:7px}
.fl-lg .fdot:first-child{margin-left:0}
.fl-g{margin-top:18px}
.fl-gh{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;padding-bottom:7px;border-bottom:1px solid var(--grid)}
.fl-gn{font-size:10.5px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--ink)}
.fl-gc{font-size:10.5px;font-weight:800;color:var(--ch-b);font-variant-numeric:tabular-nums}
.fl-gr{font-size:11.5px;color:var(--muted)}
.fl-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(232px,1fr));gap:1px 18px;margin-top:8px}
.fu{display:flex;align-items:center;gap:7px;padding:4px 0;font-size:12px;min-width:0;line-height:1.35}
/* The row's freshness dot is a ::before rather than a .fdot element: at 105
   funds that markup was 3 KiB of the free shell on its own. It carries the SAME
   fixed inks as the legend's .fdot swatches — never --lift/--drag, which 中文
   flips — and tests/test_etfs_gate pins the two sets to identical values so the
   pair cannot drift. */
.fu::before{content:'';width:8px;height:8px;border-radius:50%;flex:none;background:var(--muted)}
.fu.s1::before{background:#1FA971}.fu.s2::before{background:#f0b429}.fu.s3::before{background:#e06464}
.fu b{font-weight:800;color:var(--ink);flex:none;font-size:11.5px;letter-spacing:.01em}
.fu span{flex:1;min-width:0;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fu i{font-style:normal;font-size:10.5px;color:var(--faint);font-variant-numeric:tabular-nums;flex:none}
.fu u{text-decoration:none;font-size:9.5px;font-weight:700;color:var(--faint);
  border:1px solid var(--grid);border-radius:5px;padding:0 4px;flex:none}
/* holdings date wraps under the chip: .fu itself does not wrap */
.fu{flex-wrap:wrap}
.fu time{display:block;flex-basis:100%;min-width:0;color:var(--muted)}
.fl-foot{margin-top:16px;font-size:11.5px;color:var(--faint);line-height:1.55}

/* ═══ disclosure ═══ */
.disc{font-size:12px;color:var(--muted);margin:32px 0 0;padding-top:16px;border-top:1px solid var(--grid);line-height:1.6}
.disc b{color:var(--ink)}

/* ═══ tk logo ═══ */
.tk-logo{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:6px;overflow:hidden;flex:0 0 26px;
  background:transparent}
.tk-logo img{width:26px;height:26px;object-fit:contain;display:block}
/* Fallback for a ticker with no CDN icon (the .png 404s → onerror swaps this in).
   At 9px the 4-character ticker overran the 26px tile and the parent's
   overflow:hidden sheared it on BOTH sides; size the type to the tile instead.
   It reads as a monogram plate rather than a failed image. */
.tk-fb{font-size:8.5px;font-weight:800;letter-spacing:-.04em;line-height:1;white-space:nowrap;
  color:var(--muted);align-items:center;justify-content:center;width:26px;height:26px;
  border:1px solid var(--grid);border-radius:6px;background:color-mix(in srgb,var(--grid) 22%,transparent)}
.spark{display:inline-block;vertical-align:middle}

/* ═══ ? tip ═══ */
.txq{position:relative;display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:50%;
  border:1px solid var(--grid);color:var(--muted);font-size:10px;font-weight:700;cursor:help;flex:none;margin-left:5px;vertical-align:middle}
.txq .txq-tip{display:none;position:absolute;top:22px;left:-8px;z-index:50;width:294px;padding:11px 13px;border-radius:11px;
  background:var(--card);border:1px solid var(--grid);box-shadow:0 14px 34px -14px rgba(9,17,40,.42);
  font-size:12px;font-weight:500;color:var(--text);line-height:1.55;text-transform:none;letter-spacing:0;text-align:left}
.txq:hover .txq-tip,.txq:focus .txq-tip{display:block}
.txq:focus-visible{outline:2px solid var(--link);outline-offset:2px}
@media(max-width:520px){.txq .txq-tip{left:auto;right:-8px;width:min(290px,84vw)}}

/* ═══ tier gate (SEO Supercharge W2 — docs/TIER_PREVIEW_PATTERN.md) ═══
   Transliterated from the shipped special_situations idiom into THIS page's
   token vocabulary: --card / --grid are already aliased above, --blue becomes
   --link, and the --surface family is defined in :root. #8b5cf6 (the lock
   violet) stays a hard-coded hex, identical to the reference. The CTA gradient
   is brand blue → violet, NEVER signal amber (terminal paywall lesson).
   None of these elements carries directional colour: a gate is not a market
   read, so the 红涨绿跌 flip must not touch it. */
.gate-pill{margin-left:2px;padding:2px 8px;border-radius:999px;font-size:9.5px;font-weight:800;letter-spacing:.08em;
  color:#8b5cf6;background:color-mix(in srgb,#8b5cf6 13%,transparent);
  border:1px solid color-mix(in srgb,#8b5cf6 34%,transparent);text-transform:none}
@keyframes ghPulse{0%,100%{opacity:.45}50%{opacity:.85}}
.gh{border-radius:6px;background:linear-gradient(90deg,var(--grid),color-mix(in srgb,var(--grid) 45%,transparent));
  animation:ghPulse 2.4s ease-in-out infinite}
/* consensus-board skeletons — the walled board's shape, none of its content */
.cb-ghosts{border:1px solid var(--grid);border-radius:14px;overflow:hidden;background:var(--card)}
.cbg-hd,.cbg-row{display:grid;grid-template-columns:34px 1.7fr 1fr 1.5fr 1.05fr;gap:14px;align-items:center}
.cbg-hd{padding:10px 16px;border-bottom:1px solid var(--grid);font-size:9.5px;font-weight:800;letter-spacing:.09em;
  text-transform:uppercase;color:var(--faint)}
.cbg-row{padding:13px 16px;border-bottom:1px solid color-mix(in srgb,var(--text) 6%,transparent)}
.cbg-row:last-child{border-bottom:0}
.gh-rank{width:15px;height:12px}
.gh-tkr{width:48px;height:12px;margin-bottom:6px}
.gh-nm{width:78%;height:9px}
.gh-dots{width:66px;height:10px}
.gh-bar{width:100%;height:9px}
.gh-pill{width:96px;height:20px;border-radius:999px}
@media(max-width:720px){.cbg-hd{display:none}.cbg-row{grid-template-columns:26px 1fr;row-gap:9px}}
/* gate note — it EXPLAINS, it never sells. No CTA button lives here. */
.gate-note{display:flex;align-items:flex-start;gap:8px;margin:0 0 14px;padding:11px 14px;border-radius:12px;
  font-size:12.5px;line-height:1.5;color:var(--muted);
  background:color-mix(in srgb,#8b5cf6 7%,transparent);border:1px solid color-mix(in srgb,#8b5cf6 22%,transparent)}
.gate-note svg{width:14px;height:14px;flex:none;margin-top:2px;color:#8b5cf6}
.gate-note a{color:var(--ink-link, var(--link))}
/* the page's ONE tier wall, at "Every add, by fund" — after the free backdrop */
.tier-wall{position:relative;margin:6px 0 4px;isolation:isolate}
.tw-ghosts{display:flex;flex-direction:column;gap:10px;padding-top:4px}
.tw-ghost{border:1px solid var(--grid);border-radius:14px;background:color-mix(in srgb,var(--card) 55%,transparent);
  padding:18px 20px}
.tw-ghost .gh-tkr{width:64px;height:14px;margin-bottom:11px}
.tw-ghost .gh-line{width:70%;height:10px;margin-bottom:8px}
.tw-ghost .gh-line.short{width:38%;margin-bottom:0}
.tw-card{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(560px,94%);text-align:center;
  padding:30px 30px 26px;border-radius:20px;background:var(--surface);border:1px solid var(--surface-brd);
  box-shadow:var(--surface-shadow);-webkit-backdrop-filter:saturate(180%) blur(22px);backdrop-filter:saturate(180%) blur(22px)}
.tw-lock{width:28px;height:28px;color:#8b5cf6;margin-bottom:12px}
.tw-h{font-size:19px;font-weight:800;letter-spacing:-.02em;color:var(--ink);line-height:1.25;margin-bottom:9px}
.tw-p{font-size:13px;line-height:1.6;color:var(--muted);max-width:450px;margin:0 auto 18px}
.tw-acts{display:flex;flex-direction:column;align-items:center;gap:8px}
.tw-btn{display:inline-flex;align-items:center;justify-content:center;padding:11px 26px;border-radius:12px;
  text-decoration:none;font-size:13.5px;font-weight:700;color:#fff;
  background:linear-gradient(135deg,var(--link),#8b5cf6);
  box-shadow:0 8px 22px -10px color-mix(in srgb,#8b5cf6 70%,transparent);transition:transform .18s,box-shadow .18s}
.tw-btn:hover{transform:translateY(-1px);box-shadow:0 12px 28px -10px color-mix(in srgb,#8b5cf6 80%,transparent)}
.tw-note{font-size:11px;color:var(--faint)}
.tw-signed{margin-top:12px;font-size:12px}
.tw-signed a{color:var(--ink-link, var(--link));text-decoration:none;border-bottom:1px solid color-mix(in srgb,var(--link) 40%,transparent)}
@media(max-width:900px){
  /* Below the ghost stack's usable width the absolute card overlaps the lede
     above it; drop the ghosts and let the card flow. */
  .tw-ghosts{display:none}
  .tw-card{position:static;transform:none;width:100%;padding:26px 20px 22px}
}

/* ═══ motion ═══ */
@keyframes txUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes txBreathe{0%,100%{opacity:.5;transform:scale(.82)}50%{opacity:1;transform:scale(1.12)}}
@keyframes txGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@media (prefers-reduced-motion:reduce){
  .eh,.tile,.card,.rrc,.fc{animation:none}
  .pb-fill,.slad .sl .track i,.tug .tw .bar i,.stdot{animation:none}
  /* the as-of strip's cycle dot pulses from theme.css's own keyframe — kill it
     by name here too, the wildcard below only covers transitions */
  .eh-tape .dtp-dot{animation:none}
  /* the tier gate's skeleton shimmer is decorative — kill it by name, not by
     hoping the wildcard below covers animations (it only covers transitions) */
  .gh{animation:none}
  .tw-btn{transition:none}
  *{transition:none!important}
}

rules.new:
/* ═══ tokens: layered on theme.css (dark default) — components inherit light/dark ═══ */
:root{--card:var(--panel);--grid:var(--line);--ink:#eef2f7;
  --faint:color-mix(in srgb,var(--muted) 72%,var(--bg));
  --amber:#fbbf24;--teal:#2dd4bf;--ch-a:#8b96f8;--ch-b:#2dd4bf;--ch-c:#fbbf24;
  --lift:#54c39a;--drag:#e58a97;--accent:var(--ch-b);
  /* ── the money-source pair (W1 decomposition) ────────────────────────────
     Two kinds of buying, so two marks. They are CATEGORY inks, not direction
     inks: investor money takes the market hue, and a manager's pick takes the
     page's own INK — a filing is signed by a person. Because neither is
     derived from --up/--down, neither flips under 中文 红涨绿跌, which is
     exactly right: "who was buying" is not a direction. */
  --flow:#8b96f8;
  --pick:color-mix(in srgb,var(--ink) 74%,var(--bg));
  /* glass surface tokens for the tier wall's floating card. special_situations
     defines these locally too — theme.css ships no --surface family, so pasting
     the wall CSS without them renders a transparent-but-working card, which is
     exactly the failure mode a review misses (W2 spec §B3.2). Dark first: this
     :root IS the dark default on this page. */
  --surface: color-mix(in srgb, var(--card) 80%, transparent);
  --surface-brd: color-mix(in srgb, var(--text) 13%, transparent);
  --surface-shadow: 0 20px 52px -22px rgba(3,7,18,.66), 0 6px 18px -10px rgba(3,7,18,.44),
                    inset 0 1px 0 color-mix(in srgb,#fff 7%,transparent)}
/* Light is a design target, not a token swap (Doctrine §5.8). theme.css hands
   this page #f7f8fa canvas against #ffffff panels — panel≈bg, the flatness bug —
   so the canvas is deepened HERE and the panels are lifted off it with a soft
   shadow and a crisper hairline, the reference light treatment. */
html[data-theme="light"]{--ink:#141b26;--faint:color-mix(in srgb,var(--muted) 82%,var(--bg));
  --amber:#b45309;--teal:#0f766e;--ch-a:#4559dc;--ch-b:#0f766e;--ch-c:#b45309;
  --lift:#2f9270;--drag:#c65b6e;
  --flow:#4559dc;
  --pick:color-mix(in srgb,var(--ink) 80%,transparent);
  --lift-shadow:0 1px 2px rgba(20,32,64,.05),0 10px 26px -18px rgba(20,32,64,.30);
  --surface: color-mix(in srgb, var(--card) 72%, transparent);
  --surface-brd: color-mix(in srgb, var(--ink) 12%, transparent);
  --surface-shadow: 0 14px 36px -20px rgba(20,32,64,.22), 0 4px 12px -6px rgba(20,32,64,.12),
                    inset 0 1px 0 rgba(255,255,255,.72)}
html[data-theme="light"] body{background:#e9ecf3}
/* The panel LIFT and the panel RAIL are both box-shadows, so light mode has to
   restate the rail or the second declaration silently deletes it — which is
   exactly what a "just add a shadow for light" patch does, and it renders as a
   page that quietly loses its accent system on white. Every railed surface
   carries its colour in --rail so one pair of rules covers all of them. */
.card{--rail:var(--accent)}.tile{--rail:var(--tc,var(--accent))}
.rrc{--rail:var(--rc,var(--accent))}.fc{--rail:var(--lift)}
.card,.tile,.rrc,.fc{box-shadow:none}
html[data-theme="light"] .card,html[data-theme="light"] .tile,
html[data-theme="light"] .rrc,html[data-theme="light"] .fc{
  box-shadow:var(--lift-shadow)}
html[data-theme="light"] .shelf details{box-shadow:var(--lift-shadow)}
/* zh 红涨绿跌 (operator ruling): accumulate/trim are DIRECTION reads → swap. */
html[data-lang="zh"]{--lift:#e58a97;--drag:#54c39a}
html[data-theme="light"][data-lang="zh"]{--lift:#c65b6e;--drag:#2f9270}
*{box-sizing:border-box}
body{margin:0;padding:18px 0 0;background:var(--bg);color:var(--text);
  font-family:var(--font-ui),Inter,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:15px;line-height:1.5;-webkit-font-smoothing:antialiased}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px 64px}
a{color:var(--ink-link, var(--link));text-decoration:none}
.faint{color:var(--faint)}.muted{color:var(--muted)}
.pos{color:var(--lift)}.neg{color:var(--drag)}
/* ── the page's type scale ────────────────────────────────────────────────
   One eyebrow, one display size, one row voice, one micro voice. Figures are
   tabular everywhere; the MONO face is reserved for money, which keeps the two
   number classes audibly different — the bold pp is a row's headline, the mono
   dollar figure is its receipt (masterplan R2, one primary number per row). */
.eyebrow{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--muted)}
.ic-svg{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:1.7;
  stroke-linecap:round;stroke-linejoin:round;display:block}

/* ═══ hero ═══ */
.eh{padding:26px 0 6px;animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}
.eh-brand{display:flex;align-items:center;gap:11px;flex-wrap:wrap}
.eh-mark{display:inline-flex;width:30px;height:30px;border-radius:9px;flex:none;
  align-items:center;justify-content:center;font-size:19px;color:var(--ch-b);
  background:color-mix(in srgb,var(--ch-b) 12%,transparent);
  border:1px solid color-mix(in srgb,var(--ch-b) 26%,transparent)}
.eh-brand h1{margin:0;font-size:25px;font-weight:800;letter-spacing:-.022em;color:var(--ink)}
.eh-brand .tag{font-size:13px;color:var(--muted);flex:1 1 220px;min-width:0}
.eh-verdict{font-size:clamp(21px,2.9vw,29px);font-weight:800;color:var(--ink);letter-spacing:-.022em;line-height:1.28;margin:18px 0 4px;max-width:940px;text-wrap:balance}
/* T5 stance line — the free build's Law-1 read, from rotation context only.
   Its highlight IS directional (risk-on / risk-off), so it rides --lift/--drag
   and flips correctly under 中文; the neutral case takes plain ink. */
.stance-line{font-size:16px;line-height:1.5;color:var(--ink);font-weight:600;margin:18px 0 4px;max-width:760px}
.stance-line .st.u{color:var(--lift)}.stance-line .st.d{color:var(--drag)}.stance-line .st.n{color:var(--ink)}
/* the as-of strip: the sanctioned self-labeling .dtp chip idiom (Doctrine §3).
   The state token IS its own label, there is exactly ONE as-of on the page, and
   the cycle dot takes a FIXED ink — a data-freshness mark must not ride
   --up/--down, which 中文 would flip. */
.eh-tape{margin-top:16px;border:1px solid var(--grid);border-radius:13px;
  background:color-mix(in srgb,var(--card) 62%,transparent)}
.eh-tape .dtp-dot{background:#1FA971}
.eh-tape .dtp-asof{display:inline-flex;align-items:center;gap:2px}
.eh-tape b{color:var(--ink);font-weight:800;font-variant-numeric:tabular-nums}
/* hero tiles */
.eh-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:16px}
@media(max-width:760px){.eh-tiles{grid-template-columns:1fr}}
.tile{position:relative;background:var(--card);border:1px solid var(--grid);border-radius:14px;padding:15px 17px;
  animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}
.tile:nth-child(2){animation-delay:.06s}.tile:nth-child(3){animation-delay:.12s}
.tile.t-lift{--tc:var(--lift)}.tile.t-drag{--tc:var(--drag)}.tile.t-accent{--tc:var(--ch-a)}.tile.t-neutral{--tc:var(--faint)}
/* the free build's honest-total tile: a count is not a direction, so it takes
   the brand link ink rather than an up/down one that 中文 would flip */
.tile.t-link{--tc:var(--link)}
.tile .tk{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--muted)}
/* a step below the verdict on purpose: the sentence is the page's thesis and
   the tiles support it, so they must not tie with it for first read */
.tile .tv{font-size:24px;font-weight:800;letter-spacing:-.025em;color:var(--ink);line-height:1.12;margin:6px 0 3px;font-variant-numeric:tabular-nums}
.tile .tm{font-size:12px;color:var(--faint);line-height:1.45}
.tile .tstance{margin-top:10px}

/* ═══ section chrome ═══ */
.sec{margin-top:40px}
.sec-head{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:0 0 4px}
.sec-head .sh-dot{width:7px;height:7px;border-radius:2px;background:var(--sc,var(--accent));flex:none}
.sec-head h2{margin:0;font-size:12.5px;font-weight:800;color:var(--ink);text-transform:uppercase;letter-spacing:.115em}
.sec-sub{font-size:13.5px;color:var(--muted);margin:0 0 16px;max-width:720px;line-height:1.5}
.card{background:var(--card);border:1px solid var(--grid);border-radius:16px;padding:18px 20px;position:relative;
  animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}

/* ═══ stance pill ═══ */
.stpill{display:inline-flex;align-items:center;gap:6px;padding:4px 11px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap;cursor:help;
  background:color-mix(in srgb,var(--sp,var(--muted)) 12%,var(--card));color:var(--sp,var(--muted));border:1px solid color-mix(in srgb,var(--sp,var(--muted)) 26%,var(--grid))}
.stpill .stdot{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.st-act{--sp:var(--lift)}.st-act .stdot,.st-ready .stdot{animation:txBreathe 2.4s ease-in-out infinite}
.st-ready{--sp:var(--teal)}.st-watch{--sp:var(--link)}.st-trim{--sp:var(--amber)}.st-aside{--sp:var(--faint)}.st-ignore{--sp:var(--faint)}

/* ═══ breadth constellation ═══ */
.bdots{display:inline-flex;align-items:center;gap:3px;line-height:1;cursor:help}
.bdots i{width:9px;height:9px;border-radius:50%;display:inline-block;flex:none}
.bdots i.up{background:var(--lift)}.bdots i.dn{background:var(--drag)}
.bdots i.sep{width:1px;height:12px;border-radius:0;background:var(--grid);margin:0 2px}
.bdots i.ov{width:auto;height:auto;border-radius:0;font-size:10px;font-weight:800;color:var(--lift);font-style:normal;margin-left:1px}

/* ═══ pressure bar ═══ */
.pbar{position:relative;display:block;height:7px;background:color-mix(in srgb,var(--grid) 42%,var(--card));border-radius:999px;width:100%;overflow:hidden}
.pb-mid{position:absolute;left:50%;top:0;bottom:0;width:1px;background:var(--muted);opacity:.72;z-index:1}
.pb-fill{position:absolute;top:0;bottom:0;border-radius:999px;animation:txGrow .8s cubic-bezier(.2,.7,.3,1) both}
.pb-fill.u{left:50%;transform-origin:left;background:linear-gradient(90deg,color-mix(in srgb,var(--lift) 22%,transparent),color-mix(in srgb,var(--lift) 62%,transparent))}
.pb-fill.d{right:50%;transform-origin:right;background:linear-gradient(270deg,color-mix(in srgb,var(--drag) 22%,transparent),color-mix(in srgb,var(--drag) 62%,transparent))}

/* ═══ the money-source marks (the page's signature) ═══════════════════════════
   One rail, two segments, sized by how many funds were on each side. It rides
   fund COUNTS rather than dollars on purpose: counts are this page's primary
   and least manipulable lens, they survive a sponsor that publishes no market
   values, and they cannot be misread as a second reading of the pp headline.
   1px gap + track border so the segments stay separate on white (Doctrine §5.8). */
.srail{display:inline-flex;width:32px;height:5px;border-radius:3px;overflow:hidden;flex:none;
  background:color-mix(in srgb,var(--grid) 62%,var(--card));
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--grid) 75%,transparent)}
.srail i{display:block;height:100%}
.sr-f{background:var(--flow);border-right:1px solid var(--card)}
.sr-s{flex:1;background:var(--pick)}
.sw{width:9px;height:9px;border-radius:2px;display:inline-block;margin-right:6px;flex:none;vertical-align:-1px}
.sw-f{background:var(--flow)}.sw-s{background:var(--pick)}
.src{display:inline-flex;align-items:center;gap:6px;font-size:10.5px;font-weight:700;white-space:nowrap}
.src-t{color:var(--faint)}
.sc-f .src-t{color:color-mix(in srgb,var(--flow) 62%,var(--muted))}
.sc-s .src-t{color:color-mix(in srgb,var(--ink) 55%,var(--muted))}
/* money: mono, quiet, never bold, never directional — the receipt voice */
.mny{font-family:var(--font-mono),ui-monospace,monospace;font-size:11px;font-weight:600;
  color:var(--muted);font-variant-numeric:tabular-nums;letter-spacing:-.015em;white-space:nowrap}
.mny .pl{font-style:normal;font-weight:800;color:var(--faint);cursor:help}
.mny.none{color:var(--faint)}
/* one persistence chip, outlined and quiet — a streak is context, not a call */
.prs{display:inline-block;padding:0 6px;border-radius:6px;font-size:10px;font-weight:700;
  color:var(--muted);border:1px solid var(--grid);white-space:nowrap}
/* the small-caps "active manager" mark: a person picks these holdings, so it
   takes the same ink the manager's-pick segment does */
.am{font-style:normal;font-size:9.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;
  color:color-mix(in srgb,var(--ink) 62%,var(--muted));cursor:help}

/* ═══ consensus board (signature) ═══ */
.cb-card{padding:0}
.cb-legend{display:flex;align-items:baseline;gap:7px 16px;flex-wrap:wrap;padding:12px 20px 11px;
  border-bottom:1px solid var(--grid);font-size:11.5px;color:var(--muted);line-height:1.45}
.cb-legend .lg-k{font-size:10.5px;font-weight:800;letter-spacing:.02em;color:var(--ink);white-space:nowrap}
.cb-legend .lg-t{flex:1 1 300px;min-width:0}
.cb-legend .lg-m{font-size:10.5px;color:var(--faint);white-space:nowrap}
.cb-head,.cb-row{display:grid;grid-template-columns:28px minmax(146px,1.3fr) 116px minmax(158px,1.15fr) 172px;gap:16px;align-items:center}
.cb-head{padding:9px 20px 8px;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--grid)}
.cb-head .r{text-align:right}
.cb-row{padding:12px 20px}
.cb-row+.cb-row{border-top:1px solid color-mix(in srgb,var(--grid) 55%,transparent)}
.cb-row:hover{background:color-mix(in srgb,var(--accent) 4%,transparent)}
.cb-rank{font-size:13px;font-weight:800;color:var(--faint);font-variant-numeric:tabular-nums;text-align:center}
.cb-row:nth-child(-n+6) .cb-rank{color:var(--accent)}
.stock-cell{display:flex;align-items:center;gap:9px;min-width:0}
.stock-cell .st-txt{min-width:0}
.stock-cell .st-txt b{display:block;font-size:14px;color:var(--ink);line-height:1.15;letter-spacing:-.005em}
.stock-cell .st-txt .nm{display:block;font-size:11.5px;color:var(--muted);line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}
.themetag{display:inline-block;margin-top:3px;padding:0 7px;border-radius:6px;font-size:10px;font-weight:700;letter-spacing:.01em;
  background:color-mix(in srgb,var(--muted) 13%,var(--card));color:var(--muted)}
.cb-breadth{display:flex;flex-direction:column;align-items:flex-start;gap:5px}
.cb-net{text-align:right;font-variant-numeric:tabular-nums}
.cb-net .v{font-size:15px;font-weight:800;letter-spacing:-.02em}
.cb-net .v.u{color:var(--lift)}.cb-net .v.d{color:var(--drag)}
.cb-pres{display:flex;flex-direction:column;gap:6px}
.cb-src{display:flex;align-items:center;gap:9px;flex-wrap:wrap;cursor:help}
.cb-flags{display:flex;gap:5px;flex-wrap:wrap}
.cb-flags:empty{display:none}
.mini{display:inline-block;padding:0 7px;border-radius:6px;font-size:10px;font-weight:800;letter-spacing:.02em;white-space:nowrap}
.mini.new{background:color-mix(in srgb,var(--lift) 16%,var(--card));color:var(--lift)}
.mini.exit{background:color-mix(in srgb,var(--drag) 15%,var(--card));color:var(--drag)}
/* disagreement is a FACT about the fund count, so it sits with the dots and is
   outlined rather than filled — it must not shout louder than the stance */
.mini.split{color:var(--ink-warn, var(--amber));border:1px solid color-mix(in srgb,var(--ink-warn, var(--amber)) 34%,var(--grid));font-weight:700}
.mini.old{color:var(--muted);border:1px solid var(--grid);font-weight:700;cursor:help}
.mini.contested{background:color-mix(in srgb,var(--amber) 16%,var(--card));color:var(--ink-warn, var(--amber))}
.mini.active{background:color-mix(in srgb,var(--ch-a) 15%,var(--card));color:var(--ch-a)}
/* the whose-conviction hover popover */
.cb-who{position:relative;display:inline-flex}
.cb-who .who-src{font-size:11px;color:var(--muted);cursor:help;border-bottom:1px dashed var(--grid)}
.cb-who .who-pop{display:none;position:absolute;left:0;top:20px;z-index:40;width:230px;padding:10px 12px;border-radius:11px;
  background:var(--card);border:1px solid var(--grid);box-shadow:0 14px 34px -14px rgba(9,17,40,.4);font-size:12px;line-height:1.5;color:var(--text)}
.cb-who:hover .who-pop{display:block}
.who-pop .wl{display:flex;justify-content:space-between;gap:10px;padding:2px 0}
.who-pop .wl b{color:var(--ink)}
.who-pop .wl .wv.u{color:var(--lift)}.who-pop .wl .wv.d{color:var(--drag)}
/* the size lens — below the ranking, never instead of it */
.cb-size{display:flex;align-items:center;gap:8px 14px;flex-wrap:wrap;padding:11px 20px 12px;
  border-top:1px solid var(--grid);background:color-mix(in srgb,var(--grid) 14%,transparent)}
.cb-size .cs-k{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--muted)}
.cb-size .cs-i{display:inline-flex;align-items:baseline;gap:6px;color:var(--text)}
.cb-size .cs-i b{font-size:12px;font-weight:800;color:var(--ink)}
.cb-size .cs-i:hover b{color:var(--link)}
.cb-size .cs-n{font-size:11px;color:var(--faint);cursor:help;border-bottom:1px dashed var(--grid);margin-left:auto}
@media(max-width:720px){
  .cb-head{display:none}
  .cb-row{grid-template-columns:26px 1fr auto;gap:11px;row-gap:9px;padding:13px 16px}
  .cb-legend,.cb-size{padding-left:16px;padding-right:16px}
  .cb-pres{grid-column:2/-1}
  .cb-stance-cell{grid-column:2/-1}
}

/* ═══ fresh conviction cards ═══ */
.fc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(238px,1fr));gap:14px}
.fc{position:relative;background:var(--card);border:1px solid var(--grid);border-radius:14px;padding:14px 16px;
  animation:txUp .5s cubic-bezier(.2,.7,.3,1) both}
.fc-top{display:flex;align-items:center;gap:9px}
.fc-top .st-txt{flex:1;min-width:0}
.fc-top .st-txt b{display:block;font-size:14.5px;color:var(--ink);line-height:1.1}
.fc-top .st-txt .nm{display:block;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:150px}
.fc-conv{flex:none;font-size:14px;font-weight:800;color:var(--lift);font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.fc-conv i{font-style:normal;font-size:10px;font-weight:700;color:var(--faint);margin-left:1px}
.fc-mid{font-size:11.5px;color:var(--muted);margin:11px 0 8px}
.fc-mid b{color:var(--ink);font-weight:800}
.fc-funds{display:flex;flex-wrap:wrap;gap:4px}
.fchip{padding:1px 7px;border-radius:6px;font-size:10.5px;font-weight:700;background:color-mix(in srgb,var(--muted) 13%,var(--card));color:var(--muted)}
/* an ACTIVE manager's chip takes the manager's-pick ink: a person chose it */
.fchip.act{background:color-mix(in srgb,var(--ink) 15%,var(--card));color:var(--ink);cursor:help}
.fchip.more{background:transparent;border:1px solid var(--grid);color:var(--faint)}
.fc-foot{margin-top:12px;padding-top:11px;border-top:1px solid color-mix(in srgb,var(--grid) 60%,transparent)}

/* ═══ rotation rail (market backdrop) ═══ */
.rr{display:grid;grid-template-columns:1.05fr 1.25fr 1.05fr;gap:16px;align-items:start}
@media(max-width:900px){.rr{grid-template-columns:1fr}}
.rrc{position:relative;background:var(--card);border:1px solid var(--grid);border-radius:16px;padding:17px 19px;
  animation:txUp .55s cubic-bezier(.2,.7,.3,1) both}
.rrc:nth-child(2){animation-delay:.06s}.rrc:nth-child(3){animation-delay:.12s}
.rrc.c-risk{--rc:var(--ch-a)}.rrc.c-sect{--rc:var(--ch-b)}.rrc.c-style{--rc:var(--ch-c)}
.rrc .rr-eyebrow{font-size:10px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--rc,var(--accent))}
.rrc .rr-state{font-size:23px;font-weight:800;letter-spacing:-.025em;color:var(--ink);line-height:1.1;margin:9px 0 3px}
.rrc .rr-sub{font-size:14px;font-weight:700;letter-spacing:-.01em;color:var(--ink);margin:9px 0 3px;display:flex;align-items:center}
.rrc .rr-read{font-size:12px;color:var(--muted);line-height:1.45}
.rr-legs{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
.leg{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:8px;font-size:11px;font-weight:600;background:color-mix(in srgb,var(--grid) 45%,var(--card));color:var(--text)}
.leg .ar{font-size:9px}.leg.u{color:var(--lift)}.leg.d{color:var(--drag)}
/* sector ladder */
.slad{display:flex;flex-direction:column;gap:7px;margin-top:11px}
.slad .sl{display:grid;grid-template-columns:18px 74px 1fr auto;gap:9px;align-items:center;font-size:12px}
.slad .sl .rk{font-size:10px;font-weight:800;color:var(--faint);text-align:center;font-variant-numeric:tabular-nums}
.slad .sl .nm{font-weight:700;color:var(--ink)}
.slad .sl .track{position:relative;height:6px;border-radius:999px;background:color-mix(in srgb,var(--grid) 55%,var(--card))}
.slad .sl .track i{position:absolute;left:50%;top:0;bottom:0;border-radius:999px;animation:txGrow .7s ease both}
.slad .sl .track i.u{transform-origin:left;background:color-mix(in srgb,var(--lift) 55%,transparent)}
.slad .sl .track i.d{right:50%;left:auto;transform-origin:right;background:color-mix(in srgb,var(--drag) 55%,transparent)}
.slad .sl .mv{font-size:11px;font-weight:700;font-variant-numeric:tabular-nums;text-align:right;min-width:44px}
.slad .sl .mv.u{color:var(--lift)}.slad .sl .mv.d{color:var(--drag)}
/* style tug-of-war */
.tug{display:flex;flex-direction:column;gap:11px;margin-top:8px}
.tug .tw{font-size:12px}
.tug .tw .lab{display:flex;justify-content:space-between;gap:8px;margin-bottom:4px}
.tug .tw .lab .nm{font-weight:700;color:var(--ink)}
.tug .tw .lab .ld{font-size:11px;font-weight:700;color:var(--ch-c)}
.tug .tw .bar{position:relative;height:7px;border-radius:999px;background:color-mix(in srgb,var(--grid) 55%,var(--card))}
.tug .tw .bar .mid{position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--faint);opacity:.4}
.tug .tw .bar i{position:absolute;left:50%;top:0;bottom:0;border-radius:999px;animation:txGrow .7s ease both;
  background:color-mix(in srgb,var(--ch-c) 48%,transparent)}
.tug .tw .bar i.u{transform-origin:left}
.tug .tw .bar i.d{right:50%;left:auto;transform-origin:right}

/* ═══ accumulation table ═══ */
.atbl-card{padding:6px 14px}
.atbl{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}
.atbl th{text-align:left;padding:10px 10px 9px;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--grid)}
.atbl td{padding:11px 10px;border-bottom:1px solid color-mix(in srgb,var(--grid) 55%,transparent);vertical-align:middle}
.atbl tr:last-child td{border-bottom:none}
.atbl tbody tr:hover{background:color-mix(in srgb,var(--accent) 4%,transparent)}
.atbl th.r,.atbl td.r{text-align:right}
.atbl .conv{font-weight:800;font-size:14px;letter-spacing:-.02em}
.atbl .conv i{font-style:normal;font-size:10px;font-weight:700;color:var(--faint);margin-left:1px}
.atbl .conv.u{color:var(--lift)}.atbl .conv.d{color:var(--drag)}
.atbl .tsz{display:flex;align-items:center;justify-content:flex-end;gap:9px;margin-top:4px}
.fundcell b{color:var(--ink)}
.atbl-wrap{overflow-x:auto}
@media(max-width:640px){.atbl .hide-sm{display:none}}

/* ═══ shelf (trims / the fleet) ═══ */
.shelf details{background:var(--card);border:1px solid var(--grid);border-radius:15px;margin-bottom:12px}
.shelf summary{list-style:none;cursor:pointer;padding:14px 20px;display:flex;align-items:center;gap:11px;font-size:14px;font-weight:700;color:var(--ink);transition:background .18s;border-radius:15px}
.shelf summary::-webkit-details-marker{display:none}
.shelf summary:hover{background:color-mix(in srgb,var(--accent) 5%,var(--card))}
.shelf summary .sh-ic{flex:none;width:26px;height:26px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:15px;
  color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--card))}
.shelf summary .sh-sub{font-weight:500;color:var(--muted);font-size:12.5px}
.shelf summary .sh-caret{margin-left:auto;flex:none;font-size:11px;color:var(--faint);transition:transform .25s}
.shelf details[open] summary{border-radius:15px 15px 0 0}
.shelf details[open] summary .sh-caret{transform:rotate(90deg)}
.shelf .sh-body{padding:4px 20px 20px;border-top:1px solid var(--grid)}
.fdot{display:inline-block;width:8px;height:8px;border-radius:50%;vertical-align:middle;flex:none}
/* Freshness is a DATA-QUALITY status, not a market direction. It must NOT ride
   --lift/--drag: those flip under html[data-lang="zh"] (红涨绿跌), which painted
   "fresh" red and "stale" green in the first ZH render of the W2 mockup. Fixed
   semantic inks, identical in both languages. Same rule for any pass/fail tint. */
.fdot.fresh{background:#1FA971}.fdot.aging{background:#f0b429}.fdot.stale{background:#e06464}
.fdot.none{background:var(--muted)}

/* ═══ the fleet directory ═══════════════════════════════════════════════════
   Was a 105-row, six-column table: a spreadsheet, not a directory, and 58 KiB
   of the free shell's weight on its own (R3). It is now a grouped directory —
   and the grouping is the point: the three groups ARE the flow-vs-selection
   rule, so a reader who never pays still learns why an active manager's move
   and a theme fund's move mean different things. Everything constant (what the
   dots mean, what the small number is) is stated once in the legend, never per
   row (Doctrine Law 4). */
/* the fleet shelf is data quality, not distribution: it takes the page accent,
   not the trims shelf's --drag. Keyed on the summary rather than on the
   <details> so the element stays a bare `<details open>` — the tier suite pins
   that literal, because a coverage directory that ships collapsed may never be
   crawled (T-B3). */
.fl-sum .sh-ic{color:var(--ch-b);background:color-mix(in srgb,var(--ch-b) 10%,var(--card))}
.fl-sum:hover{background:color-mix(in srgb,var(--ch-b) 5%,var(--card))}
.fl-stats{display:flex;align-items:center;gap:8px 10px;flex-wrap:wrap;margin:14px 0 4px}
.fl-s{display:inline-flex;align-items:baseline;gap:6px;padding:5px 11px;border-radius:999px;
  border:1px solid var(--grid);background:color-mix(in srgb,var(--grid) 16%,transparent);
  font-size:11.5px;color:var(--muted)}
.fl-s b{font-size:14px;font-weight:800;color:var(--ink);font-variant-numeric:tabular-nums}
.fl-lg{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--faint);margin-left:auto}
.fl-lg .fdot{margin-left:7px}
.fl-lg .fdot:first-child{margin-left:0}
.fl-g{margin-top:18px}
.fl-gh{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;padding-bottom:7px;border-bottom:1px solid var(--grid)}
.fl-gn{font-size:10.5px;font-weight:800;letter-spacing:.115em;text-transform:uppercase;color:var(--ink)}
.fl-gc{font-size:10.5px;font-weight:800;color:var(--ch-b);font-variant-numeric:tabular-nums}
.fl-gr{font-size:11.5px;color:var(--muted)}
.fl-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(232px,1fr));gap:1px 18px;margin-top:8px}
.fu{display:flex;align-items:center;gap:7px;padding:4px 0;font-size:12px;min-width:0;line-height:1.35}
/* The row's freshness dot is a ::before rather than a .fdot element: at 105
   funds that markup was 3 KiB of the free shell on its own. It carries the SAME
   fixed inks as the legend's .fdot swatches — never --lift/--drag, which 中文
   flips — and tests/test_etfs_gate pins the two sets to identical values so the
   pair cannot drift. */
.fu::before{content:'';width:8px;height:8px;border-radius:50%;flex:none;background:var(--muted)}
.fu.s1::before{background:#1FA971}.fu.s2::before{background:#f0b429}.fu.s3::before{background:#e06464}
.fu b{font-weight:800;color:var(--ink);flex:none;font-size:11.5px;letter-spacing:.01em}
.fu span{flex:1;min-width:0;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fu i{font-style:normal;font-size:10.5px;color:var(--faint);font-variant-numeric:tabular-nums;flex:none}
.fu u{text-decoration:none;font-size:9.5px;font-weight:700;color:var(--faint);
  border:1px solid var(--grid);border-radius:5px;padding:0 4px;flex:none}
/* holdings date wraps under the chip: .fu itself does not wrap */
.fu{flex-wrap:wrap}
.fu time{display:block;flex-basis:100%;min-width:0;color:var(--muted)}
.fl-foot{margin-top:16px;font-size:11.5px;color:var(--faint);line-height:1.55}

/* ═══ disclosure ═══ */
.disc{font-size:12px;color:var(--muted);margin:32px 0 0;padding-top:16px;border-top:1px solid var(--grid);line-height:1.6}
.disc b{color:var(--ink)}

/* ═══ tk logo ═══ */
.tk-logo{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:6px;overflow:hidden;flex:0 0 26px;
  background:transparent}
.tk-logo img{width:26px;height:26px;object-fit:contain;display:block}
/* Fallback for a ticker with no CDN icon (the .png 404s → onerror swaps this in).
   At 9px the 4-character ticker overran the 26px tile and the parent's
   overflow:hidden sheared it on BOTH sides; size the type to the tile instead.
   It reads as a monogram plate rather than a failed image. */
.tk-fb{font-size:8.5px;font-weight:800;letter-spacing:-.04em;line-height:1;white-space:nowrap;
  color:var(--muted);align-items:center;justify-content:center;width:26px;height:26px;
  border:1px solid var(--grid);border-radius:6px;background:color-mix(in srgb,var(--grid) 22%,transparent)}
.spark{display:inline-block;vertical-align:middle}

/* ═══ ? tip ═══ */
.txq{position:relative;display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:50%;
  border:1px solid var(--grid);color:var(--muted);font-size:10px;font-weight:700;cursor:help;flex:none;margin-left:5px;vertical-align:middle}
.txq .txq-tip{display:none;position:absolute;top:22px;left:-8px;z-index:50;width:294px;padding:11px 13px;border-radius:11px;
  background:var(--card);border:1px solid var(--grid);box-shadow:0 14px 34px -14px rgba(9,17,40,.42);
  font-size:12px;font-weight:500;color:var(--text);line-height:1.55;text-transform:none;letter-spacing:0;text-align:left}
.txq:hover .txq-tip,.txq:focus .txq-tip{display:block}
.txq:focus-visible{outline:2px solid var(--link);outline-offset:2px}
@media(max-width:520px){.txq .txq-tip{left:auto;right:-8px;width:min(290px,84vw)}}

/* ═══ tier gate (SEO Supercharge W2 — docs/TIER_PREVIEW_PATTERN.md) ═══
   Transliterated from the shipped special_situations idiom into THIS page's
   token vocabulary: --card / --grid are already aliased above, --blue becomes
   --link, and the --surface family is defined in :root. #8b5cf6 (the lock
   violet) stays a hard-coded hex, identical to the reference. The CTA gradient
   is brand blue → violet, NEVER signal amber (terminal paywall lesson).
   None of these elements carries directional colour: a gate is not a market
   read, so the 红涨绿跌 flip must not touch it. */
.gate-pill{margin-left:2px;padding:2px 8px;border-radius:999px;font-size:9.5px;font-weight:800;letter-spacing:.08em;
  color:#8b5cf6;background:color-mix(in srgb,#8b5cf6 13%,transparent);
  border:1px solid color-mix(in srgb,#8b5cf6 34%,transparent);text-transform:none}
@keyframes ghPulse{0%,100%{opacity:.45}50%{opacity:.85}}
.gh{border-radius:6px;background:linear-gradient(90deg,var(--grid),color-mix(in srgb,var(--grid) 45%,transparent));
  animation:ghPulse 2.4s ease-in-out infinite}
/* consensus-board skeletons — the walled board's shape, none of its content */
.cb-ghosts{border:1px solid var(--grid);border-radius:14px;overflow:hidden;background:var(--card)}
.cbg-hd,.cbg-row{display:grid;grid-template-columns:34px 1.7fr 1fr 1.5fr 1.05fr;gap:14px;align-items:center}
.cbg-hd{padding:10px 16px;border-bottom:1px solid var(--grid);font-size:9.5px;font-weight:800;letter-spacing:.09em;
  text-transform:uppercase;color:var(--faint)}
.cbg-row{padding:13px 16px;border-bottom:1px solid color-mix(in srgb,var(--text) 6%,transparent)}
.cbg-row:last-child{border-bottom:0}
.gh-rank{width:15px;height:12px}
.gh-tkr{width:48px;height:12px;margin-bottom:6px}
.gh-nm{width:78%;height:9px}
.gh-dots{width:66px;height:10px}
.gh-bar{width:100%;height:9px}
.gh-pill{width:96px;height:20px;border-radius:999px}
@media(max-width:720px){.cbg-hd{display:none}.cbg-row{grid-template-columns:26px 1fr;row-gap:9px}}
/* gate note — it EXPLAINS, it never sells. No CTA button lives here. */
.gate-note{display:flex;align-items:flex-start;gap:8px;margin:0 0 14px;padding:11px 14px;border-radius:12px;
  font-size:12.5px;line-height:1.5;color:var(--muted);
  background:color-mix(in srgb,#8b5cf6 7%,transparent);border:1px solid color-mix(in srgb,#8b5cf6 22%,transparent)}
.gate-note svg{width:14px;height:14px;flex:none;margin-top:2px;color:#8b5cf6}
.gate-note a{color:var(--ink-link, var(--link))}
/* the page's ONE tier wall, at "Every add, by fund" — after the free backdrop */
.tier-wall{position:relative;margin:6px 0 4px;isolation:isolate}
.tw-ghosts{display:flex;flex-direction:column;gap:10px;padding-top:4px}
.tw-ghost{border:1px solid var(--grid);border-radius:14px;background:color-mix(in srgb,var(--card) 55%,transparent);
  padding:18px 20px}
.tw-ghost .gh-tkr{width:64px;height:14px;margin-bottom:11px}
.tw-ghost .gh-line{width:70%;height:10px;margin-bottom:8px}
.tw-ghost .gh-line.short{width:38%;margin-bottom:0}
.tw-card{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(560px,94%);text-align:center;
  padding:30px 30px 26px;border-radius:20px;background:var(--surface);border:1px solid var(--surface-brd);
  box-shadow:var(--surface-shadow);-webkit-backdrop-filter:saturate(180%) blur(22px);backdrop-filter:saturate(180%) blur(22px)}
.tw-lock{width:28px;height:28px;color:#8b5cf6;margin-bottom:12px}
.tw-h{font-size:19px;font-weight:800;letter-spacing:-.02em;color:var(--ink);line-height:1.25;margin-bottom:9px}
.tw-p{font-size:13px;line-height:1.6;color:var(--muted);max-width:450px;margin:0 auto 18px}
.tw-acts{display:flex;flex-direction:column;align-items:center;gap:8px}
.tw-btn{display:inline-flex;align-items:center;justify-content:center;padding:11px 26px;border-radius:12px;
  text-decoration:none;font-size:13.5px;font-weight:700;color:#fff;
  background:linear-gradient(135deg,var(--link),#8b5cf6);
  box-shadow:0 8px 22px -10px color-mix(in srgb,#8b5cf6 70%,transparent);transition:transform .18s,box-shadow .18s}
.tw-btn:hover{transform:translateY(-1px);box-shadow:0 12px 28px -10px color-mix(in srgb,#8b5cf6 80%,transparent)}
.tw-note{font-size:11px;color:var(--faint)}
.tw-signed{margin-top:12px;font-size:12px}
.tw-signed a{color:var(--ink-link, var(--link));text-decoration:none;border-bottom:1px solid color-mix(in srgb,var(--link) 40%,transparent)}
@media(max-width:900px){
  /* Below the ghost stack's usable width the absolute card overlaps the lede
     above it; drop the ghosts and let the card flow. */
  .tw-ghosts{display:none}
  .tw-card{position:static;transform:none;width:100%;padding:26px 20px 22px}
}

/* ═══ motion ═══ */
@keyframes txUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes txBreathe{0%,100%{opacity:.5;transform:scale(.82)}50%{opacity:1;transform:scale(1.12)}}
@keyframes txGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@media (prefers-reduced-motion:reduce){
  .eh,.tile,.card,.rrc,.fc{animation:none}
  .pb-fill,.slad .sl .track i,.tug .tw .bar i,.stdot{animation:none}
  /* the as-of strip's cycle dot pulses from theme.css's own keyframe — kill it
     by name here too, the wildcard below only covers transitions */
  .eh-tape .dtp-dot{animation:none}
  /* the tier gate's skeleton shimmer is decorative — kill it by name, not by
     hoping the wildcard below covers animations (it only covers transitions) */
  .gh{animation:none}
  .tw-btn{transition:none}
  *{transition:none!important}
}

rules.old:
.card{--rail:var(--accent)}.tile{--rail:var(--tc,var(--accent))}
.rrc{--rail:var(--rc,var(--accent))}.fc{--rail:var(--lift)}
.card,.tile,.rrc,.fc{box-shadow:inset 3px 0 0 var(--rail)}
html[data-theme="light"] .card,html[data-theme="light"] .tile,
html[data-theme="light"] .rrc,html[data-theme="light"] .fc{
  box-shadow:inset 3px 0 0 var(--rail),var(--lift-shadow)}
html[data-theme="light"] .shelf details{box-shadow:var(--lift-shadow)}
/* zh 红涨绿跌 (operator ruling): accumulate/trim are DIRECTION reads → swap. */

rules.new:
.card{--rail:var(--accent)}.tile{--rail:var(--tc,var(--accent))}
.rrc{--rail:var(--rc,var(--accent))}.fc{--rail:var(--lift)}
.card,.tile,.rrc,.fc{box-shadow:none}
html[data-theme="light"] .card,html[data-theme="light"] .tile,
html[data-theme="light"] .rrc,html[data-theme="light"] .fc{
  box-shadow:var(--lift-shadow)}
html[data-theme="light"] .shelf details{box-shadow:var(--lift-shadow)}
/* zh 红涨绿跌 (operator ruling): accumulate/trim are DIRECTION reads → swap. */

rules.old:
/* Finance Intelligence dossier — scoped theme.
   Tokens come ONLY from theme.css. No hex/rgb literals here.
   Two art directions (dark command center / light research workspace),
   each a complete material treatment. */
:root,
html[data-theme="dark"] {
  --fi-canvas:        var(--bg);
  --fi-panel:         var(--panel);
  --fi-panel2:        var(--panel2);
  --fi-line:          var(--line);
  --fi-text:          var(--text);
  --fi-muted:         var(--muted);
  --fi-link:          var(--link);
  --fi-spine:         color-mix(in srgb, var(--line) 90%, transparent);
  --fi-step-fill:     color-mix(in srgb, var(--link) 14%, var(--panel));
  --fi-step-ring:     color-mix(in srgb, var(--link) 30%, transparent);
  --fi-chip-observed: color-mix(in srgb, var(--ok)    18%, var(--panel));
  --fi-chip-watch:    color-mix(in srgb, var(--warn)  18%, var(--panel));
  --fi-chip-caution:  color-mix(in srgb, var(--info)  14%, var(--panel));
  --fi-chip-missing:  color-mix(in srgb, var(--muted) 18%, var(--panel));
  --fi-chip-stale:    color-mix(in srgb, var(--act)   16%, var(--panel));
  --fi-chip-regime:   color-mix(in srgb, var(--act)   22%, var(--panel));
}
html[data-theme="light"] {
  --fi-canvas:        var(--bg);
  --fi-panel:         var(--panel);
  --fi-panel2:        var(--panel2);
  --fi-line:          var(--line);
  --fi-text:          var(--text);
  --fi-muted:         var(--muted);
  --fi-link:          var(--link);
  --fi-spine:         color-mix(in srgb, var(--line) 90%, transparent);
  --fi-step-fill:     color-mix(in srgb, var(--link) 12%, var(--panel));
  --fi-step-ring:     var(--link);
  --fi-chip-observed: color-mix(in srgb, var(--ok)    10%, var(--panel));
  --fi-chip-watch:    color-mix(in srgb, var(--warn)  10%, var(--panel));
  --fi-chip-caution:  color-mix(in srgb, var(--info)   8%, var(--panel));
  --fi-chip-missing:  color-mix(in srgb, var(--muted)  8%, var(--panel));
  --fi-chip-stale:    color-mix(in srgb, var(--act)    8%, var(--panel));
  --fi-chip-regime:   color-mix(in srgb, var(--act)   12%, var(--panel));
}

/* Tier 1 — dark */
.fi-panel,
.fi-toc {
  background: var(--fi-panel);
  border: 1px solid var(--fi-line);
  border-radius: 12px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text) 7%, transparent);
}
/* Tier 2 — dark */
.fi-panel2,
.fi-domain,
.fi-slice,
.fi-conflict-card,
.fi-macro-card,
.fi-exposure-card,
.fi-falsifier,
.fi-constraint-row,
.fi-conflict-side {
  background: var(--fi-panel2);
  border: 1px solid var(--fi-line);
  border-radius: 10px;
}
/* Tier 1 — light */
html[data-theme="light"] .fi-panel,
html[data-theme="light"] .fi-toc {
  background: var(--fi-panel);
  border: 1px solid var(--fi-line);
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 6%, transparent),
    0 6px 20px color-mix(in srgb, var(--text) 5%, transparent);
}
/* Tier 2 — light */
html[data-theme="light"] .fi-panel2,
html[data-theme="light"] .fi-domain,
html[data-theme="light"] .fi-slice,
html[data-theme="light"] .fi-conflict-card,
html[data-theme="light"] .fi-macro-card,
html[data-theme="light"] .fi-exposure-card,
html[data-theme="light"] .fi-falsifier,
html[data-theme="light"] .fi-constraint-row,
html[data-theme="light"] .fi-hint-row,
html[data-theme="light"] .fi-conflict-side {
  background: color-mix(in srgb, var(--panel) 92%, var(--bg));
  border: 1px solid var(--fi-line);
  box-shadow: none;
}

/* freshness rail/pip — dark = real pip, light = 3px left rail */
.fi-section-head[data-state-freshness]:not([data-state-freshness=""])::before {
  content: ""; float: left; width: 8px; height: 8px; border-radius: 50%;
  margin: .5em 8px 0 0; background: var(--fi-fresh-colour);
}
.fi-section-head[data-state-freshness="FRESH"]        { --fi-fresh-colour: var(--fresh-ok); }
.fi-section-head[data-state-freshness="FRESH"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--fresh-ok) 25%, transparent); }
.fi-section-head[data-state-freshness="AGING"]        { --fi-fresh-colour: var(--warn); }
.fi-section-head[data-state-freshness="AGING"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--warn) 25%, transparent); }
.fi-section-head[data-state-freshness="SOURCE_STALE"] { --fi-fresh-colour: var(--act); }
.fi-section-head[data-state-freshness="SOURCE_STALE"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--act) 25%, transparent); }
.fi-section-head[data-state-freshness="NO_EVIDENCE"]   { --fi-fresh-colour: var(--line); }
.fi-section-head[data-state-freshness="NO_EVIDENCE"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--line) 25%, transparent); }
html[data-theme="light"] .fi-section-head::before { display: none; }
html[data-theme="light"] .fi-section-head[data-state-freshness="FRESH"]        { border-left: 3px solid var(--fresh-ok); padding-left: 12px; box-shadow: none; }
html[data-theme="light"] .fi-section-head[data-state-freshness="AGING"]        { border-left: 3px solid var(--warn);    padding-left: 12px; box-shadow: none; }
html[data-theme="light"] .fi-section-head[data-state-freshness="SOURCE_STALE"] { border-left: 3px solid var(--act);     padding-left: 12px; box-shadow: none; }
html[data-theme="light"] .fi-section-head[data-state-freshness="NO_EVIDENCE"]   { border-left: 3px solid var(--line);    padding-left: 12px; box-shadow: none; }

/* focus ring — dark glow halo, light solid */
.fi-shell *:focus-visible,
.fi-drawer *:focus-visible {
  outline: 1px solid var(--fi-link);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--fi-link) 30%, transparent);
  border-radius: 6px;
}
html[data-theme="light"] .fi-shell *:focus-visible,
html[data-theme="light"] .fi-drawer *:focus-visible {
  outline: 2px solid var(--fi-link);
  outline-offset: 2px;
  box-shadow: none;
}

/* drawer + scrim */
.fi-drawer {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(440px, 92vw);
  background: var(--fi-panel); border-left: 1px solid var(--fi-line);
  transform: translateX(100%);
  transition: transform .22s cubic-bezier(.2,.7,.3,1);
  display: flex; flex-direction: column; z-index: 80;
}
.fi-drawer[hidden] { display: none; }
.fi-drawer:not([hidden]) { transform: none; }
html[data-theme="light"] .fi-drawer {
  border-left: 0;
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 6%, transparent),
    0 12px 32px color-mix(in srgb, var(--text) 8%, transparent);
}
.fi-scrim { position: fixed; inset: 0; z-index: 70; background: color-mix(in srgb, var(--bg) 70%, transparent); }
html[data-theme="light"] .fi-scrim { background: color-mix(in srgb, var(--text) 35%, transparent); }

/* stepper rail/dot */
.fi-rerating-step[data-active="true"] .fi-step-dot {
  box-shadow: 0 0 0 4px var(--fi-step-ring);
  border-color: var(--fi-link);
}
.fi-rerating-steps::before {
  content: ""; position: absolute; left: 5%; right: 5%; top: 7px; height: 2px;
  background: color-mix(in srgb, var(--text) 14%, transparent);
  border-radius: 2px; z-index: 0;
}
html[data-theme="light"] .fi-rerating-step[data-active="true"] .fi-step-dot {
  box-shadow: 0 0 0 2px var(--fi-step-ring);
  background: var(--fi-step-fill);
  border-color: var(--fi-link);
}
html[data-theme="light"] .fi-rerating-steps::before {
  background: var(--line);
}

/* chip base rule */
.fi-chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 2px 8px;
  font-size: var(--fs-micro);
  font-weight: 600;
  border-radius: 999px;
  border: 1px solid var(--fi-line);
  background: var(--fi-panel);
  color: var(--fi-text);
}
/* Seat erratum (T11 round 2): :where() gives the light base zero theme specificity, so the
   per-state chip rules (0,2,0) still win over it; at (0,2,1) it painted every state chip white. */
:where(html[data-theme="light"]) .fi-chip { background: var(--fi-panel); }

/* page canvas — the page owns its canvas in both art directions. theme.css does not
   paint body, and the shell's 1200px box alone left every gutter, the nav band and
   the area below the content on the browser's white default in the dark direction. */
body.fi-page { background: var(--fi-canvas); }

/* shell + layout */
.fi-shell {
  max-width: 1200px;
  margin: 0 auto;
  padding: clamp(18px, 3vw, 36px) clamp(16px, 3vw, 28px) 80px;
  background: var(--fi-canvas);
  color: var(--fi-text);
  font-family: var(--font-ui);
  font-feature-settings: "tnum" 1, "cv11" 1;
}
.fi-hero { padding: 28px 0 22px; border-bottom: 1px solid var(--fi-line); }
.fi-kicker { font-size: var(--fs-label); letter-spacing: .09em; text-transform: uppercase; color: var(--fi-muted); margin: 0 0 8px; font-weight: 700; }
.fi-hero h1 { font-size: var(--fs-h1); font-weight: 800; letter-spacing: -.02em; margin: 0; }
.fi-deck { font-size: var(--fs-md); line-height: 1.55; margin: 8px 0 0; max-width: 70ch; color: var(--fi-text); }
/* Not connected (no endpoint bound): the hero meta chips carry no payload — hide the empty row. */
.fi-shell[data-state="not-connected"] .fi-meta { display: none; }
/* Ruling F-5 (not-connected honest shell): a calm unbuilt status panel in the
   same measure as .fi-section — hairline border, panel ground, section-title
   h2 scale, muted body — plus static hides so the page is honest with
   JavaScript off. Every mount stays in the DOM for a connected page; the
   runtime's not_connected keep list agrees (finance_intelligence.js). */
.fi-unbuilt {
  background: var(--fi-panel);
  border: 1px solid var(--fi-line);
  border-radius: var(--r-card, 12px);
  margin-top: 40px;
  padding: 20px 24px;
}
.fi-unbuilt h2 { font-size: var(--fs-h2); font-weight: 700; letter-spacing: -.01em; margin: 0; }
.fi-unbuilt p { font-size: var(--fs-md); line-height: 1.55; color: var(--fi-muted);
  margin: 8px 0 0; max-width: 75ch; }
.fi-shell[data-state="not-connected"] .fi-section:not(#company-exposure) { display: none; }
.fi-shell[data-state="not-connected"] .fi-toc { display: none; }
.fi-shell[data-state="not-connected"] .fi-provenance { display: none; }
.fi-shell[data-state="not-connected"] [data-fi-mount="notice"] { display: none; }
.fi-shell[data-state="not-connected"] #company-exposure > :not(.fi-section-head,
.fi-hint-lede, .fi-hint-roster) { display: none; }
.fi-meta { font-size: var(--fs-sm); color: var(--fi-muted); margin: 10px 0 0; display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.fi-toc { margin: 18px 0 8px; padding: 12px 16px; }
.fi-toc ol { display: flex; flex-wrap: wrap; gap: 8px 12px; margin: 0; padding: 0; list-style: none; font-size: var(--fs-sm); }
.fi-toc a, .fi-toc-evidence { color: var(--fi-text); text-decoration: none; padding: 4px 8px; border-radius: 7px; background: transparent; border: 0; cursor: pointer; font: inherit; }
.fi-toc a:hover, .fi-toc-evidence:hover { background: var(--fi-panel2); }
.fi-section { margin-top: 40px; padding: 20px 24px; }
.fi-section-title { font-size: var(--fs-h2); font-weight: 700; letter-spacing: -.01em; margin: 0 0 4px; }
.fi-section-title-answer { font-size: var(--fs-h1); font-weight: 800; letter-spacing: -.02em; }
.fi-section-eyebrow { display: block; font-size: var(--fs-sm); color: var(--fi-muted); font-weight: 400; margin-top: 2px; }
.fi-section-foot { font-size: var(--fs-sm); color: var(--fi-muted); margin: 12px 0 0; max-width: 75ch; }
.fi-section-head { padding: 4px 0; }
/* Seat erratum (T11 round 2): spec §B.1 rows are the house DecisionRow (.mx-chg-row, theme.css);
   the list drops its UA bullets and indent like the page's other lists. */
.fi-change-list { list-style: none; margin: 12px 0 0; padding: 0; }
.fi-disc { margin: 12px 0 0; padding-top: 8px; border-top: 1px solid var(--fi-line); }
.fi-disc > summary { list-style: none; cursor: pointer; padding: 4px 0; font-size: var(--fs-sm); color: var(--fi-link); }
.fi-disc > summary::-webkit-details-marker { display: none; }
.fi-disc > summary::before { content: "+"; display: inline-block; width: 1em; margin-right: 6px; color: var(--fi-muted); }
.fi-disc[open] > summary::before { content: "\2013"; }
.fi-disc > summary:focus-visible { outline: 2px solid var(--fi-link); outline-offset: 2px; }
.fi-disc > table, .fi-disc > ul { margin-top: 8px; }
/* Cards-more disclosure is now visible at every viewport by default; §C.10 hides it at ≥768. */
.fi-exposure-cards-more { display: block; }

/* W10-FIN-2 hint roster (#company-exposure): eleven RESEARCH_HINT_UNVALIDATED
   citation rows. Tier-2 surface in both themes; each row wraps instead of
   overflowing a 390px viewport. */
.fi-hint-roster { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 6px; }
/* Ruling F-5: quiet body line above the roster — the names are research
   hints under study, none confirmed. */
.fi-hint-lede { font-size: var(--fs-sm); color: var(--fi-muted); margin: 12px 0 0; }
.fi-hint-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; padding: 6px 10px; font-size: var(--fs-sm); background: var(--fi-panel2); border: 1px solid var(--fi-line); border-radius: var(--r-ctl, 8px); }
.fi-hint-symbol { color: var(--fi-text); font-weight: 600; min-width: 3.5em; }
.fi-hint-record { margin-left: auto; min-width: 0; color: var(--fi-muted); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }

/* Per-state colour map (§C.7/§C.8/D.36) — every spec-named chip carries its own selector.
   Spec covers ONLY step, slice, membership, posture, and macro-cell-state chips;
   every other chip keeps the base .fi-chip treatment and its plain word. */

/* rerating stepper */
.fi-slice-picker { margin: 12px 0 16px; display: flex; gap: 10px; align-items: center; font-size: var(--fs-sm); }
/* A native select sizes to its longest option (a real slice name pair runs
   ~440px) and a flex item never shrinks below that: at 390px the page
   scrolled sideways. It shrinks and clips its closed label instead; the
   field label keeps its width (CJK min-content is one glyph, so "切片"
   wrapped a character per line once the select could shrink). */
.fi-slice-picker > label { flex: none; }
.fi-slice-select { font: inherit; padding: 4px 8px; border-radius: var(--r-ctl, 8px); border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); min-width: 0; max-width: 100%; text-overflow: ellipsis; }
.fi-rerating-steps { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; margin: 18px 0 0; padding: 0; list-style: none; position: relative; }
.fi-rerating-step { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; text-align: center; padding: 0 6px; gap: 6px; }
.fi-step-dot { width: 12px; height: 12px; border-radius: 50%; background: var(--fi-step-fill); border: 2px solid var(--fi-line); margin-bottom: 4px; }
.fi-step-label { font-size: var(--fs-sm); font-weight: 600; color: var(--fi-text); }
.fi-step-metric { font-size: var(--fs-sm); color: var(--fi-muted); font-variant-numeric: tabular-nums; min-height: 1.4em; }
.fi-step-chip { display: inline-block; font-size: var(--fs-sm); font-weight: 600; padding: 2px 7px; border-radius: 999px; border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); }
.fi-step-clock { font-size: var(--fs-sm); color: var(--fi-muted); font-variant-numeric: tabular-nums; }
.fi-anchor-chip, .fi-history-chip, .fi-valuation-chip, .fi-price-chip, .fi-comparability-chip { display: inline-block; font-size: var(--fs-sm); font-weight: 600; padding: 2px 7px; border-radius: 999px; border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); }
.fi-step-evidence { background: transparent; border: 1px solid var(--fi-line); width: 24px; height: 24px; color: var(--fi-muted); cursor: pointer; font-size: var(--fs-sm); }
.fi-step-evidence:hover { color: var(--fi-text); border-color: var(--fi-muted); }
/* §C.5 / Item 5: coarse-pointer hit areas at 44×44 (WCAG 2.5.5 AAA). The glyph
   stays the same; padding or an inset hit-area absorbs the extra size. */
@media (pointer: coarse) {
  .fi-step-evidence,
  .fi-evidence-trigger,
  .fi-constraint-evidence {
    min-width: 44px; min-height: 44px;
  }
  .fi-view-tab { min-width: 44px; min-height: 44px; padding: 8px 12px; }
  .fi-disc > summary { min-width: 44px; min-height: 44px; padding: 8px 4px; }
  .fi-drawer-close { min-width: 44px; min-height: 44px; }
}
.fi-rerating-bridge { font-size: var(--fs-md); color: var(--fi-text); margin: 16px 0 0; max-width: 75ch; }
.fi-falsifiers { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 6px; }
.fi-falsifier { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 6px 10px; font-size: var(--fs-sm); }
.fi-falsifier-chip { font-size: var(--fs-sm); padding: 1px 7px; border-radius: 999px; border: 1px solid var(--fi-line); }
.fi-falsifier-statement { color: var(--fi-text); }
.fi-falsifier-window { color: var(--fi-muted); font-variant-numeric: tabular-nums; }
.fi-conflicts { margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--fi-line); }
.fi-conflicts-title { font-size: var(--fs-h3); font-weight: 700; margin: 0 0 8px; }
.fi-conflict-list { display: grid; gap: 10px; margin: 12px 0 0; padding: 0; list-style: none; }
.fi-conflict-card { padding: 12px 16px; }
.fi-conflict-label { font-size: var(--fs-sm); font-weight: 700; display: block; margin-bottom: 6px; }
.fi-conflict-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.fi-conflict-side { padding: 8px 10px; border-radius: 8px; border: 1px solid var(--fi-line); background: var(--fi-panel2); font-size: var(--fs-sm); }
.fi-conflict-side-statement { display: block; }
.fi-conflict-side-evidence { margin-top: 4px; font-size: var(--fs-sm); }
.fi-conflict-foot { font-size: var(--fs-sm); color: var(--fi-muted); margin: 8px 0 0; }

/* chip state colours — each maps to one plane-state token */
.fi-step-chip[data-state="OBSERVED"]    { background: var(--fi-chip-observed); }
.fi-step-chip[data-state="INFERRED"]    { background: var(--fi-chip-watch); }
.fi-step-chip[data-state="MISSING"]     { background: var(--fi-chip-missing); }
.fi-step-chip[data-state="CONFLICTING"] { background: var(--fi-chip-caution); }
.fi-step-chip[data-state="STALE"]       { background: var(--fi-chip-stale); }
.fi-step-chip[data-state="REGIME_BREAK"],
.fi-step-chip[data-state="VALUATION_ANCHOR_UNAVAILABLE"],
.fi-step-chip[data-state="PRICE_BASIS_UNQUALIFIED"] { background: var(--fi-chip-regime); }
.fi-step-chip[data-state="NOT_APPLICABLE"] { background: var(--fi-panel2); color: var(--fi-muted); }

/* atlas grid */
.fi-domain-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-top: 16px; }
.fi-domain { padding: 16px 16px 10px; }
.fi-domain-title { font-size: var(--fs-h3); font-weight: 700; margin: 0 0 8px; }
.fi-slice-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.fi-slice { display: grid; grid-template-columns: 1fr auto; gap: 6px 8px; align-items: center; padding: 6px 8px; border-radius: 8px; background: var(--fi-panel2); }
.fi-slice-name { font-size: var(--fs-sm); font-weight: 600; color: var(--fi-text); overflow-wrap: anywhere; }
.fi-slice-chip { font-size: var(--fs-sm); font-weight: 600; padding: 1px 7px; border-radius: 999px; border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); }
.fi-slice-chip[data-state-slice="SEMANTIC_ONLY"] { background: var(--fi-chip-missing); }
.fi-slice-chip[data-state-slice="MEASURABLE"]   { background: var(--fi-chip-observed); }
.fi-slice-chip[data-state-slice="STALE"]        { background: var(--fi-chip-stale); }
.fi-slice-chip[data-state-slice="HELD_FOR_REVIEW"] { background: var(--fi-chip-watch); }
.fi-membership-chip[data-state-membership="CURRENT_MEMBERSHIP_ONLY"],
.fi-membership-chip[data-state-membership="PIT_MEMBERSHIP_INCOMPLETE"] { background: var(--fi-chip-regime); }
.fi-posture-chip[data-state-posture="SEMANTIC_ONLY"] { background: var(--fi-chip-missing); }
.fi-posture-chip[data-state-posture="RESEARCH_CANDIDATE"] { background: var(--fi-chip-caution); }
.fi-posture-chip[data-state-posture="CANDIDATE_READY_FOR_OWNER_REVIEW"] { background: var(--fi-chip-watch); }
.fi-posture-chip[data-state-posture="ADMITTED"] { background: var(--fi-chip-observed); }
.fi-slice-open { background: transparent; border: 1px solid var(--fi-line); border-radius: 6px; color: var(--fi-muted); cursor: pointer; font-size: var(--fs-sm); }
/* Seat T11 r3 (atlas composition): a slice reads name + basket count on one line and its
   chips on a full-width wrap row below. The shared `1fr auto` slice grid handed the chip
   row's max-content to the auto column and collapsed the name (overflow-wrap: anywhere)
   and the count to one character per line at every width. The count opens nothing, so it
   is muted metadata, not a bordered control. */
.fi-domain .fi-slice { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "name count" "chips chips"; align-items: baseline; }
.fi-domain .fi-slice-name { grid-area: name; }
.fi-domain .fi-slice-baskets { grid-area: count; }
.fi-domain .fi-slice-chips { grid-area: chips; }
.fi-slice-chips, .fi-macro-cell-chips { display: flex; flex-wrap: wrap; gap: 4px; }
.fi-macro-cell-chips { margin-top: 4px; }
.fi-slice-baskets { font-size: var(--fs-micro); color: var(--fi-muted); white-space: nowrap; }
.fi-atlas-gap { font-size: var(--fs-sm); color: var(--fi-muted); margin: 10px 0 0; }

/* exposure table */
.fi-exposure-table-wrap { overflow-x: auto; margin-top: 16px; }
.fi-exposure-table { border-collapse: separate; border-spacing: 0; font-size: var(--fs-sm); width: 100%; }
.fi-exposure-table th, .fi-exposure-table td { border-bottom: 1px solid var(--fi-line); padding: 8px 10px; text-align: left; vertical-align: top; }
.fi-exposure-table thead th { position: sticky; top: 0; background: var(--fi-panel); z-index: 2; font-weight: 600; color: var(--fi-muted); font-size: var(--fs-sm); text-transform: uppercase; letter-spacing: .04em; }
.fi-exposure-table .fi-col-company { position: sticky; left: 0; background: var(--fi-panel); z-index: 1; font-weight: 600; }
.fi-exposure-table thead th.fi-col-company { z-index: 3; }
.fi-cell { min-width: 0; }
.fi-cell-role { display: block; font-weight: 600; }
.fi-cell-basis { display: block; font-size: var(--fs-sm); color: var(--fi-muted); }
.fi-cell-materiality { display: block; font-size: var(--fs-sm); color: var(--fi-text); }
.fi-cell[data-state-materiality="MATERIAL"]    .fi-cell-materiality { color: var(--fi-text); font-weight: 700; }
.fi-cell[data-state-materiality="PARTIAL"]     .fi-cell-materiality { color: var(--fi-text); }
.fi-cell[data-state-materiality="IMMATERIAL"]  .fi-cell-materiality { color: var(--fi-text); }
.fi-cell[data-state-materiality="UNMEASURED"]  .fi-cell-materiality { color: var(--fi-text); }
.fi-cell-risk { display: block; font-size: var(--fs-sm); color: var(--fi-muted); margin-top: 2px; }
.fi-cell-evidence-date { display: block; font-size: var(--fs-sm); color: var(--fi-muted); margin-top: 2px; font-variant-numeric: tabular-nums; }
.fi-company-unresolved, .fi-company-hint { color: var(--fi-muted); font-style: italic; }
.fi-exposure-cards { display: none; list-style: none; margin: 16px 0 0; padding: 0; gap: 10px; }
.fi-exposure-card { padding: 12px 16px; }

/* macro matrix */
.fi-macro-table-wrap { overflow-x: auto; margin-top: 16px; }
.fi-macro-table { border-collapse: separate; border-spacing: 0; font-size: var(--fs-sm); width: 100%; }
.fi-macro-table th, .fi-macro-table td { border-bottom: 1px solid var(--fi-line); padding: 8px 10px; text-align: left; vertical-align: top; }
.fi-macro-table thead th { position: sticky; top: 0; background: var(--fi-panel); z-index: 2; font-weight: 600; color: var(--fi-muted); font-size: var(--fs-sm); }
.fi-macro-table .fi-col-company { position: sticky; left: 0; background: var(--fi-panel); z-index: 1; font-weight: 600; }
.fi-macro-cell-state { display: inline-block; font-size: var(--fs-sm); padding: 1px 7px; border-radius: 999px; border: 1px solid var(--fi-line); }
.fi-macro-cell-state[data-state="CAUSAL_EFFECT_UNMEASURED"] { background: var(--fi-chip-caution); }
.fi-macro-cell-state[data-state="NOT_APPLICABLE"] { background: var(--fi-panel2); color: var(--fi-muted); }
.fi-macro-cell-state[data-state="DESCRIBED"] { background: var(--fi-chip-observed); }

/* constraint map */
.fi-constraint-list { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 8px; }
.fi-constraint-row { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 8px 10px; font-size: var(--fs-sm); }

/* system map */
.fi-view-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin: 12px 0 16px; }
.fi-view-tab { background: var(--fi-panel); border: 1px solid var(--fi-line); color: var(--fi-text); padding: 4px 10px; border-radius: 999px; font: inherit; cursor: pointer; }
.fi-view-tab[aria-selected="true"] { background: var(--fi-step-fill); border-color: var(--fi-link); }
/* Held for T12, which draws the graph: T11 r3 renders no <svg> (it painted an empty panel). */
.fi-system-svg { width: 100%; height: 280px; background: var(--fi-panel2); border-radius: 12px; border: 1px solid var(--fi-line); }
.fi-system-edges { margin: 10px 0 0; }
.fi-system-edge-list { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 4px; font-size: var(--fs-sm); }
.fi-system-edge { padding: 4px 0; border-bottom: 1px dashed var(--fi-line); display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; }
.fi-system-edge-statement { color: var(--fi-text); }

/* drawer body */
.fi-drawer-head { padding: 16px 18px 10px; border-bottom: 1px solid var(--fi-line); display: flex; gap: 12px; align-items: flex-start; }
.fi-drawer-head .fi-kicker { margin: 0; }
.fi-drawer-head h2 { font-size: var(--fs-h2); margin: 4px 0 0; }
.fi-drawer-close { margin-left: auto; background: transparent; border: 1px solid var(--fi-line); border-radius: 6px; color: var(--fi-muted); width: 28px; height: 28px; cursor: pointer; font: inherit; }
.fi-drawer-body { padding: 12px 18px 24px; overflow-y: auto; font-size: var(--fs-sm); }
.fi-evidence-fields { display: grid; gap: 8px; margin: 0; }
.fi-evidence-fields > div { display: grid; grid-template-columns: 36% 64%; gap: 8px; padding-bottom: 6px; border-bottom: 1px dashed var(--fi-line); }
.fi-evidence-fields dt { color: var(--fi-muted); font-weight: 600; }
.fi-evidence-fields dd { margin: 0; color: var(--fi-text); word-break: break-word; }
/* Seat T11 r3: the five T1 limitations fields — page label over owner prose (lang="en"). */
.fi-limitations { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.fi-limitation-label { display: block; font-size: var(--fs-micro); font-weight: 600; color: var(--fi-muted); }
.fi-limitation-missing { color: var(--fi-muted); }
.fi-evidence-private-notice { font-size: var(--fs-sm); color: var(--fi-muted); padding: 8px 10px; border-radius: 8px; border: 1px solid var(--fi-line); background: var(--fi-panel2); margin: 0 0 10px; }

/* notice + provenance */
.fi-notice { margin: 16px 0; font-size: var(--fs-sm); color: var(--fi-muted); padding: 8px 12px; border: 1px solid var(--fi-line); border-radius: 8px; }
.fi-provenance { margin: 40px 0 0; padding: 16px 0; border-top: 1px solid var(--fi-line); font-size: var(--fs-sm); color: var(--fi-muted); display: grid; gap: 4px; }
.fi-receipt-line { display: flex; gap: 8px; align-items: center; }
.fi-receipt-line .fi-chip { background: var(--fi-chip-missing); }

/* visually-hidden helper */
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* Item 10 (SEAT-PINNED source-language marking) — a quiet line under
   sections that hold English-source prose, in ZH only (the helper strips it
   on EN). Treatment: text-only metadata line at --fs-micro, --fi-muted,
   4px top margin — never a chip, never coloured, never italic (F7). */
.fi-srclang-note { font-size: var(--fs-micro); color: var(--fi-muted); margin: 4px 0 0; }

/* responsive */
@media (min-width: 1200px) {
  .fi-shell { max-width: 1200px; }
  /* Seat T11 r3: auto-fit keeps the spec's 4-up at >=1200 without leaving one domain in a
     quarter of the panel (repeat(4, 1fr) reserved three empty tracks). */
  .fi-domain-grid { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
}
@media (min-width: 768px) and (max-width: 1199px) {
  .fi-rerating-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
  .fi-rerating-steps::before { display: none; }
  .fi-rerating-step { flex-direction: row; align-items: center; text-align: left; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--fi-panel2); border: 1px solid var(--fi-line); flex-wrap: wrap; }
  .fi-step-dot { margin: 0 6px 0 0; }
}
@media (max-width: 767px) {
  .fi-rerating-steps { grid-template-columns: 1fr; gap: 6px; }
  .fi-rerating-steps::before { display: none; }
  .fi-rerating-step { flex-direction: row; align-items: center; text-align: left; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--fi-panel2); border: 1px solid var(--fi-line); flex-wrap: wrap; }
  .fi-step-dot { margin: 0 6px 0 0; }
  .fi-domain-grid { grid-template-columns: 1fr; }
  .fi-exposure-table-wrap { display: none; }
  .fi-exposure-more { display: none; }
  .fi-exposure-cards { display: grid; }
  .fi-exposure-cards-more { display: block; }
  .fi-section { padding: 16px; }
  .fi-unbuilt { padding: 16px; }
  .fi-macro-table-wrap { display: none; }
  /* Item 9: every row stays reachable on phone. First 8 rows render in
     .fi-macro-cards; rows 9..N live inside a sibling .fi-disc .fi-macro-cards-more
     with the same card builder (no horizontal scroll at 390px). */
  .fi-macro-cards { display: grid; gap: 10px; list-style: none; margin: 16px 0 0; padding: 0; }
  /* F6: mobile uses the cards sibling for rows 9..N; the desktop table
     disclosure (.fi-macro-more) stays hidden on phone so the inner table
     cannot overflow the viewport. */
  .fi-macro-cards-more { display: block; }
  .fi-macro-more { display: none; }
  .fi-conflict-pair { grid-template-columns: 1fr; }
  .fi-toc ol { flex-direction: column; gap: 4px; }
  .fi-shell { padding-left: 16px; padding-right: 16px; }
  .fi-hero h1 { font-size: var(--fs-h2); }
  .fi-exposure-cards { gap: 8px; }
}
/* Item 9: hide the cards-only "see all" disclosure at ≥768 — the desktop
   table + its sibling .fi-disc.fi-exposure-more already cover rows 9..N.
   F6: same rule for .fi-macro-cards-more — desktop table + .fi-macro-more
   already cover rows 9..N. */
@media (min-width: 768px) {
  .fi-exposure-cards-more { display: none; }
  .fi-macro-cards-more { display: none; }
}

/* reduced motion */
@media (prefers-reduced-motion: reduce) {
  .fi-drawer { transition: none; }
}
.fi-section-title, .fi-step-label, .fi-cell-role { overflow-wrap: anywhere; word-break: break-word; }

rules.new:
/* Finance Intelligence dossier — scoped theme.
   Tokens come ONLY from theme.css. No hex/rgb literals here.
   Two art directions (dark command center / light research workspace),
   each a complete material treatment. */
:root,
html[data-theme="dark"] {
  --fi-canvas:        var(--bg);
  --fi-panel:         var(--panel);
  --fi-panel2:        var(--panel2);
  --fi-line:          var(--line);
  --fi-text:          var(--text);
  --fi-muted:         var(--muted);
  --fi-link:          var(--link);
  --fi-spine:         color-mix(in srgb, var(--line) 90%, transparent);
  --fi-step-fill:     color-mix(in srgb, var(--link) 14%, var(--panel));
  --fi-step-ring:     color-mix(in srgb, var(--link) 30%, transparent);
  --fi-chip-observed: color-mix(in srgb, var(--ok)    18%, var(--panel));
  --fi-chip-watch:    color-mix(in srgb, var(--warn)  18%, var(--panel));
  --fi-chip-caution:  color-mix(in srgb, var(--info)  14%, var(--panel));
  --fi-chip-missing:  color-mix(in srgb, var(--muted) 18%, var(--panel));
  --fi-chip-stale:    color-mix(in srgb, var(--act)   16%, var(--panel));
  --fi-chip-regime:   color-mix(in srgb, var(--act)   22%, var(--panel));
}
html[data-theme="light"] {
  --fi-canvas:        var(--bg);
  --fi-panel:         var(--panel);
  --fi-panel2:        var(--panel2);
  --fi-line:          var(--line);
  --fi-text:          var(--text);
  --fi-muted:         var(--muted);
  --fi-link:          var(--link);
  --fi-spine:         color-mix(in srgb, var(--line) 90%, transparent);
  --fi-step-fill:     color-mix(in srgb, var(--link) 12%, var(--panel));
  --fi-step-ring:     var(--link);
  --fi-chip-observed: color-mix(in srgb, var(--ok)    10%, var(--panel));
  --fi-chip-watch:    color-mix(in srgb, var(--warn)  10%, var(--panel));
  --fi-chip-caution:  color-mix(in srgb, var(--info)   8%, var(--panel));
  --fi-chip-missing:  color-mix(in srgb, var(--muted)  8%, var(--panel));
  --fi-chip-stale:    color-mix(in srgb, var(--act)    8%, var(--panel));
  --fi-chip-regime:   color-mix(in srgb, var(--act)   12%, var(--panel));
}

/* Tier 1 — dark */
.fi-panel,
.fi-toc {
  background: var(--fi-panel);
  border: 1px solid var(--fi-line);
  border-radius: 12px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text) 7%, transparent);
}
/* Tier 2 — dark */
.fi-panel2,
.fi-domain,
.fi-slice,
.fi-conflict-card,
.fi-macro-card,
.fi-exposure-card,
.fi-falsifier,
.fi-constraint-row,
.fi-conflict-side {
  background: var(--fi-panel2);
  border: 1px solid var(--fi-line);
  border-radius: 10px;
}
/* Tier 1 — light */
html[data-theme="light"] .fi-panel,
html[data-theme="light"] .fi-toc {
  background: var(--fi-panel);
  border: 1px solid var(--fi-line);
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 6%, transparent),
    0 6px 20px color-mix(in srgb, var(--text) 5%, transparent);
}
/* Tier 2 — light */
html[data-theme="light"] .fi-panel2,
html[data-theme="light"] .fi-domain,
html[data-theme="light"] .fi-slice,
html[data-theme="light"] .fi-conflict-card,
html[data-theme="light"] .fi-macro-card,
html[data-theme="light"] .fi-exposure-card,
html[data-theme="light"] .fi-falsifier,
html[data-theme="light"] .fi-constraint-row,
html[data-theme="light"] .fi-hint-row,
html[data-theme="light"] .fi-conflict-side {
  background: color-mix(in srgb, var(--panel) 92%, var(--bg));
  border: 1px solid var(--fi-line);
  box-shadow: none;
}

/* Freshness remains visible in both themes, with an explicit local label. */
.fi-section-head[data-state-freshness]:not([data-state-freshness=""])::before {
  content: ""; float: left; width: 8px; height: 8px; border-radius: 50%;
  margin: .5em 8px 0 0; background: var(--fi-fresh-colour);
}
.fi-section-head[data-state-freshness="FRESH"]        { --fi-fresh-colour: var(--fresh-ok); }
.fi-section-head[data-state-freshness="FRESH"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--fresh-ok) 25%, transparent); }
.fi-section-head[data-state-freshness="AGING"]        { --fi-fresh-colour: var(--warn); }
.fi-section-head[data-state-freshness="AGING"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--warn) 25%, transparent); }
.fi-section-head[data-state-freshness="SOURCE_STALE"] { --fi-fresh-colour: var(--act); }
.fi-section-head[data-state-freshness="SOURCE_STALE"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--act) 25%, transparent); }
.fi-section-head[data-state-freshness="NO_EVIDENCE"]   { --fi-fresh-colour: var(--line); }
.fi-section-head[data-state-freshness="NO_EVIDENCE"]::before { box-shadow: 0 0 0 3px color-mix(in srgb, var(--line) 25%, transparent); }

.fi-freshness-label { color:var(--muted); font-size:11px; line-height:1.5; }

/* focus ring — dark glow halo, light solid */
.fi-shell *:focus-visible,
.fi-drawer *:focus-visible {
  outline: 1px solid var(--fi-link);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--fi-link) 30%, transparent);
  border-radius: 6px;
}
html[data-theme="light"] .fi-shell *:focus-visible,
html[data-theme="light"] .fi-drawer *:focus-visible {
  outline: 2px solid var(--fi-link);
  outline-offset: 2px;
  box-shadow: none;
}

/* drawer + scrim */
.fi-drawer {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(440px, 92vw);
  background: var(--fi-panel); border-left: 1px solid var(--fi-line);
  transform: translateX(100%);
  transition: transform .22s cubic-bezier(.2,.7,.3,1);
  display: flex; flex-direction: column; z-index: 80;
}
.fi-drawer[hidden] { display: none; }
.fi-drawer:not([hidden]) { transform: none; }
html[data-theme="light"] .fi-drawer {
  border-left: 0;
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 6%, transparent),
    0 12px 32px color-mix(in srgb, var(--text) 8%, transparent);
}
.fi-scrim { position: fixed; inset: 0; z-index: 70; background: color-mix(in srgb, var(--bg) 70%, transparent); }
html[data-theme="light"] .fi-scrim { background: color-mix(in srgb, var(--text) 35%, transparent); }

/* stepper rail/dot */
.fi-rerating-step[data-active="true"] .fi-step-dot {
  box-shadow: 0 0 0 4px var(--fi-step-ring);
  border-color: var(--fi-link);
}
.fi-rerating-steps::before {
  content: ""; position: absolute; left: 5%; right: 5%; top: 7px; height: 2px;
  background: color-mix(in srgb, var(--text) 14%, transparent);
  border-radius: 2px; z-index: 0;
}
html[data-theme="light"] .fi-rerating-step[data-active="true"] .fi-step-dot {
  box-shadow: 0 0 0 2px var(--fi-step-ring);
  background: var(--fi-step-fill);
  border-color: var(--fi-link);
}
html[data-theme="light"] .fi-rerating-steps::before {
  background: var(--line);
}

/* chip base rule */
.fi-chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 2px 8px;
  font-size: var(--fs-micro);
  font-weight: 600;
  border-radius: 999px;
  border: 1px solid var(--fi-line);
  background: var(--fi-panel);
  color: var(--fi-text);
}
/* Seat erratum (T11 round 2): :where() gives the light base zero theme specificity, so the
   per-state chip rules (0,2,0) still win over it; at (0,2,1) it painted every state chip white. */
:where(html[data-theme="light"]) .fi-chip { background: var(--fi-panel); }

/* page canvas — the page owns its canvas in both art directions. theme.css does not
   paint body, and the shell's 1200px box alone left every gutter, the nav band and
   the area below the content on the browser's white default in the dark direction. */
body.fi-page { background: var(--fi-canvas); }

/* shell + layout */
.fi-shell {
  max-width: 1200px;
  margin: 0 auto;
  padding: clamp(18px, 3vw, 36px) clamp(16px, 3vw, 28px) 80px;
  background: var(--fi-canvas);
  color: var(--fi-text);
  font-family: var(--font-ui);
  font-feature-settings: "tnum" 1, "cv11" 1;
}
.fi-hero { padding: 28px 0 22px; border-bottom: 1px solid var(--fi-line); }
.fi-kicker { font-size: var(--fs-label); letter-spacing: .09em; text-transform: uppercase; color: var(--fi-muted); margin: 0 0 8px; font-weight: 700; }
.fi-hero h1 { font-size: var(--fs-h1); font-weight: 800; letter-spacing: -.02em; margin: 0; }
.fi-deck { font-size: var(--fs-md); line-height: 1.55; margin: 8px 0 0; max-width: 70ch; color: var(--fi-text); }
/* Not connected (no endpoint bound): the hero meta chips carry no payload — hide the empty row. */
.fi-shell[data-state="not-connected"] .fi-meta { display: none; }
/* Ruling F-5 (not-connected honest shell): a calm unbuilt status panel in the
   same measure as .fi-section — hairline border, panel ground, section-title
   h2 scale, muted body — plus static hides so the page is honest with
   JavaScript off. Every mount stays in the DOM for a connected page; the
   runtime's not_connected keep list agrees (finance_intelligence.js). */
.fi-unbuilt {
  background: var(--fi-panel);
  border: 1px solid var(--fi-line);
  border-radius: var(--r-card, 12px);
  margin-top: 40px;
  padding: 20px 24px;
}
.fi-unbuilt h2 { font-size: var(--fs-h2); font-weight: 700; letter-spacing: -.01em; margin: 0; }
.fi-unbuilt p { font-size: var(--fs-md); line-height: 1.55; color: var(--fi-muted);
  margin: 8px 0 0; max-width: 75ch; }
.fi-shell[data-state="not-connected"] .fi-section:not(#company-exposure) { display: none; }
.fi-shell[data-state="not-connected"] .fi-toc { display: none; }
.fi-shell[data-state="not-connected"] .fi-provenance { display: none; }
.fi-shell[data-state="not-connected"] [data-fi-mount="notice"] { display: none; }
.fi-shell[data-state="not-connected"] #company-exposure > :not(.fi-section-head,
.fi-hint-lede, .fi-hint-roster) { display: none; }
.fi-meta { font-size: var(--fs-sm); color: var(--fi-muted); margin: 10px 0 0; display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.fi-toc { margin: 18px 0 8px; padding: 12px 16px; }
.fi-toc ol { display: flex; flex-wrap: wrap; gap: 8px 12px; margin: 0; padding: 0; list-style: none; font-size: var(--fs-sm); }
.fi-toc a, .fi-toc-evidence { color: var(--fi-text); text-decoration: none; padding: 4px 8px; border-radius: 7px; background: transparent; border: 0; cursor: pointer; font: inherit; }
.fi-toc a:hover, .fi-toc-evidence:hover { background: var(--fi-panel2); }
.fi-section { margin-top: 40px; padding: 20px 24px; }
.fi-section-title { font-size: var(--fs-h2); font-weight: 700; letter-spacing: -.01em; margin: 0 0 4px; }
.fi-section-title-answer { font-size: var(--fs-h1); font-weight: 800; letter-spacing: -.02em; }
.fi-section-eyebrow { display: block; font-size: var(--fs-sm); color: var(--fi-muted); font-weight: 400; margin-top: 2px; }
.fi-section-foot { font-size: var(--fs-sm); color: var(--fi-muted); margin: 12px 0 0; max-width: 75ch; }
.fi-section-head { padding: 4px 0; }
/* Seat erratum (T11 round 2): spec §B.1 rows are the house DecisionRow (.mx-chg-row, theme.css);
   the list drops its UA bullets and indent like the page's other lists. */
.fi-change-list { list-style: none; margin: 12px 0 0; padding: 0; }
.fi-disc { margin: 12px 0 0; padding-top: 8px; border-top: 1px solid var(--fi-line); }
.fi-disc > summary { list-style: none; cursor: pointer; padding: 4px 0; font-size: var(--fs-sm); color: var(--fi-link); }
.fi-disc > summary::-webkit-details-marker { display: none; }
.fi-disc > summary::before { content: "+"; display: inline-block; width: 1em; margin-right: 6px; color: var(--fi-muted); }
.fi-disc[open] > summary::before { content: "\2013"; }
.fi-disc > summary:focus-visible { outline: 2px solid var(--fi-link); outline-offset: 2px; }
.fi-disc > table, .fi-disc > ul { margin-top: 8px; }
/* Cards-more disclosure is now visible at every viewport by default; §C.10 hides it at ≥768. */
.fi-exposure-cards-more { display: block; }

/* W10-FIN-2 hint roster (#company-exposure): eleven RESEARCH_HINT_UNVALIDATED
   citation rows. Tier-2 surface in both themes; each row wraps instead of
   overflowing a 390px viewport. */
.fi-hint-roster { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 6px; }
/* Ruling F-5: quiet body line above the roster — the names are research
   hints under study, none confirmed. */
.fi-hint-lede { font-size: var(--fs-sm); color: var(--fi-muted); margin: 12px 0 0; }
.fi-hint-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; padding: 6px 10px; font-size: var(--fs-sm); background: var(--fi-panel2); border: 1px solid var(--fi-line); border-radius: var(--r-ctl, 8px); }
.fi-hint-symbol { color: var(--fi-text); font-weight: 600; min-width: 3.5em; }
.fi-hint-record { margin-left: auto; min-width: 0; color: var(--fi-muted); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }

/* Per-state colour map (§C.7/§C.8/D.36) — every spec-named chip carries its own selector.
   Spec covers ONLY step, slice, membership, posture, and macro-cell-state chips;
   every other chip keeps the base .fi-chip treatment and its plain word. */

/* rerating stepper */
.fi-slice-picker { margin: 12px 0 16px; display: flex; gap: 10px; align-items: center; font-size: var(--fs-sm); }
/* A native select sizes to its longest option (a real slice name pair runs
   ~440px) and a flex item never shrinks below that: at 390px the page
   scrolled sideways. It shrinks and clips its closed label instead; the
   field label keeps its width (CJK min-content is one glyph, so "切片"
   wrapped a character per line once the select could shrink). */
.fi-slice-picker > label { flex: none; }
.fi-slice-select { font: inherit; padding: 4px 8px; border-radius: var(--r-ctl, 8px); border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); min-width: 0; max-width: 100%; text-overflow: ellipsis; }
.fi-rerating-steps { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; margin: 18px 0 0; padding: 0; list-style: none; position: relative; }
.fi-rerating-step { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; text-align: center; padding: 0 6px; gap: 6px; }
.fi-step-dot { width: 12px; height: 12px; border-radius: 50%; background: var(--fi-step-fill); border: 2px solid var(--fi-line); margin-bottom: 4px; }
.fi-step-label { font-size: var(--fs-sm); font-weight: 600; color: var(--fi-text); }
.fi-step-metric { font-size: var(--fs-sm); color: var(--fi-muted); font-variant-numeric: tabular-nums; min-height: 1.4em; }
.fi-step-chip { display: inline-block; font-size: var(--fs-sm); font-weight: 600; padding: 2px 7px; border-radius: 999px; border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); }
.fi-step-clock { font-size: var(--fs-sm); color: var(--fi-muted); font-variant-numeric: tabular-nums; }
.fi-anchor-chip, .fi-history-chip, .fi-valuation-chip, .fi-price-chip, .fi-comparability-chip { display: inline-block; font-size: var(--fs-sm); font-weight: 600; padding: 2px 7px; border-radius: 999px; border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); }
.fi-step-evidence { background: transparent; border: 1px solid var(--fi-line); width: 24px; height: 24px; color: var(--fi-muted); cursor: pointer; font-size: var(--fs-sm); }
.fi-step-evidence:hover { color: var(--fi-text); border-color: var(--fi-muted); }
/* §C.5 / Item 5: coarse-pointer hit areas at 44×44 (WCAG 2.5.5 AAA). The glyph
   stays the same; padding or an inset hit-area absorbs the extra size. */
@media (pointer: coarse) {
  .fi-step-evidence,
  .fi-evidence-trigger,
  .fi-constraint-evidence {
    min-width: 44px; min-height: 44px;
  }
  .fi-view-tab { min-width: 44px; min-height: 44px; padding: 8px 12px; }
  .fi-disc > summary { min-width: 44px; min-height: 44px; padding: 8px 4px; }
  .fi-drawer-close { min-width: 44px; min-height: 44px; }
}
.fi-rerating-bridge { font-size: var(--fs-md); color: var(--fi-text); margin: 16px 0 0; max-width: 75ch; }
.fi-falsifiers { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 6px; }
.fi-falsifier { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 6px 10px; font-size: var(--fs-sm); }
.fi-falsifier-chip { font-size: var(--fs-sm); padding: 1px 7px; border-radius: 999px; border: 1px solid var(--fi-line); }
.fi-falsifier-statement { color: var(--fi-text); }
.fi-falsifier-window { color: var(--fi-muted); font-variant-numeric: tabular-nums; }
.fi-conflicts { margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--fi-line); }
.fi-conflicts-title { font-size: var(--fs-h3); font-weight: 700; margin: 0 0 8px; }
.fi-conflict-list { display: grid; gap: 10px; margin: 12px 0 0; padding: 0; list-style: none; }
.fi-conflict-card { padding: 12px 16px; }
.fi-conflict-label { font-size: var(--fs-sm); font-weight: 700; display: block; margin-bottom: 6px; }
.fi-conflict-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.fi-conflict-side { padding: 8px 10px; border-radius: 8px; border: 1px solid var(--fi-line); background: var(--fi-panel2); font-size: var(--fs-sm); }
.fi-conflict-side-statement { display: block; }
.fi-conflict-side-evidence { margin-top: 4px; font-size: var(--fs-sm); }
.fi-conflict-foot { font-size: var(--fs-sm); color: var(--fi-muted); margin: 8px 0 0; }

/* chip state colours — each maps to one plane-state token */
.fi-step-chip[data-state="OBSERVED"]    { background: var(--fi-chip-observed); }
.fi-step-chip[data-state="INFERRED"]    { background: var(--fi-chip-watch); }
.fi-step-chip[data-state="MISSING"]     { background: var(--fi-chip-missing); }
.fi-step-chip[data-state="CONFLICTING"] { background: var(--fi-chip-caution); }
.fi-step-chip[data-state="STALE"]       { background: var(--fi-chip-stale); }
.fi-step-chip[data-state="REGIME_BREAK"],
.fi-step-chip[data-state="VALUATION_ANCHOR_UNAVAILABLE"],
.fi-step-chip[data-state="PRICE_BASIS_UNQUALIFIED"] { background: var(--fi-chip-regime); }
.fi-step-chip[data-state="NOT_APPLICABLE"] { background: var(--fi-panel2); color: var(--fi-muted); }

/* atlas grid */
.fi-domain-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-top: 16px; }
.fi-domain { padding: 16px 16px 10px; }
.fi-domain-title { font-size: var(--fs-h3); font-weight: 700; margin: 0 0 8px; }
.fi-slice-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.fi-slice { display: grid; grid-template-columns: 1fr auto; gap: 6px 8px; align-items: center; padding: 6px 8px; border-radius: 8px; background: var(--fi-panel2); }
.fi-slice-name { font-size: var(--fs-sm); font-weight: 600; color: var(--fi-text); overflow-wrap: anywhere; }
.fi-slice-chip { font-size: var(--fs-sm); font-weight: 600; padding: 1px 7px; border-radius: 999px; border: 1px solid var(--fi-line); background: var(--fi-panel); color: var(--fi-text); }
.fi-slice-chip[data-state-slice="SEMANTIC_ONLY"] { background: var(--fi-chip-missing); }
.fi-slice-chip[data-state-slice="MEASURABLE"]   { background: var(--fi-chip-observed); }
.fi-slice-chip[data-state-slice="STALE"]        { background: var(--fi-chip-stale); }
.fi-slice-chip[data-state-slice="HELD_FOR_REVIEW"] { background: var(--fi-chip-watch); }
.fi-membership-chip[data-state-membership="CURRENT_MEMBERSHIP_ONLY"],
.fi-membership-chip[data-state-membership="PIT_MEMBERSHIP_INCOMPLETE"] { background: var(--fi-chip-regime); }
.fi-posture-chip[data-state-posture="SEMANTIC_ONLY"] { background: var(--fi-chip-missing); }
.fi-posture-chip[data-state-posture="RESEARCH_CANDIDATE"] { background: var(--fi-chip-caution); }
.fi-posture-chip[data-state-posture="CANDIDATE_READY_FOR_OWNER_REVIEW"] { background: var(--fi-chip-watch); }
.fi-posture-chip[data-state-posture="ADMITTED"] { background: var(--fi-chip-observed); }
.fi-slice-open { background: transparent; border: 1px solid var(--fi-line); border-radius: 6px; color: var(--fi-muted); cursor: pointer; font-size: var(--fs-sm); }
/* Seat T11 r3 (atlas composition): a slice reads name + basket count on one line and its
   chips on a full-width wrap row below. The shared `1fr auto` slice grid handed the chip
   row's max-content to the auto column and collapsed the name (overflow-wrap: anywhere)
   and the count to one character per line at every width. The count opens nothing, so it
   is muted metadata, not a bordered control. */
.fi-domain .fi-slice { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "name count" "chips chips"; align-items: baseline; }
.fi-domain .fi-slice-name { grid-area: name; }
.fi-domain .fi-slice-baskets { grid-area: count; }
.fi-domain .fi-slice-chips { grid-area: chips; }
.fi-slice-chips, .fi-macro-cell-chips { display: flex; flex-wrap: wrap; gap: 4px; }
.fi-macro-cell-chips { margin-top: 4px; }
.fi-slice-baskets { font-size: var(--fs-micro); color: var(--fi-muted); white-space: nowrap; }
.fi-atlas-gap { font-size: var(--fs-sm); color: var(--fi-muted); margin: 10px 0 0; }

/* exposure table */
.fi-exposure-table-wrap { overflow-x: auto; margin-top: 16px; }
.fi-exposure-table { border-collapse: separate; border-spacing: 0; font-size: var(--fs-sm); width: 100%; }
.fi-exposure-table th, .fi-exposure-table td { border-bottom: 1px solid var(--fi-line); padding: 8px 10px; text-align: left; vertical-align: top; }
.fi-exposure-table thead th { position: sticky; top: 0; background: var(--fi-panel); z-index: 2; font-weight: 600; color: var(--fi-muted); font-size: var(--fs-sm); text-transform: uppercase; letter-spacing: .04em; }
.fi-exposure-table .fi-col-company { position: sticky; left: 0; background: var(--fi-panel); z-index: 1; font-weight: 600; }
.fi-exposure-table thead th.fi-col-company { z-index: 3; }
.fi-cell { min-width: 0; }
.fi-cell-role { display: block; font-weight: 600; }
.fi-cell-basis { display: block; font-size: var(--fs-sm); color: var(--fi-muted); }
.fi-cell-materiality { display: block; font-size: var(--fs-sm); color: var(--fi-text); }
.fi-cell[data-state-materiality="MATERIAL"]    .fi-cell-materiality { color: var(--fi-text); font-weight: 700; }
.fi-cell[data-state-materiality="PARTIAL"]     .fi-cell-materiality { color: var(--fi-text); }
.fi-cell[data-state-materiality="IMMATERIAL"]  .fi-cell-materiality { color: var(--fi-text); }
.fi-cell[data-state-materiality="UNMEASURED"]  .fi-cell-materiality { color: var(--fi-text); }
.fi-cell-risk { display: block; font-size: var(--fs-sm); color: var(--fi-muted); margin-top: 2px; }
.fi-cell-evidence-date { display: block; font-size: var(--fs-sm); color: var(--fi-muted); margin-top: 2px; font-variant-numeric: tabular-nums; }
.fi-company-unresolved, .fi-company-hint { color: var(--fi-muted); font-style: italic; }
.fi-exposure-cards { display: none; list-style: none; margin: 16px 0 0; padding: 0; gap: 10px; }
.fi-exposure-card { padding: 12px 16px; }

/* macro matrix */
.fi-macro-table-wrap { overflow-x: auto; margin-top: 16px; }
.fi-macro-table { border-collapse: separate; border-spacing: 0; font-size: var(--fs-sm); width: 100%; }
.fi-macro-table th, .fi-macro-table td { border-bottom: 1px solid var(--fi-line); padding: 8px 10px; text-align: left; vertical-align: top; }
.fi-macro-table thead th { position: sticky; top: 0; background: var(--fi-panel); z-index: 2; font-weight: 600; color: var(--fi-muted); font-size: var(--fs-sm); }
.fi-macro-table .fi-col-company { position: sticky; left: 0; background: var(--fi-panel); z-index: 1; font-weight: 600; }
.fi-macro-cell-state { display: inline-block; font-size: var(--fs-sm); padding: 1px 7px; border-radius: 999px; border: 1px solid var(--fi-line); }
.fi-macro-cell-state[data-state="CAUSAL_EFFECT_UNMEASURED"] { background: var(--fi-chip-caution); }
.fi-macro-cell-state[data-state="NOT_APPLICABLE"] { background: var(--fi-panel2); color: var(--fi-muted); }
.fi-macro-cell-state[data-state="DESCRIBED"] { background: var(--fi-chip-observed); }

/* constraint map */
.fi-constraint-list { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 8px; }
.fi-constraint-row { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 8px 10px; font-size: var(--fs-sm); }

/* system map */
.fi-view-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin: 12px 0 16px; }
.fi-view-tab { background: var(--fi-panel); border: 1px solid var(--fi-line); color: var(--fi-text); padding: 4px 10px; border-radius: 999px; font: inherit; cursor: pointer; }
.fi-view-tab[aria-selected="true"] { background: var(--fi-step-fill); border-color: var(--fi-link); }
/* Held for T12, which draws the graph: T11 r3 renders no <svg> (it painted an empty panel). */
.fi-system-svg { width: 100%; height: 280px; background: var(--fi-panel2); border-radius: 12px; border: 1px solid var(--fi-line); }
.fi-system-edges { margin: 10px 0 0; }
.fi-system-edge-list { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 4px; font-size: var(--fs-sm); }
.fi-system-edge { padding: 4px 0; border-bottom: 1px dashed var(--fi-line); display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; }
.fi-system-edge-statement { color: var(--fi-text); }

/* drawer body */
.fi-drawer-head { padding: 16px 18px 10px; border-bottom: 1px solid var(--fi-line); display: flex; gap: 12px; align-items: flex-start; }
.fi-drawer-head .fi-kicker { margin: 0; }
.fi-drawer-head h2 { font-size: var(--fs-h2); margin: 4px 0 0; }
.fi-drawer-close { margin-left: auto; background: transparent; border: 1px solid var(--fi-line); border-radius: 6px; color: var(--fi-muted); width: 28px; height: 28px; cursor: pointer; font: inherit; }
.fi-drawer-body { padding: 12px 18px 24px; overflow-y: auto; font-size: var(--fs-sm); }
.fi-evidence-fields { display: grid; gap: 8px; margin: 0; }
.fi-evidence-fields > div { display: grid; grid-template-columns: 36% 64%; gap: 8px; padding-bottom: 6px; border-bottom: 1px dashed var(--fi-line); }
.fi-evidence-fields dt { color: var(--fi-muted); font-weight: 600; }
.fi-evidence-fields dd { margin: 0; color: var(--fi-text); word-break: break-word; }
/* Seat T11 r3: the five T1 limitations fields — page label over owner prose (lang="en"). */
.fi-limitations { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.fi-limitation-label { display: block; font-size: var(--fs-micro); font-weight: 600; color: var(--fi-muted); }
.fi-limitation-missing { color: var(--fi-muted); }
.fi-evidence-private-notice { font-size: var(--fs-sm); color: var(--fi-muted); padding: 8px 10px; border-radius: 8px; border: 1px solid var(--fi-line); background: var(--fi-panel2); margin: 0 0 10px; }

/* notice + provenance */
.fi-notice { margin: 16px 0; font-size: var(--fs-sm); color: var(--fi-muted); padding: 8px 12px; border: 1px solid var(--fi-line); border-radius: 8px; }
.fi-provenance { margin: 40px 0 0; padding: 16px 0; border-top: 1px solid var(--fi-line); font-size: var(--fs-sm); color: var(--fi-muted); display: grid; gap: 4px; }
.fi-receipt-line { display: flex; gap: 8px; align-items: center; }
.fi-receipt-line .fi-chip { background: var(--fi-chip-missing); }

/* visually-hidden helper */
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* Item 10 (SEAT-PINNED source-language marking) — a quiet line under
   sections that hold English-source prose, in ZH only (the helper strips it
   on EN). Treatment: text-only metadata line at --fs-micro, --fi-muted,
   4px top margin — never a chip, never coloured, never italic (F7). */
.fi-srclang-note { font-size: var(--fs-micro); color: var(--fi-muted); margin: 4px 0 0; }

/* responsive */
@media (min-width: 1200px) {
  .fi-shell { max-width: 1200px; }
  /* Seat T11 r3: auto-fit keeps the spec's 4-up at >=1200 without leaving one domain in a
     quarter of the panel (repeat(4, 1fr) reserved three empty tracks). */
  .fi-domain-grid { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
}
@media (min-width: 768px) and (max-width: 1199px) {
  .fi-rerating-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
  .fi-rerating-steps::before { display: none; }
  .fi-rerating-step { flex-direction: row; align-items: center; text-align: left; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--fi-panel2); border: 1px solid var(--fi-line); flex-wrap: wrap; }
  .fi-step-dot { margin: 0 6px 0 0; }
}
@media (max-width: 767px) {
  .fi-rerating-steps { grid-template-columns: 1fr; gap: 6px; }
  .fi-rerating-steps::before { display: none; }
  .fi-rerating-step { flex-direction: row; align-items: center; text-align: left; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--fi-panel2); border: 1px solid var(--fi-line); flex-wrap: wrap; }
  .fi-step-dot { margin: 0 6px 0 0; }
  .fi-domain-grid { grid-template-columns: 1fr; }
  .fi-exposure-table-wrap { display: none; }
  .fi-exposure-more { display: none; }
  .fi-exposure-cards { display: grid; }
  .fi-exposure-cards-more { display: block; }
  .fi-section { padding: 16px; }
  .fi-unbuilt { padding: 16px; }
  .fi-macro-table-wrap { display: none; }
  /* Item 9: every row stays reachable on phone. First 8 rows render in
     .fi-macro-cards; rows 9..N live inside a sibling .fi-disc .fi-macro-cards-more
     with the same card builder (no horizontal scroll at 390px). */
  .fi-macro-cards { display: grid; gap: 10px; list-style: none; margin: 16px 0 0; padding: 0; }
  /* F6: mobile uses the cards sibling for rows 9..N; the desktop table
     disclosure (.fi-macro-more) stays hidden on phone so the inner table
     cannot overflow the viewport. */
  .fi-macro-cards-more { display: block; }
  .fi-macro-more { display: none; }
  .fi-conflict-pair { grid-template-columns: 1fr; }
  .fi-toc ol { flex-direction: column; gap: 4px; }
  .fi-shell { padding-left: 16px; padding-right: 16px; }
  .fi-hero h1 { font-size: var(--fs-h2); }
  .fi-exposure-cards { gap: 8px; }
}
/* Item 9: hide the cards-only "see all" disclosure at ≥768 — the desktop
   table + its sibling .fi-disc.fi-exposure-more already cover rows 9..N.
   F6: same rule for .fi-macro-cards-more — desktop table + .fi-macro-more
   already cover rows 9..N. */
@media (min-width: 768px) {
  .fi-exposure-cards-more { display: none; }
  .fi-macro-cards-more { display: none; }
}

/* reduced motion */
@media (prefers-reduced-motion: reduce) {
  .fi-drawer { transition: none; }
}
.fi-section-title, .fi-step-label, .fi-cell-role { overflow-wrap: anywhere; word-break: break-word; }

