.fx-chip.size-add,.fx-chip.size-core{ color:var(--ink-up, var(--up)); border-color:color-mix(in srgb,var(--up) 34%,transparent); background:color-mix(in srgb,var(--up) 9%,var(--panel)); }
.fx-chip.size-starter{ color:var(--ink-info, var(--info)); border-color:color-mix(in srgb,var(--info) 34%,transparent); background:color-mix(in srgb,var(--info) 9%,var(--panel)); }
.fx-chip.size-trim,.fx-chip.size-exit,.fx-chip.exit{ color:var(--ink-down, var(--down)); border-color:color-mix(in srgb,var(--down) 38%,transparent); background:color-mix(in srgb,var(--down) 10%,var(--panel)); }
.fx-chip.conf.lit{ color:var(--ink-info, var(--info)); border-color:color-mix(in srgb,var(--info) 34%,transparent); background:color-mix(in srgb,var(--info) 9%,var(--panel)); }
.fx-chip.feed-warn{ color:var(--ink-warn, var(--warn)); border-color:color-mix(in srgb,var(--warn) 36%,transparent); background:color-mix(in srgb,var(--warn) 9%,var(--panel)); }
.fx-chip.feed-cool{ color:var(--ink-down, var(--down)); border-color:color-mix(in srgb,var(--down) 36%,transparent); background:color-mix(in srgb,var(--down) 9%,var(--panel)); }
