.c-high{ --cc:var(--up); } .c-medium{ --cc:var(--info); } .c-low{ --cc:var(--muted); }
.fx-ai-no{ font-size:11.5px; color:var(--ink-info, var(--info)); margin-top:3px; } .fx-ai-kill{ font-size:10.5px; color:var(--muted); margin-top:4px; }
