  .ff-filter-symbol { display: none; }
  .ff-topic-filter { width: 100%; }
  .ff-source-tabs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); width: 100%; }
  .ff-source-tab { min-height: 40px; padding: 6px 8px; }
