rules.old:
/* gmi.css — GMI explorer page stylesheet, ported verbatim (module rewrites only) from mockups/refs/gmi_explorer/gmi_explorer.css sections C..O per mockups/refs/gmi_explorer/SPECS.md; loads only on GMI pages, after templates/theme.css + templates/navigation-refresh.css. */

/* zh untrack (specimen section A, verbatim; page-scoped by inclusion) */
html[data-lang="zh"] :is(h1,h2,h3,.eyebrow){ letter-spacing:0; text-transform:none; }

/* specimen section-A components (mx-*), primitive values carried as var() fallbacks */
.mx-sec{ display:flex; align-items:baseline; gap:8px; margin:0 0 10px; }
.mx-sec h3, .mx-sec h2{ font-size:var(--fs-h2); font-weight:700; letter-spacing:-.01em; margin:0; }
.mx-sec .mx-asof{ margin-left:auto; color:var(--muted); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; }
.mx-tabset{ display:flex; gap:2px; border-bottom:1px solid var(--line); margin-bottom:10px; }
.mx-tabset button{ appearance:none; background:none; border:none; border-bottom:2px solid transparent;
  color:var(--muted); font:600 var(--fs-sm)/1 var(--font-ui); padding:8px 12px; cursor:pointer; min-height:40px;
  transition:color var(--t-fast,.16s) var(--ease-std,cubic-bezier(.2,0,0,1)), border-color var(--t-fast,.16s) var(--ease-std,cubic-bezier(.2,0,0,1)); }
.mx-tabset button[aria-selected="true"]{ color:var(--text); border-bottom-color:var(--link); }
.mx-disc{ border:1px solid var(--line); border-radius:var(--r-card,12px); background:var(--panel); }
.mx-disc summary{ cursor:pointer; padding:10px 14px; font-size:var(--fs-sm); font-weight:600; color:var(--text); min-height:20px; }
.mx-disc summary small{ color:var(--muted); font-weight:400; margin-left:6px; }
.mx-disc .mx-disc-body{ padding:0 14px 12px; color:var(--muted); font-size:var(--fs-sm); }
/* ---------- C. page shell ------------------------------------------------------ */
body.gmi-page{ margin:0; background:var(--bg); color:var(--text); font-family:var(--font-ui);
  font-size:var(--fs-body); line-height:1.5; -webkit-font-smoothing:antialiased; }
.gmi-page *{ box-sizing:border-box; }
.gmi-page a{ color:var(--link); text-decoration:none; }
.gmi-page :focus-visible{ outline:2px solid var(--link); outline-offset:2px; border-radius:var(--r-gmi-focus); }
.gmi-wrap{ max-width:1180px; margin:0 auto; padding:0 32px 64px; display:flex; flex-direction:column; gap:var(--sp-6,24px); }
.tnum{ font-variant-numeric:tabular-nums; }
.gmi-mono{ font-family:var(--font-mono); font-size:.92em; }

/* Tier-1 head: crumb, one h1 (<=4 words), one sentence (<=14 words), one as-of */
.gmi-head{ display:flex; align-items:flex-end; justify-content:space-between; gap:var(--sp-6,24px);
  padding:var(--sp-7,32px) 0 var(--sp-5,20px); border-bottom:1px solid var(--gmi-hair); }
.gmi-head-main{ min-width:0; }
.gmi-crumb{ margin:0 0 var(--sp-2,8px); font-size:var(--fs-label); font-weight:600; color:var(--muted);
  letter-spacing:.07em; text-transform:uppercase; display:flex; gap:6px; align-items:center; flex-wrap:wrap; }
html[data-lang="zh"] .gmi-crumb{ letter-spacing:0; text-transform:none; }
.gmi-crumb i{ font-style:normal; opacity:.5; }
.gmi-h1{ margin:0; font-size:var(--fs-h1); font-weight:700; letter-spacing:-.015em; line-height:1.15; }
.gmi-sub{ margin:var(--sp-2,8px) 0 0; font-size:var(--fs-md); color:var(--muted); max-width:62ch; }
.gmi-head-side{ display:flex; flex-direction:column; align-items:flex-end; gap:var(--sp-2,8px); flex:none; }
.gmi-asof{ font-size:var(--fs-sm); color:var(--muted); white-space:nowrap; font-variant-numeric:tabular-nums; }

/* ---------- D. survey marks: shape carries meaning, hue only reinforces --------- */
.gmi-sm{ display:inline-block; flex:none; width:var(--gmi-cell); height:var(--gmi-cell);
  border-radius:var(--r-gmi-sm); position:relative; vertical-align:-2px; }
.gmi-sm--adm { background:var(--gmi-mark); }
.gmi-sm--held{ border:2px solid var(--gmi-held);
  background:radial-gradient(circle, var(--gmi-held) 0 22%, transparent 27%); box-shadow:var(--gmi-glow-held); }
.gmi-sm--acc { border:1px solid var(--gmi-mark-faint);
  background:repeating-linear-gradient(135deg, var(--gmi-hatch) 0 1.4px, transparent 1.4px 3.6px); }
.gmi-sm--disp{ border:1px dashed var(--gmi-mark-faint); }
.gmi-sm--none{ border:1px solid var(--gmi-hair); }
.gmi-key .gmi-sm, .gmi-tally .gmi-sm, .gmi-inline .gmi-sm{ --gmi-cell:var(--gmi-cell-key); }
.gmi-sm--xl{ --gmi-cell:var(--gmi-cell-xl); border-radius:var(--r-gmi-md); }
.gmi-key{ display:flex; flex-wrap:wrap; gap:var(--sp-2,8px) var(--sp-5,20px); font-size:var(--fs-sm); color:var(--muted); }
.gmi-key span{ display:inline-flex; align-items:center; gap:7px; }

/* ---------- E. hero band: dark = luminance wash + glow; light = white card, hairline, shadow - */
.gmi-band{ border-radius:var(--r-panel,14px); background:var(--gmi-hero-wash), var(--panel);
  border:1px solid var(--gmi-hair); box-shadow:var(--gmi-elev); padding:var(--sp-5,20px); }
.gmi-band-card{ display:flex; flex-direction:column; gap:var(--sp-5,20px); }
html[data-theme="light"] .gmi-band{ background:var(--panel); border:1px solid var(--line); box-shadow:var(--gmi-elev); }

/* generic module panel */
.gmi-panel{ background:var(--panel); border:1px solid var(--gmi-hair); border-radius:var(--r-card,12px);
  box-shadow:var(--gmi-elev); padding:var(--sp-5,20px); display:flex; flex-direction:column; gap:var(--sp-3,12px); min-width:0; }
.gmi-panel--flush{ padding:0; gap:0; }
.gmi-cols{ display:flex; gap:18px; align-items:flex-start; }
.gmi-col-main{ flex:1 1 0; min-width:0; display:flex; flex-direction:column; gap:18px; }
.gmi-col-side{ flex:0 0 360px; min-width:0; display:flex; flex-direction:column; gap:18px; }
.gmi-row{ display:flex; gap:18px; align-items:stretch; }
.gmi-row > *{ flex:1 1 0; }
@media (max-width:900px){ .gmi-cols, .gmi-row{ flex-direction:column; align-items:stretch; } .gmi-col-main, .gmi-col-side{ flex:none; width:100%; } }

/* label/value lines */
.gmi-dl{ display:flex; flex-direction:column; margin:0; }
.gmi-dl > div{ display:flex; gap:var(--sp-4,16px); padding:9px 0; border-top:1px solid var(--gmi-hair); align-items:baseline; }
.gmi-dl > div:first-child{ border-top:0; }
.gmi-dl dt{ flex:0 0 132px; color:var(--muted); font-size:var(--fs-sm); }
.gmi-dl dd{ margin:0; flex:1; min-width:0; font-size:var(--fs-sm); overflow-wrap:anywhere; }
.gmi-ink-warn{ color:var(--ink-warn); } .gmi-ink-act{ color:var(--ink-act); }
.gmi-ink-info{ color:var(--ink-info); } .gmi-ink-ok{ color:var(--ink-ok); }
.gmi-muted{ color:var(--muted); }
.gmi-note{ font-size:var(--fs-sm); color:var(--muted); margin:0; }
.gmi-foot{ font-size:var(--fs-label); color:var(--muted); margin:0; }

/* tip trigger (Tier-2 lens); text lives in data-tip-en / data-tip-zh, never title= */
.gmi-tip{ appearance:none; border:1px solid var(--gmi-hair); background:transparent; color:var(--muted);
  width:20px; height:20px; border-radius:var(--r-gmi-dot); font:600 11px/1 var(--font-ui); cursor:help; padding:0;
  display:inline-flex; align-items:center; justify-content:center; vertical-align:1px; position:relative; }
.gmi-tip::after{ content:""; position:absolute; inset:-10px; }  /* 40px hit target */

/* chips */
.gmi-chip{ display:inline-flex; align-items:center; gap:6px; min-height:28px; padding:0 10px;
  border-radius:var(--r-pill,999px); font-size:var(--fs-sm); font-weight:600; white-space:nowrap;
  background:var(--panel2); color:var(--text); border:1px solid transparent; }
html[data-theme="light"] .gmi-chip{ background:var(--panel); border-color:var(--line); }
.gmi-chip svg{ width:14px; height:14px; flex:none; }
.gmi-chip small{ font-weight:400; color:var(--muted); font-size:var(--fs-label); }
.gmi-chip--upd{ color:var(--ink-info); }
.gmi-chip--ghost{ background:transparent; border-color:var(--gmi-hair); color:var(--muted); font-weight:500; }

/* buttons */
.gmi-btn{ display:inline-flex; align-items:center; justify-content:center; gap:8px; min-height:40px; padding:0 16px;
  border-radius:var(--r-btn,10px); border:1px solid var(--gmi-hair); background:var(--panel2); color:var(--text);
  font:600 var(--fs-sm)/1 var(--font-ui); cursor:pointer; white-space:nowrap; }
html[data-theme="light"] .gmi-btn{ background:var(--panel); border-color:var(--line); box-shadow:var(--gmi-btn-lift); }
.gmi-btn--quiet{ background:transparent; border-color:transparent; color:var(--link); padding:0 6px; }
html[data-theme="light"] .gmi-btn--quiet{ background:transparent; border-color:transparent; box-shadow:none; }
.gmi-btn svg{ width:16px; height:16px; }

/* ---------- F. census tally — a ledger line, not a KPI row ------------------------
   lead population | what it is made of | where the core set stands. No boxes: hairline
   rules separate the three thoughts; the lead integer is the only large number. */
.gmi-tally{ display:flex; align-items:stretch; gap:0; padding:2px 0 var(--sp-5,20px);
  border-bottom:1px solid var(--gmi-hair); }
.gmi-tally-lead{ flex:0 0 auto; display:flex; flex-direction:column; justify-content:flex-end; gap:6px; padding-right:var(--sp-6,24px); }
.gmi-tally-group{ flex:0 1 auto; min-width:0; display:flex; flex-direction:column; gap:8px;
  padding:0 var(--sp-8,44px) 0 var(--sp-6,24px); border-left:1px solid var(--gmi-hair); }
.gmi-tally-cap{ font-size:var(--fs-label); color:var(--muted); font-weight:600; letter-spacing:.06em; text-transform:uppercase; }
html[data-lang="zh"] .gmi-tally-cap{ letter-spacing:0; text-transform:none; font-size:var(--fs-sm); }
.gmi-tally-figs{ display:flex; gap:var(--sp-6,24px); align-items:flex-end; flex-wrap:wrap; }
.gmi-tally-fig{ display:flex; flex-direction:column; gap:6px; min-width:0; }
.gmi-tally-num{ font-size:var(--fs-num-lg); font-weight:700; line-height:1; font-variant-numeric:tabular-nums; letter-spacing:-.01em; }
.gmi-tally-num--lead{ font-size:var(--fs-num-xl); letter-spacing:-.02em; }
.gmi-tally-lab{ font-size:var(--fs-sm); color:var(--muted); display:flex; align-items:center; gap:7px; white-space:nowrap; }
.gmi-tally-lab--wrap{ white-space:normal; }
.gmi-tally-txt{ white-space:nowrap; }
@media (max-width:900px){
  .gmi-tally{ flex-wrap:wrap; row-gap:var(--sp-4,16px); }
  .gmi-tally-lead{ flex:1 1 100%; flex-direction:row; align-items:baseline; justify-content:flex-start; gap:10px; padding-right:0; }
  .gmi-tally-group{ flex:1 1 0; padding:0 var(--sp-4,16px) 0 0; border-left:0; }
  .gmi-tally-group + .gmi-tally-group{ padding:0 0 0 var(--sp-4,16px); border-left:1px solid var(--gmi-hair); }
}
@media (max-width:640px){
  .gmi-tally-group, .gmi-tally-group + .gmi-tally-group{ flex:1 1 100%; padding:0; border-left:0; }
  .gmi-tally-group + .gmi-tally-group{ padding-top:var(--sp-4,16px); border-top:1px solid var(--gmi-hair); }
  .gmi-tally-figs{ gap:var(--sp-5,20px); }
  .gmi-tally-num--lead{ font-size:var(--fs-h1); }
}

/* ---------- G. census survey sheet (S2 hero; the one bold move) ---------------- */
.gmi-census{ display:flex; flex-direction:column; border-radius:var(--r-card,12px); }
.gmi-cband{ display:flex; gap:var(--sp-5,20px); align-items:flex-start; padding:10px 12px; border-radius:var(--r-ctl,8px); }
html:not([data-theme="light"]) .gmi-cband:nth-child(even){ background:var(--gmi-step); }
html[data-theme="light"] .gmi-cband{ border-radius:0; }
html[data-theme="light"] .gmi-cband + .gmi-cband{ border-top:1px solid var(--line); }
.gmi-cband-label{ flex:0 0 228px; display:flex; flex-direction:column; gap:1px; min-width:0; }
.gmi-cband-name{ font-size:var(--fs-sm); font-weight:600; }
.gmi-cband-meta{ font-size:var(--fs-label); color:var(--muted); font-variant-numeric:tabular-nums; }
.gmi-cells{ flex:1 1 0; min-width:0; display:flex; flex-wrap:wrap; gap:var(--gmi-cell-gap); padding-top:2px; }
.gmi-cells-sep{ flex:none; width:1px; height:var(--gmi-cell); margin:0 calc(var(--gmi-cell-gap) + 1px); background:var(--gmi-mark-faint); }
.gmi-cband--empty .gmi-cells{ font-size:var(--fs-sm); color:var(--muted); align-items:center; gap:10px; }
.gmi-cband--empty .gmi-cells::before{ content:""; flex:0 0 48px; height:0; border-top:1px dashed var(--gmi-mark-faint); }
.gmi-cband--focus .gmi-cband-name{ color:var(--ink-info); }
html[data-gmi-lens="chain"] .gmi-census--coverage, html:not([data-gmi-lens="chain"]) .gmi-census--chain{ display:none; }
@media (max-width:640px){
  .gmi-cband{ flex-direction:column; gap:6px; padding:8px 4px; }
  .gmi-cband-label{ flex:none; width:100%; flex-direction:row; justify-content:space-between; align-items:baseline; gap:8px; }
}

/* value-chain rail (5 lanes; 'not set' is hatched, never a hidden zero) */
.gmi-rail{ display:flex; gap:4px; }
.gmi-rail-seg{ flex:1 1 0; min-width:0; display:flex; flex-direction:column; gap:6px; }
.gmi-rail-bar{ height:8px; border-radius:var(--r-gmi-md); background:var(--gmi-rail); }
html[data-theme="light"] .gmi-rail-bar{ background:var(--panel2); box-shadow:inset 0 0 0 1px var(--line); }
.gmi-rail-seg--unset .gmi-rail-bar{ background:repeating-linear-gradient(135deg, var(--gmi-hatch) 0 1.5px, transparent 1.5px 5px);
  box-shadow:inset 0 0 0 1px var(--gmi-mark-faint); }
.gmi-rail-seg--on .gmi-rail-bar{ box-shadow:var(--gmi-select); }
.gmi-rail-lab{ font-size:var(--fs-label); color:var(--muted); display:flex; justify-content:space-between; gap:6px; }
.gmi-rail-seg--on .gmi-rail-lab{ color:var(--text); font-weight:600; }

/* ---------- H. tree accordion + search + full index ----------------------------- */
.gmi-search{ display:flex; align-items:center; gap:10px; min-height:44px; padding:0 14px; border-radius:var(--r-btn,10px);
  border:1px solid var(--gmi-hair); background:var(--panel2); color:var(--muted); font-size:var(--fs-body); }
html[data-theme="light"] .gmi-search{ background:var(--panel); border-color:var(--line); box-shadow:var(--gmi-tray); }
.gmi-search svg{ width:18px; height:18px; flex:none; }
.gmi-search kbd{ margin-left:auto; font:500 var(--fs-label)/1 var(--font-mono); padding:4px 6px; border-radius:var(--r-gmi-kbd); border:1px solid var(--gmi-hair); color:var(--muted); }
.gmi-tree{ display:flex; flex-direction:column; }
.gmi-trow{ display:flex; align-items:center; gap:12px; min-height:44px; padding:6px 14px; border-top:1px solid var(--gmi-hair); }
.gmi-tree > .gmi-trow:first-child{ border-top:0; }
.gmi-trow-caret{ width:16px; height:16px; flex:none; color:var(--muted); transition:transform var(--t-fast,.16s) var(--ease-std,cubic-bezier(.2,0,0,1)); }
.gmi-trow--open > .gmi-trow-caret{ transform:rotate(90deg); }
.gmi-trow-name{ flex:1 1 auto; min-width:0; font-size:var(--fs-body); font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.gmi-trow-meta{ flex:none; font-size:var(--fs-sm); color:var(--muted); font-variant-numeric:tabular-nums; white-space:nowrap; }
.gmi-trow-strip{ flex:0 0 132px; display:flex; flex-wrap:wrap; gap:2px; --gmi-cell:var(--gmi-cell-strip); }
.gmi-trow-strip .gmi-sm{ border-radius:var(--r-gmi-xs); }
.gmi-trow--l2{ padding-left:42px; background:var(--gmi-step); }
.gmi-trow--l2 .gmi-trow-name{ font-weight:500; }
.gmi-trow--l3{ padding-left:70px; min-height:40px; }
.gmi-trow--l3 .gmi-trow-name{ font-weight:400; font-size:var(--fs-sm); }
.gmi-trow--more .gmi-trow-name{ color:var(--link); font-weight:600; font-size:var(--fs-sm); }
.gmi-trow--empty .gmi-trow-name{ color:var(--muted); font-weight:500; white-space:normal; }
@media (max-width:640px){ .gmi-trow-name{ white-space:normal; display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:2; line-height:1.3; } }
@media (max-width:640px){
  .gmi-trow{ padding:6px 10px; gap:10px; }
  .gmi-trow-strip{ display:none; }
  .gmi-trow--l2{ padding-left:30px; } .gmi-trow--l3{ padding-left:46px; }
}
/* S2 index: one disclosure per category. Desktop opens all (a board); <=640 opens the first (a list of 10). */
.gmi-index-group{ display:block; }
.gmi-index-h{ position:sticky; top:0; z-index:2; display:flex; align-items:center; gap:10px; min-height:48px; padding:6px 12px;
  background:var(--panel); border-bottom:1px solid var(--gmi-hair); cursor:pointer; list-style:none; }
.gmi-index-h::-webkit-details-marker{ display:none; }
.gmi-index-hn{ flex:1 1 auto; min-width:0; font-size:var(--fs-body); font-weight:700; }
.gmi-index-hc{ flex:none; font-size:var(--fs-label); color:var(--muted); font-variant-numeric:tabular-nums; }
.gmi-index-h > b{ flex:none; min-width:2.2em; text-align:right; font-size:var(--fs-sm); font-variant-numeric:tabular-nums; }
.gmi-index-h > svg{ flex:none; color:var(--muted); transition:transform .16s ease; }
.gmi-index-group[open] > .gmi-index-h > svg{ transform:rotate(90deg); }
.gmi-index-group:not([open]) > .gmi-index-h{ border-bottom:0; }
.gmi-index-h:focus-visible{ outline:2px solid var(--link); outline-offset:-2px; }
.gmi-index-t{ display:flex; justify-content:space-between; gap:8px; padding:12px 12px 4px; font-size:var(--fs-label); font-weight:600;
  color:var(--muted); letter-spacing:.06em; text-transform:uppercase; }
.gmi-index-t small{ font-variant-numeric:tabular-nums; letter-spacing:0; }
