/* ---------- J. S3 relationship card, magnitude history, ledger thread, paths ---- */
.gmi-rel-head{ display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.gmi-party{ font-size:var(--fs-md); font-weight:700; }
