.gmi-hist{ display:flex; align-items:flex-end; gap:10px; height:96px; margin-left:auto; }
.gmi-hist-col{ display:flex; flex-direction:column; align-items:center; justify-content:flex-end; gap:5px; width:44px; height:100%; }
.gmi-hist-bar{ width:100%; border-radius:var(--r-gmi-bar-top); background:var(--gmi-hist-bar); }
.gmi-hist-col--now .gmi-hist-bar{ background:var(--gmi-mark); }
