.gmi-hist-v{ font-size:var(--fs-label); font-weight:600; font-variant-numeric:tabular-nums; }
.gmi-hist-p{ font-size:var(--fs-micro); color:var(--muted); font-variant-numeric:tabular-nums; }
@media (max-width:640px){ .gmi-hist{ margin-left:0; width:100%; justify-content:space-between; } .gmi-hist-col{ width:auto; flex:1; } }
.gmi-quote{ margin:0; padding:12px 14px; border-radius:var(--r-ctl,8px); background:var(--panel2); font-size:var(--fs-sm); line-height:1.55; }
html[data-theme="light"] .gmi-quote{ background:var(--panel2); }
.gmi-quote-lead{ display:block; font-size:var(--fs-label); color:var(--muted); margin-bottom:4px; }
.gmi-thread{ display:flex; flex-direction:column; gap:0; margin:0; padding:0; list-style:none; }
.gmi-thread li{ display:flex; gap:12px; position:relative; padding:0 0 14px; font-size:var(--fs-sm); line-height:1.5; }
.gmi-thread li::before{ content:""; position:absolute; left:4.5px; top:14px; bottom:0; width:1px; background:var(--gmi-hair); }
html[data-theme="light"] .gmi-thread li::before{ background:var(--line); }
.gmi-thread li:last-child{ padding-bottom:0; } .gmi-thread li:last-child::before{ display:none; }
.gmi-node{ flex:none; width:10px; height:10px; border-radius:var(--r-gmi-dot); margin-top:5px; background:var(--gmi-mark); }
.gmi-node--re{ background:transparent; box-shadow:inset 0 0 0 1.5px var(--gmi-mark); }
.gmi-node--am{ background:transparent; box-shadow:inset 0 0 0 1.5px var(--ink-info); }
.gmi-thread time{ display:block; font-size:var(--fs-label); color:var(--muted); font-variant-numeric:tabular-nums; }
/* round 2: documented paths moved to section O (.gmi-chain) */
.gmi-species{ display:flex; flex-wrap:wrap; gap:8px; }
.gmi-spec{ display:inline-flex; align-items:center; gap:8px; min-height:40px; padding:0 14px; border-radius:var(--r-pill,999px);
  border:1px solid var(--gmi-hair); font-size:var(--fs-sm); color:var(--muted); background:transparent; }
.gmi-spec b{ color:var(--text); font-variant-numeric:tabular-nums; }
