.gmi-spec--zero b{ color:var(--muted); font-weight:500; }

/* ---------- K. S4 coverage receipts -------------------------------------------- */
.gmi-cov{ display:flex; flex-direction:column; gap:var(--sp-5,20px); }
.gmi-cov-row{ display:flex; flex-direction:column; gap:8px; }
.gmi-cov-top{ display:flex; align-items:baseline; gap:12px; flex-wrap:wrap; }
.gmi-cov-mkt{ font-size:var(--fs-md); font-weight:700; min-width:96px; }
.gmi-cov-num{ font-size:var(--fs-num-lg); font-weight:700; font-variant-numeric:tabular-nums; line-height:1; }
.gmi-cov-den{ font-size:var(--fs-sm); color:var(--muted); font-variant-numeric:tabular-nums; }
.gmi-track{ position:relative; height:10px; border-radius:var(--r-gmi-md); background:var(--gmi-track); overflow:visible; }
