.gmi-stack{ display:flex; height:10px; border-radius:var(--r-gmi-md); overflow:hidden; gap:2px; }
.gmi-stack > i{ display:block; height:100%; min-width:3px; }
.gmi-stack .s1, .gmi-legend .s1{ background:repeating-linear-gradient(135deg, var(--gmi-hatch) 0 1.5px, transparent 1.5px 4.5px); box-shadow:inset 0 0 0 1px var(--gmi-mark-faint); }
.gmi-stack .s2, .gmi-legend .s2{ background:var(--gmi-stack-2); }
.gmi-stack .s3, .gmi-legend .s3{ background:var(--gmi-mark-faint); }
.gmi-legend{ display:flex; flex-wrap:wrap; gap:6px 18px; margin-top:8px; font-size:var(--fs-sm); color:var(--muted); }
