}

/* ---------- P. per-surface rules (one anchored block per W2 lane; edit only your own) ---------- */
/* == gmi:s2 (W2A) == */
/* W2A conversions of the specimen's S2 inline styles (build_specimens.py lines
   305/346/355/400) plus the tree's one new depth level. */
.gmi-note--chain{ padding:8px 12px 0; }
.gmi-trow-caret--mark{ display:flex; align-items:center; justify-content:center; }
.gmi-panel--bare{ box-shadow:none; }
/* The `hidden` attribute must win over every .gmi-* display rule (.gmi-trow is flex):
   collapsed tree rows, filtered index rows and no-match notes carry `hidden`. */
[class*="gmi-"][hidden]{ display:none; }
/* l4: micro-themes under a sub-theme — one step deeper than l3 (70px -> 98px; 62px at <=640). */
.gmi-trow--l4{ padding-left:98px; min-height:40px; }
.gmi-trow--l4 .gmi-trow-name{ font-weight:400; font-size:var(--fs-sm); }
@media (max-width:640px){ .gmi-trow--l4{ padding-left:62px; } }
/* == /gmi:s2 == */
/* == gmi:s1s5 (W2B) == */
/* S1: the specimen's head identity line carried inline margin-bottom:6px (s1_issuer). */
.gmi-ident--head{ margin-bottom:6px; }
/* S5: conversions of the specimen's non-data inline styles (R7), one class each. */
.gmi-state-ic{ display:flex; }
.gmi-mini-row{ display:flex; gap:10px; align-items:center; }
.gmi-mini-lab{ flex:0 0 110px; }
.gmi-state-mag{ display:flex; align-items:baseline; gap:10px; }
.gmi-mag-num--lg{ font-size:var(--fs-num-lg); }
.gmi-skel-stack{ display:flex; flex-direction:column; gap:10px; }
/* == /gmi:s1s5 == */
/* == gmi:s3s4 (W2C) == */
/* The specimen's non-data inline styles as classes (R7): lead notes, the S3
   ident line, the wide hero caption, the flush stack note, the S4 strong
   figures, the excerpt footer gap, and the numerator fill (zero was the only
   state the specimen drew). */
.gmi-note--lead{ color:var(--text); font-weight:600; }
.gmi-note--flush{ margin-top:4px; }
.gmi-foot--gap{ margin-top:8px; }
.gmi-ident-st{ font-weight:600; font-size:var(--fs-sm); }
.gmi-mag-cap--wide{ max-width:none; }
.gmi-tally-lab--strong{ color:var(--text); }
.gmi-num-strong{ color:var(--text); }
.gmi-track-fill{ position:absolute; left:0; top:0; bottom:0; min-width:2px;
  border-radius:var(--r-gmi-md); background:var(--gmi-mark); }
/* == /gmi:s3s4 == */

