rules.old:
/* Progressive dossier and device-local research controls for Government Revenue. */
.dossier-book{display:grid;gap:8px}
.dossier-status{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 10px;border:1px solid var(--gr-line);border-radius:8px;background:linear-gradient(115deg,color-mix(in srgb,var(--gr-accent) 7%,transparent),transparent 62%)}
.dossier-status b{font-size:9px}
.dossier-status span{display:block;color:var(--gr-muted);font-size:7.8px}
.dossier-count{color:var(--gr-accent)!important;font:750 8px var(--gr-mono)!important;white-space:nowrap}
.award-card{width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:10px;border:1px solid var(--gr-line);border-radius:9px;background:var(--gr-raised);text-align:left;cursor:pointer}
.award-card:hover{border-color:color-mix(in srgb,var(--gr-accent) 50%,var(--gr-line));transform:translateY(-1px)}
.award-card strong{display:block;font-size:9.5px;line-height:1.35}
.award-card small{display:block;margin-top:4px;color:var(--gr-muted);font-size:7.8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.award-money{text-align:right;color:var(--gr-accent);font:750 9px var(--gr-mono);white-space:nowrap}
.award-money small{color:var(--gr-faint);font:7px var(--gr-font)}
.dossier-empty{padding:18px 12px;border:1px dashed var(--gr-line2);border-radius:9px;text-align:center;color:var(--gr-muted);font-size:8.5px}
.dossier-nav{display:flex;align-items:center;justify-content:space-between;gap:8px}
.dossier-detail h3{margin:7px 0 3px;font-size:13px;line-height:1.25}
.dossier-detail-id{color:var(--gr-accent);font:8px var(--gr-mono);overflow-wrap:anywhere}
.semantic-values{display:grid;grid-template-columns:repeat(3,1fr);margin-top:10px;border:1px solid var(--gr-line);border-radius:8px;overflow:hidden}
.semantic-values div{padding:8px;border-right:1px solid var(--gr-line)}
.semantic-values div:last-child{border:0}
.semantic-values span{display:block;color:var(--gr-faint);font-size:6.8px;text-transform:uppercase}
.semantic-values b{display:block;margin-top:3px;font:750 8.5px var(--gr-mono)}
.action-tape{display:grid;gap:5px;margin-top:9px}
.action-row{display:grid;grid-template-columns:74px minmax(0,1fr) auto;gap:8px;align-items:center;padding:8px;border-left:2px solid var(--gr-accent);background:var(--gr-raised);font-size:7.8px}
.action-row time{color:var(--gr-muted);font:7.5px var(--gr-mono)}
.action-row strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dual-clock{display:block;margin-top:2px;color:var(--gr-faint);font-size:6.8px}
.dossier-error{border-left:2px solid var(--gr-warn);padding:9px 10px;background:color-mix(in srgb,var(--gr-warn) 6%,transparent);color:var(--gr-muted);font-size:8px}
.mobile-summary{display:none}
.drawer-backdrop{position:fixed;z-index:990;inset:0;background:rgba(3,8,14,.6);backdrop-filter:blur(4px)}
.evidence-drawer{position:fixed;z-index:991;right:0;top:0;bottom:0;width:min(520px,92vw);background:var(--panel);border-left:1px solid var(--gr-line2);box-shadow:-30px 0 80px -42px rgba(0,0,0,.9);overflow:auto}
.drawer-head{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:17px 18px;border-bottom:1px solid var(--gr-line);background:color-mix(in srgb,var(--panel) 94%,transparent);backdrop-filter:blur(18px)}
.drawer-head strong{font-size:12px;min-width:0;overflow-wrap:anywhere}
.drawer-head .tool-btn{flex-shrink:0;white-space:nowrap}
.drawer-body{padding:17px 18px 35px}
.receipt{padding:12px 0;border-bottom:1px solid var(--gr-line)}
.receipt:first-child{padding-top:0}
.receipt-kind{color:var(--gr-accent);font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.1em}
.receipt h3{margin:6px 0;font-size:11px}
.receipt p{margin:0;color:var(--gr-muted);font-size:9px;line-height:1.55}
.receipt-code{margin-top:8px;padding:8px;border-radius:6px;background:var(--gr-raised);font:8px/1.5 var(--gr-mono);color:var(--gr-muted);overflow-wrap:anywhere}
.gr-shell.dossier-open .shell-body{grid-template-columns:216px minmax(0,1fr)}
.gr-shell.dossier-open .queue-pane{display:none}
.gr-shell.dossier-open .inspector-pane{grid-column:2;height:638px;border-right:0}
.filter-pane{height:638px;overflow:auto}
.briefcase{display:grid;gap:7px}
.briefcase .filter-label{margin-bottom:1px}
.briefcase-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:5px}
.briefcase-actions{display:grid;grid-template-columns:1fr 1fr;gap:5px}
.briefcase .tool-btn{min-height:29px;padding:5px 7px}
.briefcase-status{min-height:30px;padding:7px 8px;border-left:2px solid var(--gr-blue);background:color-mix(in srgb,var(--gr-blue) 6%,transparent);color:var(--gr-muted);font-size:7.8px;line-height:1.45}
.briefcase-status.warn{border-color:var(--gr-warn)}
.briefcase-count{display:inline-grid;min-width:17px;height:17px;place-items:center;margin-left:4px;border-radius:99px;background:color-mix(in srgb,var(--gr-accent) 13%,transparent);color:var(--gr-accent);font:750 7px var(--gr-mono)}
.subaward-ledger{display:grid;gap:9px;margin-top:15px;padding:13px;border:1px solid var(--gr-line2);border-radius:11px;background:linear-gradient(145deg,color-mix(in srgb,var(--gr-raised) 58%,transparent),transparent 78%)}
.subaward-coverage{display:grid;grid-template-columns:minmax(150px,.42fr) minmax(0,1fr);gap:12px;align-items:center;padding:9px 10px;border-left:2px solid var(--gr-faint);border-radius:6px;background:color-mix(in srgb,var(--gr-raised) 72%,transparent)}
.subaward-coverage strong{font-size:9px}
.subaward-coverage span{color:var(--gr-muted);font-size:8px;line-height:1.4}
.subaward-coverage.ok{border-color:var(--gr-good)}
.subaward-coverage.ok strong{color:var(--gr-good)}
.subaward-coverage.warn{border-color:var(--gr-warn);background:color-mix(in srgb,var(--gr-warn) 6%,transparent)}
.subaward-coverage.warn strong{color:var(--gr-warn)}
.subaward-coverage.muted strong{color:var(--gr-muted)}
.subaward-tools{display:grid;grid-template-columns:minmax(220px,.62fr) minmax(260px,1fr);gap:13px;align-items:end}
.subaward-tools label{display:grid;gap:5px;color:var(--gr-faint);font-size:7.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase}
.subaward-table-wrap{overflow-x:auto;border:1px solid var(--gr-line);border-radius:8px}
.subaward-table{width:100%;min-width:720px;border-collapse:collapse;table-layout:fixed;font-size:8px}
.subaward-table caption{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.subaward-table th{padding:7px 8px;border-bottom:1px solid var(--gr-line2);background:var(--gr-raised);color:var(--gr-faint);font-size:6.9px;letter-spacing:.07em;text-align:left;text-transform:uppercase}
.subaward-table th:nth-child(1){width:25%}
.subaward-table th:nth-child(2){width:16%}
.subaward-table th:nth-child(3){width:14%}
.subaward-table th:nth-child(4){width:35%}
.subaward-table th:nth-child(5){width:10%}
.subaward-table td{padding:9px 8px;border-bottom:1px solid var(--gr-line);vertical-align:top;overflow-wrap:anywhere}
.subaward-table tr:last-child td{border-bottom:0}
.subaward-table tbody tr:hover{background:color-mix(in srgb,var(--gr-accent) 4%,transparent)}
.subaward-table td strong,.subaward-table td small{display:block}
.subaward-table td strong{font-size:8.5px}
.subaward-table td small{margin-top:3px;color:var(--gr-faint);font-size:6.8px}
.subaward-table td:nth-child(2) b{color:var(--gr-accent);font:750 8px var(--gr-mono)}
.subaward-table td:nth-child(3){color:var(--gr-muted);font-family:var(--gr-mono)}
.subaward-table .tool-btn{min-height:26px;padding:4px 7px}
.subaward-pager{display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--gr-muted);font:7.5px var(--gr-mono)}
.subaward-pager>span:last-child{display:flex;gap:5px}
.subaward-pager .tool-btn:disabled{cursor:not-allowed;opacity:.42}
.idv-relationships{display:grid;gap:9px;margin-top:15px;padding:13px;border:1px solid var(--gr-line2);border-radius:11px;background:linear-gradient(145deg,color-mix(in srgb,var(--gr-blue) 8%,transparent),transparent 78%)}
.idv-coverage{display:grid;grid-template-columns:minmax(150px,.42fr) minmax(0,1fr);gap:12px;align-items:center;padding:9px 10px;border-left:2px solid var(--gr-faint);border-radius:6px;background:color-mix(in srgb,var(--gr-raised) 72%,transparent)}
.idv-coverage strong{font-size:9px}.idv-coverage span{color:var(--gr-muted);font-size:8px;line-height:1.4}.idv-coverage.ok{border-color:var(--gr-blue)}.idv-coverage.ok strong{color:var(--gr-blue)}.idv-coverage.warn{border-color:var(--gr-warn);background:color-mix(in srgb,var(--gr-warn) 6%,transparent)}.idv-coverage.warn strong{color:var(--gr-warn)}.idv-coverage.muted strong{color:var(--gr-muted)}
.idv-list{display:grid;gap:6px}.idv-relationship{display:grid;gap:7px;padding:10px;border:1px solid var(--gr-line);border-radius:8px;background:var(--gr-raised)}.idv-relationship:hover{border-color:color-mix(in srgb,var(--gr-blue) 48%,var(--gr-line))}.idv-relationship-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.idv-relationship-top .tool-btn{min-height:24px;padding:3px 7px}.idv-relationship>strong{color:var(--gr-blue);font:750 8.5px var(--gr-mono);overflow-wrap:anywhere}.idv-relationship-meta{display:flex;justify-content:space-between;gap:8px;color:var(--gr-muted);font-size:7.4px;line-height:1.45}.idv-relationship-meta span:last-child{font-family:var(--gr-mono);white-space:nowrap}
.budget-inspector{position:relative}.budget-hero{background:linear-gradient(125deg,color-mix(in srgb,var(--gr-blue) 12%,transparent),color-mix(in srgb,var(--gr-accent) 5%,transparent) 58%,transparent)}.budget-loading{display:grid;place-items:center;gap:9px;min-height:270px;padding:30px;text-align:center;border:1px solid var(--gr-line);background:radial-gradient(circle at 50% 0,color-mix(in srgb,var(--gr-blue) 15%,transparent),transparent 54%)}.budget-loading strong{font-size:10px}.budget-loading small{color:var(--gr-muted);font-size:8px}.budget-scan{width:31px;height:31px;border:2px solid color-mix(in srgb,var(--gr-blue) 28%,transparent);border-top-color:var(--gr-blue);border-radius:99px;animation:budget-spin 1.1s linear infinite}.budget-amounts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border:1px solid var(--gr-line);border-radius:10px;overflow:hidden}.budget-amount{display:grid;gap:4px;min-height:76px;padding:10px;border-right:1px solid var(--gr-line);border-bottom:1px solid var(--gr-line);background:var(--gr-raised)}.budget-amount:nth-child(2n){border-right:0}.budget-amount:nth-last-child(-n+2){border-bottom:0}.budget-amount span,.budget-amount small{color:var(--gr-faint);font-size:6.9px;letter-spacing:.05em;text-transform:uppercase}.budget-amount b{font:750 11px var(--gr-mono)}.budget-amount.primary{background:linear-gradient(145deg,color-mix(in srgb,var(--gr-accent) 13%,var(--gr-raised)),var(--gr-raised))}.budget-amount.primary b{color:var(--gr-accent)}.budget-amount small{letter-spacing:0;text-transform:none}
.budget-coverage{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.budget-rail{display:grid;gap:3px;min-height:74px;padding:9px;border-left:2px solid var(--gr-faint);border-radius:7px;background:var(--gr-raised)}.budget-rail span{color:var(--gr-faint);font-size:7px;letter-spacing:.06em;text-transform:uppercase}.budget-rail b{font:750 8px var(--gr-font)}.budget-rail small{color:var(--gr-muted);font-size:7.2px;line-height:1.35}.budget-rail.ok{border-color:var(--gr-good)}.budget-rail.ok b{color:var(--gr-good)}.budget-rail.warn{border-color:var(--gr-warn);background:color-mix(in srgb,var(--gr-warn) 6%,transparent)}.budget-rail.warn b{color:var(--gr-warn)}.budget-rail.muted b{color:var(--gr-muted)}
.budget-lines,.budget-bridges{display:grid;gap:7px}.budget-line-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;padding:10px;border:1px solid var(--gr-line);border-radius:8px;background:var(--gr-raised)}.budget-line-card>div:first-child{min-width:0}.budget-line-tag{display:table;margin-bottom:5px;color:var(--gr-blue);font:750 6.8px var(--gr-mono);letter-spacing:.06em}.budget-line-card strong,.budget-line-card small{display:block}.budget-line-card strong{font-size:8.8px}.budget-line-card small{margin-top:3px;color:var(--gr-muted);font-size:7px}.budget-line-card>div:nth-child(2){align-self:center;text-align:right}.budget-line-card>div:nth-child(2) b{color:var(--gr-accent);font:750 8.5px var(--gr-mono)}.budget-line-card>code{grid-column:1/-1;color:var(--gr-faint);font:6.8px var(--gr-mono);overflow-wrap:anywhere}.budget-bridge{display:grid;gap:5px;padding:9px;border-left:2px solid var(--gr-blue);background:color-mix(in srgb,var(--gr-blue) 5%,transparent)}.budget-bridge strong{font:750 8.5px var(--gr-mono)}.budget-bridge small,.budget-null,.budget-boundary span{color:var(--gr-muted);font-size:8px;line-height:1.45}.budget-null{padding:11px;border:1px dashed var(--gr-line2);border-radius:8px}.budget-null strong,.budget-null span{display:block}.budget-null span{margin-top:4px}.budget-boundary{display:grid;gap:5px;padding:10px;border-left:2px solid var(--gr-warn);background:color-mix(in srgb,var(--gr-warn) 6%,transparent)}.budget-boundary strong{font-size:8.8px;color:var(--gr-warn)}
/* Identity Atlas. The rail is the section's one loud device: a vertical chain whose
   connector is solid where the recipient-to-issuer path is reviewed and DASHED where
   it stops, with a hollow node on the unresolved rung. A broken path is therefore
   legible before a word is read, and an unresolved hop can never be mistaken for a
   minted one. Everything around it reuses the page's existing chip / card / receipt
   vocabulary — no second design language. */
.identity-atlas{display:grid;gap:9px;padding:13px;border:1px solid var(--gr-line2);border-radius:11px;background:linear-gradient(145deg,color-mix(in srgb,var(--gr-good) 7%,transparent),transparent 74%)}
.identity-atlas.is-unresolved{background:linear-gradient(145deg,color-mix(in srgb,var(--gr-warn) 7%,transparent),transparent 74%)}
.identity-atlas.is-historic{background:linear-gradient(145deg,color-mix(in srgb,var(--gr-line2) 60%,transparent),transparent 74%)}
.atlas-question{margin:0;color:var(--gr-muted);font-size:8.4px;line-height:1.45}
.atlas-chips{display:flex;flex-wrap:wrap;gap:5px}
.atlas-chain{display:grid;margin:2px 0 0;padding:0;list-style:none}
.atlas-hop{position:relative;display:grid;grid-template-columns:15px minmax(0,1fr);column-gap:9px;padding-bottom:12px;color:var(--gr-faint)}
.atlas-hop:last-child{padding-bottom:0}
.atlas-hop.reviewed{color:var(--gr-good)}
.atlas-hop.conflict{color:var(--gr-bad)}
.atlas-hop.historic{color:var(--gr-muted)}
.atlas-node{grid-column:1;grid-row:1/span 3;width:9px;height:9px;margin-top:3px;border:1.5px solid currentColor;border-radius:50%;background:currentColor;box-shadow:0 0 0 3px color-mix(in srgb,currentColor 12%,transparent)}
.atlas-hop.unresolved .atlas-node{border-style:dashed;background:transparent;box-shadow:none}
.atlas-hop.historic .atlas-node{position:relative;background:transparent}
.atlas-hop.historic .atlas-node:after{content:"";position:absolute;left:-2px;right:-2px;top:2px;height:1.5px;background:currentColor;transform:rotate(-45deg)}
.atlas-hop:after{content:"";position:absolute;left:4px;top:15px;bottom:-3px;width:0;border-left:1.5px solid currentColor;opacity:.5}
.atlas-hop:last-child:after{display:none}
.atlas-hop.break:after{border-left-style:dashed;border-left-color:var(--gr-faint);opacity:.9}
.atlas-rung{grid-column:2;color:inherit;font-size:6.9px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.atlas-fact{grid-column:2;margin-top:2px;color:var(--text);font-size:9px;font-weight:720;line-height:1.35;overflow-wrap:anywhere}
.atlas-hop.historic .atlas-fact,.atlas-hop.unresolved .atlas-fact{color:var(--gr-muted)}
.atlas-note{grid-column:2;margin-top:2px;color:var(--gr-muted);font-size:7.4px;line-height:1.45}
.atlas-read{margin:0;color:var(--gr-ink);font-size:8.8px;line-height:1.6;overflow-wrap:anywhere}
.atlas-sub{margin-top:3px;color:var(--gr-faint);font-size:7.2px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.atlas-entities,.atlas-unresolved,.atlas-history{display:grid;gap:6px}
.atlas-entity{display:grid;gap:6px;padding:10px;border:1px solid var(--gr-line);border-left:2px solid var(--gr-good);border-radius:8px;background:var(--gr-raised)}
.atlas-entity.derived{border-left-color:var(--gr-warn)}
.atlas-entity.historic{border-left-color:var(--gr-faint)}
.atlas-entity-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}
.atlas-entity-top>div{min-width:0}
.atlas-entity-name{display:block;font-size:8.8px;font-weight:750;line-height:1.35}
.atlas-entity-meta{display:block;margin-top:3px;color:var(--gr-muted);font-size:7.4px;line-height:1.45}
.atlas-gap{display:grid;gap:5px;padding:9px 10px;border-left:2px solid var(--gr-warn);border-radius:6px;background:color-mix(in srgb,var(--gr-warn) 7%,transparent)}
.atlas-gap.conflict{border-left-color:var(--gr-bad);background:color-mix(in srgb,var(--gr-bad) 7%,transparent)}
.atlas-gap-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}
.atlas-gap-top>.truth,.atlas-entity-top>.truth{flex:none;max-width:none}
.atlas-gap-top>strong{min-width:0}
.atlas-gap strong{font-size:8.5px;line-height:1.35;overflow-wrap:anywhere}
.atlas-gap>span{color:var(--gr-muted);font-size:7.8px;line-height:1.5}
.atlas-gap .source-link{margin-top:0;padding:6px 8px;font-size:7.8px}
.atlas-event{display:grid;grid-template-columns:auto minmax(0,1fr);gap:9px;align-items:start;padding:8px 9px;border:1px solid var(--gr-line);border-radius:7px}
.atlas-event>div{min-width:0}
.atlas-event time{padding-top:1px}
.atlas-event time{color:var(--gr-faint);font:7.4px var(--gr-mono);white-space:nowrap}
.atlas-event span{color:var(--gr-muted);font-size:7.8px;line-height:1.45}
.atlas-event .source-link{margin-top:5px}
.atlas-open{margin:0;padding-left:14px;color:var(--gr-muted);font-size:7.8px;line-height:1.55}
.atlas-open li+li{margin-top:3px}
.atlas-asof{color:var(--gr-faint);font:7.4px var(--gr-mono)}
.atlas-receipt{border:1px dashed var(--gr-line2);border-radius:7px;background:color-mix(in srgb,var(--gr-raised) 50%,transparent)}
.atlas-receipt>summary{padding:7px 9px;list-style:none;cursor:pointer;color:var(--gr-muted);font-size:7.4px;font-weight:750}
.atlas-receipt>summary::-webkit-details-marker{display:none}
.atlas-receipt>summary:before{content:"+";margin-right:6px;color:var(--gr-accent);font:750 9px var(--gr-mono)}
.atlas-receipt[open]>summary:before{content:"–"}
.atlas-receipt>summary:hover{color:var(--text)}
.atlas-receipt-body{display:grid;gap:6px;padding:0 9px 9px}
.atlas-id{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:baseline;padding:5px 0;border-bottom:1px solid var(--gr-line)}
.atlas-id:last-of-type{border-bottom:0}
.atlas-id code{color:var(--gr-accent);font:750 7.8px var(--gr-mono);overflow-wrap:anywhere}
.atlas-id b{color:var(--gr-muted);font-size:6.8px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap}
.atlas-code{padding:8px;border-radius:6px;background:var(--gr-raised);color:var(--gr-muted);font:7.4px/1.55 var(--gr-mono);white-space:pre-wrap;overflow-wrap:anywhere}
/* Light is a design target, not a token swap (DESIGN_DOCTRINE §5.8): on white the
   dark-first "raised card inside a tinted panel" inverts — the card lands DARKER than
   its canvas and the depth reads as flatness. Light therefore gets an opaque tinted
   panel with genuinely white cards on top, the same cure the estate light pass used. */
html[data-theme="light"] .identity-atlas{background:linear-gradient(145deg,color-mix(in srgb,var(--gr-good) 9%,#fff),color-mix(in srgb,var(--gr-good) 2%,#fff) 78%)}
html[data-theme="light"] .identity-atlas.is-unresolved{background:linear-gradient(145deg,color-mix(in srgb,var(--gr-warn) 9%,#fff),color-mix(in srgb,var(--gr-warn) 2%,#fff) 78%)}
html[data-theme="light"] .identity-atlas.is-historic{background:linear-gradient(145deg,color-mix(in srgb,var(--gr-muted) 8%,#fff),color-mix(in srgb,var(--gr-muted) 2%,#fff) 78%)}
html[data-theme="light"] .atlas-entity,html[data-theme="light"] .atlas-event,html[data-theme="light"] .atlas-receipt,html[data-theme="light"] .identity-atlas .source-link{background:#fff}
html[data-theme="light"] .atlas-code{background:#f2f4f7}
/* zh headings drop tracking (MASTER_PRODUCT_DESIGN_SYSTEM §13) — CJK does not letterspace. */
html[data-lang="zh"] .atlas-rung,html[data-lang="zh"] .atlas-sub{letter-spacing:0}
@keyframes budget-spin{to{transform:rotate(360deg)}}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:620px){
  .subaward-ledger{padding:10px}
  .subaward-coverage,.subaward-tools,.idv-coverage{grid-template-columns:1fr}
  .subaward-table-wrap{border:0;overflow:visible}
  .subaward-table{display:block;min-width:0}
  .subaward-table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
  .subaward-table tbody{display:grid;gap:8px}
  .subaward-table tr{display:block;padding:5px 9px;border:1px solid var(--gr-line);border-radius:8px;background:var(--gr-raised)}
  .subaward-table td{display:grid;grid-template-columns:104px minmax(0,1fr);gap:8px;padding:6px 0;border-bottom:1px solid var(--gr-line);font-family:var(--gr-font)!important}
  .subaward-table td:before{content:attr(data-label);color:var(--gr-faint);font-size:6.8px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}
  .subaward-table td:last-child{border-bottom:0}
  .subaward-table .tool-btn{justify-self:start}
  .subaward-pager{align-items:flex-start;flex-direction:column}
  .subaward-pager>span:last-child{width:100%}
  .subaward-pager .tool-btn{flex:1}
  .identity-atlas{padding:10px}
  .atlas-entity-top,.atlas-gap-top{display:grid;gap:5px;justify-items:start}
  .atlas-id{grid-template-columns:minmax(0,1fr)}
  .atlas-event{grid-template-columns:minmax(0,1fr);gap:4px}
  .idv-relationships{padding:10px}.idv-relationship-meta{display:grid;gap:3px}.idv-relationship-meta span:last-child{white-space:normal}.budget-amounts,.budget-coverage{grid-template-columns:1fr}.budget-amount,.budget-amount:nth-child(2n),.budget-amount:nth-last-child(-n+2){border-right:0;border-bottom:1px solid var(--gr-line)}.budget-amount:last-child{border-bottom:0}.budget-line-card{grid-template-columns:minmax(0,1fr)}.budget-line-card>div:nth-child(2){text-align:left}.budget-line-card>code{grid-column:auto}
}

rules.new:
/* Progressive dossier and device-local research controls for Government Revenue. */
.dossier-book{display:grid;gap:8px}
.dossier-status{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 10px;border:1px solid var(--gr-line);border-radius:8px;background:linear-gradient(115deg,color-mix(in srgb,var(--gr-accent) 7%,transparent),transparent 62%)}
.dossier-status b{font-size:9px}
.dossier-status span{display:block;color:var(--gr-muted);font-size:7.8px}
.dossier-count{color:var(--gr-accent)!important;font:750 8px var(--gr-mono)!important;white-space:nowrap}
.award-card{width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:10px;border:1px solid var(--gr-line);border-radius:9px;background:var(--gr-raised);text-align:left;cursor:pointer}
.award-card:hover{border-color:color-mix(in srgb,var(--gr-accent) 50%,var(--gr-line));transform:translateY(-1px)}
.award-card strong{display:block;font-size:9.5px;line-height:1.35}
.award-card small{display:block;margin-top:4px;color:var(--gr-muted);font-size:7.8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.award-money{text-align:right;color:var(--gr-accent);font:750 9px var(--gr-mono);white-space:nowrap}
.award-money small{color:var(--gr-faint);font:7px var(--gr-font)}
.dossier-empty{padding:18px 12px;border:1px dashed var(--gr-line2);border-radius:9px;text-align:center;color:var(--gr-muted);font-size:8.5px}
.dossier-nav{display:flex;align-items:center;justify-content:space-between;gap:8px}
.dossier-detail h3{margin:7px 0 3px;font-size:13px;line-height:1.25}
.dossier-detail-id{color:var(--gr-accent);font:8px var(--gr-mono);overflow-wrap:anywhere}
.semantic-values{display:grid;grid-template-columns:repeat(3,1fr);margin-top:10px;border:1px solid var(--gr-line);border-radius:8px;overflow:hidden}
.semantic-values div{padding:8px;border-right:1px solid var(--gr-line)}
.semantic-values div:last-child{border:0}
.semantic-values span{display:block;color:var(--gr-faint);font-size:6.8px;text-transform:uppercase}
.semantic-values b{display:block;margin-top:3px;font:750 8.5px var(--gr-mono)}
.action-tape{display:grid;gap:5px;margin-top:9px}
.action-row{display:grid;grid-template-columns:74px minmax(0,1fr) auto;gap:8px;align-items:center;padding:8px;border:1px solid var(--line);background:var(--gr-raised);font-size:7.8px}
.action-row time{color:var(--gr-muted);font:7.5px var(--gr-mono)}
.action-row strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dual-clock{display:block;margin-top:2px;color:var(--gr-faint);font-size:6.8px}
.dossier-error{border:1px solid var(--line);padding:9px 10px;background:var(--surface-warn-subtle,var(--panel2,var(--card)));color:var(--gr-muted);font-size:8px}
.mobile-summary{display:none}
.drawer-backdrop{position:fixed;z-index:990;inset:0;background:rgba(3,8,14,.6);backdrop-filter:blur(4px)}
.evidence-drawer{position:fixed;z-index:991;right:0;top:0;bottom:0;width:min(520px,92vw);background:var(--panel);border-left:1px solid var(--gr-line2);box-shadow:-30px 0 80px -42px rgba(0,0,0,.9);overflow:auto}
.drawer-head{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:17px 18px;border-bottom:1px solid var(--gr-line);background:color-mix(in srgb,var(--panel) 94%,transparent);backdrop-filter:blur(18px)}
.drawer-head strong{font-size:12px;min-width:0;overflow-wrap:anywhere}
