.dossier-error{border-left:2px solid var(--gr-warn);padding:9px 10px;background:color-mix(in srgb,var(--gr-warn) 6%,transparent);color:var(--gr-muted);font-size:8px}
.mobile-summary{display:none}
.drawer-backdrop{position:fixed;z-index:990;inset:0;background:rgba(3,8,14,.6);backdrop-filter:blur(4px)}

rules.new:
.semantic-values b{display:block;margin-top:3px;font:750 8.5px var(--gr-mono)}
