rules.old:
  * { box-sizing: border-box; }
  body { background: var(--bg); color: var(--text); font: 14px/1.5 -apple-system,
         "Segoe UI", Roboto, Helvetica, sans-serif; margin: 0; padding: 26px 18px 18px; }
  @media (min-width: 1100px) { body { padding: 26px max(40px, calc((100vw - 1500px) / 2)); } }
  html[data-lang="zh"] body { font-family: "PingFang SC","Hiragino Sans GB","Microsoft YaHei","Noto Sans CJK SC",-apple-system,sans-serif; }
  a { text-decoration: none; color: var(--ink-link, var(--link)); }
  h1 { font-size: 21px; margin: 0 0 2px; color: var(--text); }
  h2 { font-size: 13px; margin: 0 0 10px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
  .grid { display: grid; gap: 14px; grid-template-columns: repeat(12, 1fr); }
  .panel { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 15px 17px; }
  .span12 { grid-column: span 12; } .span8 { grid-column: span 8; }
  .span6 { grid-column: span 6; } .span4 { grid-column: span 4; }
  @media (max-width: 900px) { .span8, .span6, .span4 { grid-column: span 12; } }

  /* regime hero */
  .hero { display: flex; flex-wrap: wrap; align-items: center; gap: 18px; }
  .quad-badge { font-size: 22px; font-weight: 800; padding: 8px 18px; border-radius: 13px; color: #fff; }
  .quad-Q1 { background: var(--q1); } .quad-Q2 { background: var(--q2); color: #1a1a1a; }
  .quad-Q3 { background: var(--q3); } .quad-Q4 { background: var(--q4); }
  .metric { display: flex; flex-direction: column; gap: 1px; }
  .metric .v { font-size: 18px; font-weight: 700; color: var(--text); }
  .metric .k { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
  .chip { display: inline-block; padding: 3px 11px; border-radius: 12px; font-weight: 600; font-size: 12.5px;
          background: color-mix(in srgb, var(--c, var(--muted)) 16%, var(--panel));
          color: color-mix(in srgb, var(--c, var(--muted)) 82%, var(--text)); }
  .c-up { --c: var(--up); } .c-down { --c: var(--down); } .c-warn { --c: var(--warn); }
  .c-info { --c: var(--info); } .c-muted { --c: var(--muted); }

  /* global-risk-beta regime tilt (amplifiers vs cushions) */
  .gb-tilt { display:inline-block; font-size:11px; font-weight:700; padding:2px 8px;
             border-radius:9px; border:1px solid var(--line); white-space:nowrap; }
  .gb-favored { background:color-mix(in srgb,var(--up) 16%,transparent); color:var(--ink-up, var(--up));
                border-color:color-mix(in srgb,var(--up) 40%,transparent); }
  .gb-exposed { background:color-mix(in srgb,var(--down) 16%,transparent); color:var(--ink-down, var(--down));
                border-color:color-mix(in srgb,var(--down) 40%,transparent); }
  .gb-lag,.gb-neutral { background:var(--panel2,var(--panel)); color:var(--muted); }
  /* consolidated stock-screener: segmented mode toggle (parallels china.html) */
  .sb-seg { display:inline-flex; flex-wrap:wrap; gap:4px; padding:4px; border-radius:11px;
            background:var(--panel2,color-mix(in srgb,var(--muted) 10%,var(--panel)));
            border:1px solid var(--line); margin:2px 0 14px; }
  .sb-seg button { font:inherit; font-size:12.5px; font-weight:600; cursor:pointer;
            border:1px solid transparent; background:transparent; color:var(--muted);
            padding:6px 13px; border-radius:8px; line-height:1.2; transition:all .14s ease;
            white-space:nowrap; }
  .sb-seg button:hover { color:var(--text); }
  .sb-seg button[aria-selected="true"] { background:var(--panel); color:var(--text);
            border-color:var(--line); box-shadow:var(--popover-shadow,0 1px 3px rgba(0,0,0,.12)); }
  .sb-cap { margin:0 0 12px; text-transform:none; line-height:1.55; }
  .sb-table th.th-sort { cursor:pointer; user-select:none; }
  .sb-table th.th-sort:hover { color:var(--text); }
  .sb-table th.sorted { color:var(--text); }
  .sb-table .sarrow { font-size:9px; opacity:.32; margin-left:3px; font-weight:700; }
  .sb-table th.sorted .sarrow { opacity:.9; color:var(--ink-link, var(--link)); }

  /* global risk overlay (HK-specific) */
  .risk-badge { font-size: 20px; font-weight: 800; padding: 7px 16px; border-radius: 12px;
                background: color-mix(in srgb, var(--c, var(--muted)) 20%, var(--panel));
                color: color-mix(in srgb, var(--c, var(--muted)) 88%, var(--text)); }
  .peg-wrap { margin: 14px 0 4px; }
  .peg-gauge { position: relative; height: 8px; border-radius: 5px; margin: 7px 0 4px;
               background: linear-gradient(90deg, var(--up) 0%, color-mix(in srgb, var(--muted) 60%, var(--panel)) 50%, var(--down) 100%); }
  .peg-marker { position: absolute; top: -4px; width: 4px; height: 16px; border-radius: 3px;
                background: var(--text); transform: translateX(-50%); box-shadow: 0 0 0 2px var(--panel); }
  .peg-ends { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--muted); }
  .factor-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 7px 14px; margin-top: 12px; }
  .factor { display: flex; align-items: center; gap: 7px; font-size: 12.5px; }
  .factor .dot { width: 9px; height: 9px; border-radius: 50%; flex: 0 0 auto;
                 background: color-mix(in srgb, var(--c, var(--muted)) 85%, transparent); }
  .factor .fz { margin-left: auto; font-variant-numeric: tabular-nums; color: var(--muted); font-weight: 600; }

  /* regime hero: growth/inflation gauges + quad map + meaning (US/China parity) */
  .herogauges { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 22px; max-width: 600px; margin: 18px 0 2px; }
  .hg-l { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; margin-bottom: 6px; }
  .hg-l .hv { font-variant-numeric: tabular-nums; }
  .qmeaning { font-size: 13.5px; line-height: 1.55; margin: 16px 0 2px; color: var(--text); }
  .regwatch { font-size: 13px; font-weight: 600; margin: 8px 0 0; padding: 7px 11px; border-radius: 9px;
              background: color-mix(in srgb, var(--warn) 14%, var(--panel)); color: color-mix(in srgb, var(--warn) 88%, var(--text)); }
  .qmap { display: grid; grid-template-columns: 92px 1fr 1fr; gap: 8px; margin: 18px 0 4px; }
  .qmap .ax { font-size: 11px; color: var(--muted); display: flex; align-items: center; justify-content: center; text-align: center; line-height: 1.3; }
  .qmap .cell { border-radius: 12px; padding: 14px 18px; color: #fff; font-weight: 700; font-size: 16px; opacity: .4;
                display: flex; flex-direction: column; justify-content: center; min-height: 132px; transition: opacity .15s; }
  .qmap .cell small { display: block; font-weight: 500; font-size: 11.5px; opacity: .92; margin-top: 6px; line-height: 1.4; }
  .qmap .cell.cur { opacity: 1; box-shadow: inset 0 0 0 2px var(--text); }
  @media (max-width: 900px) { .qmap .cell { min-height: 92px; font-size: 14px; } }
  .qmap .q1 { background: var(--q1); } .qmap .q2 { background: var(--q2); color: #1a1a1a; }
  .qmap .q3 { background: var(--q3); } .qmap .q4 { background: var(--q4); }

  table { border-collapse: collapse; width: 100%; font-size: 13px; }
  th, td { text-align: right; padding: 5px 8px; border-bottom: 1px solid var(--line); }
  th { color: var(--muted); font-weight: 500; }
  th:first-child, td:first-child, td.l, th.l { text-align: left; }
  .pos { color: var(--ink-up, var(--up)); } .neg { color: var(--ink-down, var(--down)); }
  .lad { display: inline-block; padding: 1px 9px; border-radius: 10px; font-size: 11.5px; font-weight: 700;
         background: color-mix(in srgb, var(--c, var(--muted)) 16%, var(--panel));
         color: color-mix(in srgb, var(--c, var(--muted)) 82%, var(--text)); }
  .lad.up { --c: var(--up); } .lad.down { --c: var(--down); } .lad.flat { --c: var(--muted); }
  .agechip { font-size: 10.5px; font-weight: 700; color: var(--muted); white-space: nowrap; margin-left: 5px; }
  .note { font-size: 12.5px; color: var(--muted); line-height: 1.6; }
  .sub { font-size: 11.5px; color: var(--muted); }
  .mtf-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
  .mtf-card .mtf-name { font-weight: 700; font-size: 13.5px; margin-bottom: 6px; color: var(--text); }
  h3 { font-size: 12.5px; margin: 12px 0 6px; color: var(--text); }

  /* ---- playbook: lifespan bar + next-quad odds + exposure dial -------------- */
  .lifebar { position: relative; height: 16px; border-radius: 8px; overflow: hidden; margin: 12px 0 3px; background: var(--panel2); }
  .lifebar .zone { position: absolute; top: 0; height: 100%; }
  .lifebar .marker { position: absolute; top: -2px; height: calc(100% + 4px); width: 3px; background: var(--text); border-radius: 2px; box-shadow: 0 0 0 1px var(--panel); }
  .lifelabels { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--muted); }
  .prob { display: flex; align-items: center; gap: 9px; margin: 7px 0; }
  .prob .nm { flex: 0 0 96px; font-size: 12.5px; font-weight: 600; }
  .prob .bar { flex: 1; height: 14px; background: var(--panel2); border-radius: 7px; overflow: hidden; }
  .prob .bar i { display: block; height: 100%; border-radius: 7px; }
  .prob .pc { flex: 0 0 38px; text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; }
  .pdial { display: flex; gap: 4px; margin: 6px 0 12px; }
  .pdial > span { flex: 1; text-align: center; font-size: 11.5px; font-weight: 700; padding: 7px 4px; border-radius: 8px;
                background: var(--panel2); color: var(--muted); border: 1px solid var(--line); }
  .pdial .on-def { background: color-mix(in srgb, var(--down) 80%, var(--panel)); color: #fff; border-color: transparent; }
  .pdial .on-car { background: color-mix(in srgb, var(--warn) 75%, var(--panel)); color: #1a1a1a; border-color: transparent; }
  .pdial .on-neu { background: color-mix(in srgb, var(--muted) 55%, var(--panel)); color: var(--text); border-color: transparent; }
  .pdial .on-con { background: color-mix(in srgb, var(--up) 62%, var(--panel)); color: #fff; border-color: transparent; }
  .pdial .on-agg { background: color-mix(in srgb, var(--up) 88%, var(--panel)); color: #fff; border-color: transparent; }
  .reason { display: flex; align-items: flex-start; gap: 8px; font-size: 12.5px; margin: 5px 0; line-height: 1.45; }
  .sig { flex: none; width: 17px; height: 17px; border-radius: 50%; font-size: 11px; font-weight: 800; line-height: 17px; text-align: center; }
  .sig-p { background: color-mix(in srgb, var(--up) 22%, var(--panel)); color: var(--ink-up, var(--up)); }
  .sig-m { background: color-mix(in srgb, var(--down) 22%, var(--panel)); color: var(--ink-down, var(--down)); }
  .sig-i { background: color-mix(in srgb, var(--muted) 22%, var(--panel)); color: var(--muted); }
  .pcard { background: var(--panel2); border: 1px solid var(--line); border-radius: 9px; padding: 7px 10px; margin: 6px 0; font-size: 12.5px; }
  .calltag { display: inline-block; font-size: 10px; font-weight: 700; padding: 1px 7px; border-radius: 8px; margin-right: 6px; text-transform: uppercase; letter-spacing: .03em; }
  .tag-pref { background: color-mix(in srgb, var(--info) 18%, var(--panel)); color: color-mix(in srgb, var(--info) 85%, var(--text)); }
  .tag-lead { background: color-mix(in srgb, var(--up) 18%, var(--panel)); color: color-mix(in srgb, var(--up) 85%, var(--text)); }
  .tag-avoid { background: color-mix(in srgb, var(--down) 18%, var(--panel)); color: color-mix(in srgb, var(--down) 85%, var(--text)); }
  .help { display:inline-flex; align-items:center; justify-content:center; width:15px; height:15px; border-radius:50%;
          border:1px solid var(--muted); color:var(--muted); font-size:10px; font-weight:600; cursor:help; position:relative; vertical-align:middle; margin-left:4px; }
  .help .tip { display:none; position:absolute; bottom:140%; left:50%; transform:translateX(-50%); width:330px; background:var(--panel);
               border:1px solid var(--line); padding:9px 11px; border-radius:8px; z-index:60; font-size:12px; line-height:1.45; color:var(--text);
               font-weight:400; text-transform:none; letter-spacing:normal; box-shadow:var(--popover-shadow);
               max-height:min(60vh,420px); overflow-y:auto; overscroll-behavior:contain; }
  /* invisible hover pad across the icon→tip gap — keeps :hover alive mid-travel (on .help, not .tip: the tip is a scroll container and clips its pseudos) */
  .help:hover::before { content:''; position:absolute; bottom:100%; left:-30px; right:-30px; height:10px; }
  .help:hover .tip { display:block; }
  .stat-row { display:flex; flex-wrap:wrap; gap:18px; align-items:baseline; margin:2px 0 10px; }
  .stat-row .v { font-size:22px; font-weight:800; color:var(--text); }
  /* .stat-row .v is more specific than the generic .pos/.neg — restate direction color
     at higher specificity so flow/premium stats read green/red (and zh-flip via tokens) */
  .stat-row .v.pos { color: var(--ink-up, var(--up)); } .stat-row .v.neg { color: var(--ink-down, var(--down)); }
  table.sortable th.th-sort { cursor: pointer; user-select: none; }
  table.sortable th.sorted { color: var(--text); }
  table.sortable th .sarrow { font-size: 9px; opacity: .32; margin-left: 3px; font-weight: 700; }
  table.sortable th.sorted .sarrow { opacity: .9; color: var(--ink-link, var(--link)); }

  /* ---- regime time machine (timemachine.js) -------------------------------- */
  #time-machine .tm-wrap { position: relative; margin: 4px 0 2px; }
  .tm-canvas { display: block; width: 100%; height: 56px; cursor: ew-resize; border-radius: 8px; touch-action: none; }
  .tm-range { -webkit-appearance: none; appearance: none; width: 100%; height: 16px; background: transparent; margin: 2px 0 0; cursor: ew-resize; }
  .tm-range::-webkit-slider-runnable-track { height: 4px; border-radius: 2px; background: var(--line); }
  .tm-range::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 16px; height: 16px; margin-top: -6px; border-radius: 50%; background: var(--text); border: 2px solid var(--panel); box-shadow: 0 1px 4px rgba(0,0,0,.35); }
  .tm-range::-moz-range-thumb { width: 14px; height: 14px; border-radius: 50%; background: var(--text); border: 2px solid var(--panel); }
  .tm-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin: 8px 0 12px; }
  .tm-presets { display: inline-flex; flex-wrap: wrap; gap: 6px; }
  .tm-btn { font: inherit; font-size: 12px; font-weight: 600; color: var(--text); background: var(--panel2); border: 1px solid var(--line); border-radius: 7px; padding: 5px 11px; cursor: pointer; }
  .tm-btn:hover { border-color: var(--link); }
  .tm-play { display: inline-flex; align-items: center; gap: 7px; }
  .tm-play-ico { width: 0; height: 0; border-style: solid; border-width: 6px 0 6px 10px; border-color: transparent transparent transparent var(--text); }
  .tm-play.is-playing .tm-play-ico { width: 9px; height: 11px; border: none; border-left: 3px solid var(--text); border-right: 3px solid var(--text); }
  .tm-readout { background: var(--panel2); border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; }
  .tm-asof { display: flex; align-items: baseline; gap: 10px; margin-bottom: 9px; }
  .tm-date { font-size: 17px; font-weight: 700; font-variant-numeric: tabular-nums; }
  .tm-state-tag { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; padding: 2px 8px; border-radius: 10px; }
  .tm-state-tag.is-live { color: var(--ink-ok, var(--ok)); background: var(--wash-ok); }
  .tm-state-tag.is-hist { color: var(--muted); background: color-mix(in srgb, var(--muted) 16%, var(--panel)); }
  .tm-badges { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
  .tm-gauges { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 22px; margin: 12px 0 4px; }
  @media (max-width: 640px) { .tm-gauges { grid-template-columns: 1fr; } }
  .tm-glabel { display: flex; justify-content: space-between; font-size: 12.5px; font-weight: 600; margin-bottom: 4px; font-variant-numeric: tabular-nums; }
  .tm-flags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
  .badge { display: inline-block; padding: 3px 11px; border-radius: 11px; font-weight: 700; font-size: 12.5px; }
  /* per-quad ink/fill matrix — same recipe as dashboard.html.j2 small badges
     (13px needs 4.5:1; green/gold carry near-black ink, blue/light-green deepen
     the fill; zh rules after light so the q1/q3 hue swap wins ties). */
  .badge.quad-Q1 { background: var(--q1); color: #1a1a1a; } .badge.quad-Q2 { background: var(--q2); color: #1a1a1a; }
  .badge.quad-Q3 { background: var(--q3); color: #fff; } .badge.quad-Q4 { background: var(--q4); color: #fff; }
  html:not([data-theme="light"]) .badge.quad-Q4 { background: color-mix(in srgb, var(--q4) 88%, var(--bg)); }
  html[data-theme="light"] .badge.quad-Q1 { background: color-mix(in srgb, var(--q1) 90%, var(--text)); color: #fff; }
  html[data-lang="zh"] .badge.quad-Q1 { background: var(--q1); color: #fff; }
  html[data-lang="zh"] .badge.quad-Q3 { color: #1a1a1a; }
  html[data-theme="light"][data-lang="zh"] .badge.quad-Q3 { background: color-mix(in srgb, var(--q3) 90%, var(--text)); color: #fff; }
  .badge.state-STABLE { background: color-mix(in srgb, var(--muted) 16%, var(--panel)); color: color-mix(in srgb, var(--muted) 82%, var(--text)); }
  .kv { font-size: 12.5px; color: var(--muted); } .kv b { color: var(--text); font-variant-numeric: tabular-nums; }
  .gauge { position: relative; height: 6px; border-radius: 3px; background: linear-gradient(90deg, var(--down), var(--line) 50%, var(--up)); }
  .gauge i { position: absolute; top: 50%; width: 12px; height: 12px; border-radius: 50%; background: var(--text); border: 2px solid var(--panel); transform: translate(-50%,-50%); }
  .foot { margin-top: 26px; color: var(--muted); font-size: 12px; text-align: center; line-height: 1.7; }
  /* nav split-dropdown (macro / stocks / lookup) */
  .nav-dd { position: relative; }
  .nav-dd .caret { font-size: 9px; opacity: .6; }
  .nav-dd-menu { position: absolute; top: calc(100% + 6px); left: 0; min-width: 210px; background: var(--panel);
    border: 1px solid var(--line); border-radius: 11px; box-shadow: 0 12px 34px rgba(0,0,0,.28); padding: 6px;
    opacity: 0; visibility: hidden; transform: translateY(-6px); transition: opacity .16s, transform .16s, visibility .16s; z-index: 70; }
  .nav-dd:hover > .nav-dd-menu, .nav-dd:focus-within > .nav-dd-menu { opacity: 1; visibility: visible; transform: translateY(0); }
  .nav-dd-menu a { display: block; padding: 7px 10px; border-radius: 8px; font-size: 13px; color: var(--muted); text-decoration: none; white-space: nowrap; }
  .nav-dd-menu a:hover, .nav-dd-menu a.active { background: var(--panel2); color: var(--text); }
  /* ---- standout-stock cards (mirror of the US dashboard) -------------------- */
  .nch { display: block; width: 100%; margin: 7px 0 5px; border-radius: 5px; background: var(--panel2); }
  .nbgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(196px, 1fr)); gap: 10px; margin-top: 11px; }
  /* mobile: pack the standout cards 2-up so the list doesn't scroll on and on (paired with the
     3-row cap via data-showmore-rows + theme.js). Cards are already overflow-guarded + compact. */
  @media (max-width:680px){
    .nbgrid[data-showmore-rows]{ grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; }
    .nbgrid[data-showmore-rows] .nb-tk{ font-size:13px; }
    .nbgrid[data-showmore-rows] .nb-px{ font-size:12px; }
    /* let the header wrap so the signal badge + price drop to a new line instead of being
       clipped by the card's overflow:hidden when the column is this narrow. */
    .nbgrid[data-showmore-rows] .nb-top{ flex-wrap:wrap; row-gap:2px; }
  }
  a.nbcard { background: var(--panel2); border: 1px solid var(--line); border-radius: 10px;
            padding: 9px 11px 10px; position: relative; overflow: hidden;
            display: flex; flex-direction: column; gap: 4px; color: var(--text);
            transition: transform .12s, box-shadow .12s, border-color .12s; }
  a.nbcard:hover { transform: translateY(-2px); box-shadow: 0 5px 18px rgba(0,0,0,.22); border-color: var(--link); }
  /* state accent as a TOP gradient stripe (RIPENING-shelf idiom) — not a left border.
     position/clip live on .nbcard (not a.nbcard): div.nbcard variants (venue-demand
     picks) must contain their own absolute stripe, else it escapes to an ancestor. */
  .nbcard { position: relative; overflow: hidden; }
  .nbcard::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px; pointer-events: none;
                    background: linear-gradient(90deg, var(--muted), transparent); opacity: .6; }
  .nbcard.nb-up::before { background: linear-gradient(90deg, var(--up), color-mix(in srgb, var(--up) 30%, transparent)); opacity: 1; }
  .nbcard.nb-down::before { background: linear-gradient(90deg, var(--down), color-mix(in srgb, var(--down) 30%, transparent)); opacity: 1; }
  .nbcard.nb-caution::before { background: linear-gradient(90deg, var(--warn), color-mix(in srgb, var(--warn) 30%, transparent)); opacity: 1; }
  .nb-top { display: flex; align-items: baseline; gap: 6px; }
  .nb-tk { font-weight: 800; font-size: 14px; color: var(--text); letter-spacing: .01em; }
  .nb-nm { font-size: 10px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; min-width: 0; }
  .nb-px { font-weight: 700; font-size: 13px; color: var(--text); font-variant-numeric: tabular-nums; white-space: nowrap; }
  .nb-sub { display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); }
  /* ripe-list card lead (§7.1) + group / entry-window / port chips (§5.0) */
  .nb-lead { font-size: 11px; line-height: 1.45; color: var(--fg); margin: 5px 0 3px; font-weight: 600; }
  .nb-ripe { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; margin: 0 0 3px; }
  .nb-ripe span { font-size: 9px; font-weight: 800; padding: 1px 6px; border-radius: 7px; letter-spacing: .01em; border: 1px solid var(--line); }
  .nb-grp.grp-open { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 40%, var(--line)); background: color-mix(in srgb, var(--up) 10%, var(--panel)); }
  .nb-grp.grp-set { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 40%, var(--line)); background: color-mix(in srgb, var(--warn) 9%, var(--panel)); }
  .nb-ewin { color: var(--muted); }
  .nb-ewin.ew-open-now { color: var(--ink-up, var(--up)); }
  .nb-port.pt-wash { color: var(--ink-link, var(--link)); border-color: color-mix(in srgb, var(--link) 35%, var(--line)); }
  .nb-port.pt-ext { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 35%, var(--line)); }
  /* data-health banner (§5.5) */
  .health-banner { border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--line)); background: color-mix(in srgb, var(--warn) 8%, var(--panel)); }
  .health-banner .hb-h { margin: 0 0 4px; font-weight: 800; color: var(--ink-warn, var(--warn)); text-transform: none; }
  .health-banner .hb-list { margin: 0; padding-left: 18px; }
  .health-banner .hb-item { font-size: 11.5px; line-height: 1.6; color: var(--fg); }
  /* freshness sentinel — stale = loud red panel; degraded = one thin amber line */
  .hk-fresh-stale { border: 1px solid color-mix(in srgb, var(--act) 50%, var(--line)); background: color-mix(in srgb, var(--act) 7%, var(--panel)); }
  .hk-fresh-stale .hb-h { margin: 0 0 5px; font-weight: 800; color: var(--ink-act, var(--act)); text-transform: none; }
  .hk-fresh-stale .hb-msg { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--fg); }
  .hk-fresh-stale .hb-exp { margin: 4px 0 0; font-size: 11px; color: var(--muted); }
  .hk-fresh-degraded { display: flex; align-items: center; gap: 6px; padding: 7px 12px; border-radius: 8px; font-size: 12px; line-height: 1.4;
    color: color-mix(in srgb, var(--warn) 85%, var(--fg)); border: 1px solid color-mix(in srgb, var(--warn) 40%, var(--line)); background: color-mix(in srgb, var(--warn) 7%, var(--panel)); }
  .hk-fresh-degraded .hfd-i { color: var(--ink-warn, var(--warn)); font-size: 13px; }
  .nbcard .nch { background: transparent; margin: 4px 0 2px; }
  .nb-bot { display: flex; align-items: center; gap: 6px; margin-top: 1px; }
  .nb-state { font-size: 10px; font-weight: 800; letter-spacing: .02em; padding: 1px 7px; border-radius: 8px; }
  .nb-up .nb-state { color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 15%, var(--panel)); }
  .nb-down .nb-state { color: var(--ink-down, var(--down)); background: color-mix(in srgb, var(--down) 15%, var(--panel)); }
  .nb-caution .nb-state { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 15%, var(--panel)); }
  .nb-alpha { display: flex; align-items: center; gap: 6px; font-size: 9.5px; margin-top: 2px; flex-wrap: wrap; }
  .nb-az { font-weight: 800; font-variant-numeric: tabular-nums; padding: 0 5px; border-radius: 7px;
           background: var(--panel); border: 1px solid var(--line); color: var(--muted); }
  .nb-az.az-up { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 38%, var(--line)); }
  .nb-az.az-dn { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 38%, var(--line)); }
  .nb-rk { color: var(--muted); font-variant-numeric: tabular-nums; }
  .nb-ent { font-weight: 700; padding: 0 5px; border-radius: 7px; }
  .ent-good { color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 14%, var(--panel)); }
  .ent-warn { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 16%, var(--panel)); }
  /* dark-zh: red-on-red-tint lands at 4.41:1 on the 14% tint; thin to 8% (W3 lever). */
  html[data-lang="zh"]:not([data-theme="light"]) .ent-good { background: color-mix(in srgb, var(--up) 8%, var(--panel)); }

  /* ═══ HK BOARD RESURRECTION — priority display layer (hk_prophet_v1, 2026-08-02) ═══
     research/HK_BOARD_RESURRECTION_MASTERPLAN_BY_FABLE.md §0 G1/G4/G9.

     PORTED, NOT DESIGNED. Every rule below is the shipped US board's (#4331,
     templates/dashboard.html.j2) with the panel id swapped — same tokens, same
     geometry, same interaction, same words for the same states. HK is the third
     board on this idiom; a third dialect of it would cost the reader more than
     it could ever buy. The only HK-specific decision is WHAT the theme slot
     names (the hk_leadership cohort, fenced display-tier — see the marks row).

     Everything here renders ONLY when the artifact carries row.stage. A pre-v1
     hk_standouts.json (which is every artifact until the first nightly after the
     engine lane merges) takes the untouched flat path and renders unchanged.

     ── stage-bucket headings ────────────────────────────────────────────────
     The board's PRIMARY structure, so they carry more presence than a hairline:
     a coloured left bar plus a tint fading out to the right. The bar is the
     non-verbal encoding of the bucket and the label IS the stance — "Live now",
     "Ran — don't chase" are complete instructions on their own. --sgc carries
     the tone so one rule set serves all five buckets. Tones are --pv-* tokens and
     follow the active language convention: green-up/red-down in English,
     red-up/green-down in Chinese — except the two direction-NEUTRAL tones
     (--pv-wait, --muted), which mean the same thing in both and are the right home
     for a stance with no direction in it. */
  .nb-stage-hd { grid-column: 1 / -1; display: flex; align-items: baseline; flex-wrap: wrap;
                 gap: 3px 9px; margin: 15px 0 4px; padding: 5px 11px 5px 9px;
                 border-left: 3px solid var(--sgc, var(--muted)); border-radius: 0 8px 8px 0;
                 background: linear-gradient(90deg,
                   color-mix(in srgb, var(--sgc, var(--muted)) 12%, transparent), transparent 62%); }
  .nb-stage-hd:first-child { margin-top: 2px; }
  .nb-stage-hd .sh-l { font-size: 11.5px; font-weight: 800; letter-spacing: .05em;
                 text-transform: uppercase;
                 color: color-mix(in srgb, var(--sgc, var(--muted)) 52%, var(--text)); }
  .nb-stage-hd .sh-n { font-size: 10px; font-weight: 800; font-variant-numeric: tabular-nums;
                 padding: 1px 7px; border-radius: 999px;
                 background: color-mix(in srgb, var(--sgc, var(--muted)) 17%, transparent);
                 color: color-mix(in srgb, var(--sgc, var(--muted)) 55%, var(--text)); }
  .nb-stage-hd .sh-s { font-size: 11px; font-weight: 500; color: var(--muted);
                 text-transform: none; letter-spacing: 0; }
  html[data-lang="zh"] .nb-stage-hd .sh-l { letter-spacing: 0; }
  .sg-live       { --sgc: var(--pv-buy); }
  .sg-setting_up { --sgc: var(--pv-near); }
  .sg-ran        { --sgc: var(--muted); }
  /* Basing is the "watch — don't chase" shelf, so it takes the wait tone, not the
     avoid tone it used to inherit by sitting inside Blocked. --pv-wait is amber and
     is deliberately one of the two verb tones the zh 红涨绿跌 block does NOT remap
     (theme.css) — a directionless stance must read the same in both languages. */
  .sg-basing     { --sgc: var(--pv-wait); }
  .sg-blocked    { --sgc: var(--pv-avoid); }

  /* ── stage filter chips ──────────────────────────────────────────────────
     Real button elements with aria-pressed (a toggle group, not tabs — there is
     no tabpanel), count pills matching the stage headings so the panel counts one
     way throughout. Lives INSIDE .nb-grid-section so HK's table-mode toggle
     hides it with the grid it filters. */
  .pbf-bar { display: flex; flex-wrap: wrap; gap: 4px; padding: 4px; border-radius: 11px;
             background: var(--panel2); border: 1px solid var(--line); margin: 8px 0 2px; }
  .pbf-bar button { font: inherit; font-size: 12.5px; font-weight: 600; cursor: pointer;
             display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
             border: 1px solid transparent; background: transparent; color: var(--muted);
             padding: 6px 13px; border-radius: 8px; line-height: 1.2;
             -webkit-tap-highlight-color: transparent;
             transition: color .14s ease, background .14s ease, border-color .14s ease; }
  .pbf-bar button:hover { color: var(--text); }
  .pbf-bar button:focus-visible { outline: 2px solid var(--link); outline-offset: 2px; }
  .pbf-bar button[aria-pressed="true"] { background: var(--panel); color: var(--text);
             border-color: var(--line); box-shadow: var(--popover-shadow, 0 1px 3px rgba(0,0,0,.12)); }
  .pbf-n { font-size: 10px; font-weight: 800; font-variant-numeric: tabular-nums;
           padding: 1px 7px; border-radius: 999px;
           background: color-mix(in srgb, var(--muted) 14%, transparent); color: var(--muted); }
  .pbf-bar button[aria-pressed="true"] .pbf-n {
           background: color-mix(in srgb, var(--link) 16%, transparent); color: var(--ink-link, var(--link)); }
  @media (max-width: 680px) { .pbf-bar button { min-height: 44px; padding: 6px 14px; font-size: 13px; } }
  /* the polite result announcement — visible to assistive tech only */
  .pbf-live { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
              overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; border: 0; }

  /* filter visibility. The hide half and the reveal half target DISJOINT sets
     (`:not([data-stage=X])` vs `[data-stage=X]`), so they never fight on
     specificity. The reveal half exists because .sm-hidden is
     `display:none!important` — without it, filtering to a bucket that sits below
     the show-more fold would show an EMPTY board. While a bucket is filtered the
     show-more bar is hidden too: its "Showing 12 of 40" counts the unfiltered
     board. `:not(.st-table-mode)` is the HK-only addition — the table view has
     its own row filtering and must not inherit a stale grid facet. */
  #standouts:not(.st-table-mode)[data-stagef="live"]       [data-stage]:not([data-stage="live"]),
  #standouts:not(.st-table-mode)[data-stagef="setting_up"] [data-stage]:not([data-stage="setting_up"]),
  #standouts:not(.st-table-mode)[data-stagef="ran"]        [data-stage]:not([data-stage="ran"]),
  #standouts:not(.st-table-mode)[data-stagef="basing"]     [data-stage]:not([data-stage="basing"]),
  #standouts:not(.st-table-mode)[data-stagef="blocked"]    [data-stage]:not([data-stage="blocked"]) { display: none !important; }
  #standouts:not(.st-table-mode)[data-stagef="live"]       .sm-hidden[data-stage="live"],
  #standouts:not(.st-table-mode)[data-stagef="setting_up"] .sm-hidden[data-stage="setting_up"],
  #standouts:not(.st-table-mode)[data-stagef="ran"]        .sm-hidden[data-stage="ran"],
  #standouts:not(.st-table-mode)[data-stagef="basing"]     .sm-hidden[data-stage="basing"],
  #standouts:not(.st-table-mode)[data-stagef="blocked"]    .sm-hidden[data-stage="blocked"] { display: flex !important; }
  #standouts[data-stagef]:not([data-stagef="all"]) .nb-grid-section .sm-bar { display: none !important; }

  /* ── ran section ─────────────────────────────────────────────────────────
     Deliberately NOT a fourth table: the leaders table already follows this
     panel, and the ran lane is a "these are gone" list, not a comparison. Quiet
     one-line rows, panel-TINTED rather than panel-filled, so they read as
     visible-but-not-entries. */
  .pbr { margin-top: 17px; }
  .pbr-hd { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 9px; }
  .pbr-t { font-size: 11.5px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase;
           color: var(--muted); }
  html[data-lang="zh"] .pbr-t { letter-spacing: 0; }
  .pbr-n { font-size: 10px; font-weight: 800; font-variant-numeric: tabular-nums;
           padding: 1px 7px; border-radius: 999px;
           background: color-mix(in srgb, var(--muted) 14%, transparent); color: var(--muted); }
  .pbr-s { font-size: 11px; color: var(--muted); line-height: 1.5; margin: 4px 0 8px; }
  .pbr-l { display: flex; flex-direction: column; gap: 5px; }
  .pbr-r { display: flex; align-items: center; flex-wrap: wrap; gap: 2px 9px; padding: 6px 10px;
           border: 1px solid var(--line); border-radius: 8px; text-decoration: none;
           background: color-mix(in srgb, var(--panel2) 45%, transparent);
           color: var(--text); font-size: 11px; min-width: 0; }
  .pbr-r:hover { border-color: color-mix(in srgb, var(--muted) 45%, var(--line)); }
  .pbr-tk { font-weight: 800; font-size: 11.5px; flex: none; }
  .pbr-nm { color: var(--muted); min-width: 0; flex: 1 1 7em;
            overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .pbr-m { color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; flex: none; }
  /* --up/--down (NOT --pv-*) is correct here: this IS a directional figure, so it
     must flip red/green under html[data-lang="zh"]. HK already scopes .pos/.neg
     the same way; .az-up/.az-dn are the board-family names the US rows use. */
  .pbr-m .az-up { color: var(--ink-up, var(--up)); font-weight: 700; }
  .pbr-m .az-dn { color: var(--ink-down, var(--down)); font-weight: 700; }
  /* the honest em-dash: a ran row whose move since the signal could not be
     measured prints the gap rather than a zero. Muted, so it never reads as a
     flat return. */
  .pbr-m .pbr-na { color: var(--muted); opacity: .8; font-weight: 600; }
  /* ── vetoed section (G6) — the entry gate's own receipt ───────────────────
     The register here is SELF-CRITICISM, not opportunity. These are signals the
     gate refused, printed with what the name did afterwards so the gate can be
     judged; the lane is doing its job precisely when it reads badly. Two things
     keep it from inverting into "look what you missed, go buy them": it wears the
     Blocked bucket's own tone (--pv-avoid) rather than the buy green or the
     ran-lane amber, and the move column sits BEHIND the reason, never above it.
     Row geometry is the ran lane's, deliberately — same family, quieter voice. */
  .pbv { margin-top: 17px; }
  .pbr-r.pbr-veto { border-left: 2px solid color-mix(in srgb, var(--pv-avoid) 45%, var(--line));
           background: color-mix(in srgb, var(--pv-avoid) 4%, transparent); }
  .pbr-r.pbr-veto:hover { border-color: color-mix(in srgb, var(--pv-avoid) 45%, var(--line));
           border-left-color: color-mix(in srgb, var(--pv-avoid) 70%, var(--line)); }
  /* the block reason gets its own line: it is a full sentence, and squeezing it
     onto the identity row would truncate the one thing this lane exists to say */
  .pbv-why { flex: 1 1 100%; font-size: 10.5px; line-height: 1.5;
             color: color-mix(in srgb, var(--muted) 70%, var(--text)); }
  .pbv-mk { color: var(--muted); font-variant-numeric: tabular-nums; opacity: .85; flex: none; }
  /* the population line. It reads BEFORE the rows on purpose: the twelve figures
     below are the top of a ranked-then-truncated distribution, and a reader who
     meets them first has already formed the wrong impression by the time any
     footnote arrives. Muted and small — it frames the rows, it is not a headline. */
     At --muted it sat 8px under the subtitle at the same weight and colour and read
     as a fourth clause of it; the ink is the same 70/30 mix .pbv-why uses, which is
     enough to make it a statement of its own without turning it into a headline. */
  .pbv-pop { margin: 7px 0 1px; font-size: 10.5px; line-height: 1.55;
             color: color-mix(in srgb, var(--muted) 70%, var(--text));
             font-variant-numeric: tabular-nums; }
  /* a row whose stance differs from the section's says so; when every row agrees,
     the constant is printed ONCE in the section line and nowhere else */
  .pbv-st { font-size: 10.5px; font-weight: 700; color: var(--muted); flex: none; }
  /* board order / priority framing footnote */
  .pb-fn { margin: 9px 0 0; font-size: 11px; color: var(--muted); line-height: 1.55; }

  /* ── leaders strip table (US .topsetups idiom, ported) ────────────────────
     `.ts-tbl td{text-align:left}` is load-bearing: the page-global `th, td
     {text-align:right}` above would otherwise right-shift every text column. */
  .topsetups { margin-top: 14px; }
  .ts-tbl { width: 100%; border-collapse: collapse; margin-top: 7px; font-size: 11.5px; }
  .ts-tbl th { text-align: left; font-weight: 700; color: var(--muted); font-size: 10px;
               text-transform: uppercase; letter-spacing: .03em; padding: 3px 8px;
               border-bottom: 1px solid var(--line); }
  html[data-lang="zh"] .ts-tbl th { letter-spacing: 0; }
  .ts-tbl td { text-align: left; padding: 5px 8px; border-bottom: 1px solid var(--line); }
  .ts-tbl th.r, .ts-tbl td.r { text-align: right; font-variant-numeric: tabular-nums; }
  .ts-row { cursor: pointer; transition: background .12s; }
  .ts-row:hover { background: var(--panel2); }
  .ts-tk { font-weight: 800; color: var(--text); }
  /* The ticker is a real anchor so theme.js's capture-phase Terminal intercept can
     see it (and so middle-/cmd-click still opens a tab). It must not read as a blue
     link inside the row — the row itself is the affordance. */
  .ts-tk-a { color: inherit; text-decoration: none; }
  .ts-nm { font-size: 10px; color: var(--muted); }
  .ts-tbl td.az-up { color: var(--ink-up, var(--up)); font-weight: 700; }
  .ts-tbl td.az-dn { color: var(--ink-down, var(--down)); font-weight: 700; }
  /* ── strip tables on phones: primary decisions never x-scroll. At the board's
     own 680px break the tertiary columns demote to the row's own page (every row
     is a tap-through); what stays — ticker+name, the rank-key column, and the
     stance column — keeps its visible header as its label. .tbl-scroll (theme.css)
     remains underneath as the fail-safe if a future column outgrows the budget. */
  @media (max-width: 680px){
    .topsetups .ts-tbl .c-sector, .topsetups .ts-tbl .c-offhigh,
    .topsetups .ts-tbl .c-age,    .topsetups .ts-tbl .c-theme { display: none; }
  }
  /* ---- unified Conviction Profile on each standout card (SCREEN framing) ----- */
  .nb-conv { display: flex; align-items: center; gap: 7px; margin: 5px 0 1px; }
  .nb-cscore { font-size: 13px; font-weight: 800; font-variant-numeric: tabular-nums;
               min-width: 30px; text-align: center; padding: 1px 5px; border-radius: 8px;
               border: 1px solid var(--line); color: var(--text); }
  .nb-cscore.band-high { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 45%, var(--line));
                         background: color-mix(in srgb, var(--up) 12%, var(--panel)); }
  .nb-cscore.band-constructive { color: var(--g-cold); border-color: color-mix(in srgb, var(--g-cold) 40%, var(--line)); }
  .nb-cscore.band-neutral { color: var(--muted); }
  .nb-cscore.band-low { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 35%, var(--line)); }
  .nb-verdict { font-size: 10.5px; font-weight: 700; line-height: 1.25; color: var(--text); }
  /* multi-timeframe bottoming-alignment chip (weekly+3d+daily turning up) */
  .nb-align { display: flex; align-items: center; gap: 5px; margin: 3px 0 1px; min-width: 0;
              font-size: 9.5px; font-weight: 700; letter-spacing: .01em;
              padding: 2px 7px; border-radius: 7px; border: 1px solid var(--line);
              color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 9%, var(--panel)); }
  .nb-align.nba-near { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 9%, var(--panel)); }
  .nb-align .nba-line { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .nb-align .nba-tag { margin-left: auto; flex: none; font-size: 8px; font-weight: 800;
                       text-transform: uppercase; letter-spacing: .04em; opacity: .85; }
  .nb-axes { display: flex; gap: 4px; margin-top: 3px; }
  .nb-ax { flex: 1; }
  .nb-ax .axl { font-size: 8px; color: var(--muted); letter-spacing: .03em; }
  .nb-ax .axt { height: 3px; border-radius: 2px; background: var(--line); margin-top: 1px; overflow: hidden; }
  .nb-ax .axf { height: 100%; background: var(--g-cold); border-radius: 2px; }
  .nb-ax.ax-na .axf { background: transparent; }
  /* ---- Caution icon + popover (replaces old pill-row; ported from dashboard #1061) ---- */
  .nb-cau { position: relative; display: inline-flex; margin-top: 4px; }
  .nb-cau-btn {
    display: inline-flex; align-items: center; gap: 3px;
    padding: 0 5px 0 4px; height: 18px; border-radius: 9px; border: none; cursor: pointer;
    font-size: 9px; font-weight: 700; line-height: 1;
    color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 14%, var(--panel));
    text-decoration: none;
    animation: nb-cau-pulse 2.5s ease-in-out infinite;
  }
  @media (prefers-reduced-motion: reduce) { .nb-cau-btn { animation: none; } }
  @keyframes nb-cau-pulse {
    0%, 100% { opacity: 1; }
    50%       { opacity: .55; }
  }
  .nb-cau-badge {
    display: inline-flex; align-items: center; justify-content: center;
    width: 13px; height: 13px; border-radius: 50%; font-size: 8px; font-weight: 800;
    background: var(--warn); color: var(--panel);
  }
  .nb-cau-pop {
    display: none; position: absolute; z-index: 120; bottom: calc(100% + 5px); left: 0;
    min-width: 180px; max-width: min(260px, calc(100vw - 24px));
    padding: 7px 9px; border-radius: 8px;
    background: var(--panel); border: 1px solid color-mix(in srgb, var(--warn) 40%, var(--line));
    box-shadow: 0 4px 16px rgba(0,0,0,.18);
    font-size: 10px; font-weight: 600; line-height: 1.45; color: var(--ink-warn, var(--warn));
    pointer-events: none;
  }
  .nb-cau-pop .cau-row { display: block; padding: 2px 0; }
  .nb-cau-pop .cau-row + .cau-row { border-top: 1px solid color-mix(in srgb, var(--warn) 20%, var(--line)); padding-top: 4px; margin-top: 2px; }
  /* Show on hover/focus (desktop) */
  .nb-cau:hover .nb-cau-pop,
  .nb-cau:focus-within .nb-cau-pop,
  .nb-cau.nb-cau-open .nb-cau-pop { display: block; pointer-events: auto; }
  /* Flip to below if near top of viewport (added by JS) */
  .nb-cau.pop-below .nb-cau-pop { bottom: auto; top: calc(100% + 5px); }
  /* Clamp to right edge */
  .nb-cau.pop-right .nb-cau-pop { left: auto; right: 0; }
  .nb-tier { font-size: 8px; color: var(--muted); margin-top: 3px; letter-spacing: .02em; }
  /* volatility black hole + honesty notes (HK overhaul, China-parity) */
  .nb-vf { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 3px; }
  .nb-vchip { font-size: 8.5px; font-weight: 800; padding: 0 5px; border-radius: 6px; border: 1px solid var(--line);
              color: var(--muted); white-space: nowrap; }
  .vf-coil { color: var(--ink-link, var(--link)); border-color: color-mix(in srgb, var(--link) 38%, var(--line));
             background: color-mix(in srgb, var(--link) 10%, var(--panel)); }
  .vf-up { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 45%, var(--line)); }
  .vf-down { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 40%, var(--line)); }
  .vf-exp { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 35%, var(--line)); }
  .nb-note { font-size: 8.5px; line-height: 1.3; margin-top: 3px; padding: 2px 5px; border-radius: 6px;
             color: var(--muted); background: color-mix(in srgb, var(--text) 4%, var(--panel)); }
  .nb-note-anticipation { color: var(--ink-link, var(--link)); background: color-mix(in srgb, var(--link) 8%, var(--panel)); }
  /* ⚖ vol-managed size chip + compact entry-timing chip (US-parity gauges) */
  .nb-size { font-weight: 800; font-variant-numeric: tabular-nums; white-space: nowrap;
             padding: 0 5px; border-radius: 7px; color: var(--muted);
             background: var(--panel); border: 1px solid var(--line); }
  .nb-size.sz-up { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 38%, var(--line)); }
  .nb-size.sz-dn { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 42%, var(--line)); }
  .nb-entry { display: flex; align-items: center; gap: 5px; margin-top: 4px; padding: 3px 6px;
              border-radius: 7px; border-top: 2px solid var(--muted);
              background: color-mix(in srgb, var(--text) 4%, var(--panel)); }
  .nbe-buy_now, .nbe-partial { border-top-color: var(--up); }
  .nbe-buy_soon, .nbe-watch { border-top-color: var(--g-cold); }
  .nbe-wait_pullback, .nbe-hold, .nbe-bounce_wait { border-top-color: var(--warn); }
  .nbe-extended, .nbe-topping { border-top-color: var(--warn); }
  .nbe-exit, .nbe-avoid, .nbe-blocked { border-top-color: var(--down); }
  .nbe-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--muted); flex: none; }
  .nbe-dot.a3 { background: var(--up); } .nbe-dot.a2 { background: var(--g-cold); }
  .nbe-dot.a1 { background: var(--warn); } .nbe-dot.a0 { background: var(--down); }
  .nbe-status { font-size: 9px; font-weight: 800; color: var(--text); line-height: 1.2; }
  .nbe-zone { margin-left: auto; font-size: 9px; font-weight: 700; color: var(--muted);
              font-variant-numeric: tabular-nums; white-space: nowrap; }

  /* ---- US/China-parity panels ported to HK (dial / bignum / alerts / risk gauges) ---- */
  .dial { position: relative; height: 9px; border-radius: 5px; margin: 6px 0 3px;
          background: linear-gradient(90deg, var(--up), var(--warn) 55%, var(--down)); }
  .dial.rev { background: linear-gradient(90deg, var(--down), var(--warn) 45%, var(--up)); }
  .dial i { position: absolute; top: -3px; width: 4px; height: 15px; border-radius: 2px; background: var(--text); transform: translateX(-50%); box-shadow: 0 0 0 2px var(--panel); }
  .dial-ends { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--muted); }
  .bignum { font-size: 26px; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1; }
  /* fired alerts (ported from the US/China dashboard) */
  .alert { display: block; padding: 10px 13px; border-radius: 8px; margin: 8px 0;
           background: var(--panel2, var(--panel)); border-left: 3px solid var(--muted);
           color: var(--text); transition: transform .12s, box-shadow .12s; }
  a.alert:hover { transform: translateX(2px); box-shadow: 0 3px 14px rgba(0,0,0,.22); }
  .alert-high { border-left-color: var(--down); }
  .alert-warn { border-left-color: var(--warn); }
  .alert-info { border-left-color: var(--info); }
  .alert-head { display: flex; align-items: baseline; gap: 8px; }
  .alert-ico { font-size: 15px; flex: none; line-height: 1; }
  .alert-head b { font-size: 13.5px; color: var(--text); }
  .alert-jump { margin-left: auto; font-size: 11px; font-weight: 700;
                color: var(--ink-link, var(--link)); flex: none; white-space: nowrap; }
  .alert-detail { margin: 6px 0 0; font-size: 12.5px; color: var(--text); font-variant-numeric: tabular-nums; }
  .alert-what { margin: 6px 0 0; padding-top: 6px; border-top: 1px solid var(--line);
                font-size: 12px; color: var(--muted); line-height: 1.5; }
  .alert-edge { margin: 5px 0 0; font-size: 12px; color: var(--text); line-height: 1.45; }
  .alert-edge b { color: var(--muted); font-weight: 600; }
  /* AI master brief */
  .ai-brief .mb-sum { font-size: 15px; font-weight: 600; margin: 0 0 10px; }
  .ai-brief .mb-sec { margin: 10px 0; } .ai-brief .mb-h { font-weight: 600; color: var(--ink-link, var(--link)); margin: 0 0 4px; }
  .ai-brief .mb-list { margin: 4px 0 0 18px; padding: 0; } .ai-brief .mb-list li { margin: 3px 0; }
  .ai-brief .mb-foot { margin-top: 12px; color: var(--muted); font-size: 12px; }
  .ai-brief .mb-deg { color: var(--muted); font-size: 12px; font-style: italic; margin: 4px 0; }

  /* ============ HK STOCK DESK — command-center hero, flows desk, conviction chips ===== */
  .deskhero { display: grid; grid-template-columns: 1.35fr 1fr; gap: 20px 26px; align-items: start; }
  @media (max-width: 820px) { .deskhero { grid-template-columns: 1fr; } }
  .desk-title { display: flex; align-items: center; gap: 11px; flex-wrap: wrap; }
  .desk-title h1 { font-size: 22px; margin: 0; }
  .desk-verdict { margin: 14px 0 0; padding: 12px 15px; border-radius: 11px; line-height: 1.5;
      background: color-mix(in srgb, var(--c, var(--info)) 12%, var(--panel));
      border: 1px solid color-mix(in srgb, var(--c, var(--info)) 30%, var(--line)); }
  .desk-verdict.rv-on { --c: var(--up); } .desk-verdict.rv-off { --c: var(--down); } .desk-verdict.rv-neu { --c: var(--info); }
  .desk-verdict b { color: var(--text); }
  .desk-verdict .rv-lead { font-size: 13.5px; font-weight: 700; display: block; margin-bottom: 3px; color: var(--text); }
  .desk-verdict .rv-body { font-size: 12.5px; color: var(--muted); }
  /* exposure split bar (amplifiers vs cushions) */
  .expo-wrap { margin: 4px 0 2px; }
  .expo-bar { display: flex; height: 22px; border-radius: 7px; overflow: hidden; border: 1px solid var(--line); }
  .expo-bar .amp { background: color-mix(in srgb, var(--down) 60%, var(--panel)); }
  .expo-bar .mid { background: var(--panel2, color-mix(in srgb, var(--muted) 16%, var(--panel))); }
  .expo-bar .cush { background: color-mix(in srgb, var(--up) 58%, var(--panel)); }
  .expo-seg { display: flex; align-items: center; justify-content: center; font-size: 10.5px; font-weight: 800;
      color: #fff; min-width: 0; white-space: nowrap; }
  .expo-bar .mid .expo-seg { color: var(--muted); }
  .expo-key { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--muted); margin-top: 5px; }
  .expo-key b { color: var(--text); }
  /* desk stat tiles */
  .desk-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; }
  @media (min-width: 560px) { .desk-stats { grid-template-columns: repeat(4, 1fr); } }
  .deskhero .desk-stats { grid-template-columns: repeat(2, 1fr); }
  .dstat { background: var(--panel2, color-mix(in srgb, var(--muted) 8%, var(--panel)));
      border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; }
  .dstat .dv { font-size: 19px; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1.05; }
  .dstat .dk { font-size: 10.5px; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; margin-top: 2px; }
  .desk-overlay { margin-top: 11px; font-size: 12px; color: var(--muted); }
  .desk-overlay .ov-chip { display: inline-block; font-weight: 700; padding: 1px 8px; border-radius: 8px; margin-left: 4px;
      background: color-mix(in srgb, var(--warn) 16%, var(--panel)); color: color-mix(in srgb, var(--warn) 85%, var(--text)); }
  /* southbound + A/H conviction chips on the standout cards */
  .nb-flow { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 3px; }
  .nb-flow span { font-size: 9px; font-weight: 800; padding: 1px 6px; border-radius: 7px; letter-spacing: .01em;
      border: 1px solid var(--line); color: var(--muted); background: var(--panel); overflow-wrap: anywhere; max-width: 100%; }
  .nb-flow .fl-buy { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 40%, var(--line));
      background: color-mix(in srgb, var(--up) 10%, var(--panel)); }
  .nb-flow .fl-sell { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 40%, var(--line));
      background: color-mix(in srgb, var(--down) 10%, var(--panel)); }
  .nb-flow .fl-val { color: var(--ink-info, var(--info)); border-color: color-mix(in srgb, var(--info) 40%, var(--line));
      background: color-mix(in srgb, var(--info) 10%, var(--panel)); }
  /* H2a SFC reportable-short CONTEXT chip (ACCRUE) — a high short book leans returns softer */
  .nb-flow .fl-short { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 42%, var(--line));
      background: color-mix(in srgb, var(--warn) 11%, var(--panel)); }
  /* smart-money flows desk */
  .flows-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 22px; }
  @media (max-width: 760px) { .flows-grid { grid-template-columns: 1fr; } }
  .flow-col h3 { margin: 0 0 7px; }
  .flow-row { display: flex; align-items: center; gap: 8px; padding: 5px 0; border-bottom: 1px solid var(--line); font-size: 12.5px; }
  .flow-row:last-child { border-bottom: none; }
  .flow-row .fr-tk { font-weight: 800; min-width: 64px; color: inherit; text-decoration: none; cursor: pointer; }
  .flow-row .fr-tk:hover { text-decoration: underline; }
  .flow-row .fr-nm { color: var(--muted); flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
  .flow-row .fr-bar { flex: 0 0 88px; height: 8px; border-radius: 5px; background: var(--panel2); position: relative; overflow: hidden; }
  .flow-row .fr-bar i { position: absolute; top: 0; height: 100%; border-radius: 5px; }
  .flow-row .fr-v { flex: 0 0 56px; text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; }
  .flow-row .fr-own { flex: 0 0 44px; text-align: right; font-size: 10.5px; color: var(--muted); }
  /* desk watch strip (strong-but-blocked) */
  .watch-strip { margin: 14px 0 2px; padding: 11px 13px; border-radius: 10px;
      background: color-mix(in srgb, var(--warn) 9%, var(--panel)); border: 1px solid color-mix(in srgb, var(--warn) 26%, var(--line)); }
  .watch-strip .ws-h { font-size: 12px; font-weight: 800; color: color-mix(in srgb, var(--warn) 88%, var(--text)); margin: 0 0 7px; text-transform: uppercase; letter-spacing: .04em; }
  .watch-grid { display: flex; flex-wrap: wrap; gap: 8px; }
  .watch-grid a { display: flex; flex-direction: column; gap: 1px; padding: 6px 10px; border-radius: 8px; min-width: 130px;
      background: var(--panel); border: 1px solid var(--line); color: var(--text); transition: border-color .12s, transform .12s; }
  .watch-grid a:hover { border-color: var(--link); transform: translateY(-1px); }
  .watch-grid .wg-tk { font-weight: 800; font-size: 12.5px; }
  .watch-grid .wg-v { font-size: 10px; color: var(--muted); line-height: 1.3; }
  /* falling-knife demote (H4 KILL) — deepest-3M loser pushed out of the entry groups */
  .watch-grid a.wg-knife { border-color: color-mix(in srgb, var(--down) 34%, var(--line));
      background: color-mix(in srgb, var(--down) 7%, var(--panel)); }
  .watch-grid .wg-knife-chip { margin-top: 3px; font-size: 9px; font-weight: 800; line-height: 1.25;
      color: var(--ink-down, var(--down)); }
  /* H-PLC placement/rights dilution demote — dilutive top-up announced within 90d */
  .watch-grid a.wg-plc { border-color: color-mix(in srgb, var(--down) 34%, var(--line));
      background: color-mix(in srgb, var(--down) 7%, var(--panel)); }
  .watch-grid .wg-plc-chip { margin-top: 3px; font-size: 9px; font-weight: 800; line-height: 1.25;
      color: var(--ink-down, var(--down)); }
  /* Washout Watch strip — igniting · unconfirmed · high-risk */
  .ww-strip { margin: 8px 0 0; }
  .ww-grid { display: flex; flex-wrap: wrap; gap: 8px; }
  .ww-card { display: flex; flex-direction: column; gap: 3px; padding: 8px 11px; border-radius: 9px;
      min-width: 160px; max-width: 240px;
      background: var(--panel); border: 1px solid color-mix(in srgb, var(--down) 25%, var(--line));
      color: var(--text); text-decoration: none; transition: border-color .12s, transform .12s; }
  .ww-card:hover { border-color: var(--link); transform: translateY(-1px); }
  .ww-card.ww-ignite { border-color: color-mix(in srgb, var(--warn) 60%, var(--line));
      background: color-mix(in srgb, var(--warn) 7%, var(--panel)); }
  .ww-card.ww-pullback { border-color: color-mix(in srgb, var(--up) 35%, var(--line));
      background: color-mix(in srgb, var(--up) 5%, var(--panel)); }
  .ww-card.ww-chase { border-color: color-mix(in srgb, var(--down) 40%, var(--line)); }
  .ww-tk { font-weight: 800; font-size: 13px; }
  .ww-nm { font-size: 10px; color: var(--muted); }
  .ww-state { display: inline-block; font-size: 9.5px; font-weight: 800; padding: 1px 7px;
      border-radius: 8px; margin-top: 2px; }
  .ww-state.st-ignite { background: color-mix(in srgb, var(--warn) 22%, var(--panel));
      color: color-mix(in srgb, var(--warn) 90%, var(--text)); }
  .ww-state.st-watch  { background: color-mix(in srgb, var(--down) 16%, var(--panel));
      color: color-mix(in srgb, var(--down) 80%, var(--text)); }
  .ww-state.st-pull   { background: color-mix(in srgb, var(--up) 20%, var(--panel));
      color: color-mix(in srgb, var(--up) 80%, var(--text)); }
  .ww-state.st-chase  { background: color-mix(in srgb, var(--down) 20%, var(--panel));
      color: color-mix(in srgb, var(--down) 90%, var(--text)); }
  .ww-chips { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 3px; }
  .ww-chip { font-size: 8.5px; font-weight: 800; padding: 1px 6px; border-radius: 6px;
      background: color-mix(in srgb, var(--muted) 14%, var(--panel));
      color: color-mix(in srgb, var(--muted) 80%, var(--text)); }
  .ww-chip.wc-adr   { background: color-mix(in srgb, var(--up) 18%, var(--panel)); color: color-mix(in srgb, var(--up) 85%, var(--text)); }
  .ww-chip.wc-bear  { background: color-mix(in srgb, var(--up) 16%, var(--panel)); color: color-mix(in srgb, var(--up) 80%, var(--text)); }
  .ww-chip.wc-buy   { background: color-mix(in srgb, var(--up) 20%, var(--panel)); color: color-mix(in srgb, var(--up) 90%, var(--text)); }
  .ww-chip.wc-narr  { background: color-mix(in srgb, var(--info, #60c) 14%, var(--panel)); color: color-mix(in srgb, var(--info, #60c) 80%, var(--text)); }
  .ww-chip.wc-sb    { background: color-mix(in srgb, var(--up) 16%, var(--panel)); color: color-mix(in srgb, var(--up) 80%, var(--text)); }
  .ww-chip.wc-rsi   { background: color-mix(in srgb, var(--warn) 20%, var(--panel)); color: color-mix(in srgb, var(--warn) 85%, var(--text)); }
  .ww-chip.wc-cat   { background: color-mix(in srgb, var(--muted) 10%, var(--panel)); color: var(--muted); }
  .ww-chip.wc-knife { background: color-mix(in srgb, var(--down) 20%, var(--panel)); color: color-mix(in srgb, var(--down) 90%, var(--text)); }
  .ww-hint { font-size: 9.5px; color: var(--muted); line-height: 1.3; margin-top: 2px; }
  .ww-meta { font-size: 9px; color: var(--muted); margin-top: 2px; }
  .ww-empty { font-size: 11.5px; color: var(--muted); padding: 6px 0; }
  /* compact chip row for non-igniting watch names (Law-4: constant text moved to the footer) */
  .ww-cold-wrap { margin-top: 10px; }
  .ww-cold-h { font-size: 10.5px; font-weight: 700; color: var(--muted); margin: 0 0 6px;
      text-transform: uppercase; letter-spacing: .04em; }
  .ww-cold-row { display: flex; flex-wrap: wrap; gap: 6px; }
  .ww-cold-chip { display: inline-flex; align-items: baseline; gap: 5px; padding: 3px 9px;
      border-radius: 8px; text-decoration: none; color: var(--text);
      background: color-mix(in srgb, var(--down) 6%, var(--panel));
      border: 1px solid color-mix(in srgb, var(--down) 22%, var(--line)); transition: border-color .12s; }
  .ww-cold-chip:hover { border-color: var(--link); }
  .ww-cold-tk { font-weight: 800; font-size: 12px; }
  .ww-cold-nm { font-size: 10px; color: var(--muted); }
  .ww-cold-knife { font-size: 10px; }
  .ww-foot { font-size: 11px; color: var(--muted); line-height: 1.5; margin: 10px 0 0; }
  /* H5 peg-liquidity regime conditioner chip in the deskhero */
  .desk-liq { margin-top: 9px; display: flex; flex-direction: column; gap: 3px; padding: 8px 11px;
      border-radius: 9px; border: 1px solid var(--line); background: var(--panel); }
  .desk-liq.lq-easy { border-color: color-mix(in srgb, var(--up) 34%, var(--line));
      background: color-mix(in srgb, var(--up) 7%, var(--panel)); }
  .desk-liq.lq-tight { border-color: color-mix(in srgb, var(--down) 34%, var(--line));
      background: color-mix(in srgb, var(--down) 7%, var(--panel)); }
  .desk-liq .lq-chip { font-size: 11.5px; font-weight: 700; }
  .desk-liq .lq-accrue { font-weight: 600; opacity: .7; font-size: 10.5px; }
  .desk-liq .lq-note { font-size: 10.5px; color: var(--muted); line-height: 1.35; }
  /* high-impact event-risk banner (macro) */
  .evbanner { display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
      padding: 10px 15px; border-radius: 11px; margin-bottom: 0;
      background: color-mix(in srgb, var(--warn) 10%, var(--panel)); border: 1px solid color-mix(in srgb, var(--warn) 26%, var(--line)); }
  .evbanner .ev-h { font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em; color: color-mix(in srgb, var(--warn) 88%, var(--text)); white-space: nowrap; }
  .evbanner .ev-list { display: flex; flex-wrap: wrap; gap: 7px; }
  .ev-chip { display: inline-flex; align-items: baseline; gap: 5px; font-size: 11.5px; padding: 3px 9px; border-radius: 8px;
      background: var(--panel); border: 1px solid var(--line); }
  .ev-chip b { color: var(--text); } .ev-chip .ev-d { font-weight: 800; color: var(--ink-warn, var(--warn)); font-variant-numeric: tabular-nums; }
  .ev-chip .ev-rg { font-size: 9px; font-weight: 700; padding: 0 5px; border-radius: 6px; color: var(--muted); background: var(--panel2, color-mix(in srgb,var(--muted) 12%,var(--panel))); }
  .cat-imminent { background: color-mix(in srgb, var(--warn) 8%, var(--panel)); }

  /* ===== W6 UX overhaul (§7) — ONE desk manifest, track-record panel, tier-driven chrome ===== */
  /* (A) desk manifest: the single "what this desk is / isn't" block that replaces the ~6×
     repeated screen-vs-buylist caveats. Two clauses, colour-keyed, well-typeset. */
  .desk-manifest { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 14px; margin: 12px 0 0;
      padding: 11px 14px; border-radius: 11px; border: 1px solid var(--line);
      background: color-mix(in srgb, var(--info) 5%, var(--panel)); }
  @media (max-width: 640px) { .desk-manifest { grid-template-columns: 1fr; gap: 8px; } }
  .dm-cell { min-width: 0; }
  .dm-k { font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: .05em;
      display: inline-flex; align-items: center; gap: 5px; margin-bottom: 3px; }
  .dm-is .dm-k { color: var(--ink-up, var(--up)); }
  .dm-isnt .dm-k { color: var(--muted); }
  .dm-v { font-size: 12px; line-height: 1.5; color: var(--fg); }
  .dm-v b { color: var(--text); }
  .dm-isnt .dm-v { color: var(--muted); }
  .dm-tierline { grid-column: 1 / -1; margin: 1px 0 0; padding-top: 8px; border-top: 1px solid var(--line);
      font-size: 10.5px; color: var(--muted); line-height: 1.5; }
  .dm-tierline b { color: var(--text); }
  .dm-badge { display: inline-block; font-size: 9px; font-weight: 800; padding: 1px 6px; border-radius: 6px;
      letter-spacing: .02em; border: 1px solid var(--line); color: var(--muted);
      background: color-mix(in srgb, var(--muted) 8%, var(--panel)); vertical-align: middle; }

  /* (B) track-record / public scoreboard panel (§7.4) — intentional, not apologetic. */
  .trackrec { border: 1px solid color-mix(in srgb, var(--info) 26%, var(--line));
      background: color-mix(in srgb, var(--info) 4%, var(--panel)); }
  .tr-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin: 0 0 9px; }
  .tr-head h2 { margin: 0; }
  .tr-status { font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em;
      padding: 2px 9px; border-radius: 8px; }
  .tr-status.st-accruing { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 13%, var(--panel));
      border: 1px solid color-mix(in srgb, var(--warn) 34%, var(--line)); }
  .tr-status.st-scored { color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 13%, var(--panel));
      border: 1px solid color-mix(in srgb, var(--up) 38%, var(--line)); }
  .tr-lead { font-size: 13px; line-height: 1.55; color: var(--fg); margin: 0 0 10px; }
  .tr-lead b { color: var(--text); }
  .tr-timeline { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 4px; }
  .tr-step { flex: 1 1 150px; min-width: 0; padding: 9px 12px; border-radius: 9px; border: 1px solid var(--line);
      background: var(--panel); }
  .tr-step .ts-k { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; }
  .tr-step .ts-v { font-size: 15px; font-weight: 800; font-variant-numeric: tabular-nums; margin-top: 2px; line-height: 1.1; }
  .tr-step .ts-sub { font-size: 10.5px; color: var(--muted); margin-top: 2px; line-height: 1.35; }
  .tr-step.ts-now { border-color: color-mix(in srgb, var(--info) 40%, var(--line));
      background: color-mix(in srgb, var(--info) 7%, var(--panel)); }
  .tr-step.ts-now .ts-v { color: var(--ink-info, var(--info)); }
  .tr-foot { font-size: 10.5px; color: var(--muted); margin: 9px 0 0; line-height: 1.5; }
  .tr-tbl { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 4px; }
  .tr-tbl th, .tr-tbl td { text-align: right; padding: 5px 9px; border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; }
  .tr-tbl th:first-child, .tr-tbl td:first-child { text-align: left; }
  .tr-tbl th { color: var(--muted); font-weight: 700; font-size: 10.5px; text-transform: uppercase; letter-spacing: .03em; }

  /* (C) evidence-tag micro-style on the why-now chips — .et-validated / .et-accruing / .et-context. */
  .ev-tag { font-size: 7.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .03em;
      padding: 0 3px; border-radius: 4px; margin-left: 3px; vertical-align: middle; }
  .ev-tag.et-validated { color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 15%, var(--panel)); }
  .ev-tag.et-accruing { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 15%, var(--panel)); }
  .ev-tag.et-context { color: var(--muted); background: color-mix(in srgb, var(--muted) 12%, var(--panel)); }
  /* A/H = the near-GO edge (DSR 0.879) — gets visual priority among the flow chips. */
  .nb-flow .fl-val.fl-lead { border-color: color-mix(in srgb, var(--info) 62%, var(--line));
      background: color-mix(in srgb, var(--info) 16%, var(--panel)); box-shadow: 0 0 0 1px color-mix(in srgb, var(--info) 22%, transparent); }

  /* (D) tier-driven chrome (§7 item 1): on this screen-tier market the composite score chip
     is DESATURATED + downsized so the mechanism lead + entry window carry the weight. The
     card stays ALIVE via an accent keyed to the entry-window state. */
  .nb-cscore { filter: saturate(.55); opacity: .82; font-size: 11px; min-width: 24px; }
  /* entry-window state drives the TOP stripe (overrides the base state stripe) */
  .nbcard.ew-open-now::before { background: linear-gradient(90deg, color-mix(in srgb, var(--up) 62%, var(--line)), transparent); opacity: 1; }
  .nbcard.ew-pullback::before { background: linear-gradient(90deg, color-mix(in srgb, var(--g-cold) 55%, var(--line)), transparent); opacity: 1; }
  .nbcard.ew-wait::before { background: linear-gradient(90deg, color-mix(in srgb, var(--muted) 40%, var(--line)), transparent); opacity: .85; }
  .nbcard.ew-open-now:hover { box-shadow: 0 3px 16px color-mix(in srgb, var(--up) 20%, transparent); }
  /* ===================== COMMAND-CENTER REGIME HERO (shared) =====================
     The modern macro scorecard ported from the US macro terminal (dashboard.html.j2)
     to China / HK / Canada. Scoped under .cmd-hero on the hero panel so it never
     restyles the rest of the page; every colour routes through the existing theme
     vars so dark/light + the zh Asia red/green swap propagate at paint. A 3-column
     bar: 2x2 quadrant locator · headline regime + plain-English standfirst · a
     vitals strip of the market's NATIVE drivers (LABEL · VALUE · MEANING). */
  .cmd-hero {
    --num: var(--font-mono, ui-monospace, "SF Mono", SFMono-Regular, "Cascadia Mono", "JetBrains Mono", "Roboto Mono", Menlo, Consolas, monospace);
    --hair: color-mix(in srgb, var(--line) 72%, transparent);
    --tile: color-mix(in srgb, var(--panel2, var(--panel)) 86%, var(--panel));
    --ink-1: var(--text);
    --ink-2: color-mix(in srgb, var(--text) 64%, transparent);
    --ink-3: var(--muted);
    --rule: 1px;
    padding: 19px 21px;
  }
  html[data-theme="light"] .cmd-hero {
    --ink-2: color-mix(in srgb, var(--text) 70%, transparent);
    --hair: color-mix(in srgb, var(--line) 90%, transparent);
  }
  .cmd-hero .num, .cmd-hero .num-lg, .cmd-hero .v-num, .cmd-hero .v-chip {
    font-family: var(--num); font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum" 1; letter-spacing: -.01em; }
  .cmd-hero .num-lg { font-size: 22px; font-weight: 800; line-height: 1.05; color: var(--ink-1); }

  .cmd-hero .hero-bar { display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 26px; }
  .cmd-hero .hero-main { padding: 2px 28px; min-width: 0;
    border-left: var(--rule) solid var(--hair); border-right: var(--rule) solid var(--hair); }

  /* LEFT — 2x2 quadrant locator (growth↑ top, inflation→ right; lit cell only) */
  .cmd-hero .hero-loc { display: grid; gap: 7px; justify-items: start; }
  .cmd-hero .qmini { display: grid; grid-template-columns: repeat(2, 31px);
    grid-template-rows: repeat(2, 31px); gap: 5px; }
  .cmd-hero .qm { border-radius: 6px;
    background: color-mix(in srgb, var(--qc) 14%, var(--tile));
    border: var(--rule) solid color-mix(in srgb, var(--qc) 28%, var(--hair));
    transition: box-shadow .2s ease; }
  .cmd-hero .qm.on { background: var(--qc);
    box-shadow: 0 0 0 2px var(--panel), 0 0 0 3.5px var(--qc),
                0 0 18px color-mix(in srgb, var(--qc) 55%, transparent); }
  .cmd-hero .loc-axes { display: flex; justify-content: space-between; width: 100%;
    gap: 8px; font-family: var(--num); font-size: 8px; letter-spacing: .05em;
    color: var(--ink-3); text-transform: uppercase; font-weight: 700; }

  /* CENTER — the read */
  .cmd-hero .hero-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .12em;
    text-transform: uppercase; color: var(--ink-3); display: flex; align-items: center;
    gap: 7px; flex-wrap: wrap; }
  .cmd-hero .hero-eyebrow .num { color: var(--ink-2); }
  .cmd-hero .hero-regime { display: flex; align-items: center; gap: 12px; margin: 7px 0 6px; }
  .cmd-hero .hr-dot { width: 13px; height: 13px; border-radius: 50%; flex: none; }
  .cmd-hero h1.hr-name { font-size: 33px; font-weight: 800; letter-spacing: -.02em;
    line-height: 1; color: var(--ink-1); margin: 0; }
  html[data-lang="zh"] .cmd-hero h1.hr-name { font-size: 31px; letter-spacing: 0; }
  .cmd-hero .hero-says { margin: 0; font-size: 14px; color: var(--ink-2);
    max-width: 54ch; line-height: 1.5; }
  .cmd-hero .hero-says b { color: var(--ink-1); font-weight: 700; }

  /* RIGHT — vitals strip: 4 cells, each LABEL · VALUE · plain-English MEANING */
  .cmd-hero .hero-vitals { display: grid;
    grid-template-columns: repeat(2, minmax(124px, 1fr)); gap: 13px 20px; }
  .cmd-hero .vital { display: grid; gap: 4px; align-content: start; }
  .cmd-hero .v-top { display: flex; align-items: center; gap: 5px; }
  .cmd-hero .v-label { font-family: var(--num); font-size: 9.5px; font-weight: 700;
    letter-spacing: .1em; color: var(--ink-3); text-transform: uppercase; }
  .cmd-hero .v-num { color: var(--ink-1); }
  .cmd-hero .v-num small { font-size: 14px; color: var(--ink-3); font-weight: 600; font-family: var(--num); }
  .cmd-hero .v-mean { font-size: 11px; color: var(--ink-2); line-height: 1.35; }
  .cmd-hero .v-meter { height: 4px; border-radius: 2px; background: var(--tile);
    position: relative; overflow: hidden; }
  .cmd-hero .v-meter::after { content: ""; position: absolute; inset: 0 auto 0 0;
    width: var(--p, 0%); background: var(--mc, var(--ink-2)); border-radius: 2px; }
  .cmd-hero .v-chip { font-size: 12.5px; font-weight: 700; padding: 3px 10px;
    border-radius: 7px; width: max-content; border: var(--rule) solid var(--hair);
    background: var(--tile); color: var(--ink-1); }
  .cmd-hero .v-chip.tone-up, .cmd-hero .v-chip.liq-expanding { color: var(--ink-up, var(--up));
    border-color: color-mix(in srgb, var(--up) 45%, var(--hair));
    background: color-mix(in srgb, var(--up) 13%, var(--tile)); }
  .cmd-hero .v-chip.tone-down, .cmd-hero .v-chip.liq-contracting { color: var(--ink-down, var(--down));
    border-color: color-mix(in srgb, var(--down) 45%, var(--hair));
    background: color-mix(in srgb, var(--down) 13%, var(--tile)); }
  .cmd-hero .v-chip.tone-warn { color: var(--ink-warn, var(--warn));
    border-color: color-mix(in srgb, var(--warn) 45%, var(--hair));
    background: color-mix(in srgb, var(--warn) 11%, var(--tile)); }
  .cmd-hero .v-chip.tone-info { color: var(--ink-info, var(--info, var(--link)));
    border-color: color-mix(in srgb, var(--info, var(--link)) 45%, var(--hair));
    background: color-mix(in srgb, var(--info, var(--link)) 11%, var(--tile)); }

  @media (max-width: 900px) {
    .cmd-hero .hero-bar { grid-template-columns: 1fr; gap: 16px; }
    .cmd-hero .hero-main { border: 0; padding: 14px 0;
      border-top: var(--rule) solid var(--hair); border-bottom: var(--rule) solid var(--hair); }
    .cmd-hero h1.hr-name { font-size: 28px; }
    .cmd-hero .hero-vitals { grid-template-columns: repeat(2, 1fr); }
  }

  /* ===================== MARKET STATE board (shared) =====================
     The side-by-side .ms-front board ported from the US macro terminal (#646):
     Market State (verdict + evidence) left, the growth×inflation hero-bar right,
     the multi-timeframe tape full-width below. Lives INSIDE the .cmd-hero panel so
     it inherits its theme vars (--num/--hair/--tile/--ink-*/--rule); include this
     AFTER _cmd_hero.css.j2 so the verdict's .v-* rules win over the vitals' on the
     left column only (every verdict rule is scoped under .ms-verdict so the hero-bar
     vitals are never restyled). Colour spent only on signal. */
  .cmd-hero .ms-front { --hair-strong: var(--line); --ms-c: var(--ink-3); }
  .cmd-hero .ms-front.ms-green  { --ms-c: var(--up); }
  .cmd-hero .ms-front.ms-yellow { --ms-c: var(--warn); }
  .cmd-hero .ms-front.ms-red    { --ms-c: var(--down); }

  /* base = mobile: one tight stack (radar → eyebrow → verdict/evidence → tape →
     divider → backdrop). At >=1100px it promotes to the side-by-side grid. */
  .cmd-hero .ms-front.ms { display: flex; flex-direction: column; gap: 14px; }
  .cmd-hero .ms-front > .rrx, .cmd-hero .ms-front > .ms-head { margin: 0; }
  .cmd-hero .ms-front > .ms-top, .cmd-hero .ms-front > .ms-tape { margin-top: 0; }
  .cmd-hero .ms-front > .ms-divider { margin: 4px 0 0; }
  @media (min-width: 1100px) {
    .cmd-hero .ms-front.ms { display: grid; gap: 0 30px; align-items: start;
      grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
      grid-template-areas: "radar radar" "head head" "state hero" "tape tape"; }
    .cmd-hero .ms-front > .rrx { grid-area: radar; margin-bottom: 12px; }
    .cmd-hero .ms-front > .ms-head { grid-area: head; }
    .cmd-hero .ms-front > .ms-top { grid-area: state; margin-top: 14px; }
    .cmd-hero .ms-front > .ms-tape { grid-area: tape; }
    .cmd-hero .ms-front > .ms-divider { display: none; }
    /* the backdrop, recomposed for the narrow right column: [locator | regime]
       on top, the four vitals as a 2×2 strip beneath — never the 3-up layout */
    .cmd-hero .ms-front > .hero-bar { grid-area: hero; margin-top: 14px; padding-left: 30px;
      border-left: var(--rule) solid var(--hair);
      grid-template-columns: auto minmax(0, 1fr); gap: 12px 18px; }
    .cmd-hero .ms-front > .hero-bar .hero-main { grid-column: 2; border: 0; padding: 0; }
    .cmd-hero .ms-front > .hero-bar .hero-vitals { grid-column: 1 / -1; gap: 12px 18px; }
  }

  /* Risk Radar — the shared .rrx card (engine/risk_radar_intl.py feeds it on these
     boards). Same markup + CSS as the US Macro/Stocks pages; global theme tokens only. */
  /* ============================================================================
     RISK RADAR CARD (.rrx) — the one shared, redesigned alert used on the US Macro
     + US-Stocks pages AND the China / HK / Canada Market-State boards (the macros
     live in _risk_radar_card.html.j2). GLOBAL theme vars only + an inline --rc state
     accent, so it renders the same in the page-macro, page-stocks and china/hk/canada
     scopes. The escalating odds ramp replaces the old cramped "5d.. 10d.. 21d.." run.
     Included by dashboard.html.j2 (both modes) + _market_state.css.j2 (CN/HK/CA). ==== */
  .rrx { --rc: var(--warn);
         display: grid; gap: 12px; margin: 12px 0 2px; padding: 15px 18px; border-radius: 12px;
         background: var(--panel);
         border: 1px solid var(--line);
         border-left: 4px solid var(--rc); font-size: 12.5px; line-height: 1.4;
         box-shadow: 0 1px 2px rgba(0,0,0,.06), 0 16px 32px -24px rgba(0,0,0,.4); }
  body.page-macro .ms-front > .rrx { margin: 0 0 14px; }
  /* grouping wrappers: inert everywhere by default (the card keeps its single-column
     stack on the China/HK/Canada/stocks placements); the macro front-page overrides
     these to display:flex to build the 2-column banner. */
  .rrx > .rrx-main, .rrx > .rrx-side { display: contents; min-width: 0; }
  /* Perf: loud pulse = pseudo animating ONLY opacity (compositor-run); animating
     box-shadow on the card repainted it every frame (2026-07-21 mobile audit).
     mmGlowBreathe keyframes ship in theme.css (loaded on every placement). */
  .rrx.rrx-loud { background: color-mix(in srgb, var(--rc) 5%, var(--panel));
         position: relative;
         box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--rc) 20%, transparent), 0 14px 34px -18px color-mix(in srgb, var(--rc) 70%, transparent); }
  .rrx.rrx-loud::before { content: ""; position: absolute; inset: 0; border-radius: inherit;
         pointer-events: none;
         box-shadow: 0 0 0 5px color-mix(in srgb, var(--rc) 6%, transparent);
         opacity: 0; animation: mmGlowBreathe 2.4s ease-in-out infinite; }
  @media (prefers-reduced-motion: reduce) { .rrx.rrx-loud::before { animation: none; opacity: 0; }
         .rrx.rrx-loud { box-shadow: 0 0 0 1px color-mix(in srgb, var(--rc) 30%, transparent); } }
  /* header */
  .rrx .rrx-hd { display: flex; align-items: flex-start; gap: 10px; }
  .rrx .rrx-ic { font-size: 18px; line-height: 1.1; flex: none; }
  .rrx .rrx-id { min-width: 0; flex: 1; }
  .rrx .rrx-ttl { display: flex; align-items: center; flex-wrap: wrap; gap: 7px;
         font-weight: 700; font-size: 13px; color: var(--text); }
  .rrx .rrx-badge { font-weight: 800; letter-spacing: .03em; color: var(--rc); font-size: 11.5px;
         font-variant-numeric: tabular-nums; padding: 1px 7px; border-radius: 5px;
         background: color-mix(in srgb, var(--rc) 16%, transparent);
         border: 1px solid color-mix(in srgb, var(--rc) 38%, transparent); }
  .rrx .rrx-dom { color: var(--muted); font-size: 11.5px; margin-top: 2px; }
  .rrx .rrx-authority { font-size: 10.5px; line-height: 1.35; margin-top: 3px; font-weight: 600; }
  .rrx .rrx-authority.is-advisory { color: var(--muted); }
  .rrx .rrx-authority.is-binding { color: var(--rc); }
  .rrx .rrx-amp { color: var(--rc); font-weight: 600; font-size: 11px; margin-top: 3px; }
  .rrx .rrx-gross { flex: none; text-align: center; padding: 3px 11px; border-radius: 9px;
         background: color-mix(in srgb, var(--rc) 12%, transparent);
         border: 1px solid color-mix(in srgb, var(--rc) 32%, transparent); }
  .rrx .rrx-gross .gv { display: block; font-weight: 800; font-size: 15px; color: var(--rc);
         font-variant-numeric: tabular-nums; line-height: 1.1; }
  .rrx .rrx-gross .gn { display: block; font-size: 9px; text-transform: uppercase; letter-spacing: .07em;
         color: var(--muted); }
  /* odds hero — flat on the card (the amber wash now lives on .rrx itself, not a nested box) */
  .rrx .rrx-odds { display: flex; gap: 16px; align-items: stretch; flex-wrap: wrap; }
  .rrx .rrx-odds-l { flex: 1 1 150px; display: flex; flex-direction: column; justify-content: center; }
  .rrx .rrx-cap { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .09em;
         color: var(--muted); }
  .rrx .rrx-cap-sub { font-weight: 600; letter-spacing: .02em; opacity: .8; }
  .rrx .rrx-big { font-weight: 800; font-size: 40px; line-height: .95; color: var(--rc); margin: 4px 0 2px;
         font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  .rrx .rrx-big .pct { font-size: 22px; margin-left: 1px; }
  .rrx .rrx-big .rrx-hz { font-size: 11px; font-weight: 600; color: var(--muted); margin-left: 7px;
         letter-spacing: 0; }
  .rrx .rrx-vsn { font-size: 11.5px; color: var(--muted); }
  .rrx .rrx-vsn b { color: var(--text); font-variant-numeric: tabular-nums; }
  /* escalating ramp */
  .rrx .rrx-ramp { flex: 1 1 240px; min-width: 0; max-width: 430px; display: flex; align-items: flex-end;
         justify-content: space-between; gap: 12px; position: relative; padding-top: 18px; }
  .rrx .rrx-col { flex: 1 1 0; min-width: 0; max-width: 76px; display: flex; flex-direction: column;
         align-items: center; gap: 5px; }
  .rrx .rrx-v { font-size: 12.5px; font-weight: 800; color: var(--text); font-variant-numeric: tabular-nums; }
  .rrx .rrx-col.is-hd .rrx-v { color: var(--rc); }
  .rrx .rrx-tk { width: 100%; max-width: 54px; height: 64px; position: relative;
         display: flex; align-items: flex-end; justify-content: center; border-bottom: 1px solid var(--line); }
  .rrx .rrx-norm { position: absolute; left: 0; right: 0; bottom: 0; border-radius: 2px 2px 0 0;
         background: repeating-linear-gradient(-45deg, color-mix(in srgb, var(--muted) 32%, transparent) 0 4px, transparent 4px 8px);
         border-top: 1px dashed color-mix(in srgb, var(--muted) 60%, transparent); }
  .rrx .rrx-fill { width: 100%; border-radius: 3px 3px 0 0; position: relative; z-index: 1; min-height: 6px;
         background: linear-gradient(180deg, var(--rc), color-mix(in srgb, var(--rc) 50%, transparent)); }
  .rrx .rrx-hl { font-size: 10.5px; font-weight: 600; color: var(--muted); }
  .rrx .rrx-col.is-hd .rrx-hl { color: var(--text); }
  .rrx .rrx-leg { position: absolute; top: 0; right: 2px; display: flex; align-items: center; gap: 4px;
         font-size: 9.5px; color: var(--muted); }
  .rrx .rrx-leg-n { width: 13px; border-top: 1px dashed color-mix(in srgb, var(--muted) 60%, transparent); }
  /* threat meters */
  .rrx .rrx-threats { display: flex; flex-wrap: wrap; gap: 6px; }
  .rrx .rrx-th { --sb: var(--muted); display: inline-flex; align-items: center; gap: 6px;
         padding: 3px 9px; border-radius: 7px; font-size: 11px;
         background: var(--panel); border: 1px solid var(--line); }
  .rrx .rrx-th.dom { background: color-mix(in srgb, var(--sb) 10%, var(--panel));
         border-color: color-mix(in srgb, var(--sb) 50%, var(--line)); }
  .rrx .rrx-th.dim { opacity: .58; }
  .rrx .rrx-th-n { color: var(--text); font-weight: 600; }
  .rrx .rrx-th.dom .rrx-th-n { color: var(--sb); }
  .rrx .rrx-meter { display: inline-flex; gap: 1.5px; }
  .rrx .rrx-meter i { width: 3px; height: 11px; border-radius: 1px;
         background: color-mix(in srgb, var(--muted) 28%, transparent); }
  .rrx .rrx-meter i.on { background: var(--sb); }
  .rrx .rrx-th-s { color: var(--text); font-weight: 800; font-size: 11.5px; font-variant-numeric: tabular-nums; }
  .rrx .rrx-tag { font-size: 8.5px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted);
         border: 1px solid var(--line); border-radius: 4px; padding: 0 4px; }
  .rrx .rrx-ev { font-size: 11px; color: var(--muted); }
  .rrx .rrx-ev-k { font-weight: 700; color: var(--text); margin-right: 6px; }
  .rrx .rrx-ev-p { color: var(--text); font-weight: 600; font-variant-numeric: tabular-nums; }
  /* action */
  .rrx .rrx-do { font-size: 12px; color: var(--text); padding-top: 9px;
         border-top: 1px solid color-mix(in srgb, var(--rc) 20%, var(--line)); }
  .rrx .rrx-do-k { font-weight: 800; color: var(--rc); text-transform: uppercase; letter-spacing: .06em;
         font-size: 10.5px; margin-right: 8px; }
  /* election-cycle context chip (US radar only; engine/election_cycle.py) */
  /* compressed to <=2 dense lines so the cycle context never balloons the card */
  .rrx .rrx-cyc { font-size: 10.5px; color: var(--muted); padding-top: 7px; margin-top: 2px; line-height: 1.4;
         border-top: 1px solid color-mix(in srgb, var(--rc) 16%, var(--line));
         display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 8px; row-gap: 1px; }
  .rrx .rrx-cyc-k { font-weight: 700; color: var(--text); }
  .rrx .rrx-cyc-tag { color: var(--rc); font-weight: 700; font-size: 9.5px; }
  /* RC-R11 washout counter-read chip — a cyan-tinted variant of the modulator row. */
  .rrx .rrx-cyc.rrx-washout { border-top-color: color-mix(in srgb, var(--cyan, #38bdf8) 22%, var(--line)); }
  .rrx .rrx-cyc.rrx-washout .rrx-cyc-k { color: var(--cyan, #38bdf8); }
  .rrx .rrx-cyc-sub { color: var(--muted); font-size: 10px; margin: 0; }
  .rrx .rrx-cyc-sec { color: var(--text); font-size: 10px; margin: 0; flex-basis: 100%;
         font-variant-numeric: tabular-nums; }
  /* self-audit line (international radars only) */
  .rrx .rrx-audit { font-size: 10.5px; color: var(--muted); }
  .rrx .rrx-audit-k { font-weight: 700; color: var(--text); margin-right: 6px; }
  .rrx .rrx-audit b { color: var(--text); font-variant-numeric: tabular-nums; }
  /* track-record line — one muted glance-tier line surfacing the forward-ledger scorecard */
  .rrx .rrx-trk { font-size: 10.5px; color: var(--muted); display: flex;
         align-items: center; gap: 5px; flex-wrap: wrap; line-height: 1.4; }
  /* de-escalation panel (engine/risk_radar_recovery.py) — "risk peaking / risk-off may be ending".
     Display-only; --rvc = green when receding, blue when merely peaking. Cool palette so it never
     reads like a green "all-clear" buy signal. */
  .rrx .rrx-rec { --rvc: var(--info); display: flex; flex-direction: column; gap: 7px;
         padding: 9px 11px; border-radius: 9px;
         background: color-mix(in srgb, var(--rvc) 7%, var(--panel));
         border: 1px solid color-mix(in srgb, var(--rvc) 30%, var(--line));
         border-left: 3px solid var(--rvc); }
  .rrx .rrx-rec.is-turn { background: color-mix(in srgb, var(--rvc) 13%, var(--panel));
         box-shadow: 0 0 0 1px color-mix(in srgb, var(--rvc) 26%, transparent); }
  .rrx .rrx-rec-hd { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
  .rrx .rrx-rec-ar { color: var(--rvc); font-weight: 800; font-size: 14px; line-height: 1; }
  .rrx .rrx-rec-ttl { font-weight: 700; font-size: 12px; color: var(--text); }
  .rrx .rrx-rec-tag { font-size: 8.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
         color: var(--rvc); background: color-mix(in srgb, var(--rvc) 16%, transparent);
         border: 1px solid color-mix(in srgb, var(--rvc) 42%, transparent); border-radius: 4px; padding: 0 5px; }
  .rrx .rrx-rec-mid { display: flex; align-items: center; gap: 9px; }
  .rrx .rrx-rec-spark { width: 84px; height: 24px; flex: none;
         background: color-mix(in srgb, var(--rvc) 5%, transparent); border-radius: 4px; }
  .rrx .rrx-rec-spark .pk { fill: var(--muted); }
  .rrx .rrx-rec-spark .lx { fill: var(--rvc); }
  .rrx .rrx-rec-sub { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; min-width: 0; }
  .rrx .rrx-rec-cats { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; }
  .rrx .rrx-rec-k { font-size: 9.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em;
         color: var(--muted); }
  .rrx .rrx-rec-chip { display: inline-flex; align-items: center; gap: 3px; font-size: 10.5px;
         color: var(--text); padding: 2px 7px; border-radius: 6px;
         background: var(--panel); border: 1px solid var(--line); }
  .rrx .rrx-rec-chip.fresh { color: var(--fresh-ok); font-weight: 600;
         border-color: color-mix(in srgb, var(--fresh-ok) 45%, var(--line));
         background: color-mix(in srgb, var(--fresh-ok) 10%, var(--panel)); }
  .rrx .rrx-rec-cats.none { font-size: 10.5px; color: var(--muted); font-style: italic; }
  /* RRX2 WA: drivers line ("what faded / still warm") + muted "no signal" chip */
  .rrx .rrx-rec-drv { font-size: 10px; color: var(--muted); line-height: 1.4; margin-top: -2px; }
  /* RLT-R5: measured-edge salience line — receipt/muted styling, demoted below catalyst chips */
  .rrx .rrx-rec-sal { font-size: 10px; color: var(--muted); font-style: italic; line-height: 1.4;
         padding: 2px 0 0; border-top: 1px solid color-mix(in srgb, var(--muted) 20%, transparent); margin-top: 1px; }
  .rrx .rrx-rec-chip.muted { color: var(--muted); font-style: italic; border-style: dashed; }
  .rrx .rrx-rec-do { font-size: 11px; color: var(--text); line-height: 1.4; }
  .rrx .rrx-rec-do-k { font-weight: 800; color: var(--rvc); text-transform: uppercase; letter-spacing: .06em;
         font-size: 9.5px; margin-right: 6px; }
  body:is(.page-macro, .page-china, .page-canada) .ms-front > .rrx { gap: 10px; padding: 13px 16px; }
  body:is(.page-macro, .page-china, .page-canada) .ms-front > .rrx .rrx-odds { gap: 14px; align-items: center; }
