  #hk-command-panel .cp-head{display:flex;flex-wrap:wrap;align-items:center;gap:9px 18px;margin-bottom:13px}
  #hk-command-panel .cp-verdict{display:inline-flex;align-items:center;gap:9px;flex-wrap:wrap}
  #hk-command-panel .cp-badge{font-size:13px;font-weight:800;letter-spacing:.02em;padding:4px 12px;border-radius:999px;
    border:1px solid var(--c,var(--muted));color:var(--c,var(--muted));background:color-mix(in srgb,var(--c,var(--muted)) 13%,transparent);white-space:nowrap}
  #hk-command-panel .cp-sub{font-size:11px;color:var(--muted)}
  #hk-command-panel .cp-meters{display:flex;gap:16px;margin-left:auto;flex-wrap:wrap}
  #hk-command-panel .cp-meter{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700}
  #hk-command-panel .cp-meter .lab{white-space:nowrap}
  #hk-command-panel .cp-bar{width:64px;height:6px;border-radius:3px;background:var(--panel2);border:1px solid var(--line);overflow:hidden}
  #hk-command-panel .cp-bar>i{display:block;height:100%;border-radius:3px;transition:width .4s ease}
  #hk-command-panel .cp-meter .n{font-variant-numeric:tabular-nums;min-width:26px;text-align:right}
  #hk-command-panel .cp-sec{font-size:10.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin:0 0 7px;font-weight:700}
  #hk-command-panel .cp-forces{display:grid;grid-template-columns:repeat(auto-fit,minmax(256px,1fr));gap:6px;margin-bottom:14px}
  #hk-command-panel .cp-force{display:flex;align-items:center;gap:8px;padding:6px 9px;border-radius:8px;background:var(--panel2);
    border:1px solid var(--line);}
