.strip { display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin:0 0 16px; }
.reg { font-size:12px; font-weight:800; letter-spacing:.02em; padding:5px 12px; border-radius:9px; border:1px solid var(--line); }
.reg.calm { color:var(--ink-up, var(--up)); background:color-mix(in srgb,var(--up) 12%,transparent); border-color:color-mix(in srgb,var(--up) 38%,var(--line)); }
.reg.mixed { color:var(--ink-warn, var(--warn)); background:color-mix(in srgb,var(--warn) 12%,transparent); border-color:color-mix(in srgb,var(--warn) 38%,var(--line)); }
.reg.stress { color:var(--ink-down, var(--down)); background:color-mix(in srgb,var(--down) 12%,transparent); border-color:color-mix(in srgb,var(--down) 38%,var(--line)); }
.reg.unknown { color:var(--muted); }
.stat { font-size:12px; color:var(--muted); padding:5px 12px; border:1px solid var(--line); border-radius:9px; background:var(--panel); }
.stat b { color:var(--text); font-size:14px; font-variant-numeric:tabular-nums; }
