html:not([data-lang="zh"]) .l-zh{display:none}html[data-lang="zh"] .l-en{display:none}
body.mm-page{margin:0;background:var(--mm-bg);color:var(--mm-text);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-variant-numeric:tabular-nums}
.mm-page::before{content:"";position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 18% 4%,rgba(107,156,255,.12),transparent 28%),radial-gradient(circle at 86% 22%,rgba(154,134,255,.09),transparent 25%),linear-gradient(180deg,transparent 0,rgba(8,13,22,.12) 100%)}
[data-theme="light"] .mm-page::before{background:radial-gradient(circle at 18% 4%,rgba(53,111,242,.07),transparent 28%),radial-gradient(circle at 86% 22%,rgba(117,92,232,.05),transparent 25%)}
.mm-shell{position:relative;z-index:1;max-width:1180px;margin:0 auto;padding:38px 22px 88px}
.mm-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:40px;padding:38px 42px;border:1px solid rgba(107,156,255,.22);border-radius:24px;background:linear-gradient(135deg,rgba(20,31,50,.94),rgba(12,18,30,.92));box-shadow:var(--mm-shadow);overflow:hidden;position:relative}
.mm-hero::after{content:"";position:absolute;width:360px;height:360px;right:-130px;top:-210px;border:1px solid rgba(107,156,255,.18);border-radius:50%;box-shadow:0 0 0 42px rgba(107,156,255,.025),0 0 0 96px rgba(154,134,255,.018)}
[data-theme="light"] .mm-hero{background:linear-gradient(135deg,#fff,#f4f7fd)}
.mm-hero-copy,.mm-authority{position:relative;z-index:1}.mm-hero-copy{max-width:690px}
.mm-kicker{margin:0 0 8px;color:var(--mm-blue);font-size:10.5px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}
.mm-hero h1{font-size:46px;line-height:1.02;letter-spacing:-.045em;margin:0 0 12px}.mm-deck{max-width:640px;margin:0;color:var(--mm-muted);font-size:17px;line-height:1.55}
.mm-authority{display:flex;align-items:center;gap:12px;min-width:280px;padding:15px 17px;border:1px solid var(--mm-line-hi);border-radius:14px;background:rgba(8,13,22,.38)}
[data-theme="light"] .mm-authority{background:rgba(255,255,255,.72)}
.mm-authority-mark{display:grid;place-items:center;width:42px;height:42px;flex:none;border-radius:12px;background:rgba(85,214,208,.11);border:1px solid rgba(85,214,208,.3);color:var(--mm-cyan);font-size:12px;font-weight:900}
.mm-authority strong,.mm-authority span{display:block}.mm-authority strong{font-size:13px}.mm-authority span{margin-top:3px;color:var(--mm-muted);font-size:10.5px;line-height:1.45}
.mm-readline{display:flex;gap:14px;align-items:flex-start;margin:16px 0 34px;padding:16px 20px;border:1px solid var(--mm-line);border-radius:14px;background:var(--mm-panel2)}
.mm-readline-glyph{color:var(--mm-cyan);font-size:20px}.mm-readline strong,.mm-readline span{display:block}.mm-readline strong{font-size:12.5px}.mm-readline span{margin-top:3px;color:var(--mm-muted);font-size:11.5px;line-height:1.5}
.mm-section{margin-top:24px;padding:28px;border:1px solid var(--mm-line);border-radius:20px;background:color-mix(in srgb,var(--mm-panel) 94%,transparent);box-shadow:0 15px 46px rgba(0,0,0,.08)}
.mm-section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:22px}.mm-section-head h2,.mm-honesty h2{margin:0;font-size:23px;letter-spacing:-.025em}.mm-section-head p:not(.mm-kicker){margin:5px 0 0;color:var(--mm-muted);font-size:12.5px}
.mm-state-pill{flex:none;padding:7px 12px;border:1px solid var(--mm-line-hi);border-radius:999px;color:var(--mm-muted);font-size:11px;font-weight:700}.mm-state-pill.is-live{color:var(--mm-green);border-color:color-mix(in srgb,var(--mm-green) 45%,var(--mm-line));background:color-mix(in srgb,var(--mm-green) 8%,transparent)}.mm-state-pill.is-error{color:var(--mm-amber);border-color:color-mix(in srgb,var(--mm-amber) 45%,var(--mm-line))}
.mm-query{display:grid;grid-template-columns:minmax(215px,1.2fr) repeat(5,minmax(92px,.65fr));gap:9px;margin-bottom:16px}.mm-query-card{min-width:0;padding:13px 14px;border:1px solid var(--mm-line);border-radius:12px;background:var(--mm-panel2)}.mm-query-card.is-state{background:linear-gradient(145deg,color-mix(in srgb,var(--mm-blue) 11%,var(--mm-panel2)),var(--mm-panel2))}.mm-query-card span,.mm-query-card strong{display:block}.mm-query-card span{color:var(--mm-faint);font-size:9.5px;text-transform:uppercase;letter-spacing:.07em}.mm-query-card strong{margin-top:5px;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mm-query-card small{display:block;margin-top:3px;color:var(--mm-muted);font-size:10px}
.mm-episode-list{display:grid;gap:9px}.mm-episode{display:grid;grid-template-columns:132px minmax(160px,1.05fr) minmax(220px,1.35fr) repeat(3,minmax(80px,.55fr));gap:12px;align-items:center;padding:13px 15px;border:1px solid var(--mm-line);border-radius:13px;background:var(--mm-panel2);transition:border-color .16s ease,transform .16s ease}.mm-episode:hover{border-color:var(--mm-line-hi);transform:translateY(-1px)}
.mm-episode-date strong,.mm-episode-date span{display:block}.mm-episode-date strong{font-size:13px}.mm-episode-date span{color:var(--mm-faint);font-size:9.5px;margin-top:3px}.mm-state-chips{display:flex;flex-wrap:wrap;gap:4px}.mm-chip{display:inline-flex;padding:3px 7px;border:1px solid var(--mm-line-hi);border-radius:999px;color:var(--mm-muted);font-size:9.5px;line-height:1.25}.mm-chip.is-fresh{color:var(--mm-green);border-color:color-mix(in srgb,var(--mm-green) 45%,var(--mm-line))}.mm-chip.is-old{color:var(--mm-faint)}.mm-chip.is-bull{color:var(--mm-green)}.mm-chip.is-bear{color:var(--mm-red)}
.mm-difference{color:var(--mm-muted);font-size:10.5px;line-height:1.5}.mm-difference b{color:var(--mm-text);font-weight:650}.mm-outcome{padding-left:10px;border-left:1px solid var(--mm-line)}.mm-outcome span,.mm-outcome strong{display:block}.mm-outcome span{color:var(--mm-faint);font-size:9px;text-transform:uppercase}.mm-outcome strong{margin-top:3px;font-size:13px}.mm-outcome.is-up strong{color:var(--mm-green)}.mm-outcome.is-down strong{color:var(--mm-red)}
.mm-footnote{margin:12px 2px 0;color:var(--mm-faint);font-size:10.5px;line-height:1.5}
.mm-symbol-head{align-items:center}.mm-search{min-width:330px}.mm-search label,.mm-search>span{display:block}.mm-search label{margin-bottom:6px;color:var(--mm-faint);font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.09em}.mm-search-row{display:flex}.mm-search input{width:145px;min-width:0;padding:10px 12px;border:1px solid var(--mm-line-hi);border-right:0;border-radius:10px 0 0 10px;background:var(--mm-panel2);color:var(--mm-text);font:700 13px/1 Inter,sans-serif;text-transform:uppercase;outline:none}.mm-search input:focus{border-color:var(--mm-blue);box-shadow:0 0 0 3px rgba(107,156,255,.1)}.mm-search button{padding:10px 14px;border:0;border-radius:0 10px 10px 0;background:var(--mm-blue);color:#fff;font:750 11.5px/1 Inter,sans-serif;cursor:pointer}.mm-search button:hover{filter:brightness(1.08)}.mm-search>span{margin-top:5px;color:var(--mm-faint);font-size:9.5px}
.mm-symbol-summary{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:15px;padding:15px 17px;border:1px solid var(--mm-line);border-radius:13px;background:var(--mm-panel2)}.mm-symbol-id{display:flex;align-items:center;gap:12px}.mm-symbol-ticker{display:grid;place-items:center;min-width:56px;height:38px;padding:0 10px;border-radius:10px;background:rgba(107,156,255,.12);color:var(--mm-blue);font-size:13px;font-weight:900}.mm-symbol-id strong,.mm-symbol-id span{display:block}.mm-symbol-id span{margin-top:2px;color:var(--mm-muted);font-size:10.5px}.mm-symbol-meta{display:flex;gap:22px}.mm-symbol-meta div{text-align:right}.mm-symbol-meta span,.mm-symbol-meta strong{display:block}.mm-symbol-meta span{color:var(--mm-faint);font-size:9px;text-transform:uppercase}.mm-symbol-meta strong{margin-top:3px;font-size:12px}
.mm-grid-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.mm-grid-card{min-width:0;padding:17px;border:1px solid var(--mm-line);border-radius:var(--r-card,12px);background:var(--mm-panel2)}.mm-grid-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;padding-bottom:12px;border-bottom:1px solid var(--mm-line)}.mm-grid-head h3{margin:0;font-size:14px}.mm-grid-head p{margin:3px 0 0;color:var(--mm-muted);font-size:9.5px}.mm-class-row{display:flex;flex-wrap:wrap;gap:4px;margin:11px 0}.mm-horizon{padding:11px 0;border-top:1px solid var(--mm-line)}.mm-horizon:first-of-type{border-top:0}.mm-horizon-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.mm-horizon-head strong{font-size:11px}.mm-horizon-head span{color:var(--mm-faint);font-size:9px}.mm-stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.mm-stat{padding:8px;border-radius:var(--r-card,12px);background:var(--panel2)}.mm-stat span,.mm-stat strong{display:block}.mm-stat span{color:var(--mm-faint);font-size:8.5px}.mm-stat strong{margin-top:3px;font-size:13px}.mm-support{margin-top:8px;color:var(--mm-muted);font-size:9.5px;line-height:1.45}.mm-era-note{margin-top:7px;padding:6px 8px;border:1px solid var(--line);background:var(--panel2);color:var(--mm-amber);font-size:9px;line-height:1.45}
.mm-details{margin-top:10px;border-top:1px dashed var(--mm-line-hi);padding-top:8px}.mm-details summary{color:var(--mm-faint);font-size:9.5px;cursor:pointer}.mm-details p{margin:7px 0 0;color:var(--mm-muted);font-size:9.5px;line-height:1.5}
.mm-honesty{display:grid;grid-template-columns:260px 1fr;gap:26px;margin-top:24px;padding:28px;border:1px solid var(--mm-line);border-radius:20px;background:linear-gradient(145deg,var(--mm-panel),var(--mm-panel2))}.mm-honesty-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mm-honesty article{display:flex;gap:11px;padding:15px;border:1px solid var(--mm-line);border-radius:12px;background:color-mix(in srgb,var(--mm-panel2) 80%,transparent)}.mm-honesty article>span{display:grid;place-items:center;width:29px;height:29px;flex:none;border-radius:9px;font-size:12px;font-weight:900}.mm-check{color:var(--mm-green);background:rgba(69,210,139,.1)}.mm-clock{color:var(--mm-amber);background:rgba(234,183,93,.1)}.mm-honesty strong{font-size:11.5px}.mm-honesty article p{margin:4px 0 0;color:var(--mm-muted);font-size:10.5px;line-height:1.5}
.mm-skeleton{height:82px;border:1px solid var(--mm-line);border-radius:13px;background:linear-gradient(100deg,var(--mm-panel2) 25%,color-mix(in srgb,var(--mm-line) 65%,var(--mm-panel2)) 42%,var(--mm-panel2) 60%);background-size:300% 100%;animation:mm-shimmer 1.7s infinite}.mm-skeleton-query{height:72px;grid-column:1/-1}@keyframes mm-shimmer{0%{background-position:100% 0}100%{background-position:0 0}}@media(prefers-reduced-motion:reduce){.mm-skeleton{animation:none}.mm-episode{transition:none}}
.mm-empty{padding:26px;border:1px dashed var(--mm-line-hi);border-radius:13px;text-align:center;color:var(--mm-muted)}.mm-empty strong,.mm-empty span{display:block}.mm-empty strong{color:var(--mm-text);font-size:13px}.mm-empty span{margin-top:5px;font-size:10.5px;line-height:1.5}.mm-empty a{color:var(--mm-blue)}
@media(max-width:980px){.mm-hero{align-items:flex-start;flex-direction:column}.mm-authority{width:100%}.mm-query{grid-template-columns:repeat(3,1fr)}.mm-query-card.is-state{grid-column:span 3}.mm-episode{grid-template-columns:115px 1fr 1.25fr repeat(3,72px)}.mm-grid-list{grid-template-columns:1fr}.mm-honesty{grid-template-columns:1fr}.mm-symbol-head{align-items:flex-start;flex-direction:column}.mm-search{width:100%;min-width:0}}
@media(max-width:720px){.mm-shell{padding:22px 14px 58px}.mm-hero{padding:28px 22px;border-radius:18px}.mm-hero h1{font-size:36px}.mm-deck{font-size:14px}.mm-section{padding:20px 15px}.mm-section-head{align-items:flex-start;flex-direction:column}.mm-query{grid-template-columns:1fr 1fr}.mm-query-card.is-state{grid-column:1/-1}.mm-episode{grid-template-columns:1fr 1fr;gap:9px}.mm-episode-date{grid-column:1}.mm-state-chips{grid-column:2}.mm-difference{grid-column:1/-1}.mm-outcome{padding:8px 0 0;border-left:0;border-top:1px solid var(--mm-line)}.mm-symbol-summary{align-items:flex-start;flex-direction:column}.mm-symbol-meta{width:100%;justify-content:space-between}.mm-symbol-meta div{text-align:left}.mm-honesty-grid{grid-template-columns:1fr}.mm-search-row{width:100%}.mm-search input{flex:1;width:auto}}
@media(max-width:420px){.mm-query{grid-template-columns:1fr}.mm-query-card.is-state{grid-column:auto}.mm-episode{grid-template-columns:1fr}.mm-state-chips,.mm-difference{grid-column:1}.mm-stat-row{grid-template-columns:1fr 1fr}.mm-authority{min-width:0}}

