/* ── Hub v2: Prediction Layer ───────────────────────────────────────────── */
.pl-unavail{padding:14px;border-radius:8px;
  background:color-mix(in srgb,var(--muted) 10%,transparent);
  border:1px solid var(--border,rgba(255,255,255,.06));
  font-size:.85rem;color:var(--muted,#8899aa)}
.pl-meta-row{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:20px;align-items:center}
.pl-meta-chip{font-size:.75rem;padding:4px 10px;border-radius:5px;
  border:1px solid var(--border,rgba(255,255,255,.1));color:var(--muted,#8899aa)}
.pl-meta-chip strong{color:var(--text,#e2e8f0)}
.pl-stale-note{font-size:.78rem;color:var(--muted,#8899aa);font-style:italic}
.pl-revopt-warn{font-size:.78rem;color:var(--warn-ink);margin-left:4px}
.pl-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-bottom:28px}
.pl-cell{border-radius:8px;padding:14px;border:1px solid var(--border,rgba(255,255,255,.08));
  background:color-mix(in srgb,var(--surface,#0f1629) 60%,transparent)}
.pl-cell-pass{border-color:color-mix(in srgb,var(--ok,#3da564) 30%,transparent);
  background:color-mix(in srgb,var(--ok,#3da564) 5%,transparent)}
.pl-cell-prior{border-color:color-mix(in srgb,var(--muted,#8899aa) 20%,transparent)}
.pl-cell-dir{font-size:.68rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:var(--muted,#8899aa);margin-bottom:4px}
.pl-cell-horizon{font-size:.95rem;font-weight:800;color:var(--text,#e2e8f0);margin-bottom:8px}
.pl-badge{display:inline-block;font-size:.72rem;font-weight:700;padding:3px 8px;
  border-radius:4px;margin-bottom:8px}
.pl-badge-pass{background:color-mix(in srgb,var(--ok,#3da564) 18%,transparent);
  color:var(--ok-ink);border:1px solid color-mix(in srgb,var(--ok) 30%,transparent)}
.pl-badge-prior{background:color-mix(in srgb,var(--muted,#8899aa) 12%,transparent);
  color:var(--muted,#8899aa);border:1px solid color-mix(in srgb,var(--muted) 25%,transparent)}
.pl-cell-stat{font-size:.72rem;color:var(--muted,#8899aa);line-height:1.5}
.pl-cell-stat strong{color:var(--text,#e2e8f0)}
/* Adoption gaps */
.pl-gaps-section{margin-top:8px}
.pl-gaps-title{font-size:.75rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  color:var(--muted,#8899aa);margin-bottom:12px}
.pl-gap-list{list-style:none;padding:0;margin:0 0 20px;display:flex;flex-direction:column;gap:10px}
.pl-gap-item{padding:12px 16px;border-radius:8px;border:1px solid var(--border,rgba(255,255,255,.07));
  background:color-mix(in srgb,var(--warn,#f59e0b) 4%,transparent);font-size:.8rem}
.pl-gap-item.pl-gap-allnull{background:color-mix(in srgb,var(--fail,#ef4444) 5%,transparent);
  border-color:color-mix(in srgb,var(--fail,#ef4444) 20%,transparent)}
.pl-gap-hd{font-weight:700;color:var(--text,#e2e8f0);margin-bottom:5px}
.pl-gap-note{color:var(--muted,#8899aa);line-height:1.5}
.pl-gap-meta{font-size:.7rem;color:var(--muted,#8899aa);margin-top:5px;font-family:var(--font-mono)}
.pl-gap-tag{display:inline-block;font-size:.65rem;padding:1px 6px;border-radius:3px;margin-left:6px;
  background:color-mix(in srgb,var(--muted) 12%,transparent);color:var(--muted,#8899aa)}

/* ── Hub v2: Coverage Matrix ────────────────────────────────────────────── */
.cm-note{font-size:.82rem;color:var(--muted,#8899aa);max-width:720px;margin:0 0 16px;line-height:1.6}
.cm-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
.cm-table{width:100%;min-width:700px;border-collapse:collapse;font-size:.8rem}
.cm-table th{text-align:left;padding:8px 12px;font-size:.7rem;font-weight:700;
  color:var(--muted,#8899aa);border-bottom:1px solid var(--border,rgba(255,255,255,.08));
  text-transform:uppercase;letter-spacing:.06em}
.cm-table td{padding:9px 12px;border-bottom:1px solid var(--border,rgba(255,255,255,.04));
  color:var(--text,#e2e8f0);vertical-align:middle;line-height:1.4}
.cm-table tr:last-child td{border-bottom:none}
.cm-page{font-size:.8rem;font-weight:600;color:var(--text,#e2e8f0);font-family:var(--font-mono)}
.cm-yes{font-weight:700;color:var(--ok-ink)}
.cm-partial{font-weight:700;color:var(--warn-ink)}
.cm-no{color:var(--muted,#8899aa);font-size:.75rem}
.cm-hint{font-size:.65rem;color:var(--muted,#8899aa);display:block;margin-top:2px;font-family:var(--font-mono)}
.cm-audit{font-size:.72rem;color:var(--muted,#8899aa);font-style:italic;margin-top:8px}

/* ── Machine strings must break, not escape ──────────────────────────────────
   Truth ids, feature slugs, file paths and the statements that quote them are
   long unbroken tokens. `anywhere` rather than `break-word` on purpose: only
   `anywhere` also shrinks min-content, and min-content is what was forcing the
   null-library grid (and with it the whole page) to scroll sideways at 390px. */
.pm-truth-table td,.pm-truth-table th,
.mh-gate-table td,.mh-exp-table td,.ac-table td,.eg-table td,.cm-table td,
.nl-card,.mh-collin-block li,.pl-gap-meta,.pl-gap-note,.mh-prov-cell dd,
.mh-eng-epoch,.pm-status-chip,.mh-note,.mh-loop-step,.eg-footnote{overflow-wrap:anywhere}

/* ── Quality floor ───────────────────────────────────────────────────────── */
.mh-tab:focus-visible,.mh-stand a:focus-visible{outline:2px solid var(--blue);outline-offset:2px}
@media(prefers-reduced-motion:reduce){
  .mh-tab,.sg-sync-fill{transition:none}
}
@media(max-width:720px){
  .mh-loop{grid-template-columns:1fr}
  .mh-loop-step + .mh-loop-step{border-left:1px solid var(--border);border-top:none}
  .mh-loop-step:first-child{border-radius:10px 10px 0 0}
  .mh-loop-step:last-child{border-radius:0}
  .mh-deck{font-size:.95rem}
  .mh-stand{font-size:.86rem}
}

/* ── Research Implications (F10-X1) ────────────────────────────────────────
   Two frozen estimator runs whose honest headline is that NEITHER is usable:
   one failed its own estimator-unbiasedness check, one is missing an input receipt. The
   templated answer — big number, small label, coloured badge — is exactly
   wrong here, because it makes the number the hero when the number is the one
   thing the reader must not act on. So the state leads, and a full-height
   verdict rail binds that state to every figure in the card: you cannot read a
   value without the verdict sitting in peripheral vision.

   Red vs amber is this section's real content, and the page had no vocabulary
   for the difference before: --act = tested and FAILED; --warn = NOT JUDGED,
   an input receipt is absent. Collapsing those two into one "bad" colour would
   destroy the distinction the cards exist to make.

   The two themes are two art directions, not one skin:
   dark  = instrument panel — card lifted off the canvas by luminance, hairline
           borders, the rail carries a soft bloom.
   light = research sheet — white paper on the cool canvas, zero glow; depth
           comes from a shadow and a crisper rule. Same structure, same
           semantics, different material. */
.ric-lede{font-size:.83rem;line-height:1.65;color:var(--muted);max-width:74ch;
  margin:12px 0 18px;padding-left:15px}

/* Filters hide, never reorder — a sort control would imply a ranking. */
.ric-filter{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 22px;padding:0;border:0}
.ric-filter legend{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.ric-fbtn{padding:5px 12px;border-radius:var(--r-pill,999px);border:1px solid var(--border);
  background:transparent;color:var(--muted);font-size:.76rem;cursor:pointer;
  font-family:var(--font-ui);transition:color .15s,border-color .15s,background .15s}
.ric-fbtn:hover{color:var(--text);border-color:color-mix(in srgb,var(--text) 28%,transparent)}
.ric-fbtn[aria-pressed="true"]{background:var(--accent-deep);border-color:var(--accent-deep);
  color:var(--text);font-weight:600}
html[data-theme="light"] .ric-fbtn[aria-pressed="true"]{color:var(--panel)}
.ric-fbtn:focus-visible{outline:2px solid var(--blue);outline-offset:2px}

.ric-cards{display:flex;flex-direction:column;gap:20px}
.ric-card{display:grid;grid-template-columns:5px minmax(0,1fr);
  border:1px solid var(--border);border-radius:var(--r-card,12px);overflow:hidden;
  background:var(--card)}
.ric-card[hidden]{display:none}
.ric-rail{background:var(--muted)}
.ric-card.ric-s-complete .ric-rail{background:var(--ink-ok)}
.ric-card.ric-s-diagnostic .ric-rail{background:repeating-linear-gradient(180deg,var(--muted) 0 10px,transparent 10px 16px)}
.ric-card.ric-s-stale .ric-rail{background:repeating-linear-gradient(135deg, var(--muted) 0 3px, transparent 3px 6px)}
.ric-card.ric-s-missing .ric-rail{background:var(--warn)}
.ric-card.ric-s-failed  .ric-rail{background:var(--act)}
.ric-card.ric-s-incomplete .ric-rail{background:var(--warn)}
html[data-theme="dark"] .ric-card.ric-s-complete .ric-rail{box-shadow:0 0 12px 0 color-mix(in srgb,var(--ink-ok) 55%,transparent)}
html[data-theme="dark"] .ric-card.ric-s-diagnostic .ric-rail{box-shadow:0 0 12px 0 color-mix(in srgb,var(--muted) 40%,transparent)}
html[data-theme="dark"] .ric-card.ric-s-stale .ric-rail{box-shadow:0 0 12px 0 color-mix(in srgb,var(--muted) 40%,transparent)}
html[data-theme="dark"] .ric-card.ric-s-missing .ric-rail{box-shadow:0 0 12px 0 color-mix(in srgb,var(--warn) 55%,transparent)}
html[data-theme="dark"] .ric-card.ric-s-failed  .ric-rail{box-shadow:0 0 12px 0 color-mix(in srgb,var(--act) 55%,transparent)}
html[data-theme="dark"] .ric-card.ric-s-incomplete .ric-rail{box-shadow:0 0 12px 0 color-mix(in srgb,var(--warn) 55%,transparent)}
/* Light: paper, not panel — the glow is removed outright and depth is a shadow. */
html[data-theme="light"] .ric-card{background:var(--panel);box-shadow:var(--card-shadow)}
html[data-theme="light"] .ric-rail{box-shadow:none}

.ric-body{padding:20px 22px;min-width:0}
.ric-hd{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:12px}
.ric-state{font-size:.78rem;font-weight:700;letter-spacing:.02em;color:var(--muted)}
.ric-card.ric-s-complete .ric-state{color:var(--ink-ok)}
.ric-card.ric-s-stale .ric-state{color:var(--muted)}
.ric-card.ric-s-other .ric-state{color:var(--muted)}
.ric-card.ric-s-missing .ric-state{color:var(--warn-ink)}
.ric-card.ric-s-failed  .ric-state{color:var(--act-ink)}
.ric-card.ric-s-incomplete .ric-state{color:var(--warn-ink)}
.ric-q{font-size:1rem;font-weight:700;line-height:1.45;margin:0 0 8px;color:var(--text)}
.ric-estimand{font-size:.82rem;line-height:1.6;color:var(--muted);margin:0 0 16px;max-width:70ch}

/* Figures: last row fills leftover columns instead of leaving empty tracks. */
.ric-figs{display:flex;flex-wrap:wrap;align-items:flex-start;gap:12px;margin:0 0 16px}
.ric-fig{flex:1 1 190px;padding:10px 12px;border-radius:var(--r-ctl,8px);
  background:color-mix(in srgb,var(--text) 4%,transparent)}
html[data-theme="light"] .ric-fig{background:color-mix(in srgb,var(--text) 5%,transparent)}
.ric-fig-l{display:block;font-size:.7rem;color:var(--muted);margin-bottom:4px;line-height:1.35}
.ric-fig-v{font-family:var(--font-mono,ui-monospace,SFMono-Regular,Menlo,monospace);
  font-size:.95rem;font-weight:600;color:var(--text);font-variant-numeric:tabular-nums}
.ric-fig-u{font-size:.68rem;color:var(--muted);margin-left:5px;font-weight:400}
.ric-fig-sub{display:block;margin-top:3px;font-family:var(--font-sans,system-ui,sans-serif);
  font-size:.65rem;line-height:1.4;color:var(--muted);font-weight:400}
/* A null is typed, never zero: the em dash is the value, the reason is beside it. */
.ric-null{color:var(--muted);font-weight:400}
.ric-why{display:block;font-size:.68rem;color:var(--muted);margin-top:5px;line-height:1.45}

/* Ordered effect path — drawn ONLY where the owner marked the horizons ordered. */
.ric-path{margin:4px 0 18px;padding:14px 14px 10px;border-radius:var(--r-btn,10px);
  border:1px solid var(--border);background:color-mix(in srgb,var(--text) 3%,transparent)}
html[data-theme="light"] .ric-path{background:var(--panel)}
.ric-path-t{font-size:.72rem;color:var(--muted);margin-bottom:8px;line-height:1.45}
.ric-path svg{display:block;width:100%;height:auto;overflow:visible}
.ric-path-zero{stroke:var(--border);stroke-width:1;stroke-dasharray:3 3}
.ric-path-anchor{stroke:color-mix(in srgb,var(--text) 30%,transparent);stroke-width:1}
.ric-path-selected{stroke:var(--warn);stroke-width:1;stroke-dasharray:2 3}
.ric-path-line{fill:none;stroke:var(--blue);stroke-width:2;
  stroke-linejoin:round;stroke-linecap:round}
.ric-path-dot{fill:var(--blue)}
.ric-path-dot-selected{fill:var(--warn);stroke:var(--panel);stroke-width:1.5}
.ric-path-ax{font-family:var(--font-mono,ui-monospace,SFMono-Regular,Menlo,monospace);
  font-size:9px;fill:var(--muted)}
.ric-path-callout{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:baseline;
  margin-top:6px;font-size:.7rem;line-height:1.45;color:var(--muted)}
.ric-path-callout code{font-size:.62rem;color:var(--warn-ink);background:color-mix(in srgb,var(--warn) 12%,transparent);
  padding:2px 6px;border-radius:var(--r-ctl,8px)}

/* Gate outcomes: the PC-1/PC-2 story, in the contract's own pass/fail terms. */
.ric-gates-l{font-size:.72rem;font-weight:600;letter-spacing:.04em;color:var(--muted);
  text-transform:uppercase;margin:0 0 8px}
.ric-gates{display:flex;flex-direction:column;gap:8px;margin:0 0 4px}
.ric-gate{font-size:.78rem;line-height:1.55;display:flex;align-items:flex-start;gap:8px}
.ric-gate::before{content:"";flex:0 0 8px;width:8px;height:8px;margin-top:.45em;border-radius:var(--r-pill,999px)}
.ric-gate.ric-g-met::before{background:var(--ink-ok)}
.ric-gate.ric-g-not::before{background:var(--act)}
.ric-gate.ric-g-not .ric-g-lead{font-weight:600}
.ric-gate-b{min-width:0}
.ric-gate-n{color:var(--muted);display:block;margin-top:2px;font-size:.74rem}

/* Progressive disclosure: the lab page may go deep, but not all at once. */
.ric-more{border-top:1px solid var(--border);margin-top:4px}
.ric-more>summary{list-style:none;cursor:pointer;padding:11px 2px 11px 0;
  font-size:.78rem;font-weight:600;color:var(--muted);display:flex;align-items:center;gap:8px}
.ric-more>summary::-webkit-details-marker{display:none}
.ric-more>summary:hover{color:var(--text)}
.ric-more>summary:focus-visible{outline:2px solid var(--blue);outline-offset:2px;border-radius:var(--r-ctl,8px)}
.ric-more>summary::before{content:"+";font-family:var(--font-mono,ui-monospace,monospace);
  font-size:.9rem;line-height:1;width:11px;color:var(--muted);transition:transform .18s}
.ric-more[open]>summary::before{content:"−"}
.ric-gate .ric-more{border-top:none;margin-top:2px}
.ric-gate .ric-more>summary{padding:4px 0}
.ric-more-b{padding:2px 0 16px;font-size:.79rem;line-height:1.65;color:var(--muted)}
.ric-list{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px}
.ric-list li{padding-left:13px;position:relative}
.ric-list li::before{content:"";position:absolute;left:0;top:.62em;width:5px;height:1px;background:var(--muted)}
.ric-count{font-family:var(--font-mono,ui-monospace,monospace);color:var(--text);font-weight:600}

/* Receipts: a citation without a digest is not a receipt. */
.ric-rc{display:grid;grid-template-columns:auto minmax(0,1fr);gap:5px 12px;
  font-family:var(--font-mono,ui-monospace,SFMono-Regular,Menlo,monospace);font-size:.68rem;line-height:1.6}
.ric-rc dt{color:var(--muted)}
.ric-rc dd{margin:0;color:var(--text);word-break:break-all}

/* Zero authority is a claim the reader must be able to check, not an omission. */
.ric-auth{margin-top:14px;padding-top:13px;border-top:1px solid var(--border);
  font-size:.72rem;color:var(--muted);line-height:1.6}
.ric-auth-f{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}
.ric-auth-f code{font-size:.64rem;padding:2px 6px;border-radius:var(--r-ctl,8px);
  background:color-mix(in srgb,var(--text) 7%,transparent);color:var(--muted)}

@media (max-width:640px){
  .ric-body{padding:16px 15px}
  .ric-figs{gap:9px}
  .ric-fig{flex-basis:100%}
  .ric-q{font-size:.94rem}
  .ric-rc{grid-template-columns:1fr;gap:2px 0}
  .ric-rc dt{margin-top:6px}
}
@media (prefers-reduced-motion:reduce){
  .ric-fbtn,.ric-more>summary::before{transition:none}
}
.ric-prereg{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;
  font-size:.72rem;line-height:1;padding:4px 9px;border-radius:var(--r-pill,999px);
  border:1px solid var(--border);color:var(--muted)}
.ric-prereg-d{flex:none;width:5px;height:5px;border-radius:var(--r-pill,999px);background:var(--blue-ink)}
.ric-prereg.is-absent .ric-prereg-d{background:transparent;border:1px solid var(--muted)}
html[data-theme="dark"] .ric-prereg{background:color-mix(in srgb,var(--text) 6%,transparent)}
html[data-theme="dark"] .ric-prereg:not(.is-absent) .ric-prereg-d{
  box-shadow:0 0 6px 0 color-mix(in srgb,var(--blue) 70%,transparent)}
html[data-theme="light"] .ric-prereg{background:var(--panel);
  border-color:color-mix(in srgb,var(--text) 22%,transparent);box-shadow:var(--card-shadow)}
html[data-theme="light"] .ric-prereg:not(.is-absent) .ric-prereg-d{box-shadow:none}
.ric-prereg-why{margin:-8px 0 16px;max-width:70ch;font-size:.74rem;line-height:1.6;color:var(--muted)}
.ric-stance{margin:16px 0 0;padding-top:13px;border-top:1px solid var(--line);
  font-size:1rem;line-height:1.5;font-weight:600;color:var(--text)}
.ric-copy{margin:0;max-width:70ch;font-size:1rem;line-height:1.5;font-weight:600;color:var(--text)}
html[data-theme="dark"] .ric-stance{box-shadow:none}
html[data-theme="light"] .ric-stance{border-top-color:var(--line)}
.ric-nulls{margin:0 0 16px;padding:12px 14px;border:1px solid var(--border);border-radius:var(--r-card,12px);
  background:color-mix(in srgb,var(--text) 4%,transparent)}
.ric-nulls-t{margin:0 0 8px;font-size:.72rem;letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}
.ric-nulls ul{margin:0;padding:0;list-style:none;display:grid;gap:8px}
.ric-nulls li{font-size:.78rem;line-height:1.55;color:var(--text)}
html[data-theme="light"] .ric-nulls{background:var(--panel);box-shadow:var(--card-shadow)}
.ric-filter-count{margin:-12px 0 18px;font-size:.74rem;color:var(--muted)}
/* Preserved Research Verdicts (#vp-section) — theme.css tokens only.
   DARK: luminance steps (--bg -> --panel card -> --panel2 badge) + hairline; no shadow, no glow.
   LIGHT: white --panel material + --card-shadow; shadow, never glow. */
#vp-section .vp-lede{margin:6px 0 0;font-size:var(--fs-sm);color:var(--muted);line-height:1.5;max-width:72ch}
#vp-section .vp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr));gap:12px;margin-top:14px}
#vp-section .vp-card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r-card,12px);padding:14px 16px;display:flex;flex-direction:column;gap:8px;min-width:0}
#vp-section .vp-head{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}
#vp-section .vp-key{font-family:var(--font-mono);font-size:var(--fs-label);color:var(--muted);letter-spacing:.04em}
#vp-section .vp-badge{display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-label);font-weight:650;letter-spacing:.03em;padding:3px 8px;border-radius:var(--r-ctl,8px);background:var(--panel2);border:1px solid var(--line);color:var(--text)}
#vp-section .vp-badge::before{content:"";width:6px;height:6px;border-radius:var(--r-ctl,8px);background:var(--muted)}
#vp-section .vp-s-insufficient_support,#vp-section .vp-s-pit_partial{color:var(--ink-warn)}
#vp-section .vp-s-insufficient_support::before,#vp-section .vp-s-pit_partial::before{background:var(--ink-warn)}
#vp-section .vp-s-mixed,#vp-section .vp-s-law{color:var(--ink-info)}
#vp-section .vp-s-mixed::before,#vp-section .vp-s-law::before{background:var(--ink-info)}
#vp-section .vp-s-broken{color:var(--ink-orange)}
#vp-section .vp-s-broken::before{background:var(--ink-orange)}
#vp-section .vp-s-not_supported,#vp-section .vp-s-scoped_null{color:var(--text)}
#vp-section .vp-s-not_supported::before,#vp-section .vp-s-scoped_null::before{background:var(--muted)}
#vp-section .vp-s-counterfactual{border-style:dashed;background:transparent;color:var(--muted)}
#vp-section .vp-s-counterfactual::before{background:transparent;border:1px solid var(--muted)}
#vp-section .vp-plain{margin:0;font-size:var(--fs-sm);line-height:1.5;color:var(--text)}
#vp-section .vp-receipt{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:4px 12px;margin:0;font-size:var(--fs-label);border-top:1px solid var(--line);padding-top:8px}
#vp-section .vp-receipt dt{color:var(--muted);text-transform:uppercase;letter-spacing:.05em;font-size:var(--fs-micro)}
#vp-section .vp-receipt dd{margin:0;color:var(--text);overflow-wrap:anywhere;min-width:0}
#vp-section .vp-receipt code{font-family:var(--font-mono);font-size:var(--fs-label)}
#vp-section .vp-chip{display:inline-flex;align-items:center;padding:2px 7px;border-radius:var(--r-ctl,8px);border:1px dashed var(--line);color:var(--muted);font-size:var(--fs-micro)}
#vp-section .vp-cf{grid-column:1/-1;margin-left:24px;background:transparent;border-style:dashed;padding:10px 14px}
#vp-section .vp-cf .vp-plain{color:var(--muted)}
#vp-section .vp-ref{margin:0;font-size:var(--fs-micro);color:var(--muted)}
#vp-section .vp-ref a{color:var(--ink-link)}
#vp-section .vp-dnc{margin:16px 0 0;padding-top:12px;border-top:1px solid var(--line)}
#vp-section .vp-dnc h3{margin:0 0 6px;font-size:var(--fs-label);font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}
#vp-section .vp-dnc ul{margin:0;padding-left:18px;color:var(--muted);font-size:var(--fs-sm);line-height:1.55}
html[data-theme="light"] #vp-section .vp-card{box-shadow:var(--card-shadow)}
html[data-theme="light"] #vp-section .vp-cf{box-shadow:none}
@media (max-width:720px){ #vp-section .vp-cf{margin-left:12px} #vp-section .vp-receipt{grid-template-columns:1fr}}

rules.new:
/* ── Calibration Lab — page-specific styles ──────────────────────────────── */
body{margin:0;padding-top:24px;background:var(--bg);color:var(--text)}

/* ── Token bridge ────────────────────────────────────────────────────────────
   This page loads ONLY theme.css, which does not define --border / --card /
   --surface / --blue / --fail. Every `var(--border,rgba(255,255,255,.08))` on
   this page was therefore resolving to its hard-coded DARK fallback in light
   mode: invisible hairlines, invisible card fills, and — worst — the tinted
   banners mixing over --surface:#0f1629, i.e. a near-black box with dark text
   on the light canvas. Defining the five names on .mh-wrap (which contains the
   whole page, but NOT the shared nav chrome) maps them onto real theme tokens,
   so both themes resolve at paint with no per-rule edits.

   --ok/--act, NOT --up/--down: theme.css swaps --up/--down under
   html[data-lang="zh"] for the Asia 红涨绿跌 convention, and states in its own
   comment that status colours "encode health/danger, NOT price direction".
   Every green/red on this page is a PASS/FAIL/health reading, so painting them
   from --up/--down rendered PASS red and FAIL green for Chinese readers. */
.mh-wrap{
  --border:  color-mix(in srgb, var(--text) 13%, transparent);
  --card:    color-mix(in srgb, var(--panel) 88%, transparent);
  --surface: var(--panel);
  --blue:    var(--info);
  --fail:    var(--act);
  /* ── Chip ink ──────────────────────────────────────────────────────────────
     Status chips paint hue-coloured text on a 12–18% tint of the same hue.
     On the light theme's white card that lands at ~2.6–3.5:1 — under AA for
     11–13px type, and these chips (FAIL / FALSIFIED / PASS / ACCRUING) ARE the
     page's content. Mixing the hue toward --text deepens it on light and
     lightens it on dark with one declaration per hue; the chip FILLS keep the
     pure hue, so the colour language is unchanged. */
  --ok-ink:     color-mix(in srgb, var(--ok)   66%, var(--text));
  --act-ink:    color-mix(in srgb, var(--act)  66%, var(--text));
  --warn-ink:   color-mix(in srgb, var(--warn) 66%, var(--text));
  --blue-ink:   color-mix(in srgb, var(--blue) 66%, var(--text));
  --accent-deep:color-mix(in srgb, var(--blue) 68%, #0a1930);
}
.mh-wrap{max-width:1100px;margin:0 auto;padding:0 16px 80px}

/* ── Hero — the calibration loop ─────────────────────────────────────────── */
.mh-hero{padding:44px 0 32px;border-bottom:1px solid var(--border);margin-bottom:34px}
.mh-kicker{font-size:.7rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
  color:var(--muted);margin-bottom:12px}
.mh-kicker .hb{display:inline-block;width:7px;height:7px;border-radius:50%;
  background:var(--blue);margin-right:7px;vertical-align:1px}
.mh-title{font-size:clamp(1.6rem,4.4vw,2.35rem);font-weight:800;line-height:1.12;
  letter-spacing:-.02em;margin:0 0 10px;color:var(--text)}
.mh-deck{font-size:1.02rem;line-height:1.5;color:var(--muted);
  max-width:52ch;margin:0 0 28px}

/* The signature: three beats of the nightly loop, joined into one instrument,
   with a return rail that closes it. Ordinals are earned here — this really is
   a sequence, and the rail is what makes it a loop rather than a funnel. */
.mh-loop{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr)}
.mh-loop-step{min-width:0;padding:15px 18px 17px;border:1px solid var(--border);
  background:color-mix(in srgb,var(--text) 3%,transparent)}
.mh-loop-step + .mh-loop-step{border-left:none}
.mh-loop-step:first-child{border-radius:10px 0 0 0}
.mh-loop-step:last-child{border-radius:0 10px 0 0}
.mh-loop-hd{display:flex;align-items:baseline;gap:9px}
.mh-loop-n{font-family:var(--font-mono);font-size:.72rem;font-weight:700;
  color:var(--blue-ink);letter-spacing:.06em}
.mh-loop-name{font-size:.72rem;font-weight:800;letter-spacing:.16em;
  text-transform:uppercase;color:var(--text)}
.mh-loop-line{display:block;margin-top:9px;font-size:.82rem;line-height:1.5;color:var(--muted)}
.mh-loop-stat{display:block;margin-top:11px;font-size:.72rem;line-height:1.4;color:var(--muted)}
.mh-loop-num{font-family:var(--font-mono);font-size:.94rem;font-weight:700;
  color:var(--text);letter-spacing:-.01em;margin-right:4px}
.mh-loop-rail{position:relative;height:15px;border:1px solid var(--border);border-top:none;
  border-radius:0 0 10px 10px;margin:0 0 26px}
.mh-loop-return{position:absolute;left:50%;bottom:-1px;transform:translate(-50%,50%);
  background:var(--bg);padding:0 12px;white-space:nowrap;
  font-size:.65rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;
  color:var(--muted)}
.mh-loop-return .rr{color:var(--blue-ink);margin-right:5px;font-size:.8rem;line-height:1}

/* Forward record — one honest count, same register as the loop stats above.
   Mono is on the FIGURES only; the words stay in the body face. */
.mh-fwd{margin:0 0 22px;font-size:.72rem;line-height:1.5;color:var(--muted)}
.mh-fwd-num{font-family:var(--font-mono);font-size:.94rem;font-weight:700;
  color:var(--text);letter-spacing:-.01em;margin-right:4px}
.mh-fwd-sep{margin:0 7px;opacity:.45}

/* Where it stands — the one stance line. Calm left rule, not an alarm box. */
.mh-stand{font-size:.9rem;line-height:1.65;color:var(--muted);max-width:78ch;
  margin:0;padding-left:15px;border:1px solid var(--line);}
.mh-stand strong{color:var(--text);font-weight:700}
.mh-stand a{color:var(--ink-link, var(--link,var(--blue)))}

/* Tier-3 standing note (section-level, below the fold) */
.mh-note{border:1px solid var(--border);border-radius:10px;padding:14px 18px;margin:0 0 20px;
  background:color-mix(in srgb,var(--text) 3%,transparent);
  font-size:.83rem;line-height:1.6;color:var(--muted)}
.mh-note strong{color:var(--text)}

/* ── Section headings ────────────────────────────────────────────────────── */
.mh-section{margin-bottom:48px}
.mh-sh{display:flex;align-items:baseline;gap:12px;margin:0 0 16px}
.mh-sh h2{font-size:1.15rem;font-weight:700;margin:0;color:var(--text,#e2e8f0)}
.mh-sh .mh-sh-sub{font-size:.78rem;color:var(--muted,#8899aa)}

/* ── Engine tabs ─────────────────────────────────────────────────────────── */
.mh-tabs{display:flex;gap:4px;margin-bottom:20px;flex-wrap:wrap}
.mh-tab{padding:7px 14px;border-radius:7px;border:1px solid var(--border,rgba(255,255,255,.1));
  background:transparent;color:var(--muted,#8899aa);font-size:.82rem;cursor:pointer;
  transition:all .15s}
/* Selected tab: the raw accent takes white text to only 2.8:1 in dark mode, so
   the fill is deepened toward ink. ~5:1 dark, ~7.7:1 light. */
.mh-tab.on{background:var(--accent-deep);border-color:var(--accent-deep);
  color:#fff;font-weight:600}

/* ── Engine panel ────────────────────────────────────────────────────────── */
.mh-engine{display:none}
.mh-engine.on{display:block}
.mh-eng-hd{display:flex;align-items:center;gap:12px;margin-bottom:20px}
.mh-eng-name{font-size:1rem;font-weight:700;color:var(--text,#e2e8f0)}
.mh-eng-epoch{font-size:.72rem;color:var(--muted,#8899aa);
  background:color-mix(in srgb,var(--text) 8%,transparent);
  padding:3px 8px;border-radius:4px;font-family:var(--font-mono)}

/* ── Cohort badges ───────────────────────────────────────────────────────── */
.mh-cohorts{display:grid;grid-template-columns:repeat(auto-fit,minmax(480px,1fr));gap:20px}
.mh-cohort{border:1px solid var(--border,rgba(255,255,255,.08));border-radius:10px;
  padding:20px;background:var(--card,rgba(255,255,255,.03))}
.mh-cohort-hd{display:flex;align-items:center;gap:10px;margin-bottom:16px}
.mh-cohort-badge{font-size:.7rem;font-weight:700;letter-spacing:.1em;
  padding:3px 8px;border-radius:4px}
.badge-backtest{background:color-mix(in srgb,var(--blue,#3b82f6) 20%,transparent);
  color:var(--blue-ink);border:1px solid color-mix(in srgb,var(--blue) 35%,transparent)}
.badge-live{background:color-mix(in srgb,var(--ok,#3da564) 20%,transparent);
  color:var(--ok-ink);border:1px solid color-mix(in srgb,var(--ok) 35%,transparent)}
.mh-cohort-meta{font-size:.75rem;color:var(--muted,#8899aa)}

/* ── Primitive blocks ────────────────────────────────────────────────────── */
.mh-primitive{margin-bottom:18px;padding:14px;border-radius:8px;
  background:color-mix(in srgb,var(--text) 4%,transparent)}
.mh-prim-title{font-size:.78rem;font-weight:700;color:var(--text,#e2e8f0);
  margin-bottom:10px;display:flex;align-items:center;gap:8px}
.mh-prim-gate{font-size:.68rem;font-family:var(--font-mono);padding:2px 6px;border-radius:3px;
  background:color-mix(in srgb,var(--muted) 15%,transparent);color:var(--muted,#8899aa)}

/* ── Verdict badges ──────────────────────────────────────────────────────── */
.verdict{display:inline-flex;align-items:center;gap:5px;font-size:.72rem;font-weight:700;
  padding:3px 8px;border-radius:4px;letter-spacing:.05em}
.verdict::before{content:"";display:inline-block;width:6px;height:6px;border-radius:50%}
.verdict-fail{background:color-mix(in srgb,var(--act,#e05555) 18%,transparent);
  color:var(--act-ink);border:1px solid color-mix(in srgb,var(--act) 35%,transparent)}
.verdict-fail::before{background:var(--act,#e05555)}
.verdict-miscal{background:color-mix(in srgb,var(--warn,#f59e0b) 18%,transparent);
  color:var(--warn-ink);border:1px solid color-mix(in srgb,var(--warn) 35%,transparent)}
.verdict-miscal::before{background:var(--warn,#f59e0b)}
.verdict-pass{background:color-mix(in srgb,var(--ok,#3da564) 18%,transparent);
  color:var(--ok-ink);border:1px solid color-mix(in srgb,var(--ok) 35%,transparent)}
.verdict-pass::before{background:var(--ok,#3da564)}
.verdict-accruing{background:color-mix(in srgb,var(--blue,#3b82f6) 18%,transparent);
  color:var(--blue-ink);border:1px solid color-mix(in srgb,var(--blue) 35%,transparent)}
.verdict-accruing::before{background:var(--blue,#3b82f6)}
.verdict-none{background:color-mix(in srgb,var(--muted) 18%,transparent);
  color:var(--muted,#8899aa);border:1px solid color-mix(in srgb,var(--muted) 25%,transparent)}
.verdict-none::before{background:var(--muted,#8899aa)}

/* ── Metric rows ─────────────────────────────────────────────────────────── */
.mh-metric-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px}
.mh-metric{padding:10px 12px;border-radius:6px;
  background:color-mix(in srgb,var(--text) 3%,transparent);
  border:1px solid var(--border,rgba(255,255,255,.06))}
.mh-metric-label{font-size:.68rem;color:var(--muted,#8899aa);margin-bottom:4px}
.mh-metric-val{font-size:.95rem;font-weight:700;color:var(--text,#e2e8f0)}
.mh-metric-ci{font-size:.68rem;color:var(--muted,#8899aa)}
.mh-metric-note{font-size:.68rem;color:var(--muted,#8899aa);margin-top:4px;line-height:1.4}

/* ── Gate ledger table ───────────────────────────────────────────────────── */
.mh-gate-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
.mh-gate-table{width:100%;min-width:560px;border-collapse:collapse;font-size:.8rem}
.mh-gate-table th{text-align:left;padding:8px 12px;font-size:.72rem;font-weight:700;
  color:var(--muted,#8899aa);border-bottom:1px solid var(--border,rgba(255,255,255,.08));
  text-transform:uppercase;letter-spacing:.08em}
.mh-gate-table td{padding:9px 12px;border-bottom:1px solid var(--border,rgba(255,255,255,.04));
  color:var(--text,#e2e8f0);vertical-align:top;line-height:1.45}
.mh-gate-table tr:last-child td{border-bottom:none}
.mh-gate-table .gate-id{font-family:var(--font-mono);font-size:.75rem;font-weight:700;
  white-space:nowrap;color:var(--text,#e2e8f0)}
.mh-gate-table .gate-result{font-size:.75rem;color:var(--muted,#8899aa);
  max-width:340px;line-height:1.4}
.mh-gate-fam{font-size:.68rem;font-family:var(--font-mono);
  padding:2px 6px;border-radius:3px;
  background:color-mix(in srgb,var(--text) 8%,transparent);
  color:var(--muted,#8899aa)}
.mh-gate-sec{padding:12px 0 6px;font-size:.72rem;font-weight:700;letter-spacing:.1em;
  color:var(--muted,#8899aa);text-transform:uppercase;border-top:1px solid var(--border,rgba(255,255,255,.06));
  margin-top:8px;grid-column:1/-1}

/* ── Collinearity panel ──────────────────────────────────────────────────── */
.mh-collin{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:12px}
@media(max-width:640px){.mh-collin{grid-template-columns:1fr}}
.mh-collin-block{padding:14px;border-radius:8px;
  background:color-mix(in srgb,var(--text) 4%,transparent);
  border:1px solid var(--border,rgba(255,255,255,.06))}
.mh-collin-block h4{font-size:.8rem;font-weight:700;margin:0 0 8px;
  color:var(--text,#e2e8f0)}
.mh-collin-block ul{margin:0;padding-left:18px;font-size:.8rem;
  color:var(--muted,#8899aa);line-height:1.7}
.mh-collin-block li{margin-bottom:2px}
.mh-collin-block li strong{color:var(--text,#e2e8f0)}

/* ── Accruing experiments table ──────────────────────────────────────────── */
.mh-exp-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
.mh-exp-table{width:100%;min-width:480px;border-collapse:collapse;font-size:.8rem}
.mh-exp-table th{text-align:left;padding:8px 12px;font-size:.72rem;font-weight:700;
  color:var(--muted,#8899aa);border-bottom:1px solid var(--border,rgba(255,255,255,.08));
  text-transform:uppercase;letter-spacing:.08em}
.mh-exp-table td{padding:9px 12px;border-bottom:1px solid var(--border,rgba(255,255,255,.04));
  color:var(--text,#e2e8f0);vertical-align:top}
.mh-exp-table tr:last-child td{border-bottom:none}
.mh-exp-name{font-weight:600;font-size:.82rem;color:var(--text,#e2e8f0)}
.mh-exp-what{font-size:.75rem;color:var(--muted,#8899aa);margin-top:3px}
.mh-exp-cb{font-family:var(--font-mono);font-size:.75rem}

/* ── Sync gauge (W5.1 STOP-fallback) ─────────────────────────────────────── */
.sg-wrap{margin-bottom:48px}
.sg-stop-banner{background:color-mix(in srgb,var(--act,#e05555) 7%,var(--surface,#0f1629));
  border:1px solid color-mix(in srgb,var(--act,#e05555) 22%,transparent);
  border-radius:10px;padding:14px 18px;margin-bottom:20px;
  font-size:.85rem;line-height:1.6;color:var(--text,#e2e8f0)}
.sg-stop-banner strong{color:var(--act-ink)}
.sg-honest-note{background:color-mix(in srgb,var(--blue,#3b82f6) 6%,var(--surface,#0f1629));
  border:1px solid color-mix(in srgb,var(--blue,#3b82f6) 20%,transparent);
  border-radius:8px;padding:12px 16px;margin-bottom:20px;
  font-size:.8rem;line-height:1.55;color:var(--muted,#8899aa)}
.sg-honest-note strong{color:var(--blue-ink)}
.sg-families{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px;margin-bottom:20px}
.sg-family{padding:16px;border-radius:10px;
  border:1px solid var(--border,rgba(255,255,255,.08));
  background:var(--card,rgba(255,255,255,.03))}
.sg-fam-hd{display:flex;align-items:baseline;gap:8px;margin-bottom:12px}
.sg-fam-name{font-size:.88rem;font-weight:700;color:var(--text,#e2e8f0)}
.sg-fam-date{font-size:.72rem;color:var(--muted,#8899aa);font-family:var(--font-mono)}
.sg-sync-val{font-size:1.5rem;font-weight:800;margin:0 0 4px}
.sg-sync-bar{height:6px;border-radius:3px;
  background:color-mix(in srgb,var(--text) 10%,transparent);margin-bottom:10px;overflow:hidden}
.sg-sync-fill{height:100%;border-radius:3px;
  background:var(--blue,#3b82f6);transition:width .3s}
.sg-frac-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
.sg-frac-chip{font-size:.7rem;padding:2px 7px;border-radius:4px;
  background:color-mix(in srgb,var(--text) 8%,transparent);color:var(--muted,#8899aa)}
.sg-frac-chip strong{color:var(--text,#e2e8f0)}
.sg-hist-stats{margin-top:10px;font-size:.75rem;color:var(--muted,#8899aa);
  display:flex;gap:16px;flex-wrap:wrap}
.sg-sparkline{margin-top:12px;width:100%;height:52px}
.sg-gate-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px;margin-top:16px}
.sg-gate-cell{padding:10px 12px;border-radius:6px;
  background:color-mix(in srgb,var(--text) 3%,transparent);
  border:1px solid var(--border,rgba(255,255,255,.06))}
.sg-gate-lbl{font-size:.68rem;color:var(--muted,#8899aa);margin-bottom:3px}
.sg-gate-val{font-size:.88rem;font-weight:700;color:var(--text,#e2e8f0)}
@media(max-width:600px){
  .sg-families{grid-template-columns:1fr}
}

/* ── Evidence-Gap panel (PR-A1) ─────────────────────────────────────────── */
.eg-subpanel{margin-bottom:36px;padding:20px;border-radius:10px;
  border:1px solid var(--border,rgba(255,255,255,.08));
  background:var(--card,rgba(255,255,255,.03))}
.eg-subhd{display:flex;align-items:baseline;gap:12px;margin-bottom:10px;flex-wrap:wrap}
.eg-subhd h3{font-size:.98rem;font-weight:700;margin:0;color:var(--text,#e2e8f0)}
.eg-subhd-meta{font-size:.75rem;color:var(--muted,#8899aa)}
