/* ── Hub v2: Null Library ───────────────────────────────────────────────── */
/* Multi-column, not grid: these cards run from 6 lines to 40, so a row-based
   grid either stretched the short ones into 200px of framed dead space or left
   the same hole unframed. Column flow packs them; `columns` also has no
   min-track, which is what was pushing the page into horizontal scroll at
   390px. Reading order becomes column-major — fine for an id-sorted reference
   library. */
.nl-wrap{columns:340px 3;column-gap:16px;margin-top:8px}
.nl-card{break-inside:avoid;-webkit-column-break-inside:avoid;page-break-inside:avoid;
  margin:0 0 16px;
  border:1px solid color-mix(in srgb,var(--muted,#8899aa) 20%,transparent);
  border-radius:10px;padding:16px;min-width:0;
  background:color-mix(in srgb,var(--muted,#8899aa) 5%,transparent)}
/* Header is a two-slot row, not a nowrap line: the id wraps in its own column
   and the badge keeps reserved space. Before this it overflowed the card and
   the neighbouring card's id rendered straight through the badge. */
.nl-card-hd{display:flex;align-items:flex-start;justify-content:space-between;
  gap:6px 10px;margin-bottom:10px;flex-wrap:wrap}
.nl-card-id{flex:1 1 14ch;min-width:0;font-family:var(--font-mono);font-size:.75rem;
  font-weight:700;color:var(--muted,#8899aa);line-height:1.35}
.nl-ruled-badge{flex:0 0 auto;white-space:nowrap;
  font-size:.68rem;font-weight:700;letter-spacing:.05em;padding:2px 7px;
  border-radius:4px;
  background:color-mix(in srgb,var(--muted,#8899aa) 12%,transparent);
  color:var(--muted,#8899aa);
  border:1px solid color-mix(in srgb,var(--muted) 25%,transparent)}
