  .nav-dd-menu:not(.nav-mega):not(.nav-market-menu) > .nav-sub > a .submenu-icon {
    grid-column: 1;
    grid-row: 1 / 3;
  }

  .nav-dd-menu:not(.nav-mega):not(.nav-market-menu) > a > .l-en,
  .nav-dd-menu:not(.nav-mega):not(.nav-market-menu) > a > .l-zh {
