/* Keep right-edge standard menus inside compact desktop viewports. China is
   right-aligned so its own nested research flyouts have room; International
   and Other Assets are the final standard menus before Research. The asset
   flyouts then open inward instead of pushing another 420px panel off-screen.
   Structural positions remain stable when profile-selected markets are hidden. */
@media (min-width: 701px) {
  .site-nav .nav-links > .nav-dd:nth-last-of-type(6) > .nav-dd-menu:not(.nav-mega):not(.nav-market-menu),
  .topbar .nav-links > .nav-dd:nth-last-of-type(6) > .nav-dd-menu:not(.nav-mega):not(.nav-market-menu),
  .site-nav .nav-links > .nav-dd:nth-last-of-type(-n + 3) > .nav-dd-menu:not(.nav-mega):not(.nav-market-menu),
  .topbar .nav-links > .nav-dd:nth-last-of-type(-n + 3) > .nav-dd-menu:not(.nav-mega):not(.nav-market-menu) {
    left: auto;
    right: 0;
  }

  .site-nav .nav-links > .nav-dd:nth-last-of-type(2) .nav-sub > .nav-dd-menu,
  .topbar .nav-links > .nav-dd:nth-last-of-type(2) .nav-sub > .nav-dd-menu {
    left: auto;
    right: 100%;
  }

  .site-nav .nav-links > .nav-dd:nth-last-of-type(2) .nav-sub::after,
  .topbar .nav-links > .nav-dd:nth-last-of-type(2) .nav-sub::after {
    left: auto;
    right: 100%;
  }
}

/* Research overview */
@media (min-width: 701px) {
  .site-nav .nav-links,
  .topbar .nav-links { position: relative; }

  .site-nav .nav-mega-dd,
  .topbar .nav-mega-dd { position: static; }

  .site-nav .nav-mega-dd::after,
  .topbar .nav-mega-dd::after { content: none; }

  .site-nav .nav-dd-menu.nav-mega,
  .topbar .nav-dd-menu.nav-mega {
    left: auto;
    right: 0;
    width: min(1120px, calc(100vw - 40px));
    min-width: 0;
    padding: 23px;
    overflow: hidden;
    border-radius: 22px;
    border-color: var(--nr-line-strong);
    background: var(--nr-surface);
    box-shadow: var(--nr-shadow);
    /* An open mega must outrank the header it drops out of. It inherited
       z-index:90 from `.site-nav .nav-dd-menu` (theme.css), which loses to
       `.nav-search`{z-index:110} — so the search box painted THROUGH the panel,
       and on close, as the panel faded, it read as the menu dropping behind the
       header. 150 clears the header chrome and still sits under the dialogs
       (.mx5-dlg 200, and the modal layers above it), which must cover the nav. */
    z-index: 150;
    /* --nr-surface is 96-97% opaque, so the blur inherited from
       `.site-nav .nav-dd-menu` was contributing ~3% of the visual while forcing
       this panel to re-composite against its backdrop on every opacity frame.
       That is the switch-between-menus flicker: two backdrop-filtered panels
       cross-fading sample each other, which washes out the 1px --nr-line-strong
       edge and greys the surface until the transition settles. Dropping it costs
       ~3% of an effect and removes the artifact. Small (non-mega) dropdowns keep
       their blur -- at 86-90% opacity it actually reads there. */
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .nav-dd-menu.nav-mega::before {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    top: -12px;
    height: 14px;
  }
}

