/* ==========================================================================
   Responsive navigation composition

   The rail is built once. JavaScript measures the links that remain after the
   user's market profile has folded unused countries into International, then
   writes data-nav-layout="single" or "stacked". No market-specific menu forks
   and no duplicated navigation inventories are required.
   ========================================================================== */
@media (min-width: 901px) {
  .site-nav[data-nav-layout],
  .topbar[data-nav-layout] .wrap {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 124px auto;
    align-items: center;
    gap: 8px 10px;
  }

  .site-nav[data-nav-layout="single"] .nav-links,
  .topbar[data-nav-layout="single"] .nav-links {
    grid-column: 1;
    grid-row: 1;
    min-width: 0;
    display: flex;
    flex-wrap: nowrap;
  }

  .site-nav[data-nav-layout="single"] .nav-search,
  .topbar[data-nav-layout="single"] .nav-search {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
  }

  .site-nav[data-nav-layout="single"] .nav-ctrls,
  .topbar[data-nav-layout="single"] .nav-ctrls {
    grid-column: 3;
    grid-row: 1;
  }

  .site-nav[data-nav-layout="stacked"] .nav-links,
  .topbar[data-nav-layout="stacked"] .nav-links {
    grid-column: 1 / -1;
    grid-row: 1;
    display: flex;
    flex-wrap: nowrap;
  }

  .site-nav[data-nav-layout="stacked"] .nav-search,
  .topbar[data-nav-layout="stacked"] .nav-search {
    grid-column: 2;
    grid-row: 2;
    justify-self: end;
  }

  .site-nav[data-nav-layout="stacked"] .nav-ctrls,
  .topbar[data-nav-layout="stacked"] .nav-ctrls {
    grid-column: 3;
    grid-row: 2;
  }

  .site-nav[data-nav-layout] .nav-links,
  .topbar[data-nav-layout] .nav-links {
    position: static;
    gap: 2px;
  }

  .site-nav[data-nav-layout] a.nav-link,
  .topbar[data-nav-layout] a.nav-link {
    min-height: 40px;
    display: inline-flex;
    align-items: center;
    padding: 0 9px;
    border-radius: 9px;
  }

  .site-nav[data-nav-layout] .nav-dd-menu.nav-mega,
  .topbar[data-nav-layout] .nav-dd-menu.nav-mega {
    right: 0;
  }
}

