/* `visibility:hidden` panels still contribute their absolutely positioned
   descendants to document scroll width. These rules intentionally live last
   so the desktop closed state wins over the mega menu's grid declaration.
   Mobile keeps its JS-driven accordion at <=900px. */
@media (min-width: 901px) {
  .site-nav .nav-dd > .nav-dd-menu,
  .topbar .nav-dd > .nav-dd-menu {
    display: none;
  }

  .site-nav .nav-dd:hover > .nav-dd-menu,
  .site-nav .nav-dd:focus-within > .nav-dd-menu,
  .topbar .nav-dd:hover > .nav-dd-menu,
  .topbar .nav-dd:focus-within > .nav-dd-menu {
    display: block;
  }

  .site-nav .nav-dd:hover > .nav-dd-menu.nav-mega,
  .site-nav .nav-dd:focus-within > .nav-dd-menu.nav-mega,
  .topbar .nav-dd:hover > .nav-dd-menu.nav-mega,
  .topbar .nav-dd:focus-within > .nav-dd-menu.nav-mega {
    display: grid;
  }

  .site-nav .nav-dd:hover > .nav-dd-menu.nav-market-menu,
  .site-nav .nav-dd:focus-within > .nav-dd-menu.nav-market-menu,
  .topbar .nav-dd:hover > .nav-dd-menu.nav-market-menu,
  .topbar .nav-dd:focus-within > .nav-dd-menu.nav-market-menu {
    display: grid;
  }

  /* The wide menus are anchored to the whole nav instead of their trigger, so
     their deliberately visible gap is not part of the trigger's hover box.
     nav_market.js supplies a short hover-intent grace period while the pointer
     crosses that gap; these rules keep the panel rendered during the crossing
     without changing a single pixel of the approved menu geometry. */
  .site-nav .nav-dd.nav-hover-open > .nav-dd-menu,
  .topbar .nav-dd.nav-hover-open > .nav-dd-menu {
    display: block;
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  .site-nav .nav-dd.nav-hover-open > .nav-dd-menu.nav-mega,
  .site-nav .nav-dd.nav-hover-open > .nav-dd-menu.nav-market-menu,
  .topbar .nav-dd.nav-hover-open > .nav-dd-menu.nav-mega,
  .topbar .nav-dd.nav-hover-open > .nav-dd-menu.nav-market-menu {
    display: grid;
  }

  .site-nav .nav-dd.nav-hover-open > a.nav-link .caret,
  .topbar .nav-dd.nav-hover-open > a.nav-link .caret {
    transform: rotate(180deg);
  }

  /* A folded country drill is opened by CLICK, so `.is-open` is its state —
     but the blanket `.nav-dd > .nav-dd-menu { display:none }` above only ever
     lifted for `:hover`/`:focus-within`. The open panel therefore survived
     purely because the pointer happened to still be on the trigger it had just
     clicked, and vanished the moment it drifted. State, not hover, decides. */
  .site-nav .nav-dd .nav-market-drill.is-open > .nav-dd-menu,
  .topbar .nav-dd .nav-market-drill.is-open > .nav-dd-menu {
    display: block;
  }
}

/* In the content-aware two-row state, an icon-only brand recovers enough room
   for every opted-in market at compact desktop/iPad widths. One- and two-market
   profiles stay in the single-row state and retain the full wordmark. */
@media (min-width: 901px) and (max-width: 1100px) {
  .site-nav[data-nav-layout="stacked"] .nav-brand .brand-word,
  .topbar[data-nav-layout="stacked"] .nav-brand .brand-word {
    display: none;
  }

  .site-nav[data-nav-layout="stacked"] .nav-links,
  .topbar[data-nav-layout="stacked"] .nav-links {
    gap: 1px;
  }

  .site-nav[data-nav-layout="stacked"] a.nav-link,
  .topbar[data-nav-layout="stacked"] a.nav-link {
    padding-inline: 8px;
  }
}

