/* =========================================================================
   PANEL CHOREOGRAPHY — hover bridge · quick open/close · morphing cross-fade
   -------------------------------------------------------------------------
   THE DEFECT. Traversing the trigger row (United States → China → Hong Kong)
   removed the outgoing panel in the SAME frame the incoming one started at
   opacity 0, then played a 340ms fade-up. Frame log of the shipped build at
   1440px, pointer leaving United States at t=600ms:

       600ms  United States[op 1.00 h780]
       625ms  China[op 0.00 h780]        <- United States already display:none
       ...    China ramps 0.00 -> 1.00 over the next 340ms

   One fully blank frame, then a slow re-entrance. That is the flicker.

   THE FIX. Measured on the shipped rail: every wide panel lands on the SAME
   rect — x 148, y 101, width 1276 at 1440px — and differs only in HEIGHT
   (780px United States/China · 690px Hong Kong/Canada/International ·
   693-694px Research/Other Assets). Width is invariant at every breakpoint,
   so a switch needs no shared wrapper element: pinning the outgoing AND the
   incoming panel to one animated height makes their chromes pixel-identical
   for the crossing. The pair then reads as a SINGLE PLATE that morphs, while
   only the contents cross-fade — the surface never blinks. The incoming panel
   suppresses its own chrome for the crossing and rides on top of the
   outgoing plate, so the two opaque backgrounds never composite.

   Everything here is desktop-only and JS-cooperative: nav_market.js owns the
   classes and the measured custom properties. With scripting off, the CSS
   `:hover` path below still opens every menu — it just swaps hard, exactly as
   it did before.
   ========================================================================= */
.site-nav,
.topbar {
  --nav-open: 150ms;    /* entrance */
  --nav-close: 110ms;   /* exit — deliberately quicker than the entrance */
  --nav-swap: 100ms;    /* contents cross-fade on a trigger-to-trigger switch */
  --nav-morph: 170ms;   /* plate height; outlasts the swap so the chrome is
                           still settling as the new contents land, which is
                           what reads as a morph rather than a resize */
  --nav-ease: cubic-bezier(.22, .78, .2, 1);
  --nav-drift: 10px;    /* content travel; nav_market.js signs it by direction */
  --nav-bridge: 0px;    /* trigger-to-panel air gap, measured by nav_market.js */
}

@media (min-width: 901px) {
  /* ---- (a) the invisible hover bridge ---------------------------------
     Two dead bands sat between a trigger and everything it should reach: the
     2px flex gutter between adjacent triggers, and the 16px of air below the
     row. Crossing either fired pointerleave on the .nav-dd. The wide menus
     cannot use theme.css's `.nav-dd::after` bridge because .nav-market-dd and
     .nav-mega-dd are position:static (their panels anchor to the whole rail),
     so the zone moves to the trigger link, which is positioned here for it.
     Horizontal reach is unconditional; vertical depth comes from the real
     measured gap so it can never overhang a control in a stacked layout. */
  .site-nav .nav-links > .nav-dd > a.nav-link,
  .topbar .nav-links > .nav-dd > a.nav-link { position: relative; }

  .site-nav .nav-links > .nav-dd > a.nav-link::after,
  .topbar .nav-links > .nav-dd > a.nav-link::after {
    content: "";
    position: absolute;
    top: 0;
    left: -3px;
    right: -3px;
    bottom: calc(0px - var(--nav-bridge, 0px));
  }

  /* ---- (b) the exit ---------------------------------------------------
     display:none cannot transition, so nav_market.js holds the panel rendered
     for exactly --nav-close while this class runs the fade. */
  .site-nav .nav-dd-menu.mega-menu.nav-panel-closing,
  .topbar .nav-dd-menu.mega-menu.nav-panel-closing {
    display: grid;
    opacity: 1;
    /* nav-hover-open is already off by the time this runs, so the base
       .nav-dd-menu visibility:hidden would otherwise erase the panel before it
       could fade. */
    visibility: visible;
    transform: translateY(0);
    pointer-events: none;
    animation: none;
    transition: opacity var(--nav-close) ease-out, transform var(--nav-close) ease-out;
  }

  .site-nav .nav-dd-menu.mega-menu.nav-panel-closing.nav-panel-live,
  .topbar .nav-dd-menu.mega-menu.nav-panel-closing.nav-panel-live {
    opacity: 0;
    transform: translateY(-4px);
  }

  /* ---- (c) the switch: one plate, morphing --------------------------- */
  .site-nav .nav-dd-menu.mega-menu.nav-panel-out,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-in,
  .topbar .nav-dd-menu.mega-menu.nav-panel-out,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in {
    display: grid;
    height: var(--nav-plate-h, auto);
    min-height: 0;
    opacity: 1;
    transform: none;
    transition: height var(--nav-morph) var(--nav-ease);
  }

  /* A panel that arrived through a swap must never replay the cold entrance —
     re-enabling the keyframe when the swap classes come off would restart the
     fade from zero and reintroduce the very flash this section removes.
     The selector deliberately carries the full open-state shape plus the swap
     class: a running animation outranks every normal declaration in the
     cascade, so this has to out-specify the entrance rule (0,5,0) rather than
     merely follow it. Measured before this was tightened: both panels rode the
     entrance curve together, 0.32 -> 0.68 -> 0.86 opacity. */
  .site-nav .nav-dd.nav-hover-open > .nav-dd-menu.mega-menu.nav-panel-swapped,
  .topbar .nav-dd.nav-hover-open > .nav-dd-menu.mega-menu.nav-panel-swapped {
    animation: none;
    opacity: 1;
    transform: none;
  }

  /* The incoming panel rides on top of the outgoing plate with its own chrome
     suppressed, so the crossing shows one border, one shadow, one background.
     Doubled class matches the house `.nav-mega.nav-mega` idiom for winning
     against the themed .mega-menu surface rules without !important. */
  .site-nav .nav-dd-menu.mega-menu.nav-panel-in.nav-panel-in,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in.nav-panel-in {
    /* one above the nav layer (theme.css HEADER LAYER LAW, 150) so the incoming
       panel rides over the outgoing one. Tracks the base rule — it was 91 when
       the base was 90; leaving it at 91 would have sunk every cross-fading
       panel back under page content for the length of the swap. */
    z-index: 151;
    background: transparent;
    border-color: transparent;
    box-shadow: none;
  }

  /* Contents cross-fade with a drift that follows the pointer: travelling
     right along the row sends both the outgoing and the incoming contents
     leftward, so the swap has a direction instead of a blink. */
  .site-nav .nav-dd-menu.mega-menu.nav-panel-in > *,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-out > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-out > * {
    transition: opacity var(--nav-swap) ease, transform var(--nav-swap) ease;
  }

  .site-nav .nav-dd-menu.mega-menu.nav-panel-in > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in > * {
    opacity: 0;
    transform: translateX(var(--nav-drift));
  }

  .site-nav .nav-dd-menu.mega-menu.nav-panel-in.nav-panel-live > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in.nav-panel-live > * {
    opacity: 1;
    transform: translateX(0);
  }

  .site-nav .nav-dd-menu.mega-menu.nav-panel-out.nav-panel-live > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-out.nav-panel-live > * {
    opacity: 0;
    transform: translateX(calc(var(--nav-drift) * -1));
  }
}

/* Reduced motion: every animation and transition this section introduces is
   killed BY NAME, pseudo-elements included, and the swap becomes an instant
   cut (nav_market.js also skips the choreography outright, so this is the
   belt to that braces). The generic block above only reaches descendants and
   only softens to .01ms; these rules zero the panel element itself. */
@media (prefers-reduced-motion: reduce) {
  .site-nav .nav-dd.nav-hover-open > .nav-dd-menu.mega-menu,
  .topbar .nav-dd.nav-hover-open > .nav-dd-menu.mega-menu,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-in,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-out,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-closing,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in,
  .topbar .nav-dd-menu.mega-menu.nav-panel-out,
  .topbar .nav-dd-menu.mega-menu.nav-panel-closing,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-in > *,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-out > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-out > *,
  .site-nav .nav-dd-menu.mega-menu::before,
  .site-nav .nav-dd-menu.mega-menu::after,
  .topbar .nav-dd-menu.mega-menu::before,
  .topbar .nav-dd-menu.mega-menu::after,
  .site-nav .nav-links > .nav-dd > a.nav-link::after,
  .topbar .nav-links > .nav-dd > a.nav-link::after {
    animation: none !important;
    transition: none !important;
    transition-duration: 0s !important;
    animation-duration: 0s !important;
  }

  .site-nav .nav-dd-menu.mega-menu.nav-panel-in > *,
  .site-nav .nav-dd-menu.mega-menu.nav-panel-out > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-in > *,
  .topbar .nav-dd-menu.mega-menu.nav-panel-out > * {
    opacity: 1 !important;
    transform: none !important;
  }
}

/* Folded country menus are state-owned drills. These selectors intentionally
   come after every generic mega-menu hover rule: moving a formerly top-level
   market under International must not let :hover, :focus-within, or a stale
   nav-hover-open class reveal its panel. Only the click handler's .is-open
   state may do that. */
.site-nav .nav-links .nav-market-rail > .nav-market-drill:not(.is-open) > .nav-market-drill-panel,
.topbar .nav-links .nav-market-rail > .nav-market-drill:not(.is-open) > .nav-market-drill-panel {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(32px);
  animation: none !important;
}

.site-nav .nav-links .nav-market-rail > .nav-market-drill.is-open > .nav-market-drill-panel,
.topbar .nav-links .nav-market-rail > .nav-market-drill.is-open > .nav-market-drill-panel {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(0);
}

/* ---------------------------------------------------------------------------
   Folded country drills on MOBILE — the sheet.
   ---------------------------------------------------------------------------
   A country folded into International (nav_market.js toSubmenu) becomes a
   drill: theme.js initNavDrills toggles `.is-open`. But the mobile nav is an
   accordion keyed on `.open`, and theme.js injects NAV_MOBILE_CSS into <head>
   AFTER this stylesheet loads — so its
     `.has-nav-toggle .nav-links .nav-dd-menu { max-height:0; position:static }`
   won every equal-specificity contest above and pinned the drill panel to zero
   height. Tapping "United States" inside International therefore did nothing
   visible: the reader stayed on the International menu with no signal that a
   market had been chosen (operator report, 2026-08-04).

   The fix is the same idiom desktop already uses — the country's own panel
   REPLACES the plate — expressed as a full-screen sheet, which is what a
   phone can actually show. Every selector here carries ≥4 classes so it beats
   the runtime-injected accordion rules without !important.
   ------------------------------------------------------------------------ */
@media (max-width: 900px) {
  /* backdrop-filter (theme.css gives every .nav-dd-menu the glass blur) makes an
     element the containing block for position:fixed DESCENDANTS. Inside the
     collapsed mobile menu the host panel is 0-tall, so the sheet below resolved
     inset:0 against a zero box and measured 0×0 — rendered, focusable, invisible.
     The blur buys nothing here anyway: theme.js already forces these panels to
     background:transparent inside an opaque .nav-links card. Drop it. */
  .has-nav-toggle .nav-links .nav-dd-menu,
  .has-nav-toggle .nav-links .nav-dd:hover > .nav-dd-menu,
  .has-nav-toggle .nav-links .nav-dd:focus-within > .nav-dd-menu {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    /* theme.css's `.site-nav .nav-dd:hover > .nav-dd-menu { transform:
       translateY(0) }` is (0,3,1) and out-ranked theme.js's mobile
       `transform:none` at (0,3,0). An IDENTITY transform still makes the
       element a containing block, and a tap leaves :hover latched on mobile
       browsers — so the panel silently became the fixed sheet's viewport.
       These selectors are (0,4,0) and settle it for the whole mobile nav. */
    transform: none;
  }

  /* Closed: fully out of the flow. Zero height alone still let the panel's
     children contribute to the accordion's scroll width. */
  .has-nav-toggle .nav-links .nav-market-drill:not(.is-open) > .nav-dd-menu.nav-market-drill-panel {
    display: none;
  }

  .has-nav-toggle .nav-links .nav-market-drill.is-open > .nav-dd-menu.nav-market-drill-panel {
    position: fixed;
    inset: 0;
    z-index: 1200;
    display: block;
    box-sizing: border-box;
    width: auto;
    max-width: none;
    height: 100dvh;
    max-height: 100dvh;
    min-height: 0;
    margin: 0;
    padding: 14px 16px calc(30px + env(safe-area-inset-bottom));
    overflow-x: hidden;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    border: 0;
    border-radius: 0;
    background: var(--nr-surface-solid);
    box-shadow: none;
    opacity: 1;
    visibility: visible;
    transform: none;
    animation: nav-market-sheet-in .26s cubic-bezier(.22, 1, .36, 1) both;
  }

  /* The back control is the sheet's only exit, so it must never scroll away. */
  .has-nav-toggle .nav-links .nav-market-drill.is-open > .nav-market-drill-panel > .nav-drill-back {
    position: sticky;
    top: -14px;
    z-index: 3;
    width: 100%;
    min-height: 44px;
    margin: -14px 0 6px;
    padding: 12px 4px;
    justify-content: flex-start;
    color: var(--text, var(--ink));
    background: var(--nr-surface-solid);
    font-size: 13.5px;
  }

  /* The panel is the whole screen now, so drop the desktop plate's top inset
     that reserved room for an absolutely-positioned back button. */
  .has-nav-toggle .nav-links .nav-market-drill.is-open > .nav-market-drill-panel > .nav-market-main {
    padding-top: 0;
  }

  /* Sheets stack full-bleed: the rail's left border and inner gutters were
     drawn for a two-column plate. */
  .has-nav-toggle .nav-links .nav-market-drill.is-open > .nav-market-drill-panel > .nav-market-rail {
    margin-top: 4px;
    padding: 18px 0 0;
  }
}

/* Slide only. Fading the sheet in would tie its VISIBILITY to an animation
   completing, and an animation that never advances (suppressed compositor,
   background tab, a UA that ignores the keyframes) would leave a fully
   interactive full-screen panel at opacity 0. Motion is decoration here. */
@keyframes nav-market-sheet-in {
  from { transform: translateX(26px); }
  to   { transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .has-nav-toggle .nav-links .nav-market-drill.is-open > .nav-dd-menu.nav-market-drill-panel {
    animation: none;
  }
}

/* =========================================================================
   PREMIUM INTERACTION PARITY — keyboard + touch feedback
   -------------------------------------------------------------------------
   The menu links already inherit theme.css's global focus ring, but the newer
   button-based navigation controls do not. Keep mouse, keyboard and touch on
   one interaction grammar: visible keyboard focus, an immediate press state,
   and no undersized paginator/back targets. The selectors stay nav-local so
   page controls keep their own component contracts.
   ========================================================================= */
:where(
  .nav-drill-trigger,
  .nav-drill-back,
  .nav-ctrls .terminal-link,
  .ticker-search .search-trigger,
  .ticker-search .search-esc,
  .fan-card,
  .result-row,
  .search-pagination button
) {
  touch-action: manipulation;
}

:where(
  .nav-drill-trigger,
  .nav-drill-back,
  .nav-ctrls .terminal-link,
  .ticker-search .search-trigger,
  .ticker-search .search-esc,
  .fan-card,
  .result-row,
  .search-pagination button
):focus-visible {
  outline: 2px solid color-mix(in srgb, var(--link, #5b79ff) 70%, transparent);
  outline-offset: 2px;
  z-index: 4;
}

.nav-drill-back,
.ticker-search .search-esc,
.search-pagination button {
  transition:
    color .16s ease,
    background-color .16s ease,
    border-color .16s ease,
    box-shadow .16s ease,
    transform .16s ease;
}

.nav-drill-back {
  min-height: 40px;
}

.search-pagination button {
  min-width: 40px;
  height: 40px;
}

.nav-mega.nav-mega .nm-feat:active,
.nav-mega.nav-mega .nav-mega-item:active,
.nav-drill-trigger:active,
.nav-drill-back:active,
.ticker-search .search-trigger:active,
.fan-card:active,
.result-row:active {
  transform: translateY(0) scale(.985);
  transition-duration: .06s;
}

.ticker-search .search-esc:active,
.search-pagination button:active {
  border-color: color-mix(in srgb, var(--link, #5b79ff) 42%, var(--nr-line));
  color: var(--text, var(--ink));
  background: color-mix(in srgb, var(--link, #5b79ff) 9%, var(--nr-soft));
  box-shadow: inset 0 1px 2px color-mix(in srgb, var(--text, var(--ink)) 10%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  /* The approved mockup port lives after the older generic reduced-motion
     block, so repeat the component-level kill here at the true cascade tail. */
  .nav-search.ticker-search,
  .ticker-search .search-trigger,
  .ticker-search .search-expanded,
  .ticker-dropdown,
  .nav-drill-panel,
  .fan-card,
  .result-row,
  .nav-drill-back,
  .ticker-search .search-esc,
  .search-pagination button {
    animation: none !important;
    transition: none !important;
  }

  .fan-card,
  .result-row {
    opacity: 1;
    transform: none;
  }

  .ticker-search .idle-ticker::after {
    animation: none;
  }

  .nav-mega.nav-mega .nm-feat:active,
  .nav-mega.nav-mega .nav-mega-item:active,
  .nav-drill-trigger:active,
  .nav-drill-back:active,
  .ticker-search .search-trigger:active,
  .fan-card:active,
  .result-row:active {
    transform: none;
  }
}

/* ALL_TOOLS_MATERIAL_V1_START */
/* All-tools presentation for the existing product header. Adoption material:
   merge under navigation-refresh.css or register this paired static asset through
   the same serving/build owner. Never inject this sheet from JavaScript. */
[data-tools-open][hidden] { display: none !important; }
.mmx-tools-trigger {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 44px; padding: 0 14px; gap: 8px; border: 1px solid var(--nr-line-strong);
  border-radius: var(--r-btn,10px); background: var(--nr-soft); color: var(--text);
  font: 600 var(--fs-sm)/1.35 var(--font-ui); cursor: pointer; white-space: nowrap;
}
.mmx-tools-trigger[aria-expanded="true"] { border-color: var(--link); }
html.mmx-tools-open { overflow: hidden; scrollbar-gutter: stable; }
.mmx-tools {
  position: fixed; inset: 72px 0 auto; margin: 0 auto; padding: 0;
  width: min(1240px, calc(100% - 48px)); max-width: none;
  height: min(760px, calc(100vh - 96px)); height: min(760px, calc(100dvh - 96px));
  max-height: none; border: 1px solid var(--nr-line-strong); border-radius: var(--r-card,12px);
  background: var(--nr-surface-solid); color: var(--text);
  box-shadow: var(--nr-shadow); overflow: hidden;
  font: 400 var(--fs-body)/1.55 var(--font-ui); text-align: left;
}
.mmx-tools:not([open]) { display: none; }
.mmx-tools::backdrop { background: color-mix(in srgb, var(--bg) 78%, transparent); backdrop-filter: blur(4px); }
.mmx-tools *, .mmx-tools *::before, .mmx-tools *::after { box-sizing: border-box; }
.mmx-tools-shell { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.mmx-tools-header { display: grid; grid-template-columns: minmax(0,1fr) minmax(240px,360px) 44px; gap: 22px; padding: 26px 28px 20px; align-items: start; }
.mmx-tools-header h2 { margin: 0; font-size: var(--fs-h1); line-height: 1.18; letter-spacing: -.03em; font-weight: 650; }
.mmx-tools-header p { margin: 7px 0 0; color: var(--muted); font-size: var(--fs-body); }
.mmx-tools-search-label { display: block; color: var(--muted); font-size: var(--fs-sm); margin-bottom: 7px; }
.mmx-tools-search-box { display: flex; min-width: 0; background: var(--bg); border: 1px solid var(--nr-line-strong); border-radius: var(--r-card,12px); }
.mmx-tools-search-box input { appearance: none; width: 100%; min-width: 0; min-height: 44px; padding: 10px 13px; border: 0; outline: none; background: transparent; color: var(--text); font: inherit; }
.mmx-tools-search-box:focus-within { outline: 2px solid var(--link); outline-offset: 3px; }
.mmx-tools-search-box input::placeholder { color: var(--muted); opacity: 1; }
.mmx-tools button { font-family: var(--font-ui); }
.mmx-tools-icon-button { display: inline-flex; align-items: center; justify-content: center; min-width: 44px; min-height: 44px; flex: 0 0 44px; border: 1px solid var(--nr-line-strong); border-radius: var(--r-btn,10px); color: var(--text); background: transparent; cursor: pointer; }
.mmx-tools-icon-button svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
.mmx-tools-search-box .mmx-tools-icon-button { border: 0; }
.mmx-tools-icon-button[hidden] { display: none; }
.mmx-tools-categories { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 28px 14px; border-bottom: 1px solid var(--nr-line); }
.mmx-tools-categories button { min-height: 44px; padding: 8px 12px; border: 1px solid transparent; border-radius: var(--r-ctl,8px); color: var(--muted); background: transparent; font-size: var(--fs-sm); cursor: pointer; }
.mmx-tools-categories button[aria-pressed="true"] { color: var(--text); background: var(--nr-soft); border-color: var(--nr-line-strong); box-shadow: inset 0 -2px var(--link); }
.mmx-tools-body { min-height: 100px; flex: 1; display: grid; grid-template-columns: minmax(0,1fr) 205px; gap: 26px; padding: 24px 28px; overflow: auto; overscroll-behavior: contain; scrollbar-gutter: stable; }
.mmx-tools-results { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); align-content: start; gap: 26px; min-width: 0; }
.mmx-tools-group { min-width: 0; }
.mmx-tools-group h3 { display: flex; margin: 0 0 9px; min-height: 34px; padding-bottom: 10px; align-items: center; border-bottom: 1px solid var(--nr-line); font: 600 var(--fs-sm)/1.5 var(--font-ui); color: var(--text); }
.mmx-tools-grid { display: flex; flex-direction: column; gap: 5px; }
.mmx-tools-link { display: grid; grid-template-columns: 42px minmax(0,1fr) 16px; align-items: center; gap: 11px; min-height: 82px; padding: 11px 7px; border: 1px solid transparent; border-radius: var(--r-card,12px); text-decoration: none; color: var(--text); transition: background .14s ease, border-color .14s ease; }
.mmx-tools-link:hover { color: var(--text); background: var(--nr-soft); border-color: var(--nr-line); text-decoration: none; }
.mmx-tools-copy { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-width: 0; }
.mmx-tools-copy strong { font-size: var(--fs-body); line-height: 1.35; font-weight: 600; overflow-wrap: anywhere; }
.mmx-tools-description { display: block; width: 100%; color: var(--muted); font-size: var(--fs-sm); line-height: 1.5; overflow-wrap: anywhere; }
.mmx-tools-badge { flex-shrink: 0; padding: 1px 5px; border: 1px solid var(--nr-line-strong); border-radius: var(--r-ctl,8px); font-size: var(--fs-micro); line-height: 1.5; letter-spacing: .06em; color: var(--link); }
.mmx-tools-arrow { justify-self: end; align-self: center; color: var(--muted); font-size: 15px; }
.mmx-tools-glyph { position: relative; width: 42px; height: 42px; display: grid; place-items: center; color: var(--muted); }
.mmx-tools-glyph::before { content: ''; position: absolute; inset: 2px; border: 1px dashed var(--nr-line); border-radius: var(--r-ctl,8px); }
.mmx-tools-glyph svg { width: 38px; height: 38px; fill: none; stroke: currentColor; stroke-width: 1.2; stroke-linecap: round; stroke-linejoin: round; }
.mmx-tools-glyph .accent { stroke: var(--link); }
.mmx-tools-glyph .ghost { stroke: var(--muted); opacity: .5; stroke-dasharray: 2 3; }
.mmx-tools-glyph .soft-fill { fill: color-mix(in srgb, var(--link) 20%, transparent); stroke: var(--link); }
.mmx-tools-link[aria-disabled="true"] { cursor: default; opacity: .7; }
.mmx-tools-aside { min-width: 0; padding: 7px 0 0 24px; border-left: 1px solid var(--nr-line); }
.mmx-tools-eyebrow { font-size: var(--fs-label); letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin: 0 0 12px; }
.mmx-tools-aside h3 { margin: 0 0 12px; font-size: var(--fs-num-lg); line-height: 1.2; font-weight: 600; letter-spacing: -.02em; }
.mmx-tools-aside p:not(.mmx-tools-eyebrow) { margin: 0 0 18px; font-size: var(--fs-sm); color: var(--muted); line-height: 1.6; }
.mmx-tools-context { color: var(--text); padding-top: 18px; border-top: 1px solid var(--nr-line); }
.mmx-tools-footer { display: flex; width: 100%; max-width: none; margin: 0; align-items: center; justify-content: space-between; gap: 18px; flex-wrap: wrap; padding: 12px 28px max(12px,env(safe-area-inset-bottom)); border-top: 1px solid var(--nr-line); background: var(--bg); }
.mmx-tools-footer button, .mmx-tools-action { display: inline-flex; align-items: center; min-height: 44px; padding: 8px 12px; border: 1px solid var(--nr-line-strong); border-radius: var(--r-btn,10px); background: var(--nr-soft); color: var(--text); font: 600 var(--fs-sm)/1.5 var(--font-ui); cursor: pointer; }
.mmx-tools-footer span { color: var(--muted); font-size: var(--fs-sm); }
.mmx-tools-status { margin: 0; padding: 0 28px 12px; color: var(--muted); font-size: var(--fs-sm); }
.mmx-tools-status:empty { display: none; }
.mmx-tools-empty { grid-column: 1/-1; max-width: 500px; padding: 24px 10px; }
.mmx-tools-empty h3 { font-size: var(--fs-num-lg); line-height: 1.25; margin: 0 0 10px; }
.mmx-tools-empty p { color: var(--muted); margin: 0 0 20px; }
.mmx-tools button:disabled { cursor: default; opacity: .65; }
.mmx-tools a:focus-visible, .mmx-tools button:focus-visible, .mmx-tools-trigger:focus-visible { outline: 2px solid var(--link); outline-offset: 3px; }
/* Light is a paper-like research material: a stronger rail and crisp stroke,
   not the dark panel with its luminance glow left in place. */
html[data-theme="light"] .mmx-tools { background: var(--nr-surface-solid); box-shadow: var(--nr-shadow); border-color: var(--nr-line-strong); }
html[data-theme="light"] .mmx-tools::backdrop { background: color-mix(in srgb,var(--text) 25%,transparent); backdrop-filter: blur(2px); }
html[data-theme="light"] .mmx-tools-header, html[data-theme="light"] .mmx-tools-categories { background: var(--nr-surface-solid); }
html[data-theme="light"] .mmx-tools-body { background: var(--nr-surface-solid); }
