/* Search geometry and motion keep the approved composition, but use one short,
   GPU-friendly settle. The earlier 420ms width + 420ms panel + blurred-card
   sequence made opening and closing feel queued rather than direct. */
.nav-search.ticker-search {
  position: relative;
  z-index: 110;
  width: 128px;
  max-width: none;
  height: 40px;
  flex: none;
  overflow: visible;
  transition: width .2s cubic-bezier(.2, .82, .2, 1);
  will-change: width;
}

.nav-search.ticker-search.open { width: 300px; }

.ticker-search .search-trigger,
.ticker-search .search-expanded {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  border: 1px solid var(--mock-line-strong);
  border-radius: 12px;
  color: #647086;
  background: var(--mock-surface);
  box-shadow: 0 5px 15px rgba(31, 39, 58, .09), inset 0 1px 0 rgba(255,255,255,.12);
}

.ticker-search .search-trigger {
  gap: 7px;
  justify-content: center;
  padding: 0 10px;
  overflow: hidden;
}

.ticker-search .search-trigger:hover {
  border-color: #c7d0e0;
  box-shadow: 0 8px 20px rgba(31, 39, 58, .12), inset 0 1px 0 rgba(255,255,255,.15);
  transform: translateY(-1px);
}

.ticker-search .search-expanded {
  gap: 8px;
  padding: 0 8px 0 11px;
  min-width: 0;
  overflow: hidden;
  transform: scaleX(.58);
  transform-origin: right center;
  /* Keep the closing plate present through its fade, but never delay the
     opening visibility edge: openSearch() moves keyboard focus on the first
     animation frame, and a still-hidden descendant cannot accept focus. */
  transition:
    opacity .12s ease,
    transform .2s cubic-bezier(.2, .82, .2, 1),
    border-color .14s ease,
    visibility 0s linear .2s;
  will-change: opacity, transform;
}

.ticker-search.open .search-expanded {
  border-color: #bfc9da;
  transform: scaleX(1);
  transition:
    opacity .12s ease,
    transform .2s cubic-bezier(.2, .82, .2, 1),
    border-color .14s ease,
    visibility 0s linear 0s;
}

.ticker-search .search-glyph { width: 15px; height: 15px; }

.ticker-search .idle-ticker {
