.nxi-drawer-close:focus-visible{ outline:2px solid var(--info); outline-offset:2px; }
.nxi-drawer-scroll{ overflow:auto; overscroll-behavior:contain; padding:22px 24px 32px; }
.nxi-drawer-title{ margin:0; font-size:26px; line-height:1.16; letter-spacing:-.025em; }
.nxi-drawer-meta{ display:flex; flex-wrap:wrap; gap:7px; align-items:center; margin:10px 0 18px; color:var(--muted); font-size:10px; }
.nxi-drawer-section{ padding:16px 0; border-top:1px solid var(--line); }
.nxi-drawer-section>h3{ margin:0 0 10px; color:var(--muted); font-size:9.5px; font-weight:750; letter-spacing:.11em; text-transform:uppercase; }
.nxi-drawer-section p{ margin:0; color:var(--text); font-size:12px; line-height:1.5; }
.nxi-drawer-section p+p{ margin-top:8px; color:var(--muted); }
.nxi-drawer-market{ display:flex; align-items:center; justify-content:space-between; gap:12px; padding:10px 12px; border-radius:var(--r-ctl,8px); background:var(--panel2); }
.nxi-drawer-market span:first-child{ color:var(--muted); font-size:9px; font-weight:750; letter-spacing:.08em; text-transform:uppercase; }
.nxi-drawer-market b{ font-family:var(--num); font-size:12px; }
.nxi-drawer-assets{ display:flex; flex-wrap:wrap; gap:7px; }
.nxi-drawer-assets a{ padding:6px 9px; border-radius:var(--r-ctl,8px); background:var(--panel2); border:1px solid var(--line); color:var(--ink-link,var(--link)); font:750 10px/1.2 var(--num); }
.nxi-review-note{ margin-top:8px!important; color:var(--muted)!important; font-size:10px!important; }
body.nxi-drawer-open{ overflow:hidden; }
body.nxi-drawer-open #mmb-launch,
body.nxi-drawer-open #mmb-boot{ opacity:0!important; pointer-events:none!important; visibility:hidden!important; }

