  .nx-depth{ margin:14px 0 20px; }
  .nx-depth-summary{ min-height:48px; padding:11px 13px; }
  .nx-depth-body{ padding:0 12px 14px; }
  .nx-attention{ display:block; padding:12px 0 14px; }
