  .nx-attention .nx-pulse-sent{ display:flex; margin-top:10px; }
  .nxi-head{ padding:16px; }
  .nxi-metrics{ grid-template-columns:repeat(2,1fr); }
  .nxi-toolbar{ padding:10px 16px; overflow-x:auto; flex-wrap:nowrap; }
  .nxi-filter{ flex:0 0 auto; }
  .nxi-result-count{ margin-left:auto; }
  .nxi-list{ padding:0 16px 8px; }
  .nxi-open{ grid-template-columns:32px minmax(0,1fr); gap:8px 10px; padding:14px 0; }
  .nxi-rank{ grid-column:1; grid-row:1; }
  .nxi-row-copy{ grid-column:2; grid-row:1; }
