rules.old:
/* The Price of Duration — report-scoped editorial and figure system. */
.pod {
  --pod-blue:#5b8def;
  --pod-gold:#d6a84b;
  --pod-teal:#36a995;
  --pod-red:#d85b62;
  --pod-violet:#8f7bd8;
  --pod-ink:var(--text);
  --pod-grid:color-mix(in srgb,var(--line) 72%,transparent);
  --pod-body-size:18px;
  font-size:var(--pod-body-size);
  line-height:1.66;
}
.pod + .disc { display:none; }
.pod > p,
.pod .pod-copy p {
  font-size:var(--pod-body-size);
  line-height:1.66;
  margin:12px 0;
}
.pod h2 {
  font-size:25px;
  line-height:1.24;
  margin-top:44px;
  letter-spacing:-.018em;
}
.pod h3 {
  font-size:18px;
  line-height:1.35;
  margin-top:27px;
  margin-bottom:8px;
  letter-spacing:-.01em;
}
.pod .pod-deck {
  margin:4px 0 22px;
  color:var(--muted);
  font-size:15px;
  line-height:1.55;
  border-left:2px solid var(--pod-gold);
  padding-left:12px;
}
.pod .pod-snapshot {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:9px;
  margin:18px 0 10px;
}
.pod .pod-gauge {
  min-width:0;
  border:1px solid var(--line);
  background:linear-gradient(145deg,var(--panel2),color-mix(in srgb,var(--panel) 88%,var(--pod-c,var(--pod-blue))));
  border-radius:12px;
  padding:12px 12px 11px;
  box-shadow:var(--card-shadow);
  position:relative;
  overflow:hidden;
}
.pod .pod-gauge::before {
  content:"";
  position:absolute;
  inset:0 auto 0 0;
  width:3px;
  background:var(--pod-c,var(--pod-blue));
}
.pod .pod-gauge b {
  display:block;
  font-size:21px;
  line-height:1;
  letter-spacing:-.025em;
  font-variant-numeric:tabular-nums;
  color:var(--text);
}
.pod .pod-gauge-label {
  margin-top:6px;
  color:var(--muted);
  font-size:10.5px;
  line-height:1.35;
}
.pod .pod-asof {
  color:var(--muted);
  font-size:10.5px;
  line-height:1.45;
  margin:8px 0 22px;
}
.pod .pod-thesis {
  margin:25px 0;
  border:1px solid color-mix(in srgb,var(--pod-gold) 44%,var(--line));
  border-radius:18px;
  padding:25px 28px;
  position:relative;
  overflow:hidden;
  background:
    radial-gradient(circle at 92% 12%,color-mix(in srgb,var(--pod-gold) 17%,transparent),transparent 34%),
    linear-gradient(135deg,color-mix(in srgb,var(--pod-blue) 10%,var(--panel)),var(--panel));
  box-shadow:var(--card-shadow);
}
.pod .pod-thesis::before {
  content:"";
  position:absolute;
  left:0;
  top:0;
  bottom:0;
  width:4px;
  background:linear-gradient(180deg,var(--pod-gold),var(--pod-blue));
}
.pod .pod-thesis p {
  margin:0;
  font-size:19px;
  line-height:1.55;
  letter-spacing:-.012em;
  font-weight:650;
}
.pod .pod-thesis small {
  display:block;
  margin-bottom:8px;
  color:var(--pod-gold);
  font-size:10.5px;
  text-transform:uppercase;
  letter-spacing:.15em;
  font-weight:800;
}
.pod .pod-proof-key {
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin:14px 0 20px;
}
.pod .pod-proof-chip {
  display:inline-flex;
  gap:5px;
  align-items:center;
  border:1px solid var(--line);
  border-radius:999px;
  padding:4px 8px;
  color:var(--muted);
  font-size:10.5px;
  background:var(--panel2);
}
.pod .pod-motion-toggle {
  display:inline-flex;
  align-items:center;
  gap:7px;
  position:fixed;
  left:max(14px,env(safe-area-inset-left));
  bottom:max(14px,env(safe-area-inset-bottom));
  z-index:5000;
  min-height:29px;
  border:1px solid color-mix(in srgb,var(--pod-blue) 45%,var(--line));
  border-radius:999px;
  padding:5px 10px;
  color:var(--text);
  background:color-mix(in srgb,var(--pod-blue) 8%,var(--panel2));
  font:700 10.5px/1.2 var(--font-ui);
  box-shadow:0 8px 26px color-mix(in srgb,#000 16%,transparent);
  backdrop-filter:blur(10px);
  cursor:pointer;
}
.pod .pod-motion-toggle::before {
  content:"";
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--pod-teal);
  box-shadow:0 0 0 3px color-mix(in srgb,var(--pod-teal) 18%,transparent);
}
.pod .pod-motion-toggle:hover,
.pod .pod-motion-toggle:focus-visible {
  border-color:var(--pod-blue);
  outline:2px solid color-mix(in srgb,var(--pod-blue) 28%,transparent);
  outline-offset:2px;
}
.pod .pod-motion-toggle[aria-pressed="true"]::before { background:var(--muted); box-shadow:none; }
.pod .pod-motion-label-resume { display:none; }
.pod .pod-motion-toggle[aria-pressed="true"] .pod-motion-label-pause { display:none; }
.pod .pod-motion-toggle[aria-pressed="true"] .pod-motion-label-resume { display:inline; }
.pod sup.ev {
  display:inline-block;
  font-size:9px;
  font-weight:850;
  line-height:1;
  padding:2px 4px;
  border-radius:4px;
  margin-left:2px;
  vertical-align:2px;
}
.pod .ev-f { color:#218754; background:color-mix(in srgb,#46b87a 15%,transparent); }
.pod .ev-c { color:#3f71c5; background:color-mix(in srgb,#5b8def 15%,transparent); }
.pod .ev-i { color:#765fc1; background:color-mix(in srgb,#8f7bd8 15%,transparent); }
.pod .ev-s { color:#a76c16; background:color-mix(in srgb,#d6a84b 18%,transparent); }
html[data-theme="dark"] .pod .ev-f { color:#55c98e; }
html[data-theme="dark"] .pod .ev-c { color:#81aaf0; }
html[data-theme="dark"] .pod .ev-i { color:#b5a4ef; }
html[data-theme="dark"] .pod .ev-s { color:#e4bb68; }

.pod .pod-figure {
  margin:27px 0;
  border:1px solid var(--line);
  border-radius:18px;
  padding:16px 17px 13px;
  background:
    linear-gradient(var(--panel),var(--panel)) padding-box,
    linear-gradient(135deg,var(--pod-blue),var(--pod-gold)) border-box;
  box-shadow:var(--card-shadow);
  overflow:hidden;
}
.pod .pod-figure-head {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  margin-bottom:12px;
}
.pod .pod-figure-head b {
  font-size:14px;
  letter-spacing:.11em;
  text-transform:uppercase;
  color:var(--text);
}
.pod .pod-figure-head span {
  color:var(--muted);
  font-size:13px;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.pod .pod-figure svg {
  display:block;
  width:100%;
  height:auto;
  overflow:visible;
}
.pod .pod-figure figcaption {
  margin-top:11px;
  padding-top:9px;
  border-top:1px dashed var(--line);
  color:var(--muted);
  font-size:15px;
  line-height:1.58;
}
.pod .pod-svg-text { fill:var(--text); font-family:var(--font-ui); }
.pod .pod-svg-muted { fill:var(--muted); font-family:var(--font-ui); }
.pod .pod-figure text[font-size="9"] { font-size:11px; }
.pod .pod-figure text[font-size="9.5"] { font-size:11px; }
.pod .pod-figure text[font-size="10"] { font-size:11.5px; }
.pod .pod-figure text[font-size="10.5"] { font-size:11.5px; }
.pod .pod-figure text[font-size="11"] { font-size:12px; }
.pod .pod-svg-grid { stroke:var(--pod-grid); }
.pod .pod-node {
  fill:color-mix(in srgb,var(--panel2) 92%,transparent);
  stroke:var(--line);
}
.pod .pod-arrow {
  fill:none;
  stroke:var(--pod-blue);
  stroke-width:2.2;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.pod .pod-arrow-gold { stroke:var(--pod-gold); }
.pod .pod-arrow-teal { stroke:var(--pod-teal); }
.pod .pod-arrow-red { stroke:var(--pod-red); }
.pod .pod-reveal {
  opacity:1;
  transform:none;
  transition:opacity .7s ease,transform .7s cubic-bezier(.2,.7,.2,1);
}
.pod .pod-figure.pod-motion-pending .pod-reveal {
  opacity:0;
  transform:translateY(7px);
}
.pod .pod-figure.is-visible .pod-reveal {
  opacity:1;
  transform:none;
}
.pod .pod-figure.is-visible .pod-reveal:nth-of-type(2) { transition-delay:.12s; }
.pod .pod-figure.is-visible .pod-reveal:nth-of-type(3) { transition-delay:.24s; }
.pod .pod-figure.is-visible .pod-reveal:nth-of-type(4) { transition-delay:.36s; }
.pod .pod-figure.is-visible .pod-reveal:nth-of-type(5) { transition-delay:.48s; }
.pod .pod-draw {
  stroke-dasharray:760;
  stroke-dashoffset:0;
  transition:stroke-dashoffset 1.15s cubic-bezier(.3,.7,.2,1);
}
.pod .pod-figure.pod-motion-pending .pod-draw { stroke-dashoffset:760; }
.pod .pod-figure.is-visible .pod-draw { stroke-dashoffset:0; }

/* Report-scoped motion grammar: static final state first, motion only while visible. */
.pod .pod-motion-flow {
  opacity:0;
  pointer-events:none;
  offset-rotate:0deg;
}
.pod .pod-motion-trail {
  fill:none;
  stroke:var(--pod-red);
  stroke-width:1.5;
  stroke-dasharray:4 6;
  opacity:.42;
}
.pod .pod-motion-point,
.pod .pod-motion-collapse,
.pod .pod-motion-accumulator,
.pod .pod-motion-meter,
.pod .pod-motion-convergence,
.pod .pod-motion-machine,
.pod .pod-motion-frontier,
.pod .pod-motion-clock,
.pod .pod-motion-synapse,
.pod .pod-motion-probability,
.pod .pod-motion-gauge,
.pod .pod-motion-pulse,
.pod .pod-motion-connector,
.pod .pod-motion-bubble {
  transform-box:fill-box;
}
.pod .pod-motion-point,
.pod .pod-motion-pulse,
.pod .pod-motion-accumulator,
.pod .pod-motion-gauge { transform-origin:center; }
.pod .pod-motion-probability,
.pod .pod-motion-gauge-level { transform-origin:left center; }
.pod .pod-motion-connector {
  stroke-dasharray:7 8;
  transition:none;
}

.pod .pod-figure.is-motion-active .pod-motion-flow {
  animation:pod-flow-travel var(--pod-flow-duration,5.4s) linear var(--pod-flow-delay,0s) infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-point {
  animation:pod-point-arrive 5.8s cubic-bezier(.22,.72,.2,1) infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-collapse {
  animation:pod-collapse-charge 5.8s ease-in-out infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-accumulator {
  animation:pod-accumulator-ring 3.8s ease-out .8s infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-meter {
  animation:pod-meter-settle 6.2s cubic-bezier(.22,.72,.2,1) .6s infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-frontier {
  animation:pod-frontier-stream 3.8s linear infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-clock {
  animation:pod-clock-turn var(--pod-clock-duration,12s) linear var(--pod-clock-delay,0s) infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-probability {
  animation:pod-level-settle 1.35s cubic-bezier(.22,.72,.2,1) var(--pod-level-delay,0s) both;
}
.pod .pod-figure.is-motion-active .pod-motion-gauge {
  animation:pod-gauge-scan 3.2s ease-in-out var(--pod-gauge-delay,0s) infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-pulse {
  animation:pod-center-breathe 3.6s ease-in-out infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-connector {
  animation:pod-connector-flow 2.8s linear infinite;
}
.pod .pod-figure.is-motion-active .pod-motion-bubble {
  animation:pod-bubble-lift .9s cubic-bezier(.2,.75,.2,1) var(--pod-bubble-delay,0s) both;
}

@keyframes pod-flow-travel {
  0% { offset-distance:0%; opacity:0; }
  8% { opacity:1; }
  84% { opacity:1; }
  94%,100% { offset-distance:100%; opacity:0; }
}
@keyframes pod-point-arrive {
  0%,10% { transform:translate(-70px,70px) scale(.72); opacity:.18; }
  34%,82% { transform:none; opacity:1; }
  88% { transform:scale(1.34); opacity:.48; }
  96%,100% { transform:none; opacity:1; }
}
@keyframes pod-collapse-charge {
  0%,25%,100% { opacity:.7; stroke-width:1; }
  34%,62% { opacity:1; stroke-width:2.4; }
}
@keyframes pod-accumulator-ring {
  0% { transform:scale(.72); opacity:0; }
  24% { opacity:.72; }
  78%,100% { transform:scale(1.14); opacity:0; }
}
@keyframes pod-meter-settle {
  0%,8% { transform:translateX(-270px); opacity:0; }
  18% { opacity:1; }
  48%,90% { transform:none; opacity:1; }
  100% { transform:none; opacity:0; }
}
@keyframes pod-frontier-stream { to { stroke-dashoffset:-48; } }
@keyframes pod-clock-turn { to { transform:rotate(360deg); } }
@keyframes pod-level-settle {
  from { transform:scaleX(0); opacity:.25; }
  to { transform:scaleX(1); opacity:1; }
}
@keyframes pod-gauge-scan {
  0%,100% { transform:scale(.78); opacity:.44; }
  45%,65% { transform:scale(1.28); opacity:1; }
}
@keyframes pod-center-breathe {
  0%,100% { transform:scale(.985); opacity:.72; }
  50% { transform:scale(1.025); opacity:1; }
}
@keyframes pod-connector-flow { to { stroke-dashoffset:-32; } }
@keyframes pod-bubble-lift {
  from { transform:translateY(28px) scale(.9); opacity:.18; }
  to { transform:none; opacity:1; }
}

.pod .pod-accounting {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px;
  margin:17px 0 23px;
}
.pod .pod-ledger {
  border:1px solid var(--line);
  border-radius:14px;
  padding:15px 16px;
  background:var(--panel2);
}
.pod .pod-ledger h3 {
  margin:0 0 9px;
  font-size:13px;
}
.pod .pod-ledger.good { border-top:3px solid var(--pod-teal); }
.pod .pod-ledger.bad { border-top:3px solid var(--pod-red); }
.pod .pod-ledger ul { margin:0; padding-left:18px; }
.pod .pod-ledger li { margin:5px 0; font-size:12.5px; line-height:1.48; }
.pod .pod-callout {
  border-left:3px solid var(--pod-c,var(--pod-blue));
  background:color-mix(in srgb,var(--pod-c,var(--pod-blue)) 8%,var(--panel2));
  border-radius:0 12px 12px 0;
  padding:13px 15px;
  margin:18px 0;
}
.pod .pod-callout b {
  color:var(--pod-c,var(--pod-blue));
  display:block;
  font-size:11px;
  letter-spacing:.1em;
  text-transform:uppercase;
  margin-bottom:5px;
}
.pod .pod-callout p:last-child { margin-bottom:0; }
.pod .pod-plain {
  margin:18px 0;
  border:1px solid var(--line);
  border-radius:14px;
  padding:15px 17px;
  background:var(--panel2);
}
.pod .pod-plain > b {
  display:block;
  margin-bottom:6px;
  color:var(--pod-gold);
  font-size:10.5px;
  text-transform:uppercase;
  letter-spacing:.12em;
}
.pod .pod-table-wrap { overflow-x:auto; margin:18px 0 25px; border:1px solid var(--line); border-radius:14px; }
.pod table.pod-table { width:100%; min-width:680px; border-collapse:collapse; background:var(--panel); }
.pod table.pod-table-wide { min-width:920px; }
.pod table.pod-table th,
.pod table.pod-table td { border-bottom:1px solid var(--line); padding:10px 11px; vertical-align:top; }
.pod table.pod-table th {
  background:var(--panel2);
  color:var(--muted);
  font-size:10px;
  letter-spacing:.075em;
  text-transform:uppercase;
  text-align:left;
}
.pod table.pod-table td { font-size:15px; line-height:1.55; }
.pod table.pod-table tr:last-child td { border-bottom:0; }
.pod .pod-rule {
  border:0;
  border-top:1px solid var(--line);
  margin:29px 0;
}
.pod .pod-copy p { margin:0 0 15px; }
.pod .pod-copy blockquote {
  margin:20px 0;
  padding:16px 19px;
  border-left:3px solid var(--pod-gold);
  background:var(--panel2);
  border-radius:0 12px 12px 0;
  font-size:17px;
  line-height:1.55;
  font-weight:650;
}
.pod .pod-copy h3 { margin-top:28px; scroll-margin-top:88px; }
.pod .pod-strongline {
  font-size:17px;
  line-height:1.5;
  font-weight:750;
  letter-spacing:-.01em;
  color:var(--text);
  margin:19px 0;
}
.pod .pod-source-list {
  display:grid;
  gap:8px;
  margin:14px 0;
}
.pod .pod-source-list a {
  display:block;
  padding:10px 12px;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--panel2);
  font-size:13.5px;
}
.pod .pod-note {
  color:var(--muted);
  font-size:13.5px;
  line-height:1.55;
}

/* The Price of Duration — complete Editorial V2 composition. */
.pod .pod-v2-shell { display:block; }
.pod .statband {
  display:grid;
  grid-template-columns:repeat(5,minmax(0,1fr));
  gap:10px;
  margin:2px 0 12px;
}
.pod .stat {
  min-width:0;
  position:relative;
  overflow:hidden;
  min-height:116px;
  padding:14px 14px 13px;
  border:1px solid var(--line);
  border-radius:14px;
  background:
    radial-gradient(circle at 100% 0,color-mix(in srgb,var(--sc,var(--pod-blue)) 14%,transparent),transparent 52%),
    var(--panel2);
  box-shadow:var(--card-shadow);
}
.pod .stat::before {
  content:"";
  position:absolute;
  inset:0 auto 0 0;
  width:3px;
  background:var(--sc,var(--pod-blue));
}
.pod .stat .sk {
  display:block;
  color:var(--muted);
  font-size:11.5px;
  line-height:1.25;
  letter-spacing:.1em;
  text-transform:uppercase;
  font-weight:750;
}
.pod .stat .sv {
  display:block;
  margin-top:8px;
  color:var(--text);
  font-size:23px;
  line-height:1;
  letter-spacing:-.025em;
  font-weight:780;
  font-variant-numeric:tabular-nums;
}
.pod .stat .sl {
  display:block;
  margin-top:8px;
  color:var(--muted);
  font-size:12.5px;
  line-height:1.42;
}
.pod .pod-v2-asof {
  margin:0 0 17px;
  color:var(--muted);
  font-size:13px;
  line-height:1.55;
}
.pod .pod-bottom-line {
  margin:15px 0 26px;
  padding:20px 22px;
  border-left-width:4px;
}
.pod .pod-bottom-line .co-h {
  color:#2f9e63;
  font-size:10.5px;
  letter-spacing:.13em;
  text-transform:uppercase;
}
html[data-theme="dark"] .pod .pod-bottom-line .co-h { color:#55c98e; }
.pod .pod-bottom-line p {
  margin:0;
  font-size:17px;
  line-height:1.62;
  letter-spacing:-.006em;
}
.pod .pod-section-kicker {
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:8px;
  margin:4px 0 13px;
  color:var(--muted);
  font-size:12px;
  letter-spacing:.09em;
  text-transform:uppercase;
  font-weight:750;
}
.pod .pod-section-kicker::before {
  content:"";
  width:22px;
  height:2px;
  border-radius:2px;
  background:linear-gradient(90deg,var(--pod-gold),var(--pod-blue));
}
.pod .pod-intro-grid {
  display:grid;
  grid-template-columns:minmax(0,1.35fr) minmax(220px,.65fr);
  gap:18px;
  align-items:start;
  margin:8px 0 19px;
}
.pod .pod-intro-grid .pod-copy p:first-child { margin-top:0; }
.pod .pod-mechanism-card {
  border:1px solid color-mix(in srgb,var(--pod-gold) 38%,var(--line));
  border-radius:15px;
  padding:16px;
  background:linear-gradient(150deg,color-mix(in srgb,var(--pod-gold) 10%,var(--panel2)),var(--panel2));
}
.pod .pod-mechanism-card .mk {
  display:block;
  color:var(--pod-gold);
  font-size:9.5px;
  letter-spacing:.11em;
  text-transform:uppercase;
  font-weight:800;
}
.pod .pod-mechanism-card strong {
  display:block;
  margin:7px 0 9px;
  font-size:18px;
  line-height:1.28;
  letter-spacing:-.015em;
}
.pod .pod-mechanism-card p {
  margin:0;
  color:var(--muted);
  font-size:14px;
  line-height:1.58;
}
.pod .pod-loop {
  display:grid;
  grid-template-columns:repeat(6,minmax(0,1fr));
  gap:0;
  margin:17px 0 20px;
  border:1px solid var(--line);
  border-radius:14px;
  overflow:hidden;
  background:var(--panel2);
}
.pod .pod-loop-step {
  position:relative;
  padding:12px 18px 12px 11px;
  min-height:74px;
  border-right:1px solid var(--line);
}
.pod .pod-loop-step:last-child { border-right:0; }
.pod .pod-loop-step:not(:last-child)::after {
  content:"→";
  position:absolute;
  z-index:2;
  top:26px;
  right:-8px;
  width:16px;
  color:var(--pod-gold);
  background:var(--panel2);
  text-align:center;
  font-weight:800;
}
.pod .pod-loop-step b {
  display:block;
  font-size:13px;
  line-height:1.25;
}
.pod .pod-loop-step small {
  display:block;
  margin-top:5px;
  color:var(--muted);
  font-size:11.5px;
  line-height:1.38;
}
.pod .pod-stage-band {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px;
  margin:17px 0 22px;
}
.pod .pod-stage {
  border:1px solid var(--line);
  border-top:3px solid var(--stage,var(--pod-blue));
  border-radius:12px;
  padding:13px 14px;
  background:var(--panel2);
}
.pod .pod-stage b { display:block; font-size:14px; }
.pod .pod-stage p { margin:6px 0 0; color:var(--muted); font-size:13px; line-height:1.48; }
.pod .pod-split-figure {
  display:grid;
  grid-template-columns:minmax(0,1fr);
  gap:14px;
  align-items:stretch;
  margin:16px 0 20px;
}
.pod .pod-split-figure .pod-figure { margin:0; }
.pod .pod-equation {
  display:flex;
  flex-direction:column;
  justify-content:center;
  border:1px solid var(--line);
  border-radius:18px;
  padding:18px;
  background:
    radial-gradient(circle at 100% 0,color-mix(in srgb,var(--pod-violet) 18%,transparent),transparent 45%),
    var(--panel2);
}
.pod .pod-equation .eq-k {
  color:var(--pod-violet);
  font-size:9.5px;
  letter-spacing:.12em;
  text-transform:uppercase;
  font-weight:800;
}
.pod .pod-equation .eq-main {
  margin:13px 0;
  font-size:18px;
  line-height:1.3;
  font-weight:780;
  letter-spacing:-.015em;
}
.pod .pod-equation .eq-rule {
  height:1px;
  margin:7px 0;
  background:linear-gradient(90deg,var(--pod-violet),transparent);
}
.pod .pod-equation p { margin:4px 0 0; color:var(--muted); font-size:13.5px; line-height:1.55; }
.pod .pod-status-grid {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin:18px 0 24px;
}
.pod .vcard {
  min-width:0;
  border:1px solid var(--line);
  border-top:3px solid var(--vc,var(--pod-blue));
  border-radius:13px;
  padding:13px 14px;
  background:var(--panel2);
}
.pod .vcard .vtag {
  display:inline-flex;
  align-items:center;
  gap:6px;
  color:var(--vc,var(--pod-blue));
  font-size:9.5px;
  letter-spacing:.08em;
  text-transform:uppercase;
  font-weight:800;
}
.pod .vcard .vtag::before {
  content:"";
  width:7px;
  height:7px;
  border-radius:50%;
  background:currentColor;
  box-shadow:0 0 0 3px color-mix(in srgb,currentColor 16%,transparent);
}
.pod .vcard h3 { margin:9px 0 5px; font-size:14px; }
.pod .vcard p { margin:0; color:var(--muted); font-size:14.5px; line-height:1.6; }
.pod .pod-regime-strip {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin:16px 0 20px;
}
.pod .pod-regime-card {
  min-width:0;
  border:1px solid var(--line);
  border-top:3px solid var(--rc,var(--pod-blue));
  border-radius:13px;
  padding:13px 14px;
  background:var(--panel2);
}
.pod .pod-regime-card .rp {
  color:var(--rc,var(--pod-blue));
  font-size:23px;
  line-height:1;
  font-weight:800;
  font-variant-numeric:tabular-nums;
}
.pod .pod-regime-card b { display:block; margin-top:7px; font-size:12px; line-height:1.25; }
.pod .pod-regime-card p { margin:6px 0 0; color:var(--muted); font-size:14.5px; line-height:1.55; }
.pod .pod-compact { margin-top:12px; margin-bottom:24px; }
.pod .pod-compact th { font-size:12.5px; line-height:1.38; }
.pod .pod-compact td { font-size:15px; line-height:1.55; padding:11px 12px; }
.pod .pod-shell-rail {
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin:10px 0 15px;
}
.pod .pod-shell-rail .chip { font-size:12px; padding:6px 9px; }
.pod .pod-dashboard td:first-child { width:25%; }
.pod .pod-timeline {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin:16px 0 24px;
}
.pod .pod-gate {
  border:1px solid var(--line);
  border-radius:13px;
  padding:13px 14px;
  background:var(--panel2);
}
.pod .pod-gate .gk { color:var(--pod-gold); font-size:11.5px; letter-spacing:.08em; text-transform:uppercase; font-weight:800; }
.pod .pod-gate b { display:block; margin:7px 0 4px; font-size:14px; }
.pod .pod-gate p { margin:0; color:var(--muted); font-size:14.5px; line-height:1.55; }
.pod .pquote {
  position:relative;
  overflow:hidden;
  margin:23px 0;
  padding:23px 26px;
  border:1px solid var(--line);
  border-radius:17px;
  background:linear-gradient(135deg,color-mix(in srgb,var(--pod-blue) 13%,var(--panel)),color-mix(in srgb,var(--pod-gold) 10%,var(--panel)));
}
.pod .pquote::before {
  content:"\201C";
  position:absolute;
  top:-21px;
  left:13px;
  color:var(--pod-blue);
  opacity:.16;
  font:96px/1 var(--font-ui);
}
.pod .pquote p { position:relative; margin:0; font-size:18px; line-height:1.58; font-weight:650; }

html[data-theme="light"] .pod {
  --pod-grid:color-mix(in srgb,var(--text) 22%,transparent);
}
html[data-theme="light"] .pod .pod-figure {
  background:var(--panel);
  border-color:color-mix(in srgb,var(--text) 18%,transparent);
  box-shadow:0 16px 38px -30px color-mix(in srgb,var(--text) 45%,transparent),
             0 1px 2px color-mix(in srgb,var(--text) 12%,transparent);
}
html[data-theme="light"] .pod .pod-node {
  fill:color-mix(in srgb,var(--panel2) 72%,var(--panel));
  stroke:color-mix(in srgb,var(--text) 24%,transparent);
}
html[data-theme="light"] .pod .stat,
html[data-theme="light"] .pod .pod-stage,
html[data-theme="light"] .pod .vcard,
html[data-theme="light"] .pod .pod-regime-card,
html[data-theme="light"] .pod .pod-gate,
html[data-theme="light"] .pod .pod-equation,
html[data-theme="light"] .pod .pod-mechanism-card {
  background:color-mix(in srgb,var(--panel) 96%,var(--pod-c,var(--pod-blue)));
  border-color:color-mix(in srgb,var(--text) 16%,transparent);
  box-shadow:0 10px 24px -22px color-mix(in srgb,var(--text) 42%,transparent);
}
html[data-theme="light"] .pod .pod-thesis,
html[data-theme="light"] .pod .pquote {
  background:linear-gradient(135deg,
    color-mix(in srgb,var(--pod-blue) 5%,var(--panel)),
    color-mix(in srgb,var(--pod-gold) 6%,var(--panel)));
  box-shadow:0 14px 30px -26px color-mix(in srgb,var(--text) 46%,transparent);
}
html[data-theme="light"] .pod .pod-table {
  background:var(--panel);
}
html[data-theme="light"] .pod .pod-table th {
  background:color-mix(in srgb,var(--panel2) 78%,var(--panel));
  color:color-mix(in srgb,var(--text) 70%,var(--muted));
}
html[data-theme="light"] .pod .pod-table tbody tr:hover td {
  background:color-mix(in srgb,var(--pod-blue) 4%,var(--panel));
}
html[data-theme="light"] .pod .pod-bottom-line {
  background:color-mix(in srgb,var(--pod-teal) 5%,var(--panel));
}
html[data-lang="zh"] .pod .pod-figure {
  letter-spacing:0;
}
html[data-lang="zh"] .pod .pod-figure-head b,
html[data-lang="zh"] .pod .pod-figure-head span,
html[data-lang="zh"] .pod .pod-section-kicker {
  letter-spacing:0;
  text-transform:none;
}

@media(max-width:720px) {
  .pod .statband { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .pod .stat:last-child { grid-column:1 / -1; }
  .pod .pod-intro-grid,
  .pod .pod-split-figure { grid-template-columns:1fr; }
  .pod .pod-loop { grid-template-columns:1fr 1fr; }
  .pod .pod-loop-step { border-bottom:1px solid var(--line); }
  .pod .pod-loop-step:nth-child(2n) { border-right:0; }
  .pod .pod-loop-step::after { display:none; }
  .pod .pod-stage-band,
  .pod .pod-regime-strip { grid-template-columns:1fr; }
  .pod .pod-status-grid,
  .pod .pod-timeline { grid-template-columns:1fr 1fr; }
  .pod .pod-snapshot { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .pod .pod-accounting { grid-template-columns:1fr; }
  .pod .pod-thesis { padding:21px 20px 21px 23px; }
  .pod .pod-thesis p { font-size:17px; }
  .pod .pod-figure { margin-left:-2px; margin-right:-2px; padding:13px 10px 11px; border-radius:14px; }
  .pod .pod-figure-head { align-items:flex-start; flex-direction:column; gap:2px; }
}
@media (max-width:600px) {
  .pod { --pod-body-size:17px; }
  .pod h2 { font-size:22px; line-height:1.28; margin-top:36px; }
  .pod h3 { font-size:17px; line-height:1.38; margin-top:23px; }
  .pod .pod-figure { overflow-x:auto; overscroll-behavior-inline:contain; }
  .pod .pod-figure svg { min-width:820px; }
  .pod .pod-figure-head,
  .pod .pod-figure figcaption { min-width:0; }
  .pod .pod-compact th { font-size:13px; }
  .pod .pod-compact td { font-size:14.5px; }
}
@media(max-width:390px) {
  .pod .pod-status-grid,
  .pod .pod-timeline { grid-template-columns:1fr; }
  .pod .pod-gauge b { font-size:18px; }
  .pod .pod-gauge { padding:10px 9px; }
  .pod .pod-figure { margin-left:-5px; margin-right:-5px; }
}
@media(prefers-reduced-motion:reduce) {
  .pod .pod-reveal,
  .pod .pod-draw,
  .pod .pod-figure [class*="pod-motion-"] {
    opacity:1 !important;
    transform:none !important;
    transition:none !important;
    animation:none !important;
    stroke-dashoffset:0 !important;
  }
  .pod .pod-motion-flow { display:none !important; }
}

rules.new:
/* The Price of Duration — report-scoped editorial and figure system. */
.pod {
  --pod-blue:#5b8def;
  --pod-gold:#d6a84b;
  --pod-teal:#36a995;
  --pod-red:#d85b62;
  --pod-violet:#8f7bd8;
  --pod-ink:var(--text);
  --pod-grid:color-mix(in srgb,var(--line) 72%,transparent);
  --pod-body-size:18px;
  font-size:var(--pod-body-size);
  line-height:1.66;
}
.pod + .disc { display:none; }
.pod > p,
.pod .pod-copy p {
  font-size:var(--pod-body-size);
  line-height:1.66;
  margin:12px 0;
}
.pod h2 {
  font-size:25px;
  line-height:1.24;
  margin-top:44px;
  letter-spacing:-.018em;
}
.pod h3 {
  font-size:18px;
  line-height:1.35;
