/* ===== The Relapse — stat band, evidence chips, odds ledger, buy-list cards, figures ===== */
.rl-acc { --acc:#e0973a; }          /* amber accent — reads on both themes */

/* at-a-glance stat band (reused idiom from The Second Act) */
.statband { display:grid; grid-template-columns:repeat(5,1fr); gap:10px; margin:18px 0 4px; }
.stat { background:var(--panel2); border:1px solid var(--line); border-radius:12px;
        padding:13px 14px; position:relative; overflow:hidden; }
.stat::before { content:""; position:absolute; left:0; top:0; bottom:0; width:3px; background:var(--sc,var(--link)); }
.stat .sv { display:block; font-size:22px; font-weight:750; color:var(--text);
            font-variant-numeric:tabular-nums; letter-spacing:-.01em; line-height:1.05; }
.stat .sv.up { color:#2f9e63; } .stat .sv.dn { color:#d23f3f; }
html[data-theme="dark"] .stat .sv.up { color:#3fc07e; }
html[data-theme="dark"] .stat .sv.dn { color:#ef6a6a; }
.stat .sl { font-size:11px; color:var(--muted); line-height:1.35; margin-top:6px; display:block; }
@media (max-width:720px){ .statband { grid-template-columns:repeat(2,1fr); } }

/* evidence-label chips: [F] fact / [C] consensus / [I] inference / [S] speculation */
sup.ev { display:inline-block; font-size:9px; font-weight:800; line-height:1; padding:2px 4px;
         border-radius:5px; letter-spacing:.02em; margin-left:2px; transform:translateY(-1px); }
.ev-f { color:#2f9e63; background:color-mix(in srgb,#46b87a 14%,transparent); }
.ev-c { color:#4d7fd6; background:color-mix(in srgb,#5b8def 14%,transparent); }
.ev-i { color:#a55fe0; background:color-mix(in srgb,#c77dff 15%,transparent); }
.ev-s { color:#c07f22; background:color-mix(in srgb,#e0973a 17%,transparent); }
html[data-theme="dark"] .ev-f { color:#3fc07e; }
html[data-theme="dark"] .ev-c { color:#7aa7e0; }
html[data-theme="dark"] .ev-i { color:#c77dff; }
html[data-theme="dark"] .ev-s { color:#e0973a; }

/* single-sentence compression pull-quote */
.pquote { position:relative; margin:22px 0 8px; padding:24px 28px; border-radius:18px;
          border:1px solid var(--line); overflow:hidden;
          background:linear-gradient(135deg, color-mix(in srgb,#e0973a 15%,var(--panel)),
                                              color-mix(in srgb,#e0607a 12%,var(--panel))); }
.pquote::before { content:"\201C"; position:absolute; top:-16px; left:16px; font-size:96px; line-height:1;
