#dlg-risk.rkw-ready .rkw-info:hover { color:var(--info); }
#dlg-risk.rkw-ready .rkw-horizons { display:grid; grid-template-columns:repeat(3,1fr); gap:0; border:1px solid var(--rkw-border); background:var(--panel); border-radius:var(--r-ctl,8px); overflow:hidden; margin:10px 0 14px; }
#dlg-risk.rkw-ready .rkw-horizon { background:none; border:0; border-right:1px solid var(--rkw-border); color:var(--muted); min-height:40px; font-size:var(--fs-sm); font-weight:550; cursor:pointer; transition:background 180ms ease,color 180ms ease; }
#dlg-risk.rkw-ready .rkw-horizon:last-child { border-right:0; }
#dlg-risk.rkw-ready .rkw-horizon[aria-pressed="true"] { background:var(--panel2); color:var(--text); font-weight:650; }
#dlg-risk.rkw-ready .rkw-odds-reading { display:flex; align-items:baseline; flex-wrap:wrap; gap:10px; }
#dlg-risk.rkw-ready .rkw-probability { font-size:var(--fs-num-xl); font-weight:700; line-height:1.05; letter-spacing:-.04em; font-variant-numeric:tabular-nums; }
#dlg-risk.rkw-ready .rkw-probability-caption { font-size:var(--fs-sm); color:var(--muted); max-width:18ch; line-height:1.4; }
#dlg-risk.rkw-ready .rkw-probability-track { height:6px; margin-top:14px; border-radius:var(--r-pill,999px); background:var(--panel2); position:relative; }
#dlg-risk.rkw-ready .rkw-probability-fill { height:100%; display:block; width:0; background:var(--rkw-accent); border-radius:inherit; transition:width 200ms ease; }
#dlg-risk.rkw-ready .rkw-baseline-marker { position:absolute; top:-4px; height:14px; width:2px; background:var(--text); border:1px solid var(--panel); box-sizing:content-box; transform:translateX(-50%); }
#dlg-risk.rkw-ready .rkw-probability-scale { display:flex; justify-content:space-between; color:var(--muted); font-size:var(--fs-micro); margin-top:5px; }
#dlg-risk.rkw-ready .rkw-horizon-value { display:flex; flex-direction:column; gap:3px; min-width:0; }
#dlg-risk.rkw-ready .rkw-odds-footer { display:flex; align-items:center; flex-wrap:wrap; gap:4px 10px; justify-content:space-between; margin-top:12px; min-height:32px; }
#dlg-risk.rkw-ready .rkw-baseline { font-size:var(--fs-sm); color:var(--muted); font-variant-numeric:tabular-nums; }
#dlg-risk.rkw-ready .rkw-quality { border:0; background:var(--panel2); color:var(--muted); border-radius:var(--r-ctl,8px); padding:6px 8px; font-size:var(--fs-label); cursor:pointer; min-height:32px; text-align:left; }
#dlg-risk.rkw-ready .rkw-quality.is-thin { color:var(--ink-warn); background:var(--surface-warn-subtle); }

/* ── Compact completeness and source-session context, visible at first scan ── */
#dlg-risk.rkw-ready .rkw-completeness {
  display:flex; align-items:center; flex-wrap:wrap; gap:6px 12px;
  margin:14px 0 0; padding:10px 0 0; border-top:1px solid var(--rkw-border);
  font-size:var(--fs-sm); color:var(--muted);
}
