#dlg-risk.rkw-ready .rkw-completeness-session { color:var(--muted); font-variant-numeric:tabular-nums; }

/* ── Driver map: connected cells, semantic dots, no floating cards ── */
#dlg-risk.rkw-ready .rkw-section-heading { display:flex; justify-content:space-between; align-items:baseline; gap:8px; margin:22px 0 10px; }
#dlg-risk.rkw-ready .rkw-section-heading h3 { font-size:var(--fs-label); font-weight:700; margin:0; letter-spacing:.07em; text-transform:uppercase; color:var(--text); }
#dlg-risk.rkw-ready .rkw-section-hint { color:var(--muted); font-size:var(--fs-label); }
#dlg-risk.rkw-ready .rkw-driver-grid {
  display:grid; grid-template-columns:repeat(4,minmax(0,1fr));
  border:1px solid var(--rkw-border); border-radius:var(--r-card,12px);
  overflow:hidden; background:var(--panel);
}
#dlg-risk.rkw-ready .rkw-driver {
  display:flex; flex-direction:column; align-items:flex-start; gap:6px;
  text-align:left; min-width:0; min-height:116px; padding:13px 15px;
  position:relative; border:0; border-right:1px solid var(--rkw-border);
