#dlg-risk.rkw-ready .rkw-driver-top { display:flex; align-items:center; gap:8px; width:100%; padding-right:26px; }
#dlg-risk.rkw-ready .rkw-driver-dot { width:7px; height:7px; border-radius:var(--r-pill,999px); background:var(--rkc-c,var(--muted)); flex:none; }
#dlg-risk.rkw-ready .rkw-driver-label { font-size:var(--fs-label); color:var(--muted); font-weight:700; letter-spacing:.05em; text-transform:uppercase; }
#dlg-risk.rkw-ready .rkw-driver-state { font-size:var(--fs-sm); color:var(--text); font-weight:550; line-height:1.45; }
#dlg-risk.rkw-ready .rkw-driver > .rkw-arrow { position:absolute; top:13px; right:13px; margin-left:0; font-size:var(--fs-body); }
/* The native isle/pressure marks drive the dot and the source's own badge. */
#dlg-risk.rkw-ready .rkw-driver[data-isle="risk"] { --rkc-c:var(--isle-risk); }
#dlg-risk.rkw-ready .rkw-driver[data-isle="events"] { --rkc-c:var(--isle-events); }
