#dlg-risk.rkw-ready .rkw-driver[data-isle="news"] { --rkc-c:var(--isle-news); }
#dlg-risk.rkw-ready .rkw-driver[data-pressure="high"] { --rkc-c:var(--act); }
#dlg-risk.rkw-ready .rkw-driver[data-pressure="moderate"] { --rkc-c:var(--warn); }
#dlg-risk.rkw-ready .rkw-driver[data-pressure="low"] { --rkc-c:var(--ok); }
#dlg-risk.rkw-ready .rkw-driver[data-missing] .rkw-driver-dot { background:var(--muted); }
#dlg-risk.rkw-ready .rkw-driver[data-missing] .rkw-driver-state { color:var(--muted); font-weight:450; }
/* The strip clips its own overflow, so the focus ring is drawn inside the cell. */
#dlg-risk.rkw-ready .rkw-driver:focus-visible { outline:2px solid var(--info); outline-offset:-3px; }

/* ── Analytical band: native driver ladder beside the canonical envelope ── */
#dlg-risk.rkw-ready .rkw-analytical {
  display:grid; grid-template-columns:minmax(0,1.45fr) minmax(300px,1fr);
  gap:0; margin-top:var(--sp-5,20px); border-top:1px solid var(--rkw-border);
}
