#dlg-risk.rkw-ready .rkw-panel-heading { display:flex; align-items:baseline; justify-content:space-between; gap:10px; margin:16px 0 10px; }
#dlg-risk.rkw-ready .rkw-panel-heading h3 { font-size:var(--fs-label); font-weight:700; margin:0; letter-spacing:.07em; text-transform:uppercase; color:var(--text); }
#dlg-risk.rkw-ready .rkw-panel-hint { color:var(--muted); font-size:var(--fs-label); }
#dlg-risk.rkw-ready .rkw-sentiment-panel,
#dlg-risk.rkw-ready .rkw-leadership-panel { margin-top:var(--sp-5,20px); padding-top:var(--sp-4,16px); border-top:1px solid var(--rkw-border); }

/* ── Footer: method access and the scale disclaimer ── */
#dlg-risk.rkw-ready .rkw-foot {
  display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap;
  gap:10px 20px; margin-top:var(--sp-5,20px); padding-top:var(--sp-4,16px);
  border-top:1px solid var(--rkw-border);
}
#dlg-risk.rkw-ready .rkw-foot-note { font-size:var(--fs-sm); color:var(--muted); margin:0; max-width:56ch; line-height:1.5; }
#dlg-risk.rkw-ready .rkw-explore { display:flex; flex-wrap:wrap; gap:6px; margin:0; padding:0; border:0; }
#dlg-risk.rkw-ready .rkw-explore button { display:flex; align-items:center; gap:7px; border:1px solid var(--rkw-border); background:none; color:var(--muted); min-height:40px; font-size:var(--fs-sm); padding:6px 10px; cursor:pointer; border-radius:var(--r-ctl,8px); text-align:left; }
#dlg-risk.rkw-ready .rkw-explore button:hover { color:var(--text); background:var(--panel2); }
#dlg-risk.rkw-ready .rkw-explore-icon { font-size:var(--fs-body); color:var(--muted); }
#dlg-risk.rkw-ready .rkw-count { background:var(--panel2); font-size:var(--fs-label); border-radius:var(--r-ctl,8px); padding:2px 5px; }

/* ── Inspector: full width on every size, so nothing is squeezed ── */
#dlg-risk.rkw-ready .rkw-inspector { min-width:0; background:var(--panel); border-left:1px solid var(--rkw-border); padding:20px 24px 24px; animation:rkw-reveal 200ms ease both; }
