#dlg-risk.rkw-ready .rkw-back,
#dlg-risk.rkw-ready .rkw-inspector-next button { display:flex; align-items:center; gap:8px; background:none; border:0; color:var(--muted); font-size:var(--fs-sm); padding:6px 0; min-height:44px; cursor:pointer; }
