#dlg-risk.rkw-ready .riskdlg-scare .sc-band-calm { color:var(--ink-ok); }
#dlg-risk.rkw-ready .riskdlg-scare[data-band="sc-band-high"] .sc-bar-fill { background:var(--act) !important; }
