#dlg-risk.rkw-ready .riskdlg-scare[data-reading-state="UNAVAILABLE"] .sc-bar-track { background:repeating-linear-gradient(90deg,var(--line) 0,var(--line) 3px,transparent 3px,transparent 7px); }
#dlg-risk.rkw-ready .gde-disc { margin:0; }
#dlg-risk.rkw-ready .rkw-inspector-content > .gde-disc > summary { display:none; }
#dlg-risk.rkw-ready .gde-disc-body { padding:0; }
#dlg-risk.rkw-ready .gde-tblwrap { overflow:auto; }
#dlg-risk.rkw-ready .gde-tbl { min-width:370px; font-size:var(--fs-sm); }
#dlg-risk.rkw-ready .gde-receipt { overflow-wrap:anywhere; font-size:var(--fs-label); color:var(--muted); }
#dlg-risk.rkw-ready .rkw-odds-table { display:grid; gap:14px; }
#dlg-risk.rkw-ready .rkw-odds-row { padding:14px; border:1px solid var(--rkw-border); border-radius:var(--r-ctl,8px); background:var(--bg); }
#dlg-risk.rkw-ready .rkw-odds-row-head { display:flex; align-items:baseline; justify-content:space-between; gap:10px; }
#dlg-risk.rkw-ready .rkw-odds-row strong { font-size:var(--fs-num-lg); font-variant-numeric:tabular-nums; }
#dlg-risk.rkw-ready .rkw-odds-row-label { color:var(--muted); font-size:var(--fs-sm); }
#dlg-risk.rkw-ready .rkw-odds-evidence { color:var(--muted); font-size:var(--fs-sm); line-height:1.5; margin-top:12px; }
#dlg-risk.rkw-ready .rkw-odds-row.is-selected { border-color:var(--rkw-accent); }
#dlg-risk.rkw-ready .rkw-empty { padding:16px; color:var(--muted); font-size:var(--fs-body); line-height:1.6; background:var(--panel2); border-radius:var(--r-ctl,8px); }

