#dlg-risk.rkw-ready .gde-q { font-size:var(--fs-micro); color:var(--muted); font-weight:650; letter-spacing:.06em; text-transform:uppercase; }
#dlg-risk.rkw-ready .gde-a { font-size:var(--fs-body); font-weight:650; color:var(--text); }
#dlg-risk.rkw-ready #risk-envelope-band > p,
#dlg-risk.rkw-ready #risk-envelope-band > .gde-meta,
