#dlg-risk.rkw-ready #risk-envelope-band > .gde-causes { font-size:var(--fs-sm); color:var(--text); }
#dlg-risk.rkw-ready .gde-meta { gap:8px 14px; font-size:var(--fs-label); color:var(--muted); display:flex; flex-wrap:wrap; }
#dlg-risk.rkw-ready .gde-live-reading { padding:10px; border-radius:var(--r-ctl,8px); background:var(--panel2); }
#dlg-risk.rkw-ready .rkw-source-link { justify-self:start; border:0; background:none; color:var(--muted); padding:4px 0; min-height:32px; font-size:var(--fs-label); cursor:pointer; display:flex; gap:8px; align-items:center; }
