#dlg-risk.rkw-ready .rkw-odds-block > .rkw-probability-track,
#dlg-risk.rkw-ready .rkw-odds-block > .rkw-probability-scale { display:none; }
#dlg-risk.rkw-ready .rkw-primary { display:inline-flex; align-items:center; gap:var(--sp-3,12px); min-height:44px; margin-top:var(--sp-4,16px); padding:var(--sp-2,8px) var(--sp-4,16px); border:1px solid var(--rkw-border); border-radius:var(--r-ctl,8px); background:var(--panel); color:var(--text); font-size:var(--fs-sm); font-weight:600; cursor:pointer; }
#dlg-risk.rkw-ready .rkw-reading-caveat { flex-basis:100%; color:var(--ink-warn); line-height:1.45; }
#dlg-risk.rkw-ready .rkw-completeness-scope { font-weight:600; }
#dlg-risk.rkw-ready .riskdlg-scare[data-band="sc-band-high"] .sc-score { color:var(--ink-act) !important; }
#dlg-risk.rkw-ready .rkw-source-link { min-height:40px; }

/* Dense native analytical sections follow the same Paper surface hierarchy. */
#dlg-risk.rkw-ready .riskdlg-scare-list.scare-ladder,
#dlg-risk.rkw-ready #sentiment-regime,
#dlg-risk.rkw-ready .rsx-leaders { padding:0; border:0; border-radius:0; background:none; box-shadow:none; }
#dlg-risk.rkw-ready .rkc-mood-board { gap:var(--sp-6,24px); margin-top:var(--sp-3,12px); }
#dlg-risk.rkw-ready .rkc-mood-lens { padding:0; border:0; border-radius:0; background:none; box-shadow:none; }
#dlg-risk.rkw-ready .rkc-mood-mini-track { height:6px; border:1px solid var(--line); border-radius:var(--r-pill,999px); background:var(--panel2); }
#dlg-risk.rkw-ready .rkc-mood-pin { width:10px; height:10px; border:2px solid var(--bg); border-radius:var(--r-pill,999px); background:var(--text); box-shadow:none; transition:none; }
#dlg-risk.rkw-ready .rkc-mood-axis { color:var(--muted); font-size:var(--fs-micro); margin-top:var(--sp-2,8px); }
#dlg-risk.rkw-ready .rkc-mood-score { color:var(--text); font-size:var(--fs-num-lg); }
#dlg-risk.rkw-ready .rkc-mood-lens-name { color:var(--muted); }
#dlg-risk.rkw-ready .riskdlg-damage-label { display:block; color:var(--muted); font-size:var(--fs-label); font-weight:650; margin-bottom:var(--sp-2,8px); }
#dlg-risk.rkw-ready .riskdlg-damage-reading { display:block; color:var(--text); font-size:var(--fs-num-lg); font-weight:700; line-height:1.3; }
#dlg-risk.rkw-ready #riskdlg-damage-more > summary { min-height:44px; display:grid; grid-template-columns:1em minmax(0,1fr); align-items:start; column-gap:var(--sp-2,8px); row-gap:var(--sp-1,4px); }
#dlg-risk.rkw-ready #riskdlg-damage-more > summary::before { grid-column:1; grid-row:1 / span 2; }
#dlg-risk.rkw-ready #riskdlg-damage-more > summary > span { grid-column:2; }
#dlg-risk.rkw-ready #riskdlg-damage-more > summary .riskdlg-damage-label { margin:0; }
#dlg-risk.rkw-ready .rsx-leaders { display:flex; flex-direction:column; }
#dlg-risk.rkw-ready .rsx-leaders > #riskdlg-damage-more { order:1; }
#dlg-risk.rkw-ready .rsx-leaders > .riskdlg-ldr-caveat { order:2; }
#dlg-risk.rkw-ready .rkw-overview .rkc-rot-head { display:none; }
@media (min-width:901px) {
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare { grid-template-columns:minmax(180px,1.4fr) minmax(60px,1fr) 44px 72px; align-items:center; gap:var(--sp-3,12px); padding:var(--sp-2,8px) 0; }
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare .rkc-sc-ico,
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare .sc-name > div { display:none; }
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare .sc-name { grid-column:1; grid-row:1; line-height:1.35; }
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare .sc-bar-track { grid-column:2; grid-row:1; height:4px; }
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare .sc-score { grid-column:3; grid-row:1; text-align:right; font-size:var(--fs-sm); }
  #dlg-risk.rkw-ready .rkw-overview .riskdlg-scare .sc-band { grid-column:4; grid-row:1; text-align:right; border:0; font-size:var(--fs-micro); }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders { display:grid; grid-template-columns:minmax(0,1.45fr) minmax(260px,1fr); column-gap:var(--sp-6,24px); align-items:start; }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders > .riskdlg-rot { grid-column:1; grid-row:1 / span 2; }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders > .rkc-ldr-sub { grid-column:1; grid-row:3; }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders > #riskdlg-damage-more { grid-column:2; grid-row:1 / span 2; padding:0 0 0 var(--sp-6,24px); margin:0; border:0; border-left:1px solid var(--rkw-border); }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders > .riskdlg-ldr-caveat { grid-column:2; grid-row:3; padding-left:var(--sp-6,24px); }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders:not(:has(.riskdlg-rot)),
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders:not(:has(#riskdlg-damage-more)) { display:block; }
  #dlg-risk.rkw-ready .rkw-overview .rsx-leaders:not(:has(.riskdlg-rot)) > #riskdlg-damage-more,
