rules.new:
/* Risk Radar workspace — the Macro theme owns all colors and typography.
   Scope is deliberately limited to the progressively enhanced US dialog.

   Paper parity: the overview is one continuous instrument panel. Regions are
   separated by neutral rules rather than by a farm of bordered cards, the
   driver map is a connected strip of cells with semantic dots, and every
   surface uses the governed --bg/--panel/--panel2/--line tokens. No coloured
   edge stripe, gradient or runtime stylesheet is introduced here. */
#dlg-risk.rkw-ready {
  --rkw-accent: var(--warn);
  --rkw-border: var(--line);
  --rkw-soft: var(--panel2);
  --lens-bg: var(--panel); --lens-ink: var(--text); --lens-muted: var(--muted);
  --lens-line: var(--line);
}
#dlg-risk.rkw-ready[data-rkw-state="calm"] { --rkw-accent:var(--ok); }
#dlg-risk.rkw-ready[data-rkw-state="risk-off"],
#dlg-risk.rkw-ready[data-rkw-state="elevated"] { --rkw-accent:var(--act); }
#dlg-risk.rkw-ready[data-rkw-state="unknown"],
#dlg-risk.rkw-ready[data-rkw-state="none"] { --rkw-accent:var(--muted); }
#dlg-risk.rkw-ready [hidden] { display:none !important; }
#dlg-risk.rkw-ready .mx5-dlg-panel {
  width:min(1180px, calc(100vw - 48px)); max-width:1280px;
  max-height:min(940px, calc(100dvh - 48px));
  border:1px solid var(--rkw-border); border-radius:var(--r-card,12px);
  background:var(--bg); overflow:hidden;
  box-shadow:var(--glass-shadow);
}
#dlg-risk.rkw-ready.rkw-detail-open .mx5-dlg-panel { width:min(1180px, calc(100vw - 48px)); }
#dlg-risk.rkw-ready .mx5-dlg-header {
  padding:var(--sp-4,16px) var(--sp-6,24px); background:var(--panel);
  border-bottom:1px solid var(--rkw-border); min-height:70px; flex-shrink:0;
}
#dlg-risk.rkw-ready .mx5-dlg-title { font-size:var(--fs-h2); gap:12px; flex-wrap:wrap; }
#dlg-risk.rkw-ready .riskdlg-asof { font-size:var(--fs-sm); font-weight:450; color:var(--muted); letter-spacing:0; }
#dlg-risk.rkw-ready .rkw-scope { color:var(--muted); font-size:var(--fs-sm); font-weight:450; padding-left:12px; border-left:1px solid var(--line); }
#dlg-risk.rkw-ready .mx5-dlg-close { width:44px; height:44px; border-radius:var(--r-ctl,8px); color:var(--muted); flex:none; }
#dlg-risk.rkw-ready .mx5-dlg-close:hover { color:var(--text); background:var(--panel2); }
#dlg-risk.rkw-ready .mx5-dlg-body { padding:0; overflow:auto; overscroll-behavior:contain; scroll-behavior:auto; scrollbar-gutter:stable; }
#dlg-risk.rkw-ready button, #dlg-risk.rkw-ready summary { -webkit-tap-highlight-color:transparent; }
#dlg-risk.rkw-ready button { font-family:var(--font-ui); }
#dlg-risk.rkw-ready button:focus-visible,
#dlg-risk.rkw-ready summary:focus-visible,
#dlg-risk.rkw-ready a:focus-visible { outline:2px solid var(--info); outline-offset:3px; }
#dlg-risk.rkw-ready button { touch-action:manipulation; }
#dlg-risk.rkw-ready .rkw-layout { display:grid; grid-template-columns:minmax(0,1fr); min-width:0; }
#dlg-risk.rkw-ready .rkw-overview { min-width:0; padding:var(--sp-5,20px) var(--sp-6,24px) var(--sp-6,24px); }

/* ── Hero: reading on the left, independent index and odds on the right ── */
#dlg-risk.rkw-ready .rkw-hero {
  display:grid; grid-template-columns:minmax(0,1fr) minmax(300px,360px);
  gap:0; align-items:start;
}
#dlg-risk.rkw-ready .rkw-read { min-width:0; padding:0 var(--sp-6,24px) 0 0; }
#dlg-risk.rkw-ready .rkw-odds {
  min-width:0; border-left:1px solid var(--rkw-border);
  padding:0 0 0 var(--sp-6,24px);
  display:flex; flex-direction:column; gap:var(--sp-4,16px);
}
#dlg-risk.rkw-ready .rkw-eyebrow { font-size:var(--fs-label); color:var(--muted); font-weight:650; letter-spacing:.09em; text-transform:uppercase; line-height:1.5; }
#dlg-risk.rkw-ready .rkw-state-slot { margin:8px 0 6px; }
#dlg-risk.rkw-ready .riskdlg-state { background:none; border:0; padding:0; color:var(--rkw-accent); font-size:var(--fs-display); font-weight:650; line-height:1.04; letter-spacing:-.045em; text-transform:none; }
#dlg-risk.rkw-ready .riskdlg-domain { font-size:var(--fs-md); line-height:1.45; color:var(--text); margin:0; font-weight:500; }
#dlg-risk.rkw-ready .rkw-stance { display:flex; align-items:flex-start; gap:10px; margin-top:18px; padding-top:14px; border-top:1px solid var(--rkw-border); }
#dlg-risk.rkw-ready .rkw-stance-icon { flex:none; font-size:var(--fs-num-lg); color:var(--rkw-accent); line-height:1; padding-top:2px; }
#dlg-risk.rkw-ready .rkw-stance > div { min-width:0; }
#dlg-risk.rkw-ready .rkw-label { display:block; font-size:var(--fs-label); color:var(--muted); line-height:1.5; margin-bottom:4px; }
#dlg-risk.rkw-ready .riskdlg-stance { font-size:var(--fs-body); color:var(--text); line-height:1.55; margin:0; max-width:48ch; font-weight:550; }
#dlg-risk.rkw-ready .riskdlg-authority { margin-top:12px; color:var(--ink-warn); font-size:var(--fs-sm); }

/* ── Signal index: an own-scale pressure reading, explicitly not a probability ── */
#dlg-risk.rkw-ready .rkw-index-block { border-bottom:1px solid var(--rkw-border); padding-bottom:14px; }
#dlg-risk.rkw-ready .rkw-index {
  display:grid; grid-template-columns:minmax(0,1fr) auto;
  grid-template-areas:"label label" "score arrow" "meter meter";
  gap:6px 10px; width:100%; background:none; border:0; color:var(--text);
  padding:0; text-align:left; cursor:pointer; min-height:44px;
}
#dlg-risk.rkw-ready .rkw-index-label { grid-area:label; font-size:var(--fs-label); color:var(--muted); font-weight:650; letter-spacing:.07em; text-transform:uppercase; }
#dlg-risk.rkw-ready .rkw-score-slot { grid-area:score; min-width:0; }
#dlg-risk.rkw-ready .rkw-index .riskdlg-score { font-size:var(--fs-num-xl); font-weight:700; color:var(--text); letter-spacing:-.04em; line-height:1.05; }
#dlg-risk.rkw-ready .rkw-index .riskdlg-score small { color:var(--muted); font-size:var(--fs-sm); font-weight:450; }
#dlg-risk.rkw-ready .rkw-index .rkw-arrow { grid-area:arrow; align-self:center; margin-left:0; }
#dlg-risk.rkw-ready .rkw-index-meter { grid-area:meter; height:4px; border-radius:var(--r-pill,999px); background:var(--panel2); overflow:hidden; }
#dlg-risk.rkw-ready .rkw-index-meter-fill { display:block; height:100%; width:0; background:var(--info); border-radius:inherit; }
#dlg-risk.rkw-ready .rkw-index:hover .rkw-index-label { color:var(--text); }

/* ── SPY ≥5% pullback estimate: horizon controls, matched baseline and history ── */
#dlg-risk.rkw-ready .rkw-odds-block { display:flex; flex-direction:column; min-width:0; }
#dlg-risk.rkw-ready .rkw-odds-heading { display:flex; align-items:center; flex-wrap:wrap; justify-content:space-between; gap:2px 10px; }
