/* ── Driver map: connected cells, semantic dots, no floating cards ── */
#dlg-risk.rkw-ready .rkw-section-heading { display:flex; justify-content:space-between; align-items:baseline; gap:8px; margin:22px 0 10px; }
#dlg-risk.rkw-ready .rkw-section-heading h3 { font-size:var(--fs-label); font-weight:700; margin:0; letter-spacing:.07em; text-transform:uppercase; color:var(--text); }
