/* The strip clips its own overflow, so the focus ring is drawn inside the cell. */
#dlg-risk.rkw-ready .rkw-driver:focus-visible { outline:2px solid var(--info); outline-offset:-3px; }

/* ── Analytical band: native driver ladder beside the canonical envelope ── */
#dlg-risk.rkw-ready .rkw-analytical {
