#dlg-risk.rkw-ready .rkw-explore { display:flex; flex-wrap:wrap; gap:6px; margin:0; padding:0; border:0; }
#dlg-risk.rkw-ready .rkw-explore button { display:flex; align-items:center; gap:7px; border:1px solid var(--rkw-border); background:none; color:var(--muted); min-height:40px; font-size:var(--fs-sm); padding:6px 10px; cursor:pointer; border-radius:var(--r-ctl,8px); text-align:left; }
#dlg-risk.rkw-ready .rkw-explore button:hover { color:var(--text); background:var(--panel2); }
