#dlg-risk.rkw-ready .rkw-inspector-next button:hover { color:var(--info); }
#dlg-risk.rkw-ready .rkw-step { color:var(--muted); font-size:var(--fs-label); font-variant-numeric:tabular-nums; }
#dlg-risk.rkw-ready .rkw-inspector-heading h2 { font-size:var(--fs-h1); font-weight:600; line-height:1.15; letter-spacing:-.03em; margin:8px 0 10px; color:var(--text); }
