#dlg-risk.rkw-ready .rkw-context-nav button[aria-pressed="true"] { background:var(--panel2); border-color:var(--line); color:var(--text); }
#dlg-risk.rkw-ready .rkw-inspector-content { min-width:0; overflow-wrap:anywhere; }
#dlg-risk.rkw-ready .rkw-inspector-content > * { animation:rkw-reveal 180ms ease both; }
#dlg-risk.rkw-ready .rkw-inspector-content .lens-hd { display:none; }
#dlg-risk.rkw-ready .rkw-evidence-card { display:block; color:var(--text); }
#dlg-risk.rkw-ready .rlx-viz { margin:0 0 20px; padding:16px; border:1px solid var(--rkw-border); border-radius:var(--r-card,12px); background:var(--bg); }
#dlg-risk.rkw-ready .rlx-bar-row { display:grid; grid-template-columns:minmax(0,1fr); gap:8px; margin-bottom:15px; }
#dlg-risk.rkw-ready .rlx-bar-lbl { max-width:none; width:auto; font-size:var(--fs-sm); }
#dlg-risk.rkw-ready .rlx-bar-track { height:8px; background:var(--panel2); border-radius:var(--r-pill,999px); overflow:hidden; display:block; }
#dlg-risk.rkw-ready .rlx-bar-fill { display:block; width:var(--rlx-w,0); height:100%; border-radius:inherit; background:var(--warn); }
#dlg-risk.rkw-ready .rlx-bar-fill.muted { background:var(--muted); opacity:.65; }
#dlg-risk.rkw-ready .rlx-viz-cap { color:var(--muted); font-size:var(--fs-sm); line-height:1.5; margin-top:12px; }
#dlg-risk.rkw-ready .rlx-rows { display:block; }
#dlg-risk.rkw-ready .rlx-row { display:block; border-top:1px solid var(--rkw-border); padding:12px 0; }
#dlg-risk.rkw-ready .rlx-k { display:block; width:auto; color:var(--muted); font-size:var(--fs-label); margin-bottom:5px; }
#dlg-risk.rkw-ready .rlx-v { display:block; color:var(--text); font-size:var(--fs-body); line-height:1.55; }
#dlg-risk.rkw-ready .rlx-chips { display:flex; flex-wrap:wrap; gap:6px; margin:12px 0; }
#dlg-risk.rkw-ready .rlx-chip { color:var(--muted); background:var(--panel2); border:1px solid var(--rkw-border); border-radius:var(--r-ctl,8px); font-size:var(--fs-label); padding:5px 8px; }
