#dlg-risk.rkw-ready .rkw-source-link { justify-self:start; border:0; background:none; color:var(--muted); padding:4px 0; min-height:32px; font-size:var(--fs-label); cursor:pointer; display:flex; gap:8px; align-items:center; }
#dlg-risk.rkw-ready .rkw-source-link:hover { color:var(--info); }

@keyframes rkw-reveal { from { opacity:0; transform:translateY(5px); } to { opacity:1; transform:translateY(0); } }

@media (max-width:900px) {
  #dlg-risk.rkw-ready .rkw-hero { grid-template-columns:minmax(0,1fr); gap:var(--sp-4,16px); }
