  .chip2.xsr-fast.muted { color: var(--muted); }
  /* XSR-W1b: fast-tape rail — ordinal + plain-word state, co-equal with conviction */
  .ft-rail { display: flex; align-items: baseline; gap: 7px; margin: 7px 0 4px; padding: 6px 9px;
