.sleeve-strategy-card .sc-sub { font-size:12px; color:var(--muted); margin:0 0 8px; line-height:1.5; max-width:64ch; }
.sleeve-strategy-card .sc-stats { display:flex; flex-wrap:wrap; gap:6px; margin:6px 0; }
.sleeve-strategy-card .sc-stat { font-size:11.5px; color:var(--muted); padding:3px 9px;
  border:1px solid var(--line); border-radius:7px; background:var(--bg); }
.sleeve-strategy-card .sc-stat b { color:var(--text); font-variant-numeric:tabular-nums; }
.sleeve-strategy-card .sc-link { display:inline-block; font-size:12.5px; font-weight:650;
  color:var(--ink-up, var(--up)); text-decoration:none; margin-top:6px; }
.sleeve-strategy-card .sc-link:hover { text-decoration:underline; }
.sleeve-strategy-card .sc-note { font-size:11px; color:var(--muted); margin:5px 0 0; }
.sleeve-strategy-card .sc-tag { display:inline-block; font-size:10.5px; font-weight:700;
  letter-spacing:.04em; border:1px solid var(--line); border-radius:5px; padding:1px 6px;
  color:var(--muted); margin-right:6px; vertical-align:2px; }
/* ---- cross-market AI-semis confirmer chip (lite/THS page; display-only) ---- */
.semis-chip { display:flex; flex-wrap:wrap; align-items:baseline; gap:6px 10px; background:var(--panel2);
  border:1px solid var(--line); border-radius:9px; padding:8px 12px; margin:10px 0 0; font-size:12.5px; }
.semis-chip .sx-tag { font-size:10.5px; color:var(--muted); font-style:italic; }
.semis-badge { display:inline-block; font-size:10px; font-weight:650; border:1px solid var(--line);
  border-radius:6px; padding:0 6px; margin-left:6px; color:var(--muted); vertical-align:1px; }
.semis-badge.on { color:var(--ink-up, var(--up)); border-color:color-mix(in srgb, var(--up) 40%, var(--line)); }
/* ---- score badge ---- */
/* Chip TEXT moved off the dark-tuned Tailwind literals and onto the estate ink
   rungs (2026-08-12): #4ade80 measured 1.74:1 and #f87171 2.6:1 on the light
   panels. The tint and border keep the literal — they are non-text and clear
   the 3:1 boundary floor — so only the ink changes. */
.score-badge { display:inline-flex; align-items:center; gap:3px; font-size:11px; font-weight:700;
  padding:1px 7px; border-radius:7px; border:1px solid var(--line); font-variant-numeric:tabular-nums;
  vertical-align:1px; margin-left:6px; }
.score-badge.strong { color:var(--ink-up, var(--up)); border-color:color-mix(in srgb,#4ade80 40%,var(--line)); background:color-mix(in srgb,#4ade80 8%,transparent); }
.score-badge.neutral { color:var(--muted); border-color:var(--line); }
.score-badge.weak { color:var(--ink-down, var(--down)); border-color:color-mix(in srgb,#f87171 40%,var(--line)); background:color-mix(in srgb,#f87171 8%,transparent); }
/* ---- turn-state chip ---- */
.turn-chip { display:inline-block; font-size:10.5px; font-weight:600; padding:1px 6px; border-radius:6px;
  border:1px solid var(--line); margin-left:5px; vertical-align:1px; }
.turn-chip.washed_out { color:var(--ink-info, var(--info)); border-color:color-mix(in srgb,#60a5fa 40%,var(--line)); }
.turn-chip.basing     { color:var(--ink-warn, var(--warn)); border-color:color-mix(in srgb,#facc15 40%,var(--line)); }
.turn-chip.turning    { color:var(--ink-warn, var(--warn)); border-color:color-mix(in srgb,#fb923c 40%,var(--line)); }
.turn-chip.confirmed  { color:var(--ink-up, var(--up)); border-color:color-mix(in srgb,#4ade80 40%,var(--line)); }
/* ---- signal tier chip ---- */
.sig-fresh { color:var(--ink-ok, var(--ok)); font-size:8px; vertical-align:middle; margin-left:2px; }
.sig-chip { display:inline-block; font-size:10px; font-weight:700; padding:0 5px;
  border-radius:5px; vertical-align:1px; color:var(--ink-up, var(--up));
  border:1px solid color-mix(in srgb,var(--up) 40%,var(--line)); margin-left:4px; }
/* ---- entry radar strip ---- */
.entry-radar { background:var(--panel); border:1px solid var(--line); 
  border-radius:10px; padding:12px 15px; margin:0 0 20px; }
.entry-radar .er-head { font-size:14px; font-weight:700; margin:0 0 2px; display:flex; align-items:center; gap:8px; }
.entry-radar .er-sub { font-size:12px; color:var(--muted); margin:0 0 10px; line-height:1.5; }
.entry-radar .er-items { display:flex; flex-direction:column; gap:7px; }
.entry-radar .er-item { display:flex; flex-wrap:wrap; align-items:center; gap:6px 10px; font-size:13px; }
.entry-radar .er-reco { font-size:11px; color:var(--muted); }
.entry-radar .er-note { font-size:11px; color:var(--muted); margin-top:8px; line-height:1.5; border-top:1px solid var(--line); padding-top:7px; }
.entry-radar .er-empty { color:var(--muted); font-size:12.5px; font-style:italic; padding:4px 0; }
/* ---- overlap chips ---- */
.overlap-row { margin:6px 0 2px; display:flex; flex-wrap:wrap; gap:5px; align-items:center; font-size:11.5px; }
.overlap-chip { display:inline-block; padding:1px 8px; border:1px solid var(--line); border-radius:7px;
  background:var(--panel2); font-size:11px; cursor:pointer; color:inherit; }
.overlap-chip:hover { border-color:var(--muted); }

/* ── Theme-context chip family (retained from the aurora-glass hero the rvx hero
     replaced): the What-changed strip, the client-injected policy-lever chip and the
     strength/breaking chips all still draw from it. The glass panel + drifting aurora
     blobs that used to wrap them are gone with the hero markup — the page-level
     .rvx-aurora backdrop and the hero's own radial wash do that work now. ── */
.tc-chips { display:flex; flex-wrap:wrap; gap:6px; margin:8px 0 4px; }
.tc-chip { display:inline-flex; align-items:center; gap:5px; font-size:11.5px; padding:3px 9px;
  border-radius:20px; border:1px solid; white-space:nowrap; text-decoration:none; color:inherit; }
.tc-chip:hover { opacity:.85; }
.tc-chip.up  { background:rgba(74,222,128,.12); border-color:rgba(74,222,128,.35); color:var(--ink-up, var(--up)); }
.tc-chip.dn  { background:rgba(248,113,113,.10); border-color:rgba(248,113,113,.30); color:var(--ink-down, var(--down)); }
.tc-chip.was1{ font-size:9.5px; padding:0 5px; opacity:.75; border-radius:5px; margin-left:3px;
               background:rgba(248,113,113,.08); border-color:rgba(248,113,113,.25); color:var(--ink-down, var(--down)); }
.tc-chip.mig { background:rgba(93,139,255,.10); border-color:rgba(93,139,255,.25); color:var(--ink-link, var(--link)); }
.tc-chip.aln { background:rgba(74,222,128,.08); border-color:rgba(74,222,128,.25); color:var(--ink-up, var(--up)); }
.tc-chip.rcpt{ background:var(--panel2); border-color:var(--line); color:var(--muted); }
.tc-receipt-tip { cursor:default; }
.tc-days  { font-size:11px; color:var(--muted); align-self:center; }
.tc-pb-link { display:inline-flex; align-items:center; gap:4px; font-size:12px; color:var(--ink-link, var(--link));
  border:1px solid var(--line); border-radius:20px; padding:3px 10px; margin-top:4px; text-decoration:none; }
.tc-pb-link:hover { border-color:var(--link); }
/* leg-toggle (All / None legend buttons) */
.leg-toggle { font-size:11px; padding:2px 8px; border:1px solid var(--line); border-radius:6px;
  background:var(--panel2); color:var(--muted); cursor:pointer; margin-right:6px; }
.leg-toggle:hover { color:var(--text); border-color:var(--muted); }
/* ── zh 红涨绿跌: direction-coded chip TINTS swap with the text vars ── */
html[data-lang="zh"] .tc-chip.up,
html[data-lang="zh"] .tc-chip.aln { background:rgba(224,85,85,.10); border-color:rgba(224,85,85,.35); }
html[data-lang="zh"] .tc-chip.dn,
html[data-lang="zh"] .tc-chip.was1 { background:rgba(69,184,115,.10); border-color:rgba(69,184,115,.35); }
/* zh 红涨绿跌 (operator ruling 2026-07-21): strong=bullish→red; confirmed=basing→turning→red */
html[data-lang="zh"] .score-badge.strong { color:#e06464; border-color:color-mix(in srgb,#e06464 40%,var(--line)); background:color-mix(in srgb,#e06464 8%,transparent); }
html[data-lang="zh"] .turn-chip.confirmed { color:#e06464; border-color:color-mix(in srgb,#e06464 40%,var(--line)); }
/* --red is not defined on this theme.css page (it's a vector-family token) — literal hex */
html[data-lang="zh"] .sig-chip { color:#e06464; border-color:color-mix(in srgb,#e06464 40%,var(--line)); }
/* category filter chips for performance table */
.cat-filter-bar { display:flex; flex-wrap:wrap; gap:6px; margin:9px 0 4px; }
.cat-filter-bar button { border:1px solid var(--line); background:var(--panel); color:var(--muted);
  border-radius:8px; padding:5px 9px; font-size:12px; cursor:pointer; }
.cat-filter-bar button.on { background:var(--panel2); color:var(--text); font-weight:650;
  border-color:color-mix(in srgb,var(--link) 32%,var(--line)); }

rules.old:
/* ══════════════════════════════════════════════════════════════════════════
   ROTATION-MAP DESIGN LAYER (rvx-) — ported from the US Sector Intelligence
   page so both desks speak one visual language: state-tinted aurora, glass
   containers, a verdict hero whose headline IS the read. Every class is
   prefixed rvx- and every token --rvx-*, so nothing collides with the China
   page's retained scc-/tc-/board styles above.
   ══════════════════════════════════════════════════════════════════════════ */
:root{
  --rvx-num: ui-monospace,"SF Mono",SFMono-Regular,"Cascadia Mono",Menlo,Consolas,monospace;
  --rvx-hair: color-mix(in srgb,var(--text) 9%,transparent);
  --rvx-hair2: color-mix(in srgb,var(--text) 15%,transparent);
  --rvx-lead:#3da564; --rvx-weak:#e0a030; --rvx-improve:#4f86e0; --rvx-lag:#d15656;
}
.rvx-mut{color:var(--muted)}

/* aurora backdrop — fixed radial blooms behind the whole workspace */
.rvx-aurora{position:fixed;inset:0;z-index:-1;overflow:hidden;pointer-events:none}
.rvx-aurora b{position:absolute;border-radius:50%;filter:blur(90px);opacity:.42;animation:rvxDrift 26s ease-in-out infinite}
.rvx-aurora .a1{width:600px;height:600px;left:-150px;top:-160px;background:radial-gradient(circle,#1c3a63 0%,transparent 68%)}
.rvx-aurora .a2{width:540px;height:540px;right:-120px;top:-70px;background:radial-gradient(circle,#4a3a1a 0%,transparent 66%);opacity:.36;animation-delay:-9s}
.rvx-aurora .a3{width:680px;height:520px;left:34%;bottom:-280px;background:radial-gradient(circle,#22304d 0%,transparent 70%);opacity:.34;animation-delay:-15s}
html[data-theme="light"] .rvx-aurora b{opacity:.22}
@keyframes rvxDrift{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(24px,20px) scale(1.06)}}

.rvx-reveal{opacity:0;transform:translateY(12px);animation:rvxReveal .7s cubic-bezier(.2,.7,.2,1) forwards}
@keyframes rvxReveal{to{opacity:1;transform:none}}

/* ── VERDICT HERO ── */
.rvx-hero{margin-top:16px;padding:24px 26px;position:relative;overflow:hidden;border-radius:20px;border:1px solid var(--rvx-hair2);
  background:radial-gradient(120% 140% at 8% 0%,var(--rvx-hero-a,color-mix(in srgb,var(--info) 12%,transparent)) 0%,transparent 42%),
    radial-gradient(120% 160% at 100% 20%,var(--rvx-hero-b,color-mix(in srgb,var(--warn) 10%,transparent)) 0%,transparent 46%),
    color-mix(in srgb,var(--panel) 80%,transparent);
  box-shadow:0 30px 80px -42px rgba(0,0,0,.7),inset 0 1px 0 color-mix(in srgb,#fff 6%,transparent);backdrop-filter:blur(10px)}
.rvx-hero.strain{--rvx-hero-a:color-mix(in srgb,var(--down) 13%,transparent)}
.rvx-hero.steady{--rvx-hero-a:color-mix(in srgb,var(--up) 12%,transparent)}
.rvx-eyebrow{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);font-weight:700}
/* the page's <h1> IS the eyebrow: it keeps the document outline honest for screen
   readers and search while reading as the small caps label the design calls for */
.rvx-eyebrow h1{font:inherit;letter-spacing:inherit;margin:0;color:inherit}
.rvx-eyebrow .as-of{margin-left:auto;text-transform:none;letter-spacing:0;font-weight:500}
/* the 20-day extremes line under the verdict — a receipt, never the headline */
.rvx-story{font-size:12.5px;line-height:1.55;color:var(--muted);margin:15px 0 0;max-width:96ch}
.rvx-story:empty{display:none}
.rvx-story b{color:var(--text);font-weight:650}
.rvx-hgrid{display:grid;grid-template-columns:1.4fr .95fr;gap:24px;margin-top:13px;align-items:center}
.rvx-vword{font-size:38px;line-height:1.05;font-weight:800;letter-spacing:-.028em;margin:2px 0 8px}
.rvx-vword .ac{background:linear-gradient(90deg,var(--warn),var(--up));-webkit-background-clip:text;background-clip:text;color:transparent}
.rvx-hero.strain .rvx-vword .ac{background:linear-gradient(90deg,var(--warn),var(--down));-webkit-background-clip:text;background-clip:text}
.rvx-vsub{font-size:15px;color:color-mix(in srgb,var(--text) 88%,transparent);max-width:48ch;margin:0}
.rvx-stance{display:inline-flex;align-items:center;gap:8px;margin-top:15px;padding:7px 13px;border-radius:11px;
  background:color-mix(in srgb,var(--warn) 14%,transparent);font-weight:600;font-size:13px}
.rvx-hero.steady .rvx-stance{background:color-mix(in srgb,var(--up) 13%,transparent)}
.rvx-stance-days{opacity:.72;font-weight:500}
.rvx-chips{display:flex;flex-wrap:wrap;gap:5px 15px;margin-top:12px;align-items:center}
.rvx-chips.ctx{gap:7px 20px}
.rvx-chip{display:inline-flex;align-items:center;gap:6px;font-size:12px;text-decoration:none;color:var(--text)}
/* ONE family for the hero rows: quiet ink + a state dot, no boxes. */
.rvx-chips.ctx :is(.rvx-chip,.tc-chip){border:0;background:transparent;padding:2px 0;font-size:12px;gap:7px;
  display:inline-flex;align-items:center}
.rvx-chips.ctx :is(.rvx-chip,.tc-chip)::before{content:'';width:7px;height:7px;border-radius:50%;
  background:currentColor;opacity:.5;flex:none}
.rvx-chips.ctx > .rvx-chip{color:var(--muted)}
.rvx-chips:not(.ctx) .rvx-chip{color:var(--muted);gap:5px}
a.rvx-chip{color:var(--ink-link, var(--link))}
/* strength / breaking name chips keep their tinted pill treatment inside the hero */
.rvx-names{display:flex;flex-wrap:wrap;gap:6px;margin-top:5px}
.rvx-names-l{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
/* handoff */
.rvx-hocard{border:1px solid var(--rvx-hair2);border-radius:14px;overflow:hidden;background:color-mix(in srgb,var(--panel2) 32%,transparent)}
.rvx-hocard .cap{font-size:10px;letter-spacing:.09em;color:var(--muted);padding:10px 16px 0;font-weight:700}
.rvx-handoff{display:flex;align-items:stretch}
.rvx-hocol{flex:1;padding:13px 16px;min-width:0}
.rvx-hocol .lbl{font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:700}
.rvx-hocol .nm{font-size:16px;font-weight:750;margin:4px 0 2px;line-height:1.28;letter-spacing:-.012em}
.rvx-hocol .meta{font-size:11.5px;color:var(--muted)}
.rvx-hocol.out .nm{color:var(--rvx-weak)} .rvx-hocol.in .nm{color:var(--rvx-lead)}
.rvx-hoarrow{flex:none;width:54px;display:grid;place-items:center}
.rvx-hoarrow svg{width:54px;height:28px;overflow:visible}
.rvx-hoarrow path.ln{stroke:url(#rvxHo);stroke-width:2;fill:none;stroke-linecap:round;stroke-dasharray:58;stroke-dashoffset:58;animation:rvxHoDraw 1.1s ease-out .5s forwards}
.rvx-hoarrow path.hd{fill:var(--rvx-lead);opacity:0;animation:rvxHoHead .3s ease-out 1.5s forwards}
@keyframes rvxHoDraw{to{stroke-dashoffset:0}} @keyframes rvxHoHead{to{opacity:1}}
@media (max-width:900px){ .rvx-hgrid{grid-template-columns:1fr;gap:16px} .rvx-vword{font-size:31px} .rvx-hero{padding:20px} }
/* The reveal + draw-on animations are the page's only motion; honour the OS setting.
   Named individually (not a blanket *) so a future organ's animation is a deliberate add. */
@media (prefers-reduced-motion:reduce){
  .rvx-aurora b,.rvx-reveal,.rvx-hoarrow path.ln,.rvx-hoarrow path.hd{animation:none!important}
  .rvx-reveal{opacity:1;transform:none}
  .rvx-hoarrow path.ln{stroke-dashoffset:0} .rvx-hoarrow path.hd{opacity:1}
}

/* ══════════════════════════════════════════════════════════════════════════
   LIGHT-MODE ORGAN LAYER — the shell was designed for both themes; the organs
   inside it were not (they accreted against the dark canvas). Same two-step the
   US page uses: the inks are COMPUTED on the page body and REBOUND one level
   down on .si-stage/.si-side, because a custom property may not reference
   itself on the element that declares it (`--up: color-mix(… var(--up) …)` is a
   cycle and silently no-ops). Every rule is gated on light AND on this page's
   body class, so dark renders unchanged and the site nav keeps estate colours.
   ══════════════════════════════════════════════════════════════════════════ */
html[data-theme="light"] body.page-sector-central {
  --si-ink-up:     color-mix(in srgb, var(--up)     62%, var(--text));
  --si-ink-down:   color-mix(in srgb, var(--down)   84%, var(--text));
  --si-ink-warn:   color-mix(in srgb, var(--warn)   62%, var(--text));
  --si-ink-link:   color-mix(in srgb, var(--link)   88%, var(--text));
  --si-edge:     color-mix(in srgb, var(--text) 14%, var(--line));
}
/* zh 红涨绿跌 — theme.css swaps --up/--down at the token level, so the mix that
   darkens a green must follow the green, not the name. Red clears AA with far
   less mixing; one percentage for both would print a dour maroon. */
html[data-theme="light"][data-lang="zh"] body.page-sector-central {
  --si-ink-up:   color-mix(in srgb, var(--up)   84%, var(--text));  /* red   */
  --si-ink-down: color-mix(in srgb, var(--down) 62%, var(--text));  /* green */
}
html[data-theme="light"] .si-stage,
html[data-theme="light"] .si-side {
  --up: var(--si-ink-up); --down: var(--si-ink-down); --warn: var(--si-ink-warn);
  --link: var(--si-ink-link); --info: var(--si-ink-link);
  --line: var(--si-edge);
}

/* ── macro-desk composure: the estate's container recipe ────────────────────
   Drop shadow does the definition, borders stay TRANSPARENT (layout-stable,
   invisible), and the stage itself stays transparent so the aurora runs
   unbroken beneath every panel. A flat stage fill painted over the gradient is
   a hard seam — never reintroduce one. */
.si-stage { background:transparent; }
.si-vb-g { width:19px; height:19px; flex:none; }
.si-vr-g { width:16px; height:16px; flex:none; margin-top:1px; color:var(--ink-link, var(--link)); }
.si-view-btn .si-vb-g { color:var(--muted); }
.si-view-btn.on .si-vb-g, .si-view-btn:hover .si-vb-g { color:var(--ink-link, var(--link)); }
.si-side-out .si-vb-g { color:var(--muted); }
.si-side { padding:14px 11px; }
.si-view-btn { font-size:13px; padding:8.5px 11px; }
.si-side-out { white-space:nowrap; }
/* rail: COMPLETELY open in BOTH themes — the aurora/gradient is the page's
   identity, and a column fill (frosted or flat) reads as a hard seam cutting
   across it (operator 2026-08-05: the dark frosted-55%-bg column "looks weird"
   over the gradient). The rail is a grid COLUMN, not an overlay, so content never
   scrolls under it; the active/hover button pills carry their own backing, so no
   rail fill is needed for legibility. */
.si-side { background:transparent; border-right:0;
  backdrop-filter:none; -webkit-backdrop-filter:none; }
@media (max-width:767px) {
  /* The narrow-screen switcher is an overlay when scrolling. */
  .si-shell .si-side { padding:2px 0; background:var(--panel); }
  .si-shell .si-view-btn { padding:7px 2px; }
  #si-explore, #si-explore [id] { scroll-margin-top:5rem; }
}
.rvx-hero, .rvx-hocard, .si-view-read {
  background:var(--desk-tile, var(--panel));
  border:1px solid transparent;
  border-radius:var(--desk-r-lg, 14px);
  box-shadow:var(--card-shadow, 0 1px 2px color-mix(in srgb, var(--text) 6%, transparent)); }
.rvx-hero { border-radius:20px; }
html[data-theme="light"] .rvx-hero,
html[data-theme="light"] .si-view-read {
  background:var(--panel);
  box-shadow:0 1px 2px color-mix(in srgb, var(--text) 5%, transparent),
             0 12px 32px -14px color-mix(in srgb, var(--text) 12%, transparent); }
html[data-theme="light"] .rvx-hocard {
  background:linear-gradient(100deg,
    color-mix(in srgb, var(--si-ink-warn, var(--warn)) 6%, var(--panel)) 0%,
    var(--panel) 46%,
    color-mix(in srgb, var(--si-ink-up, var(--up)) 8%, var(--panel)) 100%);
  box-shadow:0 1px 2px color-mix(in srgb, var(--text) 5%, transparent),
             0 12px 32px -14px color-mix(in srgb, var(--text) 10%, transparent); }
html[data-theme="light"] .rvx-hocol.out .nm { color:var(--si-ink-warn, var(--warn)); }
html[data-theme="light"] .rvx-hocol.in .nm  { color:var(--si-ink-up, var(--up)); }
html[data-theme="light"] .rvx-hero .rvx-vword .ac {
  background:linear-gradient(94deg, var(--si-ink-up, var(--up)),
    color-mix(in srgb, var(--si-ink-up, var(--up)) 52%, var(--link)));
  -webkit-background-clip:text; background-clip:text; }
html[data-theme="light"] .rvx-hero.strain .rvx-vword .ac {
  background:linear-gradient(94deg, var(--si-ink-warn, var(--warn)), var(--si-ink-down, var(--down)));
  -webkit-background-clip:text; background-clip:text; }

/* — the macro rail-tick on every workspace section head — */
.si-sec-h h2, .scc-section-h h2 { display:flex; align-items:center; gap:11px; }
.si-sec-h h2::before, .scc-section-h h2::before { content:""; flex:none; width:3px; height:18px;
  border-radius:2px;
  background:linear-gradient(180deg, var(--link), color-mix(in srgb, var(--link) 35%, transparent)); }

/* typeface: SF first (Apple system faces), Inter everywhere else — operator
   directive for the sector pages */
body { font-family:-apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI',
  Roboto, Helvetica, sans-serif; }

/* the hero IS the overview's read — no echo line beneath it */
.si-view[data-view="overview"] .si-view-read { display:none; }

rules.new:
/* ══════════════════════════════════════════════════════════════════════════
   ROTATION-MAP DESIGN LAYER (rvx-) — ported from the US Sector Intelligence
   page so both desks speak one visual language: state-tinted aurora, glass
   containers, a verdict hero whose headline IS the read. Every class is
   prefixed rvx- and every token --rvx-*, so nothing collides with the China
   page's retained scc-/tc-/board styles above.
   ══════════════════════════════════════════════════════════════════════════ */
:root{
  --rvx-num: ui-monospace,"SF Mono",SFMono-Regular,"Cascadia Mono",Menlo,Consolas,monospace;
  --rvx-hair: color-mix(in srgb,var(--text) 9%,transparent);
  --rvx-hair2: color-mix(in srgb,var(--text) 15%,transparent);
  --rvx-lead:#3da564; --rvx-weak:#e0a030; --rvx-improve:#4f86e0; --rvx-lag:#d15656;
}
.rvx-mut{color:var(--muted)}

/* aurora backdrop — fixed radial blooms behind the whole workspace */
.rvx-aurora{position:fixed;inset:0;z-index:-1;overflow:hidden;pointer-events:none}
.rvx-aurora b{position:absolute;border-radius:50%;filter:blur(90px);opacity:.42;animation:rvxDrift 26s ease-in-out infinite}
.rvx-aurora .a1{width:600px;height:600px;left:-150px;top:-160px;background:radial-gradient(circle,#1c3a63 0%,transparent 68%)}
.rvx-aurora .a2{width:540px;height:540px;right:-120px;top:-70px;background:radial-gradient(circle,#4a3a1a 0%,transparent 66%);opacity:.36;animation-delay:-9s}
.rvx-aurora .a3{width:680px;height:520px;left:34%;bottom:-280px;background:radial-gradient(circle,#22304d 0%,transparent 70%);opacity:.34;animation-delay:-15s}
html[data-theme="light"] .rvx-aurora b{opacity:.22}
@keyframes rvxDrift{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(24px,20px) scale(1.06)}}

.rvx-reveal{opacity:0;transform:translateY(12px);animation:rvxReveal .7s cubic-bezier(.2,.7,.2,1) forwards}
@keyframes rvxReveal{to{opacity:1;transform:none}}

/* ── VERDICT HERO ── */
.rvx-hero{margin-top:16px;padding:24px 26px;position:relative;overflow:hidden;border-radius:20px;border:1px solid var(--rvx-hair2);
  background:radial-gradient(120% 140% at 8% 0%,var(--rvx-hero-a,color-mix(in srgb,var(--info) 12%,transparent)) 0%,transparent 42%),
    radial-gradient(120% 160% at 100% 20%,var(--rvx-hero-b,color-mix(in srgb,var(--warn) 10%,transparent)) 0%,transparent 46%),
    color-mix(in srgb,var(--panel) 80%,transparent);
  box-shadow:0 30px 80px -42px rgba(0,0,0,.7),inset 0 1px 0 color-mix(in srgb,#fff 6%,transparent);backdrop-filter:blur(10px)}
.rvx-hero.strain{--rvx-hero-a:color-mix(in srgb,var(--down) 13%,transparent)}
.rvx-hero.steady{--rvx-hero-a:color-mix(in srgb,var(--up) 12%,transparent)}
.rvx-eyebrow{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);font-weight:700}
/* the page's <h1> IS the eyebrow: it keeps the document outline honest for screen
   readers and search while reading as the small caps label the design calls for */
.rvx-eyebrow h1{font:inherit;letter-spacing:inherit;margin:0;color:inherit}
.rvx-eyebrow .as-of{margin-left:auto;text-transform:none;letter-spacing:0;font-weight:500}
/* the 20-day extremes line under the verdict — a receipt, never the headline */
.rvx-story{font-size:12.5px;line-height:1.55;color:var(--muted);margin:15px 0 0;max-width:96ch}
.rvx-story:empty{display:none}
.rvx-story b{color:var(--text);font-weight:650}
.rvx-hgrid{display:grid;grid-template-columns:1.4fr .95fr;gap:24px;margin-top:13px;align-items:center}
.rvx-vword{font-size:38px;line-height:1.05;font-weight:800;letter-spacing:-.028em;margin:2px 0 8px}
.rvx-vword .ac{background:linear-gradient(90deg,var(--warn),var(--up));-webkit-background-clip:text;background-clip:text;color:transparent}
.rvx-hero.strain .rvx-vword .ac{background:linear-gradient(90deg,var(--warn),var(--down));-webkit-background-clip:text;background-clip:text}
.rvx-vsub{font-size:15px;color:color-mix(in srgb,var(--text) 88%,transparent);max-width:48ch;margin:0}
.rvx-stance{display:inline-flex;align-items:center;gap:8px;margin-top:15px;padding:7px 13px;border-radius:11px;
  background:color-mix(in srgb,var(--warn) 14%,transparent);font-weight:600;font-size:13px}
.rvx-hero.steady .rvx-stance{background:color-mix(in srgb,var(--up) 13%,transparent)}
.rvx-stance-days{opacity:.72;font-weight:500}
.rvx-chips{display:flex;flex-wrap:wrap;gap:5px 15px;margin-top:12px;align-items:center}
.rvx-chips.ctx{gap:7px 20px}
.rvx-chip{display:inline-flex;align-items:center;gap:6px;font-size:12px;text-decoration:none;color:var(--text)}
/* ONE family for the hero rows: quiet ink + a state dot, no boxes. */
.rvx-chips.ctx :is(.rvx-chip,.tc-chip){border:0;background:transparent;padding:2px 0;font-size:12px;gap:7px;
  display:inline-flex;align-items:center}
.rvx-chips.ctx :is(.rvx-chip,.tc-chip)::before{content:'';width:7px;height:7px;border-radius:50%;
  background:currentColor;opacity:.5;flex:none}
.rvx-chips.ctx > .rvx-chip{color:var(--muted)}
.rvx-chips:not(.ctx) .rvx-chip{color:var(--muted);gap:5px}
a.rvx-chip{color:var(--ink-link, var(--link))}
/* strength / breaking name chips keep their tinted pill treatment inside the hero */
.rvx-names{display:flex;flex-wrap:wrap;gap:6px;margin-top:5px}
.rvx-names-l{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
/* handoff */
.rvx-hocard{border:1px solid var(--rvx-hair2);border-radius:14px;overflow:hidden;background:color-mix(in srgb,var(--panel2) 32%,transparent)}
.rvx-hocard .cap{font-size:10px;letter-spacing:.09em;color:var(--muted);padding:10px 16px 0;font-weight:700}
.rvx-handoff{display:flex;align-items:stretch}
.rvx-hocol{flex:1;padding:13px 16px;min-width:0}
.rvx-hocol .lbl{font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:700}
.rvx-hocol .nm{font-size:16px;font-weight:750;margin:4px 0 2px;line-height:1.28;letter-spacing:-.012em}
.rvx-hocol .meta{font-size:11.5px;color:var(--muted)}
.rvx-hocol.out .nm{color:var(--rvx-weak)} .rvx-hocol.in .nm{color:var(--rvx-lead)}
.rvx-hoarrow{flex:none;width:54px;display:grid;place-items:center}
.rvx-hoarrow svg{width:54px;height:28px;overflow:visible}
.rvx-hoarrow path.ln{stroke:url(#rvxHo);stroke-width:2;fill:none;stroke-linecap:round;stroke-dasharray:58;stroke-dashoffset:58;animation:rvxHoDraw 1.1s ease-out .5s forwards}
.rvx-hoarrow path.hd{fill:var(--rvx-lead);opacity:0;animation:rvxHoHead .3s ease-out 1.5s forwards}
@keyframes rvxHoDraw{to{stroke-dashoffset:0}} @keyframes rvxHoHead{to{opacity:1}}
@media (max-width:900px){ .rvx-hgrid{grid-template-columns:1fr;gap:16px} .rvx-vword{font-size:31px} .rvx-hero{padding:20px} }
/* The reveal + draw-on animations are the page's only motion; honour the OS setting.
   Named individually (not a blanket *) so a future organ's animation is a deliberate add. */
@media (prefers-reduced-motion:reduce){
  .rvx-aurora b,.rvx-reveal,.rvx-hoarrow path.ln,.rvx-hoarrow path.hd{animation:none!important}
  .rvx-reveal{opacity:1;transform:none}
  .rvx-hoarrow path.ln{stroke-dashoffset:0} .rvx-hoarrow path.hd{opacity:1}
}

/* ══════════════════════════════════════════════════════════════════════════
   LIGHT-MODE ORGAN LAYER — the shell was designed for both themes; the organs
   inside it were not (they accreted against the dark canvas). Same two-step the
   US page uses: the inks are COMPUTED on the page body and REBOUND one level
   down on .si-stage/.si-side, because a custom property may not reference
   itself on the element that declares it (`--up: color-mix(… var(--up) …)` is a
   cycle and silently no-ops). Every rule is gated on light AND on this page's
   body class, so dark renders unchanged and the site nav keeps estate colours.
   ══════════════════════════════════════════════════════════════════════════ */
html[data-theme="light"] body.page-sector-central {
  --si-ink-up:     color-mix(in srgb, var(--up)     62%, var(--text));
  --si-ink-down:   color-mix(in srgb, var(--down)   84%, var(--text));
  --si-ink-warn:   color-mix(in srgb, var(--warn)   62%, var(--text));
  --si-ink-link:   color-mix(in srgb, var(--link)   88%, var(--text));
  --si-edge:     color-mix(in srgb, var(--text) 14%, var(--line));
}
/* zh 红涨绿跌 — theme.css swaps --up/--down at the token level, so the mix that
   darkens a green must follow the green, not the name. Red clears AA with far
   less mixing; one percentage for both would print a dour maroon. */
html[data-theme="light"][data-lang="zh"] body.page-sector-central {
  --si-ink-up:   color-mix(in srgb, var(--up)   84%, var(--text));  /* red   */
  --si-ink-down: color-mix(in srgb, var(--down) 62%, var(--text));  /* green */
}
html[data-theme="light"] .si-stage,
html[data-theme="light"] .si-side {
  --up: var(--si-ink-up); --down: var(--si-ink-down); --warn: var(--si-ink-warn);
  --link: var(--si-ink-link); --info: var(--si-ink-link);
  --line: var(--si-edge);
}

/* ── macro-desk composure: the estate's container recipe ────────────────────
   Drop shadow does the definition, borders stay TRANSPARENT (layout-stable,
   invisible), and the stage itself stays transparent so the aurora runs
   unbroken beneath every panel. A flat stage fill painted over the gradient is
   a hard seam — never reintroduce one. */
.si-stage { background:transparent; }
.si-vb-g { width:19px; height:19px; flex:none; }
.si-vr-g { width:16px; height:16px; flex:none; margin-top:1px; color:var(--ink-link, var(--link)); }
.si-view-btn .si-vb-g { color:var(--muted); }
.si-view-btn.on .si-vb-g, .si-view-btn:hover .si-vb-g { color:var(--ink-link, var(--link)); }
.si-side-out .si-vb-g { color:var(--muted); }
.si-side { padding:14px 11px; }
.si-view-btn { font-size:13px; padding:8.5px 11px; }
.si-side-out { white-space:nowrap; }
/* rail: COMPLETELY open in BOTH themes — the aurora/gradient is the page's
   identity, and a column fill (frosted or flat) reads as a hard seam cutting
   across it (operator 2026-08-05: the dark frosted-55%-bg column "looks weird"
   over the gradient). The rail is a grid COLUMN, not an overlay, so content never
   scrolls under it; the active/hover button pills carry their own backing, so no
   rail fill is needed for legibility. */
.si-side { background:transparent; border-right:0;
  backdrop-filter:none; -webkit-backdrop-filter:none; }
@media (max-width:767px) {
  /* The narrow-screen switcher is an overlay when scrolling. */
  .si-shell .si-side { padding:2px 0; background:var(--panel); }
  .si-shell .si-view-btn { padding:7px 2px; }
  #si-explore, #si-explore [id] { scroll-margin-top:5rem; }
}
.rvx-hero, .rvx-hocard, .si-view-read {
  background:var(--desk-tile, var(--panel));
  border:1px solid transparent;
  border-radius:var(--desk-r-lg, 14px);
  box-shadow:var(--card-shadow, 0 1px 2px color-mix(in srgb, var(--text) 6%, transparent)); }
.rvx-hero { border-radius:20px; }
html[data-theme="light"] .rvx-hero,
html[data-theme="light"] .si-view-read {
  background:var(--panel);
  box-shadow:0 1px 2px color-mix(in srgb, var(--text) 5%, transparent),
             0 12px 32px -14px color-mix(in srgb, var(--text) 12%, transparent); }
html[data-theme="light"] .rvx-hocard {
  background:linear-gradient(100deg,
    color-mix(in srgb, var(--si-ink-warn, var(--warn)) 6%, var(--panel)) 0%,
    var(--panel) 46%,
    color-mix(in srgb, var(--si-ink-up, var(--up)) 8%, var(--panel)) 100%);
  box-shadow:0 1px 2px color-mix(in srgb, var(--text) 5%, transparent),
             0 12px 32px -14px color-mix(in srgb, var(--text) 10%, transparent); }
html[data-theme="light"] .rvx-hocol.out .nm { color:var(--si-ink-warn, var(--warn)); }
html[data-theme="light"] .rvx-hocol.in .nm  { color:var(--si-ink-up, var(--up)); }
html[data-theme="light"] .rvx-hero .rvx-vword .ac {
  background:linear-gradient(94deg, var(--si-ink-up, var(--up)),
    color-mix(in srgb, var(--si-ink-up, var(--up)) 52%, var(--link)));
  -webkit-background-clip:text; background-clip:text; }
html[data-theme="light"] .rvx-hero.strain .rvx-vword .ac {
  background:linear-gradient(94deg, var(--si-ink-warn, var(--warn)), var(--si-ink-down, var(--down)));
  -webkit-background-clip:text; background-clip:text; }

/* — the macro rail-tick on every workspace section head — */
.si-sec-h h2, .scc-section-h h2 { display:flex; align-items:center; gap:11px; }
.si-sec-h h2::before, .scc-section-h h2::before {content:none;}

/* typeface: SF first (Apple system faces), Inter everywhere else — operator
   directive for the sector pages */
body { font-family:-apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI',
  Roboto, Helvetica, sans-serif; }

/* the hero IS the overview's read — no echo line beneath it */
.si-view[data-view="overview"] .si-view-read { display:none; }

rules.old:
/* ══════════════════════════════════════════════════════════════════════════
   CONFLUENCE VIEW (5th rail view) — the 同花顺 subsector-confluence board,
   brought from the standalone subsectors_china page and mounted here by the
   router (subsectors_china.js writes concept cards + tables into #sc-app). The
   donor page's page-local <style> was authored with UNSCOPED selectors
   (.card / .tier / .pill / table.tbl / .num / .pos / .neg / .tk / .sec / …) that
   COLLIDE with this page's own .card/.pos/.neg board rules and the shared
   macro-desk.css (.card is defined differently in three places). Every rule
   below is therefore rescoped under #si-confluence so it styles ONLY the
   confluence board and never leaks onto the other four views — the id lifts each
   rule's specificity above the page's bare-class rules inside the view, and
   constrains it to nothing outside. Nothing here is changed from the donor beyond
   the scope prefix (and dropping the donor's global *, body, a and .wrap resets
   this page already owns). theme.css / macro-desk.css are untouched by design.
   ══════════════════════════════════════════════════════════════════════════ */
#si-confluence .sc-head { display:flex; flex-wrap:wrap; align-items:flex-end; gap:6px 22px; margin:8px 2px 6px; }
#si-confluence .sc-head h1 { font-size:23px; margin:0; font-weight:800; letter-spacing:-.015em; }
#si-confluence .sc-head .asof { color:var(--muted); font-size:12px; margin-left:auto; }
#si-confluence .sc-sub { color:var(--muted); font-size:12.5px; margin:2px 2px 14px; max-width:96ch; line-height:1.55; }
#si-confluence .sec { margin:22px 0 8px; }
#si-confluence .sec h2 { font-size:15px; font-weight:700; margin:0 2px 3px; display:flex; align-items:center; gap:8px; }
#si-confluence .sec .desc { color:var(--muted); font-size:11.5px; margin:0 2px 10px; max-width:92ch; }
#si-confluence .cards { display:grid; grid-template-columns:repeat(auto-fill,minmax(238px,1fr)); gap:10px; }
#si-confluence .card { background:var(--panel); border:1px solid var(--line); border-left-width:3px; border-radius:11px; padding:11px 12px; display:block; transition:border-color .12s,transform .08s; }
#si-confluence .card:hover { transform:translateY(-1px); border-color:var(--link); }
#si-confluence .card .top { display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }
#si-confluence .card .nm { font-weight:700; font-size:13.5px; line-height:1.25; }
#si-confluence .card .sct { color:var(--muted); font-size:10.5px; margin-top:1px; text-transform:uppercase; letter-spacing:.03em; }
#si-confluence .card .row2 { display:flex; align-items:center; gap:6px; margin-top:9px; flex-wrap:wrap; }
#si-confluence .card .meta { color:var(--muted); font-size:11px; margin-top:7px; line-height:1.45; }
#si-confluence .tier { font-weight:800; font-size:11px; padding:1px 6px; border-radius:5px; letter-spacing:.02em; color:#fff; }
#si-confluence .tier.T1{ background:var(--up); } #si-confluence .tier.T2{ background:#3da564; } #si-confluence .tier.T3{ background:var(--info); } #si-confluence .tier.T4{ background:#6b7cc4; }
#si-confluence .tier.none{ background:var(--g-mid); color:var(--muted); }
/* zh 红涨绿跌: T2 bullish tier badge swaps green→red */
html[data-lang="zh"] #si-confluence .tier.T2{ background:#d04545; }
#si-confluence .pill { font-size:10.5px; font-weight:700; padding:1px 7px; border-radius:9px; border:1px solid var(--line); }
#si-confluence .pill.buy{ color:var(--ink-up, var(--up)); border-color:color-mix(in srgb,var(--up) 45%,transparent); }
#si-confluence .pill.avoid{ color:var(--ink-down, var(--down)); border-color:color-mix(in srgb,var(--down) 45%,transparent); }
#si-confluence .pill.neutral{ color:var(--muted); }
#si-confluence .pill.tactical,#si-confluence .pill.late{ color:var(--ink-orange, var(--orange)); border-color:color-mix(in srgb,var(--orange) 45%,transparent); }
#si-confluence table.tbl { width:100%; border-collapse:collapse; font-size:12.5px; }
#si-confluence table.tbl th { text-align:left; color:var(--muted); font-weight:600; font-size:11px; text-transform:uppercase; letter-spacing:.03em; padding:6px 9px; border-bottom:1px solid var(--line); cursor:pointer; white-space:nowrap; }
#si-confluence table.tbl td { padding:7px 9px; border-bottom:1px solid var(--line); white-space:nowrap; }
#si-confluence table.tbl tr:hover td { background:var(--panel); }
#si-confluence .sc-card-hidden { display:none !important; }
#si-confluence .sc-more { margin:9px 2px 0; font:600 12px/1.4 inherit; color:var(--ink-link, var(--link)); background:none; border:1px solid var(--line); border-radius:8px; padding:5px 12px; cursor:pointer; transition:border-color .12s,background .12s; }
#si-confluence .sc-more:hover { border-color:var(--link); background:color-mix(in srgb,var(--link) 8%,transparent); }
#si-confluence .tk { font-weight:700; }
#si-confluence .num { font-variant-numeric:tabular-nums; }
#si-confluence .pos{ color:var(--ink-up, var(--up)); } #si-confluence .neg{ color:var(--ink-down, var(--down)); }
#si-confluence .scbar { display:inline-block; height:7px; border-radius:4px; background:var(--up); vertical-align:middle; }
#si-confluence .relb { font-size:9.5px; font-weight:800; padding:0 5px; border-radius:6px; letter-spacing:.02em; vertical-align:middle; white-space:nowrap; }
#si-confluence .rel-low { color:var(--ink-orange, var(--orange)); border:1px solid color-mix(in srgb,var(--orange) 45%,transparent); }
#si-confluence .rel-med { color:var(--muted); }
#si-confluence .npc { color:var(--muted); font-size:10.5px; font-variant-numeric:tabular-nums; }
#si-confluence details.thin { margin:14px 2px 0; border:1px dashed var(--line); border-radius:10px; padding:0 12px 12px; background:color-mix(in srgb,var(--orange) 4%,transparent); }
#si-confluence details.thin > summary { cursor:pointer; font-weight:700; font-size:13.5px; padding:11px 2px; list-style:none; display:flex; align-items:center; gap:8px; }
#si-confluence details.thin > summary::-webkit-details-marker { display:none; }
#si-confluence details.thin > summary::before { content:'▸'; color:var(--muted); }
#si-confluence details.thin[open] > summary::before { content:'▾'; }
#si-confluence .sc-foot { color:var(--muted); font-size:11px; margin:24px 2px 0; line-height:1.65; max-width:108ch; border-top:1px solid var(--line); padding-top:12px; }
#si-confluence .empty { color:var(--muted); padding:14px; }
/* base scroll wrapper (subsectors_china.js's wrapTbls injects .tbl-scroll) — desktop
   horizontal scroll for wide tables; the mobile override below flips it to visible */
#si-confluence .tbl-scroll { overflow-x:auto; }
@media (max-width:720px){
  #si-confluence .sec { margin-top:18px; }
  #si-confluence .sec h2 { font-size:14px; gap:6px; }
  #si-confluence .sec .desc { font-size:11px; line-height:1.45; }
  #si-confluence .cards { grid-template-columns:1fr; gap:8px; }
  #si-confluence .card { border-radius:9px; padding:10px; }
  #si-confluence .card .nm { overflow-wrap:anywhere; }
  #si-confluence .card .sct,#si-confluence .card .meta { overflow-wrap:anywhere; }
  #si-confluence .tbl-scroll { overflow-x:visible; }
  #si-confluence table.tbl.db-table,
  #si-confluence table.tbl.hw-table,
  #si-confluence table.tbl.all-table { table-layout:fixed; width:100%; font-size:11.5px; }
  #si-confluence table.tbl.db-table th,
  #si-confluence table.tbl.db-table td,
  #si-confluence table.tbl.hw-table th,
  #si-confluence table.tbl.hw-table td,
  #si-confluence table.tbl.all-table th,
  #si-confluence table.tbl.all-table td { padding:6px 5px; white-space:normal; overflow-wrap:anywhere; vertical-align:top; }
  #si-confluence table.tbl.db-table .col-stock,
  #si-confluence table.tbl.hw-table .col-stock { width:82px; overflow-wrap:normal; }
  #si-confluence table.tbl.db-table .col-tier,
  #si-confluence table.tbl.hw-table .col-tier { width:54px; }
  #si-confluence table.tbl.db-table .col-concept,
