rules.old:
/* ============================================================================
   sector_cycles.css — Sector Cycle Intelligence · deltas over cycle.css
   ----------------------------------------------------------------------------
   This page reuses the WHOLE cycle.css design system (.cyc-* + .mmc-*). Only the
   net-new chrome lives here: the Price↔Cycle mode + Log/Linear scale segmented
   controls, peak/trough legend glyphs, the focused-sector narrative timeline, the
   cross-sector leadership rail, and the clickable narrative bands.
   ========================================================================== */

/* Opaque page canvas — theme.css paints its site-wide "aurora" backdrop OVER an
   expected body { background:var(--bg) }, so the page must set it (robust in any
   browser regardless of the default canvas colour). */
body { background: var(--bg); color: var(--text); }

/* ---- section tabs: Sector ETFs vs Thematic Baskets (two independent views) -- */
.sc-tabs { display: inline-flex; gap: 4px; background: var(--panel2); border: 1px solid var(--line);
  border-radius: 13px; padding: 4px; margin: 8px 2px 2px; }
.sc-tab { font-size: 13.5px; font-weight: 700; color: var(--muted); background: transparent; border: 0;
  border-radius: 10px; padding: 8px 17px; cursor: pointer; display: inline-flex; align-items: center; gap: 7px;
  transition: color .18s, background .18s, box-shadow .18s, transform .1s; }
.sc-tab i { font-style: normal; font-size: 11px; font-weight: 700; color: var(--muted); background: var(--panel);
  border: 1px solid var(--line); border-radius: 999px; padding: 1px 7px; }
.sc-tab:hover { color: var(--text); }
.sc-tab:active { transform: translateY(1px); }
.sc-tab.on { color: var(--text); background: var(--panel);
  box-shadow: 0 1px 2px rgba(0,0,0,.22), 0 3px 12px color-mix(in srgb, var(--link) 16%, transparent); }
.sc-tab.on i { color: var(--ink-link, var(--link)); border-color: color-mix(in srgb, var(--link) 42%, var(--line)); }
@media (max-width: 560px) { .sc-tabs { flex-wrap: wrap; } }

/* ---- page-level universe toggle (Sector ETFs / Shenwan vs Thematic Baskets) -------
   On the Sector Central hubs this toggle drives BOTH the cycle map AND the conviction
   board, so it's raised out of the chart card to a prominent, labelled primary control
   that sits right above the cycle map. Scoped to .scc-page so the standalone cycles
   pages (.cyc-page, no .scc-page) keep their original compact tabs. */
.scc-page .scc-universe { display: flex; align-items: center; gap: 13px; flex-wrap: wrap; margin: 20px 0 8px; }
.scc-page .scc-universe-lab { font-size: 11px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; color: var(--muted); }
.scc-page .scc-universe .sc-tabs { margin: 0; padding: 5px; border-radius: 15px; gap: 5px; }
.scc-page .scc-universe .sc-tab { font-size: 15px; font-weight: 750; padding: 11px 24px; border-radius: 12px; }
.scc-page .scc-universe .sc-tab i { font-size: 12px; }
@media (max-width: 560px) { .scc-page .scc-universe .sc-tabs { width: 100%; }
  .scc-page .scc-universe .sc-tab { flex: 1; justify-content: center; padding: 11px 12px; } }

/* chart empty-state hint (baskets section with nothing selected yet) */
.sc-chartwrap { position: relative; }
.sc-chart-hint { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  pointer-events: none; color: var(--muted); font-size: 13.5px; line-height: 1.6; text-align: center; padding: 0 26px; }
.sc-chart-hint[hidden] { display: none; }

/* ---- a bigger, dominant hero chart ------------------------------------- */
#sc-chart { width: 100%; height: 500px; }
@media (min-width: 881px) { #sc-chart { height: 600px; } }
@media (min-width: 1400px) { #sc-chart { height: 660px; } }
@media (max-width: 880px) { #sc-chart { height: min(56vh, 440px); } }

/* ---- first-paint loading skeleton -------------------------------------- */
/* #sc-chart already reserves its height above, so there's no reflow when mm_charts appends the
   SVG (H = clientHeight || data-h — clientHeight is the CSS height here). This only paints a
   loading affordance INTO that reserved box so users don't stare at a blank void while the core
   data + engine + orchestrator download. The :empty rule vanishes the instant mm_charts appends
   the <svg>. Tokens only (--panel/--line/--muted) — no new palette. */
#sc-chart:empty {
  position: relative;
  border-radius: 12px;
  background:
    linear-gradient(100deg,
      transparent 0%,
      color-mix(in srgb, var(--panel) 55%, transparent) 40%,
      color-mix(in srgb, var(--line) 40%, transparent) 50%,
      color-mix(in srgb, var(--panel) 55%, transparent) 60%,
      transparent 100%),
    color-mix(in srgb, var(--panel) 35%, transparent);
  background-size: 220% 100%, 100% 100%;
  background-repeat: no-repeat;
  animation: sc-chart-shimmer 1.5s ease-in-out infinite;
}
#sc-chart:empty::after {
  content: "Loading the cycle map…";
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  color: var(--muted); font-size: 13px; letter-spacing: .01em;
}
html[data-lang="zh"] #sc-chart:empty::after { content: "周期图加载中…"; }
@keyframes sc-chart-shimmer { 0% { background-position: 120% 0, 0 0; } 100% { background-position: -120% 0, 0 0; } }
@media (prefers-reduced-motion: reduce) {
  #sc-chart:empty { animation: none; background: color-mix(in srgb, var(--panel) 35%, transparent); }
}
/* let the hero breathe + lift the chart inside its card */
.sc-page .cyc-hero { padding: 18px 18px 12px; }

/* ---- segmented controls (scale + mode) — premium pill switch ------------ */
.sc-modes, .sc-scale { display: inline-flex; align-items: center; gap: 3px; background: var(--panel2);
  border: 1px solid var(--line); border-radius: 10px; padding: 3px; box-shadow: inset 0 1px 2px rgba(0,0,0,.18); }
html[data-theme="light"] .sc-modes, html[data-theme="light"] .sc-scale { box-shadow: inset 0 1px 2px rgba(20,30,50,.05); }
.sc-mbtn, .sc-sbtn { font-size: 12px; font-weight: 650; letter-spacing: .01em; color: var(--muted); background: transparent;
  border: 0; border-radius: 7px; padding: 5px 13px; cursor: pointer; white-space: nowrap;
  transition: color .18s, background .18s, box-shadow .18s, transform .1s; }
.sc-mbtn:hover, .sc-sbtn:hover { color: var(--text); }
.sc-mbtn:active, .sc-sbtn:active { transform: translateY(1px); }
.sc-mbtn.on, .sc-sbtn.on { color: #fff;
  background: linear-gradient(180deg, color-mix(in srgb, var(--link) 90%, #fff 10%), var(--link));
  box-shadow: 0 1px 2px rgba(0,0,0,.28), 0 2px 10px color-mix(in srgb, var(--link) 36%, transparent); }
html[data-theme="light"] .sc-mbtn.on, html[data-theme="light"] .sc-sbtn.on { color: #fff; }
/* scale is meaningless in cycle-position mode → dim + lock, but keep its footprint (no layout shift) */
.sc-scale.disabled { opacity: .4; filter: saturate(.35); pointer-events: none; }

/* ---- "where they stand" phase chips — reactive like the sector chips ---- */
.sc-page .cyc-gchip { transition: color .18s, background .2s, border-color .2s, box-shadow .2s, transform .14s var(--ease); }
.sc-page .cyc-gchip:not(.on) { opacity: .62; }
.sc-page .cyc-gchip:not(.on):hover { opacity: 1; transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--ph, var(--muted)) 60%, var(--line));
  box-shadow: 0 3px 12px color-mix(in srgb, var(--ph, var(--muted)) 22%, transparent); }
/* selected chip: ink-on-tint, not white-on-hue — the phase hues are dark-theme
   bright (#2dd4bf teal worst: white sat at 2.46:1 dark / 1.09:1 light, the least
   legible element in the W3 audit). Same hue identity, 4.5–6.4:1 in both themes;
   matches the recipe the SI V2 workspace already applies to its embedded copy. */
.sc-page .cyc-gchip.on { color: color-mix(in srgb, var(--ph, var(--link)) 38%, var(--text)); opacity: 1; transform: translateY(-1px);
  background: color-mix(in srgb, var(--ph, var(--link)) 12%, var(--panel));
  border-color: color-mix(in srgb, var(--ph, var(--link)) 55%, var(--line));
  box-shadow: 0 4px 16px color-mix(in srgb, var(--ph, var(--link)) 24%, transparent); }
.sc-page .cyc-gchip.on .gdot { background: currentColor; box-shadow: none; }
.sc-page .cyc-gchip.on i { opacity: .95; color: inherit; }

/* legend peak/trough glyphs */
.cyc-legend .lm { width: 0; height: 0; }
.cyc-legend .lm-pk { border-left: 5px solid transparent; border-right: 5px solid transparent; border-bottom: 7px solid var(--warn); }
.cyc-legend .lm-tr { border-left: 5px solid transparent; border-right: 5px solid transparent; border-top: 7px solid var(--up); }

/* the price-mode markers (peaks/troughs) always show for the focused line; the
   mm_charts CSS only reveals peak/trough glyphs on focus — exactly what we want. */
.sc-page .mmc-series.is-focus .mmc-mk-peak, .sc-page .mmc-series.is-focus .mmc-mk-trough { opacity: 1; }

/* clickable narrative bands (focused sector, price mode) */
.sc-page .mmc-vband { cursor: pointer; transition: opacity .2s ease; }
.sc-page .mmc-vband:hover { opacity: .2 !important; }
.sc-page .mmc-vlabel { cursor: pointer; }

/* ---- focus panel: leadership + turns/legs timeline ---------------------- */
.sc-pos { display: flex; align-items: center; gap: 10px; margin: 2px 0 4px; }
.sc-pos-bar { flex: 1; height: 7px; border-radius: 99px; background: linear-gradient(90deg,
  color-mix(in srgb, var(--up) 40%, transparent), color-mix(in srgb, var(--muted) 30%, transparent),
  color-mix(in srgb, var(--warn) 55%, transparent)); position: relative; border: 1px solid var(--line); }
.sc-pos-dot { position: absolute; top: 50%; width: 13px; height: 13px; border-radius: 50%; background: var(--c, var(--link));
  transform: translate(-50%, -50%); box-shadow: 0 0 0 3px var(--panel), 0 0 12px color-mix(in srgb, var(--c, var(--link)) 60%, transparent); }
.sc-pos-lab { font-size: 10.5px; color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }

/* turns/legs timeline — each clickable leg reveals its narrative below */
.sc-legs { display: flex; flex-direction: column; gap: 5px; max-height: 320px; overflow-y: auto; padding-right: 4px; scrollbar-width: thin; }
.sc-leg { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 9px;
  background: var(--panel2); border: 1px solid var(--line); border-left: 3px solid var(--lc, var(--muted));
  border-radius: 9px; padding: 7px 11px; cursor: pointer; transition: border-color .16s, background .16s, transform .12s; }
.sc-leg:hover { border-color: color-mix(in srgb, var(--c, var(--link)) 45%, var(--line)); transform: translateX(2px); }
.sc-leg.open { border-color: color-mix(in srgb, var(--c, var(--link)) 60%, var(--line));
  background: color-mix(in srgb, var(--c, var(--link)) 8%, var(--panel2)); }
.sc-leg-k { font-size: 10px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; padding: 2px 7px; border-radius: 999px;
  white-space: nowrap; }
.sc-leg-k.up { color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 15%, transparent); }
.sc-leg-k.down { color: var(--ink-down, var(--down)); background: color-mix(in srgb, var(--down) 15%, transparent); }
.sc-leg-t { font-size: 12px; font-weight: 600; color: var(--text); min-width: 0; }
.sc-leg-t .sc-leg-dt { color: var(--muted); font-weight: 500; font-size: 11px; }
.sc-leg-m { font-size: 11px; font-weight: 700; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.sc-leg-body { font-size: 12.5px; line-height: 1.55; color: var(--text); padding: 2px 4px 8px; display: none; }
.sc-leg-body.show { display: block; }
.sc-leg-body .sc-drv { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 7px; }
.sc-leg-body .sc-drv span { font-size: 10.5px; color: var(--muted); background: var(--panel2); border: 1px solid var(--line);
  border-radius: 999px; padding: 2px 8px; }
.sc-leg-pending { font-size: 11.5px; color: var(--muted); font-style: italic; }

/* leadership rail */
.sc-lead { display: flex; flex-direction: column; gap: 5px; }
.sc-lead-row { display: grid; grid-template-columns: 18px 1fr auto auto; align-items: center; gap: 9px; font-size: 12px; }
.sc-lead-sub { font-size: 10.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.sc-lead-rk { font-size: 11px; font-weight: 800; color: var(--muted); text-align: right; font-variant-numeric: tabular-nums; }
.sc-lead-nm { display: inline-flex; align-items: center; gap: 7px; color: var(--text); font-weight: 600; cursor: pointer; }
.sc-lead-nm .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--c, var(--muted)); flex: none; }
.sc-lead-nm:hover { color: var(--ink-link, var(--link)); }
.sc-lead-rs { font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; }
.sc-lead-rs.pos { color: var(--ink-up, var(--up)); }
.sc-lead-rs.neg { color: var(--ink-down, var(--down)); }
/* rows past the cap, revealed by the "See all N" control below the list (the
   button reuses .xc-more so the two see-more affordances on this panel match) */
.sc-lead-row.sc-lead-hidden { display: none; }

/* scorecard header: keep the (sometimes long) phase badge from overlapping the
   (sometimes 2-line) sector name — let the name column flex/shrink, tags stay top-right */
.sc-page .cc-id { flex: 1 1 auto; min-width: 0; }
.sc-page .cc-nm { overflow-wrap: anywhere; }
.cc-tags { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; flex: none; }
.sc-page .cc-phase { font-size: 10px; }
@media (max-width: 880px) { .sc-page .cyc-cards { grid-template-columns: repeat(auto-fill, minmax(258px, 1fr)); } }

/* Cards read by CYCLE PHASE, not by the (rainbow) per-ETF accent — only the small
   identity dot keeps the ETF colour, so the grid groups visually by where each
   sector sits. --ph = phase hue, --c = ETF accent. */
.sc-page .cyc-card::before { background: var(--ph, var(--c)); }
.sc-page .cyc-card::after { background: radial-gradient(120% 100% at 0% 0%, color-mix(in srgb, var(--ph, var(--c)) 13%, transparent), transparent 55%); }
.sc-page .cyc-card:hover { border-color: color-mix(in srgb, var(--ph) 48%, var(--line));
  box-shadow: 0 10px 30px color-mix(in srgb, var(--ph) 18%, transparent); }
.sc-page .cyc-card.lit { border-color: var(--ph);
  box-shadow: 0 0 0 1px var(--ph), 0 14px 38px color-mix(in srgb, var(--ph) 26%, transparent); }
.sc-page .cc-leg-bar i { background: linear-gradient(90deg, color-mix(in srgb, var(--ph) 48%, transparent), var(--ph)); }

/* a basket card that's currently overlaid on the chart gets a phase-coloured ring */
.sc-page .cyc-card.sel { box-shadow: 0 0 0 1.5px var(--ph), 0 8px 24px color-mix(in srgb, var(--ph) 16%, transparent); }
.sc-page .cyc-card.sel.lit { box-shadow: 0 0 0 1px var(--ph), 0 14px 38px color-mix(in srgb, var(--ph) 26%, transparent); }

/* BUY / SELL transition badge — washed-out + curling up = BUY, stretched + rolling = SELL */
.cc-sig { font-size: 11px; font-weight: 800; letter-spacing: .07em; padding: 2px 9px; border-radius: 6px; color: #fff; line-height: 1.45; }
.cc-sig.buy { background: var(--up); box-shadow: 0 2px 9px color-mix(in srgb, var(--up) 48%, transparent); }
.cc-sig.sell { background: var(--down); box-shadow: 0 2px 9px color-mix(in srgb, var(--down) 48%, transparent); }

/* ---- W3.6: ontology STANCE chip — the one action-toned text (D1 §2.2) --------
   tone → an existing root color token so the zh up/down flip keeps working (A18):
   bullish → --up, bearish → --down (both flip red/green in zh); caution → --warn,
   anticipatory → --accent-ish, neutral → --muted (all flip-neutral). */
.cc-stance { font-size: 11px; font-weight: 800; letter-spacing: .05em; padding: 2px 9px;
  border-radius: 6px; line-height: 1.45; border: 1px solid var(--line); white-space: nowrap; }
.cc-stance.st-bull  { color: var(--ink-up, var(--up));   border-color: color-mix(in srgb, var(--up) 48%, var(--line));   background: color-mix(in srgb, var(--up) 12%, transparent); }
.cc-stance.st-bear  { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 48%, var(--line)); background: color-mix(in srgb, var(--down) 12%, transparent); }
.cc-stance.st-caut  { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 48%, var(--line)); background: color-mix(in srgb, var(--warn) 12%, transparent); }
.cc-stance.st-antic { color: var(--cyan, #38bdf8); border-color: color-mix(in srgb, var(--cyan, #38bdf8) 48%, var(--line)); background: color-mix(in srgb, var(--cyan, #38bdf8) 12%, transparent); }
.cc-stance.st-neu   { color: var(--muted); border-color: var(--line); background: color-mix(in srgb, var(--muted) 8%, transparent); }

/* ---- W3.6: amber "clocks disagree" divergence chip (D1 §2.3) --------------- */
.cc-diverge { font-size: 10.5px; font-weight: 750; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--ink-warn, var(--warn));
  background: color-mix(in srgb, var(--warn) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--line)); }
.cc-diverge-row { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; margin-top: 8px; }
.cc-diverge-note { font-size: 12px; color: var(--muted); line-height: 1.4; flex: 1 1 200px; min-width: 0; }

/* ---- Rotation Command RC-R3: rotation-event + fragmentation card chips ---- */
/* "⟲ handoff active" — a live first-class rotation event inside this sector. Link-toned
   by default; amber (warn) when the event is MAJOR (a cap-share-dominant leg). */
.cc-rot { font-size: 10.5px; font-weight: 750; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--ink-link, var(--link, #38bdf8));
  background: color-mix(in srgb, var(--link, #38bdf8) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--link, #38bdf8) 45%, var(--line)); }
.cc-rot.cc-rot-major { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 14%, transparent);
  border-color: color-mix(in srgb, var(--warn) 48%, var(--line)); }
/* "aggregate not representative" — the sector's legs disagree hard (fragmentation flag). */
.cc-frag { font-size: 10.5px; font-weight: 750; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--muted);
