  border: 1px dashed color-mix(in srgb, var(--muted) 45%, var(--line)); }

/* ---- W3.9: FX-decomposition chips + drawer (INTL/country page only) ------ */
/* currency-driven card chip: a cyan "FX-driven" pill when the latest turn was
   >60% currency — the one-glance "don't read this USD move as an equity turn" flag. */
.cc-fx { font-size: 10.5px; font-weight: 800; letter-spacing: .04em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--cyan, #38bdf8);
  background: color-mix(in srgb, var(--cyan, #38bdf8) 13%, transparent);
  border: 1px solid color-mix(in srgb, var(--cyan, #38bdf8) 45%, var(--line)); }
/* "USD view" pill in the focus head — the USD-ETF cycle lives in the FX drawer below. */
.cc-usdview { font-size: 10.5px; font-weight: 700; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--muted);
  background: color-mix(in srgb, var(--muted) 8%, transparent); border: 1px solid var(--line); }
/* per-leg currency glyph — sits next to the Rally/Selloff verb on flagged legs. */
.sc-leg-fx { margin-left: 5px; font-weight: 800; color: var(--cyan, #38bdf8);
  font-size: 12px; cursor: help; }
/* the drawer body. */
.cc-fx-drawer .cc-fx-intro { font-size: 12.5px; color: var(--muted); line-height: 1.5; margin: 4px 0 10px; }
.cc-fx-drawer .cc-fx-note { font-size: 12.5px; color: var(--text); line-height: 1.5; margin: 10px 0 0; }
.cc-fx-peg { font-size: 12px; font-weight: 650; color: var(--ink-warn, var(--warn)); margin: 8px 0 0; }

/* keep the detail underbar a stable height so clicking a scorecard (which swaps the
   default↔focus panel above it) never shifts the page / the cards below it */
@media (min-width: 881px) { .sc-page .cyc-detail { min-height: 366px; } }

/* ---- thematic baskets rail (Phase 2) — collapsible, category-grouped ----- */
.sc-baskets { margin: 0 2px 12px; }
/* header is now a flex row: [ collapsible toggle .......... ] [ Select all ] */
.sc-bask-head { display: flex; align-items: center; gap: 8px; width: 100%; }
.sc-bask-toggle { display: flex; align-items: center; gap: 9px; flex: 1 1 auto; min-width: 0; cursor: pointer; text-align: left;
  background: var(--panel2); border: 1px solid var(--line); border-radius: 11px; padding: 9px 13px;
  color: var(--text); font-size: 13px; font-weight: 650; transition: border-color .18s, background .18s; }
.sc-bask-toggle:hover { border-color: color-mix(in srgb, var(--link) 40%, var(--line)); }
.sc-bask-ic { font-size: 14px; }
.sc-bask-title { font-weight: 700; }
.sc-bask-n { font-size: 11px; font-weight: 700; color: var(--muted); background: var(--panel); border: 1px solid var(--line);
  border-radius: 999px; padding: 1px 8px; }
.sc-bask-sel { font-size: 11.5px; font-weight: 700; color: var(--ink-link, var(--link)); }
.sc-bask-hint { margin-left: auto; font-size: 11px; color: var(--muted); opacity: .8; }
.sc-bask-caret { font-size: 11px; color: var(--muted); transition: transform .22s var(--ease); margin-left: 4px; }
.sc-baskets.open .sc-bask-caret { transform: rotate(180deg); }
.sc-bask-panel { max-height: 0; overflow: hidden; opacity: 0;
  transition: max-height .32s var(--ease), opacity .25s ease, padding .25s var(--ease); }
.sc-baskets.open .sc-bask-panel { max-height: 60vh; overflow-y: auto; opacity: 1; padding: 12px 4px 2px; scrollbar-width: thin; }
.sc-bask-cat { margin-bottom: 12px; }
.sc-bask-cath { font-size: 10px; font-weight: 700; letter-spacing: .11em; text-transform: uppercase; color: var(--muted);
  margin: 0 0 7px 2px; }
.sc-bask-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.sc-bchip { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: var(--text);
  background: var(--panel); border: 1px solid var(--line); border-radius: 999px; padding: 5px 10px 5px 8px; cursor: pointer;
  white-space: nowrap; transition: transform .16s var(--ease), background .18s, border-color .18s, box-shadow .18s, opacity .18s; }
.sc-bchip .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--c); flex: none; }
.sc-bchip .sc-bdot { width: 6px; height: 6px; border-radius: 50%; flex: none; opacity: .92; }
.sc-bchip:hover { transform: translateY(-1px); border-color: color-mix(in srgb, var(--c) 55%, var(--line));
  box-shadow: 0 3px 12px color-mix(in srgb, var(--c) 22%, transparent); }
.sc-bchip.on { color: #fff; background: color-mix(in srgb, var(--c) 88%, #000 6%); border-color: var(--c);
  box-shadow: 0 3px 14px color-mix(in srgb, var(--c) 34%, transparent); }
html[data-theme="light"] .sc-bchip.on { color: #fff; }
.sc-bchip.on .dot { background: #fff; }
.sc-bchip.foc { box-shadow: 0 0 0 2px var(--c), 0 3px 14px color-mix(in srgb, var(--c) 36%, transparent); }

/* "Where they stand" facet filter: off-phase selector items are removed entirely
   (not greyed), so the chip rail / card grid shows only the active facet's members. */
.sc-page .cyc-chip.sc-hide,
.sc-page .sc-bchip.sc-hide,
.sc-page .cyc-card.sc-hide,
.sc-page .sc-bask-cat.sc-hide { display: none !important; }

/* screen-reader-only live region that announces the filtered selector count */
.sc-page .sc-sr-status { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

/* empty-state note for a "Where they stand" row kept visible with no members
   (Prime entry is always shown, even when nothing qualifies). */
.sc-page .xc-empty { font-size: 11.5px; color: var(--muted); font-style: italic; opacity: .85; padding: 2px 2px 1px; }

/* ============================================================================
   China Sector Cycles — additive elements (provenance frame, washout↔euphoria
   signature, prominent forecast card, evidence-gated pathway odds). All scoped to
   the new markup the China engine emits, so the US page is unaffected.
   ========================================================================== */
.sc-flag { font-size: 13px; filter: saturate(1.1); }

/* EXPERIMENTAL / honest-forecast provenance banner */
.sc-provenance { display: flex; gap: 12px; align-items: flex-start; margin: 0 0 14px;
  padding: 11px 14px; border: 1px solid color-mix(in srgb, var(--warn) 34%, var(--line));
  border-radius: 12px; background: color-mix(in srgb, var(--warn) 7%, var(--panel)); }
.sc-prov-chip { flex: 0 0 auto; font-size: 11px; font-weight: 800; letter-spacing: .06em;
  padding: 3px 9px; border-radius: 7px; color: var(--ink-warn, var(--warn));
  background: color-mix(in srgb, var(--warn) 16%, transparent);
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--line)); white-space: nowrap; }
.sc-prov-text { margin: 0; font-size: 12px; line-height: 1.55; color: var(--muted); }
.sc-prov-text b { color: var(--text); }

/* washout ↔ euphoria signature (focus panel) */
.sc-sig { margin: 12px 0 2px; }
.sc-sig-row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.sc-sig-k { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.sc-sig-v { font-size: 13px; font-weight: 700; font-variant-numeric: tabular-nums; }
.sc-sig-bar { height: 7px; border-radius: 5px; margin: 6px 0 4px; overflow: hidden;
  background: linear-gradient(90deg, color-mix(in srgb, var(--up) 30%, transparent),
    color-mix(in srgb, var(--muted) 22%, transparent), color-mix(in srgb, var(--down) 32%, transparent)); }
.sc-sig-bar i { display: block; height: 100%; width: 0; border-right: 2px solid var(--text); }
.sc-sig-d { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }

/* prominent projected next-turn card */
.sc-fcast { margin-top: 12px; padding: 11px 13px; border-radius: 11px; border: 1px solid var(--line);
  background: var(--panel2, var(--panel)); border-left: 3px solid var(--muted); }
.sc-fcast.pk { border-left-color: var(--down); } .sc-fcast.tr { border-left-color: var(--up); }
.sc-fcast-hd { display: flex; align-items: center; gap: 7px; }
.sc-fcast-ar { font-size: 15px; font-weight: 800; }
.sc-fcast.pk .sc-fcast-ar { color: var(--ink-down, var(--down)); } .sc-fcast.tr .sc-fcast-ar { color: var(--ink-up, var(--up)); }
.sc-fcast-k { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.sc-fcast-date { font-size: 22px; font-weight: 760; font-variant-numeric: tabular-nums; line-height: 1.1; margin: 3px 0; }
.sc-fcast-band { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; }
.sc-fcast-note { font-size: 11px; color: var(--muted); line-height: 1.45; margin-top: 5px; opacity: .92; }

/* evidence-gated conditional forward odds (GS sectors) */
.sc-pathway { border: 1px solid color-mix(in srgb, var(--link) 26%, var(--line));
  border-radius: 12px; background: color-mix(in srgb, var(--link) 5%, var(--panel)); padding: 11px 13px !important; }
.sc-pw-badge { font-size: 12px; opacity: .8; cursor: help; }
.sc-pw-odds { display: flex; align-items: center; gap: 12px; margin: 6px 0 4px; }
.sc-pw-big { font-size: 30px; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1; }
.sc-pw-big.t-up { color: var(--ink-up, var(--up)); } .sc-pw-big.t-down { color: var(--ink-down, var(--down)); } .sc-pw-big.t-mix { color: var(--text); }
.sc-pw-line { font-size: 12px; font-weight: 600; color: var(--text); }
.sc-pw-sub { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; margin-top: 2px; }
.sc-pw-comp { font-size: 10.5px; color: var(--muted); font-variant-numeric: tabular-nums; margin-top: 5px; opacity: .85; cursor: help; }
.sc-pw-legs { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 7px 0 2px; }
.sc-pw-legk { font-size: 10.5px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin-right: 2px; }
.sc-pw-leg { font-size: 11px; padding: 2px 8px; border-radius: 7px; border: 1px solid var(--line); color: var(--muted); }
.sc-pw-leg.pw-bull { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 45%, var(--line)); background: color-mix(in srgb, var(--up) 10%, transparent); }
.sc-pw-leg.pw-bear { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 45%, var(--line)); background: color-mix(in srgb, var(--down) 10%, transparent); }
.sc-pw-narr { font-size: 12px; line-height: 1.5; color: var(--text); margin: 8px 0 0; opacity: .94; }
.sc-pw-caveat { font-size: 10.5px; line-height: 1.45; color: var(--muted); margin: 6px 0 0; font-style: italic; }

@media (max-width: 640px) { .sc-provenance { flex-direction: column; gap: 7px; } }

/* ============================================================================
   Quick "Select all" pickers + the per-item "open its own page" CTA + mobile
   hero-control fixes. Button classes are self-contained (work on every page that
   embeds this chart); the layout/scope tweaks are .sc-page-only so the standalone
   Cycle Intelligence page (.cyc-page, no .sc-page) is untouched.
   ========================================================================== */

/* phase "All phases" reset: pinned to the FAR RIGHT of the Where-they-stand row (its own
   pill), so it no longer reads as a stray chip crammed against the facets — the old
   margin-left:4px butted it right up against the last phase chip and looked like an
   overlap/bug. It is the filter-reset, distinct from the rail's "Select all visible". */
.sc-page .cyc-gall { margin-left: auto; }

/* shared look for the sector-rail + basket-rail "Select all" buttons */
.sc-chip-all, .sc-bask-all { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; cursor: pointer;
  font-size: 12px; font-weight: 700; letter-spacing: .01em; color: var(--ink-link, var(--link)); flex: none;
  background: color-mix(in srgb, var(--link) 12%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--link) 38%, var(--line)); border-radius: 999px; padding: 5px 12px;
  transition: transform .14s var(--ease), background .18s, border-color .18s, box-shadow .18s, color .18s; }
.sc-chip-all:hover, .sc-bask-all:hover { transform: translateY(-1px); color: #fff;
  background: linear-gradient(180deg, color-mix(in srgb, var(--link) 92%, #fff 8%), var(--link));
  border-color: var(--link); box-shadow: 0 3px 14px color-mix(in srgb, var(--link) 34%, transparent); }
.sc-chip-all:active, .sc-bask-all:active { transform: translateY(0); }
html[data-theme="light"] .sc-chip-all:hover, html[data-theme="light"] .sc-bask-all:hover { color: #fff; }
.sca-ic { font-size: 11px; opacity: .92; }

/* sector chips rail scrolls horizontally — pin "Select all" to the left so it stays in reach */
.sc-chip-all { position: sticky; left: 0; z-index: 3;
  box-shadow: 7px 0 10px -6px color-mix(in srgb, var(--panel) 92%, transparent); }

/* prominent CTA in the focus panel's top-left: open this sector/basket's own page */
.sc-fhead-top { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; }
.sc-fhead-top .cyc-back { margin-bottom: 0; }
.sc-openpage { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; text-decoration: none;
  font-size: 12.5px; font-weight: 750; letter-spacing: .01em; color: #fff; padding: 7px 15px; border-radius: 10px; border: 0;
  background: linear-gradient(180deg, color-mix(in srgb, var(--c, var(--link)) 88%, #fff 12%), var(--c, var(--link)));
  box-shadow: 0 2px 10px color-mix(in srgb, var(--c, var(--link)) 40%, transparent);
  transition: transform .12s var(--ease), box-shadow .18s, filter .18s; }
.sc-openpage:hover { transform: translateY(-1px); filter: brightness(1.06);
  box-shadow: 0 5px 18px color-mix(in srgb, var(--c, var(--link)) 52%, transparent); }
.sc-openpage:active { transform: translateY(0); }
html[data-theme="light"] .sc-openpage { color: #fff; }
.sc-op-ic { font-size: 12px; } .sc-op-ar { font-size: 12px; opacity: .85; }

/* ---- mobile: let the hero controls wrap instead of clipping off the right edge ---- */
@media (max-width: 880px) {
  .sc-page .cyc-hero-hd { flex-direction: column; align-items: stretch; gap: 10px; }
  .sc-page .cyc-hero-tools { justify-content: flex-start; gap: 12px 14px; }
  .sc-page .cyc-zoom { flex-wrap: wrap; }
  .sc-page .sc-chip-all { padding: 6px 12px; }
}
/* hide the rail hint on the narrowest screens; the caret then needs the auto-push the
   hint was carrying so it stays right-aligned against the "Select all" button */
@media (max-width: 560px) {
  .sc-page .sc-bask-hint { display: none; }
  .sc-page .sc-bask-caret { margin-left: auto; }
}

/* ============================================================================
   UX overhaul — mobile control reclaim, guided-chart hint, a11y, mode-aware
   legend. All additive / .sc-page|.scc-page-scoped. (See sector_cycles.js.)
   ========================================================================== */

/* the Log/Linear scale is hidden entirely in Cycle-position mode (scale.hidden in JS) —
   defeat the .sc-scale{display:inline-flex} rule so [hidden] actually hides it */
.sc-scale[hidden] { display: none !important; }

/* the plain-language cycle caption beside the Price/Cycle toggle (mobile aid; the
   desktop legend already says this, so it's hidden ≥881px) */
.sc-mode-cap { font-size: 11px; color: var(--muted); white-space: nowrap; }
@media (min-width: 881px) { .sc-mode-cap { display: none; } }

/* "Chart options" disclosure: desktop shows scale+legend+zoom inline (toggle hidden);
   mobile folds them behind one tap so the chart isn't buried under a 4-row control wall */
.sc-adv-toggle { display: none; }
.sc-advanced, .sc-adv-body { display: inline-flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.cyc-leg-hint { color: var(--ink-link, var(--link)); font-weight: 600; }

/* mode-aware legend band swatches reuse cycle.css .lc; nothing extra needed */

@media (max-width: 880px) {
  /* stack the hero tools so Price/Cycle + caption + "Chart options" read top-to-bottom */
  .sc-page .cyc-hero-tools { flex-direction: column; align-items: stretch; gap: 10px; }
  .sc-page .sc-modes { width: fit-content; }
  .sc-page .sc-advanced { display: block; width: 100%; }
  .sc-page .sc-adv-toggle { display: inline-flex; align-items: center; gap: 7px; min-height: 40px; width: fit-content;
    font-size: 12.5px; font-weight: 700; color: var(--muted); background: var(--panel2);
    border: 1px solid var(--line); border-radius: 10px; padding: 8px 13px; cursor: pointer; }
  .sc-page .sc-adv-toggle::after { content: "▾"; font-size: 11px; transition: transform .2s var(--ease); }
  .sc-page .sc-advanced.open .sc-adv-toggle::after { transform: rotate(180deg); }
  .sc-page .sc-adv-body { display: none; }
  .sc-page .sc-advanced.open .sc-adv-body { display: flex; flex-direction: column; align-items: stretch; gap: 12px; margin-top: 10px; }

  /* 40px minimum touch targets across every chart/phase/zoom/chip control */
  .sc-page .sc-mbtn, .sc-page .sc-sbtn, .sc-page .cyc-zbtn, .sc-page .cyc-gchip,
  .sc-page .sc-bchip, .sc-page .sc-bask-all, .sc-page .sc-chip-all, .sc-page .cyc-gall,
  .sc-page .cyc-chip, .sc-page .mini-chip {
    min-height: 40px; display: inline-flex; align-items: center; }
  .sc-page .sc-modes, .sc-page .sc-scale { padding: 4px; }

  /* phase filter = ONE horizontal-scroll row (was 132px of wrapped chips) */
  .sc-page #sc-groups { flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch;
    scrollbar-width: none; padding-bottom: 6px; }
  .sc-page #sc-groups::-webkit-scrollbar { display: none; }
  .sc-page #sc-groups .cyc-glabel, .sc-page #sc-groups .cyc-gchip { flex: none; }
  .sc-page .cyc-gall { margin-left: 8px; flex: none; }     /* keep "All phases" inline, not auto-pushed */

  /* dim helper labels were barely legible at 10.5px+opacity — restore contrast */
  .sc-page .cyc-zhint { opacity: 1; font-size: 11px; }
}

/* one-shot onboarding pill (top-left over the chart) — distinct from the centered
   empty-state hint; cleared on first interaction by setFocus() */
.sc-hint-tap { inset: auto; top: 10px; left: 10px; right: 10px; bottom: auto; display: block;
  pointer-events: none; text-align: left; font-size: 12px; line-height: 1.45; color: var(--text);
  background: color-mix(in srgb, var(--panel) 90%, transparent); backdrop-filter: blur(6px);
  border: 1px solid color-mix(in srgb, var(--link) 34%, var(--line)); border-radius: 11px;
  padding: 8px 11px; max-width: 360px; box-shadow: 0 6px 20px rgba(0,0,0,.24);
  animation: sc-hint-in .3s var(--ease); z-index: 4; }
@keyframes sc-hint-in { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: none; } }

/* ---- Cycle DNA panel — the front-loaded "history rhymes" / predictive read ---- */
/* padding-left clears the accent border-left so the heading/text never touch the blue rule */
.sc-dna { border-left: 3px solid color-mix(in srgb, var(--link) 55%, var(--line)); padding-left: 13px; }
.sc-dna .cyc-lbl { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.sc-dna-conf { font-size: 10px; font-weight: 600; letter-spacing: .02em; text-transform: uppercase;
  padding: 1px 7px; border-radius: 999px; border: 1px solid var(--line); color: var(--muted); background: var(--panel2); }
.sc-dna-conf.high { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 45%, var(--line)); }
.sc-dna-conf.low { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 45%, var(--line)); }
.sc-dna-sum { font-size: 12.5px; line-height: 1.55; color: var(--text); margin: 6px 0 0; opacity: .96; }
.sc-dna-drv { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.sc-dna-drv span { font-size: 10.5px; color: var(--text); background: color-mix(in srgb, var(--link) 9%, var(--panel2));
  border: 1px solid color-mix(in srgb, var(--link) 24%, var(--line)); border-radius: 999px; padding: 2px 9px; }
.sc-dna-sig { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 14px; margin-top: 11px; }
.sc-dna-col .sc-dna-h { font-size: 10.5px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; margin-bottom: 4px; }
.sc-dna-col.b .sc-dna-h { color: var(--ink-up, var(--up)); } .sc-dna-col.t .sc-dna-h { color: var(--ink-down, var(--down)); }
.sc-dna-col ul { margin: 0; padding-left: 15px; }
.sc-dna-col li { font-size: 11.5px; line-height: 1.5; color: var(--text); opacity: .9; margin-bottom: 2px; }
.sc-dna-rhythm { margin-top: 10px; font-size: 11px; color: var(--muted); }
.sc-dna-analog { margin-top: 9px; font-size: 12px; line-height: 1.5; color: var(--text);
  padding: 8px 11px; background: color-mix(in srgb, var(--link) 7%, var(--panel2));
  border: 1px solid color-mix(in srgb, var(--link) 20%, var(--line)); border-radius: 9px; }
.sc-dna-ana-k { font-weight: 700; color: var(--ink-link, var(--link)); margin-right: 4px; }
@media (max-width: 620px) { .sc-dna-sig { grid-template-columns: 1fr; } }
.sc-dna-body { max-height: 9.5em; overflow: hidden; position: relative; }
.sc-dna-body::after { content: ""; position: absolute; bottom: 0; left: 0; right: 0; height: 2.5em;
  background: linear-gradient(to bottom, transparent, var(--panel)); pointer-events: none; }
.sc-dna-body.open { max-height: none; }
.sc-dna-body.open::after { display: none; }
.sc-dna-more { display: block; font-size: 10.5px; font-weight: 700; color: var(--muted); background: none; border: none;
  cursor: pointer; padding: 3px 0 0; letter-spacing: .02em; text-align: left; }
.sc-dna-more:hover { color: var(--ink-link, var(--link)); }
.sc-dna-more[hidden] { display: none; }

/* visible focus ring for keyboard users across both page chromes */
.sc-page :focus-visible, .scc-page :focus-visible { outline: 2px solid var(--link); outline-offset: 2px; border-radius: 7px; }

/* honor reduced-motion for the hub chrome + the onboarding pill (the chart engine is
   gated in JS; cycle.css already covers .cyc-page) */
@media (prefers-reduced-motion: reduce) {
  .scc-page *, .sc-page .sc-hint-tap { animation: none !important; transition: none !important; }
}


/* ---- UI-HZ-1: calibrated turn-hazard surfaces --------------------------------
   Card chip (.cc-hz) + detail-sidebar row set (.sc-hazard reuses .cyc-hazard from
   cycle.css, incl. the hz-badge PASS/PRIOR evidence classes). PRIOR cells are
   muted — a KM base rate is context, not a validated model output. */
.cc-hz { display: flex; align-items: center; gap: 5px; font-size: 11px;
  color: var(--text); font-variant-numeric: tabular-nums; cursor: help; }
.cc-hz .cc-hz-k { font-size: 9.5px; font-weight: 700; letter-spacing: .05em;
  text-transform: uppercase; color: var(--muted); }
.cc-hz b { font-weight: 700; }
.cc-hz.hz-muted { color: var(--muted); opacity: .8; }
.sc-page .sc-hazard { margin-top: 12px; margin-bottom: 0; }

rules.new:
/* ============================================================================
   sector_cycles.css — Sector Cycle Intelligence · deltas over cycle.css
   ----------------------------------------------------------------------------
   This page reuses the WHOLE cycle.css design system (.cyc-* + .mmc-*). Only the
   net-new chrome lives here: the Price↔Cycle mode + Log/Linear scale segmented
   controls, peak/trough legend glyphs, the focused-sector narrative timeline, the
   cross-sector leadership rail, and the clickable narrative bands.
   ========================================================================== */

/* Opaque page canvas — theme.css paints its site-wide "aurora" backdrop OVER an
   expected body { background:var(--bg) }, so the page must set it (robust in any
   browser regardless of the default canvas colour). */
body { background: var(--bg); color: var(--text); }

/* ---- section tabs: Sector ETFs vs Thematic Baskets (two independent views) -- */
.sc-tabs { display: inline-flex; gap: 4px; background: var(--panel2); border: 1px solid var(--line);
  border-radius: 13px; padding: 4px; margin: 8px 2px 2px; }
.sc-tab { font-size: 13.5px; font-weight: 700; color: var(--muted); background: transparent; border: 0;
  border-radius: 10px; padding: 8px 17px; cursor: pointer; display: inline-flex; align-items: center; gap: 7px;
  transition: color .18s, background .18s, box-shadow .18s, transform .1s; }
.sc-tab i { font-style: normal; font-size: 11px; font-weight: 700; color: var(--muted); background: var(--panel);
  border: 1px solid var(--line); border-radius: 999px; padding: 1px 7px; }
.sc-tab:hover { color: var(--text); }
.sc-tab:active { transform: translateY(1px); }
.sc-tab.on { color: var(--text); background: var(--panel);
  box-shadow: 0 1px 2px rgba(0,0,0,.22), 0 3px 12px color-mix(in srgb, var(--link) 16%, transparent); }
.sc-tab.on i { color: var(--ink-link, var(--link)); border-color: color-mix(in srgb, var(--link) 42%, var(--line)); }
@media (max-width: 560px) { .sc-tabs { flex-wrap: wrap; } }

/* ---- page-level universe toggle (Sector ETFs / Shenwan vs Thematic Baskets) -------
   On the Sector Central hubs this toggle drives BOTH the cycle map AND the conviction
   board, so it's raised out of the chart card to a prominent, labelled primary control
   that sits right above the cycle map. Scoped to .scc-page so the standalone cycles
   pages (.cyc-page, no .scc-page) keep their original compact tabs. */
.scc-page .scc-universe { display: flex; align-items: center; gap: 13px; flex-wrap: wrap; margin: 20px 0 8px; }
.scc-page .scc-universe-lab { font-size: 11px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; color: var(--muted); }
.scc-page .scc-universe .sc-tabs { margin: 0; padding: 5px; border-radius: 15px; gap: 5px; }
.scc-page .scc-universe .sc-tab { font-size: 15px; font-weight: 750; padding: 11px 24px; border-radius: 12px; }
.scc-page .scc-universe .sc-tab i { font-size: 12px; }
@media (max-width: 560px) { .scc-page .scc-universe .sc-tabs { width: 100%; }
  .scc-page .scc-universe .sc-tab { flex: 1; justify-content: center; padding: 11px 12px; } }

/* chart empty-state hint (baskets section with nothing selected yet) */
.sc-chartwrap { position: relative; }
.sc-chart-hint { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  pointer-events: none; color: var(--muted); font-size: 13.5px; line-height: 1.6; text-align: center; padding: 0 26px; }
.sc-chart-hint[hidden] { display: none; }

/* ---- a bigger, dominant hero chart ------------------------------------- */
#sc-chart { width: 100%; height: 500px; }
@media (min-width: 881px) { #sc-chart { height: 600px; } }
@media (min-width: 1400px) { #sc-chart { height: 660px; } }
@media (max-width: 880px) { #sc-chart { height: min(56vh, 440px); } }

/* ---- first-paint loading skeleton -------------------------------------- */
/* #sc-chart already reserves its height above, so there's no reflow when mm_charts appends the
   SVG (H = clientHeight || data-h — clientHeight is the CSS height here). This only paints a
   loading affordance INTO that reserved box so users don't stare at a blank void while the core
   data + engine + orchestrator download. The :empty rule vanishes the instant mm_charts appends
   the <svg>. Tokens only (--panel/--line/--muted) — no new palette. */
#sc-chart:empty {
  position: relative;
  border-radius: 12px;
  background:
    linear-gradient(100deg,
      transparent 0%,
      color-mix(in srgb, var(--panel) 55%, transparent) 40%,
      color-mix(in srgb, var(--line) 40%, transparent) 50%,
      color-mix(in srgb, var(--panel) 55%, transparent) 60%,
      transparent 100%),
    color-mix(in srgb, var(--panel) 35%, transparent);
  background-size: 220% 100%, 100% 100%;
  background-repeat: no-repeat;
  animation: sc-chart-shimmer 1.5s ease-in-out infinite;
}
#sc-chart:empty::after {
  content: "Loading the cycle map…";
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  color: var(--muted); font-size: 13px; letter-spacing: .01em;
}
html[data-lang="zh"] #sc-chart:empty::after { content: "周期图加载中…"; }
@keyframes sc-chart-shimmer { 0% { background-position: 120% 0, 0 0; } 100% { background-position: -120% 0, 0 0; } }
@media (prefers-reduced-motion: reduce) {
  #sc-chart:empty { animation: none; background: color-mix(in srgb, var(--panel) 35%, transparent); }
}
/* let the hero breathe + lift the chart inside its card */
.sc-page .cyc-hero { padding: 18px 18px 12px; }

/* ---- segmented controls (scale + mode) — premium pill switch ------------ */
.sc-modes, .sc-scale { display: inline-flex; align-items: center; gap: 3px; background: var(--panel2);
  border: 1px solid var(--line); border-radius: 10px; padding: 3px; box-shadow: inset 0 1px 2px rgba(0,0,0,.18); }
html[data-theme="light"] .sc-modes, html[data-theme="light"] .sc-scale { box-shadow: inset 0 1px 2px rgba(20,30,50,.05); }
.sc-mbtn, .sc-sbtn { font-size: 12px; font-weight: 650; letter-spacing: .01em; color: var(--muted); background: transparent;
  border: 0; border-radius: 7px; padding: 5px 13px; cursor: pointer; white-space: nowrap;
  transition: color .18s, background .18s, box-shadow .18s, transform .1s; }
.sc-mbtn:hover, .sc-sbtn:hover { color: var(--text); }
.sc-mbtn:active, .sc-sbtn:active { transform: translateY(1px); }
.sc-mbtn.on, .sc-sbtn.on { color: #fff;
  background: linear-gradient(180deg, color-mix(in srgb, var(--link) 90%, #fff 10%), var(--link));
  box-shadow: 0 1px 2px rgba(0,0,0,.28), 0 2px 10px color-mix(in srgb, var(--link) 36%, transparent); }
html[data-theme="light"] .sc-mbtn.on, html[data-theme="light"] .sc-sbtn.on { color: #fff; }
/* scale is meaningless in cycle-position mode → dim + lock, but keep its footprint (no layout shift) */
.sc-scale.disabled { opacity: .4; filter: saturate(.35); pointer-events: none; }

/* ---- "where they stand" phase chips — reactive like the sector chips ---- */
.sc-page .cyc-gchip { transition: color .18s, background .2s, border-color .2s, box-shadow .2s, transform .14s var(--ease); }
.sc-page .cyc-gchip:not(.on) { opacity: .62; }
.sc-page .cyc-gchip:not(.on):hover { opacity: 1; transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--ph, var(--muted)) 60%, var(--line));
  box-shadow: 0 3px 12px color-mix(in srgb, var(--ph, var(--muted)) 22%, transparent); }
/* selected chip: ink-on-tint, not white-on-hue — the phase hues are dark-theme
   bright (#2dd4bf teal worst: white sat at 2.46:1 dark / 1.09:1 light, the least
   legible element in the W3 audit). Same hue identity, 4.5–6.4:1 in both themes;
   matches the recipe the SI V2 workspace already applies to its embedded copy. */
.sc-page .cyc-gchip.on { color: color-mix(in srgb, var(--ph, var(--link)) 38%, var(--text)); opacity: 1; transform: translateY(-1px);
  background: color-mix(in srgb, var(--ph, var(--link)) 12%, var(--panel));
  border-color: color-mix(in srgb, var(--ph, var(--link)) 55%, var(--line));
  box-shadow: 0 4px 16px color-mix(in srgb, var(--ph, var(--link)) 24%, transparent); }
.sc-page .cyc-gchip.on .gdot { background: currentColor; box-shadow: none; }
.sc-page .cyc-gchip.on i { opacity: .95; color: inherit; }

/* legend peak/trough glyphs */
.cyc-legend .lm { width: 0; height: 0; }
.cyc-legend .lm-pk { border-left: 5px solid transparent; border-right: 5px solid transparent; border-bottom: 7px solid var(--warn); }
.cyc-legend .lm-tr { border-left: 5px solid transparent; border-right: 5px solid transparent; border-top: 7px solid var(--up); }

/* the price-mode markers (peaks/troughs) always show for the focused line; the
   mm_charts CSS only reveals peak/trough glyphs on focus — exactly what we want. */
.sc-page .mmc-series.is-focus .mmc-mk-peak, .sc-page .mmc-series.is-focus .mmc-mk-trough { opacity: 1; }

/* clickable narrative bands (focused sector, price mode) */
.sc-page .mmc-vband { cursor: pointer; transition: opacity .2s ease; }
.sc-page .mmc-vband:hover { opacity: .2 !important; }
.sc-page .mmc-vlabel { cursor: pointer; }

/* ---- focus panel: leadership + turns/legs timeline ---------------------- */
.sc-pos { display: flex; align-items: center; gap: 10px; margin: 2px 0 4px; }
.sc-pos-bar { flex: 1; height: 7px; border-radius: 99px; background: linear-gradient(90deg,
  color-mix(in srgb, var(--up) 40%, transparent), color-mix(in srgb, var(--muted) 30%, transparent),
  color-mix(in srgb, var(--warn) 55%, transparent)); position: relative; border: 1px solid var(--line); }
.sc-pos-dot { position: absolute; top: 50%; width: 13px; height: 13px; border-radius: 50%; background: var(--c, var(--link));
  transform: translate(-50%, -50%); box-shadow: 0 0 0 3px var(--panel), 0 0 12px color-mix(in srgb, var(--c, var(--link)) 60%, transparent); }
.sc-pos-lab { font-size: 10.5px; color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }

/* turns/legs timeline — each clickable leg reveals its narrative below */
.sc-legs { display: flex; flex-direction: column; gap: 5px; max-height: 320px; overflow-y: auto; padding-right: 4px; scrollbar-width: thin; }
.sc-leg { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 9px;
  background: var(--panel2); border: 1px solid var(--line); 
  border-radius: 9px; padding: 7px 11px; cursor: pointer; transition: border-color .16s, background .16s, transform .12s; }
.sc-leg:hover { border-color: color-mix(in srgb, var(--c, var(--link)) 45%, var(--line)); transform: translateX(2px); }
.sc-leg.open { border-color: color-mix(in srgb, var(--c, var(--link)) 60%, var(--line));
  background: color-mix(in srgb, var(--c, var(--link)) 8%, var(--panel2)); }
.sc-leg-k { font-size: 10px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; padding: 2px 7px; border-radius: 999px;
  white-space: nowrap; }
.sc-leg-k.up { color: var(--ink-up, var(--up)); background: color-mix(in srgb, var(--up) 15%, transparent); }
.sc-leg-k.down { color: var(--ink-down, var(--down)); background: color-mix(in srgb, var(--down) 15%, transparent); }
.sc-leg-t { font-size: 12px; font-weight: 600; color: var(--text); min-width: 0; }
.sc-leg-t .sc-leg-dt { color: var(--muted); font-weight: 500; font-size: 11px; }
.sc-leg-m { font-size: 11px; font-weight: 700; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.sc-leg-body { font-size: 12.5px; line-height: 1.55; color: var(--text); padding: 2px 4px 8px; display: none; }
.sc-leg-body.show { display: block; }
.sc-leg-body .sc-drv { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 7px; }
.sc-leg-body .sc-drv span { font-size: 10.5px; color: var(--muted); background: var(--panel2); border: 1px solid var(--line);
  border-radius: 999px; padding: 2px 8px; }
.sc-leg-pending { font-size: 11.5px; color: var(--muted); font-style: italic; }

/* leadership rail */
.sc-lead { display: flex; flex-direction: column; gap: 5px; }
.sc-lead-row { display: grid; grid-template-columns: 18px 1fr auto auto; align-items: center; gap: 9px; font-size: 12px; }
.sc-lead-sub { font-size: 10.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.sc-lead-rk { font-size: 11px; font-weight: 800; color: var(--muted); text-align: right; font-variant-numeric: tabular-nums; }
.sc-lead-nm { display: inline-flex; align-items: center; gap: 7px; color: var(--text); font-weight: 600; cursor: pointer; }
.sc-lead-nm .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--c, var(--muted)); flex: none; }
.sc-lead-nm:hover { color: var(--ink-link, var(--link)); }
.sc-lead-rs { font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; }
.sc-lead-rs.pos { color: var(--ink-up, var(--up)); }
.sc-lead-rs.neg { color: var(--ink-down, var(--down)); }
/* rows past the cap, revealed by the "See all N" control below the list (the
   button reuses .xc-more so the two see-more affordances on this panel match) */
.sc-lead-row.sc-lead-hidden { display: none; }

/* scorecard header: keep the (sometimes long) phase badge from overlapping the
   (sometimes 2-line) sector name — let the name column flex/shrink, tags stay top-right */
.sc-page .cc-id { flex: 1 1 auto; min-width: 0; }
.sc-page .cc-nm { overflow-wrap: anywhere; }
.cc-tags { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; flex: none; }
.sc-page .cc-phase { font-size: 10px; }
@media (max-width: 880px) { .sc-page .cyc-cards { grid-template-columns: repeat(auto-fill, minmax(258px, 1fr)); } }

/* Cards read by CYCLE PHASE, not by the (rainbow) per-ETF accent — only the small
   identity dot keeps the ETF colour, so the grid groups visually by where each
   sector sits. --ph = phase hue, --c = ETF accent. */
.sc-page .cyc-card::before { background: var(--ph, var(--c)); }
.sc-page .cyc-card::after { background: radial-gradient(120% 100% at 0% 0%, color-mix(in srgb, var(--ph, var(--c)) 13%, transparent), transparent 55%); }
.sc-page .cyc-card:hover { border-color: color-mix(in srgb, var(--ph) 48%, var(--line));
  box-shadow: 0 10px 30px color-mix(in srgb, var(--ph) 18%, transparent); }
.sc-page .cyc-card.lit { border-color: var(--ph);
  box-shadow: 0 0 0 1px var(--ph), 0 14px 38px color-mix(in srgb, var(--ph) 26%, transparent); }
.sc-page .cc-leg-bar i { background: linear-gradient(90deg, color-mix(in srgb, var(--ph) 48%, transparent), var(--ph)); }

/* a basket card that's currently overlaid on the chart gets a phase-coloured ring */
.sc-page .cyc-card.sel { box-shadow: 0 0 0 1.5px var(--ph), 0 8px 24px color-mix(in srgb, var(--ph) 16%, transparent); }
.sc-page .cyc-card.sel.lit { box-shadow: 0 0 0 1px var(--ph), 0 14px 38px color-mix(in srgb, var(--ph) 26%, transparent); }

/* BUY / SELL transition badge — washed-out + curling up = BUY, stretched + rolling = SELL */
.cc-sig { font-size: 11px; font-weight: 800; letter-spacing: .07em; padding: 2px 9px; border-radius: 6px; color: #fff; line-height: 1.45; }
.cc-sig.buy { background: var(--up); box-shadow: 0 2px 9px color-mix(in srgb, var(--up) 48%, transparent); }
.cc-sig.sell { background: var(--down); box-shadow: 0 2px 9px color-mix(in srgb, var(--down) 48%, transparent); }

/* ---- W3.6: ontology STANCE chip — the one action-toned text (D1 §2.2) --------
   tone → an existing root color token so the zh up/down flip keeps working (A18):
   bullish → --up, bearish → --down (both flip red/green in zh); caution → --warn,
   anticipatory → --accent-ish, neutral → --muted (all flip-neutral). */
.cc-stance { font-size: 11px; font-weight: 800; letter-spacing: .05em; padding: 2px 9px;
  border-radius: 6px; line-height: 1.45; border: 1px solid var(--line); white-space: nowrap; }
.cc-stance.st-bull  { color: var(--ink-up, var(--up));   border-color: color-mix(in srgb, var(--up) 48%, var(--line));   background: color-mix(in srgb, var(--up) 12%, transparent); }
.cc-stance.st-bear  { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 48%, var(--line)); background: color-mix(in srgb, var(--down) 12%, transparent); }
.cc-stance.st-caut  { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 48%, var(--line)); background: color-mix(in srgb, var(--warn) 12%, transparent); }
.cc-stance.st-antic { color: var(--cyan, #38bdf8); border-color: color-mix(in srgb, var(--cyan, #38bdf8) 48%, var(--line)); background: color-mix(in srgb, var(--cyan, #38bdf8) 12%, transparent); }
.cc-stance.st-neu   { color: var(--muted); border-color: var(--line); background: color-mix(in srgb, var(--muted) 8%, transparent); }

/* ---- W3.6: amber "clocks disagree" divergence chip (D1 §2.3) --------------- */
.cc-diverge { font-size: 10.5px; font-weight: 750; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--ink-warn, var(--warn));
  background: color-mix(in srgb, var(--warn) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--line)); }
.cc-diverge-row { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; margin-top: 8px; }
.cc-diverge-note { font-size: 12px; color: var(--muted); line-height: 1.4; flex: 1 1 200px; min-width: 0; }

/* ---- Rotation Command RC-R3: rotation-event + fragmentation card chips ---- */
/* "⟲ handoff active" — a live first-class rotation event inside this sector. Link-toned
   by default; amber (warn) when the event is MAJOR (a cap-share-dominant leg). */
.cc-rot { font-size: 10.5px; font-weight: 750; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--ink-link, var(--link, #38bdf8));
  background: color-mix(in srgb, var(--link, #38bdf8) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--link, #38bdf8) 45%, var(--line)); }
.cc-rot.cc-rot-major { color: var(--ink-warn, var(--warn)); background: color-mix(in srgb, var(--warn) 14%, transparent);
  border-color: color-mix(in srgb, var(--warn) 48%, var(--line)); }
/* "aggregate not representative" — the sector's legs disagree hard (fragmentation flag). */
.cc-frag { font-size: 10.5px; font-weight: 750; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--muted);
  background: color-mix(in srgb, var(--muted) 10%, transparent);
  border: 1px dashed color-mix(in srgb, var(--muted) 45%, var(--line)); }

/* ---- W3.9: FX-decomposition chips + drawer (INTL/country page only) ------ */
/* currency-driven card chip: a cyan "FX-driven" pill when the latest turn was
   >60% currency — the one-glance "don't read this USD move as an equity turn" flag. */
.cc-fx { font-size: 10.5px; font-weight: 800; letter-spacing: .04em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--cyan, #38bdf8);
  background: color-mix(in srgb, var(--cyan, #38bdf8) 13%, transparent);
  border: 1px solid color-mix(in srgb, var(--cyan, #38bdf8) 45%, var(--line)); }
/* "USD view" pill in the focus head — the USD-ETF cycle lives in the FX drawer below. */
.cc-usdview { font-size: 10.5px; font-weight: 700; letter-spacing: .03em; padding: 2px 8px;
  border-radius: 6px; line-height: 1.45; white-space: nowrap; color: var(--muted);
  background: color-mix(in srgb, var(--muted) 8%, transparent); border: 1px solid var(--line); }
/* per-leg currency glyph — sits next to the Rally/Selloff verb on flagged legs. */
.sc-leg-fx { margin-left: 5px; font-weight: 800; color: var(--cyan, #38bdf8);
  font-size: 12px; cursor: help; }
/* the drawer body. */
.cc-fx-drawer .cc-fx-intro { font-size: 12.5px; color: var(--muted); line-height: 1.5; margin: 4px 0 10px; }
.cc-fx-drawer .cc-fx-note { font-size: 12.5px; color: var(--text); line-height: 1.5; margin: 10px 0 0; }
.cc-fx-peg { font-size: 12px; font-weight: 650; color: var(--ink-warn, var(--warn)); margin: 8px 0 0; }

/* keep the detail underbar a stable height so clicking a scorecard (which swaps the
   default↔focus panel above it) never shifts the page / the cards below it */
@media (min-width: 881px) { .sc-page .cyc-detail { min-height: 366px; } }

/* ---- thematic baskets rail (Phase 2) — collapsible, category-grouped ----- */
.sc-baskets { margin: 0 2px 12px; }
/* header is now a flex row: [ collapsible toggle .......... ] [ Select all ] */
.sc-bask-head { display: flex; align-items: center; gap: 8px; width: 100%; }
.sc-bask-toggle { display: flex; align-items: center; gap: 9px; flex: 1 1 auto; min-width: 0; cursor: pointer; text-align: left;
  background: var(--panel2); border: 1px solid var(--line); border-radius: 11px; padding: 9px 13px;
  color: var(--text); font-size: 13px; font-weight: 650; transition: border-color .18s, background .18s; }
.sc-bask-toggle:hover { border-color: color-mix(in srgb, var(--link) 40%, var(--line)); }
.sc-bask-ic { font-size: 14px; }
.sc-bask-title { font-weight: 700; }
