  box-shadow: 0 3px 12px color-mix(in srgb, var(--c) 22%, transparent); }
.sc-bchip.on { color: #fff; background: color-mix(in srgb, var(--c) 88%, #000 6%); border-color: var(--c);
  box-shadow: 0 3px 14px color-mix(in srgb, var(--c) 34%, transparent); }
