   the new markup the China engine emits, so the US page is unaffected.
   ========================================================================== */
.sc-flag { font-size: 13px; filter: saturate(1.1); }

/* EXPERIMENTAL / honest-forecast provenance banner */
.sc-provenance { display: flex; gap: 12px; align-items: flex-start; margin: 0 0 14px;
  padding: 11px 14px; border: 1px solid color-mix(in srgb, var(--warn) 34%, var(--line));
  border-radius: 12px; background: color-mix(in srgb, var(--warn) 7%, var(--panel)); }
.sc-prov-chip { flex: 0 0 auto; font-size: 11px; font-weight: 800; letter-spacing: .06em;
  padding: 3px 9px; border-radius: 7px; color: var(--ink-warn, var(--warn));
  background: color-mix(in srgb, var(--warn) 16%, transparent);
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--line)); white-space: nowrap; }
.sc-prov-text { margin: 0; font-size: 12px; line-height: 1.55; color: var(--muted); }
.sc-prov-text b { color: var(--text); }

/* washout ↔ euphoria signature (focus panel) */
.sc-sig { margin: 12px 0 2px; }
.sc-sig-row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.sc-sig-k { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.sc-sig-v { font-size: 13px; font-weight: 700; font-variant-numeric: tabular-nums; }
.sc-sig-bar { height: 7px; border-radius: 5px; margin: 6px 0 4px; overflow: hidden;
  background: linear-gradient(90deg, color-mix(in srgb, var(--up) 30%, transparent),
    color-mix(in srgb, var(--muted) 22%, transparent), color-mix(in srgb, var(--down) 32%, transparent)); }
.sc-sig-bar i { display: block; height: 100%; width: 0; border-right: 2px solid var(--text); }
.sc-sig-d { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }

/* prominent projected next-turn card */
.sc-fcast { margin-top: 12px; padding: 11px 13px; border-radius: 11px; border: 1px solid var(--line);
  background: var(--panel2, var(--panel));  }
.sc-fcast.tr {  }
.sc-fcast-hd { display: flex; align-items: center; gap: 7px; }
.sc-fcast-ar { font-size: 15px; font-weight: 800; }
.sc-fcast.pk .sc-fcast-ar { color: var(--ink-down, var(--down)); } .sc-fcast.tr .sc-fcast-ar { color: var(--ink-up, var(--up)); }
.sc-fcast-k { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.sc-fcast-date { font-size: 22px; font-weight: 760; font-variant-numeric: tabular-nums; line-height: 1.1; margin: 3px 0; }
.sc-fcast-band { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; }
.sc-fcast-note { font-size: 11px; color: var(--muted); line-height: 1.45; margin-top: 5px; opacity: .92; }

/* evidence-gated conditional forward odds (GS sectors) */
.sc-pathway { border: 1px solid color-mix(in srgb, var(--link) 26%, var(--line));
  border-radius: 12px; background: color-mix(in srgb, var(--link) 5%, var(--panel)); padding: 11px 13px !important; }
.sc-pw-badge { font-size: 12px; opacity: .8; cursor: help; }
.sc-pw-odds { display: flex; align-items: center; gap: 12px; margin: 6px 0 4px; }
.sc-pw-big { font-size: 30px; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1; }
.sc-pw-big.t-up { color: var(--ink-up, var(--up)); } .sc-pw-big.t-down { color: var(--ink-down, var(--down)); } .sc-pw-big.t-mix { color: var(--text); }
.sc-pw-line { font-size: 12px; font-weight: 600; color: var(--text); }
.sc-pw-sub { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; margin-top: 2px; }
.sc-pw-comp { font-size: 10.5px; color: var(--muted); font-variant-numeric: tabular-nums; margin-top: 5px; opacity: .85; cursor: help; }
.sc-pw-legs { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 7px 0 2px; }
.sc-pw-legk { font-size: 10.5px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin-right: 2px; }
.sc-pw-leg { font-size: 11px; padding: 2px 8px; border-radius: 7px; border: 1px solid var(--line); color: var(--muted); }
.sc-pw-leg.pw-bull { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 45%, var(--line)); background: color-mix(in srgb, var(--up) 10%, transparent); }
.sc-pw-leg.pw-bear { color: var(--ink-down, var(--down)); border-color: color-mix(in srgb, var(--down) 45%, var(--line)); background: color-mix(in srgb, var(--down) 10%, transparent); }
.sc-pw-narr { font-size: 12px; line-height: 1.5; color: var(--text); margin: 8px 0 0; opacity: .94; }
.sc-pw-caveat { font-size: 10.5px; line-height: 1.45; color: var(--muted); margin: 6px 0 0; font-style: italic; }

@media (max-width: 640px) { .sc-provenance { flex-direction: column; gap: 7px; } }

/* ============================================================================
   Quick "Select all" pickers + the per-item "open its own page" CTA + mobile
   hero-control fixes. Button classes are self-contained (work on every page that
   embeds this chart); the layout/scope tweaks are .sc-page-only so the standalone
   Cycle Intelligence page (.cyc-page, no .sc-page) is untouched.
   ========================================================================== */

/* phase "All phases" reset: pinned to the FAR RIGHT of the Where-they-stand row (its own
   pill), so it no longer reads as a stray chip crammed against the facets — the old
   margin-left:4px butted it right up against the last phase chip and looked like an
   overlap/bug. It is the filter-reset, distinct from the rail's "Select all visible". */
.sc-page .cyc-gall { margin-left: auto; }

/* shared look for the sector-rail + basket-rail "Select all" buttons */
.sc-chip-all, .sc-bask-all { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; cursor: pointer;
  font-size: 12px; font-weight: 700; letter-spacing: .01em; color: var(--ink-link, var(--link)); flex: none;
  background: color-mix(in srgb, var(--link) 12%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--link) 38%, var(--line)); border-radius: 999px; padding: 5px 12px;
  transition: transform .14s var(--ease), background .18s, border-color .18s, box-shadow .18s, color .18s; }
.sc-chip-all:hover, .sc-bask-all:hover { transform: translateY(-1px); color: #fff;
  background: linear-gradient(180deg, color-mix(in srgb, var(--link) 92%, #fff 8%), var(--link));
  border-color: var(--link); box-shadow: 0 3px 14px color-mix(in srgb, var(--link) 34%, transparent); }
.sc-chip-all:active, .sc-bask-all:active { transform: translateY(0); }
html[data-theme="light"] .sc-chip-all:hover, html[data-theme="light"] .sc-bask-all:hover { color: #fff; }
.sca-ic { font-size: 11px; opacity: .92; }

/* sector chips rail scrolls horizontally — pin "Select all" to the left so it stays in reach */
.sc-chip-all { position: sticky; left: 0; z-index: 3;
  box-shadow: 7px 0 10px -6px color-mix(in srgb, var(--panel) 92%, transparent); }

/* prominent CTA in the focus panel's top-left: open this sector/basket's own page */
.sc-fhead-top { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; }
.sc-fhead-top .cyc-back { margin-bottom: 0; }
.sc-openpage { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; text-decoration: none;
  font-size: 12.5px; font-weight: 750; letter-spacing: .01em; color: #fff; padding: 7px 15px; border-radius: 10px; border: 0;
  background: linear-gradient(180deg, color-mix(in srgb, var(--c, var(--link)) 88%, #fff 12%), var(--c, var(--link)));
  box-shadow: 0 2px 10px color-mix(in srgb, var(--c, var(--link)) 40%, transparent);
  transition: transform .12s var(--ease), box-shadow .18s, filter .18s; }
.sc-openpage:hover { transform: translateY(-1px); filter: brightness(1.06);
  box-shadow: 0 5px 18px color-mix(in srgb, var(--c, var(--link)) 52%, transparent); }
.sc-openpage:active { transform: translateY(0); }
html[data-theme="light"] .sc-openpage { color: #fff; }
.sc-op-ic { font-size: 12px; } .sc-op-ar { font-size: 12px; opacity: .85; }

/* ---- mobile: let the hero controls wrap instead of clipping off the right edge ---- */
@media (max-width: 880px) {
  .sc-page .cyc-hero-hd { flex-direction: column; align-items: stretch; gap: 10px; }
  .sc-page .cyc-hero-tools { justify-content: flex-start; gap: 12px 14px; }
  .sc-page .cyc-zoom { flex-wrap: wrap; }
  .sc-page .sc-chip-all { padding: 6px 12px; }
}
/* hide the rail hint on the narrowest screens; the caret then needs the auto-push the
   hint was carrying so it stays right-aligned against the "Select all" button */
@media (max-width: 560px) {
  .sc-page .sc-bask-hint { display: none; }
  .sc-page .sc-bask-caret { margin-left: auto; }
}

/* ============================================================================
   UX overhaul — mobile control reclaim, guided-chart hint, a11y, mode-aware
   legend. All additive / .sc-page|.scc-page-scoped. (See sector_cycles.js.)
   ========================================================================== */

/* the Log/Linear scale is hidden entirely in Cycle-position mode (scale.hidden in JS) —
   defeat the .sc-scale{display:inline-flex} rule so [hidden] actually hides it */
.sc-scale[hidden] { display: none !important; }

/* the plain-language cycle caption beside the Price/Cycle toggle (mobile aid; the
   desktop legend already says this, so it's hidden ≥881px) */
.sc-mode-cap { font-size: 11px; color: var(--muted); white-space: nowrap; }
@media (min-width: 881px) { .sc-mode-cap { display: none; } }

/* "Chart options" disclosure: desktop shows scale+legend+zoom inline (toggle hidden);
   mobile folds them behind one tap so the chart isn't buried under a 4-row control wall */
.sc-adv-toggle { display: none; }
.sc-advanced, .sc-adv-body { display: inline-flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.cyc-leg-hint { color: var(--ink-link, var(--link)); font-weight: 600; }

/* mode-aware legend band swatches reuse cycle.css .lc; nothing extra needed */

@media (max-width: 880px) {
  /* stack the hero tools so Price/Cycle + caption + "Chart options" read top-to-bottom */
  .sc-page .cyc-hero-tools { flex-direction: column; align-items: stretch; gap: 10px; }
  .sc-page .sc-modes { width: fit-content; }
  .sc-page .sc-advanced { display: block; width: 100%; }
  .sc-page .sc-adv-toggle { display: inline-flex; align-items: center; gap: 7px; min-height: 40px; width: fit-content;
    font-size: 12.5px; font-weight: 700; color: var(--muted); background: var(--panel2);
    border: 1px solid var(--line); border-radius: 10px; padding: 8px 13px; cursor: pointer; }
  .sc-page .sc-adv-toggle::after { content: "▾"; font-size: 11px; transition: transform .2s var(--ease); }
  .sc-page .sc-advanced.open .sc-adv-toggle::after { transform: rotate(180deg); }
  .sc-page .sc-adv-body { display: none; }
  .sc-page .sc-advanced.open .sc-adv-body { display: flex; flex-direction: column; align-items: stretch; gap: 12px; margin-top: 10px; }

  /* 40px minimum touch targets across every chart/phase/zoom/chip control */
  .sc-page .sc-mbtn, .sc-page .sc-sbtn, .sc-page .cyc-zbtn, .sc-page .cyc-gchip,
  .sc-page .sc-bchip, .sc-page .sc-bask-all, .sc-page .sc-chip-all, .sc-page .cyc-gall,
  .sc-page .cyc-chip, .sc-page .mini-chip {
    min-height: 40px; display: inline-flex; align-items: center; }
  .sc-page .sc-modes, .sc-page .sc-scale { padding: 4px; }

  /* phase filter = ONE horizontal-scroll row (was 132px of wrapped chips) */
  .sc-page #sc-groups { flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch;
    scrollbar-width: none; padding-bottom: 6px; }
  .sc-page #sc-groups::-webkit-scrollbar { display: none; }
  .sc-page #sc-groups .cyc-glabel, .sc-page #sc-groups .cyc-gchip { flex: none; }
  .sc-page .cyc-gall { margin-left: 8px; flex: none; }     /* keep "All phases" inline, not auto-pushed */

  /* dim helper labels were barely legible at 10.5px+opacity — restore contrast */
  .sc-page .cyc-zhint { opacity: 1; font-size: 11px; }
}

/* one-shot onboarding pill (top-left over the chart) — distinct from the centered
   empty-state hint; cleared on first interaction by setFocus() */
.sc-hint-tap { inset: auto; top: 10px; left: 10px; right: 10px; bottom: auto; display: block;
  pointer-events: none; text-align: left; font-size: 12px; line-height: 1.45; color: var(--text);
  background: color-mix(in srgb, var(--panel) 90%, transparent); backdrop-filter: blur(6px);
  border: 1px solid color-mix(in srgb, var(--link) 34%, var(--line)); border-radius: 11px;
  padding: 8px 11px; max-width: 360px; box-shadow: 0 6px 20px rgba(0,0,0,.24);
  animation: sc-hint-in .3s var(--ease); z-index: 4; }
@keyframes sc-hint-in { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: none; } }

/* ---- Cycle DNA panel — the front-loaded "history rhymes" / predictive read ---- */
/* padding-left clears the accent border-left so the heading/text never touch the blue rule */
.sc-dna { border:1px solid var(--line); padding-left: 13px; }
.sc-dna .cyc-lbl { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.sc-dna-conf { font-size: 10px; font-weight: 600; letter-spacing: .02em; text-transform: uppercase;
  padding: 1px 7px; border-radius: 999px; border: 1px solid var(--line); color: var(--muted); background: var(--panel2); }
.sc-dna-conf.high { color: var(--ink-up, var(--up)); border-color: color-mix(in srgb, var(--up) 45%, var(--line)); }
.sc-dna-conf.low { color: var(--ink-warn, var(--warn)); border-color: color-mix(in srgb, var(--warn) 45%, var(--line)); }
.sc-dna-sum { font-size: 12.5px; line-height: 1.55; color: var(--text); margin: 6px 0 0; opacity: .96; }
.sc-dna-drv { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.sc-dna-drv span { font-size: 10.5px; color: var(--text); background: color-mix(in srgb, var(--link) 9%, var(--panel2));
  border: 1px solid color-mix(in srgb, var(--link) 24%, var(--line)); border-radius: 999px; padding: 2px 9px; }
.sc-dna-sig { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 14px; margin-top: 11px; }
.sc-dna-col .sc-dna-h { font-size: 10.5px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; margin-bottom: 4px; }
.sc-dna-col.b .sc-dna-h { color: var(--ink-up, var(--up)); } .sc-dna-col.t .sc-dna-h { color: var(--ink-down, var(--down)); }
.sc-dna-col ul { margin: 0; padding-left: 15px; }
.sc-dna-col li { font-size: 11.5px; line-height: 1.5; color: var(--text); opacity: .9; margin-bottom: 2px; }
.sc-dna-rhythm { margin-top: 10px; font-size: 11px; color: var(--muted); }
.sc-dna-analog { margin-top: 9px; font-size: 12px; line-height: 1.5; color: var(--text);
  padding: 8px 11px; background: color-mix(in srgb, var(--link) 7%, var(--panel2));
  border: 1px solid color-mix(in srgb, var(--link) 20%, var(--line)); border-radius: 9px; }
.sc-dna-ana-k { font-weight: 700; color: var(--ink-link, var(--link)); margin-right: 4px; }
@media (max-width: 620px) { .sc-dna-sig { grid-template-columns: 1fr; } }
.sc-dna-body { max-height: 9.5em; overflow: hidden; position: relative; }
.sc-dna-body::after { content: ""; position: absolute; bottom: 0; left: 0; right: 0; height: 2.5em;
  background: linear-gradient(to bottom, transparent, var(--panel)); pointer-events: none; }
.sc-dna-body.open { max-height: none; }
.sc-dna-body.open::after { display: none; }
.sc-dna-more { display: block; font-size: 10.5px; font-weight: 700; color: var(--muted); background: none; border: none;
  cursor: pointer; padding: 3px 0 0; letter-spacing: .02em; text-align: left; }
.sc-dna-more:hover { color: var(--ink-link, var(--link)); }
.sc-dna-more[hidden] { display: none; }

/* visible focus ring for keyboard users across both page chromes */
.sc-page :focus-visible, .scc-page :focus-visible { outline: 2px solid var(--link); outline-offset: 2px; border-radius: 7px; }

/* honor reduced-motion for the hub chrome + the onboarding pill (the chart engine is
   gated in JS; cycle.css already covers .cyc-page) */
@media (prefers-reduced-motion: reduce) {
  .scc-page *, .sc-page .sc-hint-tap { animation: none !important; transition: none !important; }
}


