.fable-chip.tested-accrue { background:color-mix(in srgb,#aaf 20%,transparent); color:#33a; border:1px solid #55c; }
/* A1: DSR provenance chips */
.dsr-prov { font-size:10px; padding:1px 6px; border-radius:6px; margin-left:4px; font-weight:600; vertical-align:middle; }
.dsr-prov.ledger   { background:color-mix(in srgb,var(--up) 15%,transparent); color:var(--ink-up, var(--up)); border:1px solid color-mix(in srgb,var(--up) 50%,var(--line)); }
