td.r, th.r { text-align:right; font-variant-numeric:tabular-nums; }
.pos { color:var(--ink-up, var(--up)); } .neg { color:var(--ink-down, var(--down)); }
.sig { font-weight:600; } .mkt { font-size:11px; color:var(--muted); }
.src { font-size:10.5px; color:var(--muted); }
.extra { font-size:11px; color:var(--muted); margin-top:2px; }
.extra-chips { display:flex; flex-wrap:wrap; gap:4px; margin-top:4px; }
.extra-chip { font-size:10.5px; padding:1px 7px; border-radius:6px; border:1px solid var(--line);
  background:var(--panel2); color:var(--muted); display:inline-flex; gap:4px; }
