.mx-stockdash--hk .hk-v37-an-body.is-enhanced .hk-v37-an-seg :is(button, a)[aria-selected=true],
.mx-stockdash--hk .hk-v37-an-body:not(.is-enhanced):not(:has(.hk-v37-an-lane:target)) .hk-v37-an-seg [data-hk-an-default=true],
