.mx-stockdash--hk .hk-v37-an-body:not(.is-enhanced):has(#anv2-bot:target) .hk-v37-an-seg [href="#anv2-bot"],
.mx-stockdash--hk .hk-v37-an-body:not(.is-enhanced):has(#anv2-red:target) .hk-v37-an-seg [href="#anv2-red"] {
  color: var(--text); border-color: color-mix(in srgb, var(--text) 30%, var(--line)); background: var(--panel);
