  background:linear-gradient(90deg,var(--muted),transparent); opacity:.6; }
.v2-card[data-lane="entry_open"]::before { background:linear-gradient(90deg,var(--up),color-mix(in srgb,var(--up) 30%,transparent)); opacity:1; }
.v2-card[data-lane="setting_up"]::before { background:linear-gradient(90deg,var(--warn),color-mix(in srgb,var(--warn) 30%,transparent)); opacity:1; }
